int H,W;
int N;
int Y[101010],X[101010],A[101010];

ll XX[101010],YY[101010];
vector<pair<int,int>> XL[101010];
vector<pair<int,int>> YL[101010];
vector<pair<int,int>> XE[101010];
vector<pair<int,int>> YE[101010];

ll mix[101010],miy[101010];

template<int um> class UF {
	public:
	vector<int> par,rank;
	UF() {rank=vector<int>(um,0); for(int i=0;i<um;i++) par.push_back(i);}
	int operator[](int x) {return (par[x]==x)?(x):(par[x] = operator[](par[x]));}
	int operator()(int x,int y) {
		if((x=operator[](x))==(y=operator[](y))) return x;
		if(rank[x]>rank[y]) return par[x]=y;
		rank[x]+=rank[x]==rank[y]; return par[y]=x;
	}
};

UF<101010> ufy,ufx;

void dfsx(int x) {
	FORR(e,XE[x]) {
		int tar=e.first;
		ll v=XX[x]+e.second;
		if(XX[tar]==-1LL<<60) {
			XX[tar]=v;
			dfsx(tar);
		}
		else {
			if(XX[tar]!=v) {
				cout<<"No"<<endl;
				exit(0);
			}
		}
	}
}

void dfsy(int y) {
	FORR(e,YE[y]) {
		int tar=e.first;
		ll v=YY[y]+e.second;
		if(YY[tar]==-1LL<<60) {
			YY[tar]=v;
			dfsy(tar);
		}
		else {
			if(YY[tar]!=v) {
				cout<<"No"<<endl;
				exit(0);
			}
		}
	}
}

void solve() {
	int i,j,k,l,r,x,y; string s;

	FOR(i,101000) XX[i]=YY[i]=-1LL<<60;

	cin>>H>>W>>N;
	FOR(i,N) {
		cin>>Y[i]>>X[i]>>A[i];
		Y[i]--;
		X[i]--;
		YL[Y[i]].push_back({X[i],A[i]});
		XL[X[i]].push_back({Y[i],A[i]});
	}
	FOR(y,H) if(YL[y].size()>1) {
		sort(ALL(YL[y]));
		FOR(i,YL[y].size()-1) {
			ufx(YL[y][i].first,YL[y][i+1].first);
			XE[YL[y][i].first].push_back({YL[y][i+1].first,YL[y][i+1].second-YL[y][i].second});
			XE[YL[y][i+1].first].push_back({YL[y][i].first,YL[y][i].second-YL[y][i+1].second});
		}
	}
	FOR(x,W) if(XL[x].size()>1) {
		sort(ALL(XL[x]));
		FOR(i,XL[x].size()-1) {
			ufy(XL[x][i].first,XL[x][i+1].first);
			YE[XL[x][i].first].push_back({XL[x][i+1].first,XL[x][i+1].second-XL[x][i].second});
			YE[XL[x][i+1].first].push_back({XL[x][i].first,XL[x][i].second-XL[x][i+1].second});
		}
	}

	FOR(i,N) {
		if(XX[X[i]]==-1LL<<60 && YY[Y[i]]==-1LL<<60) {
			XX[X[i]]=A[i];
			YY[Y[i]]=0;
			dfsx(XX[i]);
			dfsy(YY[i]);
		}
		if(YY[Y[i]]==-1LL<<60) {
			YY[Y[i]]=A[i]-XX[X[i]];
			dfsy(YY[i]);
		}
		if(XX[X[i]]==-1LL<<60) {
			XX[X[i]]=A[i]-YY[Y[i]];
			dfsx(XX[i]);
		}
	}

	FOR(y,H) miy[y]=1LL<<60;
	FOR(y,H) if(YY[y]!=-1LL<<60) miy[ufy[y]] = min(miy[ufy[y]],YY[y]);
	FOR(x,W) mix[x]=1LL<<60;
	FOR(x,W) if(XX[x]!=-1LL<<60) mix[ufx[x]] = min(mix[ufx[x]],XX[x]);

	FOR(i,N) {
		if(mix[X[i]]+miy[Y[i]]<0) {
			cout<<"No"<<endl;
			return;
		}
	}

	cout<<"Yes"<<endl;



}


