struct edge {
  int p, a;
  edge(int p, int a) : p(p), a(a) {};
};

vector<ll> nodes[2];
multimap<int, edge> edges[2];

const ll toobig = 1LL<<40;
ll mins[2];
bool consistent;

void
dfs(int r, bool i, ll cur) {
  // cout << "dfs" << r << ", " << i << ", " << cur << endl;

  if (nodes[i][r] != -1) {
    consistent &= cur == nodes[i][r];
    return;
  }

  // cout << "uoooo" << endl;
  nodes[i][r] = cur;
  // cout << nodes[i][r] << endl;
  mins[i] = Min(cur, mins[i]);

  auto nexts = edges[i].equal_range(r);

  for (auto it = nexts.first; it != nexts.second; it++) {
    edge e = it->second;

    // cout << "e: " << e.a << " -> " << e.p << endl;

    dfs(e.p, !i, e.a - cur);
  }
}

