// Segment Tree
class SegTree {
public:
    int N;
    int init;
    const int& (*op)(const int&, const int&);
    VI dat;

    SegTree(int n_, int init_, const int& (*op_)(const int&, const int&)) : init(init_), op(op_) {
        N = 1;
        while (N < n_) N *= 2;
        dat = VI(N * 4, init);
    }

    // x_k = a
    void update(int k, int a) {
        k += N - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = op(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    // return: op [a, b)
    int query(int a, int b) { return query(a, b, 0, 0, N); }

    int query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return init;
        if (a <= l && r <= b) return dat[k];
        int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return op(vl, vr);
    }

};
