        --y; --x;
        ps[i] = MP(MP(y, x), a);
    }

    sort(ALL(ps));

    VVPII ys(H);
    rep(i, N) {
        int y = ps[i].fst.fst;
        int x = ps[i].fst.snd;
        int a = ps[i].snd;
        ys[y].EB(x, a);
    }


    bool flg = true;
    priority_queue<PII, VPII, greater<PII>> q; // y, idx
    VI sums(W, INF);

    rep(y, H) {
        if (ys[y].size()) {
            q.push(MP(y, 0));
        }
    }

    while (q.size() && flg) {
        int y = q.top().fst;
        int i = q.top().snd;
        int x = ys[y][i].fst;
        int a = ys[y][i].snd;
        q.pop();

        int j = i + 1;
        if (j >= (int)ys[y].size()) continue;

        int nx = ys[y][j].fst;
        int na = ys[y][j].snd;

        int diff = na - a;

        int sum = sums[x];
        if (sum == INF) sums[x] = sum = 0;

        int nsum = sum + diff;
        if (sums[nx] == INF) sums[nx] = nsum;
        else if (sums[nx] != nsum) {
            flg = false;
            break;
        }

        q.push(MP(y, j));
    }


    SegTree sg(W, INF, min<int>);
    rep(x, W) {
        sg.update(x, sums[x]);
    }

    rep(y, H) {
        if (!ys[y].size()) { continue; }
        int x = ys[y][0].fst;
        int a = ys[y][0].snd;

        int sum1 = sums[x];
        int sum2 = sg.query(x, W);
        int diff = sum2 - sum1;

        if (a + diff < 0) flg = false;
    }


    cout << (flg ? "Yes" : "No") << endl;



    return 0;
}

