typedef vector<vector<pii>> Graph;

Graph graph(MAX_RC);
vector<bool> used(MAX_RC, false);
vi node(MAX_RC, 0);

void dfs(int v, int will) {
    if(used[v]) {
        if(node[v] != will) {
            cout << "No" << endl;
            exit(0);
        }
        return;
    }

    used[v] = true;
    node[v] = will;
    tr(it, graph[v]) {
        dfs(it->first, it->second - node[v]);
    }
}


