void dfs(ll cur, ll val) {
	//cout << cur <<   " " << val << endl;
	if (flag) {
		return;
	}
	col[cur] = val;
	for (auto next_edge : G[cur]) {
		ll next = next_edge.to; ll cost = next_edge.len;
		if (col[next] == INF) {

			dfs(next, val + cost);
		}
		else {
			if (col[next] != col[cur] + cost) {
				flag = 1;
			}
		}
	}
}

