bool DFSUtil(int, vector<bool>, vector<pair<int,int>>&);

int main(){
  int R, C;
  cin >> R >> C;
  int N;
  cin >> N;
  vector<pair<int, int>> g[C + R];

  for(int i = 0; i < N; i++){
    int r, c, a;
    cin >> r >> c >> a;
    g[r].push_back(make_pair( c + C, a));
    g[c + C].push_back(make_pair(r, a));
  }

  vector<bool> visited(R + C, false);
  vector<int> node(R + C, 0);
  int minR, minC = pow(10,9);
  if(!DFSUtil(0, visited, g)){
    cout << "No";
  }
  else{
    cout << "Yes";
  }
}

bool DFSUtil(int v, vector<bool> visited, vector<pair<int,int>> &g){
  visited[v] = true;
  for(int i = 0; i < g[v].size(); i++){
    int w = g[v][i]. first;
    int a = g[v][i].second;
    if(visited[w] && node[v] + node[w] != a){
      return false;
    }
    node[w] = a - node[v];

    if(v < R) minR = minR >node[v] ? node[v] : minR;
    if(v >= R) minC = minC>node[v] ? node[v] : minC;
    if(minR + minC < 0) return false;
    if(!visited[w]){
      if(!DFSUtil(w, visited,g)) return false;
    }
  }
  return true;
}

