	char ch(getchar()); 
	while(!isdigit(ch))
	{
		if(ch=='-')
		{
			flag=-1;
		}
		ch=getchar();
	}
	while(isdigit(ch))
	{
		x=(x<<1)+(x<<3)+(ch^48);
		ch=getchar();
	}
	return flag*x;
}
int fx[MAXN];
int fy[MAXN];
LL wx[MAXN];
LL wy[MAXN];
int findx(int x)
{
	if(fx[x]==x) 
	{
		return x;
	}
	int y=findx(fx[x]); 
	wx[x]+=wx[fx[x]];
	return fx[x]=y;
}
int findy(int x)
{
	if(fy[x]==x)
	{
		return x;
	}
	int y(findy(fy[x]));
	wy[x]+=wy[fy[x]];
	return fy[x]=y;
}
bool unionnx(int x,int y,LL val1,LL val2)
{
	int a(findx(x));
	int b(findx(y));
	if(a==b)
	{
		return wx[x]-wx[y]==val2-val1;//1 x  2 y
	}
	fx[a]=b; 
	wx[a]=val2-val1+wx[y]-wx[x];
	return 1;
}
bool unionny(int x,int y,LL val1,LL val2)
{
	int a(findy(x));
	int b(findy(y));
	if(a==b)
	{
		return wy[x]-wy[y]==val2-val1;//1 x  2 y
	}
	fy[a]=b; 
	wy[a]=val2-val1+wy[y]-wy[x];
	return 1;
}
class Node
{
	public:
		int x;
		int y;
		LL val;
}node[MAXN];
bool cmpx(const Node &a,const Node &b )
{
	return a.x<b.x;
}
bool cmpy(const Node &a,const Node &b)
{
	return a.y<b.y;
}
