    for (int i=1; i<G[y].size(); i++) {
      P &b = G[y][i];
      B[a.first].push_back(P(b.first, b.second-a.second));
    }
  }
  for (int x=0; x<C; x++) T[x] = INF;
  T[0] = 0;
  for (int x=0; x<C; x++) {
