int h, w, n;
const int N = 1e5;
vector<ll> x(N), y(N);
ll a[N];
ll r[N], c[N];
vector<pair<int, ll>> xg[N], yg[N];
int sol() {
  ios::sync_with_stdio(false), cin.tie(0);
  cin >> h >> w >> n;
  for(int i = 0; i < n; i++) {
    cin >> r[i] >> c[i] >> a[i];
    r[i]--; c[i]--;
    yg[r[i]].emplace_back(c[i], a[i]);
    xg[c[i]].emplace_back(r[i], a[i]);
  }
  vector<vector<int>> used(2, vector<int>(N));
  for(int i = 0; i < w; i++) if(!used[1][i]) {
    queue<pair<int, int>> q;
    q.emplace(i, 1);
    used[1][i] = 1;
    ll mi[2] = {(ll) 1e18, (ll) 1e18};
    while(q.size()) {
      int i, xx; tie(i, xx) = q.front(); q.pop();
      vector<ll> &v = xx ? x : y;
      vector<ll> &ov = !xx ? x : y;
      auto* g = xx ? xg : yg;
      mi[xx] = min(mi[xx], v[i]);
      for(auto to : g[i]) if(!used[!xx][to.first]) {
        q.emplace(to.first, !xx);
        ov[to.first] = - v[i] + to.second;
        used[!xx][to.first] = 1;
      }
    }
    if(mi[0] + mi[1] < 0) return 0;
  }
  for(int i = 0; i < n; i++) {
    if(y[r[i]] + x[c[i]] != a[i]) return 0;
  }
  return 1;
}

