int main(void) {
    int H, W, N;
    cin >> H >> W >> N;
    vector<pair<PII, int>> ps(N);
    rep(i, N) {
        int y, x, a;
        cin >> y >> x >> a;
        --y; --x;
        ps[i] = MP(MP(y, x), a);
    }

    sort(ALL(ps));

    VVPII ys(H);
    rep(i, N) {
        int y = ps[i].fst.fst;
        int x = ps[i].fst.snd;
        int a = ps[i].snd;
        ys[y].EB(x, a);
    }


    bool flg = true;
    priority_queue<PII, VPII, greater<PII>> q; // y, idx
    VLL sums(W, INF);

    rep(y, H) {
        if (ys[y].size()) {
            q.push(MP(y, 0));
        }
    }

    while (q.size() && flg) {
        int y = q.top().fst;
        int i = q.top().snd;
        int x = ys[y][i].fst;
        int a = ys[y][i].snd;
        q.pop();

        int j = i + 1;
        if (j >= (int)ys[y].size()) continue;

        int nx = ys[y][j].fst;
        int na = ys[y][j].snd;

        LL diff = na - a;

        LL sum = sums[x];
        if (sum == INF) sums[x] = sum = 0;

        LL nsum = sum + diff;
        if (sums[nx] == INF) sums[nx] = nsum;
        else if (sums[nx] != nsum) {
            flg = false;
            break;
        }

        q.push(MP(y, j));
    }


    SegTree sg(W, INFL);
    rep(x, W) {
        sg.update(x, sums[x]);
    }

    rep(y, H) {
        if (!ys[y].size()) { continue; }
        int x = ys[y][0].fst;
        int a = ys[y][0].snd;

        LL sum1 = sums[x];
        LL sum2 = sg.query(x, W);
        LL diff = sum2 - sum1;

        if (a + diff < 0) flg = false;
    }


    cout << (flg ? "Yes" : "No") << endl;



    return 0;
}

