	std::vector<int> row(R, INFINT), col(C, INFINT);
	std::map<int, std::map<int, int>> a;
	std::map<int, std::vector<int>> r_c, c_r;
	int startR;
	REP(i, N) {
		VAR(int, r, c, _a);
		a[--r][--c] = _a;
		r_c[r].emplace_back(c);
		c_r[c].emplace_back(r);
		if (i == 0) startR = r;
	}

	std::vector<bool> checkedR(R), checkedC(C);
	std::function<bool(int, int)> dfs = [&](int r, int c) {
