		if (c == -1) {
			for (const auto& _c : r_c[r]) {
				if (checkedC[_c]) {
					if (row[r] + col[_c] != a[r][_c]) flag &= false;
					else flag &= true;
				}
				else {
					checkedC[_c] = true;
					col[_c] = a[r][_c] - row[r];
					flag &= dfs(-1, _c);
				}
			}
		}
