  cin >> n;
  rep(i,n){
    cin >> x >> y >> a;
    x--;y--;
    p[0][x].pb(make_pair(y,a));
    p[1][y].pb(make_pair(x,a));
  }

  rep(i, r)u[0][i] = INF;
  rep(i, c)u[1][i] = INF;

  bool ret = true;

  rep(i,r){
    if(u[0][i] == INF){
      u[0][i] = 0;
      m[0] = 0;m[1] = INF;
      ret &= dfs(0, i, 0);
      if(m[0] + m[1] < 0)ret = false;
    }
  }

  if(ret) cout << "Yes" << endl;
  else cout << "No" << endl;

  return 0;

}

