typedef tuple<int,int,int> state;

int dx[] = {1,-1,1,-1};
int dy[] = {1,1,-1,-1};
int dx2[] = {1,0};
int dy2[] = {0,1};
int r, c, n, rr[N], cc[N], a;
map<pair<int,int>,ll> v;
queue<state> q;
void psh(int y, int x) {
	int a = v[{y,x}];
	fo(i,0,4) {
		int yy = y + dy[i], xx = x + dx[i];
		if (v.find({yy,xx}) == v.end()) continue;
		int c = v[{yy,xx}];
		int b = -1, d = -1;
		if (v.find({yy,x}) != v.end()) {
			b = v[{yy,x}];
		}
		if (v.find({y,xx}) != v.end()) {
			d = v[{y,xx}];
		}
		if (b != -1 && d != -1) {
			if (a + c != b + d) {
				puts("No"); exit(0);
			}
		} else if (b != -1) {
			d = a + c - b;
			if (d < 0) {
				puts("No"); exit(0);
			}
			q.push(state(y,xx,d));
		} else if (d != -1) {
			b = a + c - d;
			if (b < 0) {
				puts("No"); exit(0);
			}
			q.push(state(yy,x,b));
		}
	}
}
int rp[N], cp[N];
int main() {
