	fo(i,0,n) {
		scanf("%d %d %d", rr+i, cc+i, &a);
		v[{rr[i],cc[i]}] = a;
	}
	fo(i,0,n) psh(rr[i], cc[i]);
	while (!q.empty()) {
		int y, x, vv;
		tie(y, x, vv) = q.front(); q.pop();
		if (v.find({y,x}) != v.end() && v[{y,x}] != vv) {
			puts("No"); exit(0);
		}
		v[{y,x}] = vv;
		psh(y, x);
	}
	for (auto vv : v) {
		int y = vv.first.first, x = vv.first.second;
		ll aa = vv.second;
		if (v.find({y+1,x}) != v.end()) {
			ll aa2 = v[{y+1,x}];
			ll dif = (aa+aa2)%2;
			if (rp[y] && rp[y] != dif+1) {
				puts("No"); exit(0);
			}
			rp[y] = dif+1;
		}
		if (v.find({y,x+1}) != v.end()) {
			ll aa2 = v[{y,x+1}];
			ll dif = (aa+aa2)%2;
			if (cp[x] && cp[x] != dif+1) {
				puts("No"); exit(0);
			}
			cp[x] = dif+1;
		}
	}
	puts("Yes");

	return 0;
}

