struct Edge {
    ll to, val;
    Edge (ll _t, ll _v) : to(_t), val(_v) {}
};

ll H,W,N;
vector<Edge> edge[100001 * 2];
ll w[100001 * 2];

// 頂点i の重みw[i] を求めていく
// 矛盾があればfalse
bool dfs(ll i){
    //if(i<H){
    //    cout<<"y="<<i;
    //} else {
    //    cout<<"x="<<(H-i);
    //}
    //cout<<", w="<<w[i]<<endl;
    for(auto e: edge[i]){
        if(w[e.to]!=LLONG_MAX){ // 頂点e.toが決定済み
            if(w[i]+w[e.to]!=e.val)
                return false;
        } else {           // 頂点e.toが未決定
            w[e.to]  = e.val - w[i]; // 仮決定
            if(!dfs(e.to)){
                return false;
            }
        }
    }
    return true;
}

