    rep(i,0,100001*2)
        w[i]=LLONG_MAX;

    rep(i,0,H+W){
        if (edge[i].size() == 0 || w[i] != LLONG_MAX) // すでに決定済み，あるいは決定不要
            continue;
        w[i] = 0; // 仮決定
        if(!dfs(i)){
