void normalize(pair<int, int> p)
{
	if (p.first == -1)
	{
		R = min(R, 0ll+p.second);
	}
	else
	{
		L = max(L, 0ll-p.second);
	}
}

pair<int, int> sub(int val, pair<int, int> a)
{
	pair<int, int> p = make_pair(0, val);
	a.first = p.first - a.first;
	a.second = p.second - a.second;
	return a;
}

void dfs(int v)
{
	//cout << s_r[r[v]].first << " " << s_r[r[v]].second << " " << v << " " << r[v] <<" "<<L<<" "<<R<< endl;
	//cout << s_c[c[v]].first << " " << s_c[c[v]].second << endl;

	if (L > R)
		return;

	used[v] = 1;
	normalize(s_r[r[v]]);
	normalize(s_c[c[v]]);

	set<int>::iterator it;
	while (true)
	{
