			{
				c_val[c[id]] = val[id] - r_val[r[id]];
				s_c[c[id]] = sub(val[id], s_r[r[id]]);
				dfs(id);
			}
			continue;
		}
		if (by_col[c[v]].size())
		{
			it = by_col[c[v]].begin();
			int id = (*it);
			by_col[c[v]].erase(it);
