    lint h, w;
    cin >> h >> w;
    lint n;
    cin >> n;
    vector<lint> r(n), c(n), a(n);
    vector<lint> nodes(h + w, inf);
    vector<vector<pair<int, lint>>> edges(h + w);
    for (int i = 0; i < n; ++i) {
        cin >> r[i] >> c[i] >> a[i];
        r[i]--, c[i]--;
        edges[r[i]].emplace_back(h + c[i], a[i]);
        edges[h + c[i]].emplace_back(r[i], a[i]);
    }
    for (int i = h; i < h + w; ++i) {
        if (nodes[i] != inf || edges[i].size() == 0)
            continue;
        nodes[i]   = 0;
        lint minir = inf, minic = inf;
        function<void(int, int)> dfs = [&](int c, int p) {
            for (auto &v : edges[c]) {
                if (v.first == p)
                    continue;
                if (nodes[v.first] != inf) {
                    continue;
                }
                nodes[v.first] = v.second - nodes[c];
                dfs(v.first, c);
            }
            if (c < h)
                minir = min(minir, nodes[c]);
            else
                minic = min(minic, nodes[c]);
        };
        dfs(i, -1);
        if (minir + minic < 0) {
            cout << "No"
                 << "\n";
            return 0;
        }
    }
    for (int i = 0; i < n; ++i) {
        if (nodes[r[i]] + nodes[h + c[i]] != a[i]) {
            cout << "No"
                 << "\n";
            return 0;
        }
    }
    cout << "Yes"
         << "\n";
    return 0;
}

