{
    for(int i = 1;i <= n;++i)
    {
        int r = saver[i];
        int c = savec[i];
        int w = savew[i];
        if(!M.count(Node(r,c)))
            M[Node(r,c)] = w;
        else
        {
            if(w != M[Node(r,c)]) return false;
        }
        if(!gao(r,c)) return false;

    }
    return true;
}

