const long long INF = 1e18;

int r, c;

vector<vector<pair<int, int>>> g;
vector<bool> used;

vector<long long> rowsMin;
vector<long long> colsMin;
vector<long long> value;
int cmpCount;

bool Dfs(int v, long long curValue) {
    value[v] = curValue;
    used[v] = true;

    if (v < r) {
        rowsMin[cmpCount] = min(rowsMin[cmpCount], curValue);
    } else {
        colsMin[cmpCount] = min(colsMin[cmpCount], curValue);
    }

    for (const pair<int, int>& p : g[v]) {
        if (!used[p.first]) {
            if (!Dfs(p.first, p.second - curValue)) {
                return false;
            }
        } else {
            if (p.second - curValue != value[p.first]) {
                return false;
            }
        }
    }

    return true;
}

