		int ptr = -1;
		for (int j = 0; j < py[i].size(); j++) {
			if (vx[py[i][j].first] != -INF) {
				ptr = j; break;
			}
		}
		int pmin = INF;
		for (int j = 0; j < py[i].size(); j++) pmin = min(pmin, py[i][j].second);
