int field[100000][100000];
bool filled[100000][100000];

const int dx[] = {1, 1, -1, -1};
const int dy[] = {1, -1, 1, -1};

bool isIllegal(int i) {
    int ri = r[i];
    int ci = c[i];
    int ai = a[i];

    for (int j = 0; j < 4; j++) {
        int y = ri + dy[j];
        int x = ci + dx[j];
        if (x < 0 || C <= x || y < 0 || R <= y) continue;

        int cnt = 1 + filled[ri][x] + filled[y][ci] + filled[y][x];
        if (cnt <= 2) continue;
        if (cnt == 4) {
            if (ai + field[y][x] != field[ri][x] + field[y][ci]) {
                return true;
            }
        } else if (!filled[ri][x]) {
            int temp = ai + field[y][x] - field[y][ci];
            if (temp < 0) return true;
            field[ri][x] = temp;
            filled[ri][x] = true;
        } else if (!filled[y][ci]) {
            int temp = ai + field[y][x] - field[ri][x];
            if (temp < 0) return true;
            field[y][ci] = temp;
            filled[y][ci] = true;
        } else if (!filled[y][x]) {
            int temp = field[ri][x] + field[y][ci] - ai;
            if (temp < 0) return true;
            field[y][x] = temp;
            filled[y][x] = true;
        }
    }
    return false;
}

