struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

struct edge{
    int to, cost;
};

int R, C, N;
map<int, int> mp[200000];
int dist[200000];
int min_d[200000];
int root_min_d[200000];
vector<edge> G[200000];

bool used[200000];
bool ok = true;
const int INF = 1e9;

void dfs(int v, int d){
    used[v] = true;
    dist[v] = d;
    for(edge e : G[v]){
        int to = e.to, cost = e.cost;
        if(used[to]){
            if(dist[to] != d+cost) ok = false;
        }else{
            dfs(to, d+cost);
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << setprecision(10) << fixed;
    cin >> R >> C >> N;
    for(int i = 0; i < N; i++){
        int r, c, a;
        cin >> r >> c >> a;
        r--; c--;
        mp[r][c] = a;
    }
    UnionFind uf(C);
    for(int i = 0; i < R; i++){
        int prev_c, prev_a;
        for(auto it = mp[i].begin(); it != mp[i].end(); it++){
            int c = it->first, a = it->second;
            if(it != mp[i].begin()){
                G[prev_c].push_back((edge){c, a-prev_a});
                G[c].push_back((edge){prev_c, prev_a-a});
                uf.unionSet(c, prev_c);
            }
            prev_c = c, prev_a = a;
        }
    }
    for(int i = 0; i < C; i++){
        if(!used[i]){
            dfs(i, 0);
            if(!ok){
                cout << "No" << endl;
                return 0;
            }
        }
    }
    for(int i = 0; i < C; i++) root_min_d[i] = INF;
    for(int i = 0; i < C; i++){
        int r = uf.root(i);
        root_min_d[r] = min(root_min_d[r], dist[i]);
    }
    for(int i = 0; i < R; i++){
        if(mp[i].size() == 0) continue;
        auto it = mp[i].begin();
        int c = it->first;
        int a = it->second;
        int r = uf.root(c);
        // cout << i << ' ' << dist[c] << ' ' << c << ' ' << a << ' ' << root_min_d[r] << ' ' << a-dist[c]+root_min_d[r] << endl;
        if(a-dist[c]+root_min_d[r] < 0){
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
}

