using namespace std;
using ll = long long;
template <class T> using vec = vector<T>;
template <class T> using vvec = vector<vec<T>>;

template<typename Monoid,typename F>
class SegmentTree{
private:
    int sz;
    vector<Monoid> seg;
    const F op;
    const Monoid e;
public:
    SegmentTree(int n,const F op,const Monoid &e):op(op),e(e){
        sz = 1;
        while(sz<=n) sz <<= 1;
        seg.assign(2*sz,e);
    }
    void set(int k, const Monoid &x){
        seg[k+sz] = x;
    }
    void build(){
        for(int i=sz-1;i>0;i--){
            seg[i] = op(seg[2*i],seg[2*i+1]);
        }
    }
    void update(int k,const Monoid &x){
        k += sz;
        seg[k] = x;
        while(k>>=1){
            seg[k] = op(seg[2*k],seg[2*k+1]);
        }
    }
    Monoid query(int l,int r){
        Monoid L = e,R = e;
        for(l+=sz,r+=sz;l<r;l>>=1,r>>=1){
            if(l&1) L = op(L,seg[l++]);
            if(r&1) R = op(seg[--r],R);
        }
        return op(L,R);
    }
    Monoid operator[](const int &k)const{
        return seg[k+sz];
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int R,C,N;
    cin >> R >> C >> N;
    vec<map<int,int>> A(R);
    for(int i=0;i<N;i++){
        int r,c,a;
        cin >> r >> c >> a;
        r--; c--;
        A[r][c] = a;
    }
    bool ok = true;
    ll inf = 1e18;
    vec<ll> row(R,inf),col(C,inf);
    for(int i=0;i<R;i++){
        for(auto& [j,val]:A[i]){
            if(i-1>=0 && A[i-1].count(j)){
                if(row[i-1]==inf) row[i-1] = val-A[i-1][j];
                else if(row[i-1]!=val-A[i-1][j]) ok = false;
            }
            if(i+1<R && A[i+1].count(j)){
                if(row[i]==inf) row[i] = A[i+1][j]-val;
                else if(row[i]!=A[i+1][j]-val) ok = false;
            }
            if(j+1<C && A[i].count(j+1)){
                if(col[j]==inf) col[j] = A[i][j+1]-val;
                else if(col[j]!=A[i][j+1]-val) ok = false;
            }
            if(j-1>=0 && A[i].count(j-1)){
                if(col[j-1]==inf) col[j-1] = val-A[i][j-1];
                else if(col[j-1]!=val-A[i][j-1]) ok = false;
            }
        }
    }
    auto op = [](ll a,ll b){return min(a,b);};
    SegmentTree segrow(R,op,inf),segcol(C,op,inf);
    set<int> rinf,cinf;
    vec<ll> rowS(R+1),colS(C+1);
    for(int i=0;i<R-1;i++){
        if(row[i]!=inf){
            rowS[i+1] = rowS[i]+row[i];
            segrow.set(i,rowS[i+1]);
        }else rinf.insert(i);
    }
    for(int i=0;i<C-1;i++){
        if(col[i]!=inf){
            colS[i+1] = colS[i]+col[i];
            segcol.set(i,colS[i+1]);
        }else cinf.insert(i);
    }
    rinf.insert(-1);
    cinf.insert(-1);
    rinf.insert(R-1);
    cinf.insert(C-1);
    segrow.build();
    segcol.build();
    map<pair<int,int>,ll> val;
    for(int i=0;i<R;i++){
        for(auto& [j,x]:A[i]){
            auto itr = rinf.lower_bound(i);
            if(*itr!=i) itr--;
            auto itc = cinf.lower_bound(j);
            if(*itc!=j) itc--;
            int r = *itr+(*itr!=i),c = *itc+(*itc!=j);
            ll v = x-rowS[i]-colS[j];
            if(!val.count({r,c})){
                val[{r,c}] = v;
                ok &= v>=0;
            }else if(val[{r,c}]!=v){
                ok = false;
            }
        }
    }

    for(auto& [p,v]:val){
        int i = p.first,j = p.second;
//        cerr << i << " " << j << " " << v << "\n";
        auto itr = rinf.upper_bound(i);
        auto itc = cinf.upper_bound(j);
        int r = *itr,c = *itc;
        ll rmi = segrow.query(i,r),cmi = segcol.query(j,c);
        ok &= v+rmi+cmi>=0;
    }

    cout << (ok? "Yes\n":"No\n");
}

