template<class T> struct UnionFindDiff {
    int n;
    vector<int> U;
    vector<T> D; // P[U[x]] - P[x]
    UnionFindDiff() {}
    UnionFindDiff(int n_): n(n_), U(n, -1), D(n, T(0)) {}
    int root(int x) {
	if (U[x] < 0) return x;
	int r = root(U[x]);
	if (U[x] != r) {
	    D[x] = D[U[x]] + D[x];
	    U[x] = r;
	}
	return r;
    }
    int link(int x, int y, T diff /* = P[x] - P[y] */) {
	int p, q;
	p = root(x); q = root(y);
	if (p == q) return p;
	if (U[q] < U[p]) { swap(p, q); swap(x, y); diff = -diff; }
	D[q] = D[x] - D[y] + diff;
	U[p] += U[q];
	n--;
	return U[q] = p;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return -U[root(x)]; }
    int count() { return n; }
    T diff(int x, int y) { // return P[x] - P[y];
	root(x); root(y);
	// assert(root(x) == root(y));
	return D[y] - D[x];
    }
};
int N, R, C;
VI B[200011];
const LL INF = 1LL<<60;

void MAIN() {
    scanf("%d%d%d", &R, &C, &N);
    UnionFindDiff<LL> U(R+C);

    bool yes = true;
    REP (i, N) {
	int r, c, a;
	scanf("%d%d%d", &r, &c, &a);
	r--; c--;
	c += R;
	if (U.same(r, c)) {
	    LL d = U.diff(r, c);
	    if (d != a) yes = false;
	} else {
	    U.link(r, c, a);
	}
    }

    if (yes) {
	REP (i, R+C) if (U.size(i) > 1) B[U.root(i)].push_back(i);
	REP (i, R+C) if (!B[i].empty()) {
	    LL rmi = INF, cma = -INF;
	    EACH (e, B[i]) {
		if (*e < R) {
		    amin(rmi, U.diff(*e, i));
		} else {
		    amax(cma, U.diff(*e, i));
		}
	    }

	    if (rmi - cma < 0) yes = false;
	}
    }
    puts(yes? "Yes": "No");
}

