int getp(int v) {
  if (p[v] == v) return v;
  p[v] = getp(p[v]);
  d[v] += d[p[v]];
  return p[v];
}

bool join(int a, int b, ll dif) {
  int pa = getp(a);
  int pb = getp(b);
  dif += d[b] - d[a];
  if (pa == pb) {
    if (dif) return false;
  } else {
    if (rand()) {
      swap(pa, pb);
      dif *= -1;
    }
    p[pa] = pb;
    d[pa] = dif;
  }
  return true;
}

bool f(const vi & x, const vi & y, const vi & a) {
  vector<vii> v(100000);
  for (int i = 0; i < x.size(); ++i) {
    v[x[i]].push_back(pii(y[i], a[i]));
  }
  d.assign(d.size(), 0);
  for (int i = 0; i < p.size(); ++i) p[i] = i;
  for (int i = 0; i < v.size(); ++i) {
    for (int j = 0; j + 1 < v[i].size(); ++j) {
      if (!join(v[i][j].first, v[i][j+1].first, v[i][j+1].second-v[i][j].second)) return false;
    }
  }
  vl mid(d.size(), 0);
  for (int i = 0; i < d.size(); ++i) {
    int pi = getp(i);
    mid[pi] = min(mid[pi], -d[i]);
  }
  for (int i = 0; i < x.size(); ++i) {
    int pi = getp(y[i]);
    if (a[i] + d[y[i]] + mid[pi] < 0) return false;
  }
  return true;
}

