using namespace std;

const string YES = "Yes";
const string NO  = "No";


struct Data {
  int x,y;
  bool operator < ( const Data& data ) const {
    if( x != data.x ) return x < data.x;
    return y < data.y;
  }
  bool operator == (const Data& data) const {
    return x == data.x && y == data.y;
  }
};

int H,W,N;

int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

inline bool isValid(int x,int y) { return 0 <= x && x < W && 0 <= y && y < H; }

bool check(map<Data,int> &mp,int x,int y,int a) {
  rep(i,4) {
    int x2 = x + dx[i] * 2 , y2 = y + dy[i] * 2;
    if( !isValid(x2,y2) ) continue;
    int x3 = x + dx[(i+1)%4] * 2, y3 = y + dy[(i+1)%4] * 2;
    if( !isValid(x3,y3) ) continue;
    if( !mp.count((Data){x2,y2}) ) continue;
    if( !mp.count((Data){x3,y3}) ) continue;
    int x4 = x + dx[i] * 2 + dx[(i+1)%4] * 2;
    int y4 = y + dy[i] * 2 + dy[(i+1)%4] * 2;
    if( mp.count((Data){x4,y4}) ) {
      int a2 = mp[(Data){x4,y4}];
      if( ( a + a2 ) != ( mp[(Data){x2,y2}] + mp[(Data){x3,y3}] ) ) return false;
    }
  }
  return true;
}

typedef pair<Data,int> di;

int main(){
  scanf(" %d %d",&H,&W);
  scanf(" %d",&N);
  map<Data,int> mp;
  rep(i,N) {
    int x,y,a;
    scanf(" %d %d %d",&y,&x,&a);
    --x, --y;
    mp[(Data){x,y}] = a;
  }
  bool update = true;
  int cnt = 0;
  map<Data,int> vec = mp;

  while( update ) {
    ++cnt;
if(cnt>100)break;
    update = false;
    map<Data,int> next;
    for(map<Data,int>::iterator it = vec.begin();it!=vec.end();++it) {
      int x = (it->first).x;
      int y = (it->first).y;
      int a = it->second;
      if( !check(vec,x,y,a) ) {
	cout << NO << endl;
	return 0;
      }
      //cout << x << "," << y << " = " << a <<endl;
      rep(i,4) {
	int x2 = x + dx[i], y2 = y + dy[i];
	if( !isValid(x2,y2) ) continue;
	int x3 = x + dx[(i+1)%4], y3 = y + dy[(i+1)%4];
	if( !isValid(x3,y3) ) continue;
	if( !mp.count((Data){x2,y2}) ) continue;
	if( !mp.count((Data){x3,y3}) ) continue;
	int x4 = x + dx[i] + dx[(i+1)%4];
	int y4 = y + dy[i] + dy[(i+1)%4];
	if( mp.count((Data){x4,y4}) ) {
	  int v1 = a + vec[(Data){x4,y4}];
	  int v2 = mp[(Data){x2,y2}] + mp[(Data){x3,y3}];
	  if( v1 != v2 ) {
	    cout << NO << endl;
	    return 0;
	  }
	} else {
	  int v1 = a;
	  int v2 = mp[(Data){x2,y2}] + mp[(Data){x3,y3}];
	  if( v2 - v1 < 0 ) {
	    cout << NO << endl;
	    return 0;
	  }
	  next[(Data){x4,y4}] = v2 - v1;
	  update = true;
	}
      }
      if( update ) break;
    }
    vec = next;
    for(map<Data,int>::iterator it = next.begin();it!=next.end();++it) {
      int x = (it->first).x;
      int y = (it->first).y;
      int a = it->second;
      mp[(Data){x,y}] = a;
    }

  }
  cout << YES << endl;
  return 0;
}

