bool judge(const int a, const int b, const int c, const int d) {

	if (a >= 0 && b >= 0 && c >= 0 && d >= 0) {
		if (a + d != b + c) {
			return false;
		}
	}

	if (b == -1) {
		if (a + c < d) {
			return false;
		}
	}

	if (c == -1) {
		if (a + d < c) {
			return false;
		}
	}

	if (d == -1) {
		if (b + c < a) {
			return false;
		}
	}

	return true;
}


int main() {

	int R, C, N;
	scanf("%d %d", &R, &C);
	scanf("%d", &N);

	map<int, map<int, int>> row_based_a;

	for (int i = 1; i <= N; i++) {
		int r, c, a;
		scanf("%d %d %d", &r, &c, &a);

		row_based_a[r-1][c-1] = a;
	}


	bool result_flag = true;

	for (int r = 0; r < R; r++) {

		if (!result_flag) {
			break;
		}

		for (int c = 0; c < C; c++) {

			if (!result_flag) {
				break;
			}

			auto itr_r = row_based_a.find(r);
			if (itr_r != row_based_a.end()) {
				auto itr_c = itr_r->second.find(c);
				if (itr_c != itr_r->second.end()) {

					// (r, c)に数字が書き込まれている場合
					const int number_a = itr_c->second;

					// あと2つ以上数字があれば判定できる
					int left_to_judge = 2;
					int number_b = -1, number_c = -1, number_d = -1;
					int d_r = -1, d_c = -1;

					for (int r_c = r+1; r_c < R; r_c++) {
						for (int c_c = c+1; c_c < C; c_c++) {

							if (r_c == r && c_c == c) {
								continue;
							}

							auto itr_b = row_based_a.find(r);
							if (itr_b != row_based_a.end()) {
								auto itr_b_c = itr_b->second.find(c_c);
								if (itr_b_c != itr_b->second.end()) {
									number_b = itr_b_c->second;
									left_to_judge--;
								}
							}

							auto itr_c = row_based_a.find(r_c);
							if (itr_c != row_based_a.end()) {
								auto itr_c_r = itr_c->second.find(c);
								if (itr_c_r != itr_c->second.end()) {
									number_c = itr_c_r->second;
									left_to_judge--;
								}
							}

							auto itr_d_r = row_based_a.find(r_c);
							if (itr_d_r != row_based_a.end()) {
								auto itr_d_c = itr_d_r->second.find(c_c);
								if (itr_d_c != itr_d_r->second.end()) {
									number_d = itr_d_c->second;
									left_to_judge--;
								}
							}

							if (left_to_judge <= 0) {
								if (!judge(number_a, number_b, number_c, number_d)) {
									result_flag = false;
									break;
								}

							}
							else {
								continue;
							}
						}
					}

				}
			}

		}
	}


	cout << (result_flag ? "Yes" : "No") << endl;

	return 0;
}

