}

void dfsr(int i) {
	low = max(low, -xr[i]);
	for(int j : er[i]) {
		int c = ::c[j], a = ::a[j];
		up = min(up, a - xr[i]);
		if(!vc[c]) {
			vc[c] = true;
			yc[c] = a - xr[i];
			dfsc(c);
		} else {
			ok &= (yc[c] + xr[i] == a);
		}
	}
}

void dfsc(int j) {
	up = min(up, yc[j]);
	for(int i : ec[j]) {
		int r = ::r[i], a = ::a[i];
		low = max(low, yc[j] - a);
