	else{
		int v = fb[i];
		fb[i] = finda(v);
		db[i] = db[i] + db[v];
		return fb[i];
	}
}
int mergea(int i, int j, long long k){
	int fi = finda(i), fj = finda(j);
	if(fi != fj){
		fa[fi] = fj;
		da[fi] = k + da[j] - da[i];
	}
	else{
		if(da[i] - db[j] != k)
			return -1;
	}
	return fj;
}
int mergeb(int i, int j,long long k){
	int fi = findb(i), fj = findb(j);
