using namespace std;

const int maxn = 1e6+1000;
typedef long long LL;
struct Node
{
    int v;
    LL w;
    Node(int v = 0,LL w = 0):v(v),w(w) {}
};


vector<Node> G[maxn];


int R,C;
int n;


LL A[maxn];
bool vis[maxn];



const LL INF = 0x3f3f3f3f3f3f3f3f;

int seq[maxn];
int cur;

bool dfs(int u)
{
    seq[cur++] = u;
    for(int i = 0;i < G[u].size();++i)
    {
        int v = G[u][i].v;
        LL w = G[u][i].w;

        if(!vis[v])
        {
            vis[v] = 1;
            A[v] = w-A[u];
            if(!dfs(v)) return false;
        }
        else
        {
            if(A[v] + A[u] != w) return false;

        }
    }
    return true;

}


bool bfs(int s)
{
    int b = 0, e = 1;
    seq[0] = s;
    vis[s] = true;
    A[s] = 0;
    while (b < e) {
      for (int j = 0; j < (int) G[seq[b]].size(); j++) {
        int u = G[seq[b]][j].v;
        int w = G[seq[b]][j].w;
        if (vis[u]) {
          if (A[seq[b]] + A[u] != w) {
            return false;
            }
          continue;
        }
        seq[e] = u;
        A[u] = w - A[seq[b]];
        vis[u] = true;
        e++;
      }
      b++;
    }
    cur = e;

    return true;
}

bool judge()
{

    memset(vis,0,sizeof(vis));
    for(int i = 1;i <= R+C;++i)
        if(!vis[i])
        {
            vis[i] = 1;
            A[i] = 0;

            cur = 0;
            if(!bfs(i)) return false;


            LL Minr = INF;
            LL Minc = INF;

            for(int j = 0;j < cur;++j)
            {
                int t = seq[i];
                if(t <= R)
                    Minr = min(Minr,A[t]);
                else
                    Minc = min(Minc,A[t]);

            }
            if(Minr + Minc < 0) return false;

        }
    return true;
}

