    P2 v_pre = v[0];
    for(int i = 1; i < N; i++){
        if(v_pre.first.first != v[i].first.first){
            v_pre = v[i];
        }else{
            bool flag = unite(v_pre.first.second, v[i].first.second, v[i].second - v_pre.second);
            if(!flag){
                cout << "No" << endl;
                return 0;
            }
        }
    }
    long long int OFF = 101000;
    for(int i = 0; i < N; i++){
        swap(v[i].first.first, v[i].first.second);
    }
    sort(v.begin(), v.end());
    v_pre = v[0];
    for(int i = 1; i < N; i++){
        if(v_pre.first.first != v[i].first.first){
            v_pre = v[i];
        }else{
            bool flag = unite(v_pre.first.second + OFF, v[i].first.second + OFF, v[i].second - v_pre.second);
            if(!flag){
                cout << "No" << endl;
                return 0;
            }
        }
    }
    for(int i = 0; i < 210000; i++){
        min_cost[i] = INF;
    }
    for(int i = 0; i < 210000; i++){
        P p = find(i);
        min_cost[p.first] = min(min_cost[p.first], -p.second);
    }
    for(int i = 0; i < N; i++){
        swap(v[i].first.first, v[i].first.second);
        int r = v[i].first.first + OFF, c = v[i].first.second;
        P rp = find(r), cp = find(c);

        if(v[i].second + rp.second + min_cost[rp.first] < 0){
