const int MAXN = 100005;

int R, C, n, cnt;
int x[MAXN], y[MAXN], cost[MAXN], bio[MAXN], val[MAXN], mx[MAXN], mn[MAXN];
vector <pi> r[MAXN], v[MAXN];

void dfs (int x, int curr) {
    if (bio[x]) return;
    bio[x] = cnt;
    val[x] = curr;
    mn[cnt] = min(mn[cnt], val[x]);
    for (auto par : v[x]) {
        int sus = par.first, dif = par.second;
        dfs(sus, curr + dif);
    }
}

bool check () {
    for (int i = 1; i <= C; i++) {
        for (auto par : v[i]) {
            int sus = par.first, dif = par.second;
            if (val[sus] - val[i] != dif) return 0;
        }
    }
    for (int i = 1; i <= cnt; i++) {
        if (mx[i] > mn[i]) return 0;
    }
    return 1;
}

