					int rx = lx + 1, ry = ly + 1;
					if (lx < 1 || rx > n || ly < 1 || ly > m) continue;

					vector<pair<int, int> > vct;
					for (int ddi = 0; ddi <= 1; ddi++) {
						for (int ddj = 0; ddj <= 1; ddj++) {
							vct.push_back(make_pair(lx + ddi, ly + ddj));
						}
					}

					vector<ll> a(4);
					for (int i = 0; i < 4; i++) {
						a[i] = mp.count(vct[i]) ? mp[vct[i]] : -1;
					}

					int cnt = 0;
					for (int i = 0; i < 4; i++) cnt += a[i] != -1;

					if (cnt == 4) {
						ok &= a[0] + a[3] == a[1] + a[2];
					}
					else if (cnt == 3) {
						for (int i = 0; i < 4; i++) {
							if (a[i] == -1) {
								ll nw =  a[i ^ 2] + a[i ^ 1] - a[i ^ 3];
								ok &= nw >= 0;
								mp[vct[i]] = nw;
								q.push(vct[i]);
							}
						}
					}
				}
			}
		};
		for (int i = 0; i < k; i++) {
			mp[a[i].first] = a[i].second;
			q.push(a[i].first);
		}
		while (!q.empty()) {
			upd(q.front().first, q.front().second);
			q.pop();
		}

		string ans = ok ? "Yes" : "No";
		cout << ans << endl;
	}

	return 0;
}

