using ll = long long;
using vi = vector<ll>;
using pii = pair<ll, ll>;

vector<bool> visited;
vi diff;
vector<vector<pii>> col;

bool dfs(int i, ll v)
{
    visited[i] = true;
    diff[i] = v;

    bool ret = true;
    for(pii& p : col[i]){
        ll tmp = v + p.second;
        if(visited[p.first]){
            ret &= tmp == diff[p.first];
        }
        else{
            dfs(p.first, tmp);
        }
    }

    return ret;
}

int main()
{
    int R, C, n;
    cin >> R >> C >> n;

    vector<vector<pii>> a(R);
    rep(i, n){
        int r, c, v;
        cin >> r >> c >> v;
        --r;
        --c;
        a[r].emplace_back(c, v);
    }

    col.resize(C);
    rep(i, R){
        rep(j, a[i].size() - 1){
            col[a[i][j].first].emplace_back(a[i][j+1].first, a[i][j+1].second - a[i][j].second);
            col[a[i][j+1].first].emplace_back(a[i][j].first, a[i][j].second - a[i][j+1].second);
        }
    }

    diff.resize(C);
    visited.assign(C, false);

    rep(i, C){
        if(visited[i]) continue;
        if(!dfs(i, 0)){
            cout << "No" << endl;
            return 0;
        }
    }

    ll m = *min_element(diff.begin(), diff.end());

    rep(i, R){
        for(pii& p : a[i]){
            if(p.second - diff[p.first] + m < 0){
                cout << "No" << endl;
                return 0;
            }
        }
    }

    cout << "Yes" << endl;
}

