int rush(const pii &pos, const lld val0){
    int flag=0;
    map<pii, lld>::iterator ait[3];
    for(int i=0; i<4; i++){
        int cnt=0;
        for(int j=0; j<3; j++){
            pii buf(pos.first+dx[j][i], pos.second+dy[j][i]);
            ait[j]=s.find(buf);
            if(ait[j]!=s.end())
                cnt++;
        }
        if(cnt==3){
            if((val0+ait[1]->second)!=(ait[0]->second+ait[2]->second)){
                //printf("find %d+%d!=%d+%d\n", val0, ait[1]->second, ait[0]->second, ait[2]->second);
                return -1;
            }
        }else if(cnt==2){
            lld val;
            pii buf;
            if(ait[0]==s.end()){
                val=-(ait[2]->second-val0-ait[1]->second);
                buf=MP(pos.first+dx[0][i], pos.second+dy[0][i]);
            }else if(ait[1]==s.end()){
                val=-(val0-ait[0]->second-ait[2]->second);
                buf=MP(pos.first+dx[1][i], pos.second+dy[1][i]);
            }else if(ait[2]==s.end()){
                val=-(ait[0]->second-val0-ait[1]->second);
                buf=MP(pos.first+dx[2][i], pos.second+dy[2][i]);
            }
            //printf("p (%d,%d) = %d\n", buf.first, buf.second, val);
            if(val<0LL)return -1;
            if(val>(1LL<<40))while(1);
            s.insert(MP(buf, val));
            int temp=rush(buf, val);
            if(temp<0)return -1;
            flag+=temp+1;
        }
    }
    return flag;
}

