    --y[i], --x[i];
    hashed[{y[i], x[i]}] = c[i];
  }

  int v[] = {-1, 1};
  for(auto k : hashed) {
    auto point = k.first;
    for(int a = -1; a <= 0; a++) {
      for(int b = -1; b <= 0; b++) {
        int ny = point.first + a, nx = point.second + b;
        if(isover(ny, nx)) continue;
        if(isover(ny + 1, nx + 1)) continue;

        auto p = get(ny, nx), q = get(ny + 1, nx + 1);
        auto r = get(ny + 1, nx), s = get(ny, nx + 1);

        if(p == -1 && q == -1) {
          continue;
        } else if(p == -1) {
          if(r >= 0 && s >= 0) {
            int val = r + s - q;
            if(val < 0) E();
            if(hashed.count({ny, nx})) {
              if(hashed[{ny, nx}] != val) E();
            } else {
              hashed[{ny, nx}] = val;
            }
          }
        } else if(q == -1) {
          if(r >= 0 && s >= 0) {
            int val = r + s - p;
            if(val < 0) E();
            if(hashed.count({ny + 1, nx + 1})) {
              if(hashed[{ny + 1, nx + 1}] != val) E();
            } else {
              hashed[{ny + 1, nx + 1}] = val;
            }
          }
        } else {
          if(r == -1 && s == -1) continue;
          if(r == -1) {
            int val = p + q - s;
            if(val < 0) E();
            if(hashed.count({ny + 1, nx})) {
              if(hashed[{ny + 1, nx}] != val) E();
            } else {
              hashed[{ny + 1, nx}] = val;
            }
          } else if(s == -1) {
            int val = p + q - r;
            if(val < 0) E();
            if(hashed.count({ny, nx + 1})) {
              if(hashed[{ny, nx + 1}] != val) E();
            } else {
              hashed[{ny, nx + 1}] = val;
            }

          } else {
            int val = p + q;
            int val2 = s + r;
            if(val != val2) E();
          }
        }
      }
    }
  }
  puts("Yes");
}

