int main(){
    int N,R,C;
    cin>>R>>C>>N;
    int r[100010],c[100010],a[100010];
    for(int i=0;i<N;i++){
        cin>>r[i]>>c[i]>>a[i];
        edge e;
        e.to=c[i]+R;
        e.cost=a[i];
        G[r[i]].push_back(e);
        e.to=r[i];
        G[c[i]+R].push_back(e);
    }
    int64_t val[200010];
    fill(val,val+200010,INF);
    for(int i=1;i<=R+C;i++){
        if(val[i]==INF){
            queue<int> q;
            q.push(i);
            val[i]=0;
            while(!q.empty()){
                int v = q.front(); q.pop();
                for(int j=0;j<G[v].size();j++){
                    edge u = G[v][j];
                    if(val[u.to]==INF){
                        val[u.to] = u.cost - val[v];
                        q.push(u.to);
                    }
                }
            }
        }
    }
    bool flag = true;
    for(int i=1;i<=R+C;i++){
        for(int j=0;j<G[i].size();j++){
            edge e = G[i][j];
            if(e.cost != val[i] + val[e.to]){
                flag=false;
                break;
            }
        }
    }
    if(flag){
        bool used[200010]={};
        for(int i=1;i<=R+C;i++){
            if(!used[i]){
                queue<int> q;
                q.push(i);
                used[i]=true;
                int64_t min_R=INF;
                int64_t min_L=INF;
                if(i<=R){
                    min_R = min(min_R,val[i]);
                }else{
                    min_L = min(min_L,val[i]);
                }
                while(!q.empty()){
                    int v = q.front(); q.pop();
                    for(int j=0;j<G[v].size();j++){
                        edge u = G[v][j];
                        if(!used[u.to]){
                            used[u.to]=true;
                            if(u.to<=R){
                                min_R = min(min_R,val[u.to]);
                            }else{
                                min_L = min(min_L,val[u.to]);
                            }
                            q.push(u.to);
                        }
                    }
                }
                if(min_R+min_L < 0){
                    flag=false;
                    break;
                }
            }
        }
    }


    if(flag){
        cout<<"Yes"<<endl;
    }else{
        cout<<"No"<<endl;
    }
    return 0;
}

