		r--;
		c--;
		P pos(r, c);
		q.push(pos);
		memo[pos] = a;
	}
	bool ans = true;
	vector<int> diff(R, INF);
	while (!q.empty()) {
		P pos = q.front();
		q.pop();
		int r = pos.first, c = pos.second;
		P b(r + 1, c);
		if (memo.find(b) == memo.end()) {
			if (diff[r] != INF) {
				if (memo[pos] - diff[r] < 0) {
					ans = false;
					break;			
				} else {
					q.push(b);
					memo[b] = memo[pos] - diff[r];
				}
			}
		} else {
			int d = memo[pos] - memo[b];
			if (diff[pos.first] == INF) {
				diff[pos.first] = d;
			} else {
				ans = false;
				break;
			}			
		}
		P u(r - 1, c);
		if (memo.find(u) == memo.end()) {
			if (r > 0 && diff[r - 1] != INF) {
				if (memo[pos] + diff[r - 1] < 0) {
					ans = false;
					break;			
