bool DFSUtil(int v, vector<bool> &visited, vector<bool> &was){
  visited[v] = true;
  for(int i = 0; i < g[v].size(); i++){
    int w = g[v][i]. first;
    long long a = g[v][i].second;
    if(was[w] && node[v] + node[w] != a){
      return false;
    }
    node[w] = a - node[v];
    was[w] = true;

    if(v < R) minR = minR >node[v] ? node[v] : minR;
    if(v >= R) minC = minC>node[v] ? node[v] : minC;
    if(minR + minC < 0) return false;
    if(!visited[w]){
      if(!DFSUtil(w, visited, was)) return false;
    }
  }
  return true;
}

