using namespace std;

typedef pair<int, int> P;
map<P, int> table;
const int SIZE = 100009;
bool cr[SIZE];
bool cc[SIZE];
int row[SIZE];
int col[SIZE];


set<pair<P, int>> pr[SIZE];
set<pair<P, int>> pc[SIZE];

int main()
{
    int R, C;
    RD(R, C);


    int N;
    RD(N);


    while(N--)
    {
        int r, c, x;
        RD(r, c, x);

        table[{r, c}] = x;

        pr[r].insert({{r, c}, x});
        pc[c].insert({{r, c}, x});
    }

    bool ans = true;



    queue<P> que;


    auto add_row = [&](int x, int y, int v)
    {
        for(int dx = -1; dx <= 1; dx += 2)
        {
            auto it = table.find({x + dx, y});
            if(it != table.end())
            {
                int xx = x - (dx < 0);
                int vv = (it->second - v) * dx;

                if(cr[xx])
                {
                    if(row[xx] != vv)
                        ans = false;
                }
                else
                {
                    cr[xx] = true;
                    row[xx] = vv;
                    que.push({xx, 0});
                }
            }
        }
    };
    auto add_col = [&](int x, int y, int v)
    {
        for(int dy = -1; dy <= 1; dy += 2)
        {
            auto it = table.find({x, y + dy});
            if(it != table.end())
            {
                int yy = y - (dy < 0);
                int vv = (it->second - v) * dy;
                if(cc[yy])
                {
                    if(col[yy] != vv)
                        ans = false;
                }
                else
                {
                    cc[yy] = true;
                    col[yy] = vv;
                    que.push({0, yy});
                }
            }
        }
    };


    auto add = [&](int x, int y, int v)
    {
        add_row(x, y, v);
        add_col(x, y, v);
    };


    for(auto e: table)
        add(e.first.first, e.first.second, e.second);


    auto f = [&](set<pair<P, int>>& lst, int dx, int dy, int dv)
    {
        for(auto e: lst)
        {
            int x2 = e.first.first + dx;
            int y2 = e.first.second + dy;
            int v = e.second + dv;


            if(v < 0)
                ans = false;

            auto it = table.find({x2, y2});

            if(it != table.end())
            {
                if(it->second != v)
                    ans = false;
            }
            else if(0 < x2 && x2 <= R && 0 < y2 && y2 <= C)
            {
                table[{x2, y2}] = v;
                pr[x2].insert({{x2, y2}, v});
                pc[y2].insert({{x2, y2}, v});
                add(x2, y2, v);
            }
        }
    };

    while(que.size())
    {
        auto p = que.front();
        que.pop();


        if(p.first)
        {
            f(pr[p.first], 1, 0, row[p.first]);
            f(pr[p.first + 1], -1, 0, -row[p.first]);
        }
        else
        {
            f(pc[p.second], 0, 1, col[p.second]);
            f(pc[p.second + 1], 0, -1, -col[p.second]);
        }
    }



    WTL(ans? "Yes": "No");


}

