int rind[110000];
int cind[110000];
int V[110000];
bool dame=false;
void dfs(int u,long long a,long long b){
	int r=R[u];
	int c=C[u];
	v[u]=1;
	if(pd[r]){
		if(p[r]!=a)dame=true;
	}else{
		pd[r]=1;
		p[r]=a;
	}
	if(qd[c]){
		if(q[c]!=b)dame=true;
	}else{
		qd[c]=1;
		q[c]=b;
	}
	if(rind[u]){
		int to=row[r][rind[u]-1].second;
		if(!v[to]){
			dfs(to,a,b+V[to]-V[u]);
		}
	}
	if(rind[u]+1<row[r].size()){
		int to=row[r][rind[u]+1].second;
		if(!v[to]){
			dfs(to,a,b+V[to]-V[u]);
		}
	}
	if(cind[u]){
		int to=col[c][cind[u]-1].second;
		if(!v[to]){
			dfs(to,a+V[to]-V[u],b);
		}
	}
	if(cind[u]+1<col[c].size()){
		int to=col[c][cind[u]+1].second;
		if(!v[to]){
			dfs(to,a+V[to]-V[u],b);
		}
	}

}
int main(){
	int a,b,c;scanf("%d%d%d",&a,&b,&c);
	for(int i=0;i<c;i++){
		int s,t,u;
		scanf("%d%d%d",&s,&t,&u);
		s--;t--;
		R[i]=s;C[i]=t;V[i]=u;
		cost[i]=u;
		row[s].push_back(make_pair(t,i));
		col[t].push_back(make_pair(s,i));
	}
	for(int i=0;i<a;i++)std::sort(row[i].begin(),row[i].end());
	for(int i=0;i<b;i++)std::sort(col[i].begin(),col[i].end());
	for(int i=0;i<a;i++){
		for(int j=0;j<row[i].size();j++){
			rind[row[i][j].second]=j;
		}
	}
	for(int i=0;i<b;i++){
		for(int j=0;j<col[i].size();j++){
			cind[col[i][j].second]=j;
		}
	}

	for(int i=0;i<c;i++){
		if(v[i])continue;
		dfs(i,V[i],0);
	}
	for(int i=0;i<c;i++){
		if(V[i]!=p[R[i]]+q[C[i]])dame=true;
	}
	if(dame){
		printf("No\n");return 0;
	}
	while(1);
	long long wp=99999999999999999LL;
	long long wq=99999999999999999LL;
	for(int i=0;i<a;i++)if(pd[i])wp=min(wp,p[i]);
	for(int i=0;i<b;i++)if(qd[i])wq=min(wq,q[i]);
	if(wp+wq<0){
		printf("No\n");
	}else printf("Yes\n");
}

