            FOR2(j, c){
                if(cost[i][j] != MAX){
                    if(x[i] == MAX && y[j] != MAX){
                        x[i] = cost[i][j] - y[j];
                        rest -= 1;
                    }else if(x[i] != MAX && y[j] == MAX){
                        y[j] = cost[i][j] - x[i];
                        rest -= 1;
                    }
                }
            }
        }
