bool solve() {
	REP(x,h) xhead[x]=-1; REP(i,n) xnxt[i]=xhead[px[i]],xhead[px[i]]=i;
	REP(y,w) yhead[y]=-1; REP(i,n) ynxt[i]=yhead[py[i]],yhead[py[i]]=i;
	REP(x,h) xz[x]=-1; REP(y,w) yz[y]=-1;
	//REP(x,h) { printf("x=%d:",x); for(int at=xhead[x];at!=-1;at=xnxt[at]) printf(" %d=%d",py[at],pz[at]); puts(""); }
	//REP(y,w) { printf("y=%d:",y); for(int at=yhead[y];at!=-1;at=ynxt[at]) printf(" %d=%d",px[at],pz[at]); puts(""); }
	REP(cx,h) if(xz[cx]==-1&&xhead[cx]!=-1) {
		int c=xhead[cx],cy=py[c],cz=pz[c]; xz[cx]=yz[cy]=cz; //printf("starting at (%d,%d)=%d\n",cx,cy,cz);
		for(int at=xhead[cx];at!=-1;at=xnxt[at]) if(py[at]!=cy) {
			int ny=py[at],nz=pz[at]; //printf("initx(%d,%d)=%d\n",px[at],py[at],pz[at]);
			assert(yz[ny]==-1); yz[ny]=nz; qy[qyhead++]=ny;
		}
		for(int at=yhead[cy];at!=-1;at=ynxt[at]) if(px[at]!=cx) {
			int nx=px[at],nz=pz[at]; //printf("inity(%d,%d)=%d\n",px[at],py[at],pz[at]);
			assert(xz[nx]==-1); xz[nx]=nz; qx[qxhead++]=nx;
		}
		while(qxtail<qxhead||qytail<qyhead) {
			if(qxtail<qxhead) {
				int x=qx[qxtail++]; //printf("\tprocessing x=%d\n",x);
				for(int at=xhead[x];at!=-1;at=xnxt[at]) if(py[at]!=cy) {
					int ny=py[at];
					int nz=cz+pz[at]-xz[x]; //printf("\t\t(%d,%d)=%d -> (%d,%d)=%d\n",px[at],py[at],pz[at],cx,ny,nz);
					if(yz[ny]>=0) if(yz[ny]!=nz) return false; else continue;
					if(nz<0) return false;
					yz[ny]=nz; qy[qyhead++]=ny;
				}
			}
			if(qytail<qyhead) {
				int y=qy[qytail++]; //printf("\tprocessing y=%d\n",y);
				for(int at=yhead[y];at!=-1;at=ynxt[at]) if(px[at]!=cx) {
					int nx=px[at];
					int nz=cz+pz[at]-yz[y]; //printf("\t\t(%d,%d)=%d -> (%d,%d)=%d\n",px[at],py[at],pz[at],nx,cy,nz);
					if(xz[nx]>=0) if(xz[nx]!=nz) return false; else continue;
					if(nz<0) return false;
					xz[nx]=nz; qx[qxhead++]=nx;
				}
			}
		}
		//REP(i,qxhead) printf("(%d,%d)=%d ",qx[i],cy,xz[qx[i]]); REP(i,qyhead) printf("(%d,%d)=%d ",cx,qy[i],yz[qy[i]]); puts("");
	}
	return true;
}

void run() {
	scanf("%d%d%d",&h,&w,&n); REP(i,n) scanf("%d%d%d",&px[i],&py[i],&pz[i]),--px[i],--py[i];
	printf("%s\n",solve()?"Yes":"No");
}

