        if(children[i].size() == 0){
            continue;
        }
        int mini = i;
        for(int j = 0; j < children[i].size(); j++){
            if(uni.diff(mini, children[i][j]) > 0){
                mini = children[i][j];
            }
        }
        for(int j = 0; j < children[i].size(); j++){
            parent[children[i][j]] = mini;
        }
    }
