int main() {
	int R = nextInt();
	int C = nextInt();
	int N = nextInt();
	deque<tuple<int, int, int> > rca;
	map<pair<int, int>, int> dic;
	vector<bool> rRuleFlags(R+1);
	vector<int> rRule(R+1);
	vector<bool> cRuleFlags(C+1);
	vector<int> cRule(C+1);
	for(int i=0; i<N; ++i) {
		int r = nextInt();
		int c = nextInt();
		int a = nextInt();
		rca.emplace_back(r, c, a);
		dic[{r, c}] = a;
	}
	for(tuple<int, int, int> v : rca) {
		int r = get<0>(v);
		int c = get<1>(v);
		int a = get<2>(v);
		{
			auto it = dic.find({r+1, c});
			if(it!=dic.end()) {
				int a2 = it->second;
				int d = a2 - a;
				if(rRuleFlags[r+1]) {
					if(rRule[r+1]!=d) {
						echoln("No");
						return 0;
					}
				}
				else {
					rRuleFlags[r+1] = true;
					rRule[r+1] = d;
				}
			}
		}
		{
			auto it = dic.find({r, c+1});
			if(it!=dic.end()) {
				int a2 = it->second;
				int d = a2 - a;
				if(cRuleFlags[c+1]) {
					if(cRule[c+1]!=d) {
						echoln("No");
						return 0;
					}
				}
				else {
					cRuleFlags[c+1] = true;
					cRule[c+1] = d;
				}
			}
		}
	}
	while(!rca.empty()) {
		int r = get<0>(rca.front());
		int c = get<1>(rca.front());
		int a = get<2>(rca.front());
		rca.pop_front();
		if(rRuleFlags[r+1] && dic.find({r+1, c})==dic.end()) {
			int a2 = a+rRule[r+1];
			if(a2<0) {
				echoln("No");
				return 0;
			}
			else {
				dic[{r+1, c}] = a2;
				rca.emplace_back(r+1, c, a2);
			}
		}
		if(rRuleFlags[r] && dic.find({r-1, c})==dic.end()) {
			int a2 = a-rRule[r];
			if(a2<0) {
				echoln("No");
				return 0;
			}
			else {
				dic[{r-1, c}] = a2;
				rca.emplace_back(r-1, c, a2);
			}
		}
		if(cRuleFlags[c+1] && dic.find({r, c+1})==dic.end()) {
			int a2 = a+cRule[c+1];
			if(a2<0) {
				echoln("No");
				return 0;
			}
			else {
				dic[{r, c+1}] = a2;
				rca.emplace_back(r, c+1, a2);
			}
		}
		if(cRuleFlags[c] && dic.find({r, c-1})==dic.end()) {
			int a2 = a-cRule[c];
			if(a2<0) {
				echoln("No");
				return 0;
			}
			else {
				dic[{r, c-1}] = a2;
				rca.emplace_back(r, c-1, a2);
			}
		}
	}
	echoln("Yes");

	return 0;
}

