struct point
{
    int r;
    int c;

    point(int r, int c) : r(r), c(c){}
};

struct datum : public point
{
    int val;

    datum(int r, int c, int val) : point(r, c), val(val){}
};

typedef map<int, map<int, int>> matrix;

int R, C, N;

bool is_fill(matrix& mat, int r, int c, int dr, int dc)
{
    if (not exist(mat[r], c) or not exist(mat[r], c + dc)) return false;
    if (not exist(mat[r + dr], c) or not exist(mat[r + dr], c + dc)) return false;
    return true;
}

bool is_correct(matrix& mat, int r, int c, int dr, int dc)
{
    if (not is_fill(mat, r, c, dr, dc)) return false;
    if (mat[r][c] < 0 or mat[r + dr][c + dc] < 0 or mat[r + dr][c] < 0 or mat[r][c + dc] < 0) return false;
    return mat[r][c] + mat[r + dr][c + dc] == mat[r + dr][c] + mat[r][c + dc];
}

bool is_correct(matrix& mat, int r, int c)
{
    FOR(i, -1, 2){
        FOR(j, -1, 2){
            if (not i and not j) continue;
            if (r + i < 1 or R < r + i or c + j < 1 or C < c + j) continue;
            if (not is_fill(mat, r, c, i, j)) continue;
            if (not is_correct(mat, r, c, i, j)) return false;
        }
    }

    return true;
}

point try_write(matrix& mat, int r, int c, int dr, int dc)
{
    bool w = exist(mat[r], c);
    bool x = exist(mat[r + dr], c);
    bool y = exist(mat[r], c + dc);
    bool z = exist(mat[r + dr], c + dc);
    if (w + x + y + z != 3) return {0, 0};
    if (not w){
        mat[r][c] = mat[r + dr][c] + mat[r][c + dc] - mat[r + dr][c + dc];
    }
    if (not x){
        mat[r + dr][c] = mat[r][c] + mat[r + dr][c + dc] - mat[r][c + dc];
        r += dr;
    }
    if (not y){
        mat[r][c + dc] = mat[r][c] + mat[r + dr][c + dc] - mat[r + dr][c];
        c += dc;
    }
    if (not z){
        mat[r + dr][c + dc] = mat[r + dr][c] + mat[r][c + dc] - mat[r][c];
        r += dr;
        c += dc;
    }
    return {r, c};
}

bool check(matrix& mat, int r, int c)
{
    FOR(i, -1, 2){
        FOR(j, -1, 2){
            if (not i and not j) continue;
            if (r + i < 1 or R < r + i or c + j < 1 or C < c + j) continue;
            if (is_fill(mat, r, c, i, j) and not is_correct(mat, r, c, i, j)) return false;
            point p = try_write(mat, r, c, i, j);
            if (not p.r and not p.c) continue;
            if (not is_correct(mat, p.r, p.c)) return false;
        }
    }

    return true;
}

