{
    R = in();
    C = in();
    N = in();
    vector<datum> data;
    matrix mat;

    REP(i, N){
        int r = in();
        int c = in();
        int val = in();
        mat[r][c] = val;
        data.pb(r, c, val);
    }

    for (datum i : data){
        if (not check(mat, i.r, i.c)){
            puts("No");
            return 0;
        }
    }
    puts("Yes");

    return 0;
}

