{
    seq[cur++] = u;
    for(int i = 0;i < G[u].size();++i)
    {
        int v = G[u][i].v;
        LL w = G[u][i].w;

        if(!vis[v])
        {
            vis[v] = 1;
            A[v] = w-A[u];
            if(!dfs(v)) return false;
        }
        else
        {
            if(A[v] + A[u] != w) return false;

        }
    }
    return true;

}


bool bfs(int s)
{
    int b = 0, e = 1;
    seq[0] = s;
    vis[s] = true;
    A[s] = 0;
    while (b < e) {
      for (int j = 0; j < (int) G[seq[b]].size(); j++) {
        int u = G[seq[b]][j].v;
        int w = G[seq[b]][j].w;
        if (vis[u]) {
          if (A[seq[b]] + A[u] != w) {
            return false;
            }
          continue;
        }
        seq[e] = u;
        A[u] = w - A[seq[b]];
        vis[u] = true;
        e++;
      }
      b++;
    }
    cur = e;

    return true;
}

