		for (int dx = -1; dx <= 1; dx++)
			for (int dy = -1; dy <= 1; dy++)
				if (x[i] + dx > 0 && x[i] + dx <= r && y[i] + dy > 0 && y[i] + dy <= c && g.count(make_pair(x[i] + dx, y[i] + dy)) == 0)
					add(x[i] + dx, y[i] + dy, 0);

	printf("Yes\n");

	return 0;
}

