bool solve(){

  ll mp00 = mp[make_pair(0, 0)];
  bool oc00 = occu[make_pair(0, 0)];
  REP(h, 1, r){
    ll mph0 = mp[make_pair(h, 0)];
    bool och0 = occu[make_pair(h, 0)];
    if(oc00 && och0) continue;
    REP(w, 1, c){
        ll x1 = mp00 + mp[make_pair(h, w)], x2 = mph0 + mp[make_pair(0, w)];
