const int INF = 1 << 30;
const ll INFL = 1LL << 60;


class Solver {
  public:
    bool solve() {
        int R, C; cin >> R >> C;
        int N; cin >> N;
        vector<int> y(N), x(N), a(N);
        vector<int> y0(N, 0), x0(N, 0);
        vector<ll> diff_y(N, -INF), diff_x(N, -INF);
        map<pii, int> G;
        rep(i, N) {
            cin >> y[i] >> x[i] >> a[i];
            y[i]--; x[i]--;
            G[make_pair(y[i], x[i])] = a[i];
            if(y[i] == 0) x0[x[i]] = a[i];
            if(x[i] == 0) y0[y[i]] = a[i];
        }
        cerr << x0 << endl;
        cerr << y0 << endl;
        bool flg = false;
        rep(i, N) {
            ll dx = a[i] - y0[y[i]];
            ll dy = a[i] - x0[x[i]];
            cerr << i <<  " (" << y[i] << "," << x[i] << ") " << endl;
            cerr << "diff x " << diff_x[y[i]] << " " << dx << endl;
            cerr << "diff y " << diff_y[x[i]] << " " << dy << endl;
            if(diff_x[y[i]] != -INF and diff_x[y[i]] != dx) {
                flg = true;
                cerr << "!x" << endl;
            }                
            if(diff_y[x[i]] != -INF and diff_y[x[i]] != dy) {
                flg = true;
                cerr << "!y" << endl;
            }
            if(x[i] != 0) diff_x[y[i]] = dx;
            if(y[i] != 0) diff_y[x[i]] = dy;
        }

        {
            const int dy[] = {-1, -1, 0, 1, 1, 1, 0, -1};
            const int dx[] = {0, 1, 1, 1, 0, -1, -1, -1};
            auto check = [&](vector<int> g,int mx) {
                    rep(b, 3) if(g[b] < 0 or mx <= g[b]) return false;
                    return true;
                };
            rep(i, N) {
                int yy = y[i], xx = x[i];
                vector<int> ys, xs;
                rep(j, 8) {                    
                    ys.push_back(yy + dy[j]);
                    xs.push_back(xx + dx[j]);
                    if(xs.size() == 3) {

                        if(check(xs, C) and check(ys, R)) {
                            debug(xs);
                            debug(ys);                            
                            vector<int> aa(3);
                            rep(k, 3) {                                
                                aa[k] = G.count(make_pair(ys[k], xs[k])) ? G[make_pair(ys[k], xs[k])] : -INF; 
                            }
                            int xa = aa[0] + aa[2];
                            int xb = a[i] + aa[1];
                            cerr << xa << " " << xb << endl;
                            if(xa >= 0 and xb >= 0) {
                                flg |= xa != xb;
                            }
                            if(xa >= 0 and xb < 0 and xb + INF >= 0) {
                                flg |= xa < xb + INF;
                            }
                            if(xa < 0 and xb >= 0 and xa + INF >= 0) {
                                flg |= xb < xa + INF;
                            }
                        }
                        xs.erase(xs.begin(), xs.begin() + 1);
                        ys.erase(ys.begin(), ys.begin() + 1);
                    }
                }
            }
        }

        cout << ( flg ? "No" : "Yes" ) << endl;
        return 0;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    Solver s;
    s.solve();
    return 0;
}

