typedef long long int ll;

#define rep(x, a, b) for (int x = a; x < b; x++)
#define Min(x, y) (((x) < (y))?(x):(y))
#define Max(x, y) (((x) > (y))?(x):(y))

struct edge {
  int p, a;
  edge(int p, int a) : p(p), a(a) {};
};

vector<ll> nodes[2];
vector<vector<edge>> edges[2];

const ll toobig = 1LL<<40;
ll mins[2];
bool consistent;

void
dfs(int r, bool i, ll cur) {
  if (nodes[i][r] != -1) {
    consistent &= cur == nodes[i][r];
    return;
  }

  nodes[i][r] = cur;
  mins[i] = Min(cur, mins[i]);

  for (auto e : edges[i][r]) {
    dfs(e.p, i?0:1, e.a - cur);
  }
}

int main()
{
  int r, c, n;

  cin >> r >> c >> n;

  nodes[0] = vector<ll>(c, -1);
  nodes[1] = vector<ll>(n, -1);
  edges[0] = vector<vector<edge>>(c);
  edges[1] = vector<vector<edge>>(r);

  rep (i, 0, n) {
    int r, c;
    ll a;

    cin >> r >> c >> a;
    r--; c--;

    edges[0][c].emplace_back(r, a);
    edges[1][r].emplace_back(c, a);
  }

  bool success = true;

  rep (i, 0, r) {
    if (nodes[1][i] >= 0) continue;

    consistent = true;
    mins[0] = mins[1] = toobig;
    dfs(i, true, 0);
    success &= (mins[0] + mins[1] >= 0) & consistent;
  }

  cout << (success?"Yes":"No") << endl;

  return 0;
}

