std::vector<std::pair<std::pair<int,int>,int> > v;
std::map<int,std::vector<int> > xis,yis;
std::vector<int> used;

std::map<int,int> xAxis,yAxis;

bool traverse(int i,int x,int y,int a,int dx,int dy){
  auto itx = xAxis.find(x), ity = yAxis.find(y);
  if(itx==xAxis.end())xAxis[x] = dx;
  else if(itx->second!=dx)return false;
  if(ity==yAxis.end())yAxis[y] = dy;
  else if(ity->second!=dy)return false;
  if(used[i])return true;
  used[i] = 1;
  for(const int &p : xis[x]){
    if(p!=i){
      int a2 = v[p].second;
      bool r = traverse(p,v[p].first.first,v[p].first.second,a2,dx,dy+a2-a);
      if(!r)return false;
    }
  }
  for(const int &p : yis[y]){
    if(p!=i){
      int a2 = v[p].second;
      bool r = traverse(p,v[p].first.first,v[p].first.second,a2,dx+a2-a,dy);
      if(!r)return false;
    }
  }
  return true;
}

struct C{
  bool operator()(const std::pair<int,int>& l, const std::pair<int,int>& r){
    return l.second < r.second;
  }
};

int main(){
  int r,c,n;
  std::cin >> r >> c >> n;
  for(int i=0;i<n;i++){
    int x,y,a;
    std::cin >> x >> y >> a;
    v.push_back(std::make_pair(std::make_pair(x,y),a));
    xis[x].push_back(i);
    yis[y].push_back(i);
    used.push_back(0);
  }
  for(int i=0;i<n;i++){
    if(!used[i]){
      xAxis.clear();
      yAxis.clear();
      bool b = true;
      b = b && traverse(i,v[i].first.first,v[i].first.second,v[i].second,0,v[i].second);
      if(!b){
        std::cout << "No" << std::endl;
        return 0;
      }
      int xMin = std::min_element(xAxis.begin(),xAxis.end(),C()) -> second;
      int yMin = std::min_element(yAxis.begin(),yAxis.end(),C()) -> second;
      if(xMin + yMin - v[i].second < 0){
        std::cout << "No" << std::endl;
        return 0;
      }
    }
  }
  std::cout << "Yes" << std::endl;
  return 0;
}

