void sayno(){
	throw 0;
}


map<int,int> xinc,yinc;
map< pair<int,int> ,int> checked;
map< pair<int,int> , int> mass;

void dfs(int y,int x,int v){
	if( checked.count({y,x}) ){
		if( checked[{y,x}] != v ) sayno();
		return;
	}
	if( v < 0 ){
		// cout << v << endl;
		sayno();
	}
	checked[{y,x}] = v;

	int val1 = v + (xinc.count(x)?xinc[x]:0);
	int val2 = v + (yinc.count(y)?yinc[y]:0);
	int val3 = v + (xinc.count(x)?xinc[x]:0) + (yinc.count(y)?yinc[y]:0);
	pair<int,int> rig = {y,x+1};
	pair<int,int> dow = {y+1,x};
	pair<int,int> dia = {y+1,x+1};

	if( xinc.count(x) and mass.count(rig) and mass[rig] != val1 ){
		// cout << val1 << " " << mass[rig] << endl;
		sayno();
	}
	if( yinc.count(y) and mass.count(dow) and mass[dow] != val2 ){
		// cout << val2 << " " << mass[dow] << "|" << x << " " << y << endl;
		sayno();
	}
	if( (xinc.count(x) or yinc.count(y)) and mass.count(dia) and mass[dia] != val3 ){
		// cout << val3 << " " << mass[dia] << "|" << x << " " << y << endl;
		sayno();
	}
	if( val1 < 0 or val2 < 0 or val3 < 0 ) sayno();

	if( xinc.count(x) ) dfs(y,x+1, v + xinc[x]);
	if( yinc.count(y) ) dfs(y+1,x, v + yinc[y]);

}
void solve(long long R, long long C, long long N, vector<long long> r, vector<long long> c, vector<long long> a){
	// cout << "OK" << endl;
	xinc.clear();
	yinc.clear();
	checked.clear();
	mass.clear();
	for(int i = 0 ; i < r.size() ; i++){
		mass[{r[i],c[i]}] = a[i];
	}
	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		pair<int,int> rig = {y,x+1};
		pair<int,int> dow = {y+1,x};

		if( mass.count(rig) ){
			int diff = mass[rig] - p.second;
			xinc[x] = diff;
		}

		if( mass.count(dow) ){
			int diff = mass[dow] - p.second;
			yinc[y] = diff;
		}
	}

	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		int v = p.second;
		dfs(y,x,v);
	}


}




