void initialize() {
	for (long long i = 0; i < MAX_N; i++) {
		sort(x_1[i].begin(), x_1[i].end());
		y_sa[i] = 1LL << 60; x_sa[i] = 1LL << 60;
	}
}
bool solve_ai() {
	for (long long i = 0; i < MAX_N; i++) {
		long long sa = 0LL;
		for (int j = 0; j < x_1[i].size(); j++) {
			if (y_sa[x_1[i][j].first] != (1LL << 60)) sa = y_sa[x_1[i][j].first] - x_1[i][j].second;
		}
		for (long long j = 0; j < x_1[i].size(); j++) {
			if (y_sa[x_1[i][j].first] != (1LL << 60)) {
				if (sa != y_sa[x_1[i][j].first] - x_1[i][j].second)return false;
			}
			else y_sa[x_1[i][j].first] = sa + x_1[i][j].second;
		}
	}
	return true;
}
bool solve_bi() {
	for (long long i = 0; i < N; i++) x_sa[x[i]] = a[i] - y_sa[y[i]];
	long long minx = 1LL << 60;
	for (long long i = 0; i < MAX_N; i++)minx = min(minx, y_sa[y[i]]);
	for (long long i = 0; i < MAX_N; i++) { x_sa[i] += minx; y_sa[i] -= minx; }
	for (long long i = 0; i < MAX_N; i++) {
		if (x_sa[i] < 0LL || y_sa[i] < 0LL)return false;
	}
	return true;
}
