      ruse[x] = i;
    }else if(cuse[y]==-1){
      uf.unite(i, ruse[x]);
      cuse[y] = i;
    }else{
      uf.unite(ruse[x], cuse[y]);
      uf.unite(ruse[x], i);
    }
  }

  vvl G = VV(n, 0, 0, ll);
  for(int i=0;i<n;i++) G[uf.find(i)].push_back(i);
  vector<set<ll>> gx(h+1);
  vector<set<ll>> gy(w+1);
  for(int k=0;k<n;k++){
    if(G[k].size()==0) continue;
    vvl dat;
    for(auto t:G[k]) dat.push_back(d[t]);
    sort(all(dat), [](vll a, vll b){return a[2] < b[2];});
    ll m = dat.size();

    ll sa = -INF;
    //------------------------
    set<ll> X, Y;
    for(int i=0;i<m;i++){
      ll x = dat[i][0], y = dat[i][1];
      X.insert(x);
      Y.insert(y);
      gx[x].insert(i);
      gy[y].insert(i);
    }
    deque<ll> q;
    vll use(m+1, 0);
    q.push_front(0);
    use[0] = 1;
    vll stnum;

    while(!q.empty()){
      ll num = q.front();
      q.pop_front();
      if(!use[num]) continue;
      stnum.push_back(num);
      ll x = dat[num][0], y = dat[num][1], T = dat[num][2];

      if(r[x]==-INF&&c[y]==-INF){
        r[x] = T, c[y] = 0;
      }else if(c[y]==-INF){
        c[y] = T - r[x];
      }else if(r[x]==-INF){
        r[x] = T - c[y];
      }else if(r[x] + c[y]!=T){
        sa = abs(T - r[x] - c[y]);
        break;
      }
      gx[x].erase(num);
      gx[y].erase(num);
      for(auto to:gx[x]) {
        if(!use[to]) {
          use[to] = 1;
          q.push_front(to);
        }
      }
      for(auto to:gy[y]) {
        if(!use[to]) {
          use[to] = 1;
          q.push_front(to);
        }
      }
    }
    //----------------------------
    if(sa!=-INF){
      c[dat[0][1]] = sa;
      for(auto node:stnum){
        ll x = dat[node][0], y = dat[node][1];
        if(r[x]==-1&&c[y]==-INF){
          r[x] = dat[node][2], c[y] = 0;
        }else if(r[x]==-INF){
          c[y] = dat[node][2] - r[x];
        }else if(c[y]==-INF){
          r[x] = dat[node][2] - c[y];
        }else if(r[x] + c[y]!=dat[node][2]){
          err();
        }
      }
    }
  }

  ll min_x = 100000000000000;
  ll min_y = 100000000000000;
  for(int i=0;i<n;i++){
    ll x = d[i][0], y = d[i][1];
    min_x = min(min_x, r[x]);
    min_y = min(min_y, c[y]);
  }
  if(min_x+min_y<0) err();
  std::cout << "Yes" << '\n';
  return 0;
}

