const int N = 1e5 + 10;

vi r[N];
vi c[N];


vector<pi> E[N];

inline void add(int xx, int yy, int cc)
{
    E[xx].pb({yy, cc});
    E[yy].pb({xx, -cc});
}

int mark[N];
ll val[N];
int OK = 1;

void dfs(int x, ll vv = 0)
{
    mark[x] = 1;
    val[x] = vv;
    forn(i, sz(E[x]))
    {
        int yy = E[x][i].F;
        int cc = E[x][i].S;
        if (mark[yy])
        {
            OK &= val[yy] == val[x] + cc;
        }
        else
        {
            dfs(yy, val[x] + cc);
        }
    }
}


int x[N], y[N], v[N];

