        {
            int id = r[i][j];
            vv.pb({y[id], v[id]});
        }
        forn(j, sz(vv) - 1)
        {
            add(vv[j].F, vv[j + 1].F, vv[j + 1].S - vv[j].S);
        }
    }
    forn(i, N) if (!mark[i]) dfs(i);

