namespace {
  int R, C, N;
  using edge_t = std::tuple<int, int, int>;
  std::map<std::tuple<int, int>, std::vector<edge_t>> G;

  void input() {
    std::cin >> R >> C;
    std::cin >> N;
    for (int i = 0; i < N; ++i) {
      int r, c, a;
      std::cin >> r >> c >> a;
      --r; --c;
      G[{0, r}].emplace_back(1, c, a);
      G[{1, c}].emplace_back(0, r, a);
    }

  }

  bool solve() {
    std::stack<std::tuple<int, int>> stack;
    std::map<std::tuple<int, int>, int> values;

    for (const auto &item : G) {
      const auto &v = item.first;
      if (values.find(v) != values.end()) {
        continue;
      }

      stack.push(v);
      values[v] = 0;
      while (!stack.empty()) {
        const auto v = stack.top(); stack.pop();
        for (const auto &edge : G[v]) {
          const int t = std::get<0>(edge);
          const int i = std::get<1>(edge);
          const int a = std::get<2>(edge);
          const auto w = std::make_tuple(t, i);

          if (values.find(w) != values.end()) continue;

          values[w] = a - values[v];
          stack.push(w);
        }
      }
    }

    // check contradiction
    for (const auto &item : G) {
      const auto &v = item.first;
      for (const auto &edge : item.second) {
        const int t = std::get<0>(edge);
        const int i = std::get<1>(edge);
        const int a = std::get<2>(edge);
        const auto w = std::make_tuple(t, i);
        if (values[v] + values[w] != a) {
          return false;
        }
      }
    }

    // check if we can set all elements to non-negative value
    std::set<std::tuple<int, int>> visited;
    for (const auto &item : G) {
      const auto &v = item.first;
      if (visited.find(v) != visited.end()) continue;

      std::int64_t min_0 = std::numeric_limits<std::int64_t>::max() / 3;
      std::int64_t min_1 = std::numeric_limits<std::int64_t>::max() / 3;

      stack.push(v);
      while (!stack.empty()) {
        const auto v = stack.top(); stack.pop();
        visited.insert(v);
        if (std::get<0>(v) == 0) {
          if (min_0 > values[v]) min_0 = values[v];
        } else {
          if (min_1 > values[v]) min_1 = values[v];
        }
        for (const auto &edge : G[v]) {
          const int t = std::get<0>(edge);
          const int i = std::get<1>(edge);
          const int a = std::get<2>(edge);
          const auto w = std::make_tuple(t, i);

          if (visited.find(w) != visited.end()) continue;
          stack.push(w);
        }
      }
      if (min_0 + min_1 < 0) return false;
    }

    return true;
  }
}


