void normalize(pair<long long, long long> p)
{
	if (p.first == -1)
	{
		R = min(R, 0ll+p.second);
	}
	else
	{
		L = max(L, 0ll-p.second);
	}
}

pair<long long, long long> sub(int val, pair<long long, long long> a)
{
	pair<long long, long long> p = make_pair(0, val);
	a.first = p.first - a.first;
	a.second = p.second - a.second;
	return a;
}

void dfs(int v)
{
	//cout << s_r[r[v]].first << " " << s_r[r[v]].second << " " << v << " " << r[v] <<" "<<L<<" "<<R<< endl;
	//cout << s_c[c[v]].first << " " << s_c[c[v]].second << endl;

	if (L > R)
		return;

	used[v] = 1;
	normalize(s_r[r[v]]);
	normalize(s_c[c[v]]);

	set<int>::iterator it;
	while (true)
	{
		if (by_row[r[v]].size())
		{
			it = by_row[r[v]].begin();
			int id = (*it);
			by_row[r[v]].erase(it);

			if (used[id] == 0)
			{
				c_val[c[id]] = val[id] - r_val[r[id]];
				s_c[c[id]] = sub(val[id], s_r[r[id]]);
				dfs(id);
			}
			continue;
		}
		if (by_col[c[v]].size())
		{
			it = by_col[c[v]].begin();
			int id = (*it);
			by_col[c[v]].erase(it);
			if (used[id] == 0)
			{
				r_val[r[id]] = val[id] - c_val[c[id]];
				s_r[r[id]] = sub(val[id], s_c[c[id]]);
				dfs(id);
			}
			continue;
		}
		break;
	}
}

