constexpr int INF = LIM<>::max();

void exit_ng()
{
	cout << "No" << endl;
	exit( 0 );
}

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	int H, W;
	scanf( "%d%d", &H, &W );

	int N;
	scanf( "%d", &N );

	map< PII, int > filled;
	REP( _, N )
	{
		int y, x, a;
		scanf( "%d%d%d", &y, &x, &a );
		filled[ MP( y - 1, x - 1 ) ] = a;
	}

	VI ds_var( H, INF ), ds_hor( W, INF );
	FOR( p, filled )
	{
		const int y = p.fst.fst;
		const int x = p.fst.snd;
		const int a = p.snd;

		if ( y + 1 < H && EXIST( filled, MP( y + 1, x ) ) )
		{
			const int d = filled[ MP( y + 1, x ) ] - a;
			if ( ds_var[y] != INF && ds_var[y] != d )
			{
				exit_ng();
			}
			ds_var[y] = d;
		}
		if ( x + 1 < W && EXIST( filled, MP( y, x + 1 ) ) )
		{
			const int d = filled[ MP( y, x + 1 ) ] - a;
			if ( ds_hor[x] != INF && ds_hor[x] != d )
			{
				exit_ng();
			}
			ds_hor[x] = d;
		}
	}

	auto filled2( filled );
	FOR( p, filled )
	{
		const int y = p.fst.fst;
		const int x = p.fst.snd;
		const int a = p.snd;

		if ( ds_hor[x] != INF &&
				( 0 <= x - 1 && a - ds_hor[x] < 0 ||
				  x + 1 < W && a + ds_hor[x] < 0 ) ||
				ds_var[y] != INF &&
				( 0 <= y - 1 && a - ds_var[y] < 0 ||
				  y + 1 < H && a + ds_var[y] < 0 ) )
		{
			exit_ng();
		}

		for ( const int sgn : { -1 , 1 } )
		{
			if ( ds_var[y] != INF )
			{
				const int na = a + sgn * ds_var[y];
				const auto pos = filled2.find( MP( y + sgn, x ) );
				if ( pos != end( filled2 ) && pos->snd != na )
				{
					exit_ng();
				}
				filled2[ MP( y + sgn, x ) ] = na;
			}
			if ( ds_hor[x] != INF  )
			{
				const int na = a + sgn * ds_hor[x];
				const auto pos = filled2.find( MP( y, x + sgn ) );
				if ( pos != end( filled2 ) && pos->snd != na )
				{
					exit_ng();
				}
				filled2[ MP( y, x + sgn ) ] = na;
			}
		}
	}

	cout << "Yes" << endl;

	return 0;
}

#include<iostream>
