using namespace std;
const int Nmax = 100001;
const int RCmax = 100001;
const long long INF = 10e10;
int R,C,N;
int r[Nmax], c[Nmax];
long long a[Nmax];
long long x[RCmax], y[RCmax];
vector<pair<int, long long> > xedge[RCmax];
vector<pair<int, long long> > yedge[RCmax];

int main(){
  cin >> R >> C >> N;

  for(int i=0; i<N; i++){
    cin >> r[i] >> c[i] >> a[i];
    xedge[r[i]].push_back(make_pair(c[i],a[i]));
    yedge[c[i]].push_back(make_pair(r[i],a[i]));
  }

  for(int i=1; i<=R; i++) x[i]=INF;
  for(int i=1; i<=C; i++) y[i]=INF;

  int ok=1;
  for(int i=1; i<=R; i++){
    if(x[i]!=INF) continue;
    queue<int> que;
    x[i]=0;
    que.push(i);
    while(!que.empty()){
      int ri=que.front(); que.pop();
      for(int k=0; k<xedge[ri].size(); k++){
        int ci = xedge[ri][k].first;
        long long ai = xedge[ri][k].second;
        if(y[ci]==INF){
          y[ci]=ai-x[ri];
          for(int l=0; l<yedge[ci].size(); l++){
            int rj=yedge[ci][l].first;
            long long aj=yedge[ci][l].second;
            if(x[rj]==INF){
              x[rj] = aj-y[ci];
              que.push(rj);
            }
            else if(x[rj]+y[ci]!=aj) ok=0;
          }
        }
        else{
          if(x[ri]+y[ci]!=ai) ok=0;
        }
      }
    }
  }

  //cout << ok << endl;
  //for(int i=1; i<=R; i++) cout << x[i] << " ";
  //cout<<endl;
  //for(int i=1; i<=C; i++) cout << y[i] << " ";
  //cout<<endl;

  int xdone[RCmax];
  int ydone[RCmax];
  for(int i=1; i<=R; i++) xdone[i] = 0;
  for(int i=1; i<=R; i++) ydone[i] = 0;

  for(int i=0; i<=R; i++){
    if(xdone[i]) continue;
    long long xmin=x[i], ymin=INF;
    queue<int> que;
    xdone[i] = 1;
    que.push(i);
    while(!que.empty()){
      int ri = que.front(); que.pop();
      for(int j=0; j<xedge[ri].size(); j++){
        int ci = xedge[ri][j].first;
        if(ydone[ci] > 0) continue;
        ydone[ci] = 1;
        ymin = y[ci] < ymin ? y[ci] : ymin;
        for(int k=0; k<yedge[ci].size(); k++){
          int rj = yedge[ci][k].first;
          if(xdone[rj] > 0) continue;
          xdone[rj] = 1;
          xmin = x[rj] < xmin ? x[rj] : xmin;
          que.push(rj);
        }
      }
    }
    if(xmin+ymin<0) ok=0;
  }

  if(ok) cout << "Yes" << endl;
  else cout << "No" << endl;

  return 0;
}

