			ll s = i.second + m[j];
			pair<int, int> a, b;
			a = MP(p.first+1, p.second);
			b = MP(p.first, p.second-1);
			if (!m.count(a) && !m.count(b)) {
				sum[a].PB(MP(b, s));
				sum[b].PB(MP(a, s));
				td.insert(a), td.insert(b);
			}
		}
		if (m.count(MP(p.first+1, p.second+1))) {
			auto j = MP(p.first+1, p.second+1);
			ll s = i.second + m[j];
			pair<int, int> a, b;
			a = MP(p.first+1, p.second);
			b = MP(p.first, p.second+1);
			if (!m.count(a) && !m.count(b)) {
				sum[a].PB(MP(b, s));
				sum[b].PB(MP(a, s));
				td.insert(a), td.insert(b);
			}
		}
		if (m.count(MP(p.first+1, p.second))) {
			auto j = MP(p.first+1, p.second);
			pair<int, int> a, b;
			a = MP(p.first, p.second+1);
			b = MP(p.first+1, p.second+1);
			if (!m.count(a) && !m.count(b)) {
				nex[a].PB(MP(b, m[j] - i.second));
				nex[b].PB(MP(a, i.second - m[j]));
				td.insert(a), td.insert(b);
			}
			a = MP(p.first, p.second-1);
			b = MP(p.first+1, p.second-1);
			if (!m.count(a) && !m.count(b)) {
				nex[a].PB(MP(b, m[j] - i.second));
				nex[b].PB(MP(a, i.second - m[j]));
				td.insert(a), td.insert(b);
			}
		}
		if (m.count(MP(p.first, p.second+1))) {
			auto j = MP(p.first, p.second+1);
			pair<int, int> a, b;
			a = MP(p.first+1, p.second);
			b = MP(p.first+1, p.second+1);
			if (!m.count(a) && !m.count(b)) {
				nex[a].PB(MP(b, m[j] - i.second));
				nex[b].PB(MP(a, i.second - m[j]));
				td.insert(a), td.insert(b);
			}
			a = MP(p.first-1, p.second);
			b = MP(p.first-1, p.second+1);
			if (!m.count(a) && !m.count(b)) {
				nex[a].PB(MP(b, m[j] - i.second));
				nex[b].PB(MP(a, i.second - m[j]));
				td.insert(a), td.insert(b);
			}
		}
