typedef pair<int, int> PII;

const int MAXN = 1E5 + 10;

int R, C, n;
vector<PII> E[MAXN << 1];
int val[MAXN << 1];
bool vis[MAXN << 1];
bool flag = true;
int m[2];

void DFS(int u, int type){
	vis[u] = true;
	m[type] = min(m[type], val[u]);
	for (int v, i = 0; i < E[u].size(); ++i){
		if (vis[v = E[u][i].st]){
			flag &= val[u] + val[v] == E[u][i].nd;
			continue;
		}
		val[v] = E[u][i].nd - val[u];
		DFS(v, !type);
	}
}

