		scanf("%d%d%d", &u, &v, &w);
		v += R;
		E[u].push_back(PII(v, w));
		E[v].push_back(PII(u, w));
	}

	for (int i = 1; flag && i <= R + C; ++i)
		if (!vis[i]){
			val[i] = 0;
			m[0] = m[1] = INT_MAX;
			DFS(i, 0);
			flag &= m[0] + m[1] >= 0;
		}
	puts(flag ? "Yes" : "No");

	return 0;
}

