		rela[i] = i;
		delta[i] = 0;
		sgn[i] = 1;
		v[i] = -1;
	}
	for(int i(0); i < n; i++) {
		if(x[i] == 1 && y[i] == 1) {
			continue;
		}
		int ca(x[i] - 1), cb(r - 2 + y[i]);
		if(x[i] == 1 || y[i] == 1) {
			int cc(x[i] == 1 ? cb : ca);
			getr(cc);
			long long val(sgn[cc] * (a[i] - delta[cc]));
			if(v[rela[cc]] == -1) {
				v[rela[cc]] = val;
			}else if(val < 0 || v[rela[cc]] != val) {
				invalid = true;
				break;
			}
		}else {
			int xx(getr(ca)), yy(getr(cb));
			a[i] += a11;
			//(sgn[ca] * v[xx] + delta[ca] + sgn[cb] * v[yy] + delta[cb] = a[i]);
			if(xx == yy) {
				//(sgn[ca] + sgn[cb]) * v + delta[ca] + delta[cb] - a[i] = 0;
				long long coe(sgn[ca] + sgn[cb]);
				if(v[xx] != -1) {
					if(coe * v[xx] + delta[ca] + delta[cb] != a[i]) {
						invalid = true;
						break;
					}
				}else {
					if(coe == 0) {
						if(delta[ca] + delta[cb] - a[i] != 0) {
							invalid = true;
							break;
						}
					}else {
						if((delta[ca] + delta[cb] - a[i]) % 2 != 0) {
							invalid = true;
						}
						long long val(a[i] - delta[ca] - delta[cb]);
						val /= coe;
						if(val < 0) {
							invalid = true;
							break;
						}else {
							v[xx] = val;
						}
					}
				}
			}else {
				//v[yy] = sgn[cb] * (-sgn[ca] * v[xx] - delta[ca] - delta[cb] + a[i])

				//rela[yy] = xx;
				long long newsgn = sgn[cb] * sgn[ca] * -1;
				long long newdelta = sgn[cb] * (-delta[ca] - delta[cb] + a[i]);
				rela[yy] = xx;
				sgn[yy] = newsgn;
				delta[yy] = newdelta;
				if(v[yy] != -1) {
					if(v[xx] != -1) {
						if(v[xx] * sgn[yy] + delta[yy] != v[yy]) {
							invalid = true;
							break;
						}
					}else {
						v[xx] = (v[yy] - delta[yy]) * sgn[yy];
						if(v[xx] < 0) {
							invalid = true;
							break;
						}
					}
				}
			}
		}
	}
	for(int i(1); i <= r + c - 2; i++) {
		if(rela[i] == i) {
			if(v[i] == -1) {
				le[i] = 0;
				ri[i] = 1e18;
			}else {
				le[i] = ri[i] = v[i];
			}
		}
	}
	for(int i(1); i <= r + c - 2; i++) {
		getr(i);
		//printf("%lld %lld %lld %lld\n", rela[i], sgn[i], delta[i], v[i]);
		if(sgn[i] > 0) {
			le[rela[i]] = max(le[rela[i]], -delta[i]);
		}else {
			ri[rela[i]] = min(ri[rela[i]], delta[i]);
		}
	}
	for(int i(1); i <= r + c - 2; i++) {
		if(le[i] > ri[i]) {
			invalid = true;
			break;
		}
	}
	long long rmn(1e18), cmn(1e18);
	for(int i(1); i <= r + c - 2; i++) {
		if(v[rela[i]] != -1) {
			long long val(sgn[i] * v[rela[i]] + delta[i]);
			//printf("%d %lld\n", i, val);
			if(i <= r - 1) {
				rmn = min(rmn, val);
			}else {
				cmn = min(cmn, val);
			}
		}
	}
	//cout << rmn << ' ' << cmn << endl;
	if(rmn + cmn - a11 < 0) {
		invalid = true;
	}
	for(int i(1); i <= r + c - 2; i++) {
		/*if(rela[i] == i) {
			printf("%d %lld %lld\n", i, le[i], ri[i]);
		}*/
		if(rela[i] == i && v[i] == -1) {
			if((ri[i] - le[i]) >= rmn) {
				cmn = min(cmn, (ri[i] - le[i]) - rmn);
			}else {
				rmn = (ri[i] - le[i]) / 2;
				cmn = (ri[i] - le[i] + 1) / 2;
			}
		}
	}
	if(rmn + cmn - a11 < 0) {
		invalid = true;
	}
	cout << (invalid ? "No" : "Yes") << endl;
}

