//!  Y8.   .8P 88    88 88 88.  .88 88    88     88        88 88    88 88.  .88  !//
//!  'Y88888P' dP    dP dP '88888P' dP    dP     dP        dP dP    dP '88888P8  !//
//!==============================================================================!//
template <typename T>
class PotUnionFind
{
public:
    PotUnionFind(const std::size_t v) : V(v), parent(v), size(v, 1), potential(v, T{}) { std::iota(parent.begin(), parent.end(), 0); }
    std::size_t find(const std::size_t a)
    {
        assert(a < V);
        if (parent[a] == a) { return a; }
        const std::size_t r = find(parent[a]);
        return potential[a] += potential[parent[a]], parent[a] = r;
    }
    bool same(const std::size_t a, const std::size_t b)
    {
        assert(a < V), assert(b < V);
        return find(a) == find(b);
    }
    void unite(std::size_t a, std::size_t b, T w)
    {
        assert(a < V), assert(b < V);
        w += getPotential(a), w -= getPotential(b);
        a = find(a), b = find(b);
        if (a == b) { return; }
        if (size[a] < size[b]) { std::swap(a, b), w = -w; }
        size[a] += size[b], parent[b] = a, potential[b] = w;
    }
    std::size_t getSize(const std::size_t a) { return assert(a < V), size[find(a)]; }
    T getPotential(const std::size_t a) { return assert(a < V), find(a), potential[a]; }
    T diff(const std::size_t a, const std::size_t b) { return assert(a < V), assert(b < V), assert(same(a, b)), potential[b] - potential[a]; }
    friend std::ostream& operator<<(std::ostream& os, const PotUnionFind& uf)
    {
        os << "[";
        for (std::size_t i = 0; i < uf.parent.size(); i++) { os << uf.parent[i] << (i + 1 == uf.parent.size() ? "" : ","); }
        return (os << "]\n");
    }

private:
    const std::size_t V;
    std::vector<std::size_t> parent, size;
    std::vector<T> potential;
};
