    std::vector<int> r(N), c(N);
    std::vector<ll> a(N);
    for (int i = 0; i < N; i++) {
        std::cin >> r[i] >> c[i] >> a[i], r[i]--, c[i]--;
        cs[r[i]].push_back({c[i], a[i]}), rs[c[i]].push_back({r[i], a[i]});
    }
    for (int r = 0; r < R; r++) { std::sort(cs[r].begin(), cs[r].end()); }
    for (int c = 0; c < C; c++) { std::sort(rs[c].begin(), rs[c].end()); }
    PotUnionFind<ll> ruf(R), cuf(C);
    for (int r = 0; r < R; r++) {
        for (int i = 1; i < cs[r].size(); i++) {
            const P p1 = cs[r][i - 1], p2 = cs[r][i];
            const int c1 = p1.first, c2 = p2.first;
            const ll a1 = p1.second, a2 = p2.second;
            if (cuf.same(c1, c2) and cuf.diff(c1, c2) != a2 - a1) { return std::cout << "No" << std::endl, 0; }
            cuf.unite(c1, c2, a2 - a1);
        }
    }
    for (int c = 0; c < C; c++) {
        for (int i = 1; i < rs[c].size(); i++) {
            const P p1 = rs[c][i - 1], p2 = rs[c][i];
            const int r1 = p1.first, r2 = p2.first;
            const ll a1 = p1.second, a2 = p2.second;
            if (ruf.same(r1, r2) and ruf.diff(r1, r2) != a2 - a1) { return std::cout << "No" << std::endl, 0; }
            ruf.unite(r1, r2, a2 - a1);
        }
    }
    std::vector<bool> used(C, false);
    std::vector<std::vector<int>> rc(R), cc(C);
    for (int r = 0; r < R; r++) {
        rc[ruf.find(r)].push_back(r);
    }
    for (int c = 0; c < C; c++) {
        cc[cuf.find(c)].push_back(c);
    }
    for (int i = 0; i < N; i++) {
        if (used[cuf.find(c[i])]) { continue; }
        used[cuf.find(c[i])] = true;
        ll cmin = 0, rmin = 0;
        for (std::size_t nc : cc[cuf.find(c[i])]) { chmin(cmin, cuf.diff(c[i], nc)); }
        for (std::size_t nr : rc[ruf.find(r[i])]) { chmin(rmin, ruf.diff(r[i], nr)); }
        const ll min = a[i] = cmin + rmin;
        if (min < 0) { return std::cout << "No" << std::endl, 0; }
    }
    std::cout << "Yes" << std::endl;
    return 0;
}

