void add(int l,int r,ll v,int a,int b,int k){
  if(r<=a || b<=l)return;
  if(l<=a && b<=r){
    sum[k] += v;
    seg[k] += v;
  }else{
    int m = (a+b)/2;
    add(l,r,v,a,m,2*k+1);
    add(l,r,v,m,b,2*k+2);
    seg[k] = min(seg[2*k+1],seg[2*k+2])+sum[k];
  }
}
