  it = 0;
  for(const int& y:Sy){
    My[y] = it++;
  }
  c = it;

  REP(i,n){
    int x,y;
    x=Mx[ps[i].first];
    y=My[ps[i].second];
    xs[y].push_back(x);
    ys[x].push_back(y);
    ps[i] = pii(x,y);
    rev[ps[i]] = i;
  }
  // graph
  REP(i,125252)g[i].clear();
  REP(i,r){
    sort(ALL(ys[i]));
    vi &vec = ys[i];
    REP(j,vec.size()-1){
      int s,t;
