      ll sa = val[tid]-val[sid];
      g[s].push_back(pll(t,sa));
      g[t].push_back(pll(s,-sa));
    }
  }
  if(!valid(r,true)){
    puts("No");
    return 0;
  }
  // graph
  REP(i,125252)g[i].clear();
  REP(i,c){
    sort(ALL(xs[i]));
    vi &vec = xs[i];
    REP(j,vec.size()-1){
      int s,t;
      s = vec[j];
      t = vec[j+1];
      int sid = rev[pii(s,i)];
      int tid = rev[pii(t,i)];
      ll sa = val[tid]-val[sid];
      g[s].push_back(pll(t,sa));
      g[t].push_back(pll(s,-sa));
    }
  }
  if(!valid(c,false)){
    puts("No");
    return 0;
  }
  // ok
  puts("Yes");
  return 0;
}

