bool dfs(int st,LL sum)
{
	if(vis[st]) return num[st]==sum;
	if(st<=r) minr=mi(minr,sum);
	else minc=mi(minc,sum);
	vis[st]=1; num[st]=sum;
	for(RG int i=head[st];i;i=e[i].next) if(!dfs(e[i].to,e[i].dis-sum)) return 0;
	return 1;
}
