		c_r[c].emplace_back(r);
		if (i == 0) startR = r;
	}

	std::vector<bool> checkedR(R), checkedC(C);
	std::function<bool(int, int)> dfs = [&](int r, int c) {
		bool flag = true;
		if (c == -1) {
			for (const auto& _c : r_c[r]) {
				if (checkedC[_c]) {
					if (row[r] + col[_c] != a[r][_c]) flag = false;
				}
				else {
					checkedC[_c] = true;
					col[_c] = a[r][_c] - row[r];
					flag &= dfs(-1, _c);
				}
			}
		}
		else {
			for (const auto& _r : c_r[c]) {
				if (checkedR[_r]) {
					if (col[c] + row[_r] != a[_r][c]) flag = false;
				}
				else {
					checkedR[_r] = true;
					row[_r] = a[_r][c] - col[c];
					flag &= dfs(_r, -1);
				}
			}
		}
		return flag;
	};
	row[startR] = 0;
	checkedR[startR] = true;
	if (!dfs(startR, -1)) {
		OUT("No")BR;
		return 0;
	}
	for (const auto& r : r_c) {
		for (const auto& c : r.second) {
			if (row[r.first] + col[c] != a[r.first][c]) {
				OUT("No")BR;
				return 0;
			}
		}
	}
	if(*std::min_element(ALL(row)) + *std::min_element(ALL(col)) < 0) {
		OUT("No")BR;
	}
	else {
		OUT("Yes")BR;
	}
	return 0;
}

