#define makp make_pair
#define fi first
#define se second
map<int, map<int, int> > mp;
map<int, map<int, bool> > vis, inq;
int x[100005], y[100005];
queue<pair<int, int> > q;

bool ceek(int x1, int y1, int x2, int y2, int x3, int y3, int x4, int y4)
{
  if(mp[x1][y1]!=0 && mp[x2][y2]!=0 && mp[x4][y4]!=0)
  {
     int sum=mp[x4][y4]+mp[x1][y1];
     //if(sum==52) printf("%d %d %d %d %d %d %d %d\n", x1, y1, x2, y2, x3, y3, x4, y4);
     if(mp[x3][y3]!=0)
     {
       if(mp[x3][y3]+mp[x2][y2] != sum) { return false; }
     }
     else
     {
        int res=sum-mp[x2][y2];
        if(res<0) return false;
        mp[x3][y3]=res;
     }
     if(!inq[x1][y1] && !vis[x1][y1]) { inq[x1][y1]=true; q.push(makp(x1,y1)); }
     if(!inq[x2][y2] && !vis[x2][y2]) { inq[x2][y2]=true; q.push(makp(x2,y2)); }
     if(!inq[x3][y3] && !vis[x3][y3]) { inq[x3][y3]=true; q.push(makp(x3,y3)); }
     if(!inq[x4][y4] && !vis[x4][y4]) { inq[x4][y4]=true; q.push(makp(x4,y4)); }
  }
  return true;
}

bool cek(int i, int j)
{
   int x1, y1, x2, y2, x3, y3;
   //kuadran 1
   x1=i-1, y1=j-1, x2=i-1, y2=j, x3=i, y3=j-1;
   if(!ceek(x1,y1,x2,y2,x3,y3,i,j)) return false;
   swap(x2,x3); swap(y2,y3);
   if(!ceek(x1,y1,x2,y2,x3,y3,i,j)) return false;
   if(!ceek(x3,y3,i,j,x1,y1,x2,y2)) return false;

   //kuadran 2
   x1=i-1, y1=j, x2=i-1, y2=j+1, x3=i, y3=j+1;
   if(!ceek(i,j,x3,y3,x1,y1,x2,y2)) return false;
   if(!ceek(x1,y1,i,j,x2,y2,x3,y3)) return false;
   if(!ceek(i,j,x1,y1,x3,y3,x2,y2)) return false;

   //kuadran 3
   x1=i+1, y1=j-1, x2=i+1, y2=j, x3=i, y3=j-1;
   if(!ceek(i,j,x2,y2,x3,y3,x1,y1)) return false;
   if(!ceek(x2,y2,i,j,x1,y1,x3,y3)) return false;
   if(!ceek(x1,y1,x3,y3,x2,y2,i,j)) return false;

   //kuadran 4
   x1=i+1, y1=j, x2=i+1, y2=j+1, x3=i, y3=j+1;
   if(!ceek(i,j,x3,y3,x1,y1,x2,y2)) return false;
   if(!ceek(x1,y1,i,j,x2,y2,x3,y3)) return false;
   if(!ceek(x2,y2,x1,y1,x3,y3,i,j)) return false;
   return true;
}

int main()
{
   int r, c, n; scanf("%d%d%d", &r, &c, &n);
   for(int i=0;i<n;i++)
   {
      int a; scanf("%d%d%d", &x[i], &y[i], &a);
      mp[x[i]][y[i]]=a+1;
   }

   bool ans=true;
   for(int i=0;i<n && ans;i++)
   {
      if(vis[x[i]][y[i]]) continue;
      while(!q.empty()) q.pop();
      inq.clear();
      q.push(makp(x[i],y[i])); inq[x[i]][y[i]]=true;
      while(!q.empty())
      {
         int curi=q.front().fi, curj=q.front().se; q.pop(); inq[curi][curj]=false;
         vis[curi][curj]=true;
         //printf("%d %d\n", curi, curj);
         if(!cek(curi,curj)) { ans=false; break; }
      }
   }
   if(ans) printf("Yes\n");
   else printf("No\n");
   return 0;
}

