#include <stdio.h>
#include <algorithm>
#include <iostream>
using namespace std;
const int max0=200100;
struct branch{
    int x,y,a;
}data[max0],mapx[2*max0];
int min0[max0],truemin[max0];
int top0,top1,delta;
bool R=1;
bool v[max0];
int dpt[max0];
int cl[max0],cc;
int bg[max0];
int bfs[max0],top2,btt;
int r,c,n,i;
bool cmp(branch a,branch b){
    if(a.x<b.x)return 1;
    if(a.x>b.x)return 0;
    if(a.y<b.y)return 1;
    if(a.y>b.y)return 0;

    //if(a.a!=b.a)R=0;
    if(a.a<b.a)return 1;
    if(a.a>b.a)return 0;
    return 0;
}
int main(){
    scanf("%d%d%d",&r,&c,&n);
    for(i=0;i<n;i++){
        scanf("%d%d%d",&data[top0].x,&data[top0].y,&data[top0].a);
        top0++;
    }
    for(i=1;i<=c;i++)min0[i]=-1;
    sort(data,data+top0,cmp);
    top1=1;
    if(R){
        for(i=0;i<n;i++)
            if(min0[data[i].y]==-1||data[i].a<min0[data[i].y])
                min0[data[i].y]=data[i].a;
        for(i=1;i<n;i++)
            if(R&&data[i].x==data[i-1].x){
                mapx[top1].x=data[i-1].y;
                mapx[top1].y=data[i].y;
                delta=data[i].a-data[i-1].a;
                mapx[top1].a=delta;
                top1++;
                mapx[top1].x=data[i].y;
                mapx[top1].y=data[i-1].y;
                mapx[top1].a=-delta;
                top1++;
            }
    }
    if(R){
        sort(mapx+1,mapx+top1,cmp);
        for(i=1;i<top1;i++)
            if(bg[mapx[i].x]==0)bg[mapx[i].x]=i;
        for(i=1;R&&i<=c;i++)
            if(!v[i]){
                cc=i;cl[i]=cc;
                v[i]=1;bfs[top2++]=i;
                while(R&&btt<top2){
                    for(int j=bg[bfs[btt]];j<top1&&mapx[j].x==bfs[btt];j++){
                        if(v[mapx[j].y]){
                            if(dpt[mapx[j].y]-dpt[mapx[j].x]!=mapx[j].a)R=0;
                        }
                        else{
                            v[mapx[j].y]=1;
                            cl[mapx[j].y]=cc;
                            bfs[top2++]=mapx[j].y;
                            dpt[mapx[j].y]=dpt[mapx[j].x]+mapx[j].a;

                            if(dpt[mapx[j].y]<truemin[cc])
                                truemin[cc]=dpt[mapx[j].y];
                        }
                    }
                    btt++;
