const long long INF=10000000000ll;

int main()
{
  int R,C,n;
  scanf("%d%d%d",&R,&C,&n);
  vector<vector<int> > e(R+C);
  vector<vector<long long> > v(R+C);
  for(int i=0;i<n;i++){
    int a,b;
    long long c;
    scanf("%d%d%lld",&a,&b,&c);
    a--;
    b--;
    e[a].push_back(R+b);
    v[a].push_back(c);
    e[R+b].push_back(a);
    v[R+b].push_back(c);
  }
  bool F=1;
  static bool vis[200000]={0};
  static long long X[200000]={0};
  for(int s=0;s<R+C&&F;s++){
    if(vis[s]){
      continue;
    }
    vis[s]=1;
    X[s]=0;
    queue<int> Q;
    Q.push(s);
    long long P1=INF,P2=INF;
    while(!Q.empty()&&F){
      int i=Q.front();
      //printf("%d %lld\n",i,X[i]);
      Q.pop();
      if(i<R){
	P1=min(P1,X[i]);
      }
      else{
	P2=min(P2,X[i]);
      }
      for(int x=0;x<e[i].size();x++){
	int j=e[i][x];
	long long c=v[i][x];
	if(!vis[j]){
	  vis[j]=1;
	  X[j]=c-X[i];
	  Q.push(j);
	}
	else if(X[i]+X[j]!=c){
	  F=0;
	  break;
	}
      }
    }
    //printf("%d %lld %lld\n",s,P1,P2);
    if(P1+P2<0){
      F=0;
    }
  }
  puts(F?"Yes":"No");
  return 0;
}

