    bool all = true;
    int  sum = masu[pos];
    REP(k, 3) {
      int sr = dr[k] + get<0>(pos);
      int sc = dc[k] + get<1>(pos);
      if (sr <= 0 || sr > R || sc <= 0 || sc > C) { all = false; break; }
      if (!masu.count(tii(sr, sc))) { all = false; break; }
      if (k != 2) sum += masu[tii(sr, sc)];
      else        sum -= masu[tii(sr, sc)];
    }

