#define FOR(i,a,b) for(int i=a; i<=b; ++i)
#define FORR(i,a,b) for (int i=a; i>=b; --i)
#define ALL(c) (c).begin(), (c).end()

typedef long long ll;
typedef vector<int> VI;
typedef vector<ll> VL;
typedef vector<VI> VVI;
typedef vector<VL> VVL;
typedef pair<int,int> P;
typedef pair<ll,ll> PL;

const ll INF = 1e18;
const int N = 1e5;
ll a[N], b[N], mia, mib;
VI ea[N], eb[N];
VL sa[N], sb[N];

void dfsb(int);

void dfsa(int now){
    mia = min(mia, a[now]);
    REP(i,ea[now].size()){
        int next = ea[now][i];
        ll sum = sa[now][i];
        if (b[next] < INF) continue;
        b[next] = sum - a[now];
        dfsb(next);
    }
}

void dfsb(int now){
    mib = min(mib, b[now]);
    REP(i,eb[now].size()){
        int next = eb[now][i];
        ll sum = sb[now][i];
        if (a[next] < INF) continue;
        a[next] = sum - b[now];
        dfsa(next);
    }
}

int main(){
    int r, c, n;
    cin >> r >> c >> n;

    fill(a, a+r, INF);
    fill(b, b+c, INF);

    VI x(n), y(n), s(n);

    REP(i,n){
        int rr, cc, ss;
        scanf("%d %d %d", &rr, &cc, &ss);
        rr--;
        cc--;
        x[i] = rr;
        y[i] = cc;
        s[i] = ss;
        ea[rr].push_back(cc);
        sa[rr].push_back(ss);
        eb[cc].push_back(rr);
        sb[cc].push_back(ss);
    }

    REP(i,n){
        if (a[x[i]] < INF) continue;
        a[x[i]] = 0;
        mia = mib = INF;
        dfsa(x[i]);
        if (mia + mib < 0){
            cout << "No" << endl;
            return 0;
        }
    }

    REP(i,n){
        if (a[x[i]] + b[y[i]] != s[i]){
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
struct node{
	int x,y;
}a[100001];
queue<node> q;
bool vis[501][501],ok;
int value[501][501];
int T,R,C,n,xi,yi,data;
int main(){
	scanf("%d",&T);
	while(T--){
		scanf("%d%d%d",&R,&C,&n);ok=true;
		memset(vis,0,sizeof(vis));
		memset(value,0,sizeof(value));
		while(!q.empty()) q.pop();
		for(int i=1;i<=n;i++){
			scanf("%d%d%d",&xi,&yi,&data);
			a[i].x=xi;a[i].y=yi;
			value[xi][yi]=data;
			vis[xi][yi]=true;
			if(data<0)ok=false;
		}
		if(!ok){
			printf("No\n");
			continue;
		}
		for(int i=1;i<=n;i++) q.push(a[i]);
		while(!q.empty()){
			node now=q.front();q.pop();
			for(int i=1;i<=R;i++) if(i!=now.x&&vis[i][now.y])
			for(int j=1;j<=C;j++) if(j!=now.y&&vis[now.x][j])
			{
				int D=value[i][now.y]+value[now.x][j]-value[now.x][now.y],x=i,y=j;
				if(D<0){
					ok=false;
					break;
				}
				if(!vis[x][y]){
					value[x][y]=D;
					vis[x][y]=true;
					n++;a[n].x=x;a[n].y=y;
					q.push(a[n]);
				}
				else{
					if(value[x][y]!=D){
						ok=false;
						break;
					}
					else ok=true;
				}
			}
			if(!ok)break;	
		}
		if(ok) printf("Yes\n");
		else printf("No\n");
	}
}

