bool pos=true;


bool det(int fy, int fx, int sy, int sx)
{
	if(yay.find(make_pair(fy,fx))!=yay.end())
	{
		return (yay[make_pair(fy,fx)]+yay[make_pair(sy,sx)]==yay[make_pair(fy,sx)]+yay[make_pair(sy,fx)]);
	}
	else
	{
		int proj=yay[make_pair(fy,sx)]+yay[make_pair(sy,fx)]-yay[make_pair(sy,sx)];
		yay[make_pair(fy,fx)]=proj;
		return (proj>=0);
	}
}
void perf(int ro, int co)
{
	int ri, ci;
	for(ri=0 ; ri<row[ro].size() ; ri++)
	{
		for(ci=0 ; ci<col[co].size() ; ci++)
		{
			if(row[ro][ri]!=co && col[co][ci]!=ro)
			{
				bool call=det(col[co][ci],row[ro][ri],ro,co);
				if(call==false)
				{
					printf("No\n");
					exit(0);
				}
			}
		}
	}
}

int main(void)
{
