	cin>>n;
	for(i=1 ; i<=n ; i++)
	{
		int u, v, w;
		scanf("%d %d %d",&u,&v,&w);
		row[u].push_back(v);
		col[v].push_back(u);
		yay[make_pair(u,v)]=w;
		perf(u,v);
	}
	printf("Yes\n");
	return 0;
}

