using namespace std;

typedef pair<int,int> pii;

map<pii,int> fld;

bool func(int dx[3], int dy[3], int r,int c){
	int nfc=0;
	pii nf;
	rep(i,4){
		int nx=c+dx[i];
		int ny=r+dy[i];
		//printf("nx,ny=%d-%d\n",nx,ny);
		pii np=pii(nx,ny);
		if(fld.find(np)==fld.end()){
			nfc++;
			nf = np;
		}
	}
	//printf("nfc=%d\n",nfc);
	if(nfc==1){
		int s1 = fld[pii(c+dx[0],r+dy[0])] + fld[pii(c+dx[1],r+dy[1])];
		int s2 = fld[pii(c+dx[2],r+dy[2])] + fld[pii(c+dx[3],r+dy[3])];
		fld[nf] = abs(s1-s2);
	}

	if(nfc<=1){
		int s1 = fld[pii(c+dx[0],r+dy[0])] + fld[pii(c+dx[1],r+dy[1])];
		int s2 = fld[pii(c+dx[2],r+dy[2])] + fld[pii(c+dx[3],r+dy[3])];
		//printf("(%d,%d)\n",s1,s2);
		if(s1 != s2){
			return false;
		}
	}
	return true;
}

int main(){
	int R,C;
	cin >> R >> C;
	int N;
	cin >> N;

	bool flg=true;
	rep(i,N){
		int r,c,a;
		scanf("%d %d %d",&r, &c, &a);
		fld[pii(c,r)] = a;
		if(r!=1&&c!=1){
			int dy[]={-1,0,0,-1};
			int dx[]={-1,0,-1,0};
			if(!func(dx,dy,r,c)){
				flg=false;
			}
		}
		if(r!=1 && c!=C){
			int dy[]={0,-1,-1,0};
			int dx[]={0,1,0,1};
			if(!func(dx,dy,r,c)){
				flg=false;
			}
		}
		if(r!=R && c!=1){
			int dr[]={0,1,0,1};
			int dc[]={0,-1,-1,0};
			if(!func(dc,dr,r,c)){
				flg=false;
			}
		}
		if(r!=R && c!=C){
			int dy[]={0,1,1,0};
			int dx[]={0,1,0,1};
			if(!func(dx,dy,r,c)){
				flg=false;
			}
		}
		//cout << flg << "---" << i << endl;
	}

	if(R*C==N || !flg){
		cout << "No" << endl;
	}else{
		cout << "YES" << endl;
	}
}

