int dx[] = {1,0,-1,0};
int dy[] = {0,-1,0,1};


struct Edge {
	ll t;
	ll c;
	Edge(ll to, ll cost):t(to),c(cost){}
	Edge(){}
};

vector<ll> weigh;
ll R, C;

bool DFS(ll node, vector<vector<Edge> >& edge, ll& xmin, ll& ymin) {
	for (auto &to : edge[node]) {
		if (weigh[to.t] == std::numeric_limits<ll>::max()) {
			weigh[to.t] = to.c - weigh[node];
			if (to.t < R) xmin = min(xmin, weigh[to.t]);
			else ymin = min(ymin, weigh[to.t]);
			if (not DFS(to.t, edge, xmin, ymin)) return false;
		}
		else {
			if (weigh[to.t] + weigh[node] != to.c) return false;
		}
	}
	return true;
}

void solve() {
	cin >> R >> C;
	ll N = in();
	weigh.resize(R + C, numeric_limits<ll>::max());
	vector<vector<Edge> > edge(R+C);
	REP(i, N) {
		ll r, c, a; cin >> r >> c >> a;
		--r; --c;
		edge[r].emplace_back(R+c,a);
		edge[R+c].emplace_back(r, a);
	}

	bool res = true;
	ll xmin, ymin;
	REP(i, R + C) if (weigh[i] == numeric_limits<ll>::max() and edge[i].size() > 0) {
		xmin = ymin = numeric_limits<ll>::max();
		weigh[i] = 0;
		if ((not DFS(i, edge, xmin, ymin))) {
			cout << "No" << endl;
			return;
		}
		if (xmin + ymin > 0) {
			cout << "No" << endl;
			return;
		}
	}
	cout << "Yes" << endl;

}

