	double m[r][c];
	for (int i = 0; i < r; ++i)
	{
		for (int j = 0; j < c; ++j)
		{
			m[i][j] = -1;
		}
	}

	int N;
	cin >> N;
	for (int k = 0; k < N; ++k)
	{
		int ri, ci;
		double ai;
		cin >> ri >> ci >> ai;
		m[ri-1][ci-1] = ai;
	}

	bool ok = false;
	bool wasAZero = false;
	while(!ok)
	{
		for (int i = 0; i < r - 1; ++i)
		{
			for (int j = 0; j < c - 1; ++j)
			{
				int numEmpty = (int) (m[i][j] == -1) +
						(int) (m[i + 1][j] == -1) +
						(int) (m[i][j + 1] == -1) +
						(int) (m[i + 1][j + 1] == -1);
				if (numEmpty != 0)
					ok = true;
				else
					wasAZero = true;

				if(numEmpty == 2)
				{
					if(m[i][j] == -1 && m[i+1][j] == -1)
					{
						m[i][j] =  ceil((m[i+1][j+1] - m[i][j+1])/2.0);
						m[i+1][j] =  floor((m[i+1][j+1] - m[i][j+1])/2.0);
					}
					else if(m[i][j] == -1 && m[i][j+1] == -1)
					{
						m[i][j] =  ceil((m[i+1][j+1] - m[i+1][j])/2.0);
						m[i][j+1] =  floor((m[i+1][j+1] - m[i+1][j])/2.0);
