						m[i][j+1] =  floor((m[i][j] - m[i+1][j])/2.0);
					}
					else if(m[i][j] == -1 && m[i+1][j+1] == -1)
					{
						m[i][j] =  ceil((m[i+1][j] + m[i][j+1])/2.0);
						m[i+1][j+1] =  floor((m[i+1][j] + m[i][j+1])/2.0);
					}
					else if(m[i][j+1] == -1 && m[i+1][j] == -1)
