						m[i+1][j] =  floor((m[i+1][j+1] + m[i][j])/2.0);
					}

					continue;
				}


				if(numEmpty == 3)
				{
					if(m[i][j] == -1 && m[i+1][j] == -1 && m[i][j+1] == -1)
					{
						m[i][j] = 0;
