bool used[N];
ll min1, min2;
ll val[N];  // 二部グラフの頂点の重み. 二次元配列にしないように工夫している


void dfs(int v){
  used[v] = 1;
  for(pil e : Graph[v]){
    int u = e.first; // 相手の頂点
    ll w = e.second - val[v]; // 相手の頂点の重み
    if(used[u]){
      if (w != val[u]){
        min2 = -INF;
        return ;
      }
      continue;
    }
    val[u] = w;
    // 二部グラフのどちらの側かを判定する
    if(u < n){
      min1 = min(min1, w);
    }else{
      min2 = min(min2, w);
    }

    dfs(u);
  }
  return ;
}
int main(){
  int k;
  scanf("%d%d%d", &n, &m, &k);
