    int v, u;
    ll x;
    scanf("%d%d%lld", &v, &u, &x);
    // 0インデックスにする
    v--;
    u--;
    // 1次元配列で表現するための工夫
    u += n;
    Graph[v].push_back(make_pair(u, x));
    Graph[u].push_back(make_pair(v, x));
  }

  for(int i = 0; i < n; ++i){
    if (used[i]) continue;
    min1 = 0;
    min2 = INF;
    val[i] = 0;
    dfs(i);
    if(min1 + min2 < 0){
      printf("No\n");
      return 0;
    }
  }
  printf("Yes\n");

  return 0;
}

