using namespace std;

int main() {
    int R, C, N; cin >> R >> C >> N;
    int X[N], Y[N], A[N];
    vector<int> px[R], py[C];
    for (int i = 0; i < N; i++) {
        cin >> X[i] >> Y[i] >> A[i];
        X[i]--;
        Y[i]--;
        px[X[i]].push_back(i);
        py[Y[i]].push_back(i);
    }
    vector<int> adj[N];
    for (int x = 0; x < R; x++) {
        for (int i = 1; i < px[x].size(); i++) {
            adj[px[x][0]].push_back(px[x][i]);
            adj[px[x][i]].push_back(px[x][0]);
        }
    }
    for (int y = 0; y < C; y++)
        for (int i = 1; i < py[y].size(); i++) {
            adj[py[y][0]].push_back(py[y][i]);
            adj[py[y][i]].push_back(py[y][0]);
        }
    vector<bool> visited(N, false);
    vector<long long> b(R, -1), c(C, -1);
    function<void(int, vector<int>&)> dfs = [&](int i, vector<int> &nodes) {
        visited[i] = true;
        nodes.push_back(i);
        int x = X[i], y = Y[i], a = A[i];
        if (b[x] == -1) {
            if (c[y] == -1) { b[x] = a; c[y] = 0; }
            else b[x] = a - c[y];
        } else {
            if (c[y] == -1) c[y] = a - b[x];
            else if (a != b[x] + c[y]) {
                cout << "No\n";
                exit(0);
            }
        }
        for (int j : adj[i])
            if (!visited[j]) dfs(j, nodes);
    };

    for (int i = 0; i < N; i++) {
        if (!visited[i]) {
            vector<int> nodes;
            dfs(i, nodes);
            long long bmin = 1LL<<60, cmin = 1LL<<60;
            for (int j : nodes) {
                assert (b[X[j]] + c[Y[j]] == A[j]);
                bmin = min(bmin, b[X[j]]);
                cmin = min(cmin, c[Y[j]]);
            }
            if (bmin + cmin < 0) { cout << "No\n"; return 0; }
        }
    }
    cout << "Yes\n";
}

