#define FOR(i,a,b) for(int i=(a);i<(b);i++)
#define REP(i,a) FOR(i,0,a)

typedef long long ll;
typedef pair<int,ll> P;

const int MAX_R=1e5,MAX_C=1e5,MAX_N=1e5;
const ll INF=1e12;

int R,C;
int N;

vector<P> G[MAX_R+MAX_C];
bool flg[MAX_R+MAX_C];
ll val[MAX_R+MAX_C];

void dfs(int v){
	REP(i,(int)G[v].size()){
		P e=G[v][i];
		if (!flg[e.first]){
			val[e.first]=e.second-val[v];
			flg[e.first]=true;
			dfs(e.first);
		}
	}
}

void dfs2(int v,ll &x,ll &y){
	if (v<R){
		x=min(x,val[v]);
	}else{
		y=min(y,val[v]);
	}
	REP(i,(int)G[v].size()){
		P e=G[v][i];
		if (!flg[e.first]){
			flg[e.first]=true;
			dfs2(e.first,x,y);
		}
	}
}

void solve(){
	REP(i,R+C){
		if (flg[i]){
			continue;
		}
		flg[i]=true;
		val[i]=0;
		dfs(i);
	}
	//矛盾が起きてないかチェック
	REP(i,R+C){
		REP(j,(int)G[i].size()){
			P e=G[i][j];
			if (val[i]+val[e.first]!=e.second){
				printf("No\n");
				return;
			}
		}
	}
	//全てのvalを0以上にできるか
	memset(flg,false,sizeof(flg));
	REP(i,R+C){
		if (!flg[i]){
			ll x,y;
			x=y=INF;
			flg[i]=true;
			dfs2(i,x,y);
			if (x+y<0){
				printf("No\n");
				return;
			}
		}
	}
	printf("Yes\n");
}

int main(){
	scanf("%d %d",&R,&C);
	scanf("%d",&N);
	REP(i,N){
		int r,c,a;
		scanf("%d %d %d",&r,&c,&a);
		r--;
		c--;
		G[r].push_back(P(R+c,a));
		G[R+c].push_back(P(r,a));
	}
	solve();
	return 0;
}

