	for (int i = 0; i < R; ++i) if (vals[i].size() >= 2) {
		for (int j = 1; j < vals[i].size(); ++j) {
			row[vals[i][0].first].push_back({ vals[i][1].first, vals[i][1].second - vals[i][0].second });
