#define REP(i,n) for(int i=0;i<(int)(n);i++)
#define ALL(x) (x).begin(), (x).end()

typedef long long ll;

const ll INF = 1e10;

struct Edge {
  ll src, dst, cst;
  Edge(ll _src, ll _dst, ll _cst) : src(_src), dst(_dst), cst(_cst) { ; }
};

typedef vector<vector<Edge>> Graph;

bool solve(Graph &g, ll R, ll C) {
  vector<ll> Y(R, INF), X(C, INF);
  REP(i,R) {
    if(Y[i] != INF) continue;
    Y[i] = 0;
    queue<Edge> que;
    que.push(Edge(-1, i, 0));
    while(!que.empty()) {
      Edge e = que.front();
      que.pop();
      for(Edge f : g[e.dst]) {
        if(f.dst < R) {
          if(Y[f.dst] != INF && Y[f.dst] != f.cst - X[f.src - R]){
            return false;
          }
          if(Y[f.dst] == INF){
            Y[f.dst] = f.cst - X[f.src - R];
            que.push(f);
          }
        }else {
          if(X[f.dst - R] != INF && X[f.dst - R] != f.cst - Y[f.src]) {
            return false;
          }
          if(X[f.dst - R] == INF){
            X[f.dst - R] = f.cst - Y[f.src];
            que.push(f);
          }
        }
      }
    }
  }

  ll Ymin = INF, Xmin = INF;
  REP(i,R) Ymin = min(Ymin, Y[i]);
  REP(i,C) Xmin = min(Xmin, X[i]);
  if(Ymin + Xmin >= 0) return true;
  else return false;
}

int main(){
  ll R, C, N;
  cin >> R >> C >> N;
  vector<ll> r(N), c(N), a(N);
  REP(i,N){
    cin >> r[i] >> c[i] >> a[i];
    --r[i]; --c[i];
  }

  Graph g(R + C);
  REP(i,N) {
    g[r[i]].push_back(Edge(r[i], R + c[i], a[i]));
    g[R + c[i]].push_back(Edge(R + c[i], r[i], a[i]));
  }

  if(solve(g, R, C)) cout << "Yes" << endl;
  else cout << "No" << endl;
  return 0;
}

