int dx[] = {1, 0, 0, -1};
int dy[] = {0, 1, -1, 0};

const int N = 1e5;

#define uniq(v) sort(begin(v), end(v)), (v).erase(unique(begin(v), end(v)), end(v))

ll h, w, n;
map<ll, ll> eca[4];
using P = pair<ll, ll>;
set<P> ps;
map<P, ll> val;
ll yy[N], xx[N];
int sol() {
  ios::sync_with_stdio(false), cin.tie(0);
  cin >> h >> w >> n;
  for(int i = 0; i < n; i++) {
    ll y, x, t;
    cin >> y >> x >> t;
    y--; x--; yy[i] = y; xx[i] = x;
    ps.emplace(y, x);
    val[P(y, x)] = t;
  }
  for(int i = 0; i < n; i++) {
    ll y = yy[i], x = xx[i];
    for(int d = 0; d < 4; d++) {
      ll ny = y + dy[d];
      ll nx = x + dx[d];
      if(ny < 0 || nx < 0 || ny >= h || nx >= w) continue;
      if(!ps.count(P(ny, nx))) continue;
      ll place = dy[d] ? y : x;
      eca[d][place] = val[P(ny, nx)] - val[P(y, x)];
    }
  }
  vector<ll> ystarts;
  int last = -1;
  ll ei[N] = {};
  ll eiBias[N] = {};
  ll eiMin[N] = {};
  map<ll, int> zipy;
  int settled[N] = {};
  // y座圧
  vector<ll> ys;
  for(auto itr = eca[1].begin(); itr != eca[1].end(); itr++)
    ys.emplace_back((*itr).first), ys.emplace_back((*itr).first + 1);
  ys.emplace_back((int) 1e9 + 10);
  uniq(ys);
  {int i = 0; for(ll el : ys) zipy[el] = i++;}
  //
  for(auto itr = eca[1].begin(); itr != eca[1].end(); itr++) {
    pair<ll, ll> qina = *itr;
    dump(qina);
    ei[zipy[qina.first + 1]] = ei[zipy[qina.first]] + qina.second;
    if(last != qina.first) {
      ystarts.emplace_back(qina.first);
    }
    eiMin[ystarts.size()-1] = min(eiMin[ystarts.size() - 1], ei[zipy[qina.first + 1]]);
    last = qina.first + 1;
  }
  dump(3);
  ystarts.emplace_back((int) 1e9 + 10); // sentinel
  vector<int> ord(n);
  iota(begin(ord), end(ord), 0);
  sort(begin(ord), end(ord), [&](int a, int b) {
      return xx[a] < xx[b];
      });
  // 平面走査
  ll bias = 0;
  dump(2);
  bool settleBias = 0;
  dump(ystarts);
  int nowx = 1;
  for(int i = 0; i < n; i++) {
    ll y = yy[ord[i]], x = xx[ord[i]];
    int p = upper_bound(begin(ystarts), end(ystarts), y) - begin(ystarts) - 1;
    if(p < 0) continue;
    dump(i, p);
    if(settled[p] == nowx) {
      if(settleBias) {
        dump(1, y, x, bias, p, eiBias[p], ei[zipy[y]], val[P(y, x)]);
        if(ei[zipy[y]] + eiBias[p] + bias != val[P(y, x)]) return 0;
        if(eiMin[p] + bias + eiBias[p] < 0) return 0;
      } else {
        bias = val[P(y, x)] - ei[zipy[y]] - eiBias[p];
        settleBias = 1;
        dump(2, y, x, bias, p, eiBias[p], ei[zipy[y]], val[P(y, x)]);
        if(eiMin[p] + bias + eiBias[p] < 0) return 0;
      }
    } else {
      settled[p] = nowx;
      if(settleBias) {
      } else {
        bias = 0; // any
        settleBias = 1;
      }
      eiBias[p] = val[P(y, x)] - ei[zipy[y]] - bias;
      dump(3, y, x, bias, p, eiBias[p], ei[zipy[y]], val[P(y, x)]);
      dump(eiMin[p]);
      if(eiMin[p] + bias + eiBias[p] < 0) return 0;
    }
    if(x == xx[ord[i+1]] || eca[0].count(xx[ord[i]])) {
      if(x != xx[ord[i+1]]) {
        bias += eca[0][xx[ord[i]]];
      }
    } else {
      nowx++;
      bias = 0;
      settleBias = 0;
    }
  }
  return 1;
}

