bool check(int x, int y) {
	if (x == 0 || y == 0 || x == r || y == c)
		return true;
	if (v.count({x, y}) + v.count({x+1, y}) + v.count({x, y+1}) + v.count({x+1, y+1}) < 3)
		return true;
	int a = get(x, y), b = get(x+1, y+1), c = get(x, y+1), d = get(x+1, y);
#define GV(i) ((i)==-1?0:(i))
	if (min({a, b, c, d}) != -1)
		return a + b == c + d;

	if (a > -1 && b > -1) {
		int sum = GV(c) + GV(d);
		if (sum > a+b) return false;
		if (c == -1)
			v[{x, y+1}] = a + b - sum;
