bool check(int x,int y){
  int cnt=4;
  ll total=0;
  bool fa=false,fb=false,fc=false,fd=false;

  if( mp.count(P(x,y)) >0)cnt--,fa=true,total+=mp[ P(x,y) ];
  if( mp.count(P(x+1,y)) >0)cnt--,fb=true,total+=mp[ P(x+1,y) ];
  if( mp.count(P(x,y+1)) >0)cnt--,fc=true,total+=mp[ P(x,y+1) ];
  if( mp.count(P(x+1,y+1)) >0)cnt--,fd=true,total+=mp[ P(x+1,y+1) ];

  if(cnt==0){
    if( mp[P(x,y)]+mp[P(x+1,y+1)] == mp[P(x,y+1)]+mp[P(x+1,y)])return true;
    else return false;
  }

  if(cnt==1){
    if(fa==false){
      mp[ P(x,y) ]=total-mp[P(x+1,y+1)]*2;
      Q.push(P(x,y));

    }
    if(fb==false){
      mp[ P(x+1,y) ]=total-mp[P(x,y+1)]*2;
      Q.push(P(x+1,y));

    }
    if(fc==false){
      mp[ P(x,y+1) ]=total-mp[P(x+1,y)]*2;
      Q.push(P(x,y+1));

    }
    if(fd==false){
      mp[ P(x+1,y+1) ]=total-mp[P(x,y)]*2;
      Q.push(P(x+1,y+1));

    }

  }

  if(cnt==2){

    if(fa==true && fd==true){

      if(total==0){
        mp[ P(x,y+1) ]=0;
        Q.push(P(x,y+1));
        mp[ P(x+1,y) ]=0;
        Q.push(P(x+1,y));
      }else{
        va.push_back(P(x,y+1));
        vb.push_back(P(x+1,y));
        vc.push_back(total);
      }

    }else if(fb==true && fc==true ){

      if(total==0){
        mp[ P(x+1,y+1) ]=0;
        Q.push(P(x+1,y+1));
        mp[ P(x,y) ]=0;
        Q.push(P(x,y));
      }else{
        va.push_back(P(x,y));
        vb.push_back(P(x+1,y+1));
        vc.push_back(total);
      }

    }

  }
  return true;
}


