      for(int dy=-1;dy<=0;dy++){

        if(px+dx<0 || py+dy<0)continue;
        if(R<=px+dx+1 || C<=py+dy+1)continue;

        if( check(px,py) == false )return false;

      }
    }
  }

  set<int> st;
  map<int,int> lk;
  map<int,int> dist;
  for(int i=0;i<(int)va.size();i++){
    int A= id[ va[i] ];
    int B= id[ vb[i] ];
    int C= vc[i];
    if(A>B)swap(A,B);
    G[A].push_back(B);
    g[A].push_back(C);
    st.insert(A);
    st.insert(B);
    lk[B]++;
  }
  queue<int> que;
  for(int index : st ){
    if(lk[ index ]==0){
      que.push(index);
      dist[index]=0;
    }
  }

  while(!que.empty()){
    int pos=que.front();que.pop();
    for(int i=0;i<(int)G[pos].size();i++){
      int to=G[pos][i];
      int num=g[pos][i];
      if(dist.count(to)>0 && dist[to]!=num-dist[pos] )return false;
      dist[to]=num-dist[pos];
      lk[to]--;
      if(lk[to]==0)que.push(to);
    }
  }

  return true;
}

