struct Edge {
	int to;
	lint dst;
};

Vec< Vec< Edge > > edges;
Vec< lint > val;
Vec< bool > vis;

void dfs(int v, lint a, bool t, lint& mx, lint &my) {
	if (vis[v]) return;
	vis[v] = true;
	val[v] = a;

	if (t) minUpdate(mx, a);
	else minUpdate(my, a);

	for (const Edge& e : edges[v]) {
		lint na = e.dst - a;
		dfs(e.to, na, !t, mx, my);
	}
}

int main() {
	int R, C, N;
	cin >> R >> C >> N;

	edges.assign(R+C, Vec< Edge >());
