		edges[r-1].push_back(Edge{R+c-1, a});
		edges[R+c-1].push_back(Edge{r-1, a});
	}

	val.assign(R+C, 0);
	vis.assign(R+C, false);
	for_(v,0,R+C) {
		if (vis[v]) continue;
		lint mx = 1LL << 60, my = 1LL << 60;
		dfs(v, 0, false, mx, my);
		if (mx + my < 0) {
			puts("No");
			return 0;
		}
	}

	for_(v,0,R+C) {
		for (const Edge& e : edges[v]) {
			if (val[v] + val[e.to] != e.dst) {
				puts("No");
				return 0;
			}
		}
	}

	puts("Yes");
}
