bool func(int dx[3], int dy[3], int r,int c){
	int nfc=0;
	pii nf;
	rep(i,4){
		int nx=c+dx[i];
		int ny=r+dy[i];
		//printf("nx,ny=%d-%d\n",nx,ny);
		pii np=pii(nx,ny);
		if(fld.find(np)==fld.end()){
			nfc++;
			nf = np;
		}
	}
	//printf("nfc=%d\n",nfc);
	if(nfc==1){
		ll s1 = fld[pii(c+dx[0],r+dy[0])] + fld[pii(c+dx[1],r+dy[1])];
		ll s2 = fld[pii(c+dx[2],r+dy[2])] + fld[pii(c+dx[3],r+dy[3])];
		fld[nf] = abs(s1-s2);
	}

	if(nfc<=1){
		ll s1 = fld[pii(c+dx[0],r+dy[0])] + fld[pii(c+dx[1],r+dy[1])];
		ll s2 = fld[pii(c+dx[2],r+dy[2])] + fld[pii(c+dx[3],r+dy[3])];
		//printf("(%d,%d)\n",s1,s2);
		if(s1 != s2){
			return false;
		}
	}
	return true;
}

