void dfs(ll s,vector<edge>graph[],ll dist[])
{
	for (edge e : graph[s])
	{
		if (dist[e.to] == INF)
		{
			dist[e.to] = dist[s] + e.cost;
			dfs(e.to, graph, dist);
		}
	}
}

bool answer = true;
int main()
{
	In_(row); In_(col); 
	In_(num);
	for (int i = 0; i < num; ++i)
	{
		ll r, c, a;
		In_(r); In_(c); In_(a);
		--r; --c;
		beads.push_back({ {r,c},a });
	}

	sort(beads.begin(), beads.end(), [](const bd& a, const bd&b) {if (a.pos.second == b.pos.second)return a.pos.first < b.pos.first; return a.pos.second < b.pos.second; });
	ll ystart = beads[0].pos.first;
	for (ll b = 0; b < beads.size() - 1; ++b)
	{
		if (beads[b].pos.second == beads[b + 1].pos.second)
		{
			ll nowlen = beads[b + 1].cost - beads[b].cost;
			ll avec = beads[b].pos.first,bvec = beads[b + 1].pos.first;
			ygraph[avec].push_back({ bvec,nowlen });
			ygraph[bvec].push_back({ avec,-nowlen });
		}
	}
	fill(ydist, ydist + MAX_N, INF);
	ydist[ystart] = 0;
	dfs(ystart,ygraph,ydist);
	for (int i = 0; i < row; ++i)
	{
		for (edge e : ygraph[i])
		{
			if (ydist[e.to] != ydist[i] + e.cost)
			{
				answer = false;
			}
		}
	}
	ll xadd = INF;
	for (ll &xd : xdist)xadd = min(xadd, xd);
	for (ll &xd : xdist)xd -= xadd;
	sort(beads.begin(), beads.end(), [](const bd& a, const bd&b) {if (a.pos.first == b.pos.first)return a.pos.second < b.pos.second; return a.pos.first < b.pos.first; });
	ll xstart = beads[0].pos.second;
	for (ll b = 0; b < beads.size() - 1; ++b)
	{
		if (beads[b].pos.first == beads[b + 1].pos.first)
		{
			ll nowlen = beads[b + 1].cost - beads[b].cost;
			ll avec = beads[b].pos.second, bvec = beads[b + 1].pos.second;
			xgraph[avec].push_back({ bvec,nowlen });
			xgraph[bvec].push_back({ avec,-nowlen });
		}
	}
	fill(xdist, xdist + MAX_N, INF);
	xdist[xstart] = 0;
	dfs(xstart, xgraph, xdist);
	for (int i = 0; i < col; ++i)
	{
		for (edge e : xgraph[i])
		{
			if (xdist[e.to] != xdist[i] + e.cost)
			{
				answer = false;
			}
		}
	}
	ll yadd = INF;
	for (ll &yd : xdist)yadd = min(yadd, yd);
	for (ll &yd : xdist)yd -= yadd;

	for (bd b : beads)
	{
		if (b.cost < ydist[b.pos.first])
		{
			answer = false;
		}
