  }
  rc[N]=PP(P(200000,200000),0);
  /*for(int i=0;i<N+1;++i) {
    printf("(%d,%d)", rc[i].first.first, rc[i].first.second);
  }*/
  sort(rc, rc+N, comp);
  bool OK=true;
  for(int i=0;i<N;++i) {
    P currentPos=rc[i].first;
    P right = P(currentPos.first,currentPos.second+1);
    PP found=*lower_bound(rc,rc+N,PP(right,0),comp);
    if (found.first == right) {
      int tc = currentPos.second;
      int tv = (found.second - rc[i].second);
      auto it=cConstraints.find(tc);
      if (it!=cConstraints.end() && cConstraints[tc]!=tv) {
        OK=false;
      } else {
        cConstraints.insert(make_pair(tc,tv));
      }
    }
    currentPos=rc[i].first;
    right = P(currentPos.first+1,currentPos.second);
    found=*lower_bound(rc,rc+N,PP(right,0),comp);
    if (found.first == right) {
      int tc = currentPos.first;
      int tv = (found.second - rc[i].second);
      auto it=rConstraints.find(tc);
      if (it!=rConstraints.end() && rConstraints[tc]!=tv) {
        OK=false;
      } else {
        rConstraints.insert(make_pair(tc,tv));
      }
    }
  }

  for(int i=0;i<N;++i) {
    P& currentPos=rc[i].first;
    if(rConstraints.find(currentPos.first)!=rConstraints.end()) {
      int v=rConstraints[currentPos.first];
      int nv = rc[i].second + v;
      if (nv <0) {
        OK = false;
      }
    }
    if(rConstraints.find(currentPos.first-1)!=rConstraints.end()) {
      int v=rConstraints[currentPos.first-1];
      int nv = rc[i].second - v;
      if (nv <0) {
        OK = false;
      }
    }
    if(cConstraints.find(currentPos.second)!=rConstraints.end()) {
      int v=cConstraints[currentPos.second];
      int nv = rc[i].second + v;
      if (nv <0) {
        OK = false;
      }
    }
    if(cConstraints.find(currentPos.second-1)!=rConstraints.end()) {
      int v=cConstraints[currentPos.second-1];
      int nv = rc[i].second - v;
      if (nv <0) {
        OK = false;
      }
    }
  }

  if (OK) {
    printf("Yes\n");
  } else {
    printf("No\n");
  }
  return 0;
}

