ll h, w;

ll idx(pll x){
  return x.xx*w + x.yy;
}

bool outbound(pll ul){
  if(ul.xx < 0 || ul.yy < 0 || ul.xx+1 >= h || ul.yy+1 >= w)
    return true;
  return false;
}

bool sane(pair<vector<pll>,ll> e){
  //FOR(i,0,sz(e.xx)){
  //  cerr << e.xx[i].yy << " * " << e.xx[i].xx << endl;
  //}
  //cerr << e.yy << endl << endl;
  FOR(i,1,sz(e.xx)){
    if(e.xx[i].xx != e.xx[i-1].xx) return true;
  }
  ll neg = 0;
  ll pos = 0;
  FOR(i,0,sz(e.xx)){
    if(e.xx[i].yy == 1) pos++;
    else neg++;
  }
  if(pos == neg) return e.yy == 0;
  ll div = max(neg, pos) - min(neg, pos);
  ll flip = (neg > pos)*(-1);
  if(e.yy%div) return false;
  return (e.yy > 0) != (flip > 0);
}

int main() { 
  ios::sync_with_stdio(false); 
  cin >> h >> w;
  ll n;
  cin >> n;
  map<ll,ll> f;
  FOR(i,0,n){
    ll r, c, num;
    cin >> r >> c >> num;
    f[idx(mp(r-1, c-1))] = num;
  }
  set<vector<pll>> equ_raw; //1 -> idx, 0 -> constant
  for(auto p : f){
    ll i = p.xx/w;
    ll j = p.xx%w;
    vector<pll> corners = {{i,j},{i-1,j},{i,j-1},{i-1,j-1}};
    for(auto ul : corners){
      if(outbound(ul)) continue;
      //cerr << ul.xx << " " << ul.yy << endl;
      vector<pll> entr = {{ul.xx,ul.yy}, {ul.xx+1,ul.yy}, {ul.xx+1, ul.yy+1}, {ul.xx, ul.yy+1}};
      vector<pll> equation;
      FOR(id,0,4){
        pll e = entr[id];
        if(f.count(idx(e)))
          equation.pb(mp(f[idx(e)], 0));
        else
          equation.pb(mp(idx(e), 1));
      }
      equ_raw.insert(equation);
    }
  }
  //cerr << "size: " << sz(equ_raw) << endl;
  set<pair<vector<pll>, ll>> equ;
  for(auto e : equ_raw){
    vector<pll> vars;
    ll val = 0;
    FOR(i,0,4){
      if(e[i].yy == 0) val += ((i%2) ? 1 : -1) * e[i].xx;
      else{
        ll idx = e[i].xx;
        vars.pb(mp(idx, ((i%2) ? 1 : -1)));
      }
    }
    sort(all(vars));
    equ.insert(mp(vars, val));
  }

  bool poss = true;
  while(sz(equ) >1 && poss){
    bool changed = false;
    for(auto e1 : equ){
      vector<pll> v1 = e1.xx;
      ll val1 = e1.yy;
      if(!sane(e1)){
        poss = false;
        break;
      }
      for(auto e2 : equ){
        if(e1 == e2) continue;
        if(!sane(e2)){
          poss = false;
          break;
        }
        vector<pll> v2 = e2.xx;
        ll val2 = e2.yy;
        bool ok = false;
        ll si, sj;
        FOR(i,0,sz(v1)){
          FOR(j,0,sz(v2)){
            if(v1[i].xx == v2[j].xx){
              si = i; sj = j;
              ok = true;
            }
          }
        }

        if(ok){
          equ.erase(e1);
          equ.erase(e2);
          changed = true;
          vector<pll> new_v;
          ll flip = (v2[sj].yy)*(-1);
          FOR(i,0,sz(v1)){
            if(i == si) continue;
            new_v.pb(mp(v1[i].xx, v1[i].yy*flip));
          }
          FOR(j,0,sz(v2)){
            if(j == sj) continue;
            new_v.pb(v2[j]);
          }
          sort(all(new_v));
          ll new_val = (val1*flip)+val2;
          equ.insert(mp(new_v, new_val));
        }

        if(changed || !poss) break;
      }
      if(changed || !poss) break;
    }
  }
    if(poss && sane(*(equ.begin())))
      cout << "Yes" << endl;
    else
      cout << "No" << endl;
}

