  cin >> R >> C >> n;
  for (int i = 0; i < n; i++) {
    int x, y, value;
    cin >> x >> y >> value;
    values[Cell{x, y}] = value;
  }

  if (R >= 10 || C >= 10) {
    cout << "No" << endl;
    return 0;
  }

  relax_zero();
  relax_single();
  relax_zero();
  prepare_conditions();
  satisfy_conditions();

  cout << "Yes" << endl;

  return 0;
}

