struct UnionFind{
    vector<int> par;
    UnionFind(int n){
        par = vector<int>(n,-1);
    }

    int root(int x){
        if(par[x]<0){
            return x;
        }else{
            return par[x]=root(par[x]);
        }
    }

    void unite(int x,int y){
        x=root(x);
        y=root(y);
        if(x!=y){
            if(par[x]<par[y]) swap(x,y);
            par[y] += par[x];
            par[x] = y;
        }
        return;
    }

    bool same(int x,int y){
        return root(x) == root(y);
    }

    int size(int x){
        return -par[root(x)];
    }
};

struct Edge{
    LL from,to,cost;
    Edge(LL from,LL to,LL cost)
        : from(from),to(to),cost(cost) {};
};
