    //cout << "dr" << endl;

    ok = check_cell(r, c, r4, c4, r + 2, c, r + 2, c - 1) &&
         check_cell(r, c, r4, c4, r - 2, c, r - 2, c - 1) &&
         check_cell(r, c, r5, c5, r + 2, c, r + 2, c + 1) &&
         check_cell(r, c, r5, c5, r - 2, c, r - 2, c + 1) &&
         check_cell(r, c, r2, c2, r, c + 2, r + 1, c + 2) &&
         check_cell(r, c, r2, c2, r, c - 2, r + 1, c - 2) &&
         check_cell(r, c, r7, c7, r, c + 2, r - 1, c + 2) &&
         check_cell(r, c, r7, c7, r, c - 2, r - 1, c - 2);
