		cin >> r[i] >> c[i] >> a[i];
		rc.push_back(make_pair(r[i], c[i]));
		RC[r[i]][c[i]] = a[i];
	}
	sort(rc.begin(), rc.end());


	vector<set<int>> sr(R),sc(C);
	bool flag = true;
	while (flag) {
