		for (int i = 0; i < rc.size(); i++) {
			if (rc[i].first + 1 != R+1) {
				if (RC[rc[i].first + 1][rc[i].second] != -1) {
					sr[rc[i].first].insert(RC[rc[i].first + 1][rc[i].second] - RC[rc[i].first][rc[i].second]);
				}
			}
			if (rc[i].second + 1 != C+1) {
				if (RC[rc[i].first][rc[i].second + 1] != -1) {
					sc[rc[i].second].insert(RC[rc[i].first][rc[i].second + 1] - RC[rc[i].first][rc[i].second]);
