			if (sr[i].size() > 1) {
				cout << "No" << endl;
				return 0;
			}
		}
		for (int i = 0; i < C; i++) {
			if (sc[i].size() > 1) {
				cout << "No" << endl;
				return 0;
			}
		}
		for (int i = 0; i < rc.size(); i++) {
			if (rc[i].first + 1 != R+1) {
				if (RC[rc[i].first + 1][rc[i].second] == -1 && sr[rc[i].first].size()) {
					RC[rc[i].first + 1][rc[i].second] = RC[rc[i].first][rc[i].second] + *sr[rc[i].first].begin();
					if (RC[rc[i].first + 1][rc[i].second] < 0) {
						cout << "No" << endl;
						return 0;
					}
					rc.push_back(make_pair(rc[i].first + 1, rc[i].second));
					flag = true;
				}
			}
			if (rc[i].second + 1 != C+1) {
				if (RC[rc[i].first][rc[i].second + 1] == -1 && sc[rc[i].second].size()) {
					RC[rc[i].first][rc[i].second + 1] = RC[rc[i].first][rc[i].second] + *sc[rc[i].second].begin();
					if (RC[rc[i].first][rc[i].second+1] < 0) {
						cout << "No" << endl;
						return 0;
					}
					rc.push_back(make_pair(rc[i].first, rc[i].second + 1));
					flag = true;
				}
			}
		}
	}

	cout << "Yes" << endl;

	return 0;
}

