#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

#define MAX 100005
typedef pair<int,int> P;
int R,C;
int N;
map< P , ll > mp;

int r[MAX],c[MAX],a[MAX];
queue<P> Q;
vector<P> va,vb;
vector<int> vc;

bool check(int x,int y){
  int cnt=4;
  ll total=0;
  bool fa=false,fb=false,fc=false,fd=false;

  if( mp.count(P(x,y)) >0)cnt--,fa=true,total+=mp[ P(x,y) ];
  if( mp.count(P(x+1,y)) >0)cnt--,fb=true,total+=mp[ P(x+1,y) ];
  if( mp.count(P(x,y+1)) >0)cnt--,fc=true,total+=mp[ P(x,y+1) ];
  if( mp.count(P(x+1,y+1)) >0)cnt--,fd=true,total+=mp[ P(x+1,y+1) ];

  if(cnt==0){
    if( mp[P(x,y)]+mp[P(x+1,y+1)] == mp[P(x,y+1)]+mp[P(x+1,y)])return true;
    else return false;
  }

  if(cnt==1){
    if(fa==false){
      mp[ P(x,y) ]=total-mp[P(x+1,y+1)]*2;
      Q.push(P(x,y));

    }
    if(fb==false){
      mp[ P(x+1,y) ]=total-mp[P(x,y+1)]*2;
      Q.push(P(x+1,y));

    }
    if(fc==false){
      mp[ P(x,y+1) ]=total-mp[P(x+1,y)]*2;
      Q.push(P(x,y+1));

    }
    if(fd==false){
      mp[ P(x+1,y+1) ]=total-mp[P(x,y)]*2;
      Q.push(P(x+1,y+1));

    }

  }

  if(cnt==2){

    if(fa==true && fd==true){

      if(total==0){
        mp[ P(x,y+1) ]=0;
        Q.push(P(x,y+1));
        mp[ P(x+1,y) ]=0;
        Q.push(P(x+1,y));
      }else{
        va.push_back(P(x,y+1));
        vb.push_back(P(x+1,y));
        vc.push_back(total);
      }

    }else if(fb==true && fc==true ){

      if(total==0){
        mp[ P(x+1,y+1) ]=0;
        Q.push(P(x+1,y+1));
        mp[ P(x,y) ]=0;
        Q.push(P(x,y));
      }else{
        va.push_back(P(x,y));
        vb.push_back(P(x+1,y+1));
        vc.push_back(total);
      }

    }

  }
  return true;
}


vector<int> G[400005];
vector< ll > g[400005];

bool solve(){
  map< P , int> id;

  while(!Q.empty()){
    P p=Q.front();Q.pop();
    int px=p.first;
    int py=p.second;


    if( mp[P(px,py)] < 0 )return false;

    for(int dx=-1;dx<=0;dx++){
      for(int dy=-1;dy<=0;dy++){

        if(px+dx<0 || py+dy<0)continue;
        if(R<=px+dx+1 || C<=py+dy+1)continue;

        if( check(px+dx,py+dy) == false )return false;

      }
    }
  }
  assert(0);
  return true;


  int cc=1;

  set<int> st;
  map<int,int> lk;
  map<int, ll > dist;
  for(int i=0;i<(int)va.size();i++){
    if(id.count(va[i])==0) id[va[i]]=cc++;
    if(id.count(vb[i])==0) id[vb[i]]=cc++;

    //    cout<<va[i].first<<' '<<va[i].second<<' ';
    //    cout<<vb[i].first<<' '<<vb[i].second<<endl;

    int A= id[ va[i] ];
    int B= id[ vb[i] ];
    int C= vc[i];
    if(A>B)swap(A,B);
    cout<<A<<' '<<B<<' '<<C<<endl;

    G[A].push_back(B);
    g[A].push_back(C);
    st.insert(A);
    st.insert(B);
    lk[B]++;
  }
  queue<int> que;
  for(int index : st ){
    if(lk[ index ]==0){
      que.push(index);
      dist[index]=0;
    }
  }

  while(!que.empty()){
    int pos=que.front();que.pop();
    //    if( dist[pos] < 0 )return false;


    for(int i=0;i<(int)G[pos].size();i++){
      int to=G[pos][i];
      ll num=g[pos][i];
      if(dist.count(to)>0 && dist[to]!=num-dist[pos] )return false;
      dist[to]=num-dist[pos];
      lk[to]--;
      if(lk[to]==0)que.push(to);
    }
  }

  return true;
}

int main(){
  scanf("%d %d %d",&R,&C,&N);
  for(int i=0;i<N;i++){
    scanf("%d %d %d",&r[i],&c[i],&a[i]);
    r[i]--,c[i]--;

    mp[ P(r[i],c[i]) ]=a[i];
    Q.push( P(r[i],c[i]) );
  }

  cout<< ( solve()? "Yes":"No") <<endl;
  return 0;
}

