const int N = 1e5 + 10;

vector<pii> g[N];
const int S = 1e6;
vi not_empty;
int used[N];
int val[N];
int timer = 1;

void out_and_exit(bool ans) {
    cout << (ans ? "Yes\n" : "No\n");
    exit(0);
}

void big_check(int xbig) {
    timer++;
    for (auto py : g[xbig]) {
        used[py.first] = timer;
        val[py.first] = py.second;
    }
    for (auto x : not_empty) {
        int df;
        bool was = false;
        for (auto py : g[x]) {
            if (used[py.first] == timer) {
                if (!was) {
                    was = true;
                    df = val[py.first] - py.second;
                }
                if (df != val[py.first] - py.second) {
                    out_and_exit(false);
                }
            }
        }
    }
}

const ll oo = 1e15 + 10;
ll lf[N], rf[N];

bool check_bounds() {
    fori (i, N) {
        rf[i] = oo;
    }
    for (auto x : not_empty) {
        ll cur_min = oo;
        for (int i = SZ(g[x]) - 1; i >= 0; --i) {
            inmax(lf[g[x][i].first], g[x][i].second - cur_min);
            inmin(cur_min, (ll)g[x][i].second);
        }
        reverse(ALL(g[x]));
        for (int i = SZ(g[x]) - 1; i >= 0; --i) {
            inmax(lf[g[x][i].first], g[x][i].second - cur_min);
            inmin(cur_min, (ll)g[x][i].second);
        }
    }

    for (auto x : not_empty) {
        for (auto py : g[x]) {
            if (py.second < lf[py.first])
                return false;
        }
    }
    return true;
}

void smain() {
    int dum, n;
    cin >> dum >> dum >> n;
    fori (_, n) {
        int x, y, a;
        cin >> x >> y >> a;
        g[x].push_back({y, a});
    }
    fori (x, N) {
        sort(ALL(g[x]));
        if (!g[x].empty())
            not_empty.push_back(x);
    }
    map<pii, int> df;
    for (auto x : not_empty) {
        if (g[x].size() > S) {
            big_check(x);
        } else {
            for (auto py1 : g[x]) {
                for (auto py2 : g[x]) {
                    if (py2 >= py1)
                        break;
                    pii key = {py1.first, py2.first};
                    if (!df.count(key)) {
                        df[key] = py1.second - py2.second;
                    }
                    if (df[key] != py1.second - py2.second) {
                        out_and_exit(false);
                    }
                }
            }
        }
    }

    out_and_exit(check_bounds());
}

