bool check(unordered_map<int,map<int,int> > const & fh) {
    for (auto row1 : fh) {
        for (auto row2 : fh) {
            if (row1.first == row2.first) continue;
            ll delta = inf;
            ll min1 = inf;
            for (auto it1 : row1.second) {
                setmin<ll>(min1, it1.second);
                if (row2.second.count(it1.first)) {
                    ll delta1 = row2.second[it1.first] - it1.second;
                    if (delta == inf) {
                        delta = delta1;
                    } else {
                        if (delta1 != delta) return false;
                    }
                }
            }
            if (min1 + delta < 0) return false;
        }
    }
    return true;
}
