		fld[pii(r,c)] = a;
		if(r!=1&&c!=1){
			int dy[]={-1,0,0,-1};
			int dx[]={-1,0,-1,0};
			if(!func(dx,dy,r,c)){
				flg=false;
			}
		}
		if(r!=1 && c!=C){
			int dy[]={0,-1,-1,0};
			int dx[]={0,1,0,1};
			if(!func(dx,dy,r,c)){
				flg=false;
			}
		}
		if(r!=R && c!=1){
			int dr[]={0,1,0,1};
			int dc[]={0,-1,-1,0};
			if(!func(dc,dr,r,c)){
				flg=false;
			}
		}
		if(r!=R && c!=C){
			int dy[]={0,1,1,0};
			int dx[]={0,1,0,1};
