				flg=false;
			}
		}
		//cout << flg << "---" << i << endl;
	}

	if(R*C==N || !flg){
		cout << "No" << endl;
	}else{
		cout << "YES" << endl;
	}
}

#include<bits/stdc++.h>

using namespace std;

int sz, N, M, Q, globalX, sg[200009], val[200009], comp[200009];
bool fixedX, ap[200009];
vector < pair < int, int > > v[200009];

void Ans (bool x)
{
    if (x) printf ("Yes\n");
    else printf ("No\n");
    exit (0);
}

void dfs (int nod, int sg2, int val2)
{
    if (ap[nod])
    {
        if (sg2 == sg[nod] && val2 != val[nod]) Ans (0);
        if (sg2 != sg[nod])
        {
            ///X*sg2+val2=X*sg[nod]+val[nod]
            ///X*(sg2-sg[nod])=val[nod]-val2
            int sus = val[nod] - val2, jos = sg2 - sg[nod];
            if (sus % jos != 0) Ans (0);
            int currX = sus / jos;
            if (fixedX)
            {
                if (globalX != currX) Ans (0);
            }
            else globalX = currX, fixedX = 1;
        }
        return ;
    }
    comp[++sz] = nod;
    ap[nod] = 1, sg[nod] = sg2, val[nod] = val2;
    for (auto it = v[nod].begin (); it != v[nod].end (); it ++)
        dfs (it->first, -sg[nod], it->second - val[nod]);
        ///sg[nod] * X + val[nod] + s2 * X + v2 = it->second
}

int main ()
{
//freopen ("input", "r", stdin);
//freopen ("output", "w", stdout);

scanf ("%d %d", &N, &M);
scanf ("%d", &Q);
for (int i=1; i<=Q; i++)
{
    int x, y, val;
    scanf ("%d %d %d", &x, &y, &val), y += N;
    v[x].push_back (make_pair (y, val));
    v[y].push_back (make_pair (x, val));
}
for (int i=1; i<=N + M; i++)
    if (ap[i] == 0)
    {
        fixedX = 0, sz = 0;
        dfs (i, 1, 0);
        int mi = 2e9, ma = -2e9;
        for (int j=1; j<=sz; j++)
        {
            int nod = comp[j];
            if (fixedX)
            {
                int curr = globalX * sg[nod] + val[nod];
                if (curr < 0) Ans (0);
            }
            else
            {
                if (sg[nod] == -1 && val[nod] < mi) mi = val[nod];
                if (sg[nod] == 1 && -val[nod] > ma) ma = -val[nod];
            }
        }
        if (fixedX == 0 && mi < ma) Ans (0);
    }
Ans (1);
return 0;
}

