    lint n;
    cin >> n;
    vector<lint> r(n), c(n), a(n);
    vector<lint> nodes(h + w, inf);
    vector<vector<pair<int, lint>>> edges(h + w);
    for (int i = 0; i < n; ++i) {
        cin >> r[i] >> c[i] >> a[i];
        r[i]--, c[i]--;
        edges[r[i]].emplace_back(h + c[i], a[i]);
        edges[h + c[i]].emplace_back(r[i], a[i]);
    }
    for (int i = 0; i < h; ++i) {
        if (nodes[i] != inf || edges[i].size() == 0)
            continue;
        nodes[i]                     = 0;
        function<void(int, int)> dfs = [&](int c, int p) {
            for (auto &v : edges[c]) {
                if (v.first == p)
                    continue;
                if (nodes[v.first] != inf) {
                    continue;
                }
                nodes[v.first] = v.second - nodes[c];
                dfs(v.first, c);
