int dy[4]={0, 0, -1, -1};

bool find(P p, int i){
	P pp;
	pp.first=p.first+dx[i]*(-1);
	pp.second=p.second+dy[i]*(-1);

	map<P, int>::iterator it = m.find(pp);
	if (it != m.end()) {
		return true;
	}else{
		return false;
	}
}

bool check(P p){
	P base;
	P p2;

	for(int i=0; i<4; i++){
		unsigned int a=0, b=0;
		bool flag_a=false, flag_d=false, flag_b=false, flag_c=false;

		base.first=p.first+dx[i];
		base.second=p.second+dy[i];
		if(base.first<0 || base.second<0){
			return true;
		}

		if(find(base, 0)){
			p2.first=base.first+dx[0]*(-1);
			p2.second=base.second+dy[0]*(-1);
			a+=m[p2];
			flag_a=true;
		}

		if(find(base, 1)){
			p2.first=base.first+dx[1]*(-1);
			p2.second=base.second+dy[1]*(-1);
			b+=m[p2];
			flag_b=true;
		}

		if(find(base, 2)){
			p2.first=base.first+dx[2]*(-1);
			p2.second=base.second+dy[2]*(-1);
			b+=m[p2];
			flag_c=true;
		}

		if(find(base, 3)){
			p2.first=base.first+dx[3]*(-1);
			p2.second=base.second+dy[3]*(-1);
			a+=m[p2];
			flag_d=true;
		}


		if(a==b){
			return true;
		}else if(a<b){
			if(!flag_a || !flag_d){
				return true;
			}else{
				return false;
			}
		}else if(a>b){
			if(!flag_b || !flag_c){
				return true;
			}else{
				return false;
			}
		}
	}
	return true;
}

