		}
	}

	ll min_col = INF;
	ll min_row = INF;
	forn(i, R) min_col = min(min_col, vals[i].snd);
	forn(i, C) min_row = min(min_row, vals[R + i].snd);
	if  (min_col + min_row < ps[0].val) {
		return false;
	}

	return true;
}

