        int A, B, C;
        scanf("%d%d%d",&A,&B,&C);
        mp[{A,B}] = C + 1;
        q.push({A,B});
    }
    while(!q.empty()) {
        int X = q.front().first, Y = q.front().second;
        q.pop();
        int mv = mp[{X,Y}];
        for(int i=0;i<4;i++) {
            int ta = mp[{X+dx[2*i], Y+dy[2*i]}], tb = mp[{X+dx[2*(i+1)%8],Y+dy[2*(i+1)%8]}];
            if(ta && tb) {
                int tmp = ta + tb - mv;
                if(tmp < 1) return puts("No");
                pair<int, int> nw = {X+dx[2*i]+dx[2*(i+1)%8], Y+dy[2*i]+dy[2*(i+1)%8]};
                int tc = mp[nw];
                if(tc) {
                    if(tc != tmp) return puts("No");
                }
                else {
                    mp[nw] = tmp;
                    q.push(nw);
                }
            }
        }
        for(int i=0;i<8;i++) {
            int ta = mp[{X+dx[i], Y+dy[i]}], tb = mp[{X+dx[(i+1)%8],Y+dy[(i+1)%8]}];
