inline bool cmp1(point a,point b)
{
	if(a.x==b.x) return a.y<b.y ? true : false;
	else         return a.x<b.x ? true : false; 
}

inline bool cmp2(point a,point b)
{
	if(a.y==b.y) return a.x<b.x ? true : false;
	else         return a.y<b.y ? true : false;
}

inline bool cmp3(point a,point b)
{
	return a.pos<b.pos ? true : false;
}

bool operator < (point a,point b)
{
	if(a.x==b.x) return a.y<b.y ? true : false;
	else         return a.x<b.x ? true : false; 
} 

inline void put(point x)
{
	heap[++size]=x;
	int now=size;
	while(now>=1)
	{
		int nxt=now>>1;
		if(heap[nxt]<heap[now]) break;
		swap(heap[nxt],heap[now]);
		now=nxt;
	}
} 

inline point get()
{
	point res=heap[1];
	heap[1]=heap[size--];
	int now=1;
	while((now<<1)<=size)
	{
		int nxt=now<<1;
		if(heap[nxt+1]<heap[nxt]) nxt++;
		if(heap[now]<heap[nxt]) break;
		swap(heap[nxt],heap[now]);
		now=nxt;
	}
	return res;
} 

inline void init()
{
	memset(nxtl,-1,sizeof(nxtl));
	memset(nxtr,-1,sizeof(nxtr));
	sort(a+1,a+n+1,cmp1);
	int t=1;
	while(t<=n)
	{
		if(a[t].x==a[t+1].x) nxtl[a[t].pos]=a[t+1].pos;
		else nxtl[t]=-1;
		t++;
	}
	sort(a+1,a+n+1,cmp2);
	t=1;
	while(t<=n)
	{
		if(a[t].y==a[t+1].y) nxtr[a[t].pos]=a[t+1].pos;
		else nxtr[t]=-1;
		t++; 
	}
	sort(a+1,a+n+1,cmp3); 
}

inline bool get_ans()
{
	point now,last;
	while(size)
	{
		now=get();
		if(now.x==last.x && now.y==last.y && now.val!=last.val) return false;
		int k=now.pos,s;
		while(nxtl[k]!=-1)
		{
			s=now.pos;
			k=nxtl[k];
			while(nxtr[s]!=-1)
			{
				s=nxtr[s];
				point newone;
				newone.x=a[s].x;
