struct union_find{
	typedef unsigned size_type;
	vector<int> par;
	size_type grs;
	explicit union_find(size_type n = 0){ init(n); }
	void init(size_type n){
		par.assign(n, -1);
		grs = n;
	}
	size_type find(size_type x){
		if(par[x] < 0){ return x; }
		return par[x] = find(par[x]);
	}
	size_type size(size_type x){
		return -par[find(x)];
	}
	size_type groups(){
		return grs;
	}
	bool unite(size_type x, size_type y){
		x = find(x);
		y = find(y);
		if(x == y){ return false; }
		if(par[x] < par[y]){ swap(x, y); }
		par[y] += par[x];
		par[x] = y;
		--grs;
		return true;
	}
	bool same(size_type x, size_type y){
		return find(x) == find(y);
	}
};

const LL INF = LLONG_MAX / 5;
bool calcdifs(VV(pll) &v1, int w, vector<LL> &res){
	int m = v1.size() - 2;
	VV(pll) G(w + 2);
	union_find uf(w + 2);
	for(int i = 1; i <= m; ++i){
		auto &v = v1[i];
		int sz = v.size();
		for(int j = 1; j < sz; ++j){
			LL d = v[j].second - v[j - 1].second;
			G[v[j - 1].first].emplace_back(v[j].first, d);
			G[v[j].first].emplace_back(v[j - 1].first, -d);
			uf.unite(v[j - 1].first, v[j].first);
		}
	}

	res.assign(w + 2, INF);
	queue<int> q;
	for(int s = 1; s <= w; ++s){
		if(uf.find(s) == s){
			res[s] = 0;
			q.push(s);
		}
	}
	while(!q.empty()){
		int u = q.front();
		q.pop();
		for(cauto p : G[u]){
			if(res[p.first] == INF){
				res[p.first] = res[u] + p.second;
				q.push(p.first);
			}
			else if(res[p.first] != res[u] + p.second){
				return false;
			}
		}
	}

	vector<LL> ofs(w + 2, INF);
	for(int i = 1; i <= m; ++i){
		for(cauto p : v1[i]){
			LL &x = ofs[uf.find(p.first)];
			x = min(x, p.second + res[p.first]);
		}
	}
	for(int i = 1; i <= w; ++i){
		res[i] -= ofs[uf.find(i)];
	}

	return true;
}

bool solve(){
	int h, w, n;
	scanf("%d%d%d", &h, &w, &n);

	vector<int> ys(n), xs(n), as(n);
	for(int i = 0; i < n; ++i){
		scanf("%d%d%d", &ys[i], &xs[i], &as[i]);
	}

	VV(pll) v1(h + 2), v2(w + 2);
	for(int i = 0; i < n; ++i){
		v1[ys[i]].emplace_back(xs[i], as[i]);
		v2[xs[i]].emplace_back(ys[i], as[i]);
	}
	for(auto &v : v1){
		sort(ALL(v));
	}
	for(auto &v : v2){
		sort(ALL(v));
	}

	vector<LL> dif1, dif2;
	if(!calcdifs(v1, w, dif2)){ return false; }
	if(!calcdifs(v2, h, dif1)){ return false; }

	for(int i = 0; i < n; ++i){
		if(dif1[ys[i]] > as[i]){ return false; }
		if(dif2[xs[i]] > as[i]){ return false; }
	}

	return true;
}

void mainmain(){
	puts(solve() ? "Yes" : "No");
}



