        int x, y, z;
        cin >> x >> y >> z;

        edg[x].push_back( make_pair( r + y, z ) );
        edg[r + y].push_back( make_pair( x, z ) );
    }

    bool ok = true;
    for( int i = 1; i <= r + c; i ++ ) {
        if( oki[i] == false ) {
            long long mn1 = numeric_limits<long long> :: max();
            long long mn2 = numeric_limits<long long> :: max();

            dfs( i, r, ok, mn1, mn2 );
            ok &= ( mn1 + mn2 >= 0 );
        }
    }


    cout << ( ( ok == true ) ? "Yes" : "No" ) << endl;
    return 0;
}

