bool dfs(int node){
	if(node < R){
		xmin = min(xmin, w[node]);
	}else{
		ymin = min(ymin, w[node]);
	}
	for(int i = 0; i < tree[node].size(); i++){
		long long next = tree[node][i].first;
		long long wei = tree[node][i].second;
		if(w[next] == INF){
			w[next] = wei - w[node];
			if(dfs(next) == false){
				return false;
			}
		}else{
			if(w[next] + w[node] != wei){
				return false;
			}
		}
	}
	return true;
}

