void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  auto m = next<int>(in);
  auto nCells = next<int>(in);

  vec<pair<int, int>> cells(nCells);

  unordered_map<pair<int, int>, int> values;
  values.reserve(1 << 18);
  values.max_load_factor(0.25);

  int ax = -1;
  int ay = -1;
  FOR(i, nCells) {
    auto x = next<int>(in);
    auto y = next<int>(in);
    auto a = next<int>(in);
    values[{x, y}] = a;
    cells[i] = {x, y};
    ax = x;
    ay = y;
  }

  auto check = [&] (int x1, int y1, int x2, int y2) -> bool {
    int cnt = 0;
    if (values.find({x1, y1}) == values.end()) {
      ++cnt;
    }
    if (values.find({x1, y2}) == values.end()) {
      ++cnt;
    }
    if (values.find({x2, y1}) == values.end()) {
      ++cnt;
    }
    if (values.find({x2, y2}) == values.end()) {
      ++cnt;
    }
    if (cnt == 1) {
      int sum1 = 0, sum2 = 0, c1 = 0;
      if (values.find({x1, y1}) != values.end()) {
        sum1 += values[{x1, y1}];
        ++c1;
      }
      if (values.find({x1, y2}) != values.end()) {
        sum2 += values[{x1, y2}];
      }
      if (values.find({x2, y1}) != values.end()) {
        sum2 += values[{x2, y1}];
      }
      if (values.find({x2, y2}) != values.end()) {
        sum1 += values[{x2, y2}];
        ++c1;
      }
      dbg(c1, sum1, sum2);
      if (c1 == 2) {
        return sum1 - sum2 >= 0;
      } else {
        return sum2 - sum1 >= 0;
      }
    }
    if (cnt > 0) {
      return true;
    }
    if (values[{x1, y1}] + values[{x2, y2}] != values[{x1, y2}] + values[{x2, y1}]) {
      return false;
    }
    return true;
  };

  for (auto& p : cells) {
    if (p.first != ax && p.second != ay) {
      if (!check(p.first, p.second, ax, ay)) {
        out << "No\n";
        return;
      }
    }
  }

  out << "Yes\n";
}

