auto count = [](int r, int c, auto& data)
{
	return data[r / 16][c / 16].count(std::make_pair(r % 16, c % 16));
};
auto value = [](int r, int c, auto& data)->int64&
{
	return data[r / 16][c / 16][std::make_pair(r % 16, c % 16)];
};
template<class Data>bool set(Data& data, int r, int c)
{

	auto lu = count(r, c, data);
	auto ld = count(r + 1, c, data);
	auto ru = count(r, c + 1, data);
	auto rd = count(r + 1, c + 1, data);
	if (lu + ld + ru + rd == 4)
	{
		if (value(r, c, data) + value(r + 1, c + 1, data) != value(r + 1, c, data) + value(r, c + 1, data))
		{
			return false;
		}
	}
	if (lu + ld + ru + rd == 3)
	{
		if (!lu)
		{
			auto v = value(r + 1, c, data) + value(r, c + 1, data) - value(r + 1, c + 1, data);
			if (v < 0)
			{
				return false;
			}
			value(r, c, data) = v;
			return set(data, r - 1, c - 1);
		}
		else if (!rd)
		{
			auto v = value(r + 1, c, data) + value(r, c + 1, data) - value(r, c, data);
			if (v < 0)
			{
				return false;
			}
			value(r + 1, c + 1, data) = v;
			return true;
		}
		else if (!ru)
		{
			auto v = value(r + 1, c + 1, data) + value(r, c, data) - value(r + 1, c, data);
			if (v < 0)
			{
				return false;
			}
			value(r, c + 1,data) = v;
			return set(data, r - 1, c) && set(data, r - 1, c + 1);
		}
		else if (!ld)
		{
			auto v = value(r + 1, c + 1, data) + value(r, c, data) - value(r, c + 1, data);
			if (v < 0)
			{
				return false;
			}
			value(r, c + 1, data) = v;
			return set(data, r, c - 1);
		}
	}
	return true;
}
