map<int, int> field;
map<int, bool> filled;

const int dx[] = {1, 1, -1, -1};
const int dy[] = {1, -1, 1, -1};

bool isIllegal(int i) {
    int ri = r[i];
    int ci = c[i];
    int ai = a[i];

    for (int j = 0; j < 4; j++) {
        int y = ri + dy[j];
        int x = ci + dx[j];
        if (x < 0 || C <= x || y < 0 || R <= y) continue;

        int cnt = 1 + filled[C*ri+x] + filled[C*y+ci] + filled[C*y+x];
        if (cnt <= 2) continue;
        if (cnt == 4) {
            if (ai + field[C*y+x] != field[C*ri+x] + field[C*y+ci]) {
                return true;
            }
        } else if (!filled[C*ri+x]) {
            int temp = ai + field[C*y+x] - field[C*y+ci];
            if (temp < 0) return true;
            field[C*ri+x] = temp;
            filled[C*ri+x] = true;
        } else if (!filled[C*y+ci]) {
            int temp = ai + field[C*y+x] - field[C*ri+x];
            if (temp < 0) return true;
            field[C*y+ci] = temp;
            filled[C*y+ci] = true;
        } else if (!filled[C*y+x]) {
            int temp = field[C*ri+x] + field[C*y+ci] - ai;
            if (temp < 0) return true;
            field[C*y+x] = temp;
            filled[C*y+x] = true;
        }
    }
    return false;
}

