        r[i]--;
        c[i]--;
        field[C*r[i] + c[i]] = a[i];
        filled[C*r[i] + c[i]] = true;
    }

    for (int i = 0; i < N; i++) {
        if (isIllegal(i)) {
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;

    return 0;
}

