int dx[] = {1,0,-1,0};
int dy[] = {0,-1,0,1};


struct Edge {
	ll t;
	ll c;
	Edge(ll to, ll cost):t(to),c(cost){}
	Edge(){}
};

vector<ll> nodes;
vector<vector<ll> > groups;
vector<bool> check;

bool DFS(ll node, vector<vector<Edge> >& edge) {
	bool res = true;
	if (check[node]) return true;
	groups.back().push_back(node);
	check[node] = true;
	for (auto &to : edge[node]) {
		if(nodes[to.t] == std::numeric_limits<ll>::max()) nodes[to.t] = to.c - nodes[node];
		else {
			if (nodes[to.t] != to.c - nodes[node]) return false;
		}
		res &= DFS(to.t, edge);
	}
	return res;
}

void solve() {
	ll R, C; cin >> R >> C;
	ll N = in();
	check.resize(R + C);
	nodes.resize(R + C, numeric_limits<ll>::max());
	vector<vector<Edge> > edge(R+C);
	REP(i, N) {
		ll r, c, a; cin >> r >> c >> a;
		--r; --c;
		edge[r].emplace_back(R+c,a);
		edge[R+c].emplace_back(r, a);
	}

	bool res = true;
	REP(i, R + C) if(not check[i] and edge[i].size() > 0) {
		groups.push_back(vector<ll>());
		nodes[i] = 0;
		res &= DFS(i, edge);
		if (not res) {
			cout << "No" << endl;
			return;
		}
	}

	for (auto &a : groups) {
		if (a.empty()) continue;
		bool xcheck = false, ycheck = false;
		ll xmin, ymin;
		for (auto &b : a) {
			if (b < R) {
				if(xcheck) xmin = min(xmin, nodes[b]);
				else xmin = nodes[b];
			}
			else {
				if(ycheck) ymin = min(ymin, nodes[b]);
				else ymin = nodes[b];
			}
		}
		res &= (xmin + ymin >= 0);
	}
	cout << (res ? "Yes" : "No") << endl;
}

