const int dx[4] = {-1, -1, 1, 1}, dy[4] = {-1, 1, -1, 1};

bool check(const set<pair<int, i64>>& se, i64& plus) {
    bool updated = false;
    pair<int, i64> before; pair<int, i64> first(-1, -1LL);
    for(const auto& cur : se) {
        if(updated == false) {
            before = cur;
            first = cur;
            updated = true;
            continue;
        }
        if(plus == -1) {
            i64 sa1 = (i64)(cur.first - before.first);
            i64 sa2 = (i64)(cur.second - before.second);
            if(sa2 < 0 || sa2 % sa1 != 0) return false;
            plus = sa2 / sa1;
            continue;
        }
        i64 sa1 = (i64)(cur.first - before.first);
        i64 sa2 = (i64)(cur.second - before.second);

        if(sa2 < 0 || sa2 % sa1 != 0) return false;
        if(plus != sa2 / sa1) return false;
    }
    if(first != pair<int, i64>(-1, -1LL) && plus != -1LL) {
        i64 front = first.second - ((i64)(first.first * plus));
        if(front < 0LL) return false;
    }
    return true;
}
