        root[i] = mn;
//        cout<<"Comp at "<<i<<" "<<mn<<endl;
    }

    for (long long i=1; i<=C; i++) {
        long long lo = value[i] - root[id[i]];
        bound[i] = max(bound[i], lo);
//        cout<<"Bound "<<i<<" "<<bound[i]<<endl;
    }
    return !bad;
}

