    ll x = d[i][0], y = d[i][1];
    if(ruse[x]==-1&&cuse[y]==-1){
      ruse[x] = cuse[y] = i;
    }else if(ruse[x]==-1){
      uf.unite(i, cuse[y]);
      ruse[x] = i;
    }else if(cuse[y]==-1){
      uf.unite(i, ruse[x]);
      cuse[y] = i;
    }else{
      uf.unite(ruse[x], cuse[y]);
      uf.unite(ruse[x], i);
    }
  }

  vvl G = VV(n, 0, 0, ll);
