bool visited[100001][2];
const ll INF = ll(1e18);
const ll INF2 = ll(1e15);
ii relax(ii x, ii y)
{
	return mp(min(x.fi, y.fi), min(x.se, y.se));
}

ii dfs(int u, bool s)
{
	ii ans = mp(INF, INF);
	for(int i = 0; i < adj[u][s].size(); i++)
	{
		int v = adj[u][s][i].fi; ll w = adj[u][s][i].se;
		if(a[v][(s^1)] != -1)
		{
			if(a[v][(s^1)] + a[u][s] != w) return mp(-1, -1);
			if(s) ans = relax(ans, mp(a[v][(s^1)], a[u][s]));
			else ans = relax(ans, mp(a[u][s], a[v][(s^1)]));
		}
		else
		{
			a[v][(s^1)] = w - a[u][s];
			//cerr << v << ' ' << (s^1) << ' ' << a[v][(s^1)] << '\n';
			ii tmp = dfs(v, (s^1));
			ans = relax(ans, tmp);
		}
	}
	return ans;
}

void dfs2(int u, bool s, ll shift)
{
	visited[u][s] = true;
	for(int i = 0; i < adj[u][s].size(); i++)
	{
		int v = adj[u][s][i].fi;
		if(visited[v][(s^1)]) continue;
		else
		{
			if(s) a[v][(s^1)] -= shift;
			else a[v][(s^1)] += shift;
		}
	}
}

