		if(x == 1 && y == 1)
		{
			a0 = val; forced = true;
		}
		adj[x][0].pb(mp(y, val));
		adj[y][1].pb(mp(x, val));
		//ma[ii(x, y)] = val;
		//vec.pb(ii(x, y));
	}
	a[1][0] = a0; a[1][1] = a0;
	for(int i = 1; i <= n; i++)
	{
		for(int j = 0; j < 2; j++)
		{
			for(int k = 0; k < adj[i][j].size(); k++)
			{
				adj[i][j][k].se += a0;
			}
		}
	}
	for(int i = 1; i <= max(R, C); i++)
	{
		for(int j = 0; j < 2; j++)
		{
			if(i > R && j == 0) continue;
