PII dfs(int v, int h) {
  if (vis[v]) {
    if (w[v] != h) {
      printf("NO\n");
      exit(0);
    }
    return PII(INT_MAX / 2 - 1, INT_MAX / 2 - 1);
  }
  vis[v] = true;
  w[v] = h;
  int w1 = h, w2 = INT_MAX;
  for (int i = 0; i < G[v].size(); i += 1) {
