class Edge{
public:
	int to, cost;
};

int R, W;
vector<vector<Edge> > edge;
vector<bool> used;
vector<int> value;
int m1=INF, m2=INF;

void dfs(int n, int v){
	used[n]=true;
	value[n]=v;
	if(n<R && value[n]<m1){
		m1=value[n];
	}else if(n>=R && value[n]<m2){
		m2=value[n];
	}

	REP(i, edge[n].size()){
		if(!used[edge[n][i].to]){
			dfs(edge[n][i].to, edge[n][i].cost-v);
		}
	}
}

int main(int argc, char* argv[]){
	cin.tie(0);
	ios::sync_with_stdio(0);
	cout.precision(10);

	int N;
	cin>>R>>W;
	cin>>N;
	edge.resize(R+W);
	used.resize(R+W);
	value.resize(R+W);

	int r, w, a;
	Edge ee;
	REP(i, N){
		cin>>r>>w>>a;
		r--;
		w--;
		ee.to=R+w;
		ee.cost=a;
		edge[r].pb(ee);
		ee.to=r;
		edge[R+w].pb(ee);
	}

	REP(i, R+W){
		if(!used[i]){
			m1=INF;
			m2=INF;
			dfs(i, 0);
			if(m1+m2<0){
				cout<<"No"<<endl;
				return 0;
			}
		}
	}

	REP(i, R){
		REP(j, edge[i].size()){
			if(value[i]+value[edge[i][j].to]!=edge[i][j].cost){
				cout<<"No"<<endl;
				return 0;
			}
		}
	}

	cout<<"Yes"<<endl;

	return 0;
}

