vi diff;
vector<vector<pii>> col;
vector<ll> con;

bool dfs(ll cc, ll i, ll v)
{
    con[i] = cc;
    diff[i] = v;

    bool ret = true;
    for(pii& p : col[i]){
        ll tmp = v + p.second;
        if(con[p.first] != -1){
            ret &= tmp == diff[p.first];
        }
        else{
            dfs(cc, p.first, tmp);
        }
    }

    return ret;
}

int main()
{
    ll R, C, n;
    cin >> R >> C >> n;

    vector<vector<pii>> a(R);
    rep(i, n){
        ll r, c, v;
        cin >> r >> c >> v;
        --r;
        --c;
        a[r].emplace_back(c, v);
    }

    col.resize(C);
    rep(i, R){
        rep(j, a[i].size() - 1){
            col[a[i][j].first].emplace_back(a[i][j+1].first, a[i][j+1].second - a[i][j].second);
            col[a[i][j+1].first].emplace_back(a[i][j].first, a[i][j].second - a[i][j+1].second);
        }
    }

    diff.resize(C);
    con.assign(C, -1);
    ll num_con = 0;

    rep(i, C){
        if(con[i] != -1) continue;
        if(!dfs(num_con, i, 0)){
            cout << "No" << endl;
            return 0;
        }
        ++num_con;
    }

    vi m(num_con);
    rep(i, C){
        m[con[i]] = min(m[con[i]], diff[i]);
    }

    rep(i, R){
        for(pii& p : a[i]){
            if(p.second - diff[p.first] + m[con[p.first]] < 0){
                cout << "No" << endl;
                return 0;
            }
        }
    }

    cout << "Yes" << endl;
}

