const int N = 1e5 + 10;

void out_and_exit(bool ans) {
    cout << (ans ? "Yes\n" : "No\n");
    exit(0);
}

struct DSU {
    int parent[N];
    int dif[N];
    vi verts[N];

    DSU() {
        fill(parent, parent + N, -1);
    }

    bool have_set(int v) {
        return parent[v] != -1;
    }

    void make_set(int v) {
        parent[v] = v;
        dif[v] = 0;
        verts[v] = {v};
    }

    int find_set(int v) {
        return parent[v] == v ? v : parent[v] = find_set(parent[v]);
    }

    void union_sets(int u, int v, int df) { // df = f[v] - f[u];
        int fu = find_set(u);
        int fv = find_set(v);
        if (fu == fv) {
            if (dif[v] - dif[u] != df) {
                out_and_exit(false);
            }
            return;
        }
        if (verts[fu].size() < verts[fv].size()) {
            swap(fu, fv);
            swap(u, v);
            df *= -1;
        }
        parent[fv] = fu;
        int inc = dif[u] - dif[v] + df;
        for (auto cur : verts[fv]) {
            dif[cur] += inc;
        }
        verts[fu].insert(verts[fu].end(), ALL(verts[fv]));

    }
};

vector<pii> g[N];
vi not_empty;



void smain() {
    int dum, n;
    cin >> dum >> dum >> n;
    fori (_, n) {
        int x, y, a;
        cin >> x >> y >> a;
        g[x].push_back({y, a});
    }
    fori (x, N) {
        sort(ALL(g[x]));
        if (!g[x].empty())
            not_empty.push_back(x);
    }
    DSU dsu;
    for (auto x : not_empty) {
        for (auto py : g[x]) {
            int y = py.first;
            int val = py.second;
            if (!dsu.have_set(y)) {
                dsu.make_set(y);
            }
            dsu.union_sets(y, g[x][0].first, g[x][0].second - val);
        }
    }
    vi min_val(N, 0);
    fori (i, N) {
        if (dsu.have_set(i)) {
            for (auto cur : dsu.verts[i]) {
                inmax(min_val[i], -dsu.dif[cur]);
            }
        }
    }
    for (auto x : not_empty) {
        for (auto py : g[x]) {
            int y = py.first;
            int val = py.second;
            int pivot_val = val - dsu.dif[y];
            if (pivot_val < min_val[dsu.find_set(y)]) {
                out_and_exit(false);
            }
        }
    }
    out_and_exit(true);
}

