bool trace(
    grid_type::iterator r1itor,
    vec_type::iterator r1c1itor,
    vec_type::iterator r1c2itor
) {
    const auto& r1 = r1itor->first;
    const auto& c1 = r1c1itor->first;
    const auto& c2 = r1c2itor->first;
    const auto& r1c1a = r1c1itor->second;
    const auto& r1c2a = r1c2itor->second;
    auto delta = c1 - c2;
    for (int s = -1; s <= 1; s += 2) {
        auto r2 = r1 + s*delta;
        auto r2itor = rows.find(r2);
        if (r2itor == rows.end()) continue;
        auto& r2cols = r2itor->second;
        auto r2c1itor = r2cols.find(c1);
        auto r2c2itor = r2cols.find(c2);
        if (r2c1itor != r2cols.end()) {
            const auto& r2c1a = r2c1itor->second;
            if (r2c2itor != r2cols.end()) {
                const auto& r2c2a = r2c2itor->second;
                return r1c1a + r2c2a == r1c2a + r2c1a;
            }  else {
                const auto& r2c2a = r1c2a + r2c1a - r1c1a;
                if (r2c2a < 0) return false;
                rows[r2][c2] = r2c2a;
                cols[c2][r2] = r2c2a;
            }
        } else if (r2c2itor != r2cols.end()) {
            const auto& r2c2a = r2c2itor->second;
            const auto& r2c1a = r1c1a + r2c2a - r1c2a;
            if (r2c1a < 0) return false;
            rows[r2][c1] = r2c1a;
            cols[c1][r2] = r2c1a;
        }
    }
    return true;
}

