map<int,int> change(map<int,int> m) {
	vector<pair<int,int>> w;
	for(auto p : m) w.push_back(p);
	int best = 0;
	map<int,int> nowy;
	for(int i = (int) w.size() - 1; i >= 0; --i) {
		if(i == (int) w.size() - 1 || w[i].first + 1 != w[i+1].first)
			best = 0;
		best = max(0, best + w[i].second);
		nowy[w[i].first] = best;
	}
	return nowy;
}

