vector<vector<int> > adj;
vector<int> U, V, W;
vector<int> vis;
vector<int> val;
vector<int> ver;
vector<int> low;

void dfs(int u) {
    ver.push_back(u);
    vis[u] = 1;
    for(int i = 0; i < adj[u].size(); i++) {
        int e = adj[u][i];
        int v = V[e];
        int w = W[e];
        if(vis[v]) continue;
        val[v] = val[u] + w;
        dfs(v);
    }
}

int main() {
    scanf("%d %d %d", &R, &C, &N);
    Row.resize(R);
    for(int i = 0; i < N; i++) {
        int r, c, a; scanf("%d %d %d", &r, &c, &a);
        r--; c--;
        Row[r].push_back(pii(c, a));
    }
    adj.resize(C);
    for(int i = 0; i < R; i++) {
        sort(Row[i].begin(), Row[i].end());

        for(int j = 0; j < (int)Row[i].size() - 1; j++) {
            int u = Row[i][j].first;
            int v = Row[i][j + 1].first;
            int w = Row[i][j + 1].second - Row[i][j].second;

            adj[u].push_back(U.size());
            U.push_back(u);
            V.push_back(v);
            W.push_back(w);
            adj[v].push_back(U.size());
            U.push_back(v);
            V.push_back(u);
            W.push_back(-w);
        }
    }

    vis = vector<int>(C, 0);
    val = vector<int>(C, 0);
    low = vector<int>(C, 0);
    for(int i = 0; i < C; i++) if(!vis[i]) {
        ver.clear();
        dfs(i);

        int mn = 1e9;
        for(int j = 0; j < ver.size(); j++) {
            mn = min(mn, val[ver[j]]);
        }
        for(int j = 0; j < ver.size(); j++) {
            low[ver[j]] = val[ver[j]] - mn;
        }
    }
    for(int i = 0; i < U.size(); i++) {
        int u = U[i];
        int v = V[i];
        int w = W[i];

        if(val[u] + w != val[v]) {
            printf("No");
            return 0;
        }
    }
    for(int i = 0; i < R; i++) {
        for(int j = 0; j < Row[i].size(); j++) {
            int c = Row[i][j].first;
            int a = Row[i][j].second;

            if(a < low[c]) {
                printf("No");
                return 0;
            }
        }
    }

    printf("Yes");
}

