        G = vector<vector<edge>>(V, vector<edge>(0));
    }

    void add_edge(int from, int to, int cost){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    bool dfs(vector<bool> &used, int &M, int &m, int s, int v, vec &val, int c, vec &par){
        used[v] = true;
        val[v] = c;
        par[v] = s;
        M = max(M, c);
        m = min(m, c);
        REP(i, G[v].size()){
            if(used[G[v][i].to]){
                if(val[G[v][i].to] != val[v] + G[v][i].cost) return false;
            }
            else{
                if(!dfs(used, M, m, s, G[v][i].to, val, c + G[v][i].cost, par)) return false;
            }
        }
        return true;
    }

};

