struct Node{
    int r, c, a;
};
Node A[N];

bool comp1(Node A, Node B)
{
    return A.r < B.r;
}

bool comp2(Node A, Node B)
{
    return A.c < B.c;
}


struct DSU{
    int root[N];
    vector<int> s[N];
    int val[N];
    int mv[N];

    int Root(int x)
    {
        if (x == root[x]) return x;
        return Root(root[x]);
    }

    void Merge(int v, int u, int w)
    {
        int x = Root(v);
        int y = Root(u);
        if (x == y)
        {
            int W = val[v] - val[u];
            if (W != w)
            {
                cout << "No";
                exit(0);
            }
            return;
        }
        if (s[x].size() > s[y].size())
        {
            swap(x, y);
            swap(v, u);
            w *= -1;
        }
        int W = val[u] + w - val[v];
        for (auto e : s[x])
        {
            s[y].push_back(e);
            val[e] += W;
        }
        root[x] = y;
        return;
    }

    void calc()
    {
        for (int i = 0; i < N; i++)
        {
            int mn = 2e9;
            if (root[i] == i)
            {
                for (auto it : s[i])
                    mn = min(mn, val[it]);
            }
            mv[i] = mn;
        }
    }
}P, Q;

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m >> k;
    for (int i = 0; i < k; i++)
    {
        cin >> A[i].r >> A[i].c >> A[i].a;
    }
    for (int i = 1; i < N; i++) P.root[i] = i, P.s[i] = {i}, P.val[i] = 0;
    for (int i = 1; i < N; i++) Q.root[i] = i, Q.s[i] = {i}, Q.val[i] = 0;
    sort(A, A + k, comp1);
    for (int i = 1; i < k; i++)
    {
        if (A[i].r == A[i - 1].r)
        {
            P.Merge(A[i].c, A[i - 1].c, A[i].a - A[i - 1].a);
        }
    }
    sort(A, A + k, comp2);
    for (int i = 1; i < k; i++)
    {
        if (A[i].c == A[i - 1].c)
        {
            Q.Merge(A[i].r, A[i - 1].r, A[i].a - A[i - 1].a);
        }
    }
    P.calc(), Q.calc();
    for (int i = 0; i < k; i++)
    {
        int fi = P.val[A[i].c] + Q.val[A[i].r];
        int mv = P.mv[P.Root(A[i].c)] + Q.mv[Q.Root(A[i].r)];
        if (A[i].a - fi + mv < 0) cout << "No", exit(0);
    }
    cout << "Yes";
}

