bool check_local(int y, int x){
  int a = (in.count(make_pair(y,x))>0)?in[make_pair(y,x)]:-1;
  int b = (in.count(make_pair(y,x+1))>0)?in[make_pair(y,x+1)]:-1;
  int c = (in.count(make_pair(y+1,x))>0)?in[make_pair(y+1,x)]:-1;
  int d = (in.count(make_pair(y+1,x+1))>0)?in[make_pair(y+1,x+1)]:-1;
  //cout << y << " " << x << endl;
  //cout << " " << a << " " << b << endl;
  //cout << " " << c << " " << d << endl;
  int minus = 0;
  if(a<0) minus++;
  if(b<0) minus++;
  if(c<0) minus++;
  if(d<0) minus++;
  if(minus == 0){
    if(a+d == b+c) return true;
    else return false;
  }
  if(minus == 1){
    if(a==-1){
      if(b+c>=d){
        in2[make_pair(y,x)] = b+c-d;
        return true;
      }
      else return false;
    }
    if(b==-1){
      if(a+d>=c){
        in2[make_pair(y,x+1)] = a+d-c;
        return true;
      }
      else return false;
    }
    if(c==-1){
      if(a+d>=b){
        in2[make_pair(y+1,x)] = a+d-b;
        return true;
      }
      else return false;
    }
    if(d==-1){
      if(b+c>=a){
        in2[make_pair(y+1,x+1)] = b+c-a;
        return true;
      }
      else return false;
    }
  }
  return true;
}
bool check2x2(){
  FOR(it,in){
    int y = (it->first).first;
    int x = (it->first).second;
    int a = it->second;

    //left-top
    if(y<R-1 && x<C-1){
      if(!check_local(y,x)) return false;
    }
    //right-top
    if(y<R-1 && x>0){
      if(!check_local(y,x-1)) return false;
    }
    //left-bottom
    if(y>0 && x<C-1){
      if(!check_local(y-1,x)) return false;
    }
    //right-bottom
    if(y>0 && x>0){
      if(!check_local(y-1,x-1)) return false;
    }
  }
  return true;
}

