    if(!check2x2()){
      cout << "No" << endl;
      return 0;
    }

    if(in2.size() == 0) break;
    FOR(it,in2){
      in[it->first] = it->second;
    }
    in2.clear();
  }

  cout << "Yes" << endl;
  return 0;
}

