#include <bits/stdc++.h>
using namespace std;

typedef long long ll; 
typedef pair<int,int> pii; 

const int maxN = 100 * 1000 + 100; 
pair<pii,int> a[maxN]; 
int r,n;

int last[maxN]; 
bool possib;
vector<pair<int,int>> c[maxN]; 
int dis[maxN]; 
int mark[maxN]; 
int mn[maxN];
int dp[maxN]; 

void dfs( int s ) { 
	mark[s] = true; 
	for( auto x : c[s] ) { 
		if( !mark[x.first] ) { 
			dis[x.first] = dis[s] + x.second; 
			dfs( x.first ); 
		} else if( dis[s] + x.second != dis[x.first] ) { 
			possib = false; 
		}
		dp[s] = min( dp[s] , dp[x.first] + x.second ); 
	}
	if( mn[s] + dp[s] < 0 ) 
		possib = false; 
}

inline bool canDo() { 
	memset( last , -1 , sizeof last ); 
	memset( mark , 0 , sizeof mark ); 
	memset( mn , 63 , sizeof mn ); 
	memset( dis , 0 , sizeof dis ) ;
	memset( dp , 0 , sizeof dp ); 
	sort( a , a + n ); 
	for( int i = 0 ; i < n ; i++ ) { 
		auto x = a[i].first;
		if( last[x.second] != -1 ) { 
			int row = a[last[x.second]].first.first;
			c[row].push_back( { x.first , a[i].second - a[last[x.second]].second } ); 
		}
		last[x.second] = i;
		mn[x.first] = min(mn[x.first],a[i].second); 
	}

	possib = true; 
	for( int i = 0 ; i < maxN ; i++ ) { 
		if( c[i].size() && !mark[i] ) 
			dfs(i); 
		c[i].clear(); 
	}
	return possib; 
}

