    int H, W, N;
    cin >> H >> W >> N;
    vector<pair<PII, int>> ps(N);
    rep(i, N) {
        int y, x, a;
        cin >> y >> x >> a;
        --y; --x;
        ps[i] = MP(MP(y, x), a);
    }

    sort(ALL(ps));

    VVPII ys(H);
    rep(i, N) {
        int y = ps[i].fst.fst;
        int x = ps[i].fst.snd;
        int a = ps[i].snd;
        ys[y].EB(x, a);
    }


    bool flg = true;
    priority_queue<PII, VPII, greater<PII>> q; // y, idx
    VLL sums(W, INFL);

    rep(y, H) {
        if (ys[y].size()) {
            q.push(MP(y, 0));
        }
    }

    VLL bases(H, INFL);

    while (q.size() && flg) {
        int y = q.top().fst;
        int i = q.top().snd;
        int x = ys[y][i].fst;
        int a = ys[y][i].snd;
        q.pop();

        if (bases[y] == INFL) {
            bases[y] = a;
        }

        int j = i + 1;
        if (j >= (int)ys[y].size()) continue;

        int nx = ys[y][j].fst;
        int na = ys[y][j].snd;

        LL diff = na - a;

        if (sums[x] == INFL) {
            if (sums[nx] == INFL) { // xx
                sums[x] = 0;
                sums[nx] = diff;
            } else { // xo
                sums[x] = sums[nx] - diff;
            }
        } else {
            if (sums[nx] == INFL) { // ox
                sums[nx] = sums[x] + diff;
            } else { // oo
                if (sums[nx] != sums[x] + diff) {
                    flg = false;
                    break;
                }
            }
        }

        q.push(MP(y, j));
    }


    LL min_sum = *min_element(ALL(sums));

    rep(y, H) {
        if (bases[y] == INFL) continue;
        LL base = bases[y];

        if (base + min_sum < 0) flg = false;
    }


    cout << (flg ? "Yes" : "No") << endl;



    return 0;
}

