using namespace std;
vector<pair<int,ll> >e[2*N+5];
int vis[2*N+5];
ll val[2*N+5];
ll up,down;
bool dfs(int u)
{
    int f = 1;
    if(u<=N)up = min(up,val[u]);
    else down = min(down,val[u]);
    vis[u] = 1;
    for(auto v:e[u])
    {
        int to = v.FT;
        ll w = v.SD;
        if(vis[to])
        {
            if(val[to]!=w-val[u])return 0;
            continue;
        }
        val[to] = w-val[u];
        f = f&dfs(to);
    }
    return f;
}
int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int r,c,n;
    while(cin>>r>>c)
    {
        cin>>n;
        MST(vis,0);
        FOR(i,1,2*N-1)e[i].clear();
        FOR(i,1,n)
        {
            int x,y,z;
            cin>>x>>y>>z;
            e[x].PB(MP(N+y,z));
            e[N+y].PB(MP(x,z));
        }
        int f = 1;
        FOR(i,1,2*N)
        {
            if(!vis[i])
            {
                up = down = INF;
                val[i] = 0;
                f = f&dfs(i);
                if(up+down<0)f = 0;
                if(!f)break;
            }
        }
        if(f)cout<<"Yes"<<endl;
        else cout<<"No"<<endl;
    }
    return 0;
}

