struct node{
    int r, c, n;
};

vector<int> row, col;
vector<vector<node>> GR, GC;

void dfs(node nd){
    int r = nd.r, c = nd.c, n = nd.n;
    if(row[r] == inf && col[c] == inf){
        row[r] = n, col[c] = 0;
    }
    else if(row[r] == inf){
        row[r] = n - col[c];
    }
    else if(col[c] == inf){
        col[c] = n - row[r];
    }
    else return;
    for(node nr: GR[r]){
        dfs(nr);
    }
    for(node nc: GC[c]){
        dfs(nc);
    }

}

