void solve(){
    int r,c,n;
    cin >> r >> c >> n;
    vector<vector<pair<int,int>>> graph(r+c);
    rep(i,0,n){
        int x,y,a;
        cin >> y >> x >> a;
        --y;
        --x;
        graph[y].push_back(make_pair(x+r,a));
        graph[x+r].push_back(make_pair(y,a));
    }

    vector<int> val(r+c);
    vector<bool> done(r+c);
    int min_y,min_x;
    function<bool(int)> dfs=[&](int u){
        if(u<r) min_y=min(min_y,val[u]);
        else min_x=min(min_x,val[u]);
        for(auto &e:graph[u]){
            if(done[e.first]){
                if(val[u]+val[e.first]!=e.second) return false;
                continue;
            }
            done[e.first]=true;
            val[e.first]=e.second-val[u];
            if(!dfs(e.first)) return false;
        }
        return true;
    };
    rep(i,0,r+c){
        if(done[i]) continue;
        done[i]=true;
        val[i]=0;
        min_y=min_x=inf;
        if(!dfs(i) or min_y+min_x<0){
            cout << "No" << endl;
            return;
        }
    }
    cout << "Yes" << endl;
}

