int r,c,n,p=1,t;
int fx[N+5],fy[N+5];
ll wx[N+5],wy[N+5],hh1[N+5],hh2[N+5];
struct node
{
    int x,y; ll h;
    node(){}inline node(int x_,int y_,ll h_){x=x_;y=y_;h=h_;}
}a[N+5];
inline bool cmp1(node a,node b){return a.x<b.x;}
inline bool cmp2(node a,node b){return a.y<b.y;}
inline int find_x(int x)
{
    if(fx[x]==x)return fx[x];
    int y=find_x(fx[x]);
    wx[x]+=wx[fx[x]];
    return fx[x]=y;
}
inline int find_y(int x)
{
    if(fy[x]==x)return fy[x];
    int y=find_y(fy[x]);
    wy[x]+=wy[fy[x]];
    return fy[x]=y;
}
inline int hb_x(int x,int y,ll l)
{
    int a=find_x(x),b=find_x(y);
    if(a==b)return wx[x]==l+wx[y];
    fx[a]=b;
    wx[a]=l+wx[y]-wx[x];
    return 1;
}
inline int hb_y(int x,int y,ll l)
{
    int a=find_y(x),b=find_y(y);
    if(a==b)return wy[x]==l+wy[y];
    fy[a]=b;
    wy[a]=l+wy[y]-wy[x];
    return 1;
}
inline int work()
{
    for(int i=0;i<=N+2;i++)fy[i]=fx[i]=i;
    //for(int i=0;i<=c;i++)fy[i]=i;
