    }
    if(p==0)return 0;
    sort(a+1,a+n+1,cmp1);
    for(int i=1;i<n;i++)
       if(a[i].x==a[i+1].x&&!hb_y(a[i].y,a[i+1].y,a[i+1].h-a[i].h))
           return 0;
    sort(a+1,a+n+1,cmp2);
    for(int i=1;i<n;i++)
       if(a[i].y==a[i+1].y&&!hb_x(a[i].x,a[i+1].x,a[i+1].h-a[i].h))
           return 0;
    for(int i=1;i<=n;i++)
    {
        int x=find_x(a[i].x);
        hh1[x]=min(hh1[x],a[i].h+wx[a[i].x]);
    }
    for(int i=1;i<=r;i++)
    {
        int x=find_x(i);
        hh2[x]=min(hh2[x],-wx[i]);
    }
    for(int i=1;i<=r;i++)
        if(fx[i]==i&&hh1[i]+hh2[i]<0)
            return 0;
    return 1;
}
