LL value[100005];
LL R , C , n;
vector<int> values[100005];
int find(int u)
{
	if(u == p[u])
		return u;
	return p[u] = find(p[u]);
}
void init()
{
	for(LL i = 1; i <= R; i++)
	{
		p[i] = i;
		values[i].PB(i);
	}
}
int main()
{
	ios_base::sync_with_stdio(0);

	cin >> R >> C >> n;
	for(LL i = 0; i < n; i++)
		rowMin[i] = INF * (LL) INF;

	for(LL i = 0; i < n; i++)
	{
		LL r , c , a;
		cin >> r >> c >> a;
		rowMin[r] = min(rowMin[r] , a);
		cols[c].PB({r , a});
