			{
				for(auto x : values[v])
				{
					values[u].PB(x);
					value[x] += newDiff;
				}
				p[v] = u;
			}
		}
	}
	for(int i = 1; i <= R; i++)
	{
		if(p[i] == i)
		{
			LL minima = INF * (LL)INF;
			for(auto x : values[i])
				minima = min(minima , value[x]);
			for(auto x : values[i])
			{
				if(value[x] - minima > rowMin[x])
				{
					cout << "No" << endl;
					return 0;
				}
			}
		}
	}


	cout << "Yes" << endl;
	return 0;
}

