void dfs(vector<vector<vector<int>>> &e, vector<vector<vector<int>>> &v, vector<vector<int>> &used, vector<vector<int>> &ab, int aorb, int k, int val, int &f, vector<int> &mins){
	if(used[aorb][k] == 0){
		used[aorb][k] = 1;
		ab[aorb][k] = val;
		mins[aorb] = min(mins[aorb], val);
		for(int i = 0; i < e[aorb][k].size(); i++){
			dfs(e, v, used, ab, 1 - aorb, e[aorb][k][i], v[aorb][k][i] - val, f, mins);
		}
	}
	else{
		if(ab[aorb][k] != val){
			f = 1;
		}
	}
}

