const int N = 1e5 + 10;
Node a[N];

int main() {
  int R, C, n;
  scanf("%d%d%d", &R, &C, &n);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d%d", &a[i].x, &a[i].y, &a[i].v);
    --a[i].x; --a[i].y;
  }
  sort(a, a + n);
  vector<int> delta(R);
  vector<int> visit(C, -INF);
  for (int i = 0, j; i < n; i = j) {
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      if (visit[a[j].y] >= 0) {
        delta[a[j].x] = a[j].v - visit[a[j].y];
        break;
      }
    }
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      a[j].v -= delta[a[j].x];
      if (visit[a[j].y] == -INF) {
        visit[a[j].y] = a[j].v;
      } else if (visit[a[j].y] != a[j].v) {
        puts("No");
        return 0;
      }
    }
  }
  int minv = INF, maxv = -INF;
  for (int i = 0; i < C; ++i) {
    if (visit[i] != -INF) {
      minv = min(minv, visit[i]);
      maxv = max(maxv, visit[i]);
    }
  }
  for (int i = 0; i < R; ++i) {
    if (minv + delta[i] < 0) {
      puts("No");
      return 0;
    }
  }
  puts("Yes");
  return 0;
}

