{
  ll from;
  ll to;
  ll len;
  Data(){};
  Data(ll f,ll t,ll l): from(f), to(t), len(l){};
  bool operator<( const Data& r ) const {
    return (from==r.from)?(to<r.to):(from<r.from);
  }
};

bool ok(vector<vector<Pll>> &X,ll s1,ll s2)
{
  // cerr << s1 << " " << s2 << endl;
  vector<Data> arr;
  REP(i,s1)
  {
    if(X[i].size()<=1) continue;
    sort(X[i].begin(),X[i].end());
    REP(j,X[i].size()-1)
      arr.push_back(Data(X[i][j].first,X[i][j+1].first,X[i][j+1].second-X[i][j].second));
  }
  sort(arr.begin(),arr.end());
  vector<ll> Y(s2,LLINF);
  Y[0]=0;
  for(auto x : arr)
  {
    // cerr << x.from << " " << x.to << " " << x.len << endl;
    if(Y[x.from]==LLINF && Y[x.to]==LLINF)
    {
      Y[x.from]=0;
      Y[x.to]=x.len;
    }
    else
    {
      if(Y[x.from]==LLINF) Y[x.from]=Y[x.to]-x.len;
      else if(Y[x.to]==LLINF) Y[x.to]=Y[x.from]+x.len;
      else if(Y[x.to]-Y[x.from]!=x.len) return false;
    }
  }
  // vector<ll> Z(s2,0);
  // FOR(i,1,s2-1)
  // {
  //   Z[i]=Z[i-1]+Y[i];
  // }
  // priv(Y);
  // priv(Z);
  REP(i,s1)
  {
    REP(j,X[i].size())
    {
      if(Y[X[i][j].first]+X[i][j].second<0) return false;
    }
  }
  return true;
}

