void dfs(int v){
    used1[v] = 1;
    if (r[v] == -1e18){
        r[v] = 0;
    }
    v1 = min(v1, r[v]);
    queue < int > q;
    for (auto u: gr[v]){
        c[u.F] = u.S - r[v];
        v2 = min(c[u.F], v2);
        if (used2[u.F]) continue;
        used2[u.F] = 1;
        for (auto u2: gc[u.F]){
            if (used1[u2.F]) continue;
            r[u2.F] = u2.S - c[u.F];
            v1 = min(v1, r[u2.F]);
            q.push(u2.F);
            used1[u2.F] = 1;
        }
    }
    while(!q.empty()){
        dfs(q.front());
        q.pop();
    }
}
