    scanf("%d%d%d",&x,&y,&a);
    ps[i] = pii(x,y);
    val[i] = a;
    Sx.push_back(x);
    Sy.push_back(y);
  }
  Sx.erase(unique(ALL(Sx)),Sx.end());
  Sy.erase(unique(ALL(Sy)),Sy.end());
  REP(i,Sx.size()){
    Mx[Sx[i]] = i;
  }
  REP(i,Sy.size()){
    My[Sy[i]] = i;
  }
  r = Sx.size();
  c = Sy.size();

  REP(i,125252)xmin[i] = INF;
  REP(i,n){
    int x,y;
    x=Mx[ps[i].first];
    y=My[ps[i].second];
    CHMIN(xmin[y],val[i]);
    ys[x].push_back(pii(y,val[i]));
    ps[i] = pii(x,y);
  }
  // graph
  REP(i,r){
    sort(ALL(ys[i]));
    vector<pii> &vec = ys[i];
    REP(j,vec.size()-1){
      int s,t;
      s = vec[j].first;
      t = vec[j+1].first;
      int sa = vec[j+1].second - vec[j].second;
      g[s].push_back(pii(t,sa));
      g[t].push_back(pii(s,-sa));
    }
  }
