int constrained(int i,int j,vector<vector<int> > a){
    int real=0;
    int fake=0;
    bool found=false;
    if(i>0 && j>0){
        if(a[i-1][j-1]!=-1 && a[i-1][j]!=-1 && a[i][j-1]!=-1){
            real=-a[i-1][j-1]+a[i-1][j]+a[i][j-1];
            found=true;
        }
    }
    if(i>0 && j<a[i].size()-1){
        if(a[i-1][j]!=-1 && a[i-1][j+1]!=-1 && a[i][j+1]!=-1){
            int real2=-a[i-1][j+1]+a[i-1][j]+a[i][j+1];
            if(real!=-1 && real2!=real)
                return -2;
            real=real2;
            found=true;
        }
    }
    if(i<a.size()-1 && j>0){
        if(a[i][j-1]!=-1 && a[i+1][j-1]!=-1 && a[i+1][j]!=-1){
            int real2=-a[i+1][j-1]+a[i][j-1]+a[i+1][j];
            if(real!=-1 && real2!=real)
                return -2;
            real=real2;
            found=true;
        }
    }
    if(i<a.size()-1 && j<a[i].size()-1){
        if(a[i][j+1]!=-1 && a[i+1][j]!=-1 && a[i+1][j+1]!=-1){
            int real2=-a[i+1][j+1]+a[i+1][j]+a[i][j+1];
            if(real!=-1 && real2!=real)
                return -2;
            real=real2;
            found=true;
        }
    }
    if(!found){
        return 0;
    }
    return real;
}
