vpi col[N], str[N];
int used[N], val[N], gval[N], label = 1;
vpi g[N];


void dfs(int v, int vl)
{
    used[v] = 1;
    val[v] = vl;

    for (pii p : g[v])
    {
        if (used[p.first])
        {
            if (val[p.first] != vl + p.second)
                label = 0;
        }
        else
            dfs(p.first, vl + p.second);
    }
}


void dfs_init(int v, int last = -1, int p = -1)
{
    if (p != -1)
        g[v].erase(find(ALL(g[v]), mp(p, -last)));

    used[v] = 1;
    vpi hui;

    for (auto p : g[v])
    {
        if (used[p.first])
        {
            hui.push_back(p);
        }
        else
        {
            dfs_init(p.first, p.second, v);
        }
    }

    for (auto p : hui)
        g[v].erase(find(ALL(g[v]), p));
}


int dp_down[N];


void dfs_down(int v, int p = -1)
{
    dp_down[v] = 0;

    for (auto p : g[v])
        dfs_down(p.first, v);

    for (auto p : g[v])
        dp_down[v] = min(dp_down[v], dp_down[p.first] + p.second);
}


bool dfs_up(int v, int p = -1, int dp_up = 0, int last = 0)
{
    int cval = dp_up + -last;
    if (min(cval, dp_down[v]) + gval[v] < 0)
        return 0;

    cval = dp_up + -last;
    vi hui, pr, sf;

    for (auto p : g[v])
        hui.push_back(dp_down[p.first] + p.second);

    pr = hui, sf = hui;
    for (int i = 1; i < SZ(pr); ++i)
        pr[i] = min(pr[i], pr[i - 1]);

    for (int i = SZ(sf) - 2; i >= 0; --i)
        sf[i] = min(sf[i], sf[i + 1]);

    bool label = 1;
    for (int i = 0; i < SZ(g[v]); ++i)
    {
        auto p = g[v][i];
        int cnt = cval;
        if (i)
            cnt = min(cnt, pr[i - 1]);

        if (i + 1 != SZ(g[v]))
            cnt = min(cnt, sf[i + 1]);

        label = min(label, dfs_up(p.first, v, cnt, p.second));
    }

    return label;
}


