using namespace std;
#define MAX_N 220000
#define INF 1LL << 47
vector<pair<long long, long long> >x_1[MAX_N];
long long x_sa[MAX_N], y_sa[MAX_N];
long long N, H, W, x[MAX_N], y[MAX_N], a[MAX_N];

void initialize() {
	for (long long i = 0; i < MAX_N; i++) {
		sort(x_1[i].begin(), x_1[i].end());
		y_sa[i] = INF; x_sa[i] = INF;
	}
}
bool solve_ai() {
	for (long long i = 0; i < MAX_N; i++) {
		long long sa = 0LL;
		for (long long j = 0; j < x_1[i].size(); j++) {
			if (y_sa[x_1[i][j].first] != (INF)) sa = y_sa[x_1[i][j].first] - x_1[i][j].second;
		}
		for (long long j = 0; j < x_1[i].size(); j++) {
			if (y_sa[x_1[i][j].first] != (INF)) {
				if (sa != y_sa[x_1[i][j].first] - x_1[i][j].second)return false;
			}
			else y_sa[x_1[i][j].first] = sa + x_1[i][j].second;
		}
	}
	return true;
}
bool solve_bi() {
	for (long long i = 0; i < N; i++) x_sa[x[i]] = a[i] - y_sa[y[i]];
	long long minx = INF;
	for (long long i = 0; i < MAX_N; i++)minx = min(minx, y_sa[y[i]]);
	for (long long i = 0; i < MAX_N; i++) { x_sa[i] += minx; y_sa[i] -= minx; }
	for (long long i = 0; i < MAX_N; i++) {
		if (x_sa[i] < 0LL || y_sa[i] < 0LL)return false;
	}
	for (int i = 0; i < N; i++) {
		if (x_sa[x[i]] + y_sa[y[i]] != a[i])return false;
	}
	return true;
}
int main() {
	cin >> H >> W >> N;
	for (long long i = 0; i < N; i++) {
		cin >> x[i] >> y[i] >> a[i];
		x_1[x[i]].push_back(make_pair(y[i], a[i]));
	}
	initialize();
	if (solve_ai() == false || solve_bi() == false) { cout << "No" << endl; }
	else { cout << "Yes" << endl; }
	return 0;
}

