bool isIllegal(ull ri, ull ci) {
    int ai = field[C * ri + ci];

    for (int j = 0; j < 4; j++) {
        ull y = ri + dy[j];
        ull x = ci + dx[j];
        if (x < 0 || C <= x || y < 0 || R <= y) continue;

        int cnt =
            1 + filled[C * ri + x] + filled[C * y + ci] + filled[C * y + x];
        if (cnt <= 2) continue;
        if (cnt == 4) {
            if (ai + field[C * y + x] !=
                field[C * ri + x] + field[C * y + ci]) {
                return true;
            }
        } else if (!filled[C * ri + x]) {
            int temp = ai + field[C * y + x] - field[C * y + ci];
            field[C * ri + x] = temp;
            filled[C * ri + x] = true;
            v.push_back(make_pair(ri, x));
            flag = false;
            if (temp < 0) return true;
        } else if (!filled[C * y + ci]) {
            int temp = ai + field[C * y + x] - field[C * ri + x];
            field[C * y + ci] = temp;
            filled[C * y + ci] = true;
            v.push_back(make_pair(y, ci));
            flag = false;
            if (temp < 0) return true;
        } else if (!filled[C * y + x]) {
            int temp = field[C * ri + x] + field[C * y + ci] - ai;
            field[C * y + x] = temp;
            filled[C * y + x] = true;
            v.push_back(make_pair(y, x));
            flag = false;
            if (temp < 0) return true;
        }
    }
    return false;
}

