        v.push_back(make_pair(r, c));
        field[C * r + c] = a;
        filled[C * r + c] = true;
    }

    while(1){
        flag = true;
        for (int i = 0; i < v.size(); i++) {
            if (isIllegal(v[i].first, v[i].second)) {
                cout << "No" << endl;
                return 0;
            }
        }
        if(flag) break;
    }

    cout << "Yes" << endl;

    return 0;
}

