}

bool tryFill3(int i, int j){
  if(E.count(make_pair(i,j))==0){
    int f = M[i+1][j]+M[i][j+1]-M[i+1][j+1];
    if (f<0) return false;
    E.insert(make_pair(i,j)); M[i][j]=f;
  } else if(E.count(make_pair(i+1,j))==0){
    int f = M[i][j]+M[i+1][j+1]-M[i][j+1];
    if (f<0) return false;
    E.insert(make_pair(i+1,j)); M[i+1][j]=f;
  } else if(E.count(make_pair(i,j+1))==0){
    int f = M[i][j]+M[i+1][j+1]-M[i+1][j];
    if (f<0) return false;
    E.insert(make_pair(i,j+1)); M[i][j+1]=f;
  } else if(E.count(make_pair(i+1,j+1))==0){
    int f = M[i+1][j]+M[i][j+1]-M[i][j];
    if (f<0) return false;
    E.insert(make_pair(i+1,j+1)); M[i+1][j+1]=f;
  }
  return true;
}

bool tryLoop(){
  int again = false;
  for (size_t i = 1; i < R; i++) {
    for (size_t j = 1; j < C; j++) {
      int fillcount = E.count(make_pair(i,j))+E.count(make_pair(i+1,j))+E.count(make_pair(i,j+1))+E.count(make_pair(i+1,j+1));
