typedef long long ll;

const ll INF = 1e12 + 5;
const int MAX_N = 2e5 + 5;
const int COLS = 1e5;

int row (int idx) {
  return idx;
}

int col (int idx) {
  return idx + COLS;
}

int vis [MAX_N];
ll val [MAX_N];
vector<pair<int, ll>> adj [MAX_N];

void dfs (int u, ll &rm, ll &cm) {
  vis[u] = 1;
  if (u < COLS) rm = min(rm, val[u]);
  else cm = min(cm, val[u]);

  for (auto nxt : adj[u]) {
    if (!vis[nxt.first]) {
      val[nxt.first] = nxt.second - val[u];
      dfs(nxt.first, rm, cm);
    } else if (val[nxt.first] != nxt.second - val[u]) {
      failure();
    }
  }
}

