    adj[col(c)].push_back({row(r), a});
  }

  for (int i = 1; i <= R; i++) {
    if (!vis[row(i)]) {
      ll rm = INF, cm = INF;
      dfs(row(i), rm, cm);
      if (rm + cm < 0) failure();
    }
  }

  cout << "Yes" << endl;
}

