using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const int N = 100 * 1000 + 10;
const int dx[] = {-1, 1};

map<pii, int> val;
bool ok = true;

int r, c, n;

bool valid(int x, int y) {
    return x >= 0 && x < r && y >= 0 && y < c;
}

bool valid(pii p) {
    return valid(p.first, p.second);
}

int getPos(int now, int i, int d) {
    return now + i * dx[d];
}

void dfs(int x, int y) {
    if (!ok)
        return;
    int cur_val = val[pii(x, y)];
    for (int d1 = 0; d1 < 2; d1++) {
        for (int d2 = 0; d2 < 2; d2++) {
            pii up = pii(getPos(x, 1, d1), y);
            pii right = pii(x, getPos(y, 1, d2));  
            pii diag = pii(getPos(x, 1, d1), getPos(y, 1, d2));
            auto iup = val.find(up);
            auto iright = val.find(right);
            auto idiag = val.find(diag);
            if (!valid(up) || !valid(right) || !valid(diag))
                continue;
            if (iup != val.end() && iright != val.end() && idiag != val.end()) {
                if (iup->second + iright->second != idiag->second + cur_val) {
                    ok = false;
                }
                continue;
            }
            bool done = false;
            if (iup != val.end() && iright != val.end()) {
                int nval = iup->second + iright->second - cur_val;
                if (nval < 0) {
                    ok = false;
                    return;
                }
                val[diag] = nval;
                dfs(diag.first, diag.second);
                done = true;
            }
            if (!done && iup != val.end() && idiag != val.end()) {
                int nval = cur_val + idiag->second - iup->second;
                if (nval < 0) {
                    ok = false;
                    return;
                }
                val[right] = nval;
                dfs(right.first, right.second);
                done = true;
            }
            if (!done && iright != val.end() && idiag != val.end()) {
                int nval = cur_val + idiag->second - iright->second;
                if (nval < 0) {
                    ok = false;
                    return;
                }
                val[up] = nval;
                dfs(up.first, up.second);
                done = true;
            }
        }
    }    
}

