bool check(bool yoyoyo){
  int a = node.size();
  REP(i,a)vere[node[i]] = i;
  REP(i,a)dist[i] = 0;
  REP(i,a)used[i] = false;
  dist[0] = 0;
  used[0] = true;
  queue<int> Q;
  Q.push(0);
  while(!Q.empty()){
    int p = Q.front(); Q.pop();
    int id = node[p];
    ll d = dist[p];
    REP(i,g[id].size()){
      int to = vere[g[id][i].first];
      ll cost = g[id][i].second;
      ll nd = d+cost;
      if(used[to]){
        if(dist[to]!=nd)return false;
      }else{
        dist[to] = nd;
        used[to] = true;
        Q.push(to);
      }
    }
  }
  // negative check
  if(yoyoyo){
    init(a,dist);
    REP(i,a){
      ll mn = query(0,a);
      if(mn + ys[node[i]][0] < 0){
        return false;
      }
      if(i==a-1)break;
      ll d = dist[i+1]-dist[i];
      add(0,i+1,d);
      add(i+1,a,-d);
    }
  }else{
    init(a,dist);
    REP(i,a){
      ll mn = query(0,a);
      if(mn + xs[node[i]][0] < 0){
        return false;
      }
      if(i==a-1)break;
      ll d = dist[i+1]-dist[i];
      add(0,i+1,d);
      add(i+1,a,-d);
    }
  }
  return true;
}

bool valid(int n,bool yoyoyo){
  REP(i,125252)po[i]=false;
  REP(i,n){
    if(po[i])continue;
    node.clear();
    po[i] = true;
    node.push_back(i);
    queue<int> Q;
    Q.push(i);
    while(!Q.empty()){
      int p = Q.front(); Q.pop();
      REP(j,g[p].size()){
        int to = g[p][j].first;
        if(po[to])continue;
        po[to] = true;
        node.push_back(to);
        Q.push(to);
      }
    }
    sort(ALL(node));
    // DEBUG("GO");
    // REP(j,node.size())DEBUG(node[j]);
    if(!check(yoyoyo))return false;
  }
  return true;
}

