    int r, c, a;
};
Node A[N];

bool comp1(Node A, Node B)
{
    return A.r < B.r;
}

bool comp2(Node A, Node B)
{
    return A.c < B.c;
}


struct DSU{
    int root[N];
    vector<int> s[N];
    int val[N];
    int mv[N];

    int Root(int x)
    {
        if (x == root[x]) return x;
        return Root(root[x]);
    }

    void Merge(int v, int u, int w)
    {
        int x = Root(v);
        int y = Root(u);
        if (x == y)
        {
            int W = val[v] - val[u];
            if (W != w)
            {
                cout << "No";
                exit(0);
            }
            return;
        }
        if (s[x].size() > s[y].size())
        {
            swap(x, y);
            swap(v, u);
            w *= -1;
        }
        int W = val[u] + w - val[v];
        for (auto e : s[x])
        {
            s[y].push_back(e);
            val[e] += W;
        }
        root[x] = y;
        return;
    }

    void calc()
    {
        for (int i = 0; i < N; i++)
        {
            int mn = 1e9;
            if (root[i] == i)
            {
                for (auto it : s[i])
                    mn = min(mn, val[it]);
            }
            mv[i] = mn;
        }
    }
}P, Q;

