    for (int i = 1; i < N; i++) Q.root[i] = i, Q.s[i] = {i}, Q.val[i] = 0;
    sort(A, A + k, comp1);
    for (int i = 1; i < k; i++)
    {
        if (A[i].r == A[i - 1].r)
        {
            P.Merge(A[i].c, A[i - 1].c, A[i].a - A[i - 1].a);
        }
    }
    sort(A, A + k, comp2);
    for (int i = 1; i < k; i++)
    {
        if (A[i].c == A[i - 1].c)
        {
            Q.Merge(A[i].r, A[i - 1].r, A[i].a - A[i - 1].a);
        }
    }
    P.calc(), Q.calc();
    for (int i = 0; i < k; i++)
    {
        int fi = P.val[A[i].c] + Q.val[A[i].r];
        int mv = P.mv[P.Root(A[i].c)] + Q.mv[Q.Root(A[i].r)];
