            int val = a[{x - 1, y}] + a[{x, y - 1}] - a[{x, y}];
            if (val < 0 || (a.count({x - 1, y - 1}) && a[{x - 1, y - 1}] != val)) {
                printf("No\n");
                return 0;
            }
        }
        if (a.count({x + 1, y}) && a.count({x, y - 1})) {
            int val = a[{x + 1, y}] + a[{x, y - 1}] - a[{x, y}];
            if (val < 0 || (a.count({x + 1, y - 1}) && a[{x + 1, y - 1}] != val)) {
                printf("No\n");
                return 0;
            }
        }
        if (a.count({x - 1, y}) && a.count({x, y + 1})) {
            int val = a[{x - 1, y}] + a[{x, y + 1}] - a[{x, y}];
            if (val < 0 || (a.count({x - 1, y + 1}) && a[{x - 1, y + 1}] != val)) {
                printf("No\n");
                return 0;
            }
        }
    }
    for (auto &e : a) {
        int x, y;
        tie(x, y) = e.first;
        if (a.count({x + 1, y + 1})) {
            int sm = a[{x, y}] + a[{x + 1, y + 1}];
            mn = min(mn, sm);
            mx = max(mx, sm);
        }
        if (a.count({x + 1, y - 1})) {
            int sm = a[{x, y}] + a[{x + 1, y - 1}];
            mn = min(mn, sm);
            mx = max(mx, sm);
        }
    }
    if (mx == -1 || (mn == mx && mz <= mx)) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }
}

