int pd[110000];
int qd[110000];
vector<pair<int,int> >row[110000];
vector<pair<int,int> >col[110000];
int cost[110000];
int v[110000];
int R[110000];
int C[110000];
int rind[110000];
int cind[110000];
int V[110000];
bool dame=false;
void dfs(int u,int a,int b){
	int r=R[u];
	int c=C[u];
	v[u]=1;
	if(pd[r]){
		if(p[r]!=a)dame=true;
	}else{
		pd[r]=1;
		p[r]=a;
	}
	if(qd[c]){
		if(q[c]!=b)dame=true;
	}else{
		qd[c]=1;
		q[c]=b;
	}
	if(rind[u]){
		int to=row[r][rind[u]-1].second;
		if(!v[to]){
			dfs(to,a,b+V[to]-V[u]);
		}
	}
	if(rind[u]+1<row[r].size()){
		int to=row[r][rind[u]+1].second;
		if(!v[to]){
			dfs(to,a,b+V[to]-V[u]);
		}
	}
	if(cind[u]){
		int to=col[c][cind[u]-1].second;
		if(!v[to]){
			dfs(to,a+V[to]-V[u],b);
		}
	}
	if(cind[u]+1<col[c].size()){
		int to=col[c][cind[u]+1].second;
		if(!v[to]){
			dfs(to,a+V[to]-V[u],b);
		}
	}

}
