		s--;t--;
		R[i]=s;C[i]=t;V[i]=u;
		cost[i]=u;
		row[s].push_back(make_pair(t,i));
		col[t].push_back(make_pair(s,i));
	}
	for(int i=0;i<a;i++)std::sort(row[i].begin(),row[i].end());
	for(int i=0;i<b;i++)std::sort(col[i].begin(),col[i].end());
	for(int i=0;i<a;i++){
		for(int j=0;j<row[i].size();j++){
			rind[row[i][j].second]=j;
		}
	}
	for(int i=0;i<b;i++){
		for(int j=0;j<col[i].size();j++){
			cind[col[i][j].second]=j;
		}
	}

	for(int i=0;i<c;i++){
		if(v[i])continue;
		dfs(i,V[i],0);
	}
	for(int i=0;i<c;i++){
		if(V[i]!=p[R[i]]+q[C[i]])dame=true;
	}
	if(dame){
