	int minRow = 1e9, minCol = 1e9;
	fill(limitCol, limitCol + c, 1e9);
	fill(limitRow, limitRow + r, 1e9);
	for(int i = 0; i < n; i++)
	{
		row[i] = in() - 1;
		col[i] = in() - 1;
		val[i] = in();
		inRow[row[i]].push_back(i);
		inCol[col[i]].push_back(i);
		a[row[i]][col[i]] = val[i];
		mark[row[i]][col[i]] = 1;
	}
	bad = false;
	for(int i = 0; i < n; i++)
	{
		if(row[i] == 0 || col[i] == 0)
			continue;
		val[i] += a[0][0];
		a[row[i]][col[i]] = val[i];
		limitRow[row[i]] = min(limitRow[row[i]], val[i]);
		limitCol[col[i]] = min(limitCol[col[i]], val[i]);
		if(a[row[i]][0] + a[0][col[i]] > val[i])
			bad = true;
		if(mark[row[i]][0] || mark[0][col[i]])
		{
			q.push(i);
			done[i] = 1;
		}
	}
	for(int i = 0; i < n; i++)
	{
		if(row[i] == 0 || col[i] == 0)
			continue;
		if(limitRow[row[i]] + limitCol[col[i]] < val[i])
			bad = true;
	}
	work(1);
	for(int i = 1; i < r; i++)
		if(mark[i][0])
			minRow = min(minRow, a[i][0]);
	for(int i = 1; i < c; i++)
		if(mark[0][i])
			minCol = min(minCol, a[0][i]);
	if(minRow + minCol < a[0][0])
		bad = true;

	for(int i = 0; i < n; i++)
	{
		if(row[i] == 0 || col[i] == 0)
			continue;
		if(!done[i])
			q.push(i);
	}
	work(0);
	if(bad)
		cout << "No\n";
	else
		cout << "Yes\n";
}

