  UF uf(c);
  vll offset(c, INF);
  rep (i, r) {
    if (ca[i].size() == 0) continue;
    if (offset[ca[i][0][0]] == INF) {
      offset[ca[i][0][0]] = 0;
    }
    rep (j, (int)ca[i].size() - 1) {
      ll s = offset[ca[i][j][0]] + ca[i][j+1][1] - ca[i][j][1];
      if (offset[ca[i][j+1][0]] == INF) {
        offset[ca[i][j+1][0]] = s;
      } else if (offset[ca[i][j+1][0]] != s) {
        if (uf.same(ca[i][j][0], ca[i][j+1][0])) {
          printf("No\n");
          return 0;
        } else {
          int x = ca[i][j+1][0];
          ll offset_adjust = s - offset[x];
          for (; x != -1; x = uf.get_next(x)) {
            offset[x] += offset_adjust;
          }
        }
      }
      uf.unite(ca[i][j][0], ca[i][j+1][0]);
    }
  }

  unordered_map<int, int> roots;
