	FORI(r,R) if (ux[r]) ux[r]=ir++;
	FORI(c,C) if (uy[c]) uy[c]=ic++;

	FOR(i,n) {
		X[ux[x[i]]].pb(mp(uy[y[i]], a[i]));
		Y[uy[y[i]]].pb(mp(ux[x[i]], a[i]));
	}

	R = ir;
	C = ic;

	FORI(i,R) sort(X[i].begin(), X[i].end());
	FORI(j,C) sort(Y[j].begin(), Y[j].end());

	// check negatives
	FOR(i,C) {
		M[i] = 1e9+4566;
		FOR(j,SZ(Y[i])) M[i] = min(M[i], Y[i][j].se);
	}

	FOR(r,R) {
		int mi = 1e9+234, ma = -1;
		FOR(c,SZ(X[r])) {
			mi = min(mi, X[r][c].se);
			ma = max(ma, X[r][c].se - M[X[r][c].fi]);
		}
		if (mi < ma) {
			printf("No\n");
			return 0;
		}
	}

	// check existing values

	FOR(r,R) {
