			dif[X[r][i].fi].pb(mp(X[r][i-1].fi, X[r][i].se-X[r][i-1].se));
			dif[X[r][i-1].fi].pb(mp(X[r][i].fi, X[r][i-1].se-X[r][i].se));
		}
	}

	ok = true;

	FORI(c,C-1) if (!vis[c]) {
		dfs(c);
	}


	printf("%s\n", ok ? "Yes" : "No");


	return 0;
}

