typedef long long ll;typedef vector<int> vi;typedef pair<int,int> pi;const int inf = (int)1e9;const double INF = 1e12, EPS = 1e-9;

struct uf{
	vi p;
	vector<ll> h;
	vector<set<int>> s;
	uf(int n){
		p.resize(n);
		h.resize(n);
		s.resize(n);
		rep(i, n){
			p[i] = i;
			s[i].insert(i);
		}
	}
	int root(int x){
		return x == p[x] ? x : (p[x] = root(p[x]));
	}
	bool merge(int a, int b, ll b_minus_a){
		int A = a, B = b;
		a = root(a); b = root(b);
		if(a == b){
			return h[B] - h[A] == b_minus_a;
		}
		if(s[a].size() < s[b].size()){
			swap(a, b);
			b_minus_a *= -1;
		}
		p[b] = a;

		ll d = h[A] - h[B] + b_minus_a;
		for(int i : s[b]){
			s[a].insert(i);
			h[i] += d;
		}
		return 1;
	}
};
bool check(vector<vector<pi>> &es){
	int n = es.size();
	uf *u_ = new uf(n);
	uf &u = *u_;

	rep(i, n) if(es[i].size() > 1){
		rep(j, es[i].size() - 1){
			pi a = es[i][j], b = es[i][j + 1];
			if(!u.merge(a.first, b.first, b.second - a.second)) return 0;
		}
	}
	map<int,ll> mnR;
	for(auto v : es) for(pi p : v){
		int pos = p.first, val = p.second, r = u.root(pos);
		ll mn = mnR.count(r) ? mnR[r] : 1e18;
		mnR[r] = mn = min(mn, val - u.h[pos]);
	}
	//dbg(mnR);
