    CININIT;
    cin>>R>>C>>N;
    r.resize(N);
    c.resize(N);
    a.resize(N);
    vector<int> needx,needy;

    rep(i,N){
        cin>>r[i]>>c[i]>>a[i];
        r[i]--;
        c[i]--;
        a[i]++;
        needx.PB(r[i]);
        if(r[i]+1<R) needx.emplace_back(r[i]+1);
        if(r[i]-1>=0) needx.emplace_back(r[i]-1);

        needy.emplace_back(c[i]);
        if(c[i]+1<C) needy.emplace_back(c[i]+1);
        if(c[i]-1>=0) needy.emplace_back(c[i]-1);
    }


    sort(ALL(needx));
    sort(ALL(needy));
    needx.erase(unique(needx.begin(),needx.end()),needx.end());
    needy.erase(unique(needy.begin(),needy.end()),needy.end());


    vi rr(N),cc(N);
    vi aa(N);

    for(int i=0;i<N;i++){
        rr[i] = find(all(needx),r[i]) - needx.begin();
        cc[i] = find(all(needy),c[i]) - needy.begin();
        aa[i] = a[i];
    }

    __int128 RC = R*C;
    if(RC>100000000){
        cout << "No" << endl;
        return 0;
    }

    ll RR = needx.size();
    ll CC = needy.size();

    vector<vector<ll>> vec(RR,vector<ll>(CC,0));
    for(int i=0;i<N;i++){
        vec[rr[i]][cc[i]] = aa[i];
    }


    __int128 hoge = RR*CC;
    hoge=1000000LL/hoge;

    auto beg(vec);

    ll counter = 0;
    while(true){
        if(++counter==200){
            cout <<"No" << endl;
            return 0;
        }
        for(int i=0;i<RR-1;i++){
            for(int j=0;j<CC-1;j++){
                if(vec[i][j]>0){
                    ll sum1 = vec[i][j]+vec[i+1][j+1];
                    ll sum2 = vec[i+1][j]+vec[i][j+1];
                    if(sum1 == sum2) continue;

                    if(vec[i+1][j+1]!=0){
                        if(sum2 > sum1){
                            cout <<"No" << endl;
                            return 0;
                        }else{
                            vec[i+1][j+1]=sum2-sum1;
                        }
                    }

                    if(vec[i+1][j]!=0 and vec[i][j+1]!=0){
                        if(sum1 > sum2){
                            cout << "No" << endl;
                            return 0;
                        }else{
                            if(vec[i+1][j]>0 and vec[i][j+1]==0){
                                vec[i][j+1] = sum1 - sum2;
                            }else if(vec[i+1][j]==0 and vec[i][j+1]>0){
                                vec[i+1][j] = sum1 - sum2;
                            }
                        }
                    }
                }
            }
        }
        if(vec == beg){
            break;
        }
    }
    cout << "Yes" << endl;
}

