bool fill_matrix_square(vector<vector<int>>& matrix, int i, int j, bool& changed) {
	changed = false;

	int filled = 0;
	if(matrix[i][j] != -1) {
		filled++;
	}
	if(matrix[i + 1][j] != -1) {
		filled++;
	}
	if(matrix[i][j + 1] != -1) {
		filled++;
	}
	if(matrix[i + 1][j + 1] != -1) {
		filled++;
	}

	if(filled == 4) {
		bool ret =
			matrix[i][j] + matrix[i + 1][j + 1] ==
			matrix[i + 1][j] + matrix[i][j + 1];

		if(!ret) DBGOUT << "failed " << __LINE__;
		return ret;
	}

	if(filled == 3) {
		changed = true;
		if(matrix[i][j] == -1) {
			matrix[i][j] = matrix[i + 1][j] + matrix[i][j + 1] - matrix[i + 1][j + 1];
			bool ret = matrix[i][j] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(matrix[i + 1][j + 1] == -1) {
			matrix[i + 1][j + 1] = matrix[i + 1][j] + matrix[i][j + 1] - matrix[i][j];
			bool ret = matrix[i + 1][j + 1] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(matrix[i + 1][j] == -1) {
			matrix[i + 1][j] = matrix[i][j] + matrix[i + 1][j + 1] - matrix[i][j + 1];
			bool ret = matrix[i + 1][j] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(matrix[i][j + 1] == -1) {
			matrix[i][j + 1] = matrix[i][j] + matrix[i + 1][j + 1] - matrix[i + 1][j];
			bool ret = matrix[i][j + 1] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
	}

	return true;
}

int main() {
	int rows, cols, n;
	cin >> rows >> cols >> n;

	vector<vector<int>> matrix(rows, vector<int>(cols, -1));

	for(int j = 0; j < n; j++) {
		int r, c, a;
		cin >> r >> c >> a;
		matrix[r - 1][c - 1] = a;
	}

	bool loop = true;
	while(loop)	{
		loop = false;

		for(int i = 0; i < rows - 1; i++) {
			for(int j = 0; j < cols - 1; j++) {
				bool changed;
				if(!fill_matrix_square(matrix, i, j, changed)) {
					cout << "No";
					return 0;
				}

				if(changed) {
					loop = true;
				}
			}
		}
	}

	cout << "Yes";
	return 0;
}

