bool add(int s, P p1, P p2) {
    if (A.count(P(p1))) {
        // cout << "p1 = " << A[p1] << endl;
        if (s - A[p1] < 0) return false;
        A[p2] = s - A[p1];
        GC[p2.first].push_back(p2.second);
    } else {
        // cout << "p2 = " << A[p2] << endl;
        if (s - A[p2] < 0) return false;
        A[p1] = s - A[p2];
        GC[p1.first].push_back(p1.second);
    }
    return true;
}

bool check(int r, int c, vector<int> dy, vector<int> dx) {
    int cnt = 1;
    vector<P> ps;
    ps.push_back(P(r, c));
    rep(i, 3) {
        int y = r + dy[i];
        int x = c + dx[i];
        if (!valid(y, x)) return true;
        ps.push_back(P(y, x));
        cnt += A.count(P(y, x));
    }
    // printf("%d %d %d\n", r, c, cnt);
    if (cnt < 2) return true;
    if (cnt == 3) {
        if (A.count(ps[2])) {
            int s = A[ps[0]] + A[ps[2]];
            if (!add(s, ps[1], ps[3])) return false;
        } else {
            int s = A[ps[1]] + A[ps[3]];
            if (!add(s, ps[0], ps[2])) return false;
        }
        return true;
    } else {
        int s1 = A[ps[0]] + A[ps[2]];
        int s2 = A[ps[1]] + A[ps[3]];
        return s1 == s2;
    }
    return true;
}

bool ok(int r, int c) {
    bool res = true;
    // 左上
    auto dx = vector<int>({1, 1, 0});
    auto dy = vector<int>({0, 1, 1});
    res &= check(r, c, dy, dx);

    // 右上
    dx = vector<int>({-1, -1, 0});
