int dx[] = {1, 0};
int dy[] = {0, 1};

const int N = 1e5;
int y[N], x[N];
vector<pair<int, int>> xs[N];
vector<int> val(N, -1);
int sol() {
  ios::sync_with_stdio(false), cin.tie(0);
  int h, w; cin >> h >> w;
  int n; cin >> n;
  for(int i = 0; i < n; i++) {
    int a; cin >> y[i] >> x[i] >> a; y[i]--; x[i]--;
    xs[x[i]].emplace_back(y[i], a);
  }
  ll bias = 0;
  ll mi = 1e18;
  for(int x = 0; x < w; x++) {
    if(xs[x].size() == 0) continue;
    ll nbias = 1e18;
    int miv = 1e9;
    for(auto el : xs[x]) {
      int y, a; tie(y, a) = el;
      if(val[y] != -1) {
        if(nbias == 1e18) {
          nbias = a - val[y];
        } else {
          if(nbias != a - val[y]) return 0;
        }
      }
      if(mi == 1e18) {
        mi = val[y] = a;
        nbias = 0;
      }
      miv = min(miv, a);
    }
    if(nbias == 1e18) nbias = miv - mi;
    bias = nbias;
    for(auto el : xs[x]) {
      int y, a; tie(y, a) = el;
      if(val[y] == -1) val[y] = a - bias, mi = min(mi, (ll) val[y]);
    }
    if(mi + bias < 0) return 0;
  }
  return 1;
}

int main() {
  cout << (sol() ? "Yes" : "No") << endl;
}

