vector<P> xlimit[100001];
vector<P> ylimit[100001];
ll mini[100001],mini2[100001];

bool checked[100001];
ll dist[100001];
bool flag=true;

void dfs(int v,ll s){
	dist[v]=s;
	checked[v]=true;
	for(int i=0;i<xlimit[v].size();i++){
		P p=xlimit[v][i];
		if(!checked[p.first]){
			dfs(p.first,s+p.second);
		}else if(dist[v]+p.second!=dist[p.first])flag=false;
	}
}

void dfs2(int v,ll s){
	dist[v]=s;
	checked[v]=true;
	for(int i=0;i<ylimit[v].size();i++){
		P p=ylimit[v][i];
		if(!checked[p.first]){
			dfs2(p.first,s+p.second);
		}else if(dist[v]+p.second!=dist[p.first])flag=false;
	}
}

int main(void){
	scanf("%d%d%d",&R,&C,&N);
	for(int i=0;i<max(C,R);i++){
		mini[i]=INF;
		mini2[i]=INF;
	}
	for(int i=0;i<N;i++){
		scanf("%d%d%lld",&r[i],&c[i],&a[i]);
		r[i]--;
		c[i]--;
		xid[r[i]].push_back(P(c[i],a[i]));
		yid[c[i]].push_back(P(r[i],a[i]));
		mini[c[i]]=min(mini[c[i]],a[i]);
		mini2[r[i]]=min(mini2[r[i]],a[i]);
	}

	for(int i=0;i<R;i++){
		if(xid[i].size()<=1)continue;
		int f=xid[i][0].first;
		for(int j=1;j<xid[i].size();j++){
			int t=xid[i][j].first;
			ll c=xid[i][0].second-xid[i][j].second;
			xlimit[f].push_back(P(t,-c));
			xlimit[t].push_back(P(f,c));
			if(mini[f]-c<0)flag=false;
			if(mini[t]+c<0)flag=false;
		}
	}
	for(int i=0;i<C;i++){
		if(yid[i].size()<=1)continue;
		int f=yid[i][0].first;
		for(int j=1;j<yid[i].size();j++){
			int t=yid[i][j].first;
			ll c=yid[i][0].second-yid[i][j].second;
			ylimit[f].push_back(P(t,-c));
			ylimit[t].push_back(P(f,c));
			if(mini2[f]-c<0)flag=false;
			if(mini2[t]+c<0)flag=false;
		}
	}

	for(int i=0;i<R;i++){
		if(!checked[i])dfs(i,0);
	}
	memset(checked,false,sizeof(checked));
	memset(dist,0,sizeof(dist));
	for(int i=0;i<C;i++){
		if(!checked[i])dfs2(i,0);
	}
	printf("%s\n",flag?"Yes":"No");
	return 0;
}

