		vector<pair<pair<int, int>, int> > a(k);
		for (int i = 0; i < k; i++) {
			scanf("%d%d%d", &a[i].first.first, &a[i].first.second, &a[i].second);
		}

		if (k <= 1) {
			cout << "Yes" << endl;
			continue;
		}

		bool ok = 1;

		ll A1 = a[1].first.first - a[0].first.first;
		ll B1 = a[1].first.second - a[0].first.second;
		ll C1 = a[1].second - a[0].second;

		bool found = 0;
		ll di, dj;
		for (int i = 2; i < k; i++) {
			ll A2 = a[i].first.first - a[0].first.first;
			ll B2 = a[i].first.second - a[0].first.second;
			ll C2 = a[i].second - a[0].second;

			ll det = A1 * B2 - A2 * B1;
			ll detx = C1 * B2 - C2 * B1;
			ll dety = A1 * C2 - A2 * C1;
			if (det == 0) {
				ok &= detx == 0 && dety == 0;
			}
			else {
				ok &= detx % det == 0 && dety % det == 0;
				di = detx / det;
				dj = dety / det;
				found = 1;
				break;
			}
		}

		if (found) {
			for (int i = 0; i < k; i++) {
				ok &= (a[i].first.first - a[0].first.first) * di + (a[i].first.second - a[0].first.second) * dj == a[i].second - a[0].second;
			}

