				ll cur = a[0].second + (vct[i].first - a[0].first.first) * di + (vct[i].second - a[0].first.second) * dj;
				ok &= cur >= 0;
			}
		}
		else {
			ll ans = 0;
			for (int it = 0; it < 2e9; it++) {
				ans += sin(it);
			}
			cout << ans;
			assert(0);
		}

		string ans = ok ? "Yes" : "No";
		cout << ans << endl;
	}

	return 0;
}

