  }
  for(int i=0;i<n;i++){
    if(!used[i]){
      xAxis.clear();
      yAxis.clear();
      bool b = traverse(i,v[i].first.first,v[i].first.second,v[i].second,0,v[i].second);
      if(!b){
        std::cout << "No" << std::endl;
        return 0;
      }
      long long xMin = std::min_element(xAxis.begin(),xAxis.end(),C()) -> second;
      long long yMin = std::min_element(yAxis.begin(),yAxis.end(),C()) -> second;
      if(xMin + yMin < 0){
        std::cout << "No" << std::endl;
        return 0;
      }
    }
  }
  std::cout << "Yes" << std::endl;
