		int to=col[c][cind[u]-1].second;
		if(!v[to]){
			dfs(to,a+V[to]-V[u],b);
		}
	}
	if(cind[u]+1<col[c].size()){
		int to=col[c][cind[u]+1].second;
		if(!v[to]){
			dfs(to,a+V[to]-V[u],b);
		}
	}

}
