	inc(i, C - 1) {
		std::vector< std::pair<int, int> > v2;
		for(auto && e : vec[i + 0]) { v2.push_back(std::make_pair(e.first * 2 + 0, e.second)); }
		for(auto && e : vec[i + 1]) { v2.push_back(std::make_pair(e.first * 2 + 1, e.second)); }
		std::sort(v2.begin(), v2.end());

		// for(auto && e : v2) { printf("<%d %s, %d>\n", e.first / 2, (e.first % 2 == 0 ? "<--" : "-->"), e.second); } printf("\n");

		int size = v2.size();
		bool flag = false;
		int diff;
		inc(j, size) {
			int fi = v2[j].first;
			if(j != size - 1 && fi % 2 == 0 && v2[j + 1].first == fi + 1) {
				if(! flag) {
					diff = v2[j + 1].second - v2[j].second;
					flag = true;
				} else {
					if(diff != v2[j + 1].second - v2[j].second) { return false; }
				}
			}
		}

		if(flag) {
			inc(j, size) {
				int fi = v2[j].first;
				int se = v2[j].second;
				if(fi % 2 == 0) {
					if(j == size - 1 || v2[j + 1].first != fi + 1) {
						if(se + diff < 0) { return false; }
						vec[i + 1].push_back(std::make_pair(fi / 2, se + diff));
					}
				} else {
					if(j == 0 || v2[j - 1].first == fi - 1) {
						if(se - diff < 0) { return false; }
					}
				}
			}
		}
	}

	return true;
}

