struct union_find{
	typedef unsigned size_type;
	vector<int> par;
	size_type grs;
	explicit union_find(size_type n = 0){ init(n); }
	void init(size_type n){
		par.assign(n, -1);
		grs = n;
	}
	size_type find(size_type x){
		if(par[x] < 0){ return x; }
		return par[x] = find(par[x]);
	}
	size_type size(size_type x){
		return -par[find(x)];
	}
	size_type groups(){
		return grs;
	}
	bool unite(size_type x, size_type y){
		x = find(x);
		y = find(y);
		if(x == y){ return false; }
		if(par[x] < par[y]){ swap(x, y); }
		par[y] += par[x];
		par[x] = y;
		--grs;
		return true;
	}
	bool same(size_type x, size_type y){
		return find(x) == find(y);
	}
};

bool solve(){
	int h, w, n;
	scanf("%d%d%d", &h, &w, &n);

	vector<int> ys(n), xs(n), as(n);
	VV(pii) G(h + w);
	union_find uf(h + w);
	for(int i = 0; i < n; ++i){
		scanf("%d%d%d", &ys[i], &xs[i], &as[i]);
		--xs[i];
		--ys[i];
		G[ys[i]].emplace_back(xs[i] + h, as[i]);
		G[xs[i] + h].emplace_back(ys[i], as[i]);
		uf.unite(ys[i], xs[i] + h);
	}

	vector<LL> val(h + w, LLONG_MAX);
	queue<int> q;
	for(int i = 0; i < h + w; ++i){
		if(uf.find(i) == i){
			val[i] = 0;
			q.push(i);
		}
	}
	while(!q.empty()){
		int u = q.front();
		q.pop();
		for(cauto p : G[u]){
			if(val[p.first] == LLONG_MAX){
				val[p.first] = p.second - val[u];
				q.push(p.first);
			}
		}
	}

	for(int i = 0; i < n; ++i){
		if(val[ys[i]] + val[xs[i] + h] != as[i]){ return false; }
	}
	LL miny = *min_element(val.begin(), val.begin() + h);
	LL minx = *min_element(val.begin() + h, val.end());
	if(miny + minx < 0){ return false; }

	return true;
}

