int uf[201010];
i64 ofs[201010];
i64 mn[201010];

pair<int, i64> root(int p)
{
	if (uf[p] < 0) return{ p, 0LL };
	auto tmp = root(uf[p]);
	tmp.second += ofs[p];
	uf[p] = tmp.first;
	ofs[p] = tmp.second;
	return tmp;
}

bool join(int p, int q, i64 d)
{
	// v[p] = v[q] + d
	auto r1 = root(p), r2 = root(q);
	if (r1.first == r2.first) {
		if (r1.second != r2.second - d) return true;
		return false;
	}
	d += r1.second - r2.second;
	p = r1.first;
	q = r2.first;
	if (0 && uf[p] < uf[q]) {
		swap(p, q);
		d *= -1;
	}
	uf[p] += uf[q];
	uf[q] = p;
	ofs[q] = d;
	return false;
}

vector<pair<int, int> > vals[101010];

int main()
{
