const int N = 100005;
int r, c, n, fa[N];
long long wi[N], mn[N];
vector<pair<int, int> > buck[N];
int Find(int x) {
	if (x == fa[x]) return x;
	int rt = Find(fa[x]);
	wi[x] += wi[fa[x]];
	return fa[x] = rt;
}
bool Union(int x, int y, long long z) {
	int rx = Find(x), ry = Find(y);
	z = z - wi[x] + wi[y];
	x = rx, y = ry;
	if (x < y) swap(x, y), z = -z;
	if (x == y) {
		return !z;
	}
	fa[x] = y;
	wi[x] = z;
	return true;
}
int main() {
	scanf("%d%d%d", &r, &c, &n);
	for (int i = 1; i <= n; i++) {
		int x, y, z;
		scanf("%d%d%d", &x, &y, &z);
		buck[x].push_back(make_pair(y, z));
	}
	for (int i = 1; i <= c; i++) fa[i] = i, wi[i] = mn[i] = 0;
	for (int i = 1; i <= r; i++) {
		sort(buck[i].begin(), buck[i].end());
		for (int j = 1; j < (int)buck[i].size(); j++) {
			if (!Union(buck[i][j - 1].first, buck[i][j].first, buck[i][j - 1].second - buck[i][j].second)) {
				puts("No");
				return 0;
			}
		}
	}
	for (int i = 1; i <= c; i++) {
		Find(i);
	}
	for (int i = 1; i <= c; i++) {
		mn[fa[i]] = min(mn[fa[i]], wi[i]);
	}
	for (int i = 1; i <= r; i++) if (buck[i].size()) {
		int p = fa[buck[i][0].first];
		long long w = buck[i][0].second - wi[buck[i][0].first];
		if (w + mn[p] < 0) {
			puts("No");
			return 0;
		}
	}
	puts("Yes");
	return 0;
}

