			}
		}
	}
	used.erase(ALL(used));
	for (auto &x : a) {
		if (!used.insert(get<1>(x)).second)continue;
		auto lit = lower_bound(ALL(ac), make_tuple(0,get<1>(x) + 1, 0), [](const ti3 &a, const ti3 &b) {return (get<1>(a) == get<1>(b)) ? (get<0>(a) < get<0>(b)) : (get<1>(a) < get<1>(b)); });
		auto it = lower_bound(ALL(ac), x, [](const ti3 &a, const ti3 &b) {return (get<1>(a) == get<1>(b)) ? (get<0>(a) < get<0>(b)) : (get<1>(a) < get<1>(b)); });
		int p1 = get<1>(*it);
		if (dr[p1].first == -1)dr[p1].first = p1;
		int as = get<2>(*it);
		for (it++; it != lit; it++) {
			int p2 = get<0>(*it);
			if (dr[p2].first == -1)dr[p2] = pii(dr[p1].first, get<2>(*it) - as);
			else if (dr[p2].second != get<2>(*it) - as) {
				cout << "No" << endl;
				return 0;
			}
		}
	}
	auto dr2 = dr, dc2 = dc;
	sort(ALL(dr2)), sort(ALL(dc2));
	for (auto&x : a) {
		if (upper_bound(ALL(dr2),pii(dr[get<0>(x)].first-1,INT_MAX))->second - dr[get<0>(x)].second + get<2>(x) < 0) {
			cout << "No" << endl;
			return 0;
		}
	}
	for (auto&x : a) {
		if (upper_bound(ALL(dc2), pii(dc[get<1>(x)].first-1,INT_MAX))->second - dc[get<1>(x)].second + get<2>(x) < 0) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;
}

