bool DFSUtil(int, vector<bool>&, vector<bool> &);
vector<pair<int, long long>> g[1234567];
long long node[1234567] = {0};
int R, C;
long long minR, minC = 1000000000;


int main(){
  cin >> R >> C;
  int N;
  cin >> N;  
  for(int i = 0; i < N; i++){
    int r, c;
    long long a;
    cin >> r >> c >> a;
    r--; c--;
    g[r].push_back(make_pair( c + R, a));
    g[c + R].push_back(make_pair(r, a));
  }

  vector<bool> visited(R + C, false);
  vector<bool> was(R + C, false);

  for(int i = 0; i < R + C; i++){
      was[i] = true;
      if(!DFSUtil(i, visited, was)){
        cout << "No";
        return 0;
      }
  }
  cout << "Yes";
}

bool DFSUtil(int v, vector<bool> &visited, vector<bool> &was){
  visited[v] = true;
  for(int i = 0; i < g[v].size(); i++){
    int w = g[v][i].first;
    long long a = g[v][i].second;
    if(was[v] && was[w]){
      if(node[v] + node[w] != a){
        return false;
      }
    }
    node[w] = a - node[v];
    was[w] = true;

    if(v < R) minR = minR >node[v] ? node[v] : minR;
    if(v >= R) minC = minC>node[v] ? node[v] : minC;
    if(w < R) minR = minR >node[w] ? node[w] : minR;
    if(w >= R) minC = minC>node[w] ? node[w] : minC;

    if(minR + minC < 0) return false;
    if(!visited[w]){
      if(!DFSUtil(w, visited, was)) return false;
    }
  }
  return true;
}

#include <bits/stdc++.h>
using namespace std;

#define REP(i, n) for (int i = 0; i < (int)n; i++)
typedef tuple<int, int> tii;

int R, C;
int N;
int r, c, a;


// 0 1
// 2 3
int dr[]{ 0, 1, 1 };
int dc[]{ 1, 0, 1 };
int coer[]{ 1, -1 };
int coec[]{ 1, -1 };

int dx[]{ 0, 1, 1, 1, 0, -1, -1, -1 };
int dy[]{ -1, -1, 0, 1, 1, 1, 0, -1 };

map<tii, int> fix;
map<tii, int> masu;
vector<tii>   emp;

bool ini_check()
{
  map<tii, int>::iterator it = masu.begin();
  for (; it != masu.end(); it++) {
    tii pos = it->first;
    int num = it->second;

    bool all = true;
    int  sum = masu[pos];
    REP(k, 3) {
      int sr = dr[k] + get<0>(pos);
      int sc = dc[k] + get<1>(pos);
      if (sr <= 0 || sr > R || sc <= 0 || sc > C) { all = false; break; }
      if (k != 2) sum += masu[tii(sr, sc)];
      else        sum -= masu[tii(sr, sc)];
    }

    if (all & sum != 0) return false;
  }
  return true;
}

bool test(vector<tii> & emp)
{
  bool update = true;

  while (update)
  {
    update = false;

    for (tii & pos : emp) {
      if (masu.count(pos)) continue;

      REP(i, 2) REP(j, 2) {
        bool all = true;
        int sum = 0;
        REP(k, 3) {
          int sr = coer[i] * dr[k] + get<0>(pos);
          int sc = coec[j] * dc[k] + get<1>(pos);
          if (sr <= 0 || sr > R || sc <= 0 || sc > C) { all = false; break; }
          if (!masu.count(tii(sr, sc)))               { all = false; break; }
          if (k != 2) sum += masu[tii(sr, sc)];
          else        sum -= masu[tii(sr, sc)];
        }

        if (all) {
          if (sum < 0) return false;
          if (fix.count(pos)) {
            int already = fix[pos];
            if (already != sum) {
              return false;
            }
          } else {
            masu[pos] = sum;
            fix[pos]  = sum;
            update = true;
          }
        }
      }
    }
  }

  return true;
}

int main()
{
  cin >> R >> C >> N;

  REP(i, N) {
    cin >> r >> c >> a;
    masu[tii(r, c)] = a;
    REP(i, 8) {
      int rr = r + dx[i];
      int cc = c + dy[i];
      if (rr > 0 && cc > 0)
        emp.push_back(tii(rr, cc));
    }
  }


  bool f = true;
  f &= ini_check();
  sort(emp.begin(), emp.end());
  f &= test(emp);
  cout << (f ? "Yes" : "No") << endl;



  return 0;
