int nbs[S], dst[S], wht[S], nxt[S], eid;

lld val[S];

const lld inf=0x3f3f3f3f3f3f3f3fLL;

void add_edge(const int u, const int v, const int w){
    wht[eid]=w;dst[eid]=v;nxt[eid]=nbs[u];nbs[u]=eid++;
    wht[eid]=w;dst[eid]=u;nxt[eid]=nbs[v];nbs[v]=eid++;
}

int draw(const int u, const lld w, lld &low, lld &hig){
    vrt[u]=0;
    val[u]=w;
    //printf("val[%d]=%lld\n", u, w);
    if(u<r){
        UPDMIN(low, w);
    }else UPDMIN(hig, w);
    for(int i=nbs[u]; ~i; i=nxt[i]){
        const int v=dst[i];
        if(!~vrt[v]){
            if(draw(v, wht[i]*1LL-val[u], low, hig)) return 1;
        }else if(val[u]+val[v]!=wht[i]*1LL)return 1;
    }
    return 0;
}

int check(){
    for(int i=0; i<r+c; i++){
        if(~vrt[i])continue;
        lld low=inf, hig=inf;
        if(draw(i, 0LL, low, hig) || low+hig<0LL)return 1;
    }
    return 0;
}

