using namespace std;

typedef long long ll;
typedef pair<int, int> PII;

const int MAXN = 1E5 + 10;

int R, C, n;
vector<PII> E[MAXN << 1];
ll val[MAXN << 1];
bool vis[MAXN << 1];
bool flag = true;
ll m[2];

void DFS(int u, int type){
	vis[u] = true;
	m[type] = min(m[type], val[u]);
	for (int v, i = 0; i < E[u].size(); ++i){
		if (vis[v = E[u][i].st]){
			flag &= val[u] + val[v] == E[u][i].nd;
			continue;
		}
		val[v] = E[u][i].nd - val[u];
		DFS(v, !type);
	}
}

int main(){
	scanf("%d%d%d", &R, &C, &n);
	for (int u, v, w, i = 0; i < n; ++i){
		scanf("%d%d%d", &u, &v, &w);
		v += R;
		E[u].push_back(PII(v, w));
		E[v].push_back(PII(u, w));
	}

	for (int i = 1; flag && i <= R + C; ++i)
		if (!vis[i]){
			val[i] = 0;
			m[0] = m[1] = LLONG_MAX;
			DFS(i, 0);
			flag &= m[0] + m[1] >= 0;
		}
	puts(flag ? "Yes" : "No");

	return 0;
}

