#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Graph
{
    int R, C;
    struct Edge { int source, target, constraint; };
    vector<vector<Edge>> adjacency_list;

    Graph(const int R, const int C) : R(R), C(C), adjacency_list(R+C) {}

    void add_edge(const int row, const int column, const int constraint)
    {
        adjacency_list[row].push_back({row, R+column, constraint});
        adjacency_list[R+column].push_back({R+column, row, constraint});
    }

    bool solve() const
    {
        auto seen = vector<bool>(R+C);
        auto differences = vector<ll>(R+C);

        bool is_consistent;
        ll min_row, min_column;
        const function<void(int)> dfs = [&](const int v)
        {
            for (const auto e : adjacency_list[v])
            {
                const auto d = e.constraint - differences[e.source];

                if (seen[e.target]) is_consistent &= differences[e.target] == d;
                else
                {
                    seen[e.target] = true;
                    differences[e.target] = d;

                    if (e.target < R) min_row = min(min_row, d);
                    else min_column = min(min_column, d);

                    dfs(e.target);
                }
            }
        };

        for (auto row = 0; row < R; row++) if (!seen[row])
        {
            is_consistent = true;
            min_row = 0;
            min_column = numeric_limits<ll>::max();

            seen[row] = true;
            dfs(row);

            if (!is_consistent || min_row + min_column < 0)
                return false;
        }
        return true;
    }
};

int main()
{
    int R, C; cin >> R >> C;

    auto graph = Graph(R, C);

    int N; cin >> N;
    for (auto i = 0; i < N; i++)
    {
        int r, c, a; cin >> r >> c >> a;
        r--; c--;
        graph.add_edge(r, c, a);
    }

    cout << (graph.solve() ? "Yes" : "No") << endl;
}

