const int dy[] = {0, 1, 0, 1};

int data[10005][10005];
int val[10005][10005];
int r, c;
int n;

queue<pair<int, int> > Q;

void check(int x, int y) {
  val[x][y] -= 1;
  if (x > 0) {
    val[x - 1][y] -= 1;
    if (val[x - 1][y] == 1) {
      Q.push(make_pair(x - 1, y));
    }
  }
  if (y > 0) {
    val[x][y - 1] -= 1;
    if (val[x][y - 1] == 1) {
      Q.push(make_pair(x, y - 1));
    }
  }
  if (x > 0 && y > 0) {
    val[x - 1][y - 1] -= 1;
    if (val[x - 1][y - 1] == 1) {
      Q.push(make_pair(x - 1, y - 1));
    }
  }
}

int main() {
  scanf("%d %d", &r, &c);
  scanf("%d", &n);
  for (int i = 0; i < r; i += 1) {
    for (int j = 0; j < c; j += 1) {
      data[i][j] = -1;
      val[i][j] = 4;
    }
  }

  for (int i = 0; i < n; i += 1) {
    int x, y, a;
    scanf("%d %d %d", &x, &y, &a);
    x -= 1; y -= 1;
    data[x][y] = a;
    check(x, y);
  }
  while (!Q.empty()) {
    int x = Q.front().first, y = Q.front().second;
    Q.pop();
    int pos = -1, flag = 0;
    for (int i = 0; i < 4; i += 1) {
      if (data[x + dx[i]][y + dy[i]] == -1) {
        pos = i;
        flag += 1;
      }
    }
    if (flag == 0) {
      if (data[x][y] + data[x + 1][y + 1] != data[x][y + 1] + data[x + 1][y]) {
        printf("NO");
        return 0;
      }
    }
    if (pos == 0) {
      data[x][y] = data[x + 1][y] + data[x][y + 1] - data[x + 1][y + 1];
      if (data[x][y] < 0) {
        printf("NO");
        return 0;
      }
      check(x, y);
    } else if (pos == 1) {
      data[x + 1][y + 1] = data[x + 1][y] + data[x][y + 1] - data[x][y];
      if (data[x + 1][y + 1] < 0) {
        printf("NO");
        return 0;
      }
      check(x + 1, y + 1);
    } else if (pos == 2) {
      data[x + 1][y] = data[x][y] + data[x + 1][y + 1] - data[x][y + 1];
      if (data[x + 1][y] < 0) {
        printf("NO");
        return 0;
      }
      check(x + 1, y);
    } else {
      data[x][y + 1] = data[x][y] + data[x + 1][y + 1] - data[x + 1][y];
      if (data[x][y + 1] < 0) {
        printf("NO");
        return 0;
      }
      check(x, y + 1);
    }
  }
  for (int i = 0; i < r; i += 1) {
    for (int j = 0; j < c; j += 1) {
      if (val[i][j] == 0) {
        if (data[i][j] + data[i + 1][j + 1] != data[i][j + 1] + data[i + 1][j]) {
          printf("NO");
          return 0;
        }
      }
    }
  }
  printf("YES");
  return 0;
}

