int R,C;

bool decide_r[100010],decide_c[100010];
ll dr[100010],dc[100010];
ll cri;

using state=tuple<int,ll>;

vector<state> row[100010];
vector<state> col[100010];

ll r[100010],c[100010],a[100010];

signed  main(void){
	cin >> R >> C;
	decide_r[0]=decide_c[0]=true;

	int n;
	cin >> n;
	rep(i,n){
		cin >> r[i] >> c[i] >> a[i];
		r[i]--,c[i]--;
		row[r[i]].push_back(state(c[i],a[i]));
		col[c[i]].push_back(state(r[i],a[i]));
	}

	rep(i,R){
		sort(_all(row[i]));
		const int m=int(row[i].size());
		rep(j,m-1){
			int cp=get<0>(row[i][j]),np=get<0>(row[i][j+1]);
			if(decide_c[np]) continue;
			dc[np]=get<1>(row[i][j+1])-get<1>(row[i][j]);
			if(np-cp==1) decide_c[np]=true;
		}
	}

	rep(j,C){
		sort(_all(col[j]));
		const int m=int(col[j].size());
		rep(i,m-1){
			int cp=get<0>(col[j][i]),np=get<0>(col[j][i+1]);
			if(decide_r[np]) continue;
			dr[np]=get<1>(col[j][i+1])-get<1>(col[j][i]);
			if(np-cp==1) decide_r[np]=true;
		}
	}

	rep(i,R) dr[i+1]+=dr[i],decide_r[i+1]&=decide_r[i];
	rep(j,C) dc[j+1]+=dc[j],decide_c[j+1]&=decide_c[j];

	cri=a[0]-dr[r[0]]-dc[c[0]];


	bool ok=true;
	rep(i,n) if(decide_r[r[i]] and decide_c[c[i]] and cri+dr[r[i]]+dc[c[i]]!=a[i]) ok=false;

	ll rmin=dr[0],cmin=dc[0];
	rep(i,R) chmin(rmin,dr[i]);
	rep(j,C) chmin(cmin,dc[j]);

	if(rmin+cmin+cri<0) ok=false;


	if(ok)
		puts("Yes");
	else
		puts("No");

	return 0;
}

