    bool ans = true;
    for(int i = 0; i < N; ++i) {
        int rr, cc, aa;
        cin >> rr >> cc >> aa;
        Z.insert(M(mp(rr, cc), aa));
    }

    for(auto e : Z) {
        int rr = e.first.first;
        int cc = e.first.second;
        for(int r = rr - 1; r <= rr; ++r) {
            for(int c = cc - 1; c <= cc; ++c) {
                if(1 <= r && r <= R && 1 <= c && c <= C) {
                    int count = 0; int ia = 0; int ib = 0; int ic = 0; int id = 0;
                    if(ia = Z.count(mp(r, c))) ++count;
                    if(ib = Z.count(mp(r+1, c))) ++count;
                    if(ic = Z.count(mp(r, c+1))) ++count;
                    if(id = Z.count(mp(r+1, c+1))) ++count;
                    if(count == 3) {
                        int zz;
                        if(!ia) {
                            zz = Z[mp(r+1, c)] + Z[mp(r, c+1)] - Z[mp(r+1, c+1)];
                            Z.insert(M(mp(r, c), zz));
                        }
                        if(!ib) {
                            Z.insert(M(mp(r+1, c), zz = Z[mp(r, c)] + Z[mp(r+1, c+1)] - Z[mp(r, c+1)]));
                        }
                        if(!ic) {
                            Z.insert(M(mp(r, c+1), zz = Z[mp(r, c)] + Z[mp(r+1, c+1)] - Z[mp(r+1, c)]));
                        }
                        if(!id) {
                            zz = Z[mp(r+1, c)] + Z[mp(r, c+1)] - Z[mp(r, c)];
                            Z.insert(M(mp(r+1, c+1), zz));
                        }
                        if(zz < 0) ans = false;
                    }
                    if(count == 4) {
                        if(Z[mp(r, c)] + Z[mp(r+1, c+1)] != Z[mp(r+1, c)] + Z[mp(r, c+1)]) {
                            ans = false;
                        }
                    }
                }
            }
        }
    }
    if(ans) cout << "Yes" << endl;
    else cout << "No" << endl;
    return 0;
}

