vector< vector< edge_base > > gra;
vector<LL> weight;
int R,C;

bool dfs(int node,LL& Xmin,LL& Ymin){
	/*頂点:nodeの重みを決めてからここにくる。*/
	if( node < R ){//Xの頂点,最小値の更新
		Xmin = min( Xmin, weight[node] );
	}else{//Yの頂点,最小値の更新
		Ymin = min( Ymin, weight[node] );
	}
	int size = gra[node].size();
	for(int i=0;i<size;++i){
		int to = gra[node][i].to;
		LL val = gra[node][i].cost;//辺の容量的なやつ
		if( weight[to] == LINF ){//頂点の重みが決まってない
			//片方が決まっているなら分ける。
			weight[to] = val - weight[node];
			if( dfs(to,Xmin,Ymin) == false ){
				return false;
			}
		}else{
			/*ある辺の２頂点の重みが両方決まっているなら
			辺の容量と一致しているか調べる。
			*/
			if( weight[to] + weight[node] != val ){
				return false;
			}
		}
	}
	return true;
}

