	LL Xmin,Ymin;
	for(int i=0;i<R+C;++i){//各頂点についてループ
		//頂点の重みが決まっていない &&
		//繋がっている頂点がある(:=制約がある)
		/*連結成分毎に調べている。*/
		if( weight[i] == LINF && gra[i].size() > 0 ){
			Xmin = Ymin = LINF;//dfs内部で値を変更している。
			weight[i] = 0;//重みを仮定して調べる。
			//評価順に注意dfs->Xmin,Ymin
			if( dfs(i,Xmin,Ymin) == false || Xmin+Ymin < 0 ){
