template<class T>inline void read(T &re)
{
    char ch;int f=1;
    while((ch=getchar())<'0'||ch>'9')
    if(ch=='-')f=-1;
    re=ch-48;
    while((ch=getchar())>='0'&&ch<='9')
    re=(re<<3)+(re<<1)+ch-48;
    re*=f;
}

inline int min(int x,int y){
    return x<y?x:y;
}

struct node{
    int x,y,w;
}ch[maxn];

int fa[maxn],w[maxn],min1[maxn],min2[maxn];

inline bool comp(const node &a,const node &b){
    if(a.y!=b.y)return a.y<b.y;
    return a.x<b.x;
}

inline int getfa(int x){
    if(fa[x]==x)return x;
    int nf=getfa(fa[x]);
    w[x]+=w[fa[x]];
    return fa[x]=nf;
}

inline bool unionn(int a,int b,int W)
{
    int a1=getfa(a),b1=getfa(b);
    if(a1!=b1){
        fa[a1]=b1;
        w[a1]=W+w[b]-w[a];//b-a+b1-b+a-a1=W+w[b]-w[a]=b1-a1
        return true;
    }
    else return w[a]==W+w[b];//b-a+b1-b=b1-a=w[a] 判断是否会矛盾 
}

