signed main() {
	INIT;
	VAR(int, R, C, N);
	std::vector<Cell> cell(N);
	REP(i, N) {
		VAR(int, r, c, a);
		cell[i] = Cell(--r, --c, a);
	}
	{
		std::sort(ALL(cell), [](Cell& l, Cell& r) {return l.r < r.r; });
		int t = cell[0].r;
		int num = 0;
		REP(i, N) {
			if (t != cell[i].r) {
				++num;
				t = cell[i].r;
			}
			cell[i].r = num;
		}
		R = num + 1;
	}
	{
		std::sort(ALL(cell), [](Cell& l, Cell& r) {return l.c < r.c; });
		int t = cell[0].c;
		int num = 0;
		REP(i, N) {
			if (t != cell[i].c) {
				++num;
				t = cell[i].c;
			}
			cell[i].c = num;
		}
		C = num + 1;
	}
	std::map<int, std::map<int, int>> map;
	std::map<int, std::map<int, bool>> used;
	REP(i, N) {
		map[cell[i].r][cell[i].c] = cell[i].a;
		used[cell[i].r][cell[i].c] = true;
	}
	std::vector<int> sr(R - 1, INFINT), sc(C - 1, INFINT);
	REP(q, 2) {
		REP(i, N) {
			//
			if (cell[i].r > 0) {
				if (used[cell[i].r - 1][cell[i].c]) {
					if (sr[cell[i].r - 1] == INFINT) {
						sr[cell[i].r - 1] = map[cell[i].r - 1][cell[i].c] - map[cell[i].r][cell[i].c];
					}
					else {
						if (sr[cell[i].r - 1] != map[cell[i].r - 1][cell[i].c] - map[cell[i].r][cell[i].c]) {
							OUT("No")BR;
							return 0;
						}
					}
				}
				else {
					if (sr[cell[i].r - 1] != INFINT) {
						if (map[cell[i].r][cell[i].c] + sr[cell[i].r - 1] < 0) {
							OUT("No")BR;
							return 0;
						}
					}
				}
			}
			//
			if (cell[i].c > 0) {
				if (used[cell[i].r][cell[i].c - 1]) {
					if (sc[cell[i].c - 1] == INFINT) {
						sc[cell[i].c - 1] = map[cell[i].r][cell[i].c - 1] - map[cell[i].r][cell[i].c];
					}
					else {
						if (sc[cell[i].c - 1] != map[cell[i].r][cell[i].c - 1] - map[cell[i].r][cell[i].c]) {
							OUT("No")BR;
							return 0;
						}
					}
				}
				else {
					if (sc[cell[i].c - 1] != INFINT) {
						if (map[cell[i].r][cell[i].c] + sc[cell[i].c - 1] < 0) {
							OUT("No")BR;
							return 0;
						}
					}
				}
			}
			//
			if (cell[i].r < R - 1) {
				if (used[cell[i].r + 1][cell[i].c]) {
					if (sr[cell[i].r] == INFINT) {
						sr[cell[i].r] = map[cell[i].r][cell[i].c] - map[cell[i].r + 1][cell[i].c];
					}
					else {
