							OUT("No")BR;
							return 0;
						}
					}
				}
				else {
					if (sr[cell[i].r] != INFINT) {
						if (map[cell[i].r + 1][cell[i].c] - sr[cell[i].r] < 0) {
							OUT("No")BR;
							return 0;
						}
					}
				}
			}
			//
			if (cell[i].c > C - 1) {
				if (used[cell[i].r][cell[i].c + 1]) {
					if (sc[cell[i].c] == INFINT) {
						sc[cell[i].c] = map[cell[i].r][cell[i].c] - map[cell[i].r][cell[i].c + 1];
					}
