using namespace std;
typedef long long ll;

template<typename Abel>
struct WeightedUnionFind{
    int num;
    vector<int> par,rank;
    vector<Abel> diff_weight;
    WeightedUnionFind(int n,Abel id=0):
        num(n),par(n),rank(n,1),diff_weight(n,Abel(0)){
        iota(par.begin(),par.end(),0);
    }
    int root(int x){
        if (x==par[x]) return x;
        int t=root(par[x]);
        diff_weight[x]+=diff_weight[par[x]];
        return par[x]=t;
    }
    bool merge(int x,int y,Abel w){
        w+=weight(x),w-=weight(y);
        x=root(x),y=root(y);
        if (x==y) return false;
        if (rank[x]<rank[y]) swap(x,y),w=-w;
        par[y]=x;
        rank[x]+=rank[y];
        diff_weight[y]=w;
        --num;
        return true;
    }
    bool same(int x,int y){
        return root(x)==root(y);
    }
    Abel weight(int x){
        root(x);
        return diff_weight[x];
    }
    Abel diff(int x,int y){
        return weight(y)-weight(x);
    }
    int size(int x){
        return rank[root(x)];
    }
    int count(){
        return num;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int R,C,N; cin >> R >> C >> N;
    vector<vector<pair<int,ll>>> col(R),row(C);
    for (int i=0;i<N;++i){
        int r,c; ll a; cin >> r >> c >> a; --r,--c;
        col[r].emplace_back(c,a);
        row[c].emplace_back(r,a);
    }
    WeightedUnionFind<ll> ufc(C),ufr(R);
    for (int i=0;i<R;++i){
        sort(col[i].begin(),col[i].end());
        for (int j=0;j+1<col[i].size();++j){
            ll d=col[i][j+1].second-col[i][j].second;
            int l=col[i][j].first,r=col[i][j+1].first;
            if (!ufc.same(l,r)) ufc.merge(l,r,d);
            else if (ufc.diff(l,r)!=d){
                cout << "No" << '\n';
                return 0;
            }
        }
        if (col[i].empty()) continue;
        int id=col[i][0].first; ll now=col[i][0].second;
        for (int j=0;j<C;++j){
            if (ufc.same(id,j)&&now+ufc.diff(id,j)<0){
                cout << "No" << '\n';
                return 0;
            }
        }
    }
    for (int i=0;i<C;++i){
        sort(row[i].begin(),row[i].end());
        for (int j=0;j+1<row[i].size();++j){
            ll d=row[i][j+1].second-row[i][j].second;
            int l=row[i][j].first,r=row[i][j+1].first;
            if (!ufr.same(l,r)) ufr.merge(l,r,d);
            else if (ufr.diff(l,r)!=d){
                cout << "No" << '\n';
                return 0;
            }
        }
        if (row[i].empty()) continue;
        int id=row[i][0].first; ll now=row[i][0].second;
        for (int j=0;j<R;++j){
            if (ufr.same(id,j)&&now+ufr.diff(id,j)<0){
                cout << "No" << '\n';
                return 0;
            }
        }
    }
    cout << "Yes" << '\n';
}

