template<typename X> inline X abs(const X& a) { return a < 0 ? -a : a; }
template<typename X> inline X sqr(const X& a) { return a * a; }

typedef long long li;
typedef long double ld;
typedef pair<int, int> pt;

const int INF = int(1e9);
const li INF64 = li(1e18);
const ld EPS = 1e-9;
const ld PI = acosl(ld(-1));

const int N = 100 * 1000 + 13;
int n, m, k;
vector<pt> xx[N], yy[N];

pair<pt, int> d[N];

inline bool read()
{
	if (scanf ("%d%d%d", &n, &m, &k) != 3)
		return false;

	int minX = INF, minY = INF;

	forn (i, k)
	{
		int x, y, val;
		assert(scanf ("%d%d%d", &x, &y, &val) == 3);

		//x--, y--;

		minX = min(minX, x);
		minY = min(minY, y);

		d[i] = mp(mp(x, y), val);
	}

	forn (i, k)
	{
		int x = d[i].x.x, y = d[i].x.y, val = d[i].y;

		x -= minX;
		y -= minY;

		xx[x].pb(mp(y, val));
		yy[y].pb(mp(x, val));
	}

	return true;
}

li xVal[N], yVal[N];

int head, tail;
pt q[2 * N];

set<pt> e;

inline void solve()
{
	forn (i, n)
		sort(all(xx[i]));
	forn (i, m)
		sort(all(yy[i]));

	int c = -1;
	if (!xx[0].empty() && xx[0][0].x == 0)
	{
		c = xx[0][0].y;
	}

	if (c == -1)
	{
		forn (i, n)
		{
			if (xx[i].empty())
				continue;
			if (xx[i][0].x != 0)
				continue;

			forn (j, sz(xx[i]))
			{
				int y = xx[i][j].x, val = xx[i][j].y;

				if (yy[y].empty())
					continue;
				if (yy[y][0].y != 0)
					continue;

				int curC = xx[i][0].y + val - xx[i][j].y;
				if ((c != -1 && c != curC) || curC < 0)
				{
					puts("No");
					return;
				}

				c = curC;
			}
		}
	}

	if (c == -1)
		c = 0;

	memset(xVal, -1, sizeof xVal);
	memset(yVal, -1, sizeof yVal);
	head = tail = 0;	

	xVal[0] = c;
	yVal[0] = c;

	forn (i, n)
		if (!xx[i].empty())
			e.insert(mp(0, i));
	forn (i, m)
		if (!yy[i].empty())
			e.insert(mp(1, i));

	forn (i, n)
		if (!xx[i].empty() && xx[i][0].x == 0)
		{
			e.erase(mp(0, i));
			xVal[i] = xx[i][0].y;
			q[tail++] = mp(0, i);
		}

	forn (i, m)
		if (!yy[i].empty() && yy[i][0].x == 0)
		{
			e.erase(mp(1, i));
			yVal[i] = yy[i][0].y;
			q[tail++] = mp(1, i);
		}

	while (!e.empty())
	{
		int t = e.begin()->x, i = e.begin()->y;
		e.erase(e.begin());

		if (t == 0)
		{
			int cur = 0;

			forn (j, sz(xx[i]))
				cur = max(cur, xx[i][j].y);

			xVal[i] = cur + c;
			q[tail++] = mp(0, i);
		}
		else
		{
			int cur = 0;

			forn (j, sz(yy[i]))
				cur = max(cur, yy[i][j].y);		

			yVal[i] = cur + c;
			q[tail++] = mp(1, i);				
		}

    	while (head != tail)
    	{
    		int t = q[head].x, i = q[head].y;
    		head++;

    		if (t == 0)
    		{
    			forn (j, sz(xx[i]))
    			{
    				int y = xx[i][j].x, val = xx[i][j].y;

    				if (y == 0)
    					continue;

    				li cur = val + c - xVal[i];
    				if ((yVal[y] != -1 && yVal[y] != cur) || cur < 0)
    				{
    					puts("No");
    					return;
    				}

    				if (yVal[y] == -1)
    				{
    					e.erase(mp(1, y));
    					yVal[y] = cur;
    					q[tail++] = mp(1, y);
    				}
    			}
    		}
    		else
    		{
    			forn (j, sz(yy[i]))
    			{
    				int x = yy[i][j].x, val = yy[i][j].y;

    				if (x == 0)
    					continue;

    				li cur = val + c - yVal[i];
    				if ((xVal[x] != -1 && xVal[x] != cur) || cur < 0)
    				{
    					puts("No");
    					return;
    				}

    				if (xVal[x] == -1)
    				{
    					e.erase(mp(0, x));
    					xVal[x] = cur;
    					q[tail++] = mp(0, x);
    				}
    			}		
    		}
    	}
    }

	li minValX = INF64, minValY = INF64;
	fore (i, 1, n - 1)
		if (xVal[i] != -1)
			minValX = min(minValX, xVal[i]);
	fore (i, 1, m - 1)
		if (yVal[i] != -1)
			minValY = min(minValY, yVal[i]);

	if (minValX != INF64 && minValY != INF64)
	{
		if (minValX + minValY - c < 0)
		{
			puts("No");
			return;
		}
	}	

	puts("Yes");
}

int main()
{
#ifdef SU2_PROJ
	assert(freopen("input.txt", "r", stdin));
	assert(freopen("output.txt", "w", stdout));
#endif

	cout << setprecision(25) << fixed;
	cerr << setprecision(10) << fixed;

	srand(int(time(NULL)));

	assert(read());
	solve();

#ifdef SU2_PROJ
	cerr << "TIME: " << clock() << endl;
#endif

	return 0;
}

