#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using P = pair<int, int>;

const ll INF = 1e15;

int R, C, N;
vector<P> g[200010];
vector<ll> memo;

bool dfs(int cur, ll& x, ll& y) {
	for (P p : g[cur]) {
		if (memo[p.first] != INF) {
			if (memo[p.first] + memo[cur] != p.second) return false;
			continue;
		}
		memo[p.first] = p.second - memo[cur];
		if (p.first < R) x = min(x, memo[p.first]);
		else y = min(y, memo[p.first]);
		if (!dfs(p.first, x, y)) return false;
	}
	return true;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> R >> C >> N;
	for (int i = 0; i < N; i++) {
		int r, c, a;
		cin >> r >> c >> a;
		r--;
		c--;
		g[r].emplace_back(R + c, a);
		g[R + c].emplace_back(r, a);
	}

	memo.resize(R + C, INF);
	bool ans = true;
	for (int i = 0; i < R + C; i++) {
		if (memo[i] == INF) {
			memo[i] = 0;
			ll x = INF, y = INF;
			if (i < R) x = 0;
			else y = 0;
			if (!dfs(i, x, y) || x + y < 0) {
				ans = false;
				break;
			}
		}
	}

	cout << (ans ? "Yes" : "No") << endl;
	return 0;
}

