void dfs(int x)
{
	V[tplt].push_back(x);
	int i=head[x];
	while (i!=0)
	{
		int y=adj[i];
		if (wv[y]==-oo)
		{
			wv[y]=we[i]-wv[x];
			dfs(y);
		}
		i=link[i];
	}
