{
	visit[x]=true;
	int i=head[x];
	bool res=true;
	while (i!=0)
	{
		int y=adj[i];
		if (we[i]!=wv[y]+wv[x])
			res=false;
		if (!visit[y]) res&=check(y);
		i=link[i];
	}
	return res;
}
