using namespace std;

int R, C;
int N;
typedef pair<int, int> P;
map<P, int> field;
queue<P> checklist;

P operator+(const P &l, const P &r) {
  return P(l.first+r.first, l.second+r.second);
}

bool exists(P p) {
  return field.find(p) != field.end();
}

bool boundaryCheck(P p) {
  if (p.first <  0 || p.second <  0 ||
      p.first >= R || p.second >= C) return false;
  return true;
}

bool update(P p, int val) {
  if (val < 0) return false;
  field[p] = val;
  checklist.push(p);
  return true;
}

bool check(P p) {
  if (!boundaryCheck(p) || !(boundaryCheck(p + P(-1, -1)))) return true;
  if (exists(p)) {
    if (exists(p + P(-1, -1))) {
      int s = field[p + P(-1, -1)] + field[p];
      if (exists(p + P(-1, 0)) && exists(p + P(0, -1))) {
        if (field[p + P(-1, 0)] + field[p + P(0, -1)] != s) return false;
      }
      else if (exists(p + P(-1, 0))) {
        if (!update(p + P(0, -1), s - field[p + P(-1, 0)])) return false;
      }
      else if (exists(p + P(0, -1))) {
        if (!update(p + P(-1, 0), s - field[p + P(0, -1)])) return false;
      }
    }
    else {
      int s = field[p];
      if (exists(p + P(-1, 0)) && exists(p + P(0, -1))) {
        if (!update(p + P(-1, -1),
           s - (field[p + P(-1, 0)] + field[p + P(0, -1)]))) return false;
      }
    }
  }
  else {
    if (exists(p + P(-1, -1)) && exists(p + P(-1, 0)) && exists(p + P(0, -1))) {
      int s = field[p + P(-1, 0)] + field[p + P(0, -1)];
      if (!update(p, s - field[p + P(-1, -1)])) return false;
    }
  }
  return true;
}

int main() {
  cin >> R >> C;
  cin >> N;

  for (int i=0; i<N; i++) {
    int r, c, a;
    cin >> r >> c >> a;
    field[P(r-1, c-1)] = a;
    checklist.push(P(r-1, c-1));
  }
  bool ok = true;
  while (!checklist.empty()) {
    P p = checklist.front(); checklist.pop();
    if (!check(p)           || !check(p + P(0, 1)) ||
        !check(p + P(1, 0)) || !check(p + P(1, 1))) {
      ok = false;
      break;
    }
  }
  cout << (ok ? "Yes" : "No") << "\n";
  return 0;
}

