void ensure(bool b)
{
    if(!b)
    {
        printf("No\n");
        exit(0);
    }
}

void go(int r)
{
    queue<pair<int, int>> Q;
    Q.push({r, 0});
    rows.erase(r);
    A[r]=0;
    while(!Q.empty())
    {
        int t;
        tie(r, t)=Q.front();
        Q.pop();
        if(t==0)
        {
            for(auto& it: row[r])
            {
                if(!cols.count(it.c))
                    ensure(B[it.c]==it.x-A[it.r]);
                else
                {
                    B[it.c]=it.x-A[it.r];
                    Q.push({it.c, 1});
                    cols.erase(it.c);
                }
            }
        }
        else
        {
            for(auto& it: col[r])
            {
                if(!rows.count(it.r))
                    ensure(A[it.r]==it.x-B[it.c]);
                else
                {
                    A[it.r]=it.x-B[it.c];
                    Q.push({it.r, 0});
                    rows.erase(it.r);
                }
            }
        }
    }
}

