using namespace std;
const long long inf = 1LL << 60;
struct edge { int to, val; };
int H, W, N, x[100009], y[100009], a[100009]; long long dat[2][100009]; vector<int> px[100009], py[100009]; vector<vector<edge> > gx, gy;
bool dfs(int pos, long long sum, int id, vector<vector<edge> > &g) {
	for (edge e : g[pos]) {
		if (dat[id][e.to] != inf) {
			if (sum + e.val != dat[id][e.to]) return false;
		}
		else {
			dat[id][e.to] = sum + e.val;
			if (!dfs(e.to, sum + e.val, id, g)) return false;
		}
	}
	return true;
}
int main() {
	ios::sync_with_stdio(false);
	cin >> H >> W >> N;
	for (int i = 0; i < N; i++) {
		cin >> x[i] >> y[i] >> a[i]; x[i]--, y[i]--;
		px[x[i]].push_back(i);
		py[y[i]].push_back(i);
	}
	gx.resize(W);
	gy.resize(H);
	for (int i = 0; i < H; i++) {
		for (int j = 1; j < px[i].size(); j++) {
			gx[y[px[i][j - 1]]].push_back(edge{ y[px[i][j]], a[px[i][j]] - a[px[i][j - 1]] });
			gx[y[px[i][j]]].push_back(edge{ y[px[i][j - 1]], a[px[i][j - 1]] - a[px[i][j]] });
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 1; j < py[i].size(); j++) {
			gy[x[py[i][j - 1]]].push_back(edge{ x[py[i][j]], a[py[i][j]] - a[py[i][j - 1]] });
			gy[x[py[i][j]]].push_back(edge{ x[py[i][j - 1]], a[py[i][j - 1]] - a[py[i][j]] });
		}
	}
	bool ret = true;
	fill(dat[0], dat[0] + W, inf);
	for (int i = 0; i < W; i++) {
		if (dat[0][i] == inf) {
			dat[0][i] = inf / 12;
			if (!dfs(i, 0, 0, gx)) ret = false;
		}
	}
	fill(dat[1], dat[1] + H, inf);
	for (int i = 0; i < H; i++) {
		if (dat[1][i] == inf) {
			dat[1][i] = inf / 12;
			if (px[i].size()) dat[1][i] = a[px[i][0]] - dat[0][y[px[i][0]]];
			if (!dfs(i, dat[1][i], 1, gy)) ret = false;
		}
	}
	cout << (ret && *min_element(dat[0], dat[0] + W) + *min_element(dat[1], dat[1] + H) >= 0 ? "Yes" : "No") << endl;
	return 0;
}

