void dfs(int i) {
	tri A = v[i];
	if (dx[A.first.first] < minx) minx = dx[A.first.first];
	if (dy[A.first.second] < miny) miny = dy[A.first.second];
	for (int j : adj[i]) {
		tri B = v[j];
		if (A.first.first == B.first.first) {
			if (!vy[B.first.second]) {
				vy[B.first.second] = 1;
				dy[B.first.second] = dy[A.first.second] + B.second.second - A.second.second;
				dfs(j);
			}
			else {
				if (dy[B.first.second] != dy[A.first.second] + B.second.second - A.second.second) failed = 1;
			}
		}
		else {
			if (A.first.second != B.first.second) throw 12;
			if (!vx[B.first.first]) {
				vx[B.first.first] = 1;
				dx[B.first.first] = dx[A.first.first] + B.second.second - A.second.second;
				dfs(j);
			}
			else {
				if (dx[B.first.first] != dx[A.first.first] + B.second.second - A.second.second) failed = 1;
			}
		}
	}
}

