using P = pair<int, int>;

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int R, C, N;
	cin >> R >> C >> N;
	map<P, int> memo;
	for (int i = 0; i < N; i++) {
		int r, c, a;
		cin >> r >> c >> a;
		r--;
		c--;
		memo[P(r,c)] = a;
	}
	bool ans = true;
	vector<int> diff(R, INF);
	for (auto& p : memo) {
		P pos = p.first;
		int v = p.second;
		P b(pos.first + 1, pos.second);
		if (memo.find(b) == memo.end()) {
			if (diff[pos.first] != INF && v - diff[pos.first] < 0) {
				ans = false;
				break;
			}
			continue;
		}
		int d = v - memo[b];
		if (diff[pos.first] == INF) {
			diff[pos.first] = d;
		} else {
			ans = false;
			break;
		}
	}
	cout << (ans ? "Yes" : "No") << endl;
	return 0;
}

