const int N = 1e5+7;
vector<pair<int, int>> cols[N], rows[N];
vector<pair<int, int>> adj[N];
long long rowbound[N], colbound[N];

bool bad;
bool vis[N], id[N];
long long value[N], root[N];
long long dfs(int u, long long val, int s) {
    assert(!vis[u]);
    vis[u] = 1;
    value[u] = val;
    id[u] = s;

    long long ans = value[u];

    for (auto pr: adj[u]) {
        int v = pr.first;
        int d = pr.second;

        if (!vis[v])    ans = min(ans, dfs(v, val+d, s));
        if (value[v] != val+d)  bad = true;
    }
    return ans;
}

bool okay(vector<pair<int, int>> *rows, int R, int C, long long *bound) {
    for (int i=1; i<=C; i++) adj[i].clear(), vis[i] = 0;

    for (int i=1; i<=R; i++) {
        sort(rows[i].begin(), rows[i].end());
        for (int j=1; j<rows[i].size(); j++) {
            int x = rows[i][j-1].first, y = rows[i][j].first;
            int d = rows[i][j].second - rows[i][j-1].second;
            adj[x].push_back({y, d});
            adj[y].push_back({x, -d});
//
//            cout<<x << " to " << y<<" "<<d<<endl;
//            cout<<y << " to " << x<<" "<<-d<<endl;
        }
    }
    bad = false;
    for (int i=1; i<=C; i++) {
        if (vis[i])    continue;
        long long mn = dfs(i, 0, i);
        root[i] = mn;
//        cout<<"Comp at "<<i<<" "<<mn<<endl;
    }

    for (int i=1; i<=C; i++) {
        long long lo = value[i] - root[id[i]];
        bound[i] = max(bound[i], lo);
//        cout<<"Bound "<<i<<" "<<bound[i]<<endl;
    }
    return !bad;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    int R, C;
    cin>>R>>C;

    int n;
    cin>>n;

    vector<tuple<int, int, int>> cells;
    for (int i=1; i<=n; i++) {
        int x, y, v;
        cin>>x>>y>>v;
        rows[x].push_back({y, v});
        cols[y].push_back({x, v});
        cells.push_back({x, y, v});
    }

    bool good = okay(rows, R, C, colbound) && okay(cols, C, R, rowbound);

    for (auto tp: cells) {
        int x = get<0> (tp);
        int y = get<1> (tp);
        int v = get<2> (tp);

        good &= (rowbound[x]<=v && colbound[y]<=v);
    }
    if (good)   cout<<"Yes\n";
    else        cout<<"No\n";
}

