		int j=b[i].point;
		if (pd[j]==0) dfs1(j,b[i].w-k2);
		else if (b[i].w-k2!=L[j]) flag=1;
	}
}
void dfs2(int k1,long long k2,long long k3){
	pd[k1]=1; L[k1]=k2; R[k1]=k3;
//	cout<<"fa "<<k1<<" "<<k2<<" "<<k3<<endl;
	if (k3==1){
		mi=max(mi,-k2);
	} else ma=min(ma,k2);
	for (int i=p[k1];i;i=b[i].next){
		int j=b[i].point;
		if (pd[j]==0) dfs2(j,b[i].w-k2,-k3);
		else {
			long long a=b[i].w-L[k1]+L[j],b=R[k1]+R[j];
			if (b==0){
				if (a) flag=1;
			} else if (abs(a)%abs(b)) flag=1;
			else {
				long long num=a/b;
				mi=max(mi,num); ma=min(ma,num);
			}
		}
	}
}
