bool dfs(int v, int k)
{
	vis[v] = k;
	for (edge e : g[v]) {
		if (vis[e.to] != -1) {
			if (d[e.to] - d[v] != e.cost) {
				return false;
			}
		} else {
			d[e.to] = d[v] + e.cost;
			dfs(e.to, k);
		}
	}
	return true;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> R >> C >> N;
	rep(i, C) MX[i] = INT_MAX;

	rep(i, N) {
		cin >> r[i] >> c[i] >> A[i];
		--r[i]; --c[i];
		MX[c[i]] = min(MX[c[i]], A[i]);
		vec[r[i]].pb(i);
		v2[r[i]].eb(mp(A[i], i));
	}

	rep(i, R) {
		sort(ALL(v2[i]));
		rep(j, v2[i].size()) vec[i][j] = v2[i][j].se;

		rep(j, (int)vec[i].size()-1) {
			int ii = vec[i][j], jj = vec[i][j+1];
			g[c[ii]].eb(c[jj], A[jj]-A[ii]);
			g[c[jj]].eb(c[ii], A[ii]-A[jj]);
		}
	}

	rep(i, C) ms[i] = LLONG_MAX; 
	memset(vis, -1, sizeof(vis));

	int now = 0;
	rep(i, C) {
		if (vis[i] == -1) {
			if (!dfs(i, now++)) {
				puts("No");
				return 0;
			}
		}
		ms[vis[i]] = min(ms[vis[i]], d[i]);
	}

	rep(i, C) {
		d[i] -= ms[vis[i]];
		if (d[i] > MX[i]) {
			puts("No");
			return 0;
		}
	}

	puts("Yes");

	return 0;
}

#include <iostream>
