int R,C,N;

vector<vector<int>> M;
set<pair<int,int>> E;

bool check4(int i,int j){
  return M[i][j]+M[i+1][j+1] == M[i+1][j]+M[i][j+1];
}

bool tryFill3(int i, int j){
  if(E.count(make_pair(i,j))==0){
    int f = M[i+1][j]+M[i][j+1]-M[i+1][j+1];
    if (f<0) return false;
    E.insert(make_pair(i,j)); M[i][j]=f;
  } else if(E.count(make_pair(i+1,j))==0){
    int f = M[i][j]+M[i+1][j+1]-M[i][j+1];
    if (f<0) return false;
    E.insert(make_pair(i+1,j)); M[i+1][j]=f;
  } else if(E.count(make_pair(i,j+1))==0){
    int f = M[i][j]+M[i+1][j+1]-M[i+1][j];
    if (f<0) return false;
    E.insert(make_pair(i,j+1)); M[i][j+1]=f;
  } else if(E.count(make_pair(i+1,j+1))==0){
    int f = M[i+1][j]+M[i][j+1]-M[i][j];
    if (f<0) return false;
    E.insert(make_pair(i+1,j+1)); M[i+1][j+1]=f;
  }
  return true;
}

bool tryLoop(){
  for (size_t i = 1; i < R; i++) {
    for (size_t j = 1; j < C; j++) {
      int fillcount = E.count(make_pair(i,j))+E.count(make_pair(i+1,j))+E.count(make_pair(i,j+1))+E.count(make_pair(i+1,j+1));
      // cout << "i,j: " << i << "," << j << " :" << fillcount << endl;
      if (fillcount==4) {
        if(!check4(i,j)) {
          cout << "No" << endl;
          exit(0);
        }
      } else if (fillcount==3) {
        bool success = tryFill3(i, j);
        if (!success) {
          cout << "No" << endl;
          exit(0);
        } else {
          return true;
        }
      }
    }
  }
  return false;
}


int main (int argc, char const *argv[])
{
  cin >> R >> C >> N;
  M.resize(R+1);
  for (size_t i = 1; i <= R; i++) {
    M[i].resize(C+1);
  }

  for (size_t i = 0; i < N; i++) {
    int r,c,a; cin >> r >> c >> a;
    E.insert(make_pair(r,c));
    M[r][c] = a;
  }

  bool iter=true;
  while(iter) {
    iter=tryLoop();
  }

  cout << "Yes" << endl;
  return 0;
}

