		edge[1][c].emplace_back(r, a);
	}

	bool ans=true;
	Fill(memo, INF);
	rep(i,R) if( memo[0][i] == INF ){
		int m[2] = {INF, INF};
		ans &= dfs(0, i, 0, m);
	}

	cout << (ans?"Yes":"No") << endl;

	return 0;
}

