const ll inf= 5e15;

bool check(const vvec<pll> &lines) {
    vec<ll> mind(1e5 + 10, inf);
    std::map<pll, ll> diff;
    for (auto &&line : lines) {
        if (line.size() < 2) continue;
        ll minv = line.back().second;
        for (ll i = (ll)(lines.size()) - 2; 0 <= i; i--) {
            ll i1, i2, v1, v2;
            std::tie(i1, v1) = line[i];
            std::tie(i2, v2) = line[i + 1];
            pll key(i1, i2);
            ll d = v2 - v1;
            auto ite = diff.find(key);
            if (ite != diff.end() && ite->second != d) return false;
            diff[key] = d;
            chmin(mind[i1], minv - v1);
            chmin(minv, v1);
        }
    }

    for (auto &&line : lines) for (auto &&e : line) {
        ll idx, v;
        std::tie(idx, v) = e;
        if (v + mind[idx] < 0) return false;
    }

    return true;
}

bool solve() {
    ll r, c, n;
    std::cin >> r >> c >> n;
