    return x == data.x && y == data.y;
  }
};

int H,W,N;

int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

inline bool isValid(int x,int y) { return 0 <= x && x < W && 0 <= y && y < H; }

int main(){
  scanf(" %d %d",&H,&W);
  scanf(" %d",&N);
  map<Data,int> mp;
  rep(i,N) {
    int x,y,a;
