    --x, --y;
    mp[(Data){x,y}] = a;
  }
  bool update = true;
  while( update ) {
    update = false;
    map<Data,int> next;
    for(map<Data,int>::iterator it = mp.begin();it!=mp.end();++it) {
      int x = (it->first).x;
      int y = (it->first).y;
