bool saiki(int now, int num, bool istate, vector<int> &tate, vector<int> &yoko,
	vector<bool> &tated, vector<bool> &yokod, vector<vector<Edge>> &tateedge, vector<vector<Edge>> &yokoedge, pair<int, int> &minpair) {
	if (istate) {
		if (tated[now]) {
			if (tate[now] != num) {
				return false;
			}
			return true;
		}
		tated[now] = true, tate[now] = num;
		minpair.first = min(minpair.first, num);
		for (auto &t : tateedge[now]) {
			if (!saiki(t.to, t.cost - num, false, tate, yoko, tated, yokod, tateedge, yokoedge, minpair))
				return false;
		}
		return true;
	}
	else {
		if (yokod[now]) {
			if (yoko[now] != num) {
				return false;
			}
			return true;
		}
		yokod[now] = true, yoko[now] = num;
		minpair.second = min(minpair.second, num);
		for (auto &t : yokoedge[now]) {
			if (!saiki(t.to, t.cost - num, true, tate, yoko, tated, yokod, tateedge, yokoedge, minpair))
				return false;
		}
		return true;

	}
}


