const int MAX_R = 1e5 + 10;
const int MAX_C = 1e5 + 10;
const int MAX_RC = MAX_R + MAX_C;
typedef vector<vector<pii>> Graph;

Graph graph(MAX_RC);
vector<bool> used(MAX_RC, false);
vll node(MAX_RC, 0ll);

void dfs(int v, ll will) {
    if(used[v]) {
        if(node[v] != will) {
            cout << "No" << endl;
            exit(0);
        }
        return;
    }

    used[v] = true;
    node[v] = will;
    tr(it, graph[v]) {
        dfs(it->first, it->second - node[v]);
    }
}


