#define INF 10000000007LL
using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;

int R,C,N;
int r[100001],c[100001];
ll a[100001];
vector<P> xid[100001],yid[100001];
vector<P> xlimit[100001];
vector<P> ylimit[100001];
ll mini[100001],mini2[100001];

bool checked[100001];
ll dist[100001];
bool flag=true;
vector<int> route;
ll dmini;
void dfs(int v,ll s){
	dist[v]=s;
	checked[v]=true;
	dmini=min(dmini,dist[v]);
	route.push_back(v);
	for(int i=0;i<xlimit[v].size();i++){
		P p=xlimit[v][i];
		if(!checked[p.first]){
			dfs(p.first,s+p.second);
		}else if(dist[v]+p.second!=dist[p.first])flag=false;
	}
}

void dfs2(int v,ll s){
	dist[v]=s;
	checked[v]=true;
	for(int i=0;i<ylimit[v].size();i++){
		P p=ylimit[v][i];
		if(!checked[p.first]){
			dfs2(p.first,s+p.second);
		}else if(dist[v]+p.second!=dist[p.first])flag=false;
	}
}

int main(void){
	scanf("%d%d%d",&R,&C,&N);
	for(int i=0;i<max(C,R);i++){
		mini[i]=INF;
		mini2[i]=INF;
	}
	for(int i=0;i<N;i++){
		scanf("%d%d%lld",&r[i],&c[i],&a[i]);
		r[i]--;
		c[i]--;
		xid[r[i]].push_back(P(c[i],a[i]));
		yid[c[i]].push_back(P(r[i],a[i]));
		mini[c[i]]=min(mini[c[i]],a[i]);
		mini2[r[i]]=min(mini2[r[i]],a[i]);
	}

	for(int i=0;i<R;i++){
		if(xid[i].size()<=1)continue;
		int f=xid[i][0].first;
		for(int j=1;j<xid[i].size();j++){
			int t=xid[i][j].first;
			ll c=xid[i][0].second-xid[i][j].second;
			xlimit[f].push_back(P(t,-c));
			xlimit[t].push_back(P(f,c));
			if(mini[f]-c<0)flag=false;
			if(mini[t]+c<0)flag=false;
		}
	}
	for(int i=0;i<C;i++){
		if(yid[i].size()<=1)continue;
		int f=yid[i][0].first;
		for(int j=1;j<yid[i].size();j++){
			int t=yid[i][j].first;
			ll c=yid[i][0].second-yid[i][j].second;
			ylimit[f].push_back(P(t,-c));
			ylimit[t].push_back(P(f,c));
			if(mini2[f]-c<0)flag=false;
			if(mini2[t]+c<0)flag=false;
		}
	}

	for(int i=0;i<R;i++){
		if(!checked[i]){
			dmini=INF;
			dfs(i,0);
			for(int j=0;j<route.size();j++){
				if(mini[route[j]]-(dist[route[j]]-dmini)<0)flag=false;
			}
			route.clear();
		}
	}
	memset(checked,false,sizeof(checked));
	memset(dist,0,sizeof(dist));
	for(int i=0;i<C;i++){
		if(!checked[i]){
			dmini=INF;
			dfs2(i,0);
			for(int j=0;j<route.size();j++){
				if(mini[route[j]]-(dist[route[j]]-dmini)<0)flag=false;
			}
			route.clear();
		}
	}
	printf("%s\n",flag?"Yes":"No");
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef pair<int, int> Pi;
typedef pair<Pi, int>  Pii;

int R, C, N;
map<Pi, int> m;
vector<Pii> v;

// a b
// c d
bool check(int a, int b, int c, int d) {
  //cout << a << ' ' << b << ' ' << c << ' ' << d << endl;
  if (a >= 0 && b >= 0 && c >= 0 && d >= 0) {
    if (a+d != b+c) return false;
    else return true;
  }

  if (a < 0 && b >= 0 && c >= 0 && d >= 0) {
    if (b+c < d) return false;
    else return true;
  }

  if (a >= 0 && b < 0 && c >= 0 && d >= 0) {
    if (a+d < c) return false;
    else return true;
  }

  if (a >= 0 && b >= 0 && c < 0 && d >= 0) {
    if (a+d < b) return false;
    else return true;
  }

  if (a >= 0 && b >= 0 && c >= 0 && d < 0) {
    if (b+c < a) return false;
    else return true;
  }

  return true;
}

// a b c
// d e f
bool check2(int a, int b, int c, int d, int e, int f) {
  if (a >= 0 && b < 0 && c >= 0 && d >= 0 && e >= 0 && f >= 0) {
    if (a+e-d != c+e-f) return false;
    else return true;
  }

  if (a >= 0 && b >= 0 && c >= 0 && d >= 0 && e < 0 && f >= 0) {
    if (b+d-a != b+f-c) return false;
    else return true;
  }

  return true;
}

int main(void) {

  //cout << check(0, 10, 30, 20) << endl;

  scanf("%d %d %d", &R, &C, &N);
  for (int i = 0; i < N; i++) {
    int r, c, a;
    scanf("%d %d %d", &r, &c, &a);
    m[make_pair(r, c)] = a;
    v.push_back(make_pair(make_pair(r, c), a));
  }

  bool ans = true;
  for (int i = 0; i < v.size() && ans; i++) {
    int r = v[i].first.first, cc = v[i].first.second, a = v[i].second;

    // 左上
    if (r > 1 && cc > 1) {
      int b = (m.find(make_pair(r-1, cc-1)) == m.end() ? -1 : m[make_pair(r-1, cc-1)]);
      int c = (m.find(make_pair(r-1, cc)) == m.end() ? -1 : m[make_pair(r-1, cc)]);
      int d = (m.find(make_pair(r, cc-1)) == m.end() ? -1 : m[make_pair(r, cc-1)]);

      ans &= check(b, c, d, a);
    }

    // 右上
    if (r > 1 && cc+1 <= C) {
      int b = m.find(make_pair(r-1, cc)) == m.end() ? -1 : m[make_pair(r-1, cc)];
      int c = m.find(make_pair(r-1, cc+1)) == m.end() ? -1 : m[make_pair(r-1, cc+1)];
      int d = m.find(make_pair(r, cc+1)) == m.end() ? -1 : m[make_pair(r, cc+1)];

      ans &= check(b, c, a, d);
    }

    // 左下
    if (r+1 <= R && cc > 1) {
      int b = m.find(make_pair(r, cc-1)) == m.end() ? -1 : m[make_pair(r, cc-1)];
      int c = m.find(make_pair(r+1, cc-1)) == m.end() ? -1 : m[make_pair(r+1, cc-1)];
      int d = m.find(make_pair(r+1, cc)) == m.end() ? -1 : m[make_pair(r+1, cc)];

      ans &= check(b, a, c, d);
    }

    // 右下
    if (r+1 <= R && cc+1 <= C) {
      int b = m.find(make_pair(r, cc+1)) == m.end() ? -1 : m[make_pair(r, cc+1)];
      int c = m.find(make_pair(r+1, cc)) == m.end() ? -1 : m[make_pair(r+1, cc)];
      int d = m.find(make_pair(r+1, cc+1)) == m.end() ? -1 : m[make_pair(r+1, cc+1)];

      ans &= check(a, b, c, d);
    }

    int b = m.find(make_pair(r-1, cc-2)) == m.end() ? -1 : m[make_pair(r-1, cc-2)];
    int c = m.find(make_pair(r-1, cc-1)) == m.end() ? -1 : m[make_pair(r-1, cc-1)];
    int d = m.find(make_pair(r-1, cc)) == m.end() ? -1 : m[make_pair(r-1, cc)];
    int e = m.find(make_pair(r, cc-2)) == m.end() ? -1 : m[make_pair(r, cc-2)];
    int f = m.find(make_pair(r, cc-1)) == m.end() ? -1 : m[make_pair(r, cc-1)];
    ans &= check2(b, c, d, e, f, a);
  }

  cout << (ans ? "Yes" : "No") << endl;
}

