#include <bits/stdc++.h>
using namespace std;
class disjoint_set {
  public:
  vector<int> rank, prt, ptl;
  disjoint_set (int size) {
    rank.resize(size);
    prt.resize(size);
    ptl.resize(size);
    for (int i = 0; i < size; i++) {
      prt[i] = i;
      rank[i] = 0;
      ptl[i] = 0;
    }
  }
  int find (int x) {
    if (x == prt[x]){
      return x;
    } else {
      int r = find(prt[x]);
      ptl[x] += ptl[prt[x]];
      return prt[x] = r;
    }
  }
  bool is_equiv (int x, int y) {
    return find(x) == find(y);
  }
  bool unite (int x, int y, int w) {
    if (find(x) == find(y)) {
      return false;
    }
    w += ptl[x];
    w -= ptl[y];
    x = find(x);
    y = find(y);
    if (rank[x] < rank[y]) {
      swap(x, y);
      w *= -1;
    }
    prt[y] = x;
    ptl[y] = w;
    if (rank[x] == rank[y]) {
      rank[x]++;
    }
    return true;
  }
  int diff (int x, int y) {
    find(x);
    find(y);
    return ptl[y] - ptl[x];
  }
};
void err() {
  cout << "NO" << '\n';
  exit(0);
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int h, w, n;
  cin >> h >> w >> n;
  vector<pair<pair<int, int>, int>> cnd(n);
  int d = 0;
  for (int t = 0; t < n; t++) {
    int i, j, a;
    cin >> i >> j >> a;
    cnd[t] = {{--i, --j}, a};
    if (i == 0 && j == 0) {
      d = a;
    }
  }
  for (auto& p : cnd) {
    int i = p.first.first;
    int j = p.first.second;
    int& a = p.second;
    if (i > 0 && j > 0) {
      a += d;
    } else if (i == 0 && j == 0) {
      a = 0;
    }
  }
  disjoint_set djs(h + w - 1);
  int mina = 2e9;
  int maxb = -2e9;
  for (auto p : cnd) {
    int i = p.first.first;
    int j = p.first.second;
    int s = h - 1 + j;
    int t = h - 1 - i;
    int w = p.second;
    if (djs.is_equiv(s, t)) {
      if (djs.diff(s, t) != w) {
        err();
      }
    } else {
      djs.unite(s, t, w);
      for (int r = 0; r < 2; r++) {
        if (djs.is_equiv(h - 1, s)) {
          if (s < h - 1) {
            mina = min(mina, djs.diff(h - 1, s));
          } else if (h - 1 < s) {
            maxb = max(maxb, djs.diff(s, h - 1));
          }
        }
        swap(s, t);
      }
    }
  }
  if (mina - maxb < d) {
    err();
  }
  cout << "YES" << '\n';
  return 0;
}

