#define REP(i, n) for (int i = 0; i < (int)n; i++)
typedef tuple<int, int> tii;

int R, C;
int N;
int r, c, a;


// 0 1
// 2 3
int dr[]{ 0, 1, 1 };
int dc[]{ 1, 0, 1 };
int coer[]{ 1, -1 };
int coec[]{ 1, -1 };

int dx[]{ 0, 1, 1, 1, 0, -1, -1, -1 };
int dy[]{ -1, -1, 0, 1, 1, 1, 0, -1 };

map<tii, int> fix;
map<tii, int> masu;
vector<tii>   emp;

bool test(vector<tii> & emp)
{


  for (tii & e : emp) {
    int er, ec;
    tie(er, ec) = e;

    REP(i, 2) REP(j, 2) {
      bool all = true;
      int sum = 0;
      REP(k, 3) {
        int sr = coer[i] * dr[k] + er;
        int sc = coec[j] * dc[k] + ec;
        if (sr <= 0 || sc <= 0) {
          all = false;
          break;
        }
        if (!masu.count(tii(sr, sc))) {
          all = false;
          break;
        }
        if (k != 2)
          sum += masu[tii(sr, sc)];
        else
          sum -= masu[tii(sr, sc)];
      }

      if (all) {
        if (sum < 0) {
          return false;
        }
        if (fix.count(tii(er, ec))) {
          int already = fix[tii(er, ec)];
          if (already != sum) {
            return false;
          }
        } else {
          masu[tii(er, ec)] = sum;
          fix[tii(er, ec)] = sum;
        }
      }
    }
  }
  return true;
}

int main()
{
  cin >> R >> C >> N;

  REP(i, N) {
    cin >> r >> c >> a;
    masu[tii(r, c)] = a;
    REP(i, 8) {
      int rr = r + dx[i];
      int cc = c + dy[i];
      if (rr > 0 && cc > 0)
        emp.push_back(tii(rr, cc));
    }
  }


  bool f = true;
  sort(emp.begin(), emp.end());
  f &= test(emp);
  sort(emp.rbegin(), emp.rend());
  f &= test(emp);

  cout << (f ? "Yes" : "No") << endl;

  // map<tii, int>::iterator it = fix.begin();


  return 0;
}

