bool flag;

void dfs(int v, const vector<vector<pair<int,int>>> &edges, map<int,ll> &val) {
  for (auto p: edges[v]) {
    int to = p.first, c = p.second;
    if (val.count(to)) {
      if (val[to] != val[v] + c) flag = false;
    }
    else {
      val[to] = val[v] + c;
      dfs(to, edges, val);
    }
  }
}

