ll H,W,N;
vector<Edge> edge[100001 * 2];
ll w[100001 * 2];
ll ymin;
ll xmin;

// 頂点i の重みw[i] を求めていく
// 矛盾があればfalse
bool dfs(ll i){
    if(i<H){
        //cout<<"y="<<i;
        ymin=min(ymin,w[i]);
    } else {
        //cout<<"x="<<(H-i);
        xmin=min(xmin,w[i]);
    }
    //cout<<", w="<<w[i]<<endl;
    for(auto e: edge[i]){
        if(w[e.to]!=LLONG_MAX){ // 頂点e.toが決定済み
            if(w[i]+w[e.to]!=e.val)
                return false;
        } else {           // 頂点e.toが未決定
            w[e.to]  = e.val - w[i]; // 仮決定
            if(!dfs(e.to)){
                return false;
            }
        }
    }
    return true;
}

signed main() {
    cin>>H>>W>>N;

    rep(i,0,N){
        ll y,x,a;
        cin>>y>>x>>a;
        y--; x--;
        edge[y].emplace_back(x+H, a);
        edge[x+H].emplace_back(y, a);
    }

    rep(i,0,100001*2)
        w[i]=LLONG_MAX;

    rep(i,0,H+W){
        if (edge[i].size() == 0 || w[i] != LLONG_MAX) // すでに決定済み，あるいは決定不要
            continue;

        w[i] = 0; // 仮決定
        ymin=LLONG_MAX/2-1;  // そのブロックにおけるY軸の数列の最小値
        xmin=LLONG_MAX/2-1;

        if(!dfs(i) || (xmin+ymin)<0){
            cout<<"No"<<endl;
            return 0;
        }
    }

    cout<<"Yes"<<endl;

    return 0;
}

