int usedx[N], usedy[N];
vector<int> xg[N], yg[N];
int sol() {
  ios::sync_with_stdio(false), cin.tie(0);
  cin >> h >> w >> n;
  for(int i = 0; i < n; i++) {
    cin >> r[i] >> c[i] >> a[i];
    r[i]--; c[i]--;
    if(!usedy[r[i]]) {
      y[r[i]] = a[i] - x[c[i]];
    } else if(!usedx[c[i]]) {
      x[c[i]] = a[i] - y[r[i]];
    }
    dump(y[r[i]], x[c[i]], a[i]);
    usedy[r[i]] = 1;
    usedx[c[i]] = 1;
    yg[r[i]].emplace_back(c[i]);
    xg[c[i]].emplace_back(r[i]);
  }
  for(int i = 0; i < n; i++) {
    if(y[r[i]] + x[c[i]] != a[i]) return 0;
  }
  vector<vector<int>> used(2, vector<int>(N));
  for(int i = 0; i < w; i++) if(!used[1][i]) {
    queue<pair<int, int>> q;
    q.emplace(i, 1);
    ll mi[2] = {(ll) 1e18, (ll) 1e18};
    while(q.size()) {
      int i, xx; tie(i, xx) = q.front(); q.pop();
      if(used[xx][i]) continue;
      dump(i, xx);
      used[xx][i] = 1;
      vector<ll> &v = xx ? x : y;
      vector<int>* g = xx ? xg : yg;
      mi[xx] = min(mi[xx], v[i]);
      dump(v[i]);
      for(int to : g[i]) if(!used[!xx][to]) q.emplace(to, !xx);
    }
    if(mi[0] + mi[1] < 0) return 0;
  }
  return 1;
}

