vector<char> used;
vector<vector<pair<int, int>>> g;
vector<int> col;
vector<int> num_comp;
vector<int> min_col, max_col;

bool have_ans = true;

void dfs(int v, int cur_col, int comp) {
	if (used[v]) {
		if (col[v] != cur_col) {
			have_ans = false;
		}
		return;
	}
	col[v] = cur_col;
	used[v] = true;
	num_comp[v] = comp;
	min_col[comp] = min(min_col[comp], cur_col);
	max_col[comp] = max(max_col[comp], cur_col);
	for (auto item : g[v]) {
		int to = item.first;
		int diff = item.second;
		dfs(to, cur_col + diff, comp);
	}
}

void solve(bool read) {
	int n, m;
	cin >> n >> m;
	int k;
	cin >> k;
	vector<vector<pair<int, int>>> lists(n);
	for (int i = 0; i < k; ++i) {
		int x, y, a;
		cin >> x >> y >> a;
		--x; --y;
		lists[x].push_back({ y, a });
	}

	used.assign(m, false);
	g.resize(m);

	for (int i = 0; i < n; ++i) {
		sort(all(lists[i]));
		for (int j = 0; j + 1 < lists[i].size(); ++j) {
			int nex = lists[i][j + 1].first, cur = lists[i][j].first;
			int diff = lists[i][j + 1].second - lists[i][j].second;
			g[cur].push_back({ nex, diff });
			g[nex].push_back({ cur, -diff });
		}
	}

	col.assign(m, 0);
	num_comp.assign(m, 0);
	int cnt = 0;
	for (int i = 0; i < m; ++i) {
		if (!used[i]) {
			min_col.push_back(1e18);
			max_col.push_back(-1e18);
			dfs(i, 0, cnt);
			++cnt;
			if (!have_ans) {
				cout << "No\n";
				return;
			}
		}
	}

	for (int i = 0; i < n; ++i) {
		for (auto item : lists[i]) {
			int y = item.first;
			int cur_col = item.second;
			int cur_min = cur_col - col[y] + min_col[num_comp[y]];
			int cur_max = cur_col - col[y] + max_col[num_comp[y]];

			if (cur_min < 0) {
				cout << "No\n";
				return;
			}

		}
	}

	cout << "Yes\n";

}

