using namespace std;
typedef long long ll;
const int maxn=100005;

int R,C,n;
struct P {
    int x,y,z;
    P(){}
    P(int x,int y,int z):x(x),y(y),z(z) {}
    bool operator<(const P&a) const{
        return x==a.x?y<a.y:x<a.x;
    }
}p[maxn];
vector<int>pos;

map<pair<int,int>,int > umap;

bool check() {
    int limit = (int)sqrt(n);
    for(int i=0;i<pos.size();i++){
        int nxt = n;
        if(i < pos.size() -1 )nxt = pos[i+1];
        if(nxt - pos[i]<limit)continue;
        for(int j=0;j<pos.size();j++){
            if(i==j)continue;
            int prex=-1,prey=-1;
            int r=pos[j];
            for(int k=pos[i];k<n&&p[k].x==p[pos[i]].x;k++){
                while(r<n&&p[r].x==p[pos[j]].x&&p[r].y<p[k].y)r++;
                if(r<n&&p[r].y==p[k].y){
                    if(prex==-1) {
                        prex=k,prey=r;
                    } else {
                        if(p[k].z-p[r].z!=p[prex].z-p[prey].z)return 0;
                        prex=k,prey=r;
                    }
                }
            }
        }
    }
    for(int i=0;i<pos.size();i++){
        int nxt = n;
        if(i < pos.size() -1 )nxt = pos[i+1];
        if(nxt - pos[i]>=limit)continue;
        for(int j=pos[i];j<nxt;j++)
         for(int k=j+1;k<nxt;k++){
            map<pair<int,int>,int>::iterator it = umap.find(make_pair(p[j].y,p[k].y));
            if(it==umap.end()){
                umap[make_pair(p[j].y,p[k].y)] = p[j].z-p[k].z;
            } else {
                if (p[j].z-p[k].z!=umap[make_pair(p[j].y,p[k].y)])return 0;
            }
         }
    }
    return 1;
}

int main() {
   // freopen("in.cpp","r",stdin);
    scanf("%d%d%d",&R,&C,&n);
    for(int i=0;i<n;i++)scanf("%d%d%d",&p[i].x,&p[i].y,&p[i].z);
    sort(p,p+n);
    pos.push_back(0);
    for(int i=1;i<n;i++)if(p[i].x!=p[i-1].x)pos.push_back(i);
    if(check())printf("Yes\n");
    else printf("No\n");
    return 0;
}

