struct union_find{
	typedef unsigned size_type;
	vector<int> par;
	size_type grs;
	explicit union_find(size_type n = 0){ init(n); }
	void init(size_type n){
		par.assign(n, -1);
		grs = n;
	}
	size_type find(size_type x){
		if(par[x] < 0){ return x; }
		return par[x] = find(par[x]);
	}
	size_type size(size_type x){
		return -par[find(x)];
	}
	size_type groups(){
		return grs;
	}
	bool unite(size_type x, size_type y){
		x = find(x);
		y = find(y);
		if(x == y){ return false; }
		if(par[x] < par[y]){ swap(x, y); }
		par[y] += par[x];
		par[x] = y;
		--grs;
		return true;
	}
	bool same(size_type x, size_type y){
		return find(x) == find(y);
	}
};

const LL INF = LLONG_MAX / 5;
void calcdifs(VV(pll) &v1, int w, vector<LL> &res){
	int m = v1.size() - 2;
	VV(pll) G(w + 2);
	union_find uf(w + 2);
	for(int i = 1; i <= m; ++i){
		auto &v = v1[i];
		int sz = v.size();
		for(int j = 1; j < sz; ++j){
			LL d = v[j].second - v[j - 1].second;
			G[v[j - 1].first].emplace_back(v[j].first, d);
			G[v[j].first].emplace_back(v[j - 1].first, -d);
			uf.unite(v[j - 1].first, v[j].first);
		}
	}

	res.assign(w + 2, INF);
	queue<int> q;
	for(int s = 1; s <= w; ++s){
		if(uf.find(s) == s){
			res[s] = 0;
			q.push(s);
		}
	}
	while(!q.empty()){
		int u = q.front();
		q.pop();
		for(cauto p : G[u]){
			if(res[p.first] == INF){
				res[p.first] = res[u] + p.second;
				q.push(p.first);
			}
		}
	}

	vector<LL> ofs(w + 2);
	for(int i = 1; i <= w; ++i){
		LL &x = ofs[uf.find(i)];
		x = min(x, res[i]);
	}
	for(int i = 1; i <= w; ++i){
		res[i] -= ofs[uf.find(i)];
	}
}

bool solve(){
	int h, w, n;
	scanf("%d%d%d", &h, &w, &n);

	vector<int> ys(n), xs(n), as(n);
	for(int i = 0; i < n; ++i){
