	}

	VV(pll) v1(h + 2), v2(w + 2);
	for(int i = 0; i < n; ++i){
		v1[ys[i]].emplace_back(xs[i], as[i]);
		v2[xs[i]].emplace_back(ys[i], as[i]);
	}
	for(auto &v : v1){
		sort(ALL(v));
	}
	for(auto &v : v2){
		sort(ALL(v));
	}

	vector<LL> dify, difx;
	calcdifs(v1, w, difx);
	calcdifs(v2, h, dify);

	for(int i = 0; i < n; ++i){
		LL t = as[i] - dify[ys[i]] - difx[xs[i]];
		if(t < 0){ return false; }
		dify[i] += t;
	}
	for(int i = 0; i < n; ++i){
		if(as[i] != dify[ys[i]] + difx[xs[i]]){
			return false;
		}
	}

	return true;
}

