	cin >> H >> W >> N;
	for (long long i = 0; i < N; i++) {
		cin >> x[i] >> y[i] >> a[i];
		x_1[x[i]].push_back(make_pair(y[i], a[i]));
	}
	initialize();
	if (solve_ai() == false || solve_bi() == false) { cout << "No" << endl; }
	else { cout << "Yes" << endl; }
	return 0;
}

