int main() {
  cin >> R >> C;
  cin >> N;

  for (int i=0; i<N; i++) {
    int r, c, a;
    cin >> r >> c >> a;
    edges[r-1  ].push_back(P(c-1+R, a));
    edges[c-1+R].push_back(P(r-1,   a));
  }

  for (int i=0; i<R+C; i++) {
    if (vis[i]) continue;
    vis[i] = true;
    queue<int> q;
    q.push(i);
    A[i] = 0;
    long long m1 = INF, m2 = INF;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      for (P p : edges[u]) {
        int v = p.first;
        if (vis[v]) continue;
        vis[v] = true;
        A[v] = (long long)p.second - A[u];
        if (v < R) m1 = min(m1, A[v]);
        else       m2 = min(m2, A[v]);
        q.push(v);
      }
    }
    if (m1 + m2 < 0) {
      cout << "No\n";
      return 0;
    }
  }
  for (int i=0; i<R; i++) {
    for (auto p : edges[i]) {
      int j = p.first;
      if (A[i] + A[j] != p.second) {
        cout << "No\n";
        return 0;
      }
    }
  }
  cout << "Yes\n";
  return 0;
}

