struct thing {
	bool t; ll v;
	//t = 0 means it is v+x
	//t = 1 means it is v-x
};

map<pair<int, int>, thing> k;
set<pair<int, int>> td;
ll mn = -1e18, mx = 1e18;

void dfs (int r, int c, bool t, ll v) {
	if (k.count(MP(r,c))) {
		if (k[MP(r,c)].t != t || k[MP(r,c)].v != v) {
			puts("No");
			exit(0);
		}
		return;
	}
	k[MP(r,c)] = {t,v};
	if (t) {
		//v-x >= 0
		//v >= x
		//x is max v
		mx = min(mx, v);
	} else {
		//v+x >= 0
		//x >= -v
		//x is at least -v
		mn = max(mn, -v);
	}
	for (auto to : sum[MP(r,c)]) {
		dfs(to.first.first, to.first.second, t^1, to.second - v);
	}
	for (auto to : sum[MP(r,c)]) {
		dfs(to.first.first, to.first.second, t, to.second + v);
	}
}

