    Graph(int V): V(V){
        G = vector<vector<edge>>(V, vector<edge>(0));
    }

    void add_edge(int from, int to, int cost){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    bool dfs(vec &val, int v, vector<bool> &used, int c, int &m1, int &m2, int R){
        used[v] = true;
        val[v] = c;
        if(v < R) m1 = min(m1, c);
