        REP(i, G[v].size()){
            if(used[G[v][i].to]){
                if(val[v] + val[G[v][i].to] != G[v][i].cost) return false;
            }else{
                if(!dfs(val, G[v][i].to, used, G[v][i].cost - val[v], m1, m2, R)) return false;
            }
        }
        return true;
    }

};

