	Edge(ll to, ll cost):t(to),c(cost){}
	Edge(){}
};

vector<ll> nodes;
vector<vector<ll> > groups;
ll R, C;

bool DFS(ll node, vector<vector<Edge> >& edge, ll& xmin, ll& ymin) {
	bool res = true;
	groups.back().push_back(node);
	for (auto &to : edge[node]) {
		if (nodes[to.t] == std::numeric_limits<ll>::max()) {
			nodes[to.t] = to.c - nodes[node];
			if (to.t < R) xmin = min(xmin, nodes[to.t]);
			else ymin = min(ymin, nodes[to.t]);
			res &= DFS(to.t, edge, xmin, ymin);
		}
		else {
			if (nodes[to.t] != to.c - nodes[node]) return false;
		}
	}
	return res;
}

void solve() {
	cin >> R >> C;
	ll N = in();
	nodes.resize(R + C, numeric_limits<ll>::max());
	vector<vector<Edge> > edge(R+C);
	REP(i, N) {
		ll r, c, a; cin >> r >> c >> a;
		--r; --c;
		edge[r].emplace_back(R+c,a);
		edge[R+c].emplace_back(r, a);
	}

	bool res = true;
	ll xmin, ymin;
	REP(i, R + C) if(nodes[i] == numeric_limits<ll>::max() and edge[i].size() > 0) {
		xmin = ymin = numeric_limits<ll>::max();
		groups.push_back(vector<ll>());
		nodes[i] = 0;
		res &= DFS(i, edge,xmin, ymin);
		res &= (xmin + ymin >= 0);
		if (not res) {
			cout << "No" << endl;
			return;
		}
	}
	cout << "Yes" << endl;

}

