inline bool valid(PI pos) {
	if (min(pos.F, pos.S) < 0) {
		return false;
	}
	if (pos.F >= r)return false;
	if (pos.S >= c)return false;
	return true;
}

inline bool has(PI pos) {
	return m2.find(pos) != m2.end();
}

inline bool chk_upd(PI pos) {
	if (!valid(pos))return true;
	li tmp[4] = { -1, -1, -1, -1};
	li cnt = 0;
	PI now[4];
	rep(i, 4) {
		now[i] = {pos.F + dy[i] + 1, pos.S + dx[i] + 1};
		if (has(now[i])) {
			tmp[i] = m2[now[i]];
			cnt++;
		}
	}
	if (cnt < 3)return true;
	if (cnt == 4) {
		if (tmp[0] + tmp[3] != tmp[1] + tmp[2]) {
			return false;
		} else {
			return true;
		}
	}
	// cnt == 3
	if (tmp[0] < 0) {
		tmp[0] = tmp[1] + tmp[2] - tmp[3];
		if (tmp[0] < 0)return false;
		m2[now[0]] = tmp[0];
		return chk_upd(now[0]);
	}
	if (tmp[1] < 0) {
		tmp[1] = tmp[0] + tmp[3] - tmp[2];
		if (tmp[1] < 0)return false;
		m2[now[1]] = tmp[1];
		return chk_upd(now[1]);
	}
	if (tmp[2] < 0) {
		tmp[2] = tmp[0] + tmp[3] - tmp[1];
		if (tmp[2] < 0)return false;
		m2[now[2]] = tmp[2];
		return chk_upd(now[2]);
	}
	if (tmp[3] < 0) {
		tmp[3] = tmp[1] + tmp[2] - tmp[0];
		if (tmp[3] < 0)return false;
		m2[now[3]] = tmp[3];
		return chk_upd(now[3]);
	}
	return true;
}

