int R, C, N, r[100005], c[100005], a[100005], mn[100005];

int dfs(int v, int prv, Vec< map< int, int > >& edges, Vec< int >& path, Vec< bool >& vis) {
	//cerr << v << " " << prv << endl;
	if (vis[v]) return v;
	vis[v] = true;
	path.push_back(v);
	for (auto p : edges[v]) {
		int u = p.first;
		if (u == prv) continue;
		int res = dfs(u, v, edges, path, vis);
		if (res != -1) return res;
	}
	path.pop_back();
	return -1;
}

bool check() {	
	Vec< Vec< pii > > pool(R, Vec< pii >());
	for_(i,0,N) pool[r[i]-1].push_back(pii(c[i]-1, a[i]));

	Vec< map< int, int > > trans(C, map< int, int >());
	for_(y,0,R) {
		sort(allof(pool[y]));
		int n = pool[y].size();
		for_(i,0,n-1) {
			pii pa = pool[y][i], pb = pool[y][i+1];
			int cx = pa.first, nx = pb.first, dst = pb.second - pa.second;
			if (trans[cx].count(nx) && trans[cx][nx] != dst) return false;
			trans[cx][nx] = dst;
			trans[nx][cx] = dst;
		}
	}

	vector< bool > vis(C, false);
	Vec< lint > dp(C, 0);

	for_(x,0,C) dp[x] = mn[x];

	for_(x,0,C) {
		for (auto p : trans[x]) {
			int v = p.first;
			lint d = p.second;
			minUpdate(dp[v], dp[x] + d);
		}
	}

	int val = *min_element(allof(dp));
	if (val < 0) return false;

	dp.assign(C, 0);
	for_(x,0,C) {
		if (vis[x]) continue;
		Vec< int > path;
		int s = dfs(x, -1, trans, path, vis);
		if (s == -1) continue;

		Vec< int > idx;
		bool flag = false;
		for (int x : path) {
			if (x == s) flag = true;
			if (flag) idx.push_back(x);
		}
		sort(allof(idx));

		dp[idx[0]] = mn[idx[0]];
		for (int x : idx) {
			for (auto p : trans[x]) {
				int v = p.first;
				lint d = p.second;
				if (v < x) continue;

				if (dp[x] + d < 0) return false;

				if (dp[v] == -1) {
					dp[v] = dp[x] + d;
				} else {
					if (dp[v] != dp[x] + d) return false;
				}
			}
		}
	}

	return true;
}

int main() {
	cin >> R >> C;
	cin >> N;
	for_(i,0,N) cin >> r[i] >> c[i] >> a[i];

	for_(i,0,C) mn[i] = 1e9;
	for_(i,0,N) minUpdate(mn[c[i]-1], a[i]);
	bool ans = check();

	swap(R, C);
	for_(i,0,N) swap(r[i], c[i]);

	for_(i,0,C) mn[i] = 1e9;
	for_(i,0,N) minUpdate(mn[c[i]-1], a[i]);
	ans &= check();

	puts(ans ? "Yes" : "No");
}
