      mjdx[root] = j;
    }
  }
  DEBUG_VEC(midx);
  DEBUG_VEC(mjdx);

  ll mi = INF;
  rep (i, h) {
    rep (j, i2j[i].size()) {
      ll idx = i2j[i][j].first, val = i2j[i][j].second;
      //DEBUG(idx); DEBUG(val);
      int rooti = uf.find(i + w), rootj = uf.find(idx);
      //DEBUG(pii(rooti, rootj));
      val = val + uf.diff(i + w, rooti) + uf.diff(idx, rootj);
      int ii = midx[rooti - w], jj = mjdx[rootj];
      //DEBUG(pii(ii, jj));
      val = val + uf.diff(rooti, ii + w) + uf.diff(rootj, jj);
      //DEBUG(val);
      chmin(mi, val);
    }
  }
  if (mi < 0) {
    cout << "No" << endl;
  }
  else {
    cout << "Yes" << endl;
  }
}

