        lu = (ru + ld) - rd;
        if (lu < 0) return false;
        a[i][j] = lu;
      }
      if (lu < INF && ld == INF && ru < INF && rd < INF) {
        ld = (lu + rd) - ru;
        if (ld < 0) return false;
        a[i + 1][j] = ld;
      }
      if (lu < INF && ld < INF && ru == INF && rd < INF) {
        ru = (lu + rd) - ld;
        if (ru < 0) return false;
        a[i][j+1] = ru;
      }
      if (lu < INF && ld < INF && ru < INF && rd == INF) {
        rd = (ru + ld) - lu;
        if (rd < 0) return false;
        a[i + 1][j + 1] = rd;
      }
    }
  }
  return true;
}

