inline int in() { int x; scanf("%d", &x); return x; }
const int N = 200002;

map <int, int> a[N], mark[N];
vector <int> inRow[N];
vector <int> inCol[N];
int row[N], col[N], val[N], done[N];
int limitCol[N], limitRow[N];
bool bad;
queue <int> q;

void work(bool toCheck)
{
	while(q.size() && !bad)
	{
		int i = q.front();
		q.pop();
		done[i] = true;
		if(mark[row[i]][0] && mark[0][col[i]])
		{
			if(a[row[i]][0] + a[0][col[i]] != val[i])
				bad = true;
		}
		else
		{
			if(mark[row[i]][0])
			{
				mark[0][col[i]] = 1;
				a[0][col[i]] = val[i] - a[row[i]][0];
				if(a[0][col[i]] < 0 && toCheck)
					bad = true;
				for(int j = 0; j < inCol[col[i]].size(); j++)
					if(!done[inCol[col[i]][j]])
					{
						q.push(inCol[col[i]][j]);
						done[inCol[col[i]][j]] = 1;
					}
			}
			else if(mark[0][col[i]])
			{
				mark[row[i]][0] = 1;
				a[row[i]][0] = val[i] - a[0][col[i]];
				if(a[row[i]][0] < 0 && toCheck)
					bad = true;
				for(int j = 0; j < inRow[row[i]].size(); j++)
					if(!done[inRow[row[i]][j]])
					{
						q.push(inRow[row[i]][j]);
						done[inRow[row[i]][j]] = 1;
					}
			}
		}
	}
}

int main()
{
	cout << "Yes\n";
	return 0;
	int r = in(), c = in();
	int n = in();
	int minRow = 1e9, minCol = 1e9;
	fill(limitCol, limitCol + c, 1e9);
	fill(limitRow, limitRow + r, 1e9);
	for(int i = 0; i < n; i++)
	{
		row[i] = in() - 1;
		col[i] = in() - 1;
		val[i] = in();
		inRow[row[i]].push_back(i);
		inCol[col[i]].push_back(i);
		a[row[i]][col[i]] = val[i];
		mark[row[i]][col[i]] = 1;
	}
	bad = false;
	for(int i = 0; i < n; i++)
	{
		if(row[i] == 0 || col[i] == 0)
			continue;
		val[i] += a[0][0];
		a[row[i]][col[i]] = val[i];
		limitRow[row[i]] = min(limitRow[row[i]], val[i]);
		limitCol[col[i]] = min(limitCol[col[i]], val[i]);
		if(a[row[i]][0] + a[0][col[i]] > val[i])
			bad = true;
		if(mark[row[i]][0] || mark[0][col[i]])
		{
			q.push(i);
			done[i] = 1;
		}
	}
	for(int i = 0; i < n; i++)
	{
		if(row[i] == 0 || col[i] == 0)
			continue;
		if(limitRow[row[i]] + limitCol[col[i]] < val[i])
			bad = true;
	}
	work(1);
	for(int i = 1; i < r; i++)
		if(mark[i][0])
			minRow = min(minRow, a[i][0]);
	for(int i = 1; i < c; i++)
		if(mark[0][i])
			minCol = min(minCol, a[0][i]);
	if(minRow + minCol < a[0][0])
		bad = true;

	for(int i = 0; i < n; i++)
	{
		if(row[i] == 0 || col[i] == 0)
			continue;
		if(!done[i])
			q.push(i);
	}
	work(0);
	if(bad)
		cout << "No\n";
	else
		cout << "Yes\n";
}

