int head[MAXN],sumE;
int val[MAXN],xmin,ymin;
bool vis[MAXN];
bool used[MAXN];
void add(int u,int v,int c) {
    E[++sumE].to = v;
    E[sumE].next = head[u];
    E[sumE].val = c;
    head[u] = sumE;
}
bool dfs(int u) {
    vis[u] = 1;
    for(int i = head[u] ; i ; i = E[i].next) {
	int v = E[i].to;
	if(!vis[v]) {
	    val[v] = E[i].val - val[u];
	    if(!dfs(v)) return false;
	}
	else {
	    if(val[u] + val[v] != E[i].val) return false;
	}
    }
    return true;
}
void find_min(int u) {
    used[u] = 1;
    if(u <= R) xmin = min(xmin,val[u]);
    if(u > R) xmin = min(ymin,val[u - R]);
    for(int i = head[u] ; i ; i = E[i].next) {
	int v = E[i].to;
	if(!used[v]) find_min(v);
    }
}
void Solve() {
    read(R);read(C);read(N);
    int a,b,c;
    for(int i = 1 ; i <= N ; ++i) {
	read(a);read(b);read(c);
