							next = 1;
						}
						else if (e != -1 && e1 != -1) {
							if (d + e1 != d1 + e) {
								ans = 0; break;
							}
						}
					}
					if (i < r) {
						ll e = -1, e1 = -1, i1 = i + 1;
						if (arr[i1].count(c)) e = arr[i1][c];
						if (arr[i1].count(c1)) e1 = arr[i1][c1];
						if (e == -1 && e1 != -1) {
							if (d1 > d + e1) {
								ans = 0; break;
							}
							arr[i1][c] = d + e1 - d1;
							next = 1;
						}
						else if (e != -1 && e1 == -1) {
							if (d > d1 + e) {
								ans = 0; break;
							}
							arr[i1][c1] = d1 + e - d;
							next = 1;
						}
						else if (e != -1 && e1 != -1) {
							if (d + e1 != d1 + e) {
								ans = 0; break;
							}
						}
					}
				}

				it++;
			}
		}
	}
