const int INF = 1145141919;

using P = pair<int, int>;

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	int R, C, N;
	cin >> R >> C >> N;
	map<P, int> memo;
	priority_queue<P, vector<P>, greater<P> > q;
	for (int i = 0; i < N; i++) {
		int r, c, a;
		cin >> r >> c >> a;
		r--;
		c--;
		P pos(r, c);
		q.push(pos);
		memo[pos] = a;
	}
	bool ans = true;
	vector<int> diff(R, INF);
	while (!q.empty()) {
		P pos = q.front();
		q.pop();
		int r = pos.first, c = pos.second;
		P b(r + 1, c);
		if (memo.find(b) == memo.end()) {
			if (diff[r] != INF) {
				if (memo[pos] - diff[r] < 0) {
					ans = false;
					break;			
				} else {
					q.push(b);
					memo[b] = memo[pos] - diff[r];
				}
			}
		} else {
			int d = memo[pos] - memo[b];
			if (diff[pos.first] == INF) {
				diff[pos.first] = d;
			} else {
				ans = false;
				break;
			}			
		}
		P u(r - 1, c);
		if (memo.find(u) == memo.end()) {
			if (r > 0 && diff[r - 1] != INF) {
				if (memo[pos] + diff[r - 1] < 0) {
					ans = false;
					break;			
				} else {
					q.push(u);
					memo[u] = memo[pos] + diff[r - 1];
				}				
			}
		}
	}
	cout << (ans ? "Yes" : "No") << endl;
	return 0;
}

