		a [i] = 0 ;
		while ( fr ^ tl )  {
			int u = q [++ fr] ;
			for ( it = head [u] ; it ; it = it -> nxt )  {
				int r = it -> to, v = it -> w ;
				if ( inq [r] )  {
					if ( a [u] + a [r] != v )  {
						return puts ( "No" ), 0 ;
					}
					continue ;
				}
				q [++ tl] = r ;
				inq [r] = true ;
				a [r] = v - a [u] ;
			}
		}
		long long m1 = inf, m2 = inf ;
		for ( int j = 0 ; j < tl ; ++ j )  {
			if ( q [j] < h ) {
				smin ( m1, a [q [j]] ) ;
			}  else  {
				smin ( m2, a [q [j]] ) ;
			}
		}
		if ( m1 + m2 < 0 )  {
			return puts ( "No" ), 0 ;
		}
	}
	return puts ( "Yes" ), 0 ;
}

