bool vis[maxn];



const LL INF = 0x3f3f3f3f3f3f3f3f;


bool dfs(int u)
{
    for(int i = 0;i < G[u].size();++i)
    {
        int v = G[u][i].v;
        LL w = G[u][i].w;

        if(!vis[v])
        {
            vis[v] = 1;
            A[v] = w-A[u];
            if(!dfs(v)) return false;
        }
        else
        {
            if(A[v] + A[u] != w) return false;

        }
    }
    return true;

}


bool bfs(int u)
{
    queue<int> Q;
    Q.push(u);

    while(!Q.empty())
    {
        int u = Q.front(); Q.pop();

        for(int i = 0;i < G[u].size();++i)
        {
            int v = G[u][i].v;
            LL w = G[u][i].w;

            if(!vis[v])
            {
                vis[v] = 1;
                A[v] = w-A[u];
                Q.push(v);
            }
            else
            {
                if(A[v] + A[u] != w) return false;

            }
        }

    }

    return true;

}


bool judge()
{

    memset(vis,0,sizeof(vis));
    for(int i = 1;i <= R;++i)
        if(!vis[i])
        {
            vis[i] = 1;
            A[i] = 0;
            if(!bfs(i)) return false;
        }

    LL Minr = INF;
    LL Minc = INF;
    for(int i = 1;i <= R;++i)
