void solve() {
	int i,j,k,l,r,x,y; string s;

	FOR(i,101000) XX[i]=YY[i]=-1LL<<60;

	cin>>H>>W>>N;
	FOR(i,N) {
		cin>>Y[i]>>X[i]>>A[i];
		Y[i]--;
		X[i]--;
		YL[Y[i]].push_back({X[i],A[i]});
		XL[X[i]].push_back({Y[i],A[i]});
	}
	FOR(y,H) if(YL[y].size()>1) {
		sort(ALL(YL[y]));
		FOR(i,YL[y].size()-1) {
			XE[YL[y][i].first].push_back({YL[y][i+1].first,YL[y][i+1].second-YL[y][i].second});
			XE[YL[y][i+1].first].push_back({YL[y][i].first,YL[y][i].second-YL[y][i+1].second});
		}
	}
	FOR(x,W) if(XL[x].size()>1) {
		sort(ALL(XL[x]));
		FOR(i,XL[x].size()-1) {
			YE[XL[x][i].first].push_back({XL[x][i+1].first,XL[x][i+1].second-XL[x][i].second});
			YE[XL[x][i+1].first].push_back({XL[x][i].first,XL[x][i].second-XL[x][i+1].second});
		}
	}

	FOR(i,N) {
		if(XX[X[i]]==-1LL<<60 && YY[Y[i]]==-1LL<<60) {
			XX[X[i]]=A[i];
			YY[Y[i]]=0;
			dfsx(X[i]);
			dfsy(Y[i]);
		}
		if(YY[Y[i]]==-1LL<<60) {
			assert(0);
			YY[Y[i]]=A[i]-XX[X[i]];
			dfsy(Y[i]);
		}
		if(XX[X[i]]==-1LL<<60) {
			assert(0);
			XX[X[i]]=A[i]-YY[Y[i]];
			dfsx(X[i]);
		}
	}

	ll mix=1LL<<60, miy=1LL<<60;
	FOR(i,W) if(XX[i]!=-1LL<<60) mix=min(mix,XX[i]);
	FOR(i,H) if(YY[i]!=-1LL<<60) miy=min(miy,YY[i]);

	if(mix+miy<0) assert(0);
	else cout<<"Yes"<<endl;



}


