int get(P p, int k) {
    auto dy = dys[k];
    auto dx = dxs[k];
    vector<P> ps;
    int r = p.first;
    int cnt = 0;
    int c = p.second;
    ps.push_back(P(r, c));
    rep(i, 3) {
        int y = r + dy[i];
        int x = c + dx[i];
        if (!valid(y, x)) return -1;
        ps.push_back(P(y, x));
        cnt += A.count(P(y, x));
    }
    if (cnt != 3) return -1;

    return A[ps[3]] + A[ps[1]] - A[ps[2]];
}

bool check(int r, int c, int k) {
    auto dy = dys[k];
    auto dx = dxs[k];
    int cnt = 1;
    vector<P> ps;
    ps.push_back(P(r, c));
    rep(i, 3) {
        int y = r + dy[i];
        int x = c + dx[i];
        if (!valid(y, x)) return true;
        ps.push_back(P(y, x));
        cnt += A.count(P(y, x));
    }
    // printf("%d %d %d\n", r, c, cnt);
    if (cnt < 2) return true;
    if (cnt == 3) {
        vector<int> s;
        rep(i, 4) {
            if (i == k) continue;
            int t = get(ps[i], i);
            if (t >= 0) s.push_back(t);
        }
        rep(i, s.size()) if (s[i] != s[0]) return false;
        return true;
    } else {
        int s1 = A[ps[0]] + A[ps[2]];
        int s2 = A[ps[1]] + A[ps[3]];
        return s1 == s2;
    }
    return true;
}

