map<PII, int> v;
int n, m;

void add(PII a, int val) {
    assert(!v.count(a));
    v[a] = val;
    for (int x = max(0, a.x - 1); x <= a.x; ++x) {
        if (x + 1 >= n) continue;
        for (int y = max(0, a.y - 1); y <= a.y; ++y) {
            if (y + 1 >= m) continue;
            auto qv = pair<int, PII>(cnt[PII(x, y)], PII(x, y));
            q.erase(qv);
            cnt[PII(x, y)]++;
            qv.x++;
            q.insert(qv);
        }
    }
}



void solve() {
    n = nxt();
    m = nxt();
    int k = nxt();
    forn(i, k) {
        PII a;
        a.x = nxt() - 1;
        a.y = nxt() - 1;
        int val = nxt();
        add(a, val);

    }
    while (!q.empty()) {
        auto qv = *q.begin();
        q.erase(q.begin());
        if (qv.x < 3) break;
        PII a00 = qv.y;
        PII a10 = PII(a00.x + 1, a00.y);
        PII a01 = PII(a00.x, a00.y + 1);
        PII a11 = PII(a00.x + 1, a00.y + 1);
        if (qv.x == 4) {
            if (v[a00] + v[a11] != v[a01] + v[a10]) {
                cout << "No\n";
                return;
            }
        } else {
            PII who;
            int val = -1;
            if (!v.count(a00)) {
                who = a00;
                val = v[a01] + v[a10] - v[a11];
            }
            if (!v.count(a11)) {
                who = a11;
                val = v[a01] + v[a10] - v[a00];
            }
            if (!v.count(a01)) {
                who = a01;
                val = v[a00] + v[a11] - v[a10];
            }
            if (!v.count(a10)) {
                who = a10;
                val = v[a00] + v[a11] - v[a01];
            }
            if (val < 0) {
                cout << "No\n";
                return;
            }
            add(who, val);
        }
    }
    if (n * 1ll * m > 20) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }
}

