bool used[100000] = {};
vector<int> numx[100000],numy[100000];
int mix = INF,miy = INF;

signed main(){
	cin >> h >> w >> n;
	for(int i = 0;i < h;i++) x[i] = INF;
	for(int i = 0;i < w;i++) y[i] = INF;
	for(int i = 0;i < n;i++){
		cin >> a[i] >> b[i] >> c[i]; a[i]--;b[i]--;
		numx[a[i]].push_back(i);
		numy[b[i]].push_back(i);
	}
	for(int i = 0;i < n;i++){
		if(used[i]) continue;
		used[i] = true;
		if(mix < 0) y[b[i]] = -mix;
		else if(miy < 0) x[a[i]] = -miy;
		else x[a[i]] = 0;
		queue<int> que;
		que.push(i);
		while(!que.empty()){
			int p = que.front();que.pop();
			if(x[a[p]] == INF) x[a[p]] = c[p] - y[b[p]];
			else if(y[b[p]] == INF) y[b[p]] = c[p] - x[a[p]];
			else if(x[a[p]] + y[b[p]] != c[p]){
				cout << "No" << endl;
				return 0;
			}
			for(int to : numx[a[p]]){
				if(!used[to]){
					used[to] = true;
					que.push(to);
				}
			}
			for(int to : numy[b[p]]){
				if(!used[to]){
					used[to] = true;
					que.push(to);
				}
			}
			numx[a[p]].clear();
			numx[b[p]].clear();
		}
	}
	for(int i = 0;i < h;i++) mix = min(mix,x[i]);
	for(int i = 0;i < w;i++) miy = min(miy,y[i]);
	if(mix + miy >= 0) cout << "Yes" << endl;
	else cout << "No" << endl;
	return 0;
}

