    ll w1 = will, w2 = INF;
    tr(it, graph[v]) {
        pll t = dfs(it->first, it->second - node[v]);
        chmin(w1, t.second);
        chmin(w2, t.first);
    }

    return mp(w1, w2);
}

int main() {
