    rep(i, N) {
        int r, c, a;
        cin >> r >> c >> a;
        --r, --c;
        graph[r].push_back(mp(c + R, a));
        graph[c + R].push_back(mp(r, a));
    }

    rep(i, MAX_RC) {
        if (!used[i]) {
            pii t = dfs(i, 0);
            if (t.first + t.second < 0) {
                cout << "No" << endl;
                return 0;
            }
        }
    }

    cout << "Yes" << endl;

    return 0;
}

