struct edge
{
	long long to; long long len;
	bool operator<(const edge& rhs) const {
		return len > rhs.len;
	}
};

ll const MAX = 3e5 + 5;
ll const INF = 1e18 + 5;
vector<vector<edge>> G(MAX);
vll a(MAX);
vll p(MAX, INF);
vll ax(MAX), ay(MAX);

bool dfs(ll start, ll val) {
	stack<ll> st;
	ll minx = INF, miny = INF;
	st.push(start);
	p[start] = 0;
	while (!st.empty()) {
		ll cur = st.top();
		st.pop();
		if (cur % 2 == 0) {
			miny = min(miny, p[cur]);
		}
		else {
			minx = min(minx, p[cur]);
		}
		for (auto next_edge : G[cur]) {
			ll next = next_edge.to;
			ll cost = next_edge.len;
			if (p[next] == INF) {
				p[next] = cost - p[cur];
				st.push(next);
			}
			else {
				if (p[next] != cost - p[cur]) {
					return false;
				}
			}
		}
	}
	return (minx + miny >= 0);
}

