            if (fr == -1) fr = r;
            int qi = q->second;
            int tmp = a[ri] - a[qi];
            if (cnt != -INF && cnt != tmp*((r-fr)%2 == 0 ? 1 : -1)) {
                no();
            }
            cnt = tmp;
        }
        if (cnt != -INF) {
            for (auto p : c2r[i]) {
                int i = p.second, r = p.first;
                int mul = (r-fr)%2 == 0 ? 1 : -1;
                if (a[i]-(cnt*mul) < 0) no();
            }
        }
    }
