            if (fc == -1) fc = c;
            int qi = q->second;
            int tmp = a[ci] - a[qi];
            if (cnt != -INF && cnt != tmp * ((c-fc)%2 == 0 ? 1 : -1)) {
                no();
            }
            cnt = tmp;
        }
        if (cnt != -INF) {
            for (auto p : r2c[i]) {
                int i = p.second, c = p.first;
                int mul = (c-fc)%2 == 0 ? 1 : -1;
                if (a[i]-cnt*mul < 0) no();
            }
        }
