typedef pair<int, int> P;
map<int, int> dict_r[100000];
map<int, int> dict_c[100000];
map<int, int>::iterator it, it2;

bool solveH(int pre) {
	for (int i = 0; i < h; i++) {
		if (i == pre) continue;

		//i行目, pre行目を見て、[i][j]にも[pre][j]にも値があるようなjを列挙→固定値を求める
		int pnum = -1145141919;
		for (it = dict_r[pre].begin(); it != dict_r[pre].end(); it++) {
			//[pre][(*it).first]が存在するか？
			if (dict_r[i].find((*it).first) != dict_r[i].end()) {
				int num = dict_r[pre][(*it).first] - dict_r[i][(*it).first];
				if (pnum >= 0 && pnum != num) { return false; }
				pnum = num;
			}
		}
		if (pnum != -1145141919) {
			for (it = dict_r[pre].begin(); it != dict_r[pre].end(); it++) {
				if ((*it).second - pnum < 0) { return false; }
			}
			for (it = dict_r[i].begin(); it != dict_r[i].end(); it++) {
				if ((*it).second + pnum < 0) { return false; }
			}
		}
	}
	return true;
}

bool solveW(int pre) {
	for (int i = 0; i < w; i++) {
		if (i == pre) continue;

		//i列目, pre列目を見て、[j][i]にも[j][pre]にも値があるようなjを列挙→固定値を求める
		int pnum = -1145141919;
		for (it = dict_c[pre].begin(); it != dict_c[pre].end(); it++) {
			//[pre][(*it).first]が存在するか？
			if (dict_c[i].find((*it).first) != dict_c[i].end()) {
				int num = dict_c[pre][(*it).first] - dict_c[i][(*it).first];
				if (pnum >= 0 && pnum != num) { return false; }
				pnum = num;
			}
		}
		if (pnum != -1145141919) {
			for (it = dict_c[pre].begin(); it != dict_c[pre].end(); it++) {
				if ((*it).second - pnum < 0) { return false; }
			}
			for (it = dict_c[i].begin(); it != dict_c[i].end(); it++) {
				if ((*it).second + pnum < 0) { return false; }
			}
		}
	}
	return true;
}

signed main() {
	int i;

	cin >> h >> w;
	cin >> n;

	static int cnt_r[100000] = {0};
	static int cnt_c[100000] = {0};

	for (i = 0; i < n; i++) {
		cin >> r >> c >> a;
		r--; c--;
		dict_r[r].insert(P(c, a));
		dict_c[c].insert(P(r, a));
		cnt_r[r]++;
		cnt_c[c]++;
	}

	for (i = 0; i < h; i++) { if (cnt_r[i] * h <= n) break; }
