  };

  auto fourCheck = [&](int y, int x) {
    if(FOUND(y, x + 1) && FOUND(y + 1, x) && !FOUND(y + 1, x + 1)) {
      mp[{y + 1, x + 1}] = mp[{y, x + 1}] + mp[{y + 1, x}] - mp[{y, x}];// ダメなら負
    }
    else if(FOUND(y - 1, x) && FOUND(y, x + 1) && !FOUND(y - 1, x + 1)) {
      mp[{y - 1, x + 1}] = mp[{y - 1, x}] + mp[{y, x + 1}] - mp[{y, x}];
    }
    else if(FOUND(y - 1, x) && FOUND(y, x - 1) && !FOUND(y - 1, x - 1)) {
      mp[{y - 1, x - 1}] = mp[{y - 1, x}] + mp[{y, x - 1}] - mp[{y, x}];
    }
    else if(FOUND(y, x - 1) && FOUND(y + 1, x) && !FOUND(y + 1, x - 1)) {
      mp[{y + 1, x - 1}] = mp[{y, x - 1}] + mp[{y + 1, x}] - mp[{y, x}];
    }
  };

  rep(i, N) {
    scanf("%lld%lld%lld", &y, &x, &A);
    if(y == 1 && x == 1) a = A;
    if(y == 1 && x == C) b = A;
    if(y == R && x == 1) c = A;
    if(y == R && x == C) d = A;
    mp[{y, x}] = A;
    fourCheck(y, x);
  }

  for(auto e: mp) {
    int y, x; tie(y, x) = e.first;
  }

  ll ta = a, tb = b, tc = c, td = d;

  for(auto e: mp) {
    int y, x; tie(y, x) = e.first;
    if(y == R || x == C) continue;
    a = mp.find({y, x}) == mp.end() ? -1 : mp[{y, x}];
    b = mp.find({y, x+1}) == mp.end() ? -1 : mp[{y, x+1}];
    c = mp.find({y+1, x}) == mp.end() ? -1 : mp[{y+1, x}];
    d = mp.find({y+1, x+1}) == mp.end() ? -1 : mp[{y+1, x+1}];

    if(a >= 0 && b >= 0 && c >= 0 && d >= 0) {
      if(a + d == b + c);
      else no();
    }

    if(a >= 0 && b >= 0 && c >= 0) {
      if(a <= b + c);
      else no();
    }

    if(a >= 0 && b >= 0 && d >= 0) {
      if(b <= a + d);
      else no();
    }

    if(b >= 0 && c >= 0 && d >= 0) {
      if(d <= b + c);
      else no();
    }

    if(a >= 0 && c >= 0 && d >= 0) {
      if(c <= a + d);
      else no();
    }
  }

  a = ta, b = tb, c = tc, d = td;

  if(a >= 0 && b >= 0 && c >= 0 && d >= 0) {
    if(a + d == b + c) yes();
    else no();
  }

  if(a >= 0 && b >= 0 && c >= 0) {
    if(a <= b + c) yes();
    else no();
  }

  if(a >= 0 && b >= 0 && d >= 0) {
    if(b <= a + d) yes();
    else no();
  }

  if(b >= 0 && c >= 0 && d >= 0) {
    if(d <= b + c) yes();
    else no();
  }

  if(a >= 0 && c >= 0 && d >= 0) {
    if(c <= a + d) yes();
    else no();
  }



  yes();

  return 0;
}

