    int f = m.find(make_pair(r, cc-1)) == m.end() ? -1 : m[make_pair(r, cc-1)];
    ans &= check2(b, c, d, e, f, a);

    b = m.find(make_pair(r-1, cc-1)) == m.end() ? -1 : m[make_pair(r-1, cc-1)];
    c = m.find(make_pair(r-1, cc)) == m.end() ? -1 : m[make_pair(r-1, cc)];
    d = m.find(make_pair(r-1, cc+1)) == m.end() ? -1 : m[make_pair(r-1, cc+1)];
    e = m.find(make_pair(r, cc-1)) == m.end() ? -1 : m[make_pair(r, cc-1)];
    f = m.find(make_pair(r, cc+1)) == m.end() ? -1 : m[make_pair(r, cc+1)];
    ans &= check2(b, c, d, e, a, f);

    b = m.find(make_pair(r-1, cc)) == m.end() ? -1 : m[make_pair(r-1, cc)];
    c = m.find(make_pair(r-1, cc+1)) == m.end() ? -1 : m[make_pair(r-1, cc+1)];
    d = m.find(make_pair(r-1, cc+2)) == m.end() ? -1 : m[make_pair(r-1, cc+2)];
    e = m.find(make_pair(r, cc+1)) == m.end() ? -1 : m[make_pair(r, cc+1)];
    f = m.find(make_pair(r, cc+2)) == m.end() ? -1 : m[make_pair(r, cc+2)];
    ans &= check2(b, c, d, a, e, f);

    b = m.find(make_pair(r, cc-2)) == m.end() ? -1 : m[make_pair(r, cc-2)];
    c = m.find(make_pair(r, cc-1)) == m.end() ? -1 : m[make_pair(r, cc-1)];
    d = m.find(make_pair(r+1, cc-2)) == m.end() ? -1 : m[make_pair(r+1, cc-2)];
    e = m.find(make_pair(r+1, cc-1)) == m.end() ? -1 : m[make_pair(r+1, cc-1)];
    f = m.find(make_pair(r+1, cc)) == m.end() ? -1 : m[make_pair(r+1, cc)];
    ans &= check2(b, c, a, d, e, f);

    b = m.find(make_pair(r, cc-1)) == m.end() ? -1 : m[make_pair(r, cc-1)];
    c = m.find(make_pair(r, cc+1)) == m.end() ? -1 : m[make_pair(r, cc+1)];
    d = m.find(make_pair(r+1, cc-1)) == m.end() ? -1 : m[make_pair(r+1, cc-1)];
