    f = m.find(make_pair(r+1, cc+1)) == m.end() ? -1 : m[make_pair(r+1, cc+1)];
    ans &= check2(b, a, c, d, e, f);

    b = m.find(make_pair(r, cc+1)) == m.end() ? -1 : m[make_pair(r, cc+1)];
    c = m.find(make_pair(r, cc+2)) == m.end() ? -1 : m[make_pair(r, cc+2)];
    d = m.find(make_pair(r+1, cc)) == m.end() ? -1 : m[make_pair(r+1, cc)];
    e = m.find(make_pair(r+1, cc+1)) == m.end() ? -1 : m[make_pair(r+1, cc+1)];
    f = m.find(make_pair(r+1, cc+2)) == m.end() ? -1 : m[make_pair(r+1, cc+2)];
