using pii = pair<int, int>;

int h, w;
int n;
vector<tuple<int, int, int>> input;

const int INF = 1e18;

bool solve() {
    vector<vector<pii>> hols(h);
    vector<int> mi(w, INF);

    for (auto &e : input) {
        int i, j, a;
        tie(i, j, a) = e;
        hols[i].emplace_back(j, a);
        mi[j] = min(mi[j], a);
    }

    vector<tuple<int, int, int>> diff;
    for (auto &hol : hols) {
        sort(hol.begin(), hol.end());
        for (int k = 0; k < (int)hol.size() - 1; k++) {
            int l = hol[k].first;
            int r = hol[k + 1].first;
            int d = hol[k + 1].second - hol[k].second;
            diff.emplace_back(l, r, d);
        }
    }

    sort(diff.begin(), diff.end());

    vector<int> val(w, -1);
    for (auto &t : diff) {
        int l, r, d;
        tie(l, r, d) = t;

        //assert(hol_min[j1] != INF);
        //assert(hol_min[j2] != INF);

        if (val[l] == -1) {
            val[l] = mi[l];
        }
        if (val[r] == -1) {
            val[r] = val[l] + d;
        }
        if (val[l] + d != val[r] || val[l] < 0 || val[r] < 0) {
            return false;
        }
    }

    return true;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    while (cin >> h >> w >> n) {

        input.resize(n);
        for(auto &t : input){
            int i, j, a;
            cin >> i >> j >> a;
            --i; --j;
            t = { i, j, a };
        }

        bool yes = true;
        for (int _ = 0; _ < 2; _++) {
            yes &= solve();
            for (auto &e : input) swap(get<0>(e), get<1>(e));
            swap(h, w);
        }
        cout << (yes ? "Yes" : "No") << endl;
    }

}

