map<int, int> grid[112123];
map<int, int> prv;

int h, w;
int n;
int ldelta[112123];

int main()
{
	cin >> h >> w >> n;
	for (int i = 0; i < n; i++)
	{
		int r, c, a;
		cin >> r >> c >> a;
		r--;
		c--;
		grid[r][c] = a;
	}
	for (int r = 0; r < h; r++)
	{
		if (grid[r].empty()) continue;
		auto &col = grid[r];
		map<int, int> delta;
		for (auto it = col.begin(); it != col.end(); it++)
		{
			int c = it->first;
			if (!prv.count(c))
			{
				prv[c] = r;
				continue;
			}
			int r2 = prv[c];
			if (!delta.count(r2))
			{
				delta[r2] = grid[r][c] - grid[r2][c];
				ldelta[r] = max(ldelta[r], delta[r2]);
				ldelta[r2] = max(ldelta[r2], -delta[r2]);
			}
			else if (delta[r2] != grid[r][c] - grid[r2][c])
			{
				cout << "No\n";
				return 0;
			}
			prv[c] = r;
		}
	}
	for (int r = 0; r < h; r++)
	{
		if (grid[r].empty()) continue;
		auto &col = grid[r];
		for (auto it = col.begin(); it != col.end(); it++)
		{
			if (it->second < ldelta[r])
			{
				cout << "No\n";
				return 0;
			}
		}
	}
	cout << "Yes\n";
	return 0;
}

