typedef pair<int, int> P;
typedef pair<P, int> Q;
const int N = 100005;
const ll INF = (ll) 1e13;
vector<P> g[N];
ll lb[N], rb[N], sum_lb[N], sum_rb[N];

int main(int argc, char *argv[]) {
	ios_base::sync_with_stdio(false);

	int R, C, r, c, n, a;

	cin >> R >> C >> n;
	fill(lb + 1, lb + C + 1, -INF);
	fill(rb + 1, rb + C + 1, +INF);

	REPU(i, 0, n) {
		cin >> r >> c >> a;
		g[r].push_back(P(c, a));
		if (c > 1) amax(lb[c - 1], -a);
		if (c < C) amin(rb[c    ], +a);
	}

	bool bad(false);

	REPU(i, 1, R + 1) if (!g[i].empty()) {
		sort(ALL(g[i]));
		int m = g[i].size();
		REPU(j, 1, m) {
			auto from = g[i][j - 1], to = g[i][j];
			if (from.first + 1 == to.first) {
				int d = from.second - to.second;
				if (d >= lb[from.first] && d <= rb[from.first]) {
					lb[from.first] = rb[from.first] = d;
				}
				else bad = true;
			}
		}
	}

	sum_lb[0] = sum_rb[0] = 0;
	REPU(i, 1, C + 1) {
		sum_lb[i] = sum_lb[i - 1] + lb[i];
		sum_rb[i] = sum_rb[i - 1] + rb[i];
	}

	REPU(i, 1, R + 1) if (!g[i].empty()) {
		int m = g[i].size();
		REPU(j, 1, m) {
			auto from = g[i][j - 1], to = g[i][j];
			int d = from.second - to.second;
			ll d_lb = sum_lb[to.first - 1] - sum_lb[from.first - 1];
			ll d_rb = sum_rb[to.first - 1] - sum_rb[from.first - 1];
			if (d_lb > d || d > d_rb) bad = true;
		}
	}

	puts(bad ? "No" : "Yes");


	return 0;
}

