const int INF = 1e9 * 2;
const ll INFL = 1LL << 60;


class Solver {
  public:
    int R, C;
    int N; 
    vector<int> Y, X;
    vector<ll> A;
    map<pii, ll> G;

    bool check_diff() {
        map<int, map<int, int>> GG;        
        auto f = [&](vector<int> &X1, vector<int> &X2, int mx) {
            rep(i, N) GG[X1[i]][X2[i]] = A[i];
            rep(x, mx) {
                if(GG.count(x) && GG.count(x + 1)) {
                    ll d = -INFL;
                    for(auto &ya : GG[x]) {
                        if(GG[x + 1].count(ya.first)) {
                            ll d2 = abs(ya.second - GG[x + 1][ya.first]);
                            if(d >= 0 and d2 != d) return false;
                            if(d < 0) d = d2;
                        }
                    }
                }
            }
            return true;
        };
        return f(X, Y, C) and f(Y, X, R);
    }

    bool check2() {
        const int dy[] = {-1, -1, 0, 1, 1, 1, 0, -1};
        const int dx[] = {0, 1, 1, 1, 0, -1, -1, -1};
        auto check = [&](vector<int> g,int mx) {
            rep(b, 3) if(g[b] < 0 or mx <= g[b]) return false;
            return true;
        };
        bool flg = false;
        rep(i, N) {
            int yy = Y[i], xx = X[i];
            vector<int> ys, xs;
            rep(j, 8) {                    
                ys.push_back(yy + dy[j]);
                xs.push_back(xx + dx[j]);
                if(xs.size() == 3) {                    
                    if(check(xs, C) and check(ys, R)) {
                        vector<int> aa(3);
                        rep(k, 3) {                                
                            aa[k] = G.count(make_pair(ys[k], xs[k])) ? G[make_pair(ys[k], xs[k])] : -INF; 
                        }
                        int xa = aa[0] + aa[2];
                        int xb = A[i] + aa[1];
                        cerr << xa << " " << xb << endl;
                        if(xa >= 0 and xb >= 0) {
                            flg |= xa != xb;
                        }
                        if(xa >= 0 and xb < 0 and xb + INF >= 0) {
                            flg |= xa < xb + INF;
                        }
                        if(xa < 0 and xb >= 0 and xa + INF >= 0) {
                            flg |= xb < xa + INF;
                        }
                    }
                    xs.erase(xs.begin(), xs.begin() + 1);
                    ys.erase(ys.begin(), ys.begin() + 1);
                }
            }
        }
        return !flg;
    }

    bool solve() {
        cin >> R >> C;
        cin >> N;
        Y.resize(N);
        X.resize(N);
        A.resize(N);
        rep(i, N) {
            cin >> Y[i] >> X[i] >> A[i];
            Y[i]--; X[i]--;
            G[make_pair(Y[i], X[i])] = A[i];
        }
        bool flg = true;
        flg &= check_diff();
        flg &= check2();
        cout << ( !flg ? "No" : "Yes" ) << endl;
        return 0;
    }
};

