#include <bits/stdc++.h>
using namespace std;
#define int long long

void sayno(){
	cout << "No" << endl;
	exit(0);
}


map<int,int> xinc,yinc;

struct UnionFind {
	vector<int> uf;
	UnionFind(int n){
		uf.resize(n);
		for(int i = 0 ; i < n ; i++) uf[i] = i;
	}
	int root(int x){
		return uf[x] == x ? x : uf[x] = root(uf[x]);
	}
	int unite(int x,int y){
		uf[root(x)] = root(y);
	}
};
void solve(long long R, long long C, long long N, vector<long long> r, vector<long long> c, vector<long long> a){

	map< pair<int,int> , int> mass;
	for(int i = 0 ; i < r.size() ; i++){
		r[i]--;
		c[i]--;
		mass[{r[i],c[i]}] = a[i];
	}
	vector<int> curx(100010,-1), cury(100010,-1);
	UnionFind ux(100010);
	UnionFind uy(100010);
	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		pair<int,int> rig = {y,x+1};
		pair<int,int> dow = {y+1,x};

		if( mass.count(rig) ){
			int diff = mass[rig] - p.second;
			if( xinc.count(x) and xinc[x] != diff ) sayno();
			xinc[x] = diff;
			ux.unite(x,x+1);
		}

		if( mass.count(dow) ){
			int diff = mass[dow] - p.second;
			if( yinc.count(y) and yinc[y] != diff ) sayno();
			yinc[y] = diff;
			uy.unite(y,y+1);
		}
	}

	int val = 0;


	for(int i = 0 ; i < C ; i++){
		curx[i] = val;
		if( xinc.count(i) ){
			val += xinc[i];
		}else{
			val = 0;
		}
	}
	for(int i = 0 ; i < R ; i++){
		cury[i] = val;
		if( yinc.count(i) ){
			val += yinc[i];
		}else{
			val = 0;
		}
	}
	vector<int> vx(100010,0);
	vector<int> vy(100010,0);
	vector<bool> dx(100010,0);
	vector<bool> dy(100010,0);


	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		int geta = p.second - (curx[x] + cury[y] + vx[ux.root(x)] + vy[uy.root(y)]);

		if( !dx[ux.root(x)] or vx[ux.root(x)] == geta ){
			vx[ux.root(x)] = geta;
			vy[uy.root(y)] = 0;
			dx[ux.root(x)] = true;
		}else if( !dy[uy.root(y)] or vy[uy.root(y)] == geta ){
			vy[uy.root(y)] = geta;
			dy[uy.root(y)] = true;
		}
	}

	for(int i = 0 ; i < R ; i++){
		// miy = min(miy,vy[uy.root(i)] + cury[i]);
		// cout << i << " " << vy[uy.root(i)] + cury[i] << " " << cury[i] << endl; 
	}
	// cout << endl;
	for(int i = 0 ; i < C ; i++){
		// mix = min(mix,vx[ux.root(i)] + curx[i]);
		// cout << i << " " << vx[ux.root(i)] + curx[i] <<" " << curx[i] <<  endl; 
	}

	for(int i = 0 ; i < 100010 ; i++) {
		if( vx[i] == -114514 ) vx[i] = 0;
		if( vy[i] == -114514 ) vy[i] = 0;
	}



	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		int v = vy[uy.root(y)] + vx[ux.root(x)] + curx[x] + cury[y];
		// cout << x << " " << y << "p " << p.second << " = " << v << endl;
		if( v != p.second ){
			sayno();
		}
	}

	int miy = 1e9;
	int mix = 1e9;
	for(int i = 0 ; i < R ; i++){
		miy = min(miy,vy[uy.root(i)] + cury[i]);
		// cout << i << " " << vy[uy.root(i)] + cury[i] << endl; 
	}
	// cout << endl;
	for(int i = 0 ; i < C ; i++){
		mix = min(mix,vx[ux.root(i)] + curx[i]);
		// cout << i << " " << vx[ux.root(i)] + curx[i] << endl; 
	}

	if( miy >= 0 and mix >= 0 ){
		cout << "Yes" << endl;
	}else{
		int minus = -min(miy,mix);
		int plus = max(miy,mix);
		if( minus <= plus ){
			cout << "Yes" << endl;
		}else sayno();

	}




}



