template<int Size = 1000000, typename WeightType = int>
class WeightedUnionFind {
    int par[Size], rank[Size], sizes[Size];
    WeightType wei[Size];

public:
	WeightedUnionFind() = default;
	WeightedUnionFind(const WeightedUnionFind&) = default;
	WeightedUnionFind(WeightedUnionFind&&) = default;
	WeightedUnionFind& operator = (const WeightedUnionFind&) = default;
	WeightedUnionFind& operator = (WeightedUnionFind&&) = default;

    WeightedUnionFind(int size) {
		init(size);
	}

	void init(int size) {
        for(int i = 0; i < size; ++i) {
            par[i] = i;
            rank[i] = 0;
            sizes[i] = 1;
            wei[i] = 0;
        }
    }

    int find(int x) {
        if(par[x] == x) {
            return x;
        }else {
            int p = find(par[x]);

            wei[x] += wei[par[x]];

            return par[x] = p;
        }
    }

    WeightType weight(int x) {
        find(x);

        return wei[x];
    }

    void unite(int x, int y, WeightType w) {
        w += weight(x); 
        w -= weight(y);
        x = find(x);
        y = find(y);

        if(x == y) return;

        if(rank[x] < rank[y]) {
            par[x] = y;
            sizes[y] += sizes[x];
            wei[x] = w;
        }else {
            par[y] = x;
            sizes[x] += sizes[y];
            wei[y] = w;
            if(rank[x] == rank[y]) ++rank[x];
        }
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    int size(int x) {
        return sizes[find(x)];
    }

    WeightType diff(int x, int y, WeightType disabledVal = static_cast<WeightType>(-1)) {
        if(!same(x, y)) {
            return disabledVal;
        }

        return weight(x) - weight(y);
    }
};
