const int MAX_R = 1e5 + 10;
const int MAX_C = 1e5 + 10;
const int MAX_RC = MAX_R + MAX_C;
typedef vector<vector<pii>> Graph;

Graph graph(MAX_RC);
vector<bool> used(MAX_RC, false);
vi node(MAX_RC, 0);

void fill_dfs(int v) {
    if(used[v])
        return;

    used[v] = true;
    tr(it, graph[v]) {
        int next = it->first;
        node[next] = it->second - node[v];
        fill_dfs(next);
    }
}

bool check_dfs(int v) {
    if(used[v])
        return true;

    used[v] = true;
    bool ok = true;
    tr(it, graph[v]) {
        int next = it->first;
        ok &= (node[next] == it->second - node[v]);
        ok &= check_dfs(next);
    }
    return ok;
}

