        int r, c, a;
        cin >> r >> c >> a;
        --r, --c;
        graph[r + C].push_back(mp(c, a));
        graph[c].push_back(mp(r + C, a));
    }

    rep(i, R+C) {
        if(!used[i])
            fill_dfs(i);
    }

    fill(all(used), false);
    bool ok = true;
    rep(i, R+C) {
        if(!used[i])
            ok &= check_dfs(i);
    }

    int rm = INF, cm = INF;
    rep(i, R)
        chmin(rm, node[i]);
    REP(i, R, R+C)
        chmin(cm, node[i]);
