		c[y].push_back(make_pair(x, z));
	}
	for (long long i = 0; i < 100009; i++)
		col[i][0] = col[i][1] = INF;
	for (long long i = 0; i < R; i++) {
		if (!used[i][0]) {
			rr[i] = 0;
			dfs(i, 0);
			cnt++;
		}
	}
	for (long long i = 0; i < C; i++) {
		if (!used[i][1]) {
			cr[i] = 0;
			dfs(i, 1);
			cnt++;
		}
	}
	for (long long i = 0; i < R; i++) {
		for (long long j = 0; j < r[i].size(); j++) {
			if (r[i][j].second != rr[i] + cr[r[i][j].first]) {
				cout << "No" << endl;
				return 0;
			}
		}
	}
	for (long long i = 1; i < cnt; i++) {
		if (col[i][1] + col[i][0] < 0) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;
	return 0;
}

