bool bfs()
{

  for (int i = 1; i <= R + C; i++) {
    if (vis[i]) {
      continue;
    }
    int b = 0, e = 1;
    x[0] = i;
    vis[i] = true;
    A[i] = 0;
    while (b < e) {
      for (int j = 0; j < (int) G[x[b]].size(); j++) {
        int u = G[x[b]][j].v;
        int w = G[x[b]][j].w;
        if (vis[u]) {
          if (A[x[b]] + A[u] != w) {
            return false;
            }
          continue;
        }
        x[e] = u;
        A[u] = w - A[x[b]];
        vis[u] = true;
        e++;
      }
      b++;
    }
    }

        LL Minr = INF;
    LL Minc = INF;
    for(int i = 1;i <= R;++i)
        Minr = min(Minr,A[i]);
    for(int i = R+1;i <= R+C;++i)
        if(vis[i])
        Minc = min(Minc,A[i]);

    if(Minr + Minc < 0) return false;


    return true;


}


