vector<P> gr[100000];
vector<P> gc[100000];

LL valr[100000], valc[100000];
char chkr[100000], chkc[100000];

PLL dfs(int x) {
    LL min_r = valr[x], min_c = INF;
    for (const PLL& p: gr[x]) {
        LL v = p.first;
        LL a = p.second;

        if (chkc[v]) {
            if (valr[x] + valc[v] != a) {
                return PLL(-1, -1);
            }
            continue;
        }

        chkc[v] = true;
        valc[v] = a - valr[x];

        min_c = min(min_c, valc[v]);

        for (const PLL& q : gc[v]) {
            LL w = q.first;
            LL b = q.second;

            if (chkr[w]) {
                if (valc[v] + valr[w] != b) {
                    return PLL(-1, -1);
                }
                continue;
            }
            chkr[w] = true;
            valr[w] = b - valc[v];

            PLL tret = dfs(w);

            min_r = min(min_r, tret.first);
            min_c = min(min_c, tret.second);
        }
    }
    return PLL(min_r, min_c);
}

