        tie(v, a) = e;

        // value + ? = a
        if(!visited[v]){dfs(v, 1ll * a - value, graph, visited);}
    }
}

template <int n>
P dfs2(int u, vector<P> (&graph)[n], bool (&visited)[n]){
    visited[u] = true;

    P result = std::make_tuple(INF, INF);
    if(u < R){fst(result) = min(fst(result), values[u]);}
    else{snd(result) = min(snd(result), values[u]);}

    for(const P& e : graph[u]){
        int v = fst(e);
        if(!visited[v]){
            P nextResult = dfs2(v, graph, visited);
            fst(result) = min(fst(result), fst(nextResult));
            snd(result) = min(snd(result), snd(nextResult));      
        }
    }

    return result;
}

void sayNo(){
    puts("No");
    exit(0);
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> R >> C >> N;

    for(int i=0;i<N;++i){
        int r, c, a;
        std::cin >> r >> c >> a;

        --r; --c;

        graph[r].emplace_back(R+c, a);
        graph[R+c].emplace_back(r, a);
        edges.emplace_back(r, R+c, a);
    }

    int M = R + C;
    for(int i=0;i<M;++i){
        if(!visited[i]){
            dfs(i, 0, graph, visited);
        }
    }

    for(const T& e : edges){
        int u, v, a;
        tie(u, v, a) = e;

        if(values[u] + values[v] != a){
            sayNo();
        }
    }

    memset(visited, 0, sizeof(visited));

    for(int i=0;i<M;++i){
        if(!visited[i]){
            P minPair = dfs2(i, graph, visited);
            ll a, b;
            tie(a, b) = minPair;

            if(a + b < 0){sayNo();}
        }
    }

    puts("Yes");
}

