    vis[i] = true;
    A[i] = 0;
    while (b < e) {
      for (int j = 0; j < (int) G[x[b]].size(); j++) {
        int u = G[x[b]][j].v;
        int w = G[x[b]][j].w;
        if (vis[u]) {
          if (A[x[b]] + A[u] != w) {
            return false;
            }
          continue;
        }
        x[e] = u;
        A[u] = w - A[x[b]];
        vis[u] = true;
        e++;
      }
      b++;
    }


long long m1 = INF, m2 = INF;
    for (int j = 0; j < e; j++) {
