                                        break;
                                    }else{
                                        mp[P(py + l, px + q)] = nn;
                                        st.insert(P(py + l, px + q));
                                    }
                                }
                            }
                        }
                    }
                    rep(l, 0, 2){
                        int tp1 = ex[0][l];
                        int tp2 = ex[1][(l + 1) % 2];
                        if(tp1 == -1 || tp2 == -1) continue;
                        sdmp[P(py, px)] = tp1 + tp2;
                        sdst.insert(P(py, px));
                    }
                }
            }
        }
    }
    cout << (f ? "Yes" : "No") << endl;
}

