	P *res = lower_bound(arr, arr + N, tmp);
	return res - arr;
}

int upperb(P *arr, int v) {
	P tmp = MP(MP(v, 1000000), 0);
	P *res = upper_bound(arr, arr + N, tmp);
	return res - arr;
}

bool solve(P *arr, int rc, int *rcl, int *rch) {
	bool res = true;
	REP(r, rc - 1) {
		int r2 = r + 1;
		int lb = lowerb(arr, r), ub = upperb(arr, r);
		int lb2 = lowerb(arr, r2), ub2 = upperb(arr, r2);
		int l = -1000000000, h = 1000000000;
		int i = lb, i2 = lb2;
		while (res && (i < ub || i2 < ub2)) {
			int c = arr[i].first.second, c2 = arr[i2].first.second;
			int a = arr[i].second, a2 = arr[i2].second;

			if (i < ub && i2 < ub2 && c == c2) {
				int d = a2 - a;
				if (d < l || d > h) res = false;
				else l = h = d;
				++i; ++i2;
			}
			else if (i < ub && (i2 >= ub2 || c < c2)) {
				l = max(l, -a);
				h = min(h, 1000000000 - a);
				if (l > h) res = false;
				++i;
			}
			else {
				l = max(l, a - 1000000000);
				h = min(h, a);
				++i2;
			}
		}
		rcl[r] = l;
		rch[r] = h;
	}
	return res;
}

int pa[100000], sz[100000], val[100000], nb[100000], nc[100000], nv[100000];

int root(int i) {
	while (pa[i] != -1) i = pa[i];
	return i;
}

int merge(int i, int j) {
	int ri = root(i), rj = root(j);
	if (ri == rj) return ri;
	if (sz[ri] < sz[rj]) {
		pa[ri] = rj;
		sz[rj] += sz[ri];
		return rj;
	}
	else {
		pa[rj] = ri;
		sz[ri] += sz[rj];
		return ri;
	}
}

bool solve2(P *cr, P *rc, int cs, int rs) {
	memset(pa, -1, sizeof(pa));
	memset(val, -1, sizeof(val));
	memset(nb, -1, sizeof(nb));
	REP(i, cs) sz[i] = 1;
	REP(c, cs) {
		int lb = lowerb(cr, c), ub = upperb(cr, c);
		FOR(i, lb, ub - 1) {
			int r = cr[i].first.second, r2 = cr[i + 1].first.second;
			int a = cr[i].second, a2 = cr[i + 1].second;
			merge(r, r2);
			nb[r] = r2; nb[r2] = r;
			nc[r] = nc[r2] = c;
			nv[r] = a; nv[r2] = a2;
		}
	}
	bool res = true;
	REP(r, rs) {
		if (nb[r] == -1) continue;
		int r2 = nb[r], c0 = nc[r];
		int v = nv[r], v2 = nv[r2];
		int lb = lowerb(rc, r), ub = upperb(rc, r);
		int lb2 = lowerb(rc, r2), ub2 = upperb(rc, r2);
		int i = lb, i2 = lb2;
		while (res && (i < ub || i2 < ub)) {
			int c = rc[i].first.second, c2 = rc[i2].first.second;
			int a = rc[i].second, a2 = rc[i2].second;

			if (i < ub && i2 < ub2 && c == c2) {
				if (a - v != a2 - v2) res = false;
				++i; ++i2;
			}
			else if (i < ub && (i2 >= ub2 || c < c2)) {
				if (v2 + (a - v) < 0) res = false;
				++i;
			}
			else {
				if (v + (a2 - v2) < 0) res = false;
				++i2;
			}
		}
	}
	return res;
}

