struct uf{
	vi p;
	vector<ll> h;
	vector<vi> s;
	uf(int n){
		p.resize(n);
		h.resize(n);
		s.resize(n);
		rep(i, n){
			p[i] = i;
			s[i].pb(i);
		}
	}
	int root(int x){
		if(x < 0 || x >= p.size()) exit(0); //?????
		return x == p[x] ? x : (p[x] = root(p[x]));
	}
	bool merge(int a, int b, ll b_minus_a){
		int A = a, B = b;
		a = root(a); b = root(b);
		if(a == b){
			return h[B] - h[A] == b_minus_a;
		}
		if(s[a].size() < s[b].size()){
			swap(a, b);
			b_minus_a *= -1;
		}
		p[b] = a;

		ll d = h[A] - h[B] + b_minus_a;
		for(int i : s[b]){
			s[a].pb(i);
			h[i] += d;
		}
		s[b].erase(all(s[b]));
		return 1;
	}
};
