  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  cin >> R >> C >> n;
  for (int i = 0; i < n; i++) {
    int x, y, value;
    cin >> x >> y >> value;
    values[Cell{x, y}] = value;
  }

  if (R >= 3 || C >= 3) {
    cout << "No" << endl;
