	P b = make_pair(p.first + 1, p.second + 0);
	if ( mp.find(l) != mp.end() ) { // 左の点が存在する場合
	    int l_n = (mp.find(l))->second;
	    if ( dc[p.second] != INF ) {
		if (dc[p.second] != (it->second - l_n)) {
		    enable = false;
		    break;
		}
	    }
	    else {
		dc[p.second] = (it->second - l_n);
	    }
	}
