#include <bits/stdc++.h>
using namespace std;

const int N = (int) 2e5;
vector<pair<int, int> > graph[N];
long long sgn[N], delta[N], lab[N];
long long vmin[N], vmax[N];
bool visited[N];

int get(int u) {
    return lab[u] < 0 ? u : lab[u] = get(lab[u]);
}

void join(int u, int v) {
    u = get(u); v = get(v);
    if (u == v) return;
    if (lab[u] < lab[v]) swap(u, v);
    lab[v] += lab[u];
    lab[u] = v;
}

void impossible() {
    cout << "No" << endl;
    exit(0);
}

void dfs(int u) {
    visited[u] = true;
    if (sgn[u] < 0) vmax[get(u)] = min(vmax[get(u)], delta[u]);
    else vmin[get(u)] = max(vmin[get(u)], -delta[u]);
    for (auto e : graph[u]) {
        int v = e.first, w = e.second;
        if (!visited[v]) {
            sgn[v] = -sgn[u];
            delta[v] = w - delta[u];
            dfs(v);
        } else {
            int ssgn = sgn[u] + sgn[v];
            long long sdelta = delta[u] + delta[v]; // ssgn * x + sdelta == w
            if (ssgn == 0) {
                if (sdelta != w) impossible();
            } else {
                if ((w - sdelta) % ssgn == 0) {
                    long long x = (w - sdelta) / ssgn;
                    vmin[get(u)] = max(vmin[get(u)], x);
                    vmax[get(u)] = min(vmax[get(u)], x);
                } else {
                    impossible();
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    int r, c; cin >> r >> c;
    int n; cin >> n;
    memset(lab, -1, sizeof lab);
    for (int i = 0; i < n; ++i) {
        int u, v, w; cin >> u >> v >> w; --u; --v;
        graph[u].push_back(make_pair(r + v, w));
        graph[r + v].push_back(make_pair(u, w));
        join(u, r + v);
    }
    for (int i = 0; i < r + c; ++i) if (get(i) == i) {
        vmin[i] = 0; vmax[i] = 1e18; sgn[i] = 1;
        dfs(i);
        if (vmin[i] > vmax[i]) impossible();
    }
    cout << "Yes" << endl;
    return 0;
}

