using namespace std;
typedef pair<int,int> P;
map<P,int> m;
int r,c,n;
int di[4] = {-1,-1,0,0};
int dj[4] = {-1,0,-1,0};
bool neighbor(const P p);

int get_value(int i, int j){
	P p(i,j);
	map<P,int>::iterator it = m.find(p);
	if(it == m.end())
		return -1;
	else
		return it->second;
}

bool within(int i, int j){
	return i >= 0 && i < r-1 && j >= 0 && j < c-1;
}

bool check(int i,int j){
// 	cout << "check" << i << j << endl;
	int a[4] = {get_value(i,j),get_value(i,j+1),get_value(i+1,j),get_value(i+1,j+1)};
	int unresolved = 0;
	int ti,tj;
	int si,sj;
	int sum =0;
	for(int ki = 0; ki <= 1;ki++){
		for(int kj = 0; kj <= 1;kj++){
			int v = get_value(i+ki,j+kj);
			if(v < 0){
				unresolved++;
				ti = i+ki;
				tj = j+kj;
				si = i+(ki+1)%2;
				sj = j+(kj+1)%2;
			}else
				sum += v;
		}
	}
// 	cout << "unresolved:" << unresolved << endl;
	if(unresolved>=2)
		return true;
	if(unresolved>=1){
		int new_value = sum - 2*get_value(si,sj);
// 		cout << new_value << endl;
		if(new_value < 0)
			return false;
		P p(ti,tj);
		m[p] = new_value;
		return neighbor(p);
	}
	return a[0]+a[3] == a[1] + a[2];
}

bool neighbor(const P p){
	int i = p.first;
	int j = p.second;
// 	cout << "neighbor:" << i << j << endl;
	for(int k = 0; k < 4;k++){
		if(within(i+di[k],j+dj[k]))
			if(!check(i+di[k],j+dj[k]))
				return false;
	}
	return true;
}

bool enumerate(){
	for(auto p:m){
		if(!neighbor(p.first))
			return false;
	}
	return true;
}


