    g[h].emplace_back((edge) {w + H, c});
    g[w + H].emplace_back((edge) {h, c});
  }
  fill_n(v, H + W, INF);

  for(int i = 0; i < H + W; i++) {
    if(v[i] != INF) continue;
    queue< int > que;
    v[i] = 0;
    que.emplace(i);
    int64 latte = INF, malta = INF;
    while(!que.empty()) {
      int p = que.front();
      que.pop();
      if(p < H) latte = min(latte, v[p]);
      else malta = min(malta, v[p]);
      for(auto &e : g[p]) {
        auto vv = e.cost - v[p];
        if(v[e.to] == INF) {
          v[e.to] = vv;
          que.emplace(e.to);
        } else if(v[e.to] != vv) {
          cout << "No" << endl;
          return (0);
        }
      }
    }
    if(latte + malta < 0) {
      cout << "No" << endl;
      return (0);
    }
  }

  cout << "Yes" << endl;
}

