int cr[100000];
int col[100000][2];
int cnt = 1;

void dfs(int node, int up) {
	used[node][up] = true;
	if (up == 0) {
		col[cnt][up] = min(col[cnt][up], rr[node]);
		for (int i = 0; i < r[node].size(); i++) {
			if (used[r[node][i].first][1 - up])
				continue;
			cr[r[node][i].first] = r[node][i].second - rr[node];
			dfs(r[node][i].first, 1 - up);
		}
	}
	else {
		col[cnt][up] = min(col[cnt][up], cr[node]);
		for (int i = 0; i < c[node].size(); i++) {
			if (used[c[node][i].first][1 - up])
				continue;
			rr[c[node][i].first] = c[node][i].second - cr[node];
			dfs(c[node][i].first, 1 - up);
		}
	}
}
int main() {
	scanf("%d %d", &R, &C);
	scanf("%d", &n);
	for (int i = 0; i < R; i++)
		r[i].clear();
	for (int i = 0; i < C; i++)
		c[i].clear();
	for (int i = 0; i < n; i++) {
		int x, y, z;
		scanf("%d %d %d", &x, &y, &z);
		x--;
		y--;
		r[x].push_back(make_pair(y, z));
		c[y].push_back(make_pair(x, z));
	}
	for (int i = 0; i < 100000; i++)
		col[i][0] = col[i][1] = INF;
	for (int i = 0; i < R; i++) {
		if (!used[i][0]) {
			rr[i] = 0;
			dfs(i, 0);
			cnt++;
		}
	}
	for (int i = 0; i < C; i++) {
		if (!used[i][1]) {
			cr[i] = 0;
			dfs(i, 1);
			cnt++;
		}
	}
	for (int i = 0; i < R; i++) {
		for (int j = 0; j < r[i].size(); j++) {
			if (r[i][j].second != rr[i] + cr[r[i][j].first]) {
				cout << "No" << endl;
				return 0;
			}
		}
	}
	for (int i = 1; i < cnt; i++) {
		if (col[i][1] + col[i][0] < 0) {
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;
	return 0;
}

