bool check(vector< vector<int> > &m){
    for(int i = 1; i < m.size() - 1; i++){
        for(int j = 1; j < m[i].size() - 1; j++){
            int flag = 0;
            if(m[i][j] == -1){
                flag = flag | 8;
            }
            if(m[i + 1][j] == -1){
                flag = flag | 4;
            }
            if(m[i][j + 1] == -1){
                flag = flag | 2;
            }
            if(m[i + 1][j + 1] == -1){
                flag = flag | 1;
            }

            if(flag == 0){
                if(m[i][j] + m[i + 1][j + 1] != m[i + 1][j] + m[i][j + 1]) return false;
            }else if(flag == 1){
                m[i+1][j+1] = m[i+1][j] + m[i][j+1] - m[i][j];
                if(m[i+1][j+1] < 0) return false;
            }else if(flag == 2){
                m[i][j+1] = m[i][j] + m[i+1][j+1] - m[i+1][j];
                if(m[i][j+1] < 0) return false;
            }else if(flag == 4){
                m[i+1][j] = m[i][j] + m[i+1][j+1] - m[i][j+1];
                if(m[i+1][j] < 0) return false;
            }else if(flag == 8){
                m[i][j] = m[i+1][j] + m[i][j+1] - m[i+1][j+1];
                if(m[i][j] < 0) return false;
            }
        }
    }
    return true;
}

