bool less_second(pair<int,int> l,pair<int,int> r){
	return l.second < r.second;
}

bool judgeRC(vector<vector<pair<int,int> > > Row){
	bool isclear = true;
	bool isRset = false;
	int sR = 0;
	REP(i,Row.size()){
		sort(Row[i].begin(),Row[i].end(), less_second);
		if(Row[i].size() >= 2){
			if(!isRset){
				sR = (Row[i][1].first - Row[i][0].first)/(Row[i][1].second - Row[i][0].second);
				isRset = true;
			}
			REP(ri,Row[i].size()){
				if(!ri)continue;
				if(sR != (Row[i][ri].first - Row[i][ri-1].first)/(Row[i][ri].second - Row[i][ri-1].second)){
					isclear = false;
					break;
				}
			}
		}
		if(Row[i].size() >=1 )
			if(sR*(R-1) + Row[i][0].first < 0)
				isclear = false;
		if(!isclear)break;
	}
	return isclear;
}


