void visit_row(int p, i64 d)
{
//	printf("ro %d\n", p);
	if (rvis[p]) {
		if (rval[p] != d) {
			puts("No");
			exit(0);
		}
		return;
	}
	rvis[p] = true;
	rval[p] = d;
	rmin = min(rmin, d);
	for (auto e : row[p]) {
		visit_row(e.first, d + e.second);
	}
}
void visit_col(int p, i64 d)
{
//	printf("co %d\n", p);
	if (cvis[p]) {
		if (cval[p] != d) {
			puts("No");
			exit(0);
		}
		return;
	}
	cvis[p] = true;
	cval[p] = d;
	cmin = min(cmin, d);
	for (auto e : col[p]) {
		visit_col(e.first, d + e.second);
	}
}

