const long long INF = 1e18;
const long long MAX = 200000;
long long val[MAX];
vector<pair<long long, long long>> edges[MAX];
long long rmin, cmin;
long long R, C, N;

bool dfs(long long i, long long prev){
    for(auto p : edges[i]){
        long long j = p.first, a = p.second;
        if(j == prev) continue;
        if(val[j] == INF){
            val[j] = a - val[i];
            if(j<R){
                rmin = min(rmin, val[j]);
            }else{
                cmin = min(cmin, val[j]);
            }
            bool result = dfs(j, i);
            if(!result) return false;
        }else{
            if(val[i] + val[j] != a){
                return false;
            }
        }
    }
    return true;
}

