int read() {
  if (scanf("%d%d%d", &r, &c, &n) < 3) {
    return false;
  }
  for (int i = 0; i < n; i++) {
    scanf("%d%d%d", &x[i], &y[i], &a[i]);
    x[i]--;
    y[i]--;
  }
  return true;
}

bool dfs(int i) {
  minv = min(minv, v[x[i]]);
  minu = min(minu, u[y[i]]);
  used[i] = true;
  for (int ii = 0; ii < 4; ii++) {
    int j = g[i][ii];
    if (used[j]) {
      continue;
    }
    if (ii & 1) {
      int vv = v[x[i]] + a[j] - a[i];
      if (usedr[x[j]] && v[x[j]] != vv) {
        return false;
      }
      v[x[j]] = vv;
      usedr[x[j]] = true;
      if (!dfs(j)) {
        return false;
      }
    } else {
      int uu = u[y[i]] + a[j] - a[i];
      if (usedc[y[j]] && u[y[j]] != uu) {
        return false;
      }
      u[y[j]] = uu;
      usedc[y[j]] = true;
      if (!dfs(j)) {
        return false;
      }
    }
  }
  return true;
}

void solve() {
  for (int i = 0; i < r; i++) {
    rows[i].clear();
    usedr[i] = false;
  }
  for (int i = 0; i < c; i++) {
    cols[i].clear();
    usedc[i] = false;
  }
  for (int i = 0; i < n; i++) {
    rows[x[i]].push_back(make_pair(y[i], i));
    cols[y[i]].push_back(make_pair(x[i], i));
    for (int j = 0; j < 4; j++) {
      g[i][j] = -1;
    }
  }
  for (int i = 0; i < r; i++) {
    sort(rows[i].begin(), rows[i].end());
    for (int j = 0; j + 1 < sz(rows[i]); j++) {
      g[rows[i][j].second][0] = rows[i][j + 1].second;
      g[rows[i][j + 1].second][2] = rows[i][j].second;
    }
  }
  for (int i = 0; i < c; i++) {
    sort(cols[i].begin(), cols[i].end());
    for (int j = 0; j + 1 < sz(cols[i]); j++) {
      g[cols[i][j].second][1] = cols[i][j + 1].second;
      g[cols[i][j + 1].second][3] = cols[i][j].second;
    }
  }
  for (int i = 0; i < n; i++) {
    used[i] = false;
  }
  for (int i = 0; i < n; i++) {
