const long long N = 1e5+7;
vector<pair<long long, long long>> cols[N], rows[N];
vector<pair<long long, long long>> adj[N];
long long rowbound[N], colbound[N];

bool bad;
bool vis[N];
long long id[N];
long long value[N], root[N];
long long dfs(long long u, long long val, long long s) {
    assert(!vis[u]);
    vis[u] = 1;
    value[u] = val;
    id[u] = s;

    long long ans = value[u];

    for (auto pr: adj[u]) {
        long long v = pr.first;
        long long d = pr.second;

        if (!vis[v])    ans = min(ans, dfs(v, val+d, s));
        if (value[v] != val+d)  bad = true;
    }
    return ans;
}

bool okay(vector<pair<long long, long long>> *rows, long long R, long long C, long long *bound) {
    for (long long i=1; i<=C; i++) adj[i].clear(), vis[i] = 0;

    for (long long i=1; i<=R; i++) {
        sort(rows[i].begin(), rows[i].end());
        for (long long j=1; j<rows[i].size(); j++) {
            long long x = rows[i][j-1].first, y = rows[i][j].first;
            long long d = rows[i][j].second - rows[i][j-1].second;
            adj[x].push_back({y, d});
            adj[y].push_back({x, -d});
//
//            cout<<x << " to " << y<<" "<<d<<endl;
//            cout<<y << " to " << x<<" "<<-d<<endl;
        }
    }
    bad = false;
    for (long long i=1; i<=C; i++) {
        if (vis[i])    continue;
        long long mn = dfs(i, 0, i);
        root[i] = mn;
//        cout<<"Comp at "<<i<<" "<<mn<<endl;
    }

    for (long long i=1; i<=C; i++) {
        long long lo = value[i] - root[id[i]];
        bound[i] = lo;
//        cout<<"Bound "<<i<<" "<<value[i]<<" "<<id[i]<<" "<<bound[i]<<endl;
        assert(bound[i] >= 0);
    }
    return !bad;
}

