#include <map>
#include <vector>
using namespace std;
typedef pair<int,int> P;
map<P,int> M;
vector<P> V;
int R,C,N;

void rec(int r,int c){
    if(r==0||c==0) return;
    int i0,i1,i2;
    if(M.find(P(r-1,c-1))!=M.end()){
        i0=M[P(r-1,c-1)];
    }else{
        i0=0;
    }
    if(M.find(P(r,c-1))!=M.end()){
        i1=M[P(r,c-1)];
    }else{
        i1=0;
    }
    if(M.find(P(r-1,c))!=M.end()){
        i2=M[P(r-1,c)];
    }else{
        i2=0;
    }
    if(M.find(P(r,c))==M.end()){
        if(!i0) return;
        if(i1&&i2){
            M[P(r,c)]=i1+i2-i0;
            if(i1+i2-i0<=0){
                cout<<"No"<<endl;
                exit(0);
            }
            if(c<C-1) rec(r,c+1);
            return;
        }
        return;
    }

    if(!i0){
        if(i1&&i2){
            M[P(r-1,c-1)]=i1+i2-M[P(r,c)];
            if(M[P(r-1,c-1)]<=0){
                cout<<"No"<<endl;
                exit(0);                
            }
            rec(r-1,c-1);
            return;
        }
    }else{
        int sum=M[P(r,c)]+i0;    
        if(i1&&i2){
            if(i1+i2!=sum){
                cout<<"No"<<endl;
                exit(0);
            }
            return;
        }
        if(i1){
            M[P(r-1,c)]=sum-i1;
            if(M[P(r-1,c)]<=0){
                cout<<"No"<<endl;
                exit(0);                
            }
            rec(r-1,c);
            if(c<C-1) rec(r-1,c+1);
            return;
        }
        if(i2){
            M[P(r,c-1)]=sum-i2;
            if(M[P(r,c-1)]<=0){
                cout<<"No"<<endl;
                exit(0);                
            }
            rec(r,c-1);
            if(r<R-1) rec(r+1,c-1);
            return;
        }
    }
}

int main(){
    cin>>R>>C>>N;
    for(int i=0;i<N;i++){
        int r,c,a;
        cin>>r>>c>>a;
        r--;c--;a++;
        M[P(r,c)]=a;
        if(V.empty()||V.back()!=P(r,c)) V.emplace_back(r,c);
        if(c<C-1) V.emplace_back(r,c+1);
    }
    sort(V.begin(),V.end());
    for(auto v:V){
        rec(v.first,v.second);
    }
    cout<<"Yes"<<endl;
    return 0;
}

