long long val[maxn];

vector<vector<int> > es, cs;
int used[maxn];


long long minadd;
long long minzero;

int dfs(int v) {
  used[v] = 1;
  minadd = min(minadd, val[v]);
  minzero = min(minzero, mn[v] - val[v]);

  for (int it = 0; it < sz(es[v]); ++it) {
    int u = es[v][it];
    long long nval = val[v] + cs[v][it];
    if (used[u]) {
      if (val[u] != nval) {
        return 1;
      }
      continue;
    }
    val[u] = nval;
    if (dfs(u)) {
      return 1;
    }
  }
  return 0;
}

void solve() {
  es = cs = vector<vector<int> >(m);
  for (int i = 0; i < n; ++i) {
    for (int j = 1; j < sz(qs[i]); ++j) {
      int s = qs[i][0].first, t = qs[i][j].first;
      int diff = qs[i][j].second - qs[i][0].second;
      es[s].pb(t), cs[s].pb(diff);
      es[t].pb(s), cs[t].pb(-diff);
    }
  }
  for (int i = 0; i < m; ++i) {
    used[i] = 0;
  }

  for (int i = 0; i < m; ++i) {
    if (used[i]) {
      continue;
    }
    minzero = minadd = 1e18;
    val[i] = 0;
    if (dfs(i) || (minzero + minadd < 0)) {
      printf("No\n");
      return;
    }
  }
  printf("Yes\n");
}

