			int y; int x; int a;
			scanf("%d%d%d", &y, &x, &a), -- y, -- x;
			edges.emplace_back(y, Graph::To(H + x, a));
			edges.emplace_back(H + x, Graph::To(y, -a));
		}
		rep(y, H)
			edges.emplace_back(H + W, Graph::To(y, 0));
