		g[x].push_back(mp(n + y, w));
		g[n + y].push_back(mp(x, w));
	}
	for (int v = 0; v < n; v++) {
		if (used[v]) continue;
		L = -INF; R = INF;
		if (!dfs(v) || L > R) {
			printf("No\n");
			return 0;
		}
	}
	printf("Yes\n");

	return 0;
}

