class Graph{
	private:
	int V;
	vvp List;
	vi a;
	vb used;
	void dfs(int c,int v){
		a[v]=c;
		used[v]=1;
		for(int i=0;i<List[v].size();i++){
			P u=List[v][i];
			if(!used[u.first]) dfs(u.second-c,u.first);
		}
	}
	public:
	Graph(int v){
		V=v;
		List=vvp(v);
	}
	void add_edge(int s,int t,int c){
		List[s].push_back(P(t,c));
		List[t].push_back(P(s,c));
	}
	string solve(int h){
		a=vi(V);
		used=vb(V);
		for(int i=0;i<V;i++) if(!used[i]) dfs(0,i);
		for(int i=0;i<V;i++) for(int j=0;j<List[i].size();j++){
			P e=List[i][j];
			if(a[i]+a[e.first]!=e.second) return "No";
		}
		int m,n;
		for(int i=0;i<h;i++) m=min(m,a[i]);
		for(int i=h;i<V;i++) n=min(n,a[i]);
		if(m+n<0) return "No";
		return "Yes";
	}
};

