using namespace std;

struct Edge {
	int to;
	int cost;
};


bool saiki(int now, int num, bool istate, vector<int> &tate, vector<int> &yoko,
	vector<bool> &tated, vector<bool> &yokod, vector<vector<Edge>> &tateedge, vector<vector<Edge>> &yokoedge, pair<int, int> &minpair) {
	if (istate) {
		if (tated[now]) {
			if (tate[now] != num) {
				return false;
			}
			return true;
		}
		tated[now] = true, tate[now] = num;
		minpair.first = min(minpair.first, num);
		for (auto &t : tateedge[now]) {
			if (!saiki(t.to, t.cost - num, false, tate, yoko, tated, yokod, tateedge, yokoedge, minpair))
				return false;
		}
		return true;
	}
	else {
		if (yokod[now]) {
			if (yoko[now] != num) {
				return false;
			}
			return true;
		}
		yokod[now] = true, yoko[now] = num;
		minpair.second = min(minpair.second, num);
		for (auto &t : yokoedge[now]) {
			if (!saiki(t.to, t.cost - num, true, tate, yoko, tated, yokod, tateedge, yokoedge, minpair))
				return false;
		}
		return true;

	}
}


signed main() {
	int R, C;
	cin >> R >> C;
	int N;
	cin >> N;
	vector<int> r(N), c(N), a(N);
	for (int i = 0; i < N; i++) {
		cin >> r[i] >> c[i] >> a[i];
		r[i]--, c[i]--;
	}
	vector<vector<Edge>> tateedge(R), yokoedge(C);
	vector<int> tate(R), yoko(C);
	vector<bool> tated(R, false), yokod(C, false);

	pair<int, int> minminp;

	for (int i = 0; i < N; i++) {
		tateedge[r[i]].push_back({ c[i], a[i] });
		yokoedge[c[i]].push_back({ r[i], a[i] });
	}
	bool res = true;
	for (int i = 0; i < R; i++) {
		pair<int, int> minp;
		if (tated[i] || tateedge[i].empty())
			continue;
		if (!saiki(i, 0, true, tate, yoko, tated, yokod, tateedge, yokoedge, minp)) {
			res = false;
			break;
		}
		if (minp.first + minp.second < 0) {
			res = false;
			break;
		}
	}
	cout << (res ? "Yes" : "No") << endl;

	return 0;
}

