void dfs(int v, const vector<vector<pair<int,int>>> &edges, map<int,ll> &val) {
  for (auto p: edges[v]) {
    int to = p.first, c = p.second;
    if (val.count(to)) {
      if (val[to] != val[v] + c) throw 0;
    }
    else {
      val[to] = val[v] + c;
      dfs(to, edges, val);
    }
  }
}

int main() {
  int R, C, N;
  cin >> R >> C >> N;
  vector<map<int,int>> row(R), col(C);
  vector<vector<pair<int,int>>> erow(C), ecol(R);
  REP(i,N) {
    int r, c, a;
    cin >> r >> c >> a;
    --r; --c;
    row[r][c] = a;
    col[c][r] = a;
  }
  REP(i,R) {
    if (row[i].empty()) continue;
    int from, to, a, b;
    tie(from, a) = *row[i].begin();
    for (auto p: row[i]) {
      tie(to, b) = p;
      erow[from].emplace_back(to, b - a);
      erow[to].emplace_back(from, b - a);
    }
  }
  REP(i,C) {
    if (col[i].empty()) continue;
    int from, to, a, b;
    tie(from, a) = *col[i].begin();
    for (auto p: col[i]) {
      tie(to, b) = p;
      ecol[from].emplace_back(to, b - a);
      ecol[to].emplace_back(from, b - a);
    }
  }
  col.clear();
  try {
    vector<ll> rval(C, -1), cval(R, -1); 
    REP(i,C) {
      if (rval[i] != -1) continue;
      map<int,ll> val;
      val[i] = 0;
      dfs(i, erow, val);
      ll mi = 1e18;
      for (auto p: val) chmin(mi, p.second);
      for (auto p: val) rval[p.first] = p.second - mi;
    }
    REP(i,R) {
      if (cval[i] != -1) continue;
      map<int,ll> val;
      val[i] = 0;
      dfs(i, ecol, val);
      ll mi = 1e18;
      for (auto p: val) chmin(mi, p.second);
      for (auto p: val) cval[p.first] = p.second - mi;
    }
    REP(i,R) {
      for (auto p: row[i]) {
        int j, v; tie(j, v) = p;
        if (v < cval[i] + rval[j]) throw 0;
      }
    }
    cout << "Yes" << endl;
  }
  catch(int) {
    cout << "No" << endl;
  }
  return 0;
}

