void init(int n){
  REP(i,MAX)seg[i+MAX-1]=0;
  REP(i,n)seg[i+MAX-1]=dist[i];
  FORR(i,0,MAX-1)seg[i]=min(seg[2*i+1],seg[2*i+2]);
  REP(i,2*MAX)sum[i]=0;
}

bool check(bool yoyoyo){
  int a = node.size();
  REP(i,a)vere[node[i]] = i;
  REP(i,a)dist[i] = 0;
  REP(i,a)used[i] = false;
  dist[0] = 0;
  used[0] = true;
  queue<int> Q;
  Q.push(0);
  while(!Q.empty()){
    int p = Q.front(); Q.pop();
    int id = node[p];
    ll d = dist[p];
    REP(i,g[id].size()){
      int to = vere[g[id][i].first];
      ll cost = g[id][i].second;
      ll nd = d+cost;
      if(used[to]){
        if(dist[to]!=nd)return false;
      }else{
        dist[to] = nd;
        used[to] = true;
        Q.push(to);
      }
    }
  }
  // negative check
  if(yoyoyo){
    init(a);
    REP(i,a){
      ll mn = query(0,a);
      if(mn + ys[node[i]][0] < 0){
        return false;
      }
      if(i==a-1)break;
      ll d = dist[i+1]-dist[i];
      add(0,i+1,d);
      add(i+1,a,-d);
    }
  }else{
    init(a);
    REP(i,a){
      ll mn = query(0,a);
      if(mn + xs[node[i]][0] < 0){
        return false;
      }
      if(i==a-1)break;
      ll d = dist[i+1]-dist[i];
      add(0,i+1,d);
      add(i+1,a,-d);
    }
  }
  return true;
}

