      if (!ok) break;
    }
    //cout << "dl" << endl;

    // down right
    if (is_inside(r8, c8)) {
      ok = calc_cell(r8, c8, r, c, r5, c5, r7, c7) &&
           calc_cell(r5, c5, r7, c7, r, c, r8, c8) &&
           calc_cell(r7, c7, r5, c5, r, c, r8, c8);
      if (!ok) break;
    }
    //cout << "dr" << endl;

    ok = check_cell(r, c, r4, c4, r + 2, c, r + 2, c - 1) &&
