#include <iostream>
#include <map>
#include <vector>
using namespace std;

int R, C, N;
vector< pair<int, int> > v;
map<int, int> field;
map<int, bool> filled;
bool flag;

const int dx[] = {1, 1, -1, -1};
const int dy[] = {1, -1, 1, -1};

bool isIllegal(int ri, int ci) {
    int ai = field[C * ri + ci];

    for (int j = 0; j < 4; j++) {
        int y = ri + dy[j];
        int x = ci + dx[j];
        if (x < 0 || C <= x || y < 0 || R <= y) continue;

        int cnt =
            1 + filled[C * ri + x] + filled[C * y + ci] + filled[C * y + x];
        if (cnt <= 2) continue;
        if (cnt == 4) {
            if (ai + field[C * y + x] !=
                field[C * ri + x] + field[C * y + ci]) {
                return true;
            }
        } else if (!filled[C * ri + x]) {
            int temp = ai + field[C * y + x] - field[C * y + ci];
            field[C * ri + x] = temp;
            filled[C * ri + x] = true;
            v.push_back(make_pair(ri, x));
            flag = false;
            if (temp < 0) return true;
        } else if (!filled[C * y + ci]) {
            int temp = ai + field[C * y + x] - field[C * ri + x];
            field[C * y + ci] = temp;
            filled[C * y + ci] = true;
            v.push_back(make_pair(y, ci));
            flag = false;
            if (temp < 0) return true;
        } else if (!filled[C * y + x]) {
            int temp = field[C * ri + x] + field[C * y + ci] - ai;
            field[C * y + x] = temp;
            filled[C * y + x] = true;
            v.push_back(make_pair(y, x));
            flag = false;
            if (temp < 0) return true;
        }
    }
    return false;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> R >> C >> N;
    for (int i = 0; i < N; i++) {
        int r, c, a;
        cin >> r >> c >> a;
        r--;
        c--;
        v.push_back(make_pair(r, c));
        field[C * r + c] = a;
        filled[C * r + c] = true;
    }

    while(1){
        flag = true;
        for (int i = 0; i < v.size(); i++) {
            if (isIllegal(v[i].first, v[i].second)) {
                cout << "No" << endl;
                return 0;
            }
        }
        if(flag) break;
    }

    cout << "Yes" << endl;

    return 0;
}

