		component[i] = i;
	}

	for (int i = 0; i < N; ++i) {
		cin >> r[i] >> c[i] >> a[i];
		--r[i]; --c[i];
		graph[r[i]].push_back(make_pair(R + c[i], a[i]));
		graph[R + c[i]].push_back(make_pair(r[i], a[i]));
		merge(r[i], R + c[i], component);
	}

	for (int i = 0; i < graph.size(); ++i) {
		if (val[i] == INT_MAX && graph[i].size() > 0) {
			val[i] = 0;
			dfs(graph, val, i);
		}
	}

	/*
