			if (val[r[i]] + val[R + c[i]] != a[i]) {
				cout << "No" << endl;
				return 0;
			}
		}
	}

	for (int i = 0; i < R + C; ++i) {
		if (val[i] != INT_MAX) {
			table[find(i, component)] = make_pair(INT_MAX, INT_MAX);
		}
		// cout << component[i] << " ";
	}
	// cout << endl;

	for (int i = 0; i < R; ++i) {
		if (val[i] != INT_MAX) {
			table[find(i, component)].first = min(table[find(i, component)].first, val[i]);
		}
	}
	for (int i = R; i < (R + C); ++i) {
