template<typename T> bool domax(T &a, T b) { return (b > a ? (a = b, true) : false); }
template<typename T> bool domin(T &a, T b) { return (b < a ? (a = b, true) : false); }
typedef long long ll;

const int maxn = 100*1000+5, maxc = maxn;

int Y, X, n, x[maxn], y[maxn], a[maxn], deltay[maxn], deltax[maxn];
std::vector<int> yy[maxc], xx[maxc];
bool seen[maxn], seeny[maxn], seenx[maxn];

int miny, minx;
void go(int i) {
    seen[i] = true;
    while (!yy[y[i]].empty()) {
        int j = yy[y[i]].back();
        yy[y[i]].pop_back();
        if (!seenx[x[j]]) {
            seenx[x[j]] = true;
            deltax[x[j]] = deltax[x[i]] + a[j] - a[i];
            domin(minx, deltax[x[j]]);
        } else if (deltax[x[j]] != deltax[x[i]] + a[j] - a[i]) {
            printf("No\n");
            exit(0);
        }
        if (!seen[j]) go(j);
    }
    while (!xx[x[i]].empty()) {
        int j = xx[x[i]].back();
        xx[x[i]].pop_back();
        if (!seeny[y[j]]) {
            seeny[y[j]] = true;
            deltay[y[j]] = deltay[y[i]] + a[j] - a[i];
            domin(miny, deltay[y[j]]);
        } else if (deltay[y[j]] != deltay[y[i]] + a[j] - a[i]) {
            printf("No\n");
            exit(0);
        }
        if (!seen[j]) go(j);
    }
}

