void dfsc(int c, long long a){
  used[c] = true;
  minc = min( minc, a );
  val[c] = a;
  for(int i = 0; i < G[c].size(); i++){
    int r, e;
    long long b;
    tie(r,b,e) = G[c][i];
    eg.push_back( e );
    if( !used[r] )
      dfsc( r, b - val[c] );
  }
}

void dfsr(int r, long long a){
  used[r] = true;
  minr = min( minr, a );
  val[r] = a;
  for(int i = 0; i < G[r].size(); i++){
    int c, e;
    long long b;
    tie(c,b,e) = G[r][i];
    eg.push_back( e );
    if( !used[c] )
      dfsc( c, b - val[r] );
  }
}

