  bool operator<(const Cell& other) const {
    if (x != other.x)
      return x < other.x;
    return y < other.y;
  }
};

struct Condition {
  Cell a, b;
  int sum;
};

int R, C, n;
map<Cell, int> values;
queue<Cell> q;
vector<Condition> conditions;
