    values[Cell{x, y}] = value;
  }

  if (R >= 100 && C >= 100) {
    cout << "No" << endl;
    return 0;
  }

  relax_zero();
  relax_single();
  relax_zero();
  prepare_conditions();
  satisfy_conditions();

  cout << "Yes" << endl;

  return 0;
}

