inline bool read()
{
	if (scanf ("%d%d%d", &n, &m, &k) != 3)
		return false;

	forn (i, k)
	{
		int x, y, val;
		assert(scanf ("%d%d%d", &x, &y, &val) == 3);

		x--, y--;

		xx[x].pb(mp(y, val));
		yy[y].pb(mp(x, val));
	}

	return true;
}

int xVal[N], yVal[N];

int head, tail;
pt q[2 * N];

inline void solve()
{
	forn (i, n)
		sort(all(xx[i]));
	forn (i, m)
		sort(all(yy[i]));

	int c = -1;
	if (!xx[0].empty() && xx[0][0].x == 0)
	{
		c = xx[0][0].y;
	}

	if (c == -1)
	{
		forn (i, n)
		{
			if (xx[i].empty())
				continue;
			if (xx[i][0].x != 0)
				continue;

			forn (j, sz(xx[i]))
			{
				int y = xx[i][j].x, val = xx[i][j].y;

				if (yy[y].empty())
					continue;
				if (yy[y][0].y != 0)
					continue;

				int curC = xx[i][0].y + val - xx[i][j].y;
				if ((c != -1 && c != curC) || curC < 0)
				{
					puts("No");
					return;
				}

				c = curC;
			}
		}
	}

	if (c == -1)
		c = 0;

	memset(xVal, -1, sizeof xVal);
	memset(yVal, -1, sizeof yVal);
	head = tail = 0;	

	xVal[0] = c;
	yVal[0] = c;

	forn (i, n)
		if (!xx[i].empty() && xx[i][0].x == 0)
		{
			xVal[i] = xx[i][0].y;
			q[tail++] = mp(0, i);
		}

	forn (i, m)
		if (!yy[i].empty() && yy[i][0].x == 0)
		{
			yVal[i] = yy[i][0].y;
			q[tail++] = mp(1, i);
		}

	while (head != tail)
	{
		int t = q[head].x, i = q[head].y;
		head++;

		if (t == 0)
		{
			forn (j, sz(xx[i]))
			{
				int y = xx[i][j].x, val = xx[i][j].y;

				if (y == 0)
					continue;

				int cur = val + c - xVal[i];
				if ((yVal[y] != -1 && yVal[y] != cur) || cur < 0)
				{
					puts("No");
					return;
				}

				if (yVal[y] == -1)
				{
					yVal[y] = cur;
					q[tail++] = mp(1, y);
				}
			}
		}
		else
		{
			forn (j, sz(yy[i]))
			{
				int x = yy[i][j].x, val = yy[i][j].y;

				if (x == 0)
					continue;

				int cur = val + c - yVal[i];
				if ((xVal[x] != -1 && xVal[x] != cur) || cur < 0)
				{
					puts("No");
					return;
				}

				if (xVal[x] == -1)
				{
					xVal[x] = cur;
					q[tail++] = mp(0, x);
				}
			}		
		}
	}

	int minValX = INF, minValY = INF;
	fore (i, 1, n - 1)
		if (xVal[i] != -1)
			minValX = min(minValX, xVal[i]);
	fore (i, 1, m - 1)
		if (yVal[i] != -1)
			minValY = min(minValY, yVal[i]);

	if (minValX != INF && minValY != INF)
	{
		if (minValX + minValY - c < 0)
		{
			puts("No");
			return;
		}
	}	

	puts("Yes");
}

