using namespace std;
using ll = int64_t;

struct Cell {
  int x, y;

  bool operator<(const Cell& other) const {
    if (x != other.x)
      return x < other.x;
    return y < other.y;
  }
};

struct Condition {
  Cell a, b;
  int sum;
};

int R, C, n;
map<Cell, int> values;
queue<Cell> q;
vector<Condition> conditions;
map<Cell, vector<Condition>> edges;
set<Cell> used;
set<Cell> temp_used;

void fail() {
  cout << "No" << endl;
  cout.flush();
  exit(0);
}

bool valid(Cell a) {
  return a.x >= 1 && a.y >= 1 && a.x <= R && a.y <= C;
}

void relax_zero(Cell a, Cell b, Cell c, Cell d) {
  array<Cell, 4> cells = {a, d, b, c};
  int already = 0;
  for (auto cell : cells) {
    if (!valid(cell))
      return;
    already += values.count(cell);
  }
  if (already == 4) {
    int i = 0;
    int sum = values[cells[(i ^ 2)]] + values[cells[(i ^ 2) ^ 1]];
    int current_sum = values[cells[i ^ 1 ]] + values[cells[i]];
    if (sum != current_sum)
      fail();
  }
}

void relax_zero() {
  for (auto p : values)
    q.push(p.first);
  while (!q.empty()) {
    auto p = q.front();
    q.pop();
    relax_zero(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x + 1, p.y + 1});
    relax_zero(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x + 1, p.y - 1});
    relax_zero(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x - 1, p.y + 1});
    relax_zero(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x - 1, p.y - 1}); 
  }
}

void relax_single(Cell a, Cell b, Cell c, Cell d) {
  array<Cell, 4> cells = {a, d, b, c};
  int already = 0;
  for (auto cell : cells) {
    if (!valid(cell))
      return;
    already += values.count(cell);
  }
  if (already == 3) {
    for (int i = 0; i < 4; i++) {
      if (!values.count(cells[i])) {
        int sum = values[cells[(i ^ 2)]] + values[cells[(i ^ 2) ^ 1]];
        int brother = values[cells[i ^1]];
        if (brother > sum) {
          fail();
        }
        values[cells[i]] = sum - brother;
      }
    }

    for (auto cell : cells)
      q.push(cell);
  }
}

void relax_single() {
  for (auto p : values)
    q.push(p.first);
  while (!q.empty()) {
    auto p = q.front();
    q.pop();
    relax_single(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x + 1, p.y + 1});
    relax_single(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x + 1, p.y - 1});
    relax_single(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x - 1, p.y + 1});
    relax_single(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x - 1, p.y - 1}); 
  }
}

void prepare_conditions(Cell a, Cell b, Cell c, Cell d) {
  array<Cell, 4> cells = {a, d, b, c};
  int already = 0;
  for (auto cell : cells) {
    if (!valid(cell))
      return;
    already += values.count(cell);
  }
  if (already == 2) {
    for (int i = 0; i < 4; i += 2) {
      if (values.count(cells[i]) && values.count(cells[i ^ 1])) {
        int sum = values[cells[i]] + values[cells[i ^ 1]];
        conditions.push_back(Condition{cells[(i ^ 2)], cells[(i ^ 2) ^ 1], sum});
      }
    }
  }
}

void prepare_conditions() {
  for (auto p : values)
    q.push(p.first);
  while (!q.empty()) {
    auto p = q.front();
    q.pop();
    prepare_conditions(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x + 1, p.y + 1});
    prepare_conditions(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x + 1, p.y - 1});
    prepare_conditions(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x - 1, p.y + 1});
    prepare_conditions(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x - 1, p.y - 1}); 
  }
  for (auto condition : conditions) {
    edges[condition.a].push_back(condition);
    swap(condition.a, condition.b);
    edges[condition.a].push_back(condition);
  }
}

void dfs_temp(Cell u, bool relax, int current_value, int& start_value) {
  temp_used.insert(u);
  for (auto condition : edges[u]) {
    int next_value = condition.sum - current_value;
    if (!relax)
      assert(next_value >= 0);
    if (relax && next_value <= 0) {
      start_value = max(start_value, -next_value);
    }
    if (!temp_used.count(condition.b)) {
      dfs_temp(condition.b, !relax, next_value, start_value);
    }
  }
}

void dfs(Cell u, bool relax, int current_value) {
  used.insert(u);
  for (auto condition : edges[u]) {
    int next_value = condition.sum - current_value;
    if (next_value < 0)
      fail();
    if (!used.count(condition.b)) {
      dfs(condition.b, !relax, next_value);
    }
  }
}



void satisfy_conditions() {
  for (auto condition : conditions) {
    if (!used.count(condition.a)) {
      int min_value = 0;
      dfs_temp(condition.a, false, 0, min_value);
      dfs(condition.a, false, min_value);
    }
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  cin >> R >> C >> n;
  for (int i = 0; i < n; i++) {
    int x, y, value;
    cin >> x >> y >> value;
    values[Cell{x, y}] = value;
  }

  srand(time(NULL));
  if (rand() & 1) assert(false);

  relax_zero();
  relax_single();
  relax_zero();
  prepare_conditions();
  satisfy_conditions();

  cout << "Yes" << endl;

  return 0;
}

