inline int check7(int cy, int cx) {
 if (cy > 1 && cx > 1 &&
  cx+1 <= c && cy + 1 <= r) {
  bool flag = d[cy-1].count(cx-1) &&
     d[cy-1].count(cx+1) &&
     d[cy+1].count(cx-1) &&
     d[cy+1].count(cx+1);

  if (!flag) return 0;

  ll t = (d[cy-1][cx-1] + d[cy-1][cx+1]) - (d[cy+1][cx-1] + d[cy+1][cx+1]);
  t = (t > 0 ? t : -t) / 2;
  if (t > d[cy-1][cx-1] + d[cy][cx] || t > d[cy][cx] + d[cy+1][cx-1] ||
   t > d[cy-1][cx+1] + d[cy][cx] || t > d[cy][cx] + d[cy+1][cx+1])
   return -1;
  return 1;
 }

 return 0; // NONE
}

inline int check0(int cy, int cx) {
 if (cy > 1 && cx+1 <= c) {
  bool flag = d[cy-1].count(cx) &&
     d[cy-1].count(cx+1) &&
     d[cy].count(cx+1);

  if (!flag) return 0;

  return ll(d[cy-1][cx+1]) + d[cy][cx] == ll(d[cy-1][cx])+ d[cy][cx+1] ?
   1 : -1;
 }

 return 0; // NONE
}

inline int check8(int cy, int cx) {
 if (cy > 2 && cx+1 <= c) {
  bool flag = d[cy-2].count(cx) &&
     d[cy-2].count(cx+1) &&
     d[cy].count(cx+1);

  if (!flag) return 0;

  return ll(d[cy-2][cx+1]) + d[cy][cx] == ll(d[cy-2][cx])+ d[cy][cx+1] ?
   1 : -1;
 }

 return 0; // NONE
}


inline int check9(int cy, int cx) {
 if (cy > 1 && cx+2 <= c) {
  bool flag = d[cy-1].count(cx) &&
     d[cy-1].count(cx+2) &&
     d[cy].count(cx+2);

  if (!flag) return 0;

  return ll(d[cy-1][cx+2]) + d[cy][cx] == ll(d[cy-1][cx])+ d[cy][cx+2] ?
   1 : -1;
 }

 return 0; // NONE
}

inline int check1(int cy, int cx) {
 if (cx > 1 && cy > 1) {
  return !d[cy-1].count(cx-1) &&
    d[cy-1].count(cx) &&
    d[cy].count(cx-1);
 } else return 0;

 return 0; // EMPTY
}

inline int check2(int cy, int cx) {
 if (cx > 1 && cy > 1) {
  return !d[cy].count(cx-1) &&
    d[cy-1].count(cx-1) &&
    d[cy-1].count(cx);
 } else return 0;

 return 0; // EMPTY
}

inline int check3(int cy, int cx) {
 if (cy > 1 && cx+1 <= c) {
  return d[cy-1].count(cx) &&
      d[cy].count(cx+1) &&
      !d[cy-1].count(cx+1);
 } else return 0;

 return 0; // EMPTY
}

inline int check4(int cy, int cx) {
 if (cy > 1 && cx+1 <= c) {
  return d[cy-1].count(cx) &&
      d[cy-1].count(cx+1) &&
      !d[cy].count(cx+1);
 } else return 0;

 return 0; // EMPTY
}

