    }

    for (auto kv : vert) {
        sort(kv.snd.begin(), kv.snd.end());
        for (int i = 0; i + 1 < kv.snd.size(); i++) {
            g[kv.snd[i].fst].pb(mp(kv.snd[i + 1].fst, kv.snd[i + 1].snd - kv.snd[i].snd));
            g[kv.snd[i + 1].fst].pb(mp(kv.snd[i].fst, - kv.snd[i + 1].snd + kv.snd[i].snd));
        }
    }

    for (int i = 0; i < maxn; i++) {
        if (!det[i]) {
            dfs(i, 0);
        }
    }

    for (int i = 0; i < maxn; i++) {
        if (!det[i]) {
            vis.clear();
            mm = 1e18;
            dfs(i, 0);

            for (int x : vis) {
                if (mm - (val[x] - minVert[x]) < 0) {
                    cout << "No" << endl;
                    return 0;
                }
            }
        }
    }

    cout << "Yes" << endl;

    return 0;
