int binpow(int x, int p) {
    int res = 1;
    while(p) {
        if(p % 2)
            res = (res * x) % mod;
        x = (x * x) % mod;
        p /= 2;
    }
    return res;
}

const int N = 1e6 + 7, NS = 2e3 + 7, lg = 20, sq = 550, inf = 1e18 + 7, SM = 1e2 + 7;
