vpi v[N];
int used[N], a[N];
int r, c, n;    
int left, right;        
void dfs(int x, int s) {
    used[x] = 1;
    a[x] = s;
    //cout << x << ' ' << s << endl;
    if(x < r) 
        amax(left, -s);
    else 
        amin(right, s);
    for (auto u : v[x]) {
        if(!used[u.x]) 
            dfs(u.x, u.y - s);
        else {
            if(a[u.x] != u.y - s) {
                cout << "No";
                exit(0);
            }
        }
    }
}
void solve() {
    cin >> r >> c >> n;
    for (int i = 0; i < n; i++) {
        int x, y, a;
        cin >> x >> y >> a;
        x--, y--;
        v[x].pb({r + y, a});
       // cout << x << ' ' << r + y << ' ' << a << endl;
        v[r + y].pb({x, a});
    }
    for (int i = 0; i < r; i++) {
        if(!used[i]) {
            left = -inf, right = inf;
            dfs(i, 0);
            if(left > right) {
                cout << "No";
                return;
            }
        }
    }
    cout << "Yes";
}   

