{
	int ans = INF;
	for (; r >= 0; r = (r & (r + 1)) - 1)
		ans = min(ans, t[r]);

	return ans;
}

inline void update (int i, int val)
{
	for (; i < n; i = (i | (i + 1)))
		t[i] = min(t[i], val);
}

inline void solve()
{
	forn (i, n)
		sort(all(xx[i]));
	forn (i, m)
		sort(all(yy[i]));

	int c = -1;
	if (!xx[0].empty() && xx[0][0].x == 0)
	{
		c = xx[0][0].y;
	}

	if (c == -1)
	{
		forn (i, n)
		{
			if (xx[i].empty())
				continue;
			if (xx[i][0].x != 0)
				continue;

			forn (j, sz(xx[i]))
			{
				int y = xx[i][j].x, val = xx[i][j].y;

				if (yy[y].empty())
					continue;
				if (yy[y][0].y != 0)
					continue;

				int curC = xx[i][0].y + val - xx[i][j].y;
				if ((c != -1 && c != curC) || curC < 0)
				{
					puts("No");
					return;
				}

				c = curC;
			}
		}
	}

	if (c == -1)
		c = 0;

	memset(xVal, -1, sizeof xVal);
	memset(yVal, -1, sizeof yVal);
	head = tail = 0;	

	xVal[0] = c;
	yVal[0] = c;

	/*forn (i, n)
		if (!xx[i].empty())
			e.insert(mp(0, i));
	forn (i, m)
		if (!yy[i].empty())
			e.insert(mp(1, i));*/

	forn (i, n)
		if (!xx[i].empty() && xx[i][0].x == 0)
		{
			//e.erase(mp(0, i));
			xVal[i] = xx[i][0].y;
			q[tail++] = mp(0, i);
		}

	forn (i, m)
		if (!yy[i].empty() && yy[i][0].x == 0)
		{
			//e.erase(mp(1, i));
			yVal[i] = yy[i][0].y;
			q[tail++] = mp(1, i);
		}

	//while (!e.empty())
	{
		/*int t = e.begin()->x, i = e.begin()->y;
		e.erase(e.begin());

		if (t == 0)
		{
			int cur = 0;

			forn (j, sz(xx[i]))
				cur = max(cur, xx[i][j].y);

			xVal[i] = cur + c;
			q[tail++] = mp(0, i);
		}
		else
		{
			int cur = 0;

			forn (j, sz(yy[i]))
				cur = max(cur, yy[i][j].y);		

			yVal[i] = cur + c;
			q[tail++] = mp(1, i);				
		}*/

    	while (head != tail)
    	{
    		int t = q[head].x, i = q[head].y;
    		head++;

    		if (t == 0)
    		{
    			forn (j, sz(xx[i]))
    			{
    				int y = xx[i][j].x, val = xx[i][j].y;

    				if (y == 0)
    					continue;

    				li cur = val + c - xVal[i];
    				if ((yVal[y] != -1 && yVal[y] != cur) || cur < 0)
    				{
    					puts("No");
    					return;
    				}

    				if (yVal[y] == -1)
    				{
    					//e.erase(mp(1, y));
    					yVal[y] = cur;
    					q[tail++] = mp(1, y);
    				}
    			}
    		}
    		else
    		{
    			forn (j, sz(yy[i]))
    			{
    				int x = yy[i][j].x, val = yy[i][j].y;

    				if (x == 0)
    					continue;

    				li cur = val + c - yVal[i];
    				if ((xVal[x] != -1 && xVal[x] != cur) || cur < 0)
    				{
    					puts("No");
    					return;
    				}

    				if (xVal[x] == -1)
    				{
    					//e.erase(mp(0, x));
    					xVal[x] = cur;
    					q[tail++] = mp(0, x);
    				}
    			}		
    		}
    	}
    }

	li minValX = INF64, minValY = INF64;
	fore (i, 1, n - 1)
		if (xVal[i] != -1)
			minValX = min(minValX, xVal[i]);
	fore (i, 1, m - 1)
		if (yVal[i] != -1)
			minValY = min(minValY, yVal[i]);

	if (minValX != INF64 && minValY != INF64)
	{
		if (minValX + minValY - c < 0)
		{
			puts("No");
			return;
		}
	}	

	forn (i, m)
		t[i] = INF;

	for (int i = n - 1; i >= 0; i--)
	{
		for (int j = sz(xx[i]) - 1; j >= 0; j--)
		{
			int pos = xx[i][j].x;

			if (xx[i][j].y > getMin(m - 1 - pos))
			{
				puts("No");
				return;
			}

			update(m - 1 - pos, xx[i][j].y);
		}
	}

	puts("Yes");
}

