vector<pii> radj[123456];

vector<pii> adj[123456];

bool seen[123456];
long long int dist[123456];
long long int small[123456];
long long int sec[123456];
void dfs(long long int at, long long int d, long long int sector) {
    //cerr << "DFS " << at << endl;;
    if(!seen[at]) {
        dist[at] = d;
        sec[at] = sector;
        small[sector] = min(small[sector], d);
        seen[at] = true;
        for(auto edge : adj[at]) {
            dfs(edge.first, d + edge.second, sector);
        }
    }
}
long long int R, C;
int main() {
    //cerr << "Begin" << endl;
    cin >> R >> C >> N;
    for(long long int i = 1; i <= N; i++) {
        cin >> a[i].first >> a[i].second >> v[i];
        radj[a[i].first].push_back({a[i].second, v[i]});
    }
    //cerr << "Read lines" << endl;

    for(long long int i = 1; i <= R; i++) {
        for(long long int j = 0; j < (long long int)radj[i].size()-1; j++) {
            //cerr << "NEXT " << radj[i].size()-1 << endl;
            pii c1 = radj[i][j];
            pii c2 = radj[i][j+1];
            //cerr << c1.first << " " << c2.first << endl;
            long long int diff = c2.second - c1.second;
            adj[c1.first].emplace_back(c2.first, diff);
            adj[c2.first].emplace_back(c1.first, -diff);
        }
    }
    //cerr << "Readinput" << endl;

    for(long long int i = 1; i <= C; i++) {
        small[i] = 1e12;
        dfs(i, 0, i);
    }

    for(long long int i = 1; i <= C; i++) {
        for(auto edge: adj[i]) {
            if(dist[i] != dist[edge.first] - edge.second) {
                //cerr << "Not consistent columns " << i << " " << edge.first << "\n";
                //cerr << dist[i] << " " << dist[edge.first] << " " << edge.second << "\n";
                cout << "No\n";
                return 0;
            }
        }
    }

    long long int lowest = 1e12;
    for(long long int i = 1; i <= N; i++) {
        long long int curd = v[i];
        long long int delta = dist[a[i].second];
        long long int offset = curd-delta;
        long long int sector = sec[a[i].second];
        long long int mylow = small[sector];
        lowest = min(lowest, mylow+offset);
    }
    if(lowest >= 0) {
        //cerr << "Lowest was only " << lowest << "\n";
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }
    return 0;
}

