class Graph{
	private:
	int V;
	vvp List;
	vl a;
	void dfs(int v,ll x){
		a[v]=x;
		for(int i=0;i<List[v].size();i++){
			P p=List[v][i];
			ll u=p.first,c=p.second;
			if(a[u]==INF) dfs(u,c-x);
		}
	}
	pll DFS(int v){
		ll mh=INF,mw=INF;
		if(v<h) mh=min(mh,a[v]);
		else mw=min(mw,a[v]);
		a[v]=INF;
		for(int i=0;i<List[v].size();i++){
			int u=List[v][i].first;
			if(a[u]!=INF){
				pll p=DFS(u);
				mh=min(mh,p.first);
				mw=min(mw,p.second);
			}
		}
		return {mh,mw};
	}
	public:
	Graph(int v){
		V=v;
		List=vvp(v);
	}
	void add_edge(int s,int t,int c){
		List[s].push_back({t,c});
		List[t].push_back({s,c});
	}
	string solve(){
		a=vl(V,INF);
		for(int i=0;i<V;i++) if(a[i]==INF) dfs(i,0);
		for(int i=0;i<V;i++) for(int j=0;j<List[i].size();j++){
			P p=List[i][j];
			ll v=p.first,c=p.second;
			if(a[i]+a[v]!=c) return "No";
		}
		for(int i=0;i<V;i++) if(a[i]!=INF){
			pll p=DFS(i);
			if(p.first+p.second<0) return "No";
		}
		return "Yes";
	}
};

