struct Node {
  int x, y;
  int64 v;
};

bool operator <(const Node& a, const Node& b) {
  return (a.x < b.x) || (a.x == b.x && a.y < b.y);
}

const int N = 1e5 + 10;
Node a[N];
int f[N];
int64 minv[N];

int find(int x) {
  if (f[x] != f[f[x]]) f[x] = find(f[x]);
  return f[x];
}

void join(int x, int y) {
  int rx = find(x), ry = find(y);
  if (rx != ry) {
    f[ry] = rx;
    minv[rx] = min(minv[rx], minv[ry]);
  }
}

int main() {
  int R, C, n;
  scanf("%d%d%d", &R, &C, &n);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d%lld", &a[i].x, &a[i].y, &a[i].v);
    --a[i].x; --a[i].y;
  }
  sort(a, a + n);
  vector<int64> delta(R);
  vector<int> visit(C, -1);
  for (int i = 0; i < R; ++i) {
    f[i] = i;
    minv[i] = INF64;
  }
  for (int i = 0, j; i < n; i = j) {
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      int k = visit[a[j].y];
      if (k >= 0) {
        delta[a[j].x] = a[j].v - a[k].v;
        break;
      }
    }
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      a[j].v -= delta[a[j].x];
      minv[a[j].x] = min(minv[a[j].x], a[j].v);
      int k = visit[a[j].y];
      if (k < 0) {
        visit[a[j].y] = j;
      } else {
        if (a[k].v != a[j].v) {
          puts("No");
          return 0;
        }
        join(a[j].x, a[k].x);
      }
    }
  }
  for (int i = 0; i < R; ++i) {
    if (find(i) != i) continue;
    if (minv[i] + delta[i] < 0) {
      puts("No");
      return 0;
    }
  }
  puts("Yes");
  return 0;
}

