const int N=1e5+5,U=1e9;
bool ok;
struct BING
{
int n,last[N],lastv[N];
int fa[N];s64 d[N],mn[N];
void init(int r,int c)
{
	n=r;
	rep(i,1,c)last[i]=0;
	rep(i,1,r){fa[i]=i;d[i]=0;mn[i]=0;}
}
void find(int x)
{
	if(fa[x]==x)return ;
	find(fa[x]);
	d[x]+=d[fa[x]];
	fa[x]=fa[fa[x]];
}
void merge(int x,int y,s64 dx)
{
	find(x);find(y);
	dx=dx-d[x]+d[y];
/*	if(!(d[x]>=-U&&d[x]<=U))
	{
		cerr<<"d[x]="<<d[x]<<endl;
		exit(0);
	}
	if(!(dx>=-U&&dx<=U))
	{
		cerr<<"dx="<<dx<<endl;
		exit(0);
	}*/
	x=fa[x];y=fa[y];
	//cerr<<x<<" "<<y<<" "<<dx<<endl;
	if(x==y){ok&=dx==0;return ;}
	fa[x]=y;d[x]=dx;
}
void ins(int x,int y,int a)
{
	//assert(a==0||a==U);
	if(!last[y])
	{
		last[y]=x;lastv[y]=a;
		return ;
	}
	merge(x,last[y],a-lastv[y]);
}
void init_mn()
{
	rep(i,1,n)
	{
		find(i);
		chmin(mn[fa[i]],d[i]);
	}
}
s64 get_mn(int x)
{
	return -d[x]+mn[fa[x]];
}
};
