	vector<PLL>& xs = row[y];
	SORT(xs);
	for(int i=0;i+1<SZ(xs);++i){
	  Gx[xs[i].FF].EB(xs[i+1].FF, xs[i+1].SS - xs[i].SS);
	  Gx[xs[i+1].FF].EB(xs[i].FF, xs[i].SS - xs[i+1].SS);
	}
