	vis.PB(u);
	for(auto& e: G[u]){
	  if(d[e.FF] == INF){
		d[e.FF] = d[u] + e.SS;
		if(!dfs(G, e.FF, d,vis))
		  return false;
	  }
	  else{
		if(d[u] + e.SS != d[e.FF]){
		  return false;
		}
	  }
	}
	return true;
  };

  REP(x,W){
	if(dx[x] != INF) continue;
