const int INF=1000000005;

void dfs(int a,int b){

	if(!l[a][b]) return;

	if(r[a]!=INF&&c[b]!=INF) return;

	if(r[a]==INF&&c[b]!=INF){
  		r[a]=m[a][b]-c[b]; 
  	}
  	if(r[a]!=INF&&c[b]==INF){
  		c[b]=m[a][b]-r[a]; 
  	}
  	if(a-1>=1) dfs(a-1,b); 

  	if(a+1<=R) dfs(a+1,b); 

  	if(b-1>=1) dfs(a,b-1); 

  	if(b+1<=C) dfs(a,b+1); 

  	return;

}

