  for(int i=0; i<N; i++){
  	X[i]=G[i].first.first;
  	Y[i]=G[i].first.second;
  	A[i]=G[i].second;
  }

  for(int i=0; i<N; i++){
  	m[X[i]][Y[i]]=A[i];
  	l[X[i]][Y[i]]=1;
  }

  for(int i=0; i<100005; i++){
  	c[i]=INF; r[i]=INF;
  }

  c[Y[0]]=0;

  for(int i=0; i<N; i++){
  	if(Y[i]==Y[0]){
  		r[X[i]]=A[i]; 
  	}
  }

  for(int i=0; i<N; i++){
  	if(r[X[i]]==INF&&c[Y[i]]==INF) continue;
  	if(r[X[i]]==INF||c[Y[i]]==INF) dfs(X[i],Y[i]);
  }

  for(int i=0; i<N; i++){
  	if(r[X[i]]!=INF&&c[Y[i]]!=INF){
  		if(r[X[i]]+c[Y[i]]!=A[i]){
  			cout<<"No"<<endl; return 0;
  		}
  	}
  }

  int x=INF,y=INF; int p,q;

  for(int i=1; i<=R; i++){
  	if(r[i]<x){
  		x=r[i]; p=i;
  	}
  }

  for(int i=1; i<=C; i++){
  	if(c[i]<y){
  		y=c[i]; q=i;
  	}
  }

  if(r[p]+c[q]<0){
  	cout<<"No"<<endl; return 0;
  }

  cout<<"Yes"<<endl;

  //cout<<r[2]<<endl;

  return 0;

}

