using namespace std;
typedef unsigned long long ull;

int R, C, N;
vector<pair<ull, ull> > v;
map<ull, int> field;
map<ull, bool> filled;
bool flag;

const int dx[] = {1, 1, -1, -1};
const int dy[] = {1, -1, 1, -1};

bool isIllegal(ull ri, ull ci) {
    int ai = field[C * ri + ci];

    for (int j = 0; j < 4; j++) {
        ull y = ri + dy[j];
        ull x = ci + dx[j];
        if (x < 0 || C <= x || y < 0 || R <= y) continue;
        int temp;
        int cnt =
            1 + filled[C * ri + x] + filled[C * y + ci] + filled[C * y + x];
        if (cnt == 1) continue;
        if (cnt == 4) {
            if (ai + field[C * y + x] !=
                field[C * ri + x] + field[C * y + ci]) {
                return true;
            }
        } else if (!filled[C * ri + x]) {
            if (cnt == 3)
                temp = ai + field[C * y + x] - field[C * y + ci];
            else
                temp = 0;
            field[C * ri + x] = temp;
            filled[C * ri + x] = true;
            v.push_back(make_pair(ri, x));
            flag = false;
            if (temp < 0) return true;
            return false;
        } else if (!filled[C * y + ci]) {
            if (cnt == 3)
                temp = ai + field[C * y + x] - field[C * ri + x];
            else
                temp = 0;
            field[C * y + ci] = temp;
            filled[C * y + ci] = true;
            v.push_back(make_pair(y, ci));
            flag = false;
            if (temp < 0) return true;
            return false;
        } else if (!filled[C * y + x]) {
            if (cnt == 3)
                temp = field[C * ri + x] + field[C * y + ci] - ai;
            else
                temp = 0;
            field[C * y + x] = temp;
            filled[C * y + x] = true;
            v.push_back(make_pair(y, x));
            flag = false;
            if (temp < 0) return true;
            return false;
        }
    }
    return false;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> R >> C >> N;
    for (int i = 0; i < N; i++) {
        int r, c, a;
        cin >> r >> c >> a;
        r--;
        c--;
        v.push_back(make_pair(r, c));
        field[C * r + c] = a;
        filled[C * r + c] = true;
    }

    while (1) {
        flag = true;
        for (int i = 0; i < v.size(); i++) {
            if (isIllegal(v[i].first, v[i].second)) {
                cout << "No" << endl;
                return 0;
            }
        }
        if (flag) break;
    }

    cout << "Yes" << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
class disjoint_set {
  public:
  vector<int> rank, prt, ptl;
  disjoint_set (int size) {
    rank.resize(size);
    prt.resize(size);
    ptl.resize(size);
    for (int i = 0; i < size; i++) {
      prt[i] = i;
      rank[i] = 0;
      ptl[i] = 0;
    }
  }
  int find (int x) {
    if (x == prt[x]){
      return x;
    } else {
      int r = find(prt[x]);
      ptl[x] += ptl[prt[x]];
      return prt[x] = r;
    }
  }
  bool is_equiv (int x, int y) {
    return find(x) == find(y);
  }
  bool unite (int x, int y, int w) {
    if (find(x) == find(y)) {
      return false;
    }
    w += ptl[x];
    w -= ptl[y];
    x = find(x);
    y = find(y);
    if (rank[x] < rank[y]) {
      swap(x, y);
      w *= -1;
    }
    prt[y] = x;
    ptl[y] = w;
    if (rank[x] == rank[y]) {
      rank[x]++;
    }
    return true;
  }
  int diff (int x, int y) {
    find(x);
    find(y);
    return ptl[y] - ptl[x];
  }
};
void err() {
  cout << "No" << '\n';
  exit(0);
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int h, w, n;
  cin >> h >> w >> n;
  vector<pair<pair<int, int>, int>> cnd(n);
  int d = 0;
  for (int t = 0; t < n; t++) {
    int i, j, a;
    cin >> i >> j >> a;
    cnd[t] = {{--i, --j}, a};
    if (i == 0 && j == 0) {
      d = a;
    }
  }
  for (auto& p : cnd) {
    int i = p.first.first;
    int j = p.first.second;
    int& a = p.second;
    if (i > 0 && j > 0) {
      a += d;
    } else if (i == 0 && j == 0) {
      a = 0;
    }
  }
  disjoint_set djs(h + w - 1);
  int mina = 2e9;
  int maxb = -2e9;
  for (auto p : cnd) {
    int i = p.first.first;
    int j = p.first.second;
    int s = h - 1 + j;
    int t = h - 1 - i;
    int w = p.second;
    if (djs.is_equiv(s, t)) {
      if (djs.diff(s, t) != w) {
        err();
      }
    } else {
      djs.unite(s, t, w);
      for (int r = 0; r < 2; r++) {
        if (djs.is_equiv(h - 1, s)) {
          if (s < h - 1) {
            mina = min(mina, djs.diff(h - 1, s));
          } else if (h - 1 < s) {
            maxb = max(maxb, djs.diff(s, h - 1));
          }
        }
        swap(s, t);
      }
    }
  }
  if (maxb > 0 && mina - maxb < d) {
    err();
  }
  cout << "Yes" << '\n';
  return 0;
}

