typedef long long int ll;

using namespace std;

int R, C, N;
int wr[100001], wc[100001];

struct E{
    int to, cost;
    E(int t, int c): to(t), cost(c) {};
};
vector<E> edge_r[100001], edge_c[100001];
int rmin, cmin;

bool dfs(int v) {
    if(v < R) {
        rmin = min(rmin, wr[v]);
        REP(i, edge_r[v].size()) {
            E e = edge_r[v][i];
            if(wc[e.to] != -1) {
                if(wr[v]+wc[e.to]!=e.cost) return false;
            } else {
                wc[e.to] = e.cost - wr[v];
                if(!dfs(e.to+R)) return false;
            }
        }
    }
    else {
        v -= R;
        cmin = min(cmin, wc[v]);
        REP(i, edge_c[v].size()) {
            E e = edge_c[v][i];
            if(wr[e.to] != -1) {
                if(wc[v]+wr[e.to]!=e.cost) return false;
            } else {
                wr[e.to] = e.cost - wc[v];
                if(!dfs(e.to)) return false;
            }
        }
    }
    return true;
}

int main(void) {
    int tr, tc, ta;
    cin >> R >> C >> N;

    REP(i, R) wr[i] = -1;
    REP(i, C) wc[i] = -1;

    REP(i, N) {
        cin >> tr >> tc >> ta;
        tr--; tc--;
        edge_r[tr].push_back(E(tc, ta));
        edge_c[tc].push_back(E(tr, ta));
    }

    REP(i, R) {
        if(wr[i] != -1 || edge_r[i].size() == 0) continue;
        wr[i] = 0;
        rmin = numeric_limits<int>::max();
        cmin = numeric_limits<int>::max();
        if(!dfs(i) || rmin+cmin < 0) {
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
}

