							if (!arr[i].count(c - 1)) arr[i][c - 1] = 0, next = next1 + 1;
							if (!arr[i1].count(c - 1)) arr[i1][c - 1] = 0, next = next1 + 1;
							ll d1 = arr[i][c - 1], e1 = arr[i1][c - 1];
							if (d + e1 != d1 + e) {
								ans = 0; break;
							}
						}
					}
				}
				if (i < R) {
					ll e = -1, i1 = i + 1;
					if (arr[i1].count(c)) e = arr[i1][c];
					if (e == 0) {
						if (c < C) {
							if (!arr[i].count(c + 1)) arr[i][c + 1] = 0, next = next1 + 1;
							if (!arr[i1].count(c + 1)) arr[i1][c + 1] = 0, next = next1 + 1;
							ll d1 = arr[i][c + 1], e1 = arr[i1][c + 1];
							if (d + e1 != d1 + e) {
								ans = 0; break;
							}
						}
						if (c > 1) {
							if (!arr[i].count(c - 1)) arr[i][c - 1] = 0, next = next1 + 1;
							if (!arr[i1].count(c - 1)) arr[i1][c - 1] = 0, next = next1 + 1;
							ll d1 = arr[i][c - 1], e1 = arr[i1][c - 1];
							if (d + e1 != d1 + e) {
								ans = 0; break;
							}
						}
					}
				}

				it++;
			}
		}


	}
	if (ans) cout << "Yes" << endl;
	else cout << "No" << endl;

	return 0;
}

