ll memo[2*MAXN];

void no() {
    cout << "No" << endl;
    exit(0);
}
int R, C;
const ll INF = 1ll<<50;

bool dfs(int v, pii& p) {
    done[v] = true;
    if (v < R) p.first = min(p.first, memo[v]);
    else p.second = min(p.second, memo[v]);
    for (pii e : G[v]) {
        if (done[e.first]) {
            if (e.second != memo[v]+memo[e.first]) return false;
            else continue;
        } else {
            memo[e.first] = e.second - memo[v];
            if (!dfs(e.first, p)) return false;
        }
    }
    return true;
}

