        G[R+c[i]].emplace_back(r[i], a[i]);
    }
    for (int i = 0; i < R; i++) if (!done[i]) {
        memo[i] = 0;
        pii p(INF, INF);
        if (!dfs(i, p)) no();
        if (p.first+p.second < 0) no();
    }
    cout << "Yes" << endl;
