bool check(int r,int c)
{
    for(int tdr = -1;tdr <= 1; tdr += 2)
        for(int tdc = -1;tdc <= 1;tdc += 2)
        {
            int tr = r + tdr;
            int tc = c + tdc;

            if(tr >= 1 && tr <= R && tc >= 1 && tc <= C)
            {
                int Minr = min(r,tr),Maxr = max(r,tr);
                int Minc = min(c,tc),Maxc = max(c,tc);
                for(int i = Minr;i <= Maxr;++i)
                    for(int j = Minc;j <= Maxc;++j)
                    {
                        if(!M.count(Node(i,j))) goto e;
                    }


                if(M[Node(Minr,Minc)]+M[Node(Maxr,Maxc)] != M[Node(Minr,Maxc)] + M[Node(Maxr,Minc)])
                    return false;

            }

            e: 1;

        }

    return true;

}



bool gao(int r,int c)
{
    if(!check(r,c)) return false;

    for(int tdr = -1;tdr <= 1; tdr += 2)
        for(int tdc = -1;tdc <= 1;tdc += 2)
        {
            int tr = r + tdr;
            int tc = c + tdc;

            if(tr >= 1 && tr <= R && tc >= 1 && tc <= C)
            {
                int Minr = min(r,tr),Maxr = max(r,tr);
                int Minc = min(c,tc),Maxc = max(c,tc);
                int cnt = 0;
                int sum1 = 0,sum2 = 0;
                int nr,nc;
                for(int i = Minr;i <= Maxr;++i)
                    for(int j = Minc;j <= Maxc;++j)
                    {
                        if(!M.count(Node(i,j)))
                        {
                            cnt++;
                            nr = i,nc = j;
                        }
                        else
                        {
                            if((i-Minr+j-Minc)%2 == 0)
                                sum1 += M[Node(i,j)];
                            else
                                sum2 += M[Node(i,j)];

                        }
                    }


                if(cnt == 1)
                {

                    int lft;
                    if( (nr-Minr+nc-Minc)%2 == 0)
                        lft = sum2-sum1;
                    else
                        lft = sum1-sum2;

                    if(lft <= 0) return false;
                    M[Node(nr,nc)] = lft;
                    if(!check(nr,nc)) return false;


                }
            }
        }



    return true;

}


