        if(val[j] == INF){
            val[j] = a - val[i];
            if(j<R){
                rmin = min(rmin, val[j]);
            }else{
                cmin = min(cmin, val[j]);
            }
            bool result = dfs(j, i);
            if(!result) return false;
        }else{
            if(val[i] + val[j] != a){
                return false;
            }
        }
    }
    return true;
}

