        fh[y][x] = a;
        fw[x][y] = a;
    }
    // compute
    bool ans = fh.size() < fw.size() ? check(fh) : check(fw);
    // output
    fprintf(stderr, "%s\n", ans ? "Yes" : "No");
    printf("%s\n", ans ? "Yes" : "No");
    return 0;
}

