    if (is_inside(r1, c1)) {
      ok = calc_cell(r1, c1, r, c, r2, c2, r4, c4) &&
           calc_cell(r2, c2, r4, c4, r1, c1, r, c) &&
           calc_cell(r4, c4, r2, c2, r1, c1, r, c);
      if (!ok) break;
    }
    //cout << "ul" << endl;

    // up right
    if (is_inside(r3, c3)) {
      ok = calc_cell(r3, c3, r, c, r2, c2, r5, c5) &&
