struct wunionf{
	vector<int> data;
	vector<typ> we;
	wunionf(int size):data(size,-1),we(size,0){}

	//x+z=yになるようにする
	//矛盾するかの判定はしてない(diffを使って判定しよう)
	bool unions(int x,int y,typ z){
		z+=weight(x);z-=weight(y);
		x=root(x);y=root(y);
		if(x!=y){
			if(data[y]<data[x]){int d=x;x=y;y=d;z=-z;}
			data[x]+=data[y];data[y]=x;
			we[y]=z;
		}
		return x!=y;
	}

	int weight(int x){
		root(x);
		return we[x];
	}

	bool finds(int x,int y){
		return root(x)==root(y);
	}
	int root(int x){
		if(data[x]<0) return x;
		int par=root(data[x]);
		we[x]+=we[data[x]];
		return data[x]=par;
	}

	int find(int x){
		return -data[x];
	}

	//y-x(xから見たyの重み)を求める。やる前にfinds(x,y)でつながってるかを確認する。
	typ diff(int x,int y){
		return we[y]-we[x];
	}
};
string cal(void)
{
	wunionf uni(252521);
	int R,C,n;
	scanf("%d %d",&R,&C);
	scanf("%d",&n);
	rep(i,n) scanf("%d %d %lld",&r[i],&c[i],&a[i]);
