		r[i]--;c[i]--;
		gr[r[i]].pb(mp(c[i],a[i]));
		gr[c[i]+N].pb(mp(r[i]+N,a[i]));
	}
	rep(i,2*N){
		if(gr[i].size()<2) continue;
		int m=gr[i].size();
		sort(All(gr[i]));
		rep(j,m-1){
			int x=gr[i][j].fi,y=gr[i][j+1].fi;lint z=gr[i][j+1].se-gr[i][j].se;
			if(uni.finds(x,y) && uni.diff(x,y)!=z) return "No";
			uni.unions(x,y,z);
		}
	}
	rep(i,114514) mi[i]=1145141919819364364LL;
	rep(i,2*N){
		int r=uni.root(i);
		mi[r]=min(mi[r],uni.diff(r,i));
	}
	rep(i,n){
		int r1=uni.root(c[i]),r2=uni.root(r[i]+N);
		if(a[i]+uni.diff(c[i],r1)+mi[r1]+uni.diff(r[i]+N,r2)+mi[r2]<0LL) return "No";
	}
	return "Yes";
}
