      cerr << "min[" << i << "]: " << mi[i] << endl;
    }
  }
  */
  bool ok = 1;
  REP(i, 0, n) {
    if (dp[cc[i]] > inf && a[i] - dp[cc[i]] + mi[root[cc[i]]] < 0) {
      ok = 0;
    }
  }
  cout << (ok ? "Yes" : "No") << endl;
}

