typedef pair<int, int> PII;

int r, c, n;
vector<PII> G[200005];
bool vis[200005];
int w[200005];

PII dfs(int v, int h) {
  if (vis[v]) {
    if (w[v] != h) {
      printf("No\n");
      exit(0);
    }
    return PII(INT_MAX / 2 - 1, INT_MAX / 2 - 1);
  }
  w[v] = h;
  vis[v] = true;
  int w1 = h, w2 = INT_MAX / 2 - 1;
  for (int i = 0; i < G[v].size(); i += 1) {
    PII tmp = dfs(G[v][i].first, G[v][i].second - h);
    w1 = min(w1, tmp.second);
    w2 = min(w2, tmp.first);
  }
  return PII(w1, w2);
}

