			if(z[6] < 0 && z[8] >= 0) b = (b && (z[6] = z[3] + z[5] - z[8]) >= 0);
			if(z[8] < 0 && z[6] >= 0) b = (b && (z[8] = z[3] + z[5] - z[6]) >= 0);
		}
		if(z[1] >= 0 && z[7] >= 0){
			if(z[0] >= 0 && z[6] >= 0) b = (b && judge(z[0] , z[6] , z[3] , z[5]));
