            }
        }
        static int64 value[N];
        for (int v : comp) {
            for (auto j : cy[v]) {
                value[j.fs] = j.sc - delta[v];
            }
        }
        int64 minDelta = linf;
        for (int v : comp) {
            minDelta = min(minDelta, delta[v]);
        }
        for (int v : comp) {
            for (auto j : cy[v]) {
                if (value[j.fs] + minDelta < 0) {
                    puts("No");
                    return 0;
                }
            }
        }
    }
    puts("Yes");
    return 0;
}

