struct Edge{
	int to;
	long long val;
	Edge(){}
	Edge(int a, int b){
		to = a;
		val = b;
	}
};

vector<Edge> G[200200];

void add_edge(int r, int c, int a){
	G[r].push_back(Edge(c + R, a));
	G[c + R].push_back(Edge(r, a));
}

void dfs(int v, int p, int k){
	if(p == -1){
		vals[v] = 0;
		used[v] = true;
	}
	compo[v] = k;
	for(int i = 0; i < G[v].size(); ++i){
		int u = G[v][i].to;
		if(u == p) continue;
		if(!used[u]){
			used[u] = true;
			vals[u] = G[v][i].val - vals[v];
			dfs(u, v, k);
		} else {
			if(vals[u] + vals[v] == G[v][i].val){
				continue;
			} else {
				printf("No\n");
				exit(0);
			}
		}
	}
}

