	for(int i = 0; i < N; ++i){
		add_edge(rs[i], cs[i], as[i]);
	}
	for(int i = 0; i < R + C; ++i){
		used[i] = false;
	}
	int co = 0;
	for(int i = 0; i < R + C; ++i){
		if(!used[i]){
			dfs(i, -1, co++);
		}
	}
	for(int i = 0; i < co; ++i){
		min_rs[i] = 1e17;
		min_cs[i] = 1e17;
	}
	for(int i = 0; i < R; ++i){
		int c = compo[i];
		min_rs[c] = min(min_rs[c], vals[i]);
	}
	for(int i = 0; i < C; ++i){
		int c = compo[i + R];
		min_cs[c] = min(min_cs[c], vals[i + R]);
	}
	for(int i = 0; i < co; ++i){
		if(min_cs[i] + min_rs[i] < 0) return false;
	}
	return true;
}

