vpi col[N], str[N];
int used[N], val[N], gval[N], label = 1;
vpi g[N], g2[N];


void dfs(int v, int vl)
{
    used[v] = 1;
    val[v] = vl;

    for (pii p : g[v])
    {
        if (used[p.first])
        {
            if (val[p.first] != vl + p.second)
                label = 0;
        }
        else
            dfs(p.first, vl + p.second);
    }
}


void dfs_init(int v, int last = -1, int p = -1)
{
    used[v] = 1;
    vpi hui;

    for (auto p : g[v])
    {
        if (!used[p.first])
        {
            g2[v].push_back(p);
            dfs_init(p.first, p.second, v);
        }
    }
}


int dp_down[N];


void dfs_down(int v, int p = -1)
{
    used[v] = 1;
    dp_down[v] = 0;

    for (auto p : g2[v])
        dfs_down(p.first, v);

    for (auto p : g2[v])
        dp_down[v] = min(dp_down[v], dp_down[p.first] + p.second);
}


bool dfs_up(int v, int p = -1, int dp_up = 0, int last = 0)
{
    int cval = dp_up + -last;
    if (min(cval, dp_down[v]) + gval[v] < 0)
        return 0;

    cval = dp_up + -last;
    vi hui, pr, sf;

    for (auto p : g2[v])
        hui.push_back(dp_down[p.first] + p.second);

    pr = hui, sf = hui;
    for (int i = 1; i < SZ(pr); ++i)
        pr[i] = min(pr[i], pr[i - 1]);

    for (int i = SZ(sf) - 2; i >= 0; --i)
        sf[i] = min(sf[i], sf[i + 1]);

    bool label = 1;
    for (int i = 0; i < SZ(g2[v]); ++i)
    {
        auto p = g2[v][i];
        int cnt = cval;
        if (i)
            cnt = min(cnt, pr[i - 1]);

        if (i + 1 != SZ(g2[v]))
            cnt = min(cnt, sf[i + 1]);

        label = min(label, dfs_up(p.first, v, cnt, p.second));
    }

    return label;
}


void smain() {
    int r, c, n;
    cin >> r >> c >> n;

    for (int i = 0; i < N; ++i)
        gval[i] = oo;

    for (int i = 0; i < n; ++i) {
        int r, c, v;
        cin >> r >> c >> v;
        str[r].push_back(mp(c, v));
        col[c].push_back(mp(r, v));
        gval[r] = min(gval[r], v);
    }

    for (int i = 0; i < N; ++i) {
        stable_sort(ALL(str[i]));
        stable_sort(ALL(col[i]));
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 1; j < SZ(col[i]); ++j) {
            pii a = col[i][j - 1], b = col[i][j];
            g[a.first].push_back(mp(b.first, b.second - a.second));
            g[b.first].push_back(mp(a.first, a.second - b.second));
        }
    }

    for (int i = 1; i <= r; ++i) {
        if (!used[i])
            dfs(i, 0);
    }

    if (!label) {
        cout << "No\n";
        return;
    }

    fill(used, used + N, 0);
    for (int i = 1; i <= r; ++i) {
        if (!used[i])
            dfs_init(i);
    }

    fill(used, used + N, 0);
    for (int i = 1; i <= r; ++i) {
        if (!used[i]) {
            dfs_down(i);
            if (gval[i] + dp_down[i] < 0)
                label = 0;

            if (!dfs_up(i))
                label = 0;
        }
    }

    if (label)
    {
        cout << "Yes\n";
    }
    else {
        cout << "No\n";
    }
}

