bool dfs(int v, int k)
{
	vis[v] = k;
	for (edge e : g[v]) {
		if (vis[e.to] != -1) {
			if (d[e.to] - d[v] != e.cost) {
				return false;
			}
		} else {
			d[e.to] = d[v] + e.cost;
			dfs(e.to, k);
		}
	}
	return true;
}

