    a = fi(a);
    b = fi(b);
    if(a==b)return 1;
    if(l[a].mp.size()<l[b].mp.size())swap(a,b);
    auto it = l[a].mp.find(y); assert(it!=l[a].mp.end());
    auto jt = l[b].mp.find(y); assert(jt!=l[b].mp.end());
    const int d = it->SEC-jt->SEC;
    l[a].mn = min(l[a].mn-d,l[b].mn+d);
    for(const auto&x:l[b].mp){
        auto kt = l[a].mp.find(x.FIR);
        if(kt==l[a].mp.end()){
            l[a].mp.insert(make_pair(x.FIR,x.SEC+d));
        }else if(kt->SEC!=x.SEC+d){
