bool DFSUtil(int, vector<bool>&, vector<bool> &);
vector<pair<int, int>> g[1234567];
long long node[1234567] = {0};
int R, C;
long long minR, minC = 1000000000;


int main(){
  cin >> R >> C;
  int N;
  cin >> N;  
  for(int i = 0; i < N; i++){
    int r, c, a;
    cin >> r >> c >> a;
    r--; c--;
    g[r].push_back(make_pair( c + C, a));
    g[c + C].push_back(make_pair(r, a));
  }

  vector<bool> visited(R + C, false);
  vector<bool> was(R + C, false);
  if(!DFSUtil(0, visited, was)){
    cout << "No";
  }
  else{
    cout << "Yes";
  }
}

bool DFSUtil(int v, vector<bool> &visited, vector<bool> &was){
  visited[v] = true;
  was[v] = true;
  for(int i = 0; i < g[v].size(); i++){
    int w = g[v][i].first;
    int a = g[v][i].second;
    if(was[w]){
      if(node[v] + node[w] != a){
        return false;
      }
      continue;
    }
    node[w] = a - node[v];
    was[w] = true;

    if(v < R) minR = minR >node[v] ? node[v] : minR;
    if(v >= R) minC = minC>node[v] ? node[v] : minC;
    if(minR + minC < 0) return false;
    if(!visited[w]){
      if(!DFSUtil(w, visited, was)) return false;
    }
  }
  return true;
}

