bool valid(){
  REP(i,125252)dist[i] = 1e11;
  REP(i,125252)used[i] = false;
  dist[0] = 0;
  used[0] = true;
  queue<int> Q;
  Q.push(0);
  while(!Q.empty()){
    int p = Q.front(); Q.pop();
    ll d = dist[p];
    REP(i,g[p].size()){
      int to = g[p][i].first;
      ll cost = g[p][i].second;
      ll nd = d+cost;
      if(used[to]){
        if(dist[to]!=nd)return false;
      }else{
        dist[to] = nd;
        used[to] = true;
        Q.push(to);
      }
    }
  }
  return true;
}

const int MAX = 1<<17;
ll seg[2*MAX];
ll sum[2*MAX];
void init(int n){
  REP(i,MAX)seg[i+MAX-1]=0;
  REP(i,n)seg[i+MAX-1]=dist[i];
  FORR(i,0,MAX-1)seg[i]=min(seg[2*i+1],seg[2*i+2]);
  REP(i,2*MAX)sum[i]=0;
}
void add(int l,int r,ll v,int a,int b,int k){
  if(r<=a || b<=l)return;
  if(l<=a && b<=r){
    sum[k] += v;
    seg[k] += v;
  }else{
    int m = (a+b)/2;
    add(l,r,v,a,m,2*k+1);
    add(l,r,v,m,b,2*k+2);
    seg[k] = min(seg[2*k+1],seg[2*k+2])+sum[k];
  }
}
void add(int l,int r,ll v){
  add(l,r,v,0,MAX,0);
}
ll query(int l,int r,int a,int b,int k){
  if(r<=a || b<=l)return 1e18;
  if(l<=a && b<=r){
    return seg[k];
  }else{
    int m = (a+b)/2;
    return min(query(l,r,a,m,2*k+1),query(l,r,m,b,2*k+2))+sum[k];
  }
}
ll query(int l,int r){
  return query(l,r,0,MAX,0);
}

int main(){
  scanf("%d%d%d",&r,&c,&n);
  set<int> Sx,Sy;
  REP(i,n){
    int x,y,a;
    scanf("%d%d%d",&x,&y,&a);
    ps[i] = pii(x,y);
    val[i] = a;
    Sx.insert(x);
    Sy.insert(y);
  }
  map<int,int> Mx,My;
  int it = 0;
  for(const int& x:Sx){
    Mx[x] = it++;
  }
  r = it;
  it = 0;
  for(const int& y:Sy){
    My[y] = it++;
  }
  c = it;

  REP(i,n){
    int x,y;
    x=Mx[ps[i].first];
    y=My[ps[i].second];
    xs[y].push_back(x);
    ys[x].push_back(y);
    ps[i] = pii(x,y);
    rev[ps[i]] = i;
  }
  // graph
  REP(i,125252)g[i].clear();
  REP(i,r){
    sort(ALL(ys[i]));
    vi &vec = ys[i];
    REP(j,vec.size()-1){
      int s,t;
      s = vec[j];
      t = vec[j+1];
      int sid = rev[pii(i,s)];
      int tid = rev[pii(i,t)];
      ll sa = val[tid]-val[sid];
      g[s].push_back(pll(t,sa));
      g[t].push_back(pll(s,-sa));
    }
  }
  if(!valid()){
    puts("No");
    return 0;
  }
  // negative check
  init(c);
  REP(i,r){
    ll mn = query(0,c);
    if(mn + ys[i][0] < 0){
      puts("No");
      return 0;
    }
    if(i==r-1)break;
    ll d = dist[i+1]-dist[i];
    add(0,i+1,d);
    add(i+1,c,-d);
  }
  // graph
  REP(i,125252)g[i].clear();
  REP(i,c){
    sort(ALL(xs[i]));
    vi &vec = xs[i];
    REP(j,vec.size()-1){
      int s,t;
      s = vec[j];
      t = vec[j+1];
      int sid = rev[pii(s,i)];
      int tid = rev[pii(t,i)];
      ll sa = val[tid]-val[sid];
      g[s].push_back(pll(t,sa));
      g[t].push_back(pll(s,-sa));
    }
  }
  if(!valid()){
    puts("No");
    return 0;
  }
  // negative check
  init(r);
  REP(i,c){
    ll mn = query(0,r);
    if(mn + xs[i][0] < 0){
      puts("No");
      return 0;
    }
    if(i==c-1)break;
    ll d = dist[i+1]-dist[i];
    add(0,i+1,d);
    add(i+1,r,-d);
  }
  // ok
  puts("Yes");
  return 0;
}

