		}
		last = false;
		for(int j = 0; j < vr[i].size(); j++) {
			mn = min(mn, (ll)vr[i][j].se);
			if(mp.find(vr[i][j].fi) != mp.end()) {
				pii tmp;
				tmp = mp[vr[i][j].fi];
				if(tmp.se + dc[i-1] - (tmp.fi ? dr[tmp.fi-1] : 0) != vr[i][j].se) {
					flg = false;
				}
			}
			else {
				mp[vr[i][j].fi] = pll(i, vr[i][j].se);
			}
		}
		if(check_r[i]) {
			last = true;
			mn = mn + dr[i] - (i ? dr[i-1] : 0);
		}
		else {
			mp.clear();
		}
		if(mn < 0) {
			flg = false;
		}
	}

	if(flg)
		cout << "Yes" << endl;
	else
		cout << "No" << endl;
}

