const ll inf= 5e15;

// idx, num
bool check(const vec<pll> &l1, const vec<pll> &l2) {
    vec<pll> split;
    for (ll i1 = 0, i2 = 0; i1 < l1.size() && i2 < l2.size(); ) {
        ll idx1, n1, idx2, n2;
        std::tie(idx1, n1) = l1[i1];
        std::tie(idx2, n2) = l2[i2];
        if (idx1 == idx2) {
            split.emplace_back(i1, i2);
            i1++, i2++;
        } else if (idx1 < idx2) {
            i1++;
        } else {
            i2++;
        }
    }

    auto check_f = [&](const vec<pll> &line, ll idx, ll val, ll l, ll r) {
        ll base = line[idx].second;
        for (ll i = idx - 1; 0 <= i && l < line[i].first; i--) {
            ll diff = line[i].second - base;
            if (val + diff < 0) return false;
        }
        for (ll i = idx + 1; i < line.size() && line[i].first < r; i++) {
            ll diff = line[i].second - base;
            if (val + diff < 0) return false;
        }
        return true;
    };

    for (ll i = 0; i < split.size(); i++) {
        ll i1, i2;
        std::tie(i1, i2) = split[i];
        ll v1 = l1[i1].second, v2 = l2[i2].second;
        if (i + 1 < split.size()) {
            ll ni1, ni2;
            std::tie(ni1, ni2) = split[i + 1];
            ll nv1 = l1[ni1].second, nv2 = l2[ni2].second;
            if (v1 - nv1 != v2 - nv2) return false;
        }
        ll l = (i == 0 ? -inf : l1[split[i - 1].first].first);
        ll r = (i + 1 == split.size() ? inf : l1[split[i + 1].first].first);
        if (!check_f(l1, i1, v2, l, r)) return false;
        if (!check_f(l2, i2, v1, l, r)) return false;
    }

    return true;
}

bool solve() {
    ll r, c, n;
    std::cin >> r >> c >> n;
    vvec<pll> rows(r), cols(c);
    for (ll i = 0; i < n; i++) {
        ll ri, ci, a;
        std::cin >> ri >> ci >> a;
        ri--; ci--;
        rows[ri].emplace_back(ci, a);
        cols[ci].emplace_back(ri, a);
    }

    for (auto &&v : rows) std::sort(ALL(v));
    for (auto &&v : cols) std::sort(ALL(v));
    for (ll i = 0; i + 1 < r; i++) if (!check(rows[i], rows[i + 1])) return false;
    for (ll i = 0; i + 1 < c; i++) if (!check(cols[i], cols[i + 1])) return false;
    return true;
}

