        int y,x,a;
        cin >> y >> x >> a;
        --y;
        --x;
        ps.push_back(make_pair(y,x));
        as.push_back(a);
        ys.push_back(y);
        xs.push_back(x);
    }
    unordered_map<int,int> y_zip,x_zip;
    vector<int> y_unzip,x_unzip;
    int y_size=compress(ys,y_zip,y_unzip);
    int x_size=compress(xs,x_zip,x_unzip);
    vector<vector<int>> vs(y_size,vector<int>(x_size,-1));
    rep(i,0,ps.size()) vs[y_zip[ps[i].first]][x_zip[ps[i].second]]=as[i];
    rep(y,0,y_size){
        rep(x,0,x_size){
            if((y==0 and x==0) or vs[y][x]!=-1) continue;
            if(y>0 and x==0){
                vs[y][x]=vs[y-1][x];
            }else if(y==0 and x>0){
                vs[y][x]=vs[y][x-1];
            }else{
                vs[y][x]=vs[y-1][x]+vs[y][x-1]-vs[y-1][x-1];
                if(vs[y][x]<0){
                    cout << "No" << endl;
                    return;
                }
            }
        }
    }
    rep(y,1,y_size){
        rep(x,1,x_size){
            if(vs[y][x]+vs[y-1][x-1]!=vs[y-1][x]+vs[y][x-1]){
                cout << "No" << endl;
                return;
            }
        }
    }
    cout << "Yes" << endl;
}

