bool kakikomi(vector<vector<int>>&masu, queue<array<int, 2>>&Q, int r, int c) {
	//ダメならfalseを返す
	int blank = 0;
	rep(i, 2)rep(j, 2)if (masu[r + i][c + j] == -1)blank++;
	if (blank == 0) {
		if (masu[r][c] + masu[r + 1][c + 1] == masu[r + 1][c] + masu[r][c + 1])return true;
		return false;
	}
	if (blank == 1) {
		if (masu[r][c] == -1) {
			int num = masu[r + 1][c] + masu[r][c + 1] - masu[r + 1][c + 1];
			if (num < 0)return false;
			masu[r][c] = num;
			Q.push({ r,c });
			return true;
		}
		else if (masu[r+1][c+1] == -1) {
			int num = masu[r + 1][c] + masu[r][c + 1] - masu[r][c];
			if (num < 0)return false;
			masu[r+1][c+1] = num;
			Q.push({ r+1,c+1 });
			return true;
		}
		else if (masu[r + 1][c] == -1) {
			int num = masu[r][c] + masu[r + 1][c + 1] - masu[r][c + 1];
			if (num < 0)return false;
			masu[r + 1][c] = num;
			Q.push({ r + 1,c });
			return true;
		}
		else if (masu[r][c + 1] == -1) {
			int num = masu[r][c] + masu[r + 1][c + 1] - masu[r + 1][c];
			if (num < 0)return false;
			masu[r][c + 1] = num;
			Q.push({ r,c + 1 });
			return true;
		}
	}
	return true;
}

