int main() {
  int h, w, cnt;
  scanf("%d %d", &h, &w);
  scanf("%d", &cnt);
  for (int i = 0; i < h + w; i++) {
    g[i].clear();
  }
  for (int i = 0; i < cnt; i++) {
    int x, y, z;
    scanf("%d %d %d", &x, &y, &z);
    x--; y--;
    g[x].push_back(make_pair(h + y, z));
    g[h + y].push_back(make_pair(x, z));
  }
  for (int i = 0; i < h + w; i++) {
    was[i] = false;
  }
  for (int i = 0; i < h + w; i++) {
    if (was[i]) {
      continue;
    }
    int b = 0, e = 1;
    x[0] = i;
    was[i] = true;
    a[i] = 0;
    while (b < e) {
      for (int j = 0; j < (int) g[x[b]].size(); j++) {
        int u = g[x[b]][j].first;
        int v = g[x[b]][j].second;
        if (was[u]) {
          if (a[x[b]] + a[u] != v) {
            puts("No");
            return 0;
          }
          continue;
        }
        x[e] = u;
        a[u] = v - a[x[b]];
        was[u] = true;
        e++;
      }
      b++;
    }
    long long m1 = inf, m2 = inf;
    for (int j = 0; j < e; j++) {
      if (x[j] < h) {
        m1 = min(m1, a[x[j]]);
