int pd;

inline int find_y(int x) {
	if(fy[x] == x) return x;
	int tmp = fy[x];
	fy[x] = find_y(tmp);
	cy[x] += cy[tmp];
	return fy[x];
}

inline int find_x(int x) {
	if(fx[x] == x) return x;
	int tmp = fx[x];
	fx[x] = find_x(fx[x]);
	cx[x] += cx[tmp];
	return fx[x];
}

inline void Link_y(int a, int b, int c) {
	int fa = find_y(a), fb = find_y(b);
	if(fa == fb) {
		if(cy[a] - cy[b] != c) 
			pd= 1;
	}
	else {
		fy[fa] = fb;
		cy[fa] = c + cy[b] - cy[a];
	}
}

inline void Link_x(int a, int b, int c) {
	int fa = find_x(a), fb = find_x(b);
	if(fa == fb) {
		if(cx[a] - cx[b] != c)
			pd = 1;
	}
	else {
		fx[fa] = fb;
		cx[fa] = c + cx[b] - cx[a];
	}
}

