  v.emplace_back(ii(y, x));
  d[y][x] = z;
 }

 bool okay = true;
 for (bool work = true; work && okay;) {
  work = false;
  for (int i = 0; i < v.size(); i++) {
   auto& u = v[i];
   int cy = u.first, cx = u.second;

   if (d[cy][cx] < 0) { okay = false; break; }

   if (check0(cy, cx) < 0) {
    okay = false;
    break;
   }

   if (check1(cy, cx)) {
    d[cy-1][cx-1] = ll(d[cy-1][cx]) + d[cy][cx-1] - d[cy][cx];
    v.emplace_back(ii(cy-1, cx-1));
    work = true;

   }

   if (check2(cy, cx)) {
    d[cy][cx-1] = ll(d[cy][cx]) + d[cy-1][cx-1] - d[cy-1][cx];
    v.emplace_back(ii(cy, cx-1));
    work = true;
   }

   if (check3(cy, cx)) {
    d[cy-1][cx+1] = ll(d[cy-1][cx]) + d[cy][cx+1] - d[cy][cx];
    v.emplace_back(ii(cy-1, cx+1));
    work = true;
   }

   if (check4(cy, cx)) {
    d[cy][cx+1] = ll(d[cy-1][cx+1]) + d[cy][cx] - d[cy-1][cx];
    v.emplace_back(ii(cy, cx+1));
    work = true;
   }

  }
 }

 if (okay) for (int i = 0; i < v.size(); i++) {
  auto& u = v[i];
  int cy = u.first, cx = u.second;

  if (d[cy][cx] < 0) { okay = false; break; }

  if (check0(cy, cx) < 0 || check9(cy, cx) < 0) {
   okay = false;
   break;
  }
 }

 puts(okay ? "Yes" : "No");
 return 0;
}

