#include<iostream>
#include<map>
using namespace std;

const int INF=1e9+8;
const int MAX_N=1e5+5;

map<int,int> data[MAX_N];
int ans[MAX_N];
int in[MAX_N][2];
int R,C;
bool f=true;
void fil(int r,int c){
	if(r>1 && ans[r-1]!=INF){
		if(data[r-1].count(c)==0){
			data[r-1][c]=ans[r-1]-data[r][c];
			if(data[r-1][c]<0)f=false;
			fil(r-1,c);
		}
		else if(data[r-1][c]-data[r][c]!=ans[r-1])f=false;
	}
	if(r<R && ans[r]!=INF){
		if(data[r+1].count(c)==0){
			data[r+1][c]=data[r][c]-ans[r];
			if(data[r+1][c]<0)f=false;
			fil(r+1,c);
		}
		else if(data[r][c]-data[r+1][c]!=ans[r])f=false;
	}
}

int main(){
	for(int i=0;i<MAX_N;i++)ans[i]=INF;
	cin>>R>>C;
	int N;
	cin>>N;
	for(int i=0;i<N;i++){
		int r,c,a;
		cin>>r>>c>>a;
		data[r][c]=a;
		if(r>1){
			if(data[r-1].count(c)==1){
				ans[r-1]=data[r-1][c]-data[r][c];
			}
		}
		in[i][0]=r;
		in[i][1]=c;
	}
	for(int i=0;i<N;i++)fil(in[i][0],in[i][1]);

	if(f)cout<<"Yes"<<endl;
	else cout<<"No"<<endl;
}

