int map[100001][100001];
int main() {
  memset(map, -1, 100001 * 100001);

  int R, C, N;

  cin >> R >> C >> N;

  for(int i = 0; i < N; i++) {
    int r, c, a;
    cin >> r >> c >> a;
    map[r - 1][c - 1] = a;
  }

  bool flag = true;
  for(int i = 0; i < R; i++) {
    for(int j = 0; j < C; j++) {
      if(map[i][j] == -1) continue;

      int n = i + 1;
      while(n < R) {
        if(map[n][j] != -1) break;
        n++;
      }
      if(map[n][j] == -1) continue;

      int m = j + 1;
      while(m < C) {
        if(map[i][m] != -1) break;
        m++;
      }
      if(map[i][m] == -1) break;

      if(map[n][m] == -1) {
        map[n][m] = map[n][j] + map[i][m] - map[i][j];
        if(map[n][m] < 0) {
          flag = false;
          break;
        }
        else {
          if(map[n][m] != map[n][j] + map[i][m] - map[i][j]) {
            flag = false;
            break;
          }
        }
      }
    }
    if(!flag) break;
  }

  if(flag) cout << "Yes" << endl;
  else cout << "No" << endl;
}

