int find(int *fa, long long *d, int x) {
	if (fa[x] == 0) return x;
	int res = find(fa, d, fa[x]);
	d[x] += d[fa[x]];
	return fa[x] = res;
}

bool no_sol = false ;

bool uni(int *fa, long long *d, int x, int y, int g) {
	//printf("%d %d %d\n", x, y, g);
	if (find(fa, d, x) == find(fa, d, y)) {
		if (d[x] - d[y] != g) {
			no_sol = true;
		}
		return false ;
	}
	fa[x] = y; d[x] = g;
}

int far[111111], fac[111111], val[111111];
vector<int> vecR[111111], vecC[111111];
long long dr[111111], dc[111111], minval_r[111111], minval_c[111111];
int R, C, n;
pair<int,int> A[111111];
int main() {
	cin >> R >> C >> n;
	For(i,1,n) {
		scanf("%d%d%d", &A[i].first, &A[i].second, &val[i]);
		vecR[A[i].first].push_back(i);
		vecC[A[i].second].push_back(i);
	}
	For(i,1,R) if (vecR[i].size() >= 2) {
		for (int j = 1; j < vecR[i].size(); ++j) {
			uni(far, dr, A[vecR[i][j - 1]].second, A[vecR[i][j]].second, val[vecR[i][j - 1]] - val[vecR[i][j]]);
		}
	}
	For(i,1,C) if (vecC[i].size() >= 2) {
		for (int j = 1; j < vecC[i].size(); ++j) {
			uni(fac, dc, A[vecC[i][j - 1]].first, A[vecC[i][j]].first, val[vecC[i][j - 1]] - val[vecC[i][j]]);
		}
	}

	For(i,1,C) {
		int t = find(far, dr, i);
		minval_r[t] = min(minval_r[t], dr[i]);
	}
	For(i,1,R) {
		int t = find(fac, dc, i);
		minval_c[t] = min(minval_c[t], dc[i]);
	}

	For(i,1,n) {
		int r = A[i].first, c = A[i].second;
		if (val[i] < dr[c] - minval_r[find(far, dr, c)]) no_sol = true;
		if (val[i] < dc[r] - minval_c[find(fac, dc, r)]) no_sol = true;
	}

	if (no_sol) puts("No"); else puts("Yes");
	return 0;
}

