void failed() {
	cout << "No" << endl;
	exit(0);
}

void dfs(int i) {
	done[i] = 1;
	tri A = v[i];
	if (dx[A.first.first] < minx) minx = dx[A.first.first];
	if (dy[A.first.second] < miny) miny = dy[A.first.second];
	for (int j : adj[i]) {
		if (done[j]) continue;
		tri B = v[j];
		if (A.first.first == B.first.first) {
			if (!vy[B.first.second]) {
				vy[B.first.second] = 1;
				dy[B.first.second] = dy[A.first.second] + B.second.second - A.second.second;
			}
			else {
				if (dy[B.first.second] != dy[A.first.second] + B.second.second - A.second.second) failed();
			}
			dfs(j);
		}
		else {
			if (!vx[B.first.first]) {
				vx[B.first.first] = 1;
				dx[B.first.first] = dx[A.first.first] + B.second.second - A.second.second;
			}
			else {
				if (dx[B.first.first] != dx[A.first.first] + B.second.second - A.second.second) failed();
			}
			dfs(j);
		}
	}
}

