#define INF (1LL<<60)
#define _1 first
#define _2 second
typedef pair<int, int> P;

int R, C, N;
vector<P> G[100000], B[100000];
int T[100000], M[100000];
vector<int> X;

bool g(int x) {
  X.push_back(x);
  for (auto &p : B[x]) {
    int u = p._1, v = T[x] + p._2;
    if (T[u] != INF && T[u] != v) return false;
    if (T[u] == INF) {
      T[u] = v;
      if (!g(u)) return false;
    }
  }
  return true;
}

bool f() {
  for (int y=0; y<R; y++) {
    sort(G[y].begin(), G[y].end());
    for (int i=1; i<G[y].size(); i++) {
      P &a = G[y][i-1], &b = G[y][i];
      B[a._1].push_back(P(b._1, b._2-a._2));
      B[b._1].push_back(P(a._1, a._2-b._2));
    }
  }
  for (int x=0; x<C; x++) T[x] = INF;
  for (int y=0; y<R; y++) {
    for (auto &p : G[y]) {
      int x = p._1;
      if (T[x] == INF) {
        X.clear();
        T[x] = 0;
        if (!g(x)) return false;
        int ma = INF, mb = INF;
        for (auto x : X) {
          mb = min(mb, T[x]);
          ma = min(ma, M[x] - T[x]);
        }
        if (ma+mb < 0) return false;
      }
    }
  }
  return true;
}

signed main() {
  cin >> R >> C >> N;
  for (int i=0; i<C; i++) M[i] = INF;
  for (int i=0; i<N; i++) {
    int r, c, a;
    cin >> r >> c >> a;
    r--, c--;
    G[r].push_back(P(c, a));
    M[c] = min(M[c], a);
  }
  if (f()) cout << "Yes\n";
  else cout << "No\n";
  return 0;
}

