int h, w;
int n;
vector<tuple<int, int, int>> input;

const int INF = 1e18;

bool solve() {
    vector<vector<pii>> hols(h);
    vector<int> mi(w, INF);

    for (auto &e : input) {
        int i, j, a;
        tie(i, j, a) = e;
        hols[i].emplace_back(j, a);
        mi[j] = min(mi[j], a);
    }

    vector<tuple<int, int, int>> diff;
    for (auto &hol : hols) {
        sort(hol.begin(), hol.end());
        for (int k = 0; k < (int)hol.size() - 1; k++) {
            int l = hol[k].first;
            int r = hol[k + 1].first;
            int d = hol[k + 1].second - hol[k].second;
            diff.emplace_back(l, r, d);
        }
    }

    sort(diff.begin(), diff.end());

    vector<int> val(w, -1);
    for (auto &t : diff) {
        int l, r, d;
        tie(l, r, d) = t;

        assert(val[l] != INF);
        assert(val[r] != INF);

        if (val[l] == -1) {
            val[l] = mi[l];
        }
        if (val[r] == -1) {
            val[r] = val[l] + d;
        }
        if (val[l] + d != val[r] || val[l] < 0 || val[r] < 0) {
            return false;
        }
    }

