using LL = long long;
constexpr LL LINF=334ll<<53;
constexpr int INF=15<<26;
constexpr LL  MOD=1E9+7;
struct UnionFind{
    vector<int> par; //par: -1*elements(root) number of par(not root)
    UnionFind(int n){par = vector<int>(n,-1);}
    int root(int x){return par[x]<0?x:(par[x]=root(par[x]));}
    void unite(int x,int y){
        x=root(x);
        y=root(y);
        if(x!=y){
            if(par[x]<par[y]) swap(x,y);
            par[y] += par[x];
            par[x] = y;
        }
    }
    bool is_par(int x){return root(x)==x;}
    bool same(int x,int y){return root(x) == root(y);}
    int size(int x){return -par[root(x)];}
};
struct Problem{
    int r,c,n;
    vector<LL> a_row,a_col;
    UnionFind uf;
    Problem(LL r, LL c):r(r),c(c),a_row(r,LINF),a_col(c,LINF),uf(r+c){};
    void impossible(){cout <<"No"<<"\n";exit(0);}
    void solve(){
        cin >> n;
        for(int i=0; i<n; ++i){
            LL rr,cc,a;
            cin >> rr >> cc >> a;
            --rr;--cc;
            if(a_row[rr] == LINF and a_col[cc] == LINF){
                a_row[rr]=0;
                a_col[cc]=a;
                uf.unite(rr,cc+r);
            }else if(a_row[rr] == LINF){
                a_row[rr]=a-a_col[cc];
                uf.unite(rr,cc+r);
            }else if(a_col[cc] == LINF){
                a_col[cc]=a-a_row[rr];
                uf.unite(rr,cc+r);
            }else{
                if(a_row[rr]+a_col[cc]!=a)impossible();
            }
        }
        vector<LL> rmin(r+c,LINF),cmin(r+c,LINF);
        for(int i=0; i<r; ++i){
            int iroot = uf.root(i);
            rmin[iroot]=min(rmin[iroot],a_row[i]);
        }
        for(int i=0; i<c; ++i){
            int iroot = uf.root(i+r);
            cmin[iroot]=min(cmin[iroot],a_col[i]);

        }
        bool ok = true;
        for(int i=0; i<r+c; ++i){
            if(rmin[i]+cmin[i]<0)ok=false;
        }


        cout << (ok?"Yes":"No")<<"\n";
    }
};

int main(){
    cin.tie(0);
    ios_base::sync_with_stdio(false);
    long long r,c=0;
    cin >> r  >> c;
    Problem p(r,c);
    p.solve();
    return 0;
}

