int R, C, N;
const int MAX_V = 200010;
vector<pair<int, i64>> adj[MAX_V];
bool used[MAX_V];
i64 weight[MAX_V];
void dfs(int cur_v, i64& minR, i64& minC) {
    used[cur_v] = true;
    for(const auto& e : adj[cur_v]) {
        int nxt_v; i64 w;
        tie(nxt_v, w) = e;
        w -= weight[cur_v];
        if(used[nxt_v]) {
            if(w != weight[nxt_v])
              minC = minR = -INF;
            continue;
        }
        weight[nxt_v] = w;
        if(nxt_v < R)
          minR = min(minR, w);
        else
          minC = min(minC, w);
        dfs(nxt_v, minR, minC);
    }
}

