        adj[r].emplace_back(c, x);
        adj[c].emplace_back(r, x);
    }
    for(int i : _in(N)) {
        if(used[i]) continue;
        i64 minR = 0LL, minC = INF;
        weight[i] = 0LL;
        dfs(i, minR, minC);
        if(minC + minR < 0LL) {
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
