using namespace std;
const int maxr = 200000;
const int oo = 1000000000;
int R,C,N;
int r[maxr+1],c[maxr+1],a[maxr+1];
int m,head[maxr*2+1],link[maxr*2+1],adj[maxr*2+1],we[maxr*2+1],wv[maxr*2+1];
int tplt;
vector<int> V[maxr*2+1];
bool visit[maxr*2+1];
void addEdge(int x,int y,int w)
{
	m++;
	link[m]=head[x];
	adj[m]=y;
	we[m]=w;
	head[x]=m;
	m++;
	link[m]=head[y];
	adj[m]=x;
	we[m]=w;
	head[y]=m;
}
void dfs(int x)
{
	V[tplt].push_back(x);
	int i=head[x];
	while (i!=0)
	{
		int y=adj[i];
		if (wv[y]==-oo)
		{
			wv[y]=we[i]-wv[x];
			dfs(y);
		}
		i=link[i];
	}
}
bool check(int x)
{
	visit[x]=true;
	int i=head[x];
	bool res=true;
	while (i!=0)
	{
		int y=adj[i];
		if (we[i]!=wv[y]+wv[x])
			res=false;
		if (!res) return res;
		if (!visit[y]) res&=check(y);
		if (!res) return res;
		i=link[i];
	}
	return res;
}
int main() 
{
	ios_base::sync_with_stdio(0);
	//freopen("input.txt","r",stdin);
	//freopen("output.txt","w",stdout);
	cin >> R >> C >> N;
	m=0;
	memset(head,0,sizeof(head));
	for (int i=1; i<=N; i++)
		{
			cin >> r[i] >> c[i] >> a[i];
			addEdge(r[i],R+c[i],a[i]);
			addEdge(R+c[i],r[i],a[i]);
		}
	for (int i=1; i<=R+C; i++)
		wv[i]=-oo;
	tplt=0;
	for (int i=1; i<=R+C; i++)
		if (wv[i]==-oo)
		{
			wv[i]=0;
			tplt++;
			V[tplt].clear();
			dfs(i);
			int min1=oo,min2=oo;
			for (auto it=V[tplt].begin(); it!=V[tplt].end(); it++)
			{
				if (*it<=R) min1=min(min1,wv[*it]);
				else
				min2=min(min2,wv[*it]);
			}
			if (min1+min2<0)
			{
				cout << "No";
				return 0;
			}
		}
	/*for (int i=1; i<=R; i++)
		cout << wv[i] << ' ';
	cout << '\n';
	for (int i=R+1; i<=R+C; i++)
		cout << wv[i] << ' ';
	cout << '\n';*/
	memset(visit,false,sizeof(visit));
	for (int i=1; i<=R+C; i++)
		if (!visit[i])
		{
			if (!check(i))
			{
				cout << "No";
				return 0;
			}
		}
	cout << "Yes";
	return 0;
}

