using namespace std;

bool check(const pair<int, int>& p, int a, map<pair<int, int>, int>& m,
           map<pair<int, int>, int>& t) {
    pair<int, int> top(p.first, p.second - 1);
    pair<int, int> tr(p.first + 1, p.second - 1);
    pair<int, int> right(p.first + 1, p.second);
    pair<int, int> br(p.first + 1, p.second + 1);
    pair<int, int> bottom(p.first, p.second + 1);
    pair<int, int> bl(p.first - 1, p.second + 1);
    pair<int, int> left(p.first - 1, p.second);
    pair<int, int> tl(p.first - 1, p.second - 1);

    if (t.count(top) && t[top] != -1 && t.count(tl) && t[tl] != -1 &&
        t.count(left) && t[left] != -1) {
        if (t[p] == -1) {
            t[p] = t[top] + t[left] - t[tl];
            if (t[p] < 0) {
                return false;
            }
        } else {
            if (t[top] + t[left] != t[tl] + t[p]) {
                return false;
            }
        }
    }

    if (t.count(top) && t[top] != -1 && t.count(tr) && t[tr] != -1 &&
        t.count(right) && t[right] != -1) {
        if (t[p] == -1) {
            t[p] = t[top] + t[right] - t[tr];
            if (t[p] < 0) {
                return false;
            }
        } else {
            if (t[top] + t[right] != t[tr] + t[p]) {
                return false;
            }
        }
    }

    if (t.count(right) && t[right] != -1 && t.count(br) && t[br] != -1 &&
        t.count(bottom) && t[bottom] != -1) {
        if (t[p] == -1) {
            t[p] = t[bottom] + t[right] - t[br];
            if (t[p] < 0) {
                return false;
            }
        } else {
            if (t[bottom] + t[right] != t[br] + t[p]) {
                return false;
            }
        }
    }

    if (t.count(bottom) && t[bottom] != -1 && t.count(bl) && t[bl] != -1 &&
        t.count(left) && t[left] != -1) {
        if (t[p] == -1) {
            t[p] = t[bottom] + t[left] - t[bl];
            if (t[p] < 0) {
                return false;
            }
        } else {
            if (t[bottom] + t[left] != t[bl] + t[p]) {
                return false;
            }
        }
    }

    return true;
}

int main() {
    int r, c;
    cin >> r >> c;
    int n;
    cin >> n;

    map<pair<int, int>, int> m;
    for (int i = 0; i < n; ++i) {
        int x, y, a;
        cin >> y >> x >> a;
        y--;
        x--;

        m[{x, y}] = a;

        for (int dx = -1; dx <= 1; ++dx) {
            for (int dy = -1; dy <= 1; ++dy) {
                if (dx == 0 && dy == 0) continue;

                m.emplace(make_pair(x + dx, y + dy), -1);
            }
        }
    }

    bool ok = true;

    map<pair<int, int>, int> t = m;
    for (auto& p : m) {
        if (!check(p.first, p.second, m, t)) {
            ok = false;
            break;
        }
    }

    cout << (ok ? "Yes" : "No") << endl;
}

#include <iostream>
#include <vector>
using namespace std;

#define INT_MAX 2000000000

typedef struct node {
  typedef struct edge {
    node *next;
    int heavy;
  } edge;
  vector<edge> edges;
  int val;
  bool checked;
  int ax;
} node;

int xmin;
int ymin;

bool check(node *v,node *bef){
  v->checked = true;
  vector<node::edge>::iterator it;
  for(it = v->edges.begin(); it != v->edges.end(); ++it){
    if((*it).next != bef){
      if((*it).next->checked){
        if(v->val + (*it).next->val != (*it).heavy){
          return false;
        }
      }else{
        (*it).next->val = (*it).heavy - v->val;
        if((*it).next->ax == 0){
          xmin = min(xmin, (*it).next->val);
        }else{
          ymin = min(ymin, (*it).next->val);
        }
        if(!check((*it).next, v)){
          return false;
        }
      }
    }
  }
  return true;
}

int main(int argc, char *argv[]){
  int R, C;
  int N;
  cin >> R >> C;
  cin >> N;
  node x[R];
  node y[C];
  int i;
  for(i=0; i<R; ++i){
    x[i].checked = false;
    x[i].ax = 0;
  }
  for(i=0; i<C; ++i){
    y[i].checked = false;
    y[i].ax = 1;
  }
  int r, c, a;
  for(i=0; i<N; ++i){
    cin >> r >> c >> a;

    node::edge e1;
    e1.next = &y[c-1];
    e1.heavy = a;
    x[r-1].edges.push_back(e1);

    node::edge e2;
    e2.next = &x[r-1];
    e2.heavy = a;
    y[c-1].edges.push_back(e2);
  }
  for(i=0; i<R; ++i){
    if(!x[i].checked){
      if(x[i].edges.size() > 0){
        x[i].val = 0;
        xmin = 0;
        ymin = INT_MAX;
        if(check(&x[i], NULL)){
          if(xmin + ymin < 0){
            cout << "No" << endl;
            return 0;
          }
        }else{
          cout << "No" << endl;
          return 0;
        }
      }
    }
  }
  cout << "Yes" << endl;
  return 0;
}

#include<cstdio>
