using namespace std;

const int INF=1e9;
const int N=100010;
struct node{
	int x,y,a;
};
node po[N];
int n,m,nn,h[N][2],minn[2];   

int cmp(const node &a,const node &b)
{
	if (a.x!=b.x) return a.x<b.x;
	else return a.y<b.y;
}

int pd()
{
	memset(h,-1,sizeof(h));
	int i=1,hh=po[1].x,d;
	int now=0;
	minn[now]=INF;
	while (po[i].x==hh) 
	{
		if (po[i].a<0) return 0;
		h[po[i].y][now]=po[i].a;
		minn[now]=min(minn[now],po[i].a);
		i++;
	}
	while(i<=nn)
	{
		hh=po[i].x;
		d=-1; now^=1;
	    for (int j=1;j<=m;j++) h[j][now]=-1;
		minn[now]=INF;   //这一行中的最小值 
		while (po[i].x==hh)
		{
			if (po[i].a<0) return 0;
			if (h[po[i].y][now^1]!=-1)  //上一行这里有数 
			{
				if (d==-1)   //第一次相等 
				{
					d=po[i].a-h[po[i].y][now^1];
			        h[po[i].y][now]=po[i].a;
					minn[now]=min(minn[now],po[i].a); 
			        if (minn[now]-d<0||minn[now^1]+d<0) return 0;   //非负整数
				}
				else
				{
					if (po[i].a-h[po[i].y][now^1]!=d) return 0;
					minn[now]=min(minn[now],po[i].a); 
					h[po[i].y][now]=po[i].a;
				}
			}
			else
			{
				h[po[i].y][now]=po[i].a;
				minn[now]=min(minn[now],po[i].a);
				if (d!=INF)
				    if (minn[now]-d<0) return 0;
			}
			i++;
		}
	} 
	return 1;
}

int main()
{
//	freopen("then.in","r",stdin);
//    freopen("then.out","w",stdout);
	int T;
	//canf("%d",&T);
	T=1;
	while (T--)
	{
		scanf("%d%d%d",&n,&m,&nn);
		for (int i=1;i<=nn;i++)
		    scanf("%d%d%d",&po[i].x,&po[i].y,&po[i].a);
		sort(po+1,po+1+nn,cmp);
		if (pd()) printf("Yes\n");
		else printf("No\n");
	}
}

