void exit_ng()
{
	cout << "No" << endl;
	exit( 0 );
}

int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	int H, W;
	scanf( "%d%d", &H, &W );

	int N;
	scanf( "%d", &N );

	map< PII, int > filled;
	REP( _, N )
	{
		int y, x, a;
		scanf( "%d%d%d", &y, &x, &a );
		filled[ MP( y - 1, x - 1 ) ] = a;
	}

	VI ds_hor( H, -1 ), ds_var( W, -1 );
	FOR( p, filled )
	{
		const int y = p.fst.fst;
		const int x = p.fst.snd;
		const int a = p.snd;

		if ( y + 1 < H && EXIST( filled, MP( y + 1, x ) ) )
		{
			const int d = filled[ MP( y + 1, x ) ] - a;
			if ( ds_hor[y] != -1 && ds_hor[y] != d )
			{
				exit_ng();
			}
			ds_hor[y] = d;
		}
		if ( x + 1 < W && EXIST( filled, MP( y, x + 1 ) ) )
		{
			const int d = filled[ MP( y, x + 1 ) ] - a;
			if ( ds_var[x] != -1 && ds_var[x] != d )
			{
				exit_ng();
			}
			ds_var[x] = d;
		}
	}

	FOR( p, filled )
	{
		const int y = p.fst.fst;
		const int x = p.fst.snd;
		const int a = p.snd;

		if ( ds_hor[y] != -1 &&
				( 0 <= y - 1 && a - ds_hor[y] < 0 || y + 1 < H && a + ds_hor[y] < 0 ) ||
				ds_var[x] != -1 &&
				( 0 <= x - 1 && a - ds_var[x] < 0 || x + 1 < W && a + ds_var[x] < 0 ) )
		{
			exit_ng();
		}
	}

	cout << "Yes" << endl;

	return 0;
}

