#define int long long
#define INF (1LL<<60)
#define _1 first
#define _2 second
typedef pair<int, int> P;

int R, C, N;
vector<P> G[100000], B[100000];
int T[100000];

bool g(int x) {
  for (auto &p : B[x]) {
    int u = p._1, v = T[x] + p._2;
    if (T[u] != INF && T[u] != v) return false;
    if (T[u] == INF) {
      T[u] = v;
      if (!g(u)) return false;
    }
  }
  return true;
}

bool f() {
  for (int y=0; y<R; y++) {
    sort(G[y].begin(), G[y].end());
    P &a = G[y][0];
    for (int i=1; i<G[y].size(); i++) {
      P &b = G[y][i];
      B[a._1].push_back(P(b._1, b._2-a._2));
    }
  }
  for (int x=0; x<C; x++) T[x] = INF;
  T[0] = 0;
  if (!g(0)) return false;
  int ma = INF, mb = INF;
  for (int x=0; x<C; x++) mb = min(mb, T[x]);
  for (int y=0; y<R; y++) {
    if (!G[y].empty()) ma = min(ma, G[y][0]._2 - T[G[y][0]._1]);
  }
  return ma+mb >= 0;
}

signed main() {
  cin >> R >> C >> N;
  for (int i=0; i<N; i++) {
    int r, c, a;
    cin >> r >> c >> a;
    r--, c--;
    G[r].push_back(P(c, a));
  }
  if (f()) cout << "Yes\n";
  else cout << "No\n";
  return 0;
}

