bool inside(int a,int b,int c,int d){
	return 0<=a&&a<c&&0<=b&&b<d;
}


bool check(int y,int x){
	int cnt = 0;
	rep(i,2){
		rep(j,2){
			if(vv[y+i][x+j] == -1) cnt++,pos=pii(y+i,x+j);
		}
	}
	tmp = -1;
	if(cnt == 1){
		if(vv[y][x] == -1 || vv[y+1][x+1] == -1){
			if(vv[y+1][x] + vv[y][x+1] - (vv[y][x] + vv[y+1][x+1] + 1) < 0)
				return false;
			else
				tmp = vv[y+1][x] + vv[y][x+1] - (vv[y][x] + vv[y+1][x+1] + 1);
		}
		else{
			if(vv[y+1][x+1] + vv[y+1][x+1] - (vv[y+1][x] + vv[y][x+1] + 1) < 0)
				return false;
			else
				tmp = vv[y+1][x+1] + vv[y+1][x+1] - (vv[y+1][x] + vv[y][x+1] + 1);
		}
	}
	else if(cnt == 0){
		if(vv[y][x] + vv[y+1][x+1] != vv[y+1][x] + vv[y][x+1]){
			return false;
		}
	}
	return true;
}

void mainmain(){
	int H,W;
	cin>>H>>W;
	int n;
	cin>>n;
	// assert(H < 1000 && W < 1000);
	vector<pii> next;
	rep(i,n){
		int a,b,c;
		cin>>a>>b>>c;
		a--,b--;
		ma[mkp(a,b)] = c;
		int dd[] = {0,1,0,-1,0};
		rep(j,4){
			next.PB(pii(a+dd[j],b+dd[j+1]));
		}
	}
	rep(o,next.size()){
		int y = next[o].F;
		int x = next[o].S;
		if(!inside(y,x,H,W)) continue;
		if(used.find(mkp(y,x)) != used.end()) continue;
		used.insert(mkp(y,x));
		rep(i,3) rep(j,3){
			int yy = y+i-1;
			int xx = x+j-1;			
			if(inside(yy,xx,H,W)){
				if(ma.count(mkp(yy,xx))) vv[i][j] = ma[mkp(yy,xx)];
				else vv[i][j] = -1;
			}
		}
		vll v;
		rep(i,2){
			rep(j,2){
				if(y + i - 1 < 0) continue;
				if(y + i >= H) continue;
				if(x + j - 1 < 0) continue;
				if(x + j >= W) continue;
				if(!check(i,j)){
					cout<<"No"<<endl;
					return;
				}
				else{
					if(tmp >= 0 && pos == pii(1,1)){
						v.PB(tmp);
					}
				}
			}
		}
		sort(ALL(v));
		if(v.size()){
			if(v[0] != v.back()){
				cout<<"No"<<endl;
				return;
			}
			else{
				int dd[] = {0,1,0,-1,0};
				rep(j,4){
					next.PB(mkp(y+dd[j],x+dd[j+1]));
				}
				ma[mkp(y,x)] = v[0];
			}
		}
	}
	cout<<"Yes"<<endl;
}


