struct edge{int to,cost;};
struct st{int pos,num;};
#define MAX_V 100000
int r,c;

vector<edge> G[100000];

int f=false;



void dfs(int cur, int d[MAX_V],map<piii,bool> &used){
	for(auto &e : G[cur]){
		int from=cur, to=e.to;
		if( used.count(make_pair( from,pii(to,e.cost) ))==0 ){
			used[make_pair( from,pii(to,e.cost) )]=true;
			if(d[to]==INF){
				d[to] = d[cur]+e.cost;
				if()
				dfs(to,d,used);
			}else {
				if(d[to] != d[cur]+e.cost)f=true;
			}
		}
	}
}


void solve(vector<pii> inp[100000]){
	rep(i,r)sort(all(inp[i]));

	vector<int> less(MAX_V,INF);
	rep(i,r){
		rep(j,inp[i].size()-1){
			int from = inp[i][j].first;
			int to = inp[i][j+1].first;
			less[from] = min(less[from],inp[i][j].second);
			if(j==inp[i].size()-1)	less[from] = min(less[from],inp[i][j].second);
			G[from].pb(edge{to  ,inp[i][j+1].second-inp[i][j].second});
			G[to  ].pb(edge{from,-(inp[i][j+1].second-inp[i][j].second)});
		}
	}

	int d[MAX_V];
	map<piii,bool> used;
	rep(i,MAX_V)d[i] = INF;
	rep(i,MAX_V){
		if(d[i]==INF){
			dfs((int)i,d,used);
		}
	}
}




int main(){
	cin>>r>>c;
	int n;
	cin>>n;
	vector<pii> inpy[MAX_V];
	vector<pii> inpx[MAX_V];
	rep(i,n){
		int y,x,a;
		cin>>y>>x>>a;
		y--,x--;
		inpy[y].pb(pii(x,a));
		inpx[x].pb(pii(y,a));
	}



	solve(inpy);
	rep(i,r)G[i].clear();
	solve(inpx);

	if(f)cout<<"No"<<endl;
	else cout<<"Yes"<<endl;





}

