using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;

int R,C,N;
int r[100001],c[100001];
ll a[100001];
vector<P> xid[100001],yid[100001];
vector<P> xlimit[100001];
vector<P> ylimit[100001];
ll mini[100001],mini2[100001];

bool checked[100001];
ll dist[100001];
bool flag=true;
vector<int> route;
ll dmini;
void dfs(int v,ll s){
	dist[v]=s;
	checked[v]=true;
	dmini=min(dmini,dist[v]);
	route.push_back(v);
	for(int i=0;i<xlimit[v].size();i++){
		P p=xlimit[v][i];
		if(!checked[p.first]){
			dfs(p.first,s+p.second);
		}else if(dist[v]+p.second!=dist[p.first])flag=false;
	}
}

void dfs2(int v,ll s){
	dist[v]=s;
	checked[v]=true;
	for(int i=0;i<ylimit[v].size();i++){
		P p=ylimit[v][i];
		if(!checked[p.first]){
			dfs2(p.first,s+p.second);
		}else if(dist[v]+p.second!=dist[p.first])flag=false;
	}
}

int main(void){
	scanf("%d%d%d",&R,&C,&N);
	for(int i=0;i<max(C,R);i++){
		mini[i]=INF;
		mini2[i]=INF;
	}
	for(int i=0;i<N;i++){
		scanf("%d%d%lld",&r[i],&c[i],&a[i]);
		r[i]--;
		c[i]--;
		xid[r[i]].push_back(P(c[i],a[i]));
		yid[c[i]].push_back(P(r[i],a[i]));
		mini[c[i]]=min(mini[c[i]],a[i]);
		mini2[r[i]]=min(mini2[r[i]],a[i]);
	}

	for(int i=0;i<R;i++){
		if(xid[i].size()<=1)continue;
		int f=xid[i][0].first;
		for(int j=1;j<xid[i].size();j++){
			int t=xid[i][j].first;
			ll c=xid[i][0].second-xid[i][j].second;
			xlimit[f].push_back(P(t,-c));
			xlimit[t].push_back(P(f,c));
			if(mini[f]-c<0)flag=false;
			if(mini[t]+c<0)flag=false;
		}
	}
	for(int i=0;i<C;i++){
		if(yid[i].size()<=1)continue;
		int f=yid[i][0].first;
		for(int j=1;j<yid[i].size();j++){
			int t=yid[i][j].first;
			ll c=yid[i][0].second-yid[i][j].second;
			ylimit[f].push_back(P(t,-c));
			ylimit[t].push_back(P(f,c));
			if(mini2[f]-c<0)flag=false;
			if(mini2[t]+c<0)flag=false;
		}
	}

	for(int i=0;i<R;i++){
		if(!checked[i]){
			dmini=INF;
			dfs(i,0);
			for(int j=0;j<route.size();j++){
				if(mini[route[j]]-(dist[route[j]]-dmini)<0)flag=false;
			}
			route.clear();
		}
	}
	memset(checked,false,sizeof(checked));
	memset(dist,0,sizeof(dist));
	for(int i=0;i<C;i++){
		if(!checked[i]){
			dmini=INF;
			dfs2(i,0);
			for(int j=0;j<route.size();j++){
				if(mini[route[j]]-(dist[route[j]]-dmini)<0)flag=false;
			}
			route.clear();
	}
	printf("%s\n",flag?"Yes":"No");
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define int long long

void sayno(){
	cout << "No" << endl;
	exit(0);
}

long long RR,CC;


map<int,int> xinc,yinc;
map< pair<int,int> ,int> checked;


void dfs(int y,int x,int v){
	if( checked.count({y,x}) ){
		if( checked[{y,x}] != v ) sayno();
		return;
	}
	if( v < 0 ){
		sayno();
	}
	checked[{y,x}] = v;
	if( xinc.count(x) ) dfs(y,x+1, v + xinc[x]);
	if( yinc.count(y) ) dfs(y+1,x, v + yinc[y]);

}
void solve(long long R, long long C, long long N, vector<long long> r, vector<long long> c, vector<long long> a){
	RR = R;
	CC = C;

	map< pair<int,int> , int> mass;
	for(int i = 0 ; i < r.size() ; i++){
		mass[{r[i],c[i]}] = a[i];
	}
	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		pair<int,int> rig = {y,x+1};
		pair<int,int> dow = {y+1,x};

		if( mass.count(rig) ){
			int diff = mass[rig] - p.second;
			if( xinc.count(x) and xinc[x] != diff ) sayno();
			xinc[x] = diff;
		}

		if( mass.count(dow) ){
			int diff = mass[dow] - p.second;
			if( yinc.count(y) and yinc[y] != diff ) sayno();
			yinc[y] = diff;
		}
	}

	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		int v = p.second;
		dfs(y,x,v);
	}
	cout << "Yes" << endl;



}



