          int x = ty[y][j], c = cy[y][j];
          ll ns = c-sy[y];
          if (sx[x] == LINF) {
            sx[x] = ns;
            mins(lx,ns);
            qx.push(x);
          } else {
            if (sx[x] != ns) {
              puts("No");
              return 0;
            }
          }
        }
      }
    }
    if (lx+ly < 0) {
