#include <iostream>
#include <map>
using namespace std;

int R, C, N;
map<pair<int, int>, int> grid;

bool validate(int r, int c)
{
    int cnt = 0, cell[4] = {-1, -1, -1, -1};

    for (int i = 0; i < 4; i++) {
        auto it = grid.find(make_pair(r + (i >> 1), c + (i & 1)));
        if (it != grid.end()) {
            cell[i] = it->second;
            cnt++;
        }
    }

    if (cnt == 3) {
        if (cell[0] == -1) {
            if (cell[1] + cell[2] < cell[3])
                return false;
            else
                grid.insert(make_pair(make_pair(r, c), cell[1] + cell[2] - cell[3]));
        } else if (cell[1] == -1) {
            if (cell[0] + cell[3] < cell[2])
                return false;
            else
                grid.insert(make_pair(make_pair(r, c + 1), cell[0] + cell[3] - cell[2]));
        } else if (cell[2] == -1) {
            if (cell[0] + cell[3] < cell[1])
                return false;
            else
                grid.insert(make_pair(make_pair(r + 1, c), cell[0] + cell[3] - cell[1]));
        } else if (cell[3] == -1) {
            if (cell[1] + cell[2] < cell[0])
                return false;
            else
                grid.insert(make_pair(make_pair(r + 1, c + 1), cell[1] + cell[2] - cell[0]));
        }
    } else if (cnt == 4) {
        if (cell[0] + cell[3] != cell[1] + cell[2])
            return false;
    }

    return true;
}

bool run(void)
{
    int a, b, c;
    pair<int, int> p;

    cin >> R >> C >> N;
    for (int i = 0; i < N; i++) {
        cin >> a >> b >> c;
        grid.insert(make_pair(make_pair(a, b), c));
    }

    for (auto it = grid.begin(); it != grid.end(); it++) {
        p = it->first;
        for (int i = max(1, p.first - 1); i < min(R, p.first + 1); i++)
            for (int j = max(1, p.second - 1); j < min(C, p.second + 1); j++)
                if (!validate(i, j))
                    return false;
    }

    for (auto it = grid.begin(); it != grid.end(); it++) {
        p = it->first;
        for (int i = max(1, p.first - 1); i < min(R, p.first + 1); i++)
            for (int j = max(1, p.second - 1); j < min(C, p.second + 1); j++)
                if (!validate(i, j))
                    return false;
    }

    return true;
}

int main(void)
{
    if (run())
        cout << "Yes" << endl;
    else
        cout << "No" << endl;
}

