int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int h, w;
    cin >> h >> w;
    int n;
    cin >> n;
    vector<vector<P>> v(h + 10);
    vector<vector<edge>> G(w + 10);
    vector<ll> mi(w + 10, LINF);
    for(int i = 0; i < n; i++) {
        ll r, c, a;
        cin >> r >> c >> a;
        v[r].push_back(P(c, a));
        chmin(mi[c], a);
    }
    for(int i = 1; i <= h; i++) {
        if(v[i].size() <= 1) {
            continue;
        }
        sort(all(v[i]));
        for(int j = 1; j < v[i].size(); j++) {
            G[v[i][j - 1].first].push_back(
                {v[i][j].first, v[i][j].second - v[i][j - 1].second});
        }
    }
    vector<ll> d(w + 10, LINF), st(w + 10, -1);
    priority_queue<P, vector<P>, greater<P>> q;
    for(int i = 1; i <= w; i++) {
        if(G[i].size() >= 1 && d[i] == LINF) {
            d[i] = 0;
            q.push(P(d[i], i));
            while(!q.empty()) {
                int vv = q.top().second;
                q.pop();
                for(auto e : G[vv]) {
                    if(chmin(d[e.to], d[vv] + e.cost)) {
                        st[e.to] = i;
                        q.push(P(d[e.to], e.to));
                    }
                }
            }
        }
    }
    bool f = true;
    for(int i = 1; i <= w; i++) {
        if(d[i] == LINF) {
            continue;
        }
        if(mi[st[i]] + d[i] < 0) {
            f = false;
        }
        if(mi[i] - d[i] < 0) {
            f = false;
        }
        for(auto e : G[i]) {
            if(d[e.to] - d[i] != e.cost) {
                f = false;
            }
        }
    }
    if(f) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
}

