int R, C, N;
int MX[100010];

struct edge {
	int to, cost;
	edge(){}
	edge(int to, int cost) : to(to), cost(cost) {}
};

ll d[100010];

int r[100010], c[100010], A[100010];
vector<edge> g[100010];
vector<int> vec[100010];
vector<pii> v2[100010];
int in[100010];

bool dijk()
{
	using P = pair<ll, int>;
	priority_queue<P, vector<P>, greater<P> > que;

	rep(i, C) d[i] = LLONG_MAX;

	rep(i, C) if (!in[i]) {
		que.push(mp(0LL, i));
		d[i] = 0;
	}

	while (!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.se;
		if (p.fi > d[v]) continue;
		for (edge e : g[v]) {
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(mp(d[e.to], e.to));
			}
		}
	}

	rep(i, C) if (d[i] > MX[i]) return false;
	rep(i, R) {
		rep(j, (int)vec[i].size()-1) {
			int ii = vec[i][j], jj = vec[i][j+1];
			if (A[ii]-A[jj] != d[c[ii]]-d[c[jj]]) return false;
		}
	}
	return true;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cin >> R >> C >> N;
	rep(i, C) MX[i] = INT_MAX;

	rep(i, N) {
		cin >> r[i] >> c[i] >> A[i];
		--r[i]; --c[i];
		MX[c[i]] = min(MX[c[i]], A[i]);
		vec[r[i]].pb(i);
		v2[r[i]].eb(mp(A[i], i));
	}

	rep(i, R) {
		sort(ALL(v2[i]));
		rep(j, v2[i].size()) vec[i][j] = v2[i][j].se;

		rep(j, (int)vec[i].size()-1) {
			int ii = vec[i][j], jj = vec[i][j+1];
			//if (A[ii] > A[jj]) swap(ii, jj);
			g[c[ii]].eb(c[jj], A[jj]-A[ii]);
			++in[c[jj]];
		}
	}
	if (dijk()) puts("Yes");
	else puts("No");

	return 0;
}

