int R, C, N;
static ll a[131072], r[131072], c[131072];
static int par[131072];
static ll diff[131072];
static vector<pair<pair<int, int> , ll> > v;

ll tmp;
int parent(int x){
	while(1){
		int p = par[x];
		if (p == x) return p;
		tmp += diff[x];
		x = p;
	}
}

int main(void){
	srand(time(NULL));
	cin >> R >> C >> N;
	for(int i=0;i<N;i++) cin >> r[i] >> c[i] >> a[i];

	for(int i=0;i<N;i++) v.pb(mp(mp(r[i]-1,c[i]-1),a[i]));
	sort(v.begin(), v.end());

	for(int i=0;i<C;i++) {par[i] = i;}
	for(int i=0;i+1<N;i++){
		if (v[i].first.first==v[i+1].first.first){
			tmp = v[i].second;
			int p1 = parent(v[i].first.second);
			par[v[i].first.second] = p1;
			diff[v[i].first.second] = tmp - v[i].second;

			ll tmp2 = tmp;

			tmp = v[i+1].second;
			int p2 = parent(v[i+1].first.second);
			par[v[i+1].first.second] = p2;
			diff[v[i+1].first.second] = tmp - v[i+1].second;			


			if (p1==p2){
				if (tmp!=tmp2){
					cout << "No" << endl;
					return 0;
				}
			}else{
				if (rand()%2){
					par[p1] = p2;
					diff[p1] = tmp - tmp2;
				}else{
					par[p2] = p1;
					diff[p2] = tmp2 - tmp;
				}
			}
		}
	}

	ll lb[C] = {0};
	for(int i=0;i<C;i++){
		tmp = 0;
		int p = parent(i);
		//cout << "i=" << i << " " << p << " " << tmp << endl;
		lb[p] = max(lb[p], tmp);
	}
	//cout << endl;
	//for(int i=0;i<C;i++) cout << lb[i] << " ";
	//cout << endl;

	for(int i=0;i<N;i++){
		tmp = v[i].second;
		int p = parent(i);
		if (tmp < lb[p]){
			cout << "No" << endl;
			return 0;
		}
	}
	cout << "Yes" << endl;

	return 0;
}

