vector<pair<LL , LL> > cols[100005];
LL p[100005];
LL rowMin[100005];
LL value[100005];
LL R , C , n;
vector<int> values[100005];
int find(int u)
{
	if(u == p[u])
		return u;
	return p[u] = find(p[u]);
}
void init()
{
	for(LL i = 1; i <= R; i++)
	{
		p[i] = i;
		values[i].PB(i);
	}
}
int main()
{
	ios_base::sync_with_stdio(0);

	cin >> R >> C >> n;
	for(LL i = 0; i < n; i++)
		rowMin[i] = INF * (LL) INF;

	for(LL i = 0; i < n; i++)
	{
		LL r , c , a;
		cin >> r >> c >> a;
		rowMin[r] = min(rowMin[r] , a);
		cols[c].PB({r , a});
	}
	init();
	for(LL i = 1; i <= C; i++)
	{
		sort(cols[i].begin() , cols[i].end());

		for(LL j = 1; j < cols[i].size(); j++)	
		{
			LL diff = cols[i][j].Y - cols[i][j - 1].Y;
			int u = find(cols[i][j].X) , v = find(cols[i][j - 1].X);
			LL oldDiff = value[cols[i][j].X] - value[cols[i][j - 1].X];
			if(values[u].size() < values[v].size())
			{
				oldDiff = -oldDiff;
				swap(u , v);
				diff = -diff;
			}

			if(u == v && oldDiff != diff)
			{
				cout << "No" << endl;
				return 0;
			}

			LL newDiff = oldDiff + diff;
			if(u != v)
			{
				for(auto x : values[v])
				{
					values[u].PB(x);
					value[x] += newDiff;
				}
				p[v] = u;
			}
		}
	}
	for(int i = 1; i <= R; i++)
	{
		if(p[i] == i)
		{
			LL minima = INF * (LL)INF;
			for(auto x : values[i])
				minima = min(minima , value[x]);
			for(auto x : values[i])
			{
				if(value[x] - minima > rowMin[x])
				{
					cout << "No" << endl;
					return 0;
				}
			}
		}
	}


	cout << "Yes" << endl;
	return 0;
}

