typedef long long ll;
typedef pair<int, int> P;
#define X first
#define Y second

const int MAX = 1<<17;

P root[MAX];

P Find(int x)
{
  if (root[x].X == x)
    return P(x, 0);
  P tmp = Find(root[x].X);
  tmp.Y += root[x].Y;
  return root[x] = tmp;
}

int Merge(int a, int b, ll raz) //a - b
{
  if (rand() % 2) {
    swap(a, b);
    raz = -raz;
  }

  P ta = Find(a);
  P tb = Find(b);

  if (ta.X == tb.X)
    return (ta.Y - tb.Y) == raz;

  root[b] = P(ta.X, ta.Y - tb.Y - raz);

  return 1;
}

pair <P, int> p[MAX];

