  int rje = 1;
  for (int st=0; st<2; st++) {
    sort(p, p + n);
    for (int i=0; i<MAX; i++)
      root[i] = P(i, 0);

    for (int i=1; i<n; i++)
      if (p[i].X.X == p[i-1].X.X)
        rje &= Merge(p[i].X.Y, p[i-1].X.Y, p[i].Y - p[i-1].Y);

    for (int i=0; i<n; i++)
      swap(p[i].X.X, p[i].X.Y);
  }

  printf("%s\n", rje ? "Yes" : "No");

