		ri = lower_bound(ALL(vr), ri) - vr.begin();
		ci = lower_bound(ALL(vc), ci) - vc.begin();
		a[i] = make_tuple(ri, ci, ai);
	}
	auto ac = a;
	sort(ALL(a));
	sort(ALL(ac), [](const ti3 &a, const ti3 &b) {return (get<1>(a) == get<1>(b)) ? (get<0>(a) < get<0>(b)) : (get<1>(a) < get<1>(b)); });
	vi dr(vr.size(),INF), dc(vc.size(),INF);
	uset<int> used;
	for (auto &x : ac) {
		if (!used.insert(get<0>(x)).second)continue;
		auto lit = lower_bound(ALL(a), make_tuple(get<0>(x) + 1, 0, 0));
		auto it = lower_bound(ALL(a), x);
		int p1 = get<1>(*it);
		if (dc[p1] == INF)dc[p1] = 0;
		int as = get<2>(*it);
		for (it++; it != lit; it++) {
			int p2 = get<1>(*it);
			if (dc[p2] == INF)dc[p2] = get<2>(*it) - as;
			else if (dc[p2] != get<2>(*it) - as) {
