				return 0;
			}
		}
	}
	used.erase(ALL(used));
	for (auto &x : a) {
		if (!used.insert(get<1>(x)).second)continue;
		auto lit = lower_bound(ALL(ac), make_tuple(0,get<1>(x) + 1, 0), [](const ti3 &a, const ti3 &b) {return (get<1>(a) == get<1>(b)) ? (get<0>(a) < get<0>(b)) : (get<1>(a) < get<1>(b)); });
		auto it = lower_bound(ALL(ac), x, [](const ti3 &a, const ti3 &b) {return (get<1>(a) == get<1>(b)) ? (get<0>(a) < get<0>(b)) : (get<1>(a) < get<1>(b)); });
		int p1 = get<1>(*it);
		if (dr[p1] == INF)dr[p1] = 0;
		int as = get<2>(*it);
		for (it++; it != lit; it++) {
			int p2 = get<0>(*it);
			if (dr[p2] == INF)dr[p2] = get<2>(*it) - as;
			else if (dr[p2] != get<2>(*it) - as) {
				cout << "No" << endl;
				return 0;
			}
		}
	}
	int m;
	int min = INF;
	rep(i, dr.size()) {
		if (dr[i] < min)min = dr[i], m = i;
	}
	for (auto&x : a) {
		if (min - dr[get<0>(x)] + get<2>(x) < 0) {
