map<pair<int, int>, long long> g;

void fail() {
	printf("No\n");

	exit(0);
}

void add(int x, int y, long long val);

void checkSquare(int x, int y) {
	int cnt = 0;
	cnt += g.count(make_pair(x, y));
	cnt += g.count(make_pair(x + 1, y));
	cnt += g.count(make_pair(x, y + 1));
	cnt += g.count(make_pair(x + 1, y + 1));

	if (cnt == 4) {
		long long A = g[make_pair(x, y)] + g[make_pair(x + 1, y + 1)];
		long long B = g[make_pair(x + 1, y)] + g[make_pair(x, y + 1)];

		if (A != B) fail();
	}
	else if (cnt == 3) {
		if (g.count(make_pair(x, y)) == 0) {
			long long A = g[make_pair(x + 1, y + 1)];
			long long B = g[make_pair(x + 1, y)] + g[make_pair(x, y + 1)];

			add(x, y, B - A);
		}
		else if (g.count(make_pair(x + 1, y + 1)) == 0) {
			long long A = g[make_pair(x, y)];
			long long B = g[make_pair(x + 1, y)] + g[make_pair(x, y + 1)];

			add(x + 1, y + 1, B - A);
		}
		else if (g.count(make_pair(x, y + 1)) == 0) {
			long long A = g[make_pair(x, y)] + g[make_pair(x + 1, y + 1)];
			long long B = g[make_pair(x + 1, y)];

			add(x, y + 1, A - B);
		}
		else {
			long long A = g[make_pair(x, y)] + g[make_pair(x + 1, y + 1)];
			long long B = g[make_pair(x, y + 1)];

			add(x + 1, y, A - B);
		}
	}
}

void add(int x, int y, long long val) {
	if (val < 0) fail();

	auto p = make_pair(x, y);
	if (g.count(p) == 1) {
		if (g[p] != val) fail();

		return;
	}

	g[p] = val;

	checkSquare(x, y);
	checkSquare(x, y - 1);
	checkSquare(x - 1, y);
	checkSquare(x - 1, y - 1);
}

