		{
			q.push(i);
			done[i] = 1;
		}
	}
	while(q.size() && !bad)
	{
		int i = q.front();
		q.pop();
		done[i] = true;
		if(mark[row[i]][0] && mark[0][col[i]])
		{
			if(a[row[i]][0] + a[0][col[i]] != val[i])
