struct UF{
	int par[200010];
	void init(){
		rep(i,200010){
			par[i] = i;
		}
	}
	int find(int x){
		if(par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	bool same(int x,int y){
		return find(x) == find(y);
	}
	void unit(int x,int y){
		if(same(x,y))return;
		x = find(x);
		y = find(y);
		if(x > y){
			par[x] = y;
		}
		else {
			par[y] = x;
		}
	}
}uf;

ll R,C,N;
vector<P> G[200010];
ll x[200010];

P solve(int v){
	P ret = P(INF,INF);
	if(v <= R)ret.fr = x[v];
	else ret.sc = x[v];
	rep(i,G[v].size()){
		P ed = G[v][i];
		if(x[ed.fr] != -INF){
			if(x[ed.fr]+x[v] != ed.sc)return P(-INF,-INF);
		}
		else {
			x[ed.fr] = ed.sc-x[v];
			P p = solve(ed.fr);
			ret.fr = min ( ret.fr , p.fr );
			ret.sc = min ( ret.sc , p.sc );
		}
	}
	return ret;
}

