using namespace std;

const int LIM = 1e+5 + 100;

vector<map<int, long long>> vm(LIM);
vector<map<int, long long>> vt(LIM);

vector<int> a(LIM);
vector<bool> used(LIM, false);
vector<bool> used_c(LIM, false);
vector<int> setted(LIM, false);

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int r, c, n;
  cin >> r >> c >> n;

  for (int i = 0; i < n; ++i) {
    int ii, jj, val;
    cin >> ii >> jj >> val;
    --ii;
    --jj;
    vm[ii][jj] = val;
    vt[jj][ii] = val;
  }

  bool ok = true;
  for (int row = 0; row < r; ++row) {
    if (used[row])
      continue;
    long long min_diff = 0;
    long long max_diff = 0;

    used[row] = true;
    queue<int> current;
    current.push(row);
    queue<int> q;

    for (const pair<int, int>& p : vm[row]) {
      a[p.first] = p.second;
      used_c[p.first] = true;
      setted[p.first] = true;
      q.push(p.first);
    }

    while (!q.empty()) {
      int col = q.front();
      q.pop();
      current.push(col);

      for (const pair<int, int>& p : vt[col]) {
        int row = p.first;
        if (used[row])
          continue;
        used[row] = true;

        long long diff = 0;
        for (const pair<int, int>& pp : vm[row]) {
          if (setted[pp.first]) {
            diff = pp.second - a[pp.first];
          }
        }

        for (const pair<int, int>& pp : vm[row]) {
          if (setted[pp.first] && pp.second - diff != a[pp.first])
            ok = false;
          if (!setted[pp.first]) {
            a[pp.first] = pp.second - diff;
            setted[pp.first] = true;
          }

          if (!used_c[pp.first]) {
            q.push(pp.first);
            used_c[pp.first] = true;
          }
        }

        min_diff = min(min_diff, diff);
        max_diff = max(max_diff, diff);
      }
    }

    while (!current.empty()) {
      long long x = a[current.front()];
      current.pop();
      if (x + min_diff < 0 || x + max_diff < 0)
        ok = false;
    }
  }

  if (!ok)
    cout << "No" << endl;
  else
    cout << "Yes" << endl;

  return 0;
}

