const ll inf= 5e15;

bool check(const vvec<pll> &lines) {
    vec<ll> mind(1e5 + 10, inf);
    std::map<pll, ll> diff;
    for (auto &&line : lines) {
        if (line.size() < 2) continue;
        ll minv = line.back().second;
        for (ll i = (ll)(line.size()) - 2; 0 <= i; i--) {
            ll i1, i2, v1, v2;
            std::tie(i1, v1) = line[i];
            std::tie(i2, v2) = line[i + 1];
            pll key(i1, i2);
            ll d = v2 - v1;
            auto ite = diff.find(key);
            if (ite != diff.end() && ite->second != d) return false;
            diff[key] = d;
            chmin(mind[i1], minv - v1);
            chmin(minv, v1);
        }
    }

    for (auto &&line : lines) for (auto &&e : line) {
        ll idx, v;
        std::tie(idx, v) = e;
        if (v + mind[idx] < 0) return false;
    }

    return true;
}

bool solve() {
    ll r, c, n;
    std::cin >> r >> c >> n;
    vvec<pll> rows(r), cols(c);
    for (ll i = 0; i < n; i++) {
        ll ri, ci, a;
        std::cin >> ri >> ci >> a;
        ri--; ci--;
        rows[ri].emplace_back(ci, a);
        cols[ci].emplace_back(ri, a);
    }

    for (auto &&v : rows) std::sort(ALL(v));
    for (auto &&v : cols) std::sort(ALL(v));

    if (!(check(rows) && check(cols))) return false;

    for (auto &&v : rows) {
        for (auto &&e : v) e.first = c - 1 - e.first;
        reverse(ALL(v));
    }
    for (auto &&v : cols) {
        for (auto &&e : v) e.first = r - 1 - e.first;
        reverse(ALL(v));
    }

    if (!(check(rows) && check(cols))) return false;
    return true;
}

int main() {
    std::cout << (solve() ? "Yes" : "No") << '\n';
    return 0;
}

