struct Near
{
	int nid;
	int sum;

	Near(int nid, int sum) : nid(nid), sum(sum) {}
};

int r, c, n;
vector<Near> nears[MAXRC * 2];
int x[MAXRC * 2];

bool dfs(int id) {
	for (auto near : nears[id]) {
		int tmp = near.sum - x[id];

		if (x[near.nid] == MININT) {
			x[near.nid] = tmp;
			if (!dfs(near.nid)) return false;
		}
		else if (x[near.nid] != tmp)
			return false;
	}

	return true;
}

