void dfs(long long node, long long up) {
	used[node][up] = true;
	if (up == 0) {
		col[cnt][up] = min(col[cnt][up], rr[node]);
		for (long long i = 0; i < rows[node].size(); i++) {
			if (used[rows[node][i].first][1 - up])
				continue;
			cr[rows[node][i].first] = rows[node][i].second - rr[node];
			dfs(rows[node][i].first, 1 - up);
		}
	}
	else {
		col[cnt][up] = min(col[cnt][up], cr[node]);
		for (long long i = 0; i < cols[node].size(); i++) {
			if (used[cols[node][i].first][1 - up])
				continue;
			rr[cols[node][i].first] = cols[node][i].second - cr[node];
			dfs(cols[node][i].first, 1 - up);
		}
	}
}
