  for(int i = 0; i < N; ++i) {
    int r, c, a; scanf("%d%d%d", &r, &c, &a); --r; --c;
    graph[r].emplace_back(R+c, -a);
    graph[R+c].emplace_back(r, a);
  }
  vector<char> vis(R+C, false);
  vector<long long> rel(R+C, 0);
  long long rmin = LLONG_MAX/5;
  long long cmax = LLONG_MIN/5;
  bool ok = true;
  function<void(int, long long)> search = [&](int v, long long vrel){
    if(vis[v]) {
      if(vrel != rel[v]) ok = false;
      return;
    }
    vis[v] = true;
    rel[v] = vrel;
    if(v < R) {
      rmin = min(rmin, vrel);
    } else {
      cmax = max(cmax, vrel);
    }
    for(auto edge : graph[v]) {
      search(edge.first, vrel+edge.second);
    }
  };
  for(int v = 0; v < R+C; ++v) {
    if(vis[v]) continue;
    rmin = LLONG_MAX/5;
    cmax = LLONG_MIN/5;
    search(v, 0);
