        e[c+R].emplace_back(r,a);
    }
    REP (i,R+C) cost[i] = INF;
    REP (i,R+C) if (!used[i]) {
        minr = minc = INF;
        if (!dfs(i,0)) {
            puts("No");
            return 0;
        }
    }
    puts("Yes");
    return 0;
}

