  rep(i, c)u[1][i] = INF;

  bool ret = true;

  rep(i,r){
    if(u[0][i] == INF){
      u[0][i] = 0;
      m[0] = 0;m[1] = INF;
      ret &= dfs(0, i, 0);
    }
  }

  if(ret) cout << "Yes" << endl;
  else cout << "No" << endl;

  return 0;

}

