			if(boo[1][j]) {if(num[1][j]-fl<0) return 0;}
			if(boo[2][j]) {if(num[2][j]+fl<0) return 0;}
		}
	}
	return 1;
}

bool check(int x,int y) {
	if(x==1||y==1) return 1;
	if(num[x][y]+num[x-1][y-1]==num[x][y-1]+num[x-1][y]) return 1;
	return 0;
}

void dfs(int x,int y) {
	if(flag) return;
	if(x==R&&y==C) {flag=1; return;}
	if(boo[x][y]) {
		if(!check(x,y)) return;
		if(y==C) dfs(x+1,1);
		else dfs(x,y+1);
	}
	else {
		for(int i=0;i<=2;i++) {
			num[x][y]=i;
			if(!check) continue;
			if(y==C) dfs(x+1,1);
			else dfs(x,y+1);
		}
	}
}


