int find(int *fa, long long *d, int x) {
	if (fa[x] == 0) return x;
	int res = find(fa, d, fa[x]);
	d[x] += d[fa[x]];
	return fa[x] = res;
}

bool no_sol = false ;

bool uni(int *fa, long long *d, int x, int y, int g) {
	//printf("%d %d %d\n", x, y, g);
	int p = find(fa, d, x), q = find(fa, d, y);	
	if (p == q) {
		if (d[x] - d[y] != g) {
			no_sol = true;
		}
		return false ;
	}
	fa[p] = q; d[p] = g - d[x] + d[y];
}

