		vecC[A[i].second].push_back(i);
	}

	For(i,1,R) if (vecR[i].size() >= 2) {
		for (int j = 1; j < vecR[i].size(); ++j) {
			uni(far, dr, A[vecR[i][j - 1]].second, A[vecR[i][j]].second, val[vecR[i][j - 1]] - val[vecR[i][j]]);
		}
	}
	For(i,1,C) if (vecC[i].size() >= 2) {
		for (int j = 1; j < vecC[i].size(); ++j) {
