// Segment Tree
class SegTree {
public:
    int N;
    LL init;
    VLL dat;

    SegTree(int n_, LL init_) : init(init_) {
        N = 1;
        while (N < n_) N *= 2;
        dat = VLL(N * 4, init);
    }

    // x_k = a
    void update(int k, LL a) {
        k += N - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
        }
    }

    // return: op [a, b)
    LL query(int a, int b) { return query(a, b, 0, 0, N); }

    LL query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return init;
        if (a <= l && r <= b) return dat[k];
        LL vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        LL vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }

};
// /Segment Tree

int main(void) {
    int H, W, N;
    cin >> H >> W >> N;
    vector<pair<PII, int>> ps(N);
    rep(i, N) {
        int y, x, a;
        cin >> y >> x >> a;
        --y; --x;
        ps[i] = MP(MP(y, x), a);
    }

    sort(ALL(ps));

    VVPII ys(H);
    rep(i, N) {
        int y = ps[i].fst.fst;
        int x = ps[i].fst.snd;
        int a = ps[i].snd;
        ys[y].EB(x, a);
    }


    bool flg = true;
    priority_queue<PII, VPII, greater<PII>> q; // y, idx
    VLL sums(W, INFL);

    rep(y, H) {
        if (ys[y].size()) {
            q.push(MP(y, 0));
        }
    }

    while (q.size() && flg) {
        int y = q.top().fst;
        int i = q.top().snd;
        int x = ys[y][i].fst;
        int a = ys[y][i].snd;
        q.pop();

        int j = i + 1;
        if (j >= (int)ys[y].size()) continue;

        int nx = ys[y][j].fst;
        int na = ys[y][j].snd;

        LL diff = na - a;

        if (sums[x] == INFL) {
            if (sums[nx] == INFL) { // xx
                sums[x] = 0;
                sums[nx] = diff;
            } else { // xo
                sums[x] = sums[nx] - diff;
            }
        } else {
            if (sums[nx] == INFL) { // ox
                sums[nx] = sums[x] + diff;
            } else { // oo
                if (sums[nx] != sums[x] + diff) {
                    flg = false;
                    break;
                }
            }
        }

        q.push(MP(y, j));
    }


    SegTree sg(W, INFL);
    rep(x, W) {
        sg.update(x, sums[x]);
    }

    rep(y, H) {
        if (!ys[y].size()) { continue; }
        int x = ys[y][0].fst;
        int a = ys[y][0].snd;

        LL sum1 = sums[x];
        LL sum2 = sg.query(x, W);
        LL diff = sum2 - sum1;

        if (a + diff < 0) flg = false;
    }


    cout << (flg ? "Yes" : "No") << endl;



    return 0;
}

#include <iostream>
#include <map>
using namespace std;

int R, C, N;
bool mod;
map<pair<int, int>, int> grid;

void insert(int r, int c, int v)
{
    mod = true;
    grid.insert(make_pair(make_pair(r, c), v));
}

bool validate(int r, int c, int mx[4], int my[4])
{
    int cnt = 0, cell[4] = {-1, -1, -1, -1};

    for (int i = 0; i < 4; i++) {
        auto it = grid.find(make_pair(r + mx[i], c + my[i]));
        if (it != grid.end()) {
            cell[i] = it->second;
            cnt++;
        }
    }

    if (cnt == 3) {
        if (cell[0] == -1) {
            if (cell[1] + cell[2] < cell[3])
                return false;
            else
                insert(r, c, cell[1] + cell[2] - cell[3]);
        } else if (cell[1] == -1) {
            if (cell[0] + cell[3] < cell[2])
                return false;
            else
                insert(r, c + 1, cell[0] + cell[3] - cell[2]);
        } else if (cell[2] == -1) {
            if (cell[0] + cell[3] < cell[1])
                return false;
            else
                insert(r + 1, c, cell[0] + cell[3] - cell[1]);
        } else if (cell[3] == -1) {
            if (cell[1] + cell[2] < cell[0])
                return false;
            else
                insert(r + 1, c + 1, cell[1] + cell[2] - cell[0]);
        }
    } else if (cnt == 4) {
        if (cell[0] + cell[3] != cell[1] + cell[2])
            return false;
    }

    return true;
}

bool validate_four(int r, int c)
{
    int mx[4] = {0, 0, 1, 1}, my[4] = {0, 1, 0, 1};
    return validate(r, c, mx, my);
}

bool validate_nine(int r, int c)
{
    if (r - 1 < 1 || c - 1 < 1)
        return true;
    if (r + 1 > R || c + 1 > C)
        return true;

    int mx[4] = {-1, -1, 1, 1}, my[4] = {-1, 1, -1, 1};
    return validate(r, c, mx, my);
}

bool run(void)
{
    pair<int, int> p;

    while (true) {
        mod = false;

        for (auto it = grid.begin(); it != grid.end(); it++) {
            p = it->first;
            for (int i = max(1, p.first - 1); i < min(R, p.first + 1); i++)
                for (int j = max(1, p.second - 1); j < min(C, p.second + 1); j++)
                    if (!(validate_four(i, j) && validate_nine(i, j)))
                        return false;
        }

        if (!mod)
            return true;
    }
}

int main(void)
{
    int a, b, c;

    cin >> R >> C >> N;
    for (int i = 0; i < N; i++) {
        cin >> a >> b >> c;
        grid.insert(make_pair(make_pair(a, b), c));
    }

    if (run())
        cout << "Yes" << endl;
    else
        cout << "No" << endl;
}

