		--c;
		cin >> digits[r][c];
	}

	bool possible = true;
	bool filled = false;
	bool hadChanges = true;
	int newDigit = -1;
	while (!filled && possible && hadChanges) {
		filled = true;		
		hadChanges = false;
		for (int i = 0; i < R && possible; ++i) {
			for (int j = 0; j < C; ++j) {
				if (i < R - 1 && j < C - 1) {
