    std::cin.tie(0);
    ll H, W; cin >> H >> W;
    ll N; cin >> N;
    vector< vector<P> > v(W);
    REP(i, N) {
        ll y, x, a; cin >> y >> x >> a; --y, --x;
        v[x].pb({y, a});
    }
    vector< vector<P> > ev(H);
    REP(i, W) {
        sort( ALL(v[i]) );
        ll n = v[i].size();
        REP(j, n-1) {
            ll y1 = v[i][j].first;
            ll y2 = v[i][j+1].first;
            ll d = v[i][j+1].second - v[i][j].second;
            ev[y1].pb({y2, d});
            ev[y2].pb({y1, -d});
        }
    }
    vector<bool> used(H, false);
    vector<ll> pot(H, 0);
    bool ans = true;
    REP(q, H) {
        if (used[q]) continue; used[q] = true;
