#define lim 100001
int res,r,c,m,n,x,y,z,u,v,w,mn,i,j,root;
vector<pair<int, int> > X[lim], Y[lim], A[lim];
int C[lim], M[lim], R[lim], D[lim], C2[lim], M2[lim], R2[lim], D2[lim];
void dfs(int i)
{
    int j,x;
    C[i] = c;
    for (j = 0; j < A[i].size(); j++)
    {
        x = A[i][j].f;
        if (C[x])
        {
            if (D[x] != D[i] + A[i][j].s)
                res = 0;
        }
        else
        {
            D[x] = D[i] + A[i][j].s;
            if (D[x] < mn)
            {
                root = x;
                mn = D[x];
            }
            dfs(x);
        }
    }
}
int main()
{
    res = 1;
    scanf("%d%d%d",&r,&c,&n);
    m = max(r,c);
    for (i = 0; i < n; i++)
    {
        scanf("%d%d%d",&x,&y,&z);
        X[x].pb(mp(y, z));
        Y[y].pb(mp(x, z));
    }
    for(i=1;i<=m;i++)
        for (j = 1; j < X[i].size(); j++)
        {
            u = X[i][0].f;
            v = X[i][j].f;
            w = X[i][j].s - X[i][0].s;
            A[u].pb(mp(v,w));
        }
    for (i = 1; i <= m; i++)
        if (!C[i])
        {
            c = i;
            mn = 0;
            root = i;
            dfs(i);
            M[i] = mn;
            R[i] = root;
        }
    memcpy(C2, C, sizeof C);
    memcpy(M2, C, sizeof M);
    memcpy(R2, C, sizeof R);
    memcpy(D2, C, sizeof D);
    memset(C,0,sizeof C);
    for (i = 1; i <= m; i++)
        A[i].clear();
    for (i = 1; i <= m; i++)
        for (j = 1; j < Y[i].size(); j++)
        {
            u = Y[i][0].f;
            v = Y[i][j].f;
            w = Y[i][j].s - Y[i][0].s;
            A[u].pb(mp(v, w));
        }
    for (i = 1; i <= m; i++)
        if (!C[i])
        {
            c = i;
            mn = 0;
            root = i;
            dfs(i);
            M[i] = mn;
            R[i] = root;
        }
    for(x=1;x<=m;x++)
        for (i = 0; i < X[x].size(); i++)
        {
            y = X[x][i].f;
            if (X[x][i].s + M2[C2[x]] - D2[y] + M[C[y]] - D[x] < 0)
                res = 0;
        }
    printf("%s\n",res?"Yes":"No");
	return 0;
}

