const int N = 1e5 + 4;

ll n, m, k, r[N], c[N];
vector<pll> g[2][N];

void read() {
    cin >> n >> m >> k;
    for (int i = 0; i < k; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        g[0][u].em_back(v, w);
        g[1][v].em_back(u, w);
    }
}

int used[2][N];
ll color[2][N];

ll up, down;

void dfs(int s, int u, ll add, int stat) {
    used[s][u] = stat;
    color[s][u] = add;

    if (s) { /// add - x >= 0
        up = min(up, add);
    } else { /// x + add >= 0
        down = max(down, -add);
    }

    for (pll p : g[s][u]) if (stat != used[s ^ 1][p.first]) {
        dfs(s ^ 1, p.first, p.second - add, stat);
    }
}

bool check() {
    for (int u = 1; u <= n; ++u) {
        for (pll p : g[0][u]) {
            if (color[0][u] + color[1][p.first] != p.second) {
                return false;
            }
        }
    }
    return true;
}

void solve() {
    read();

    for (int i = 1; i <= n; ++i) if (!used[0][i]) {
        up = 8e18;
        down = -up;
        dfs(0, i, 0, 1);
        if (up < down) {
            cout << "No\n";
            return;
        }
        dfs(0, i, down, 2);
    }

    if (check()) {
        cout << "Yes\n";
    } else {
        cout << "No\n";
    }
}

int main() {
    ios::sync_with_stdio(0);
    cout.tie(0), cin.tie(0);

    int z = 1;
    /// cin >> z;

    while (z--) {
        solve();
    }

    return 0;
}

