constexpr int MOD = 1000000007;
constexpr int INF = MOD;

typedef long long LL;
typedef pair<int, int> P;
typedef pair<LL, LL> PLL;

int R, C;
int N;

vector<P> gr[100000];
vector<P> gc[100000];

int valr[100000], valc[100000];
char chkr[100000], chkc[100000];

P dfs(int x) {
    int min_r = valr[x], min_c = INF;
    for (const P& p: gr[x]) {
        int v = p.first;
        int a = p.second;

        if (chkc[v]) {
            if (valr[x] + valc[v] != a) {
                return P(-1, -1);
            }
            continue;
        }

        chkc[v] = true;
        valc[v] = a - valr[x];

        min_c = min(min_c, valc[v]);

        for (const P& q : gc[v]) {
            int w = q.first;
            int b = q.second;

            if (chkr[w]) {
                if (valc[v] + valr[w] != b) {
                    return P(-1, -1);
                }
                continue;
            }
            chkr[w] = true;
            valr[w] = b - valc[v];

            P tret = dfs(w);

            min_r = min(min_r, tret.first);
            min_c = min(min_c, tret.second);
        }
    }
    return P(min_r, min_c);
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> R >> C >> N;
    for (int j = 0; j < N; ++j) {
        int r, c, a;
        cin >> r >> c >> a;
        --r; --c;

        gr[r].push_back(P(c, a));
        gc[c].push_back(P(r, a));
    }

    fill(chkr, chkr+R, false);
    fill(chkc, chkc+C, false);


    for (int j = 0; j < R; ++j) {
        if (!chkr[j]) {
            valr[0] = 0;
            chkr[0] = true;
            int rmin, cmin;
            tie(rmin, cmin) = dfs(j);
            if (rmin + cmin < 0) {
                cout << "No" << endl;
                return 0;
            }
        }
    }
    cout << "Yes" << endl;

    return 0;
}

