void solve(V<t3> &numlist, ll nodecount)
{
    sort(numlist);

    V<t2> linklist[100002];

    static ll minvals[100002];
    rep (i, 100002) minvals[i] = 1e18;

    static ll maxvals[100002];
    memset(maxvals, 0, sizeof(maxvals));

    ll prevgroup = -1LL;
    ll prevnode = -1LL;
    ll prevval = -1LL;

    for (auto item : numlist) {
        ll group = get<0>(item);
        ll node = get<1>(item);
        ll val = get<2>(item);

        if (group == prevgroup) {
            debug_printf("link : %lld -- %lld\n", prevnode, node);
            linklist[prevnode].pb(t2(node, val - prevval));
            assert(prevnode < node);
        }
        minvals[node] = min(minvals[node], val);
        maxvals[node] = max(maxvals[node], val);

        prevgroup = group;
        prevnode = node;
        prevval = val;
    }

    static bool checked[100002];
    memset(checked, 0, sizeof(checked));

    static ll relative[100002];
    memset(relative, 0, sizeof(relative));
    ll min_relative = 0LL;
    ll max_relative = 0LL;

    srep (start, 1LL, nodecount+1LL) {
        if (checked[start]) continue;
        queue<ll> q;
        V<ll> nodelist;

        q.push(start);
        nodelist.pb(start);
        checked[start] = true;
        relative[start] = 0LL;
        min_relative = 0LL;
        max_relative = 0LL;

        while (!q.empty()) {
            ll node = q.front(); q.pop();
            for (auto nd : linklist[node]) {
                ll next = get<0>(nd);
                ll diff = get<1>(nd);
                ll nrelative = relative[node] + diff;
                debug_printf("node=%lld next=%lld noder=%lld nextr=%lld\n",
                             node, next, relative[node], nrelative);
                if (checked[next]) {
                    debug_printf("  next=%lld relative[next]=%lld nrelative=%lld\n",
                                 next, relative[next], nrelative);
                    if (relative[next] != nrelative) {
                        cout << "No" << endl;
                        exit(0);
                    }
                }
                if (!checked[next]) q.push(next);
                nodelist.pb(next);
                checked[next] = true;
                relative[next] = nrelative;
                min_relative = min(min_relative, nrelative);
                max_relative = max(max_relative, nrelative);
            }
        }

        for (auto node : nodelist) {
            debug_printf("node=%lld minvals[node]=%lld maxvals[node]=%lld "
                         "relative[node]=%lld min_relative=%lld max_relative=%lld\n",
                         node, minvals[node], maxvals[node], relative[node],
                         min_relative, max_relative);
            if (minvals[node] - (relative[node] - min_relative) < 0LL) {
                cout << "No" << endl;
                exit(0);
            }
            if (maxvals[node] + (max_relative - relative[node]) > 1e9) {
                cout << "No" << endl;
                exit(0);
            }
        }
    }
}

