const int N = 200000;

int n, m, k;
bool ok, visited[N];
long long mi, ma, delta[N];
std::vector<std::pair<int, int>> graph[N];

void dfs(int u) {
  visited[u] = true;
  if (u < n) {
    mi = std::max(mi, -delta[u]);
  } else {
    ma = std::min(ma, delta[u]);
  }
  for (auto &&iterator : graph[u]) {
    int v = iterator.first;
    int w = iterator.second;
    if (visited[v]) {
      ok &= delta[u] + delta[v] == w;
    } else {
      delta[v] = w - delta[u];
      dfs(v);
    }
  }
}

int main() {
  while (scanf("%d%d%d", &n, &m, &k) == 3) {
    for (int i = 0; i < n + m; ++i) {
      graph[i].clear();
    }
    for (int i = 0, a, b, c; i < k; ++i) {
      scanf("%d%d%d", &a, &b, &c);
      a--, b--;
      graph[a].emplace_back(n + b, c);
      graph[n + b].emplace_back(a, c);
    }
    ok = true;
    memset(visited, 0, sizeof(*visited) * (n + m));
    for (int i = 0; i < n; ++i) {
      if (!visited[i]) {
        mi = std::numeric_limits<long long>::min(),
        ma = std::numeric_limits<long long>::max(), delta[i] = 0;
        dfs(i);
        ok &= mi <= ma;
      }
    }
    puts(ok ? "Yes" : "No");
  }
}

