struct Near
{
	int nid;
	int sum;

	Near(int nid, int sum) : nid(nid), sum(sum) {}
};

int r, c, n;
vector<Near> nears[MAXRC * 2];
int x[MAXRC * 2];
bool vis[MAXRC * 2];

int xm, ym;

bool dfs(int id, int val) {
	if (vis[id]) {
		if (x[id] != val) return false;
		else return true;
	}

	vis[id] = true;
	x[id] = val;

	if (id >= r) ym = MIN(ym, val);
	else xm = MIN(xm, val);

	for (auto near : nears[id]) {
		if (!dfs(near.nid, near.sum - val))
			return false;
	}

	return true;
}

