		nears[ci + r].push_back(Near(ri, ai));
	}

	bool rst = true;

	for (int i = 0; i < r + c; ++i) vis[i] = false;

	for (int i = 0; i < r + c; ++i) {
		if (vis[i]) continue;

		xm = MAXINT, ym = MAXINT;
