            int j1, j2, d;
            tie(j1, j2, d) = t;

            assert(ver_min[j1] != INF);
            assert(ver_min[j2] != INF);

            if (hol_rel[j1] == -1) {
                hol_rel[j1] = ver_min[j1];
                hol_rel[j2] = hol_rel[j1] + d;
            } 
            if (hol_rel[j2] == -1) {
                hol_rel[j2] = hol_rel[j1] + d;
            }
            if (hol_rel[j1] + d != hol_rel[j2] || hol_rel[j1] < 0 || hol_rel[j2] < 0) {
                yes = false;
            }
