	xinc.clear();
	yinc.clear();
	checked.clear();
	mass.clear();
	for(int i = 0 ; i < r.size() ; i++){
		mass[{r[i],c[i]}] = a[i];
	}
	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		pair<int,int> rig = {y,x+1};
		pair<int,int> dow = {y+1,x};

		if( mass.count(rig) ){
			int diff = mass[rig] - p.second;
			xinc[x] = diff;
		}

		if( mass.count(dow) ){
			int diff = mass[dow] - p.second;
			yinc[y] = diff;
		}
	}

	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		int v = p.second;
		dfs(y,x,v);
	}


}




