			int kuuhaku =
				(v[i][k] == -1) +
				(v[i - 1][k] == -1) +
				(v[i][k - 1] == -1) +
				(v[i - 1][k - 1] == -1);

			if (kuuhaku == 0) {
				if (v[i - 1][k] + v[i][k - 1] != v[i][k] + v[i - 1][k - 1]) {
					ok = false;
					break;
				}
			}
			else if (kuuhaku == 1) {
				if (v[i - 1][k] == -1) v[i - 1][k] = v[i][k] + v[i - 1][k - 1] - v[i][k - 1];
				if (v[i][k] == -1) v[i][k] = v[i - 1][k] + v[i][k - 1] - v[i - 1][k - 1];
				if (v[i][k - 1] == -1) v[i][k - 1] = v[i][k] + v[i - 1][k - 1] - v[i - 1][k];
				if (v[i - 1][k - 1] == -1) v[i - 1][k - 1] = v[i - 1][k] + v[i][k - 1] - v[i][k];
				rep(l, 4) {
					if (v[i - dx[l]][k - dy[l]] < 0) {
						ok = false;
						break;
					}
				}
			}
			else if (kuuhaku == 2) {
				if ((v[i][k] > 0 && v[i - 1][k - 1] > 0)) {
					v[i - 1][k] = 0;
					v[i][k - 1] = v[i][k] + v[i - 1][k - 1];
				}
				else if ((v[i - 1][k] > 0 && v[i][k - 1] > 0)) {
					v[i][k] = 0;
					v[i - 1][k - 1] = v[i - 1][k] + v[i][k - 1];
				}

				if ((v[i][k] > 0 && v[i][k - 1] > 0)) {
					v[i - 1][k] = v[i][k-1];
					v[i-1][k - 1] = v[i][k];
				}
				else if ((v[i][k] > 0 && v[i - 1][k] > 0)) {
					v[i-1][k - 1] = v[i][k];
					v[i][k-1] = v[i-1][k];
				}
				else if ((v[i - 1][k - 1] > 0 && v[i][k - 1] > 0)) {
					v[i][k] = v[i - 1][k - 1];
					v[i - 1][k] = v[i][k-1];
				}
				else if ((v[i - 1][k - 1] > 0 && v[i - 1][k] > 0)) {
					v[i][k] = v[i - 1][k - 1];
					v[i][k-1] = v[i-1][k];
				}

			}
			else if (kuuhaku == 3) {
				if (v[i - 1][k] > 0) {
					v[i][k - 1] = 0;
					v[i][k] = 0;
					v[i - 1][k - 1] = v[i - 1][k];
				}
				if (v[i][k] > 0) {
					v[i - 1][k - 1] = 0;
					v[i][k - 1] = 0;
					v[i - 1][k] = v[i][k];
				}
				if (v[i][k - 1] > 0) {
					v[i - 1][k] = 0;
					v[i][k] = 0;
					v[i - 1][k - 1] = v[i][k - 1];
				}
				if (v[i - 1][k - 1] > 0) {
					v[i][k] = 0;
					v[i][k - 1] = 0;
					v[i - 1][k] = v[i][k - 1];
				}

			}
		}
	}

	if (ok) {
		cout << "Yes" << endl;
	}
	else {
		cout << "No" << endl;
	}

	return 0;
}

