void solve(){
    int r,c,n;
    cin >> r >> c >> n;
    vector<vector<pair<int,int>>> ps(c);
    vector<map<int,int>> mp(r);
    set<pair<int,int>> exist;
    rep(i,0,n){
        int x,y,a;
        cin >> y >> x >> a;
        --x;
        --y;
        ps[x].push_back(make_pair(y,a));
        mp[y][x]=a;
        exist.insert(make_pair(y,x));
    }

    rep(x,0,c) sort(ps[x].begin(),ps[x].end());

    vector<int> req(r-1);
    rep(y,0,r-1){
        int k=-inf;
        for(auto &p:mp[y]){
            int x=p.first;
            if(exist.find(make_pair(y+1,x))==exist.end()) continue;
            int diff=mp[y+1][x]-mp[y][x];
            if(k==-inf) k=diff;
            else if(k!=diff){
                cout << "No" << endl;
                return;
            }
        }
        req[y]=k;
    }

    vector<map<int,int>> memo(r-1);
    vector<int> min_diff(r,inf);
    rep(x,0,c){
        rep(i,0,int(ps[x].size())-1){
            int y1=ps[x][i].first,y2=ps[x][i+1].first;
            int sum=-inf;
            rep(y,y1,y2){
                if(req[y]==-inf) sum=-inf;
                else{
                    if(sum==-inf) sum=0;
                    sum+=req[y];
                }
            }
            if(sum==-inf) continue;
            memo[y1][y2]=sum;
            min_diff[y1]=min(min_diff[y1],sum);
            if(sum!=ps[x][i+1].second-ps[x][i].second){
                cout << "No" << endl;
                return;
            }
        }
    }

    rep(y,0,c){
        if(mp[y].size()==0 or min_diff[y]==inf) continue;
        int mini=inf;
        for(auto &p:mp[y]) mini=min(mini,p.second);
        if(mini+min_diff[y]<0){
            cout << "No" << endl;
            return;
        }
    }
    cout << "Yes" << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(10);
    solve();
    return 0;
}

