vector<PII> G[200005];
bool vis[200005];
int w[200005];
int ll, rr;

void dfs(int v, int h) {
  if (vis[v]) {
    if (w[v] != h) {
      printf("NO\n");
      exit(0);
    }
    return;
  }
  vis[v] = true;
  w[v] = h;
  if (v < r) ll = max(ll, h);
  else rr = min(rr, h);
  for (int i = 0; i < G[v].size(); i += 1) {
    PII nxt = G[v][i];
    dfs(nxt.first, nxt.second + h);
  }
}

int main() {
