    int x, y, a;
    scanf("%d %d %d", &x, &y, &a);
    x -= 1; y -= 1;
    G[x].push_back(PII(r + y, a));
    G[r + y].push_back(PII(x, -a));
  }
  for(int i = 0; i < r + c; i += 1) {
    vis[i] = false;
  }
  for(int i = 0; i < r + c; i += 1) {
    if (!vis[i]) {
      ll = INT_MIN, rr = INT_MAX;
      dfs(i, 0);
      if (ll > rr) {
        printf("NO\n");
        return 0;
      }
    }
  }
  printf("YES\n");
  return 0;
}

#include <bits/stdc++.h>
using namespace std;

// one-based numbering
template<class Abel> struct UnionFind {
	vector<int> data;
	vector<Abel> diff_weight;
	UnionFind(int n, Abel id) {
		data.resize(n+1, -1);
		diff_weight.resize(n+1, id);
	}
	int find(int x) {
		if(data[x] < 0) return x;
		else {
			int root = find(data[x]);
			diff_weight[x] += diff_weight[data[x]];
			return data[x] = root;
		}
	}
	int size(int x) {
		return -data[find(x)];
	}
	bool same(int x, int y) {
		x = find(x); y = find(y);
		return x == y;
	}
	bool unite(int x, int y, Abel w) {
		w += weight(x); w -= weight(y);
		x = find(x); y = find(y);
		if(x == y) return false;
		if (data[x] > data[y]) swap(x, y), w = -w;
		data[x] += data[y];
		data[y] = x;
		diff_weight[y] = w;
		return true;
    }
	Abel weight(int x) {
		find(x);
		return diff_weight[x];
	}
	Abel diff(int x, int y) {
		return weight(y) - weight(x);
	}
};

int main() {
    int r, c, n; cin >> r >> c >> n;
    vector<vector<pair<int, long long>>> v(r+1);
    vector<long long> rv(r+1, 1e16), cv(c+1, 1e16);
    map<pair<int, int>, long long> m; 
    for (int i = 0; i < n; i++) {
        int c, d; long long a; cin >> c >> d >> a;
        v[c].emplace_back(d, a);
        m[{c, d}] = a;
    }
    UnionFind<long long> cuf(c, 0);
    for (auto vec: v) {
        if (vec.size() <= 1) continue;
        for (int i = 0; i < vec.size()-1; i++) {
            if (cuf.same(vec[i].first, vec[i+1].first)) {
                if (cuf.diff(vec[i].first, vec[i+1].first) != vec[i+1].second - vec[i].second) {
                    cout << "No" << endl;
                    return 0;
                }
            } else {
                cuf.unite(vec[i].first, vec[i+1].first, vec[i+1].second - vec[i].second);
            }
        }
    }
    map<long long, long long> mincv;
    for (int i = 1; i <= c; i++) {
        mincv[cuf.find(i)] = min(mincv[cuf.find(i)], cuf.weight(i));
    }
    for (int i = 1; i <= c; i++) {
        cv[i] = cuf.weight(i) - mincv[cuf.find(i)];
    }
    for (auto x: m) {
        long long t = x.second - cv[x.first.second];
        if (cv[x.first.second] == 1e16) t = 1e16;
        if (rv[x.first.first] != 1e16) {
            if (rv[x.first.first] != t) {
                cout << "No" << endl;
                return 0;
            }
        } else rv[x.first.first] = t;
    }
    sort(rv.begin(), rv.end());
    sort(cv.begin(), cv.end());
    if (rv.front() + cv.front() < 0) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;
    }
    return 0;
}

