#include <bits/stdc++.h>
#define oo 1e18
using namespace std;

typedef long long ll;
const int N = 1e5 + 5;
int fax[N], fay[N], T, R, C, n;
ll mi1[N], mi2[N], wx[N], wy[N];
struct node {
	int x, y;
	ll val;
	void read( ) {
		scanf("%d%d%lld",& x,& y,& val);
	}
}P[N];

bool cmpx(const node & a, const node & b) {
	return a.x < b.x;
}

bool cmpy(const node & a, const node & b) {
	return a.y < b.y;
}

int find_x(int u) {

	if(fax[u] == u) return u;
	int rt = find_x(fax[u]);
	wx[u] += wx[fax[u]];
	return fax[u] = rt;
}

bool link_x(int u, int v, int w) {

	int fu = find_x(u), fv = find_x(v);
	if(fu != fv) {
		fax[fu] = fv;
		wx[fu] = w + wx[v] - wx[u]; return true;
	}
	else return wx[u] == wx[v] + w;
}

int find_y(int u) {

	if(fay[u] == u) return u;
	int rt = find_y(fay[u]);
	wy[u] += wy[fay[u]];
	return fay[u] = rt;
}

bool link_y(int u, int v, int w) {

	int fu = find_y(u), fv = find_y(v);
	if(fu != fv) {
		fay[fu] = fv;
		wy[fu] = w + wy[v] - wy[u]; return true;
	}
	else return wy[u] == wy[v] + w;
}

int main( ) {

	//freopen("then.in", "r", stdin);
	//freopen("then.out", "w", stdout);
	T = 1;
	while(T --) {
		bool tag = true;
		scanf("%d%d%lld",& R,& C,& n);
		for(int i = 1;i <= R;i ++) {
			fax[i] = i; wx[i] = 0; 
		}
		for(int i = 1;i <= C;i ++) {
			fay[i] = i; wy[i] = 0;
		}
		for(int i = 1;i <= n;i ++) {
			P[i].read( );
			if(P[i].val < 0) tag = false;
		}
		sort(P + 1, P + n + 1, cmpx);
		for(int i = 1;i < n;i ++) {
			if(P[i].x == P[i + 1].x) 
				if(! link_y(P[i].y, P[i + 1].y, P[i + 1].val - P[i].val)) tag = false;
		}
		sort(P + 1, P + n + 1, cmpy);
		for(int i = 1;i < n;i ++) {
			if(P[i].y == P[i + 1].y)
				if(! link_x(P[i].x, P[i + 1].x, P[i + 1].val - P[i].val)) tag = false;
		}
		memset(mi1, 0x3f3f, sizeof(mi1));
		memset(mi2, 0x3f3f, sizeof(mi2));
		for(int i = 1;i <= n;i ++) {
			int rt = find_x(P[i].x);
			mi1[rt] = min(mi1[rt], P[i].val + wx[P[i].x]);
		}
		for(int i = 1;i <= R;i ++) {
			int rt = find_x(i);
			mi2[rt] = min(mi2[rt], -wx[i]);
		}
		ll cmp = oo;
		for(int i = 1;i <= R;i ++) cmp = min(cmp, mi1[i] + mi2[i]);
		if(cmp < 0) tag = false;
		if(tag) printf("Yes\n");
		else printf("No\n");
	}
}

