bool valid(int y, int x){
	return (y >= 0 && x >= 0 && y + 1 < R && x + 1 < C);
}

bool fill(int y, int x){
	int lefttop;
	int leftdown;
	int righttop;
	int rightdown;
	int num = 0;

	if(rca.count(make_pair(y, x)) == 0){
		lefttop = -1;
	}else{
		lefttop = rca[make_pair(y, x)];
		num++;
	}

	if(rca.count(make_pair(y+1, x)) == 0){
		leftdown = -1;
	}else{
		leftdown = rca[make_pair(y+1, x)];
		num++;
	}

	if(rca.count(make_pair(y, x+1)) == 0){
		righttop = -1;
	}else{
		righttop = rca[make_pair(y, x+1)];
		num++;
	}

	if(rca.count(make_pair(y+1, x+1)) == 0){
		rightdown = -1;
	}else{
		rightdown = rca[make_pair(y+1, x+1)];
		num++;
	}
	if(num < 3){
		return true;
	}else if(num == 3){
		if(lefttop == -1){
			lefttop = leftdown + righttop - rightdown;
			if(lefttop < 0){
				return false;
			}
			rca[make_pair(y, x)] = lefttop;
			return true;
		}
		if(leftdown == -1){
			leftdown = lefttop + rightdown - righttop;
			if(leftdown < 0){
				return false;
			}
			rca[make_pair(y+1, x)] = leftdown;
			return true;
		}
		if(righttop == -1){
			righttop = lefttop + rightdown - leftdown;
			if(righttop < 0){
				return false;
			}
			rca[make_pair(y, x+1)] = righttop;
			return true;
		}
		if(rightdown == -1){
			rightdown = leftdown + righttop - lefttop;
			if(rightdown < 0){
				return false;
			}
			rca[make_pair(y+1, x+1)] = rightdown;
			return true;
		}
	}else{
		return (lefttop + rightdown == leftdown + righttop);
	}
}

