  bool update = true;
  int cnt = 0;
  while( update ) {
    ++cnt;
    if( cnt >= 100 ) break;
    update = false;
    map<Data,int> next;
    for(map<Data,int>::iterator it = mp.begin();it!=mp.end();++it) {
      int x = (it->first).x;
      int y = (it->first).y;
      int a = it->second;
      if( !check(mp,x,y,a) ) {
	cout << NO << endl;
	return 0;
      }
      //cout << x << "," << y << " = " << a <<endl;
      rep(i,4) {
	int x2 = x + dx[i], y2 = y + dy[i];
