vector<long long> result;
bool validate(const vector<vector<pair<int, int> > >& c2) {
  int n = c2.size();
  vector<int> visited(n);
  result.clear();
  result.resize(n);
  for (int i=0; i<n; i++) {
    if (visited[i]) continue;
    visited[i] = 1;
    queue<int> Q;
    result[i] = 0;
    Q.push(i);
    vector<int> cur;
    cur.push_back(i);
    long long low = 0;
    while (!Q.empty()) {
      int now = Q.front();
      low = min(low, result[now]);
      Q.pop();
      for (int i=0; i<c2[now].size(); i++) {
        int id = c2[now][i].first;
        int val = c2[now][i].second;
        if (visited[id] && result[now] + val != result[id]) return false;
        if (visited[id]) continue;
        visited[id] = 1;
        result[id] = result[now] + val;
        Q.push(id);
        cur.push_back(id);
      }
    }
    for (int j=0; j<cur.size(); j++)
      result[cur[j]] -= low;
  }
  return true;
}

