const char * task_d()
{
    size_t r, c, n;
    cin >> r >> c >> n;
    //vector<vector<int64_t>> a(r, vector<int64_t>(c, -1));
    vector<unordered_map<size_t, int>> a(r);

    const auto get = [&a](const size_t i, const size_t j) -> int {
        const auto iter = a[i].find(j);
        return iter != end(a[i]) ? iter->second : -1;
    };

    queue<pair<size_t, size_t>> q;

    for(size_t i = 0, r, c; i < n; ++i)
    {
        cin >> r >> c;
        cin >> a[--r][--c];
        q.emplace(r, c);
    }

    for(; !q.empty(); q.pop())
    {
        const auto i = q.front().first;
        const auto j = q.front().second;

        if(i + 1 < r && j + 1 < c && get(i, j + 1) != -1 && get(i + 1, j) != -1)
        {
            if(get(i + 1, j + 1) == -1)
            {
                a[i + 1][j + 1] = a[i][j + 1] + a[i + 1][j] - a[i][j];
                if(a[i + 1][j + 1] < 0) return "No";
                q.emplace(i + 1, j + 1);
            }
            else if(a[i][j] + a[i + 1][j + 1] != a[i][j + 1] + a[i + 1][j])
                return "No";
        }

        if(i + 1 < r && 0 < j && get(i, j - 1) != -1 && get(i + 1, j) != -1)
        {
            if(get(i + 1, j - 1) == -1)
            {
                a[i + 1][j - 1] = a[i][j - 1] + a[i + 1][j] - a[i][j];
                if(a[i + 1][j - 1] < 0) return "No";
                q.emplace(i + 1, j - 1);
            }
            else if (a[i][j] + a[i + 1][j - 1] != a[i][j - 1] + a[i + 1][j])
                return "No";
        }

        if(0 < i && j + 1 < c && get(i - 1, j) != -1 && get(i, j + 1) != -1)
        {
            if(get(i - 1, j + 1) == -1)
            {
                a[i - 1][j + 1] = a[i - 1][j] + a[i][j + 1] - a[i][j];
                if(a[i - 1][j + 1] < 0) return "No";
                q.emplace(i - 1, j + 1);
            }
            else if (a[i][j] + a[i - 1][j + 1] != a[i - 1][j] + a[i][j + 1])
                return "No";
        }

        if(0 < i && 0 < j && get(i, j - 1) != -1 && get(i - 1, j) != -1)
        {
            if(get(i - 1, j - 1) == -1)
            {
                a[i - 1][j - 1] = a[i][j - 1] + a[i - 1][j] - a[i][j];
                if(a[i - 1][j - 1] < 0) return "No";
                q.emplace(i - 1, j - 1);
            }
            else if (a[i][j] + a[i - 1][j - 1] != a[i][j - 1] + a[i - 1][j])
                return "No";
        }
    }

    return "Yes";
}

int main(const int argc, char * argv [])
{
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    cout << task_d() << '\n';

    return EXIT_SUCCESS;
}

