struct Data
{
  ll from;
  ll to;
  ll len;
  Data(){};
  Data(ll f,ll t,ll l): from(f), to(t), len(l){};
  bool operator<( const Data& r ) const {
    return (from==r.from)?(to<r.to):(from<r.from);
  }
};

bool ok(vector<vector<Pll>> &X,ll s1,ll s2)
{
