  REP(i,s2) if(Y[i]==LLINF) Y[i]=1e10;
  REP(i,s1)
  {
    REP(j,X[i].size())
    {
      if(Y[X[i][j].first]+X[i][j].second<0) return false;
    }
  }
  return true;
}

