  vector<vector<pii> > mat(r);
  for (int i = 0; i < n; i++) {
    int x, y, a;
    std::cin >> y >> x >> a;
    mat[--y].push_back(pii(--x, a));
  }
  lli val = 0;
  bool updated = false;
  for (int i = 0; i < r; i++) {
    if(mat[i].empty())continue;
    if(mat[i][0].first == 0 and mat[i].back().first == c - 1){
      val = mat[i][0].second - mat[i].back().second;
      updated = true;
      break;
    }
  }
  if(updated){
      std::cout << "Yes" << std::endl;
      return 0;
  }
  bool is_yes = true;
  for (int i = 0; i < r and is_yes; i++) {
    if(mat[i].empty())continue;
    if(mat[i][0].first != 0 and mat[i].back().first != c - 1){
      continue; 
    }else if(mat[i][0].first != 0 and mat[i].back().first == c - 1){
      is_yes &= (mat[i].back().second >= -val);
    }else if(mat[i][0].first == 0 and mat[i].back().first != c - 1){
      is_yes &= (mat[i][0].second >= val);
    }else{
      is_yes &= (val == mat[i][0].second - mat[i].back().second);
    }
  }
  if(is_yes)std::cout << "Yes" << std::endl;
  else std::cout << "No" << std::endl;
  return 0;
