using namespace std;

vector<bool> used;
vector<long long> x, y;
vector<long long> vl;
vector<long long> vlx, vly;
vector<bool> udx, udy;
vector<vector<long long> > tx;
vector<vector<long long> > ty;

bool dfs(long long v) {
    used[v] = true;
    bool fx = 0, fy = 0;
    if (!udx[x[v]] && !udy[y[v]])
        vly[y[v]] = 0, fy = 1, udy[y[v]] = 1;
    if (!udx[x[v]] )
        fx = 1, udx[x[v]] = 1, vlx[x[v]] = vl[v] - vly[y[v]];
    if (!udy[y[v]])
        fy = 1, udy[y[v]] = 1, vly[y[v]] = vl[v] - vlx[x[v]];
    if (vlx[x[v]] + vly[y[v]] != vl[v])
        return false;
    if (fx)
    {
        udx[x[v]] = 1;
        for (long long i = 0; i < tx[x[v]].size(); ++i)
            if (!used[tx[x[v]][i]])
                if (!dfs(tx[x[v]][i]))
                    return false;
    }
    if (fy)
    {
        udy[y[v]] = 1;
        for (long long i = 0; i < ty[y[v]].size(); ++i)
            if (!used[ty[y[v]][i]])
                if (!dfs(ty[y[v]][i]))
                    return false;
    }
    return true;
}

