constexpr int INFINT_LIM = (1LL << 31) - 1;  // 2.15x10^ 9
constexpr ll INFLL = 1LL << 60;              // 1.15x10^18
constexpr double EPS = 1e-9;
constexpr int MOD = 1000000007;
constexpr double PI = 3.141592653589793238;

signed main() {
	INIT;
	VAR(int, R, C, N);
	std::vector<int> row(R, INFLL), col(C, INFLL);
	std::map<int, std::map<int, int>> a;
	std::map<int, std::vector<int>> r_c, c_r;
	REP(i, N) {
		VAR(int, r, c, _a);
		a[--r][--c] = _a;
		r_c[r].emplace_back(c);
		c_r[c].emplace_back(r);
	}

	std::vector<bool> checkedR(R), checkedC(C);
	int minR = INFINT, minC = INFINT;
	std::function<bool(int, int)> dfs = [&](int r, int c) {
		bool flag = true;
		if (c == -1) {
			for (const auto& _c : r_c[r]) {
				if (checkedC[_c]) {
					if (row[r] + col[_c] != a[r][_c]) flag = false;
				}
				else {
					checkedC[_c] = true;
					col[_c] = a[r][_c] - row[r];
					CHMIN(minC, col[_c]);
					flag &= dfs(-1, _c);
				}
			}
		}
		else {
			for (const auto& _r : c_r[c]) {
				if (checkedR[_r]) {
					if (col[c] + row[_r] != a[_r][c]) flag = false;
				}
				else {
					checkedR[_r] = true;
					row[_r] = a[_r][c] - col[c];
					CHMIN(minR, row[_r]);
					flag &= dfs(_r, -1);
				}
			}
		}
		return flag;
	};
	for (const auto& t : a) {
		int r = t.first;
		if (checkedR[r]) continue;
		row[r] = 0;
		checkedR[r] = true;
		minR = minC = INFINT;
		if (!dfs(r, -1)) {
			OUT("No")BR;
			return 0;
		}
		if (minR + minC < 0) {
			OUT("No")BR;
		}
	}

	OUT("Yes")BR;
	return 0;
}

