    x[r][c] = a;
    y[c][r] = a;
  }
  bool ok = okx();
  for (int i = 0; i < N; i++) {
    x[i] = y[i];
  }
  ok &= okx();
  if (ok) {
    cout << "Yes\n";
  } else {
    cout << "No\n";
