struct UnionFind {
  vector<ll> data;
  vector<ll> difweight;
  UnionFind(ll size){
    data.assign(size,-1);
    difweight.assign(size,0);
  }
  bool unite(ll x, ll y, ll w) { //y=x+w
    w += weight(x); w -= weight(y);
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y), w = -w;
      data[x] += data[y]; 
      data[y] = x;
      difweight[y] = w;
    }
    return x != y;
  }
  bool find(ll x, ll y) {
    return root(x) == root(y);
  }
  ll diff(ll x,ll y){
    return weight(y)-weight(x);
  }
  ll weight(ll x){
    root(x);
    return difweight[x];
  }
  ll root(ll x) {
    if(data[x] < 0){
      return x;
    }
    else{
      ll tmp = root(data[x]);
      difweight[x] += difweight[data[x]];
      return data[x] = tmp;
    }
  }
  ll size(ll x) {
    return -data[root(x)];
  }
  ll debug(){
    rep(i,0,data.size()){
      root(i);
      cout<<i spa data[i] spa difweight[i] spa weight(i)<<endl;
    }
    cout<<endl;
  }
};
