/*
 * Union-Find tree
 * header requirement: vector
 */
class UnionFind {
private:
  std::vector<int> disj;
  std::vector<int> rank;
public:
  UnionFind(int n) : disj(n), rank(n) {
    for (int i = 0; i < n; ++i) {
      disj[i] = i;
      rank[i] = 0;
    }
  }
  int root(int x) {
    if (disj[x] == x) {
      return x;
    }
    return disj[x] = root(disj[x]);
  }
  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) {
      return;
    }
    if (rank[x] < rank[y]) {
      disj[x] = y;
    } else {
      disj[y] = x;
      if (rank[x] == rank[y]) {
	++rank[x];
      }
    }
  }
  bool is_same_set(int x, int y) {
    return root(x) == root(y);
  }
};

int r, c, n;
vector<PL> edges[N];
ll dp[N];
int root[N];
bool update_cons(UnionFind &uf, int c1, int c2, ll d) {
  comp.push_back(intdiff(PI(c1, c2),d));
  edges[c1].push_back(PL(c2, d));
  uf.unite(c1, c2);
  return true;
}

ll inf = -1e16;
bool dfs(int v, ll c, int r) {
  root[v] = r;
  if (dp[v] > inf) {
    return dp[v] == c;
  }
  dp[v] = c;
  REP(i, 0, edges[v].size()) {
    PL e = edges[v][i];
    bool res = dfs(e.first, c + e.second, r);
    if (!res) {
      return false;
    }
  }
  return true;
}

int main(void){
  cin >> r >> c >> n;
  UnionFind uf(c);
  REP(i, 0, n) {
    cin >> rr[i] >> cc[i] >> a[i];
    rr[i]--, cc[i]--;
    cons[rr[i]].push_back(PL(cc[i], a[i]));
  }
  REP(i, 0, r) {
    sort(cons[i].begin(), cons[i].end());
    if (cons[i].size() <= 1) {
      continue; // no constraints
    }
    REP(j, 0, cons[i].size() - 1) {
      bool res = update_cons(uf, cons[i][j].first, cons[i][j + 1].first,
			     cons[i][j + 1].second - cons[i][j].second);
    }
  }
  REP(i, 0, c) {
    dp[i] = inf;
  }
  REP(i, 0, c) {
    bool res = 1;
    if (dp[i] <= inf) {
      res = dfs(i, 0, i);
    }
    if (!res) {
      cout << "No" << endl; // contradiction!!
      return 0;
    }
  }
  // no obvious contradiction found.
  VL mi(c, 0);
  REP(i, 0, c) {
    mi[root[i]] = min(mi[root[i]], dp[i]);
