    }
  }
  */
  bool ok = 1;
  REP(i, 0, n) {
    if (a[i] - dp[cc[i]] + mi[root[cc[i]]] < 0) {
      ok = 0;
    }
  }
  cout << (ok ? "Yes" : "No") << endl;
}

