#define MAXN 200005
struct pnt{
	long long x,y,c;
}p[MAXN];
long long fa[MAXN],fb[MAXN],ma[MAXN],mb[MAXN],da[MAXN],db[MAXN],la[MAXN],lb[MAXN];
long long r,c,n;
bool operator<(pnt x, pnt y){
	return x.x < y.x || x.x == y.x && x.y < y.y;
}
long long finda(long long i){
	if(fa[i] == i)return i;
	else{
		long long v = fa[i];
		fa[i] = finda(v);
		da[i] = da[i] + da[v];
		return fa[i];
	}
}
long long findb(long long i){
	if(fb[i] == i)return i;
	else{
		long long v = fb[i];
		fb[i] = finda(v);
		db[i] = db[i] + db[v];
		return fb[i];
	}
}
long long mergea(long long i, long long j, long long k){
	long long fi = finda(i), fj = finda(j);
	if(fi != fj){
		fa[fi] = fj;
		da[fi] = k + da[j] - da[i];
	}
	else{
		if(da[i] - db[j] != k)
			return -1;
	}
	return fj;
}
long long mergeb(long long i, long long j,long long k){
	long long fi = findb(i), fj = findb(j);
	if(fi != fj){
		fb[fi] = fj;
		db[fi] = k + db[j] - db[i];
	}
	else{
		if(da[i] - db[j] != k)
			return -1;
	}
	return fj;
}

int main()
{
	cin>>r>>c>>n;
	for(long long i=1;i<=n;i++){
		cin>>p[i].x>>p[i].y>>p[i].c;
	}
	sort(p+1,p+n+1);
	memset(la,0,sizeof(la));
	memset(lb,0,sizeof(lb));
	for(long long i=0;i<=r;i++){
		fa[i] = i; da[i] = 0;
	}
	for(long long i=0;i<=c;i++){
		fb[i] = i; db[i] = 0;
	}
	bool flag = true;
	for(long long i=1;i<=n;i++){
		//if(p[i].x == 1)vb[p[i].y] = p[i].c;
		//if(p[i].y == 1)va[p[i].x] = p[i].c;
		if(la[p[i].x]!=0){
			pnt& q = p[la[p[i].x]];
			if(mergeb(p[i].y, q.y, p[i].c-q.c) == -1){
				flag = false;
				break;
			}
		}
		if(lb[p[i].y]!=0){
			pnt& q = p[lb[p[i].y]];
			if(mergea(p[i].x, q.x, p[i].c-q.c) == -1){
				flag = false;
				break;
			}
		}
		la[p[i].x] = i;
		lb[p[i].y] = i;
	}
	if(flag){
		memset(ma,0,sizeof(ma));
		memset(mb,0,sizeof(mb));
		for(long long i=1;i<=r;i++){
			long long k = finda(i);
			ma[k] = min(ma[k],da[i]);
		}
		for(long long i=1;i<=c;i++){
			long long k = findb(i);
			mb[k] = min(mb[k],db[i]);
		}
		for(long long i=1;i<=n;i++){
			long long fi = finda(p[i].x), fj = findb(p[i].y);
			if(p[i].c - da[p[i].x] + ma[fi] < 0){
				flag = false;
				break;
			}
			if(p[i].c - db[p[i].y] + mb[fj] < 0){
				flag = false;
				break;
			}
		}
	}
	if(flag)
		cout <<"Yes"<<endl;
	else
		cout<<"No"<<endl;
	return 0;
}

