}

void update(int x,int y){
    if(!ma[x].count(y)) ma[x][y] = ma[x + 1][y] + ma[x][y +  1] - ma[x + 1][y + 1];
    else if(!ma[x + 1].count(y + 1)) ma[x + 1][y + 1] = ma[x + 1][y] + ma[x][y + 1] - ma[x][y];
    else if(!ma[x].count(y + 1)) ma[x][y + 1] = ma[x][y] + ma[x + 1][y + 1] - ma[x + 1][y];
    else if(!ma[x + 1].count(y)) ma[x + 1][y] = ma[x][y] + ma[x + 1][y + 1] - ma[x][y + 1];
