const ll inf= 5e15;

bool check(const vvec<pll> &lines, ll w) {
    vvec<tll> tv(w);
    for (auto &&line : lines) {
        if (line.size() < 2) continue;
        for (ll i = (ll)(line.size()) - 2; 0 <= i; i--) {
            ll i1, i2, v1, v2;
            std::tie(i1, v1) = line[i];
            std::tie(i2, v2) = line[i + 1];
            pll key(i1, i2);
            ll d = v2 - v1;
            tv[i1].emplace_back(i2, v1, v2);
        }
    }

    vec<ll> vals(tv.size(), inf);
    vec<bool> def(tv.size());
    ll apply = 0;
    for (ll i1 = tv.size() - 1; 0 <= i1; i1--) for (auto &&e : tv[i1]) {
        ll i2, v1, v2;
        std::tie(i2, v1, v2) = e;
        if (!def[i2]) {
            def[i2] = true;
            vals[i2] = v2 - apply;
        } else {
            ll cur = vals[i2] + apply;
            ll cand = v2;
            if (cand < cur) apply += cand - cur;
        }

        if (!def[i1]) {
            def[i1] = true;
            ll diff = v2 - v1;
            vals[i1] = vals[i2] - diff;
        } else {
            ll ok_d = v2 - v1;
            ll cur_d = vals[i2] - vals[i1];
            if (ok_d != cur_d) return false;
        }
    }

    for (auto &&line : lines) for (auto &&e : line) {
        ll i, v;
        std::tie(i, v) = e;
        if (!def[i]) {
            vals[i] = v - apply;
            def[i] = true;
        } else {
            ll cur = vals[i] + apply;
            ll cand = v;
            if (cand < cur) apply += cand - cur;
        }
    }

    for (ll e : vals) if (e + apply < 0) return false;
    return true;
}

bool solve() {
    ll r, c, n;
    std::cin >> r >> c >> n;
    vvec<pll> rows(r), cols(c);
    for (ll i = 0; i < n; i++) {
        ll ri, ci, a;
        std::cin >> ri >> ci >> a;
        ri--; ci--;
        rows[ri].emplace_back(ci, a);
        cols[ci].emplace_back(ri, a);
    }

    for (auto &&v : rows) std::sort(ALL(v));
    for (auto &&v : cols) std::sort(ALL(v));

    if (!(check(rows, c) && check(cols, r))) return false;

    for (auto &&v : rows) {
        for (auto &&e : v) e.first = c - 1 - e.first;
        reverse(ALL(v));
    }
    for (auto &&v : cols) {
        for (auto &&e : v) e.first = r - 1 - e.first;
        reverse(ALL(v));
    }

    if (!(check(rows, c) && check(cols, r))) return false;
    return true;
}

