	if(flag){
		memset(ma,0,sizeof(ma));
		memset(mb,0,sizeof(mb));
		for(long long i=1;i<=r;i++){
			long long k = finda(i);
			ma[k] = min(ma[k],da[i]);
		}
		for(long long i=1;i<=c;i++){
			long long k = findb(i);
			mb[k] = min(mb[k],db[i]);
		}
		for(long long i=1;i<=n;i++){
			long long fi = finda(p[i].x), fj = findb(p[i].y);
			if(p[i].c - da[p[i].x] + ma[fi] < 0){
				flag = false;
				break;
			}
			if(p[i].c - db[p[i].y] + mb[fj] < 0){
				flag = false;
				break;
			}
		}
	}
	if(flag)
		cout <<"Yes"<<endl;
	else
		cout<<"No"<<endl;
	return 0;
}

