	std::vector<std::vector<std::map<std::pair<int, int>, int>>>
		data(R / 16 + 1, std::vector<std::map<std::pair<int, int>, int>>(C / 16 + 1));
	auto count = [&](int r, int c)
	{
		return data[r / 16][c / 16].count(std::make_pair(r % 16, c % 16));
	};
	auto value = [&](int r, int c)->int&
	{
		return data[r / 16][c / 16][std::make_pair(r % 16, c % 16)];
	};
	for (int i{};i < N;++i)
	{
		int r, c, a;
		std::cin >> r >> c >> a;
		value(r, c) = a;
	}
	for (int r = 1;r < R;++r)for (int c = 1;c < C;++c)
	{
		auto lu = count(r, c);
		auto ld = count(r + 1, c);
		auto ru = count(r, c + 1);
		auto rd = count(r + 1, c + 1);
		if (lu + ld + ru + rd == 4)
		{
			if (value(r, c) + value(r + 1, c + 1) != value(r + 1, c) + value(r, c + 1))
			{
				std::cout << "No" << std::endl;
				return;
			}
		}
