				auto v = value(r + 1, c) + value(r, c + 1) - value(r + 1, c + 1);
				if (v < 0)
				{
					std::cout << "No" << std::endl;
					return;
				}
				value(r, c) = v;
				--r;
				c -= 2;
			}
			else if (!rd)
