	for (i = 0; i < h; i++) { if (cnt_r[i] * h <= n) break; }
	if (!solveH(i)) { cout << "No" << endl; return 0; }
	for (i = 0; i < w; i++) { if (cnt_c[i] * w <= n) break; }
	if (!solveW(i)) { cout << "No" << endl; return 0; }
	cout << "Yes" << endl;
	return 0;
}

