void solve(long long R, long long C, long long N, vector<long long> r, vector<long long> c, vector<long long> a){
	map< pair<int,int> , int> mass;
	for(int i = 0 ; i < r.size() ; i++){
		mass[{r[i],c[i]}] = a[i];
	}
	map<int,int> xinc,yinc;
	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		pair<int,int> rig = {y,x+1};
		pair<int,int> dow = {y+1,x};

		if( mass.count(rig) ){
			int diff = mass[rig] - p.second;
			if( xinc.count(x) and xinc[x] != diff ) sayno();
			xinc[x] = diff;
		}

		if( mass.count(dow) ){
			int diff = mass[dow] - p.second;
			if( yinc.count(y) and yinc[y] != diff ) sayno();
			yinc[y] = diff;
		}
	}
	for( auto p : mass ){
		int y = p.first.first;
		int x = p.first.second;
		int v = p.second;
		int val1 = v + xinc[x];
		int val2 = v + yinc[y];
		int val3 = v + xinc[x] + yinc[y];
		pair<int,int> rig = {y,x+1};
		pair<int,int> dow = {y+1,x};
		pair<int,int> dia = {y+1,x+1};

		if( mass.count(rig) and mass[rig] != val1 ) sayno();
		if( mass.count(dow) and mass[dow] != val2 ) sayno();
		if( mass.count(dia) and mass[dia] != val3 ) sayno();

		if( val1 < 0 or val2 < 0 ){
			sayno();
		}
	}
	cout << "Yes" << endl;



}



