int vx[4] = { -1, -1, 0, 0 }, vy[4] = { -1, 0, -1, 0 };
int wx[4] = { 0, 0, 1, 1 }, wy[4] = { 0, 1, 0, 1 };

bool check(int x, int y) {
	for (int i = 0; i < 4; i++) {
		if (x + vx[i] < 0 || y + vy[i] < 0)
			continue;
		int cnt = 0, ch = 0;
		long long b[2][2] = {};
		for (int j = 0; j < 4; j++) {
			if (x + vx[i] + wx[j] >= c || y + vy[i] + wy[j] >= r)
				break;
			if (mp.find(y + vy[i] + wy[j] + (x + vx[i] + wx[j])*c) == mp.end()) {
				b[wy[j]][wx[j]] = -1;
				ch = j;
			}
			else {
				b[wy[j]][wx[j]] = mp[y + vy[i] + wy[j] + (x + vx[i] + wx[j])*c];
				cnt++;
			}
		}
		if (cnt == 4) {
			if (b[0][0] + b[1][1] != b[1][0] + b[0][1]) {
				return false;
			}
		}
		else if (cnt == 3) {
			if (ch == 0) {
				mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] = b[1][0] + b[0][1] - b[1][1];
			}
			else if (ch == 1) {
				mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] = b[0][0] + b[1][1] - b[0][1];
			}
			else if (ch == 2) {
				mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] = b[0][0] + b[1][1] - b[1][0];
			}
			else {
				mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] = b[0][1] + b[1][0] - b[0][0];
			}
			if (mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] < 0) {
				return false;
			}
			ri.push_back(y + vy[i] + wy[ch]+1);
			ci.push_back(x + vx[i] + wx[ch]+1);
			a.push_back(mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c]);
		}
	}
	return true;
}

