bool bfs()
{

  for (int i = 1; i <= R + C; i++) {
    if (vis[i]) {
      continue;
    }
    int b = 0, e = 1;
    x[0] = i;
    vis[i] = true;
    A[i] = 0;
    while (b < e) {
      for (int j = 0; j < (int) G[x[b]].size(); j++) {
        int u = G[x[b]][j].v;
        int w = G[x[b]][j].w;
        if (vis[u]) {
          if (A[x[b]] + A[u] != w) {
            return false;
            }
          continue;
        }
        x[e] = u;
        A[u] = w - A[x[b]];
        vis[u] = true;
        e++;
      }
      b++;
    }


long long m1 = INF, m2 = INF;
    for (int j = 0; j < e; j++) {
      if (x[j] <= R) {
        m1 = min(m1, A[x[j]]);
      } else {
        m2 = min(m2, A[x[j]]);
      }
    }
    if (m1 + m2 < 0) {
      return false;
    }
}

    return true;


}


bool judge()
{

    memset(vis,0,sizeof(vis));
    for(int i = 1;i <= R;++i)
        if(!vis[i])
        {
            vis[i] = 1;
            A[i] = 0;

            cur = 0;
            if(!dfs(i)) return false;


            LL Minr = INF;
            LL Minc = INF;
