//                if(vis[i])
//                Minc = min(Minc,A[i]);

            for(int j = 0;j < cur;++j)
            {
                int t = seq[i];
                if(t <= R)
                    Minr = min(Minr,A[t]);
                else
                    Minc = min(Minc,A[t]);

            }
            if(Minr + Minc < 0) return false;

        }
    return true;
}

