inline bool has_num(int y, int x){
    return (num.find(y) != end(num) and num[y].find(x) != end(num[y]));
}

bool dfs(int y, int x){
    if(used[y][x]) return true;
    used[y][x] = true;

    bool ret = true;
    rep(i, 4){
        int ny = y + dy[i], nx = x + dx[i];
        if(not has_num(y, nx) or not has_num(ny, x)) continue;
        int nnum = num[y][nx] + num[ny][x] - num[y][x];
        if(nnum >= 0 and (not has_num(ny, nx) or num[ny][nx] == nnum)){
            num[ny][nx] = nnum;
            ret &= dfs(ny, nx);
        }
        else {
            ret = false;
        }
        if(not ret) break;
    }

    return ret;
}

signed main(void){
    int h, w; cin >> h >> w;
    int n; cin >> n;
    yxs = vector<P>(n);
    rep(i, n){
        int y, x, a; cin >> y >> x >> a;
        y--, x--;
        num[y][x] = a;
        yxs[i] = P(y, x);
    }
    sort(_all(yxs));

    bool res = true;
    rep(i, n){
        int y, x; tie(y, x) = yxs[i];
        res &= dfs(y, x);
        if(not res) break;
    }

    cout << (res ? "Yes" : "No") << endl;

    return 0;
}

#include <iostream>
#include <map>
using namespace std;

int R, C, N;
bool mod;
map<pair<int, int>, int> grid;

void insert(int r, int c, int v)
{
    mod = true;
    grid.insert(make_pair(make_pair(r, c), v));
}

bool validate(int r, int c)
{
    int cnt = 0, cell[4] = {-1, -1, -1, -1};

    for (int i = 0; i < 4; i++) {
        auto it = grid.find(make_pair(r + (i >> 1), c + (i & 1)));
        if (it != grid.end()) {
            cell[i] = it->second;
            cnt++;
        }
    }

    if (cnt == 3) {
        if (cell[0] == -1) {
            if (cell[1] + cell[2] < cell[3])
                return false;
            else
                insert(r, c, cell[1] + cell[2] - cell[3]);
        } else if (cell[1] == -1) {
            if (cell[0] + cell[3] < cell[2])
                return false;
            else
                insert(r, c + 1, cell[0] + cell[3] - cell[2]);
        } else if (cell[2] == -1) {
            if (cell[0] + cell[3] < cell[1])
                return false;
            else
                insert(r + 1, c, cell[0] + cell[3] - cell[1]);
        } else if (cell[3] == -1) {
            if (cell[1] + cell[2] < cell[0])
                return false;
            else
                insert(r + 1, c + 1, cell[1] + cell[2] - cell[0]);
        }
    } else if (cnt == 4) {
        if (cell[0] + cell[3] != cell[1] + cell[2])
            return false;
    }

    return true;
}

bool run(void)
{
    pair<int, int> p;

    while (true) {
        mod = false;

        for (auto it = grid.begin(); it != grid.end(); it++) {
            p = it->first;
            for (int i = max(1, p.first - 1); i < min(R, p.first + 1); i++)
                for (int j = max(1, p.second - 1); j < min(C, p.second + 1); j++)
                    if (!validate(i, j))
                        return false;
        }

        if (!mod)
            return true;
    }
}

int main(void)
{
    int a, b, c;

    cin >> R >> C >> N;
    for (int i = 0; i < N; i++) {
        cin >> a >> b >> c;
        grid.insert(make_pair(make_pair(a, b), c));
    }

    if (run())
        cout << "Yes" << endl;
    else
        cout << "Yes" << endl;
}

