#define ll long long
#define maxn 100005
using namespace std;

struct node
{
	ll x,y,val;
}tr[maxn];
ll t,n,r,c;
ll fa[maxn],del[maxn],mn1[maxn],mn2[maxn];//del[i]指i到父节点的差值
const ll oo=2e16;

bool cmp(node a,node b)
{
	if(a.y!=b.y)
	return a.y<b.y;
	else return a.x<b.x;
}//以y轴为第一关键字从小到大排序

ll find(ll a)
{
	if(fa[a]==a)
	return a;
	ll fax=find(fa[a]);
	del[a]+=del[fa[a]];//合并差值
	return fa[a]=fax;
}//找父亲

ll unionn(ll a,ll b,ll v)
{
	ll fax=find(a),fay=find(b);
	if(fax!=fay)
	{
		del[fax]=v+del[b]-del[a];//推导的性质
		fa[fax]=fay;//合并并查集
		return 1;
	}//不在同一个集合内
	else
	{
		if(del[a]!=del[b]+v)return 0;
		else return 1;
	}//在同一个集合内
}//并查集合并

int main()
{
	for(int i=1;i<=100000;++i)
	mn1[i]=mn2[i]=oo;
	ll flag=1;
	scanf("%lld%lld%lld",&r,&c,&n);
	for(ll i=1;i<=r;++i)
	{
		fa[i]=i;
		del[i]=0;
	}//初始化并查集
	for(ll i=1;i<=n;++i)
	{
		ll x,y,z;
		scanf("%lld%lld%lld",&x,&y,&z);
		tr[i].x=x;
		tr[i].y=y;
		tr[i].val=z;
		if(z<0)flag=0;
	}
	if(!flag)
	{
		printf("No\n");
		return 0;
	}
	if(r==1)
	{
		printf("Yes\n");
		return 0;
	}//特判行为1
	sort(tr+1,tr+1+n,cmp);//初始化排序
	for(ll i=1;i<n;++i)
	{
		if(tr[i].y==tr[i+1].y)
		{
			if(!unionn(tr[i].x,tr[i+1].x,tr[i+1].val-tr[i].val))//顺便结合两行
			flag=0;//与所得结论矛盾
		}
	}//判断是否矛盾
	if(!flag)
	{
		printf("No\n");
		return 0;
	}
	for(ll i=1;i<=n;++i)
	{
		ll fax=find(tr[i].x);
		mn1[fax]=min(mn1[fax],tr[i].val+del[tr[i].x]);
	}//求父节点行上一点的最小值
	for(ll i=1;i<=r;++i)
	{
		ll fax=find(i);
		mn2[fax]=min(mn2[fax],-del[i]);
	}//求某一行的父节点可能的最小值
	for(ll i=1;i<=r;++i)
	{
		if(fa[i]==i&&mn1[i]+mn2[i]<0)
		{
			flag=0;
			break;
		}
	}
	if(!flag)
	printf("No\n");
	else printf("Yes\n");
	return 0;
}

