      judge -= as[i];
      cnt --;
    }
    if(rs[i] == 1 && cs[i] == C) {
      judge += as[i];
      cnt --;
    }
    if(rs[i] == R && cs[i] == C) {
      judge -= as[i];
      cnt ++;
    }
  }

  if(cnt == 0 && judge == 0) {
    cout << "Yes" << endl;
    exit(0);
  }
  else {
    if(cnt < 0 && judge <= 0) {
      cout << "Yes\n";
      exit(0);
    }
    else if(cnt > 0 && judge >= 0) {
      cout << "Yes\n";
      exit(0);
    }
    else {
      cout << "No\n";
      exit(0);
    }
  }

  return 0;
}

