inline int min(const int &a,const int &b){return a<b?a:b;}
inline bool cmp1(point a,point b){return a.x<b.x;}
inline bool cmp2(point a,point b){return a.y<b.y;}
int find1(int n)
{
	if(f1[n]==n) return n;
	int fa=find1(f1[n]);
	w1[n]+=w1[f1[n]];
	return f1[n]=fa;
}
int find2(int n)
{
	if(f2[n]==n) return n;
	int fa=find2(f2[n]);
	w2[n]+=w2[f2[n]];
	return f2[n]=fa;
}
inline bool merge1(int x,int y,int z)
{
	int t1=find1(x),t2=find1(y);
	if(t1!=t2)
	{
		f1[t1]=t2,w1[t1]=z+w1[y]-w1[x];
		return 1;
	}
	return w1[x]==z+w1[y];
}
inline bool merge2(int x,int y,int z)
{
	int t1=find2(x),t2=find2(y);
	if(t1!=t2)
	{
		f2[t1]=t2,w2[t1]=z+w2[y]-w2[x];
		return 1;
	}
	return w2[x]==z+w2[y];
}
int main()
{
	scanf("%d%d%d",&n,&m,&k);
	for(int i=1;i<=n;i++) f1[i]=i,w1[i]=0;
	for(int i=1;i<=m;i++) f2[i]=i,w2[i]=0;
	for(int i=1;i<=k;i++)
	{
		scanf("%d%d%d",&a[i].x,&a[i].y,&a[i].num);
