using std::vector;

bool fill_corner(vector< vector<int> >& grid)
{
    int r = grid.size() - 1;
    int c = grid[r].size() - 1;

    int &lt = grid[r-1][c-1];
    int &rt = grid[r-1][c];
    int &ld = grid[r][c-1];
    if (lt >= 0 and rt >= 0 and ld >= 0) {
        grid[r][c] = rt + ld - lt;
        return true;
    }
    return false;
}
bool fill_right(vector< vector<int> >& grid, int r)
{
    int c = grid[r].size() - 1;

    int &lt = grid[r][c-1];
    int &ld = grid[r+1][c-1];
    int &rd = grid[r+1][c];
    if (lt >= 0 and ld >= 0 and rd >= 0) {
        grid[r][c] = lt + rd - ld;
        return true;
    }
    return false;
}

bool fill_bottom(vector< vector<int> >& grid, int c)
{
    int r = grid.size() - 1;

    int &lt = grid[r-1][c];
    int &rt = grid[r-1][c+1];
    int &rd = grid[r][c+1];
    if (lt >= 0 and rt >= 0 and rd >= 0) {
        grid[r][c] = lt + rd - rt;
        return true;
    }
    return false;
}

bool fill(vector< vector<int> >& grid, int r, int c)
{
    if (r == grid.size() - 1 and c == grid[r].size() - 1) {
        return fill_corner(grid);
    }

    if (r == grid.size() - 1) return fill_bottom(grid, c);
    if (c == grid[r].size() - 1) return fill_right(grid, r);

    int &rt = grid[r][c+1];
    int &ld = grid[r+1][c];
    int &rd = grid[r+1][c+1];
    if (rt >= 0 and ld >= 0 and rd >= 0) {
        grid[r][c] = rt + ld - rd;
        return true;
    }
    return false;
}

bool check(vector< vector<int> >& grid)
{
    int R = grid.size();
    int C = grid[0].size();
    int RC = R >= C ? R : C;

    // fill the grid if possible
    while (true) {
        bool changed = false;
        for (int r = 0; r < R; ++r) {
            for (int c = 0; c < C; ++c) {
                if (grid[r][c] >= 0) continue;
                if (fill(grid, r, c)) {
                    if (grid[r][c] < 0) return false;
                    changed = true;
                }
            }
        }
        if (!changed) break;
    }
    for (int r = 0; r < R; ++r) {
        for (int c = 0; c < C; ++c) {
            int &lt = grid[r][c];
            if (lt < 0) continue;
            for (int d = 1; d < RC; ++d) {
                if (r + d >= R or c + d >= C) break;
                int &rt = grid[r][c+d];
                int &ld = grid[r+d][c];
                int &rd = grid[r+d][c+d];
                if (rt >= 0 and ld >= 0 and rd >= 0 and lt + rd != rt + ld) {
                    return false;
                }
            }
        }
    }
    return true;
}

int main()
{
    using std::cin;

    int R, C, N;
    cin >> R >> C >> N;

    vector< vector<int> > grid(R, vector<int>(C, -1));
    for (int i = 0; i < N; ++i) {
        int r, c, a;
        cin >> r >> c >> a;
        grid[r-1][c-1] = a;
    }

    std::cout << (check(grid) ? "Yes" : "No") << std::endl;
    return 0;
}

