using namespace std;

typedef long long ll;
typedef pair<int, int> pii;

#define fi first
#define se second
#define mp make_pair
#define fastIO ios::sync_with_stdio(false);cin.tie(0);cout.tie(0);

const int N = (int)1e5 + 9;
vector<pii> L[N];
vector<pii> R[N];

int x[N];
int y[N];
bool lf[N];
bool rf[N];

void dfs(int u, int part){
  if(part == 0){
    lf[u]=true;
    for(auto p : L[u]){
      if(!rf[p.fi]){
        y[p.fi] = p.se - x[u];
        dfs(p.fi, 1);
      }
    }
  }
  else{
    rf[u]=true;
    for(auto p : R[u]){
      if(!lf[p.fi]){
        x[p.fi] = p.se - y[u];
        dfs(p.fi,0);
      }
    }
  }
}

int main(){
  fastIO;
  int n, m, q;
  cin >> n >> m >> q;
  int r[q], c[q], a[q];
  for(int i = 0 ; i < q; i ++ ){
    cin >> r[i] >> c[i] >> a[i];
    L[r[i]].push_back(mp(c[i],a[i]));
    R[c[i]].push_back(mp(r[i],a[i]));
  }
  dfs(1,0);
  for(int i = 1; i <= n; i ++ )
    if(!lf[i]) dfs(i,0);
  for(int i = 1; i <= m ; i ++ )
    if(!rf[i]) dfs(i,1);
  for(int i = 0 ; i < q; i ++ ){
    if(x[r[i]] + y[c[i]] != a[i]){
      cout << "No\n";
      return 0;
    }
  }
  int cl = x[1], cr = y[1];
  for(int i = 1; i <= n; i ++ )
    cl = min(cl, x[i]);
  for(int i = 1; i <= m; i ++ )
    cr = min(cr, y[i]);
  if(cl + cr >= 0){
    cout << "Yes\n";
  }
  else{
    cout << "No\n";
  }
  return 0;
}

