using namespace std;

class Counting {
	unsigned long long p, n;
	vector<long long> invMemo, facMemo, facInvMemo;
public:
	Counting(unsigned long long nn, unsigned long long np) {
		p = np;
		n = nn;
		invMemo.resize(n + 1);
		facMemo.resize(n + 1);
		facInvMemo.resize(n + 1);
		facMemo[0] = 1;
		facMemo[1] = 1;
		facInvMemo[0] = 1;
		facInvMemo[1] = 1;
		invMemo[0] = 0;
		invMemo[1] = 1;
		for (unsigned long long i = 2; i <= n; i++) {
			invMemo[i] = p - (p / i)*invMemo[p%i] % p;
			facMemo[i] = (facMemo[i - 1] * i) % p;
			facInvMemo[i] = (facInvMemo[i - 1] * invMemo[i]) % p;
		}
	}
	unsigned long long fac(unsigned long long k) {
		return facMemo[k];
	}
	unsigned long long facInv(unsigned long long k) {
		return facInvMemo[k];
	}
	unsigned long long choose(unsigned long long n, unsigned long long k) {
		if (!(0 <= k && k <= n))
			return 0;
		return (((facMemo[n] * facInvMemo[k]) % p)*facMemo[n - k]) % p;
	}
	unsigned long long divide(unsigned long long a, unsigned long long b) {
		return (a * invMemo[b]) % p;
	}
	unsigned long long mod(unsigned long long a) {
		a %= p;
		if (a < 0) a += p;
		return a;
	}
	unsigned long long power(unsigned long long a, unsigned long long e) {
		unsigned long long ans = 1;
		for (; e > 0; e /= 2) {
			if (e % 2 != 0)
				ans = ans * a % p;
			a = a*a%p;
		}
		return ans;
	}
};

int r, c, n;
vector<int> ri, ci;
vector<long long> a;
map<unsigned long long, long long> mp;
int vx[4] = { -1, -1, 0, 0 }, vy[4] = { -1, 0, -1, 0 };
int wx[4] = { 0, 0, 1, 1 }, wy[4] = { 0, 1, 0, 1 };

bool check(int x, int y) {
	for (int i = 0; i < 4; i++) {
		if (x + vx[i] < 0 || y + vy[i] < 0)
			continue;
		int cnt = 0, ch = 0;
		long long b[2][2] = {};
		for (int j = 0; j < 4; j++) {
			if (x + vx[i] + wx[j] >= c || y + vy[i] + wy[j] >= r)
				break;
			if (mp.find(y + vy[i] + wy[j] + (x + vx[i] + wx[j])*c) == mp.end()) {
				b[wy[j]][wx[j]] = -1;
				ch = j;
			}
			else {
				b[wy[j]][wx[j]] = mp[y + vy[i] + wy[j] + (x + vx[i] + wx[j])*c];
				cnt++;
			}
		}
		if (cnt == 4) {
			if (b[0][0] + b[1][1] != b[1][0] + b[0][1]) {
				return false;
			}
		}
		else if (cnt == 3) {
			if (ch == 0) {
				mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] = b[1][0] + b[0][1] - b[1][1];
			}
			else if (ch == 1) {
				mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] = b[0][0] + b[1][1] - b[0][1];
			}
			else if (ch == 2) {
				mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] = b[0][0] + b[1][1] - b[1][0];
			}
			else {
				mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] = b[0][1] + b[1][0] - b[0][0];
			}
			if (mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c] < 0) {
				return false;
			}
			ri.push_back(y + vy[i] + wy[ch]+1);
			ci.push_back(x + vx[i] + wx[ch]+1);
			a.push_back(mp[y + vy[i] + wy[ch] + (x + vx[i] + wx[ch])*c]);
		}
	}
	return true;
}

