#include <bits/stdc++.h>
using namespace std;
const int maxn = 400400;
struct tile {
	int r, c, a;
};
vector<tile> tiles[2][maxn];
map<int, int> val[maxn];
map<int, int> upe[maxn];
int main(){
	int r, c;
	cin >> r >> c;
	int n;
	cin >> n;
	for(int i = 0; i < n; i++){
		int x, y, z; cin >> x >> y >> z;
		val[x][y] = z;
		tiles[0][x - y + maxn / 2].push_back((tile){x, y, z});
		tiles[1][x + y].push_back((tile){x, y, z});
	}
	for(int rot = 0; rot < 2; rot++){
		for(int i = 0; i < maxn; i++){
			sort(tiles[rot][i].begin(), tiles[rot][i].end(), [](tile a, tile b){
				return a.r < b.r;
			});
		}
	}
	auto get_value = [&](int x, int y){
		auto it = val[x].find(y);
		if(it == val[x].end()) return -1;
		return it->second;
	};
	auto get_upper = [&](int x, int y){
		auto it = upe[x].find(y);
		if(it == upe[x].end()) return INT_MAX;
		return it->second;
	};
	auto bad = [](){
		cout << "No" << endl;
		exit(0);
	};
	for(int rot = 0; rot < 2; rot++){
		for(int i = 0; i < maxn; i++){
			int len = tiles[rot][i].size();
			for(int j = 0; j < len - 1; j++){
				vector<int> xs = {tiles[rot][i][j].r, tiles[rot][i][j+1].r};
				vector<int> ys = {tiles[rot][i][j].c, tiles[rot][i][j+1].c};
				if(xs[0] > xs[1]) swap(xs[0], xs[1]);
				if(ys[0] > ys[1]) swap(ys[0], ys[1]);
				/**
				  AB
				  CD
				  **/
				int A = get_value(xs[0], ys[0]);	
				int B = get_value(xs[0], ys[1]);
				int C = get_value(xs[1], ys[0]);
				int D = get_value(xs[1], ys[1]);
				int cnt_neg = (A == -1) + (B == -1) + (C == -1) + (D == -1);
				if(cnt_neg > 2);
				else if(cnt_neg == 0){
					if(A + D != B + C){
						bad();
					}
				} else if(cnt_neg == 2){
					if(A == -1){
						int nupper = min(get_upper(xs[0], ys[0]), B + C);
						upe[xs[0]][ys[0]] = nupper;
						upe[xs[1]][ys[1]] = nupper;
					} else {
						int nupper = min(get_upper(xs[1], ys[0]), A + D);
						upe[xs[1]][ys[0]] = nupper;
						upe[xs[0]][ys[1]] = nupper;
					}
				} else {
					if(A == -1){
						if(B + C < D) bad();
					       	int nval = B + C - D;
						int upper = get_upper(xs[0], ys[0]);
						if(nval > upper) bad();
						val[xs[0]][ys[0]] = nval;	
					} else if(B == -1){
						if(A + D < C) bad();
						int nval = A + D - C;
						int upper = get_upper(xs[0], ys[1]);
						if(nval > upper) bad();
						val[xs[0]][ys[1]] = nval;
					} else if(C == -1){
						if(A + D < B) bad();
						int nval = A + D - B;
						int upper = get_upper(xs[1], ys[0]);
						if(nval > upper) bad();
						val[xs[1]][ys[0]] = nval;
					} else {
						if(B + C < A) bad();
						int nval = B + C - A;
						int upper = get_upper(xs[1], ys[1]);
						if(nval > upper) bad();
						val[xs[1]][ys[1]] = nval;
					}
				}
			}
		}
	}
	for(int i = 0; i < maxn; i++){
		for(auto p : upe[i]){
			if(val[i][p.first] > p.second) bad();
		}
	}
	cout << "Yes" << endl;
	return 0;
}

