int check(int x, int y)
{
	if(!(0 <= x && x <= R-1)) return 0;
	if(!(0 <= y && y <= C-1)) return 0;

	int cnt = 0;
	for(int i = 0; i < 4; i++) {
		if(inMap[Pii(x + dx[i], y + dy[i])]) cnt++;
	}

	if(cnt == 4) {
		//cout << "-4- " << x << " " << y << endl;
		//cout << MP[Pii(x,y)] + MP[Pii(x+1, y+1)] << " " << (MP[Pii(x+1, y)] + MP[Pii(x, y+1)]) << endl;
		return !((MP[Pii(x,y)] + MP[Pii(x+1, y+1)]) == (MP[Pii(x+1, y)] + MP[Pii(x, y+1)]));
	}
	if(cnt == 3) {
		for(int i = 0; i < 4; i++) {
			if(!inMap[Pii(x + dx[i], y + dy[i])]) {
				int sum1 = (MP[Pii(x,y)] + MP[Pii(x+1, y+1)]);
				int sum2 = (MP[Pii(x+1, y)] + MP[Pii(x, y+1)]);
				int sub = ((i%3)? (sum1 - sum2): (sum2 - sum1));
				//cout << endl << "-3- " << x + dx[i] << "  " << y + dy[i] <<  endl;
