int* matrix_get_var(unordered_map<int, unordered_map<int, int>>& matrix, int i, int j) {
	auto it = matrix.find(i);
	if(it == matrix.end()) {
		return nullptr;
	}

	auto arr = it->second;
	auto it2 = arr.find(j);
	if(it2 == arr.end()) {
		return nullptr;
	}

	return new int(it2->second);
}

bool fill_matrix_square(unordered_map<int, unordered_map<int, int>>& matrix, int i, int j, bool& changed) {
	changed = false;

	int filled = 0;
	int* v1 = matrix_get_var(matrix, i, j);
	if(v1) {
		filled++;
	}
	int* v2 = matrix_get_var(matrix, i + 1, j);
	if(v2) {
		filled++;
	}
	int* v3 = matrix_get_var(matrix, i, j + 1);
	if(v3) {
		filled++;
	}
	int* v4 = matrix_get_var(matrix, i + 1, j + 1);
	if(v4) {
		filled++;
	}

	if(filled == 0 || filled == 1 || filled == 2) {
		return true;
	}

	if(!v1) {
		matrix[i][j] = -1;
		v1 = &matrix[i][j];
	}
	if(!v2) {
		matrix[i + 1][j] = -1;
		v2 = &matrix[i + 1][j];
	}
	if(!v3) {
		matrix[i][j + 1] = -1;
		v3 = &matrix[i][j + 1];
	}
	if(!v4) {
		matrix[i + 1][j + 1] = -1;
		v4 = &matrix[i + 1][j + 1];
	}

	if(filled == 4) {
		bool ret =
			*v1 + *v4 == *v2 + *v3;

		if(!ret) DBGOUT << "failed " << __LINE__;
		return ret;
	}

	if(filled == 3) {
		changed = true;
		if(matrix[i][j] == -1) {
			matrix[i][j] = matrix[i + 1][j] + matrix[i][j + 1] - matrix[i + 1][j + 1];
			bool ret = matrix[i][j] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(matrix[i + 1][j + 1] == -1) {
			matrix[i + 1][j + 1] = matrix[i + 1][j] + matrix[i][j + 1] - matrix[i][j];
			bool ret = matrix[i + 1][j + 1] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(matrix[i + 1][j] == -1) {
			matrix[i + 1][j] = matrix[i][j] + matrix[i + 1][j + 1] - matrix[i][j + 1];
			bool ret = matrix[i + 1][j] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(matrix[i][j + 1] == -1) {
			matrix[i][j + 1] = matrix[i][j] + matrix[i + 1][j + 1] - matrix[i + 1][j];
			bool ret = matrix[i][j + 1] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
	}

	return true;
}

