			if (DI.first <= 0 || DI.first > R || DI.second <= 0 || DI.second > C) continue;

			int cnt = 0;
			if (G.end() != G.find(UD))cnt += 1;
			if (G.end() != G.find(SI))cnt += 4;
			if (G.end() != G.find(DI))cnt += 9;
			if (cnt == 5)
			{
				int d = G[UD] + G[SI] - G[p];
				if (d < 0)
				{
					flag = 0;
					break;
				}
				Q.push(DI);
				G.insert({ DI,d });
			}
			if (cnt == 10)
			{
				int d = G[p] + G[DI] - G[UD];
				if (d < 0)
				{
					flag = 0;
					break;
				}
				Q.push(SI);
				G.insert({ SI,d });
			}
			if (cnt == 13)
			{
				int d = G[p] + G[DI] - G[SI];
				if (d < 0)
				{
					flag = 0;
					break;
				}
				Q.push(UD);
				G.insert({ UD,d });
			}
			if (cnt == 14)
			{
				if (G[p] + G[DI] != G[UD] + G[SI])
				{
					flag = 0;
					break;
				}
			}

		}

	}
	if (flag)cout << "Yes" << endl;
	else cout << "No" << endl;

