bool dfs1(int v) {
	was[v] = true;
	assert(vals[v].snd >= 0);
	assert(vals[v].fst == 0);
	for (const auto& e : g[v]) {
		int to = e.fst;
		ll sum = e.snd;
		if  (vals[to].snd != -1) {
			if  (vals[v].snd + vals[to].snd != sum) {
				return false;
			}
		} else {
			vals[to] = mp(0, sum - vals[v].snd);
			if  (vals[to].snd < 0) {
				return false;
			}
		}
		if  (!was[to]) {
			if  (!dfs1(to)) {
				return false;
			}
		}
	}
	return true;
}

bool dfs2(int v, ll& low, ll& up, vi& vs) {
	ll a, b;
	tie(a, b) = vals[v];

	if  (a == 0) {
		if  (b < 0) {
			return false;
		}
	} else if  (a > 0) {
		low = max(low, (-b + a - 1) / a);
	} else {
		assert(a < 0);
		up = max(up, b / (-a));
	}

	vs.pb(v);
	was[v] = true;
	for (const auto& e : g[v]) {
		int to = e.fst;
		ll sum = e.snd;
		if  (was[to]) {
			ll c, d;
			tie(c, d) = vals[to];
			ll right = sum - (b + d);
			ll left = a + c;
			if  (left == 0) {
				if  (right != 0) {
					return false;
				}
			} else if  (right % left != 0) {
				return false;
			}
			low = max(low, right / left);
			up = min(up, right / left);
			continue;
		}
		vals[to].fst = -a;
		vals[to].snd = -b + sum;
		dfs2(to, low, up, vs);
	}

	return true;
}

