	vals[v] = mp(1, 0);
	ll low = -INF;
	ll up = INF;
	vi vs;
	if  (!dfs2(v, low, up, vs)) {
		return false;
	}
	if  (up < 0 || low > up) {
		return false;
	}
	for (int u : vs) vals[u] = mp(-1, -1);
	vals[v] = mp(0, up);
	return true;
}

