	// 	}
	// }
	// puts("----");

	memset (was, 0, sizeof was);
	forn(i, R + C) {
		if (vals[i].snd != -1 && !was[i]) {
			if  (!dfs1(i)) {
				return false;
			}
		}
	}

	forn(i, R + C) {
		if  (!was[i]) {
			if  (!solve_comp(i)) {
				return false;
			}
		}
	}

	// forn(i, R + C) {
	// 	printf("%d: %lld %lld\n", i, vals[i].fst, vals[i].snd);
	// 	for (auto e : g[i]) {
