void init(){
  REP(i,MAX)seg[i+MAX-1]=dist[i];
  FORR(i,0,MAX-1)seg[i]=min(seg[2*i+1],seg[2*i+2]);
  REP(i,2*MAX)sum[i]=0;
}
void add(int l,int r,ll v,int a,int b,int k){
  if(r<=a || b<=l)return;
  if(l<=a && b<=r){
    sum[k] += v;
    seg[k] += v;
  }else{
    int m = (a+b)/2;
    add(l,r,v,a,m,2*k+1);
    add(l,r,v,m,b,2*k+2);
    seg[k] = min(seg[2*k+1],seg[2*k+2])+sum[k];
  }
}
void add(int l,int r,ll v){
  add(l,r,v,0,MAX,0);
}
ll query(int l,int r,int a,int b,int k){
  if(r<=a || b<=l)return 1e18;
  if(l<=a && b<=r){
    return seg[k];
  }else{
    int m = (a+b)/2;
    return min(query(l,r,a,m,2*k+1),query(l,r,m,b,2*k+2))+sum[k];
  }
}
ll query(int l,int r){
  return query(l,r,0,MAX,0);
}

