bool check(int x,int y){
  int cnt=4;

  cnt-=mp.count(P(x,y));
  cnt-=mp.count(P(x+1,y));
  cnt-=mp.count(P(x,y+1));
  cnt-=mp.count(P(x+1,y+1));
  if(cnt==0){
    if( mp[P(x,y)]+mp[P(x+1,y+1)] == mp[P(x,y+1)]+mp[P(x+1,y)])return true;
    else return false;
  }
  if(cnt==1){
    if(mp.count(P(x,y))==0){
      mp[ P(x,y) ]=mp[P(x+1,y)]+mp[P(x,y+1)]-mp[P(x+1,y+1)];
      if(!used[P(x,y)]){
        Q.push(P(x,y));
        used[P(x,y)]=true;
      }

    }else if(mp.count(P(x+1,y))==0){
      mp[ P(x+1,y) ]=mp[P(x,y)]+mp[P(x+1,y+1)]-mp[P(x,y+1)];
      if(!used[P(x+1,y)]){
        Q.push(P(x+1,y));
        used[P(x+1,y)]=true;
      }

    }else if(mp.count(P(x,y+1))==0){
      mp[ P(x,y+1) ]=mp[P(x,y)]+mp[P(x+1,y+1)]-mp[P(x+1,y)];
      if(!used[P(x,y+1)]){
        Q.push(P(x,y+1));
        used[P(x,y+1)]=true;
      }

    }else if(mp.count(P(x+1,y+1))==0){
      mp[ P(x+1,y+1) ]=mp[P(x+1,y)]+mp[P(x,y+1)]-mp[P(x,y)];
      Q.push(P(x+1,y+1));
      if(!used[P(x+1,y+1)]){
        Q.push(P(x+1,y+1));
        used[P(x+1,y+1)]=true;
      }

    }

  }

  if(cnt==2){
    int total=0;
    bool fa=false,fb=false,fc=false,fd=false;

    if( mp.count(P(x,y))>0 ) total += mp[P(x,y)], fa=true;
    if( mp.count(P(x+1,y))>0 ) total += mp[P(x+1,y)], fb=true;
    if( mp.count(P(x,y+1))>0 ) total += mp[P(x,y+1)], fc=true;
    if( mp.count(P(x+1,y+1))>0 ) total += mp[P(x+1,y+1)], fd=true;

    if(total==0 && fa==true && fd==true){
      mp[ P(x,y) ]=0;
      Q.push(P(x,y));

      mp[ P(x+1,y+1) ]=0;
      Q.push(P(x+1,y+1));
    }else if(total==0 && fb==true && fc==true ){
      mp[ P(x,y+1) ]=0;
      Q.push(P(x,y+1));

      mp[ P(x+1,y) ]=0;
      Q.push(P(x+1,y));
    }

  }
  return true;
}


bool solve(){
  while(!Q.empty()){
    P p=Q.front();Q.pop();
    int px=p.first;
    int py=p.second;
    used[P(px,py)]=true;
    if( mp[P(px,py)] < 0 )return false;

    for(int dx=-1;dx<=0;dx++){
      for(int dy=-1;dy<=0;dy++){

        if(px+dx<0 || py+dy<0)continue;
        if(R<=px+dx+1 || C<=py+dy+1)continue;

        if( check(px,py) == false )return false;

      }
    }
  }
  return true;
}

