  for(int i=0;i<N;i++){
    scanf("%d %d %d",&r[i],&c[i],&a[i]);
    r[i]--,c[i]--;

    mp[ P(r[i],c[i]) ]=a[i];
    Q.push( P(r[i],c[i]) );
  }

  cout<< ( solve()? "Yes":"No") <<endl;

