ll a[N];
ll L, R;

bool dfs(int v) {
    if (v < n)
        L = max(L, -a[v]);
    else
        R = min(R, a[v]);
    used[v] = 1;
    for (pii e : g[v]) {
        int u = e.first;
        int w = e.second;
        if (used[u]) {
            if (a[v] + a[u] != w) return false;
        } else {
            a[u] = w - a[v];
            if (!dfs(u)) return false;
        }
    }
    return true;
}

