    exit(0);
}


unordered_map<int, lint> input_data[Rmax];

int main()
{
    cin >> R >> C >> N;

    REP(_, N)
    {
        lint r, c, a;
        cin >> r >> c >> a;
        r--;
        c--;
        r2c[r].push_back(pint(c, a));
        c2r[c].push_back(pint(r, a));
        input_data[r][c] = a;
    }

    vector<bool> used(C);
    REP(c, C) if (!used[c] and c2r[c].size())
    {
        unordered_map<int, lint> d_R, d_C;
        queue<pint> to_visit;
        set<pint> used_p;
        to_visit.push(pint(c2r[c][0].first, c));

        d_C[c] = 0;
        d_R[c2r[c][0].first] = 0;

        while (!to_visit.empty())
        {
            pint now = to_visit.front();
            to_visit.pop();

            used_p.insert(now);
            if (r2c[now.first].size())
            {
                for (auto pa_nxt : r2c[now.first])
                {
                    pint nxt = make_pair(now.first, pa_nxt.first);
                    if (d_C.count(nxt.second) && d_C[nxt.second] != d_C[now.second] + pa_nxt.second - input_data[now.first][now.second]) NO();
                    if (used_p.count(nxt) == 0)
                    {
                        used_p.insert(nxt);
                        to_visit.push(nxt);
                        d_C[nxt.second] = d_C[now.second] + pa_nxt.second - input_data[now.first][now.second];
                    }
                }
                r2c[now.first].clear();
            }

            if (c2r[now.second].size())
            {
                for (auto pa_nxt : c2r[now.second])
                {
                    pint nxt = make_pair(pa_nxt.first, now.second);
                    if (d_R.count(nxt.first) && d_R[nxt.first] != d_R[now.first] + pa_nxt.second - input_data[now.first][now.second]) NO();
                    if (used_p.count(nxt) == 0)
                    {
                        used_p.insert(nxt);
                        to_visit.push(nxt);
                        d_R[nxt.first] = d_R[now.first] + pa_nxt.second - input_data[now.first][now.second];
                    }
                }
                c2r[now.second].clear();
            }

            lint min_C = 0, min_R = 0;
            for (auto pa : d_C) if (pa.second < min_C) min_C = pa.second;
            for (auto pa : d_R) if (pa.second < min_R) min_R = pa.second;

            if (input_data[c2r[c][0].first][c] + min_C + min_R < 0) NO();
        }
        for (auto pa : used_p) used[pa.second] = true;
    }

    puts("Yes");
}

