vi p(100000);
vl d(100000);

vi sp[2];
vl sd[2], smid[2];

int getp(int v) {
  if (p[v] == v) return v;
  int allp = getp(p[v]);
  d[v] += d[p[v]];
  p[v] = allp;
  return p[v];
}

bool join(int a, int b, ll dif) {
  int pa = getp(a);
  int pb = getp(b);
  dif += d[b] - d[a];
  if (pa == pb) {
    if (dif) return false;
  } else {
    if (rand()) {
      swap(pa, pb);
      dif *= -1;
    }
    p[pa] = pb;
    d[pa] = dif;
  }
  return true;
}

bool f(const vi & x, const vi & y, const vi & a, int t) {
  vector<vii> v(100000);
  for (int i = 0; i < x.size(); ++i) {
    v[x[i]].push_back(pii(y[i], a[i]));
  }
  d.assign(d.size(), 0);
  for (int i = 0; i < p.size(); ++i) p[i] = i;
  for (int i = 0; i < v.size(); ++i) {
    for (int j = 0; j + 1 < v[i].size(); ++j) {
      if (!join(v[i][j].first, v[i][j+1].first, v[i][j+1].second-v[i][j].second)) return false;
    }
  }
  vl mid(d.size(), 0);
  for (int i = 0; i < d.size(); ++i) {
    int pi = getp(i);
    assert(d[pi] == 0);
    mid[pi] = min(mid[pi], -d[i]);
  }
//  if (t == 0) for (int i = 0; i < 3; ++i) { cout << p[i] << ' ' << d[i] << ' ' << mid[i] << endl; }
  sp[t] = p;
  sd[t] = d;
  smid[t] = mid;
/*  for (int i = 0; i < x.size(); ++i) {
    int pi = getp(y[i]);
    if (a[i] + d[y[i]] + mid[pi] < 0) return false;
  }*/
  return true;
}

bool g(const vi & x, const vi & y, const vi & a) {
  for (int i = 0; i < x.size(); ++i) {
    int px = sp[1][x[i]], py = sp[0][y[i]];
    assert(sd[0][y[i]] + smid[0][py] <= 0 && sd[1][x[i]] + smid[1][px] <= 0);
//    cerr << x[i] << ' ' << y[i] << ' ' << a[i] << ' ' << sd[1][x[i]] << ' ' << smid[1][px] << ' ' << px << ' ' << sd[0][y[i]] << ' ' << smid[0][py] << endl;
    if (a[i] + sd[0][y[i]] + smid[0][py] + sd[1][x[i]] + smid[1][px] < 0) return false;
  }
  return true;
}

