    scanf("%d%d%d", &x[i], &y[i], &a[i]);
    --x[i]; --y[i];
  } 
  if (f(x, y, a, 0) && f(y, x, a, 1) && g(x, y, a)) {
    printf("Yes\n");
  } else {
    printf("No\n");
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> P;
typedef long long ll;
map <P,ll> M;
stack <P> stk;
int w,h,n;
int dx[4][3]={
  0,1,1,
  1,1,0,
  0,-1,-1,
  -1,-1,0
};

int dy[4][3]={
  {-1,-1,0},
  {0,1,1},
  {1,1,0},
  {0,-1,-1}
};

bool check(int x,int y){
  // cout <<x<<" "<<y<<" "<<M[P(x,y)]<<endl;
  for(int i=0;i<4;i++){
    int cnt[2]={1},A=M[P(x,y)],B=0;
    int tx=-1,ty=-1,flg=0;
    for(int j=0;j<3;j++){
      int nx=x+dx[i][j],ny=y+dy[i][j];
      if(nx<1||ny<1||nx>w||ny>h){flg=1;break;}
      if(!M.count(P(nx,ny)))tx=nx,ty=ny;
      else cnt[j!=1]++, (j==1? A+=M[P(nx,ny)]:B+=M[P(nx,ny)]);
    }
        if(flg||M.count(P(tx,ty)))continue;
    if(cnt[0]+cnt[1]==4&&A!=B)return 0;
    if(cnt[0]==1&&cnt[1]==2)M[P(tx,ty)]=B-A,stk.push(P(tx,ty));
    if(cnt[0]==2&&cnt[1]==1)M[P(tx,ty)]=A-B,stk.push(P(tx,ty));
    if(cnt[0]+cnt[1]==3&&M[P(tx,ty)]<0)return 0;
  }
  return 1;
}

int main(){
  cin>>w>>h>>n;
  for(int i=0;i<n;i++){
    int a,b,c;
    cin>>a>>b>>c;
    M[P(a,b)]=c;
  }

  map<P,ll> ::iterator it;
  for(it=M.begin();it!=M.end();it++)stk.push(P(it->first.first,it->first.second));

  int ans=1;
  while(!stk.empty()){
    P a=stk.top();stk.pop();
    int res=check(a.first,a.second);
    ans*=res;
  }

  cout <<(ans? "Yes":"No")<<endl;
  return 0;
}

