    else if(row[r] == inf){
        row[r] = n - col[c];
    }
    else if(col[c] == inf){
        col[c] = n - row[r];
    }
    else return;
    for(node nr: GR[r]){
        dfs(nr);
    }
    for(node nc: GC[c]){
        dfs(nc);
    }

}


