typedef long long ll;
typedef pair<int, ll> pil;
#define mp make_pair

const ll INF = (ll)1e18;
const int N = 200200;
int n, m;
vector<pil> g[N];
bool used[N];
ll min1, min2;
ll val[N];

void read()
{
	int k;
	scanf("%d%d%d", &n, &m, &k);
	while(k--)
	{
		int v, u;
		ll x;
		scanf("%d%d%lld", &v, &u, &x);
		v--;
		u--;
		u += n;
		g[v].push_back(mp(u, x));
		g[u].push_back(mp(v, x));
	}
	return;
}

void dfs(int v)
{
	used[v] = 1;
	for (pil e : g[v])
	{
		int u = e.first;
		ll w = e.second - val[v];
		if (used[u])
		{
			if (w != val[u])
			{
				min1 = min2 = -INF;
			}
			continue;
		}
		val[u] = w;
		if (u < n)
			min1 = min(min1, w);
		else
			min2 = min(min2, w);
		dfs(u);
	}
	return;
}

int main()
{
//	freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);

	read();
	for (int i = 0; i < n; i++)
	{
		if (used[i]) continue;
		min1 = 0;
		min2 = INF;
		val[i] = 0;
		dfs(i);
		if (min1 + min2 < 0)
		{
			printf("No\n");
			return 0;
		}
	}
	printf("Yes\n");

	return 0;
}

