    if( x != data.x ) return x < data.x;
    return y < data.y;
  }
  bool operator == (const Data& data) const {
    return x == data.x && y == data.y;
  }
};

int H,W,N;

int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

inline bool isValid(int x,int y) { return 0 <= x && x < W && 0 <= y && y < H; }

bool check(map<Data,int> &mp,int x,int y,int a) {
  rep(i,4) {
    int x2 = x + dx[i] * 2 , y2 = y + dy[i] * 2;
    if( !isValid(x2,y2) ) continue;
    int x3 = x + dx[(i+1)%4] * 2, y3 = y + dy[(i+1)%4] * 2;
    if( !isValid(x3,y3) ) continue;
    if( !mp.count((Data){x2,y2}) ) continue;
    if( !mp.count((Data){x3,y3}) ) continue;
    int x4 = x + dx[i] * 2 + dx[(i+1)%4] * 2;
    int y4 = y + dy[i] * 2 + dy[(i+1)%4] * 2;
    if( mp.count((Data){x4,y4}) ) {
      int a2 = mp[(Data){x4,y4}];
      if( ( a + a2 ) != ( mp[(Data){x2,y2}] + mp[(Data){x3,y3}] ) ) return false;
    }
  }
  return true;
}

