ll enc(int i, int j) {
    return i * 1000000000 + j;
}
pair<ll, ll> dec(int e) {
    return make_pair(e / 1000000000, e % 1000000000);
}

map<int, int> m; // enc -> num
queue<int> q;

int get(int i, int j) {
    int e = enc(i, j);
    return m.count(e) ? m[e] : -1;
}

bool check() {

    auto push = [&](int i, int j, int a) {
        int e = enc(i, j);
        if (!m.count(e)) {
            m[e] = a;
            q.push(e);
            // cout << e << ' ' << a << endl;
        }
    };

    while (q.size()) {
        int ci, cj;
        tie(ci, cj) = dec(q.front());
        q.pop();

        for (int mi = ci - 1; mi <= ci; ++mi) {
            for (int mj = cj - 1; mj <= cj; ++mj) {
                if (mi < 0) continue;
                if (mj < 0) continue;
                if (mi + 1 >= h) continue;
                if (mj + 1 >= w) continue;

                int a = get(mi, mj);
                int b = get(mi, mj + 1);
                int c = get(mi + 1, mj);
                int d = get(mi + 1, mj + 1);

                int cnt = (a != -1) + (b != -1) + (c != -1) + (d != -1);
                if (cnt == 3) {
                    if (a == -1) {
                        int na = b + c - d;
                        if (na < 0) return false;
                        push(mi, mj, na);
                    }
                    if (b == -1) {
                        int nb = a + d - c;
                        if (nb < 0) return false;
                        push(mi, mj + 1, nb);
                    }
                    if (c == -1) {
                        int nc = a + d - b;
                        if (nc < 0) return false;
                        push(mi + 1, mj, nc);
                    }
                    if (d == -1) {
                        int nd = b + c - a;
                        if (nd < 0) return false;
                        push(mi + 1, mj + 1, nd);
                    }
                } else if (cnt == 4) {
                    if (a + d != b + c) return false;
                }
            }
        }
    }
    exit(1);
    return true;
}

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    while (cin >> h >> w >> n) {
        m.clear();
        while (q.size()) q.pop();
        for (int i = 0; i < n; i++) {
            int h, w, a;
            cin >> h >> w >> a;
            --h; --w;
            m[enc(h, w)] = a;
            q.emplace(enc(h, w));
        }

        puts(check() ? "Yes" : "No");
    }

}

