bool dijk()
{
	using P = pair<ll, int>;
	priority_queue<P, vector<P>, greater<P> > que;

	rep(i, C) d[i] = LLONG_MAX;

	rep(i, C) if (!in[i]) {
		que.push(mp(0LL, i));
		d[i] = 0;
	}

	while (!que.empty()) {
		P p = que.top(); que.pop();
		int v = p.se;
		if (p.fi > d[v]) continue;
		for (edge e : g[v]) {
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				que.push(mp(d[e.to], e.to));
			}
		}
