	rep(i, R) {
		rep(j, (int)vec[i].size()-1) {
			int ii = vec[i][j], jj = vec[i][j+1];
			if (A[ii]-A[jj] != d[c[ii]]-d[c[jj]]) return false;
		}
	}
	return true;
}

