        if (i)
            cnt = min(cnt, pr[i - 1]);

        if (i + 1 != SZ(g2[v]))
            cnt = min(cnt, sf[i + 1]);

        label = min(label, dfs_up(p.first, v, cnt, p.second));
    }

    return label;
}


