class union_find {
public:
	union_find(int n)
	: par_(n, P(-1, 0))
	{}

	P root(int x) {
		if(par_[x].first < 0) return P(x, 0);
		P tmp = root(par_[x].first);
		par_[x].first = tmp.first;
		par_[x].second += tmp.second;
		return par_[x];
	}

	bool unite(int x, int y, int w) {
		ll px = root(x).first, py = root(y).first;
		if(px == py) {
			return false;
		} else {
			if(par_[px].first < par_[py].first) {
				par_[px].first += par_[py].first;
				par_[py].first = px;
				par_[py].second = (par_[x].second + w) - par_[y].second;
			} else {
				par_[py].first += par_[px].first;
				par_[px].first = py;
				par_[px].second = (par_[y].second - w) - par_[x].second;
			}
			return true;
		}
	}

	bool same(int x, int y) {
		return root(x).first == root(y).first;
	}

	bool compare(int x, int y, ll& result) {
		if(!same(x, y)) return false;
		result = root(y).second - root(x).second;
		return true;
	}
	std::vector<P> par_;
};
