    ios_base::sync_with_stdio(0);
    cin >> r >> c >> n;
    vector<pii> init;
    for (int i = 0; i < n; i++) {
        int x, y, v;
        cin >> x >> y >> v;
        x--;
        y--;
        init.push_back(pii(x, y));
        val[pii(x, y)] = v;
    }
    for (pii p : init)
        dfs(p.first, p.second);
    cout << (ok ? "Yes" : "No") << endl;
    return 0;
}

