template <typename T>
struct WeightedUnionFind{
  vector<Int> rs,ps;
  vector<T> ws;

  WeightedUnionFind(){}
  WeightedUnionFind(Int n):
    rs(n,1),ps(n),ws(n,T(0)){iota(ps.begin(),ps.end(),0);}

  Int find(Int x){
    if(x==ps[x]) return x;
    Int t=find(ps[x]);
    ws[x]+=ws[ps[x]];
    return ps[x]=t;
  }

  T weight(Int x){
    find(x);
    return ws[x];
  }

  bool same(Int x,Int y){
    return find(x)==find(y);
  }

  void unite(Int x,Int y,T w){
    w+=weight(x);
    w-=weight(y);
    x=find(x);y=find(y);
    if(x==y){
      if(w!=T(0)){
        cout<<"No"<<endl;
        exit(0);
      }
      return;
    }
    if(rs[x]<rs[y]) swap(x,y),w=-w;
    rs[x]+=rs[y];
    ps[y]=x;
    ws[y]=w;
  }

  T diff(Int x,Int y){
    return weight(y)-weight(x);
  }
};

