int minrd, mincd;

vector<char> used;

bool dfs(int v, bool first = true)
{
    if (first)
        minrd = mincd = 0;

    used[v] = true;

    minrd = min(minrd, rDelta[v]);
    mincd = min(mincd, cDelta[v]);

    for (int u: e[v])
    {
        int rd = rDelta[v], cd = cDelta[v];

        if (vertices[u].x == vertices[v].x)
            rd = rDelta[v] + vertices[u].v - vertices[v].v;
        else
            cd = cDelta[v] + vertices[u].v - vertices[v].v;

        if (!used[u])
        {
            rDelta[u] = rd;
            cDelta[u] = cd;

            if (!dfs(u, false))
                return false;
        }
        else if (rDelta[u] != rd || cDelta[u] != cd)
            return false;
    }

    if (first)
    {
        //printf("minrd %d, mincd %d\n", minrd, mincd);
        if ((-mincd) + (-minrd) > vertices[v].v)
            return false;
    }

    return true;
}

