typedef long long ll;
typedef pair<ll, ll> P;
#define X first
#define Y second

const int MAX = 1<<17;
const ll INF = 1e18;

ll val[2][MAX];
vector <P> V[2][MAX];
pair <P, int> p[MAX];

void Nope()
{
  printf("No\n");
  exit(0);
}

P Dfs(P poz)
{
  P ret = P(INF, INF);
  if (poz.X == 0)
    ret.X = val[poz.X][poz.Y];
  else
    ret.Y = val[poz.X][poz.Y];

  for (auto it : V[poz.X][poz.Y]) {
    ll nval = it.Y - val[poz.X][poz.Y];
    if (val[poz.X^1][it.X] == INF) {
      val[poz.X^1][it.X] = nval;
      P tmp = Dfs(P(poz.X^1, it.X));
      ret.X = min(ret.X, tmp.X);
      ret.Y = min(ret.Y, tmp.Y);
    }
    else if (val[poz.X^1][it.X] != nval)
      Nope();
  }

  return ret;
}

int main()
{
  int n;

  scanf("%*d%*d%d", &n);

  for (int i=0; i<n; i++) {
    scanf("%lld%lld%d", &p[i].X.X, &p[i].X.Y, &p[i].Y);
    V[0][p[i].X.X].push_back(P(p[i].X.Y, p[i].Y));
    V[1][p[i].X.Y].push_back(P(p[i].X.X, p[i].Y));
  }

  for (int i=0; i<2; i++)
    for (int j=0; j<MAX; j++)
      val[i][j] = INF;

  for (int i=0; i<MAX; i++) {
    if (val[0][i] == INF) {
      val[0][i] = 0;
      P tmp = Dfs(P(0, i));
      if (tmp.X + tmp.Y < 0)
        Nope();
    }
  }

  printf("Yes\n");

  return 0;
}

