bool dfs(int u)
{
    for(int i = 0;i < G[u].size();++i)
    {
        int v = G[u][i].v;
        LL w = G[u][i].w;

        if(!vis[v])
        {
            vis[v] = 1;
            A[v] = w-A[u];
            if(!dfs(v)) return false;
        }
        else
        {
            if(A[v] + A[u] != w) return false;

        }
    }
    return true;

}


bool judge()
{

    memset(vis,0,sizeof(vis));
    for(int i = 1;i <= R;++i)
        if(!vis[i])
        {
            vis[i] = 1;
            A[i] = 0;
            if(!dfs(i)) return false;
        }

    LL Minr = INF;
    LL Minc = INF;
    for(int i = 1;i <= R;++i)
        Minr = min(Minr,A[i]);
    for(int i = R+1;i <= R+C;++i)
        if(vis[i])
        Minc = min(Minc,A[i]);

    if(Minr + Minc < 0) return false;


    return true;
}

