  for (int y=0; y<R; y++) {
    if (G[y].empty()) continue;
    P &a = G[y][0];
    int x = a._1;
    if (T[x] == INF) {
      T[x] = a._2;
      if (!g(x)) return false;
    }
  }
  int ma = INF, mb = INF;
  for (int x=0; x<C; x++) mb = min(mb, T[x]);
  for (int y=0; y<R; y++) {
    for (auto &p : G[y]) {
      if (T[p._1] == INF) continue;
      ma = min(ma, p._2 - T[p._1]);
    }
  }
  return ma+mb >= 0;
}

