		rep(j, (int)et[i].size() - 1) {
			int r1 = et[i][j];
			int r2 = et[i][j + 1];
			etR[r1].push_back(r2);
			ecR[r1].push_back(ec[i][j + 1] - ec[i][j]);
			etR[r2].push_back(r1);
			ecR[r2].push_back(ec[i][j] - ec[i][j + 1]);
		}
	}

