			}
		}

		for (int i = 0; i < row - 1; i++)
		{
			for (int j = column - 1; j > 0; j--)
			{
				if (grid[i][j] != INT_MIN)
				{
					for (int next_i = i + 1; next_i < row; next_i++)
					{
						if (grid[next_i][j] != INT_MIN)
						{
							for (int next_j = j - 1; next_j >= 0; next_j--)
							{
								if (grid[i][next_j] == INT_MIN && grid[next_i][next_j] == INT_MIN)
									continue;
								else if (grid[i][next_j] != INT_MIN && grid[next_i][next_j] == INT_MIN)
								{
									new_blank_count--;
									grid[next_i][next_j] = grid[i][next_j] + grid[next_i][j] - grid[i][j];
									if (grid[next_i][next_j] < 0)
										goto no;
								}
								else if (grid[i][next_j] == INT_MIN && grid[next_i][next_j] != INT_MIN)
								{
									new_blank_count--;
									grid[i][next_j] = grid[i][j] + grid[next_i][next_j] - grid[next_i][j];
									if (grid[i][next_j] < 0)
										goto no;
								}
								else
								{
									if (grid[i][j] + grid[next_i][next_j] != grid[i][next_j] + grid[next_i][j])
										goto no;
								}
							}
						}
					}
				}
			}
		}

		if (new_blank_count == 0 || new_blank_count == blank_count)
			break;
		else
			blank_count = new_blank_count;
	}

	cout << "Yes" << endl;
	return 0;
no:
	cout << "No" << endl;
	return 0;
}

