bool dfs(int v, int64_t s, const vector<vector<pair<int, int64_t>>>& e, vector<int>& used, vector<int64_t>& ans) {
    used[v] = 1;
    ans[v] = s;
    for (auto [u, a] : e[v]) {
        if (!used[u]) {
            if (!dfs(u, a - s, e, used, ans)) return false;
        } else {
            if (ans[u] + s != a) return false;
        }
    }
    return true;
}

