    do { ch = getchar(); } while(ch <= ' ');
    while((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z')) {
        ans += ch;
        ch = getchar();
    }
