long long Pow(long long a, long long b) {
    if(!b) return 1;

    long long ans = Pow(a, b / 2);

    ans = ans * ans % MOD;

    if(b % 2) ans = ans * a % MOD;

    return ans;
}

map<int, long long> w[MAXN];

struct mde {
    mde(int x, int y, long long a) : x(x), y(y), a(a) {
        w[x][y] = a;
    }

    int x;
    int y;
    long long a;
} ;

vector<mde> q;

void lul(int x, int y, int X, int Y) {
    int ska = 0;
    if(w[x].find(y) != w[x].end()) ska++;
    if(w[x].find(Y) != w[x].end()) ska++;
    if(w[X].find(y) != w[X].end()) ska++;
    if(w[X].find(Y) != w[X].end()) ska++;

    if(ska < 3) return;
    long long e[2] = {0, 0};

    if(w[x].find(y) != w[x].end()) e[0] += w[x][y];
    if(w[x].find(Y) != w[x].end()) e[1] += w[x][Y];
    if(w[X].find(y) != w[X].end()) e[1] += w[X][y];
    if(w[X].find(Y) != w[X].end()) e[0] += w[X][Y];

    if(ska == 4) {
        if(e[0] != e[1]) {
            puts("No");
            exit(0);
        }
    }

    if(w[x].find(y) == w[x].end()) {
        if(e[0] > e[1]) {
            puts("No");
            exit(0);            
        }
        q.push_back(mde(x, y, e[1] - e[0]));
    }
    if(w[x].find(Y) == w[x].end()) {
        if(e[1] > e[0]) {
            puts("No");
            exit(0);            
        }
        q.push_back(mde(x, Y, e[0] - e[1]));        
    }
    if(w[X].find(y) == w[X].end()) {
        if(e[1] > e[0]) {
            puts("No");
            exit(0);            
        }
        q.push_back(mde(X, y, e[0] - e[1]));                
    }
    if(w[X].find(Y) == w[X].end()) {
        if(e[0] > e[1]) {
            puts("No");
            exit(0);            
        }
        q.push_back(mde(X, Y, e[1] - e[0]));
    }

}

int main() {
    // freopen(".in", "r", stdin);

    int n = next_int<int>();
    int m = next_int<int>();

    int k = next_int<int>();

    for(int i = 0; i < k; i++) {
        int x = next_int<int>();
        int y = next_int<int>();
        long long a = next_int<int>();

        q.push_back(mde(x, y, a));
    }

    for(int i = 0; i < q.size(); i++) {
        if(q[i].x > 1 && q[i].y > 1) lul(q[i].x - 1, q[i].y - 1, q[i].x, q[i].y);
        if(q[i].y > 1 && q[i].x < n) lul(q[i].x, q[i].y - 1, q[i].x + 1, q[i].y);
        if(q[i].x > 1 && q[i].y < m) lul(q[i].x - 1, q[i].y, q[i].x, q[i].y + 1);
        if(q[i].x < n && q[i].y < m) lul(q[i].x, q[i].y, q[i].x + 1, q[i].y + 1);
    }

    puts("Yes");
}

