int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int H, W, N;
  cin >> H >> W >> N;
  map<int,vector<PLL>> col, row;
  REP(i,N){
	int y, x, a;
	cin >> y >> x >> a;
	--x;
	--y;
	row[y].EB(x, a);
	col[x].EB(y, a);
  }

  vector<vector<PLL>> Gx(W), Gy(H);
  vector<LL> dx(W, INF), dy(H, INF);
  vector<LL> mx(W, INF), my(H, INF);
  REP(y,H){
	if(!row.count(y)) continue;
	vector<PLL>& xs = row[y];
	SORT(xs);
	for(int i=0;i+1<SZ(xs);++i){
	  Gx[xs[i].FF].EB(xs[i+1].FF, xs[i+1].SS - xs[i].SS);
	  Gx[xs[i+1].FF].EB(xs[i].FF, xs[i].SS - xs[i+1].SS);
	}
	REP(i,SZ(xs)) mini(mx[xs[i].FF], xs[i].SS);
  }
  REP(x,W){
	if(!col.count(x)) continue;
	vector<PLL>& ys = col[x];
	SORT(ys);
	for(int i=0;i+1<SZ(ys);++i){
	  Gy[ys[i].FF].EB(ys[i+1].FF, ys[i+1].SS - ys[i].SS);
	  Gy[ys[i+1].FF].EB(ys[i].FF, ys[i].SS - ys[i+1].SS);
	}
	REP(i,SZ(ys)) mini(my[ys[i].FF], ys[i].SS);
  }

  bool ng = false;
  function<bool(vector<vector<PLL>>&,int,VL&,VI&)> dfs = [&](vector<vector<PLL>>& G, int u, VL& d, VI& vis){
	vis.PB(u);
	for(auto& e: G[u]){
	  if(d[e.FF] == INF){
		d[e.FF] = d[u] + e.SS;
		if(!dfs(G, e.FF, d,vis))
		  return false;
	  }
	  else{
		if(d[u] + e.SS != d[e.FF]){
		  return false;
		}
	  }
	}
	return true;
  };

  REP(x,W){
	if(dx[x] != INF) continue;
	dx[x] = 0;
	VI vis;
	if(!dfs(Gx, x, dx, vis)){
	  ng = true;
	  break;
	}
	int mix = x;
	LL m = mx[x];
	for(int u: vis){
	  if(mx[u] + dx[u] < m){
		mix = u;
		m = mx[u] + dx[u];
	  }
	}
	if(m < 0){
	  for(int u: vis){
		if(dx[u] - m > mx[u]){
		  ng = true;
		  break;
		}
	  }
	}
  }
  REP(y,H){
	if(dy[y] != INF) continue;
	dy[y] = 0;
	VI vis;
	if(!dfs(Gy, y, dy, vis)){
	  ng = true;
	  break;
	}
	int mix = y;
	LL m = my[y];
	for(int u: vis){
	  if(my[u] + dy[u] < m){
		mix = u;
		m = my[u] + dy[u];
	  }
	}
	if(m < 0){
	  for(int u: vis){
		if(dy[u] - m > my[u]){
		  ng = true;
		  break;
		}
	  }
	}
  }

  //REP(x,W) cout << dx[x] << " "; cout << endl;
  //REP(y,H) cout << dy[y] << endl;
  cout << (ng? "No": "Yes") << endl;

  return 0;
}

