struct thing
{
    int r, c, x;
};

int R, C, N;
vector<thing> row[100000], col[100000];
long long A[100000];
long long B[100000];
set<int> rows, cols;

void ensure(bool b)
{
    if(!b)
    {
        printf("No\n");
        exit(0);
    }
}

void go(int r)
{
    long long minr=0x3f3f3f3f3f3f3f3fLL;
    long long minc=0x3f3f3f3f3f3f3f3fLL;
    queue<pair<int, int>> Q;
    Q.push({r, 0});
    rows.erase(r);
    A[r]=0;
    while(!Q.empty())
    {
        int t;
        tie(r, t)=Q.front();
        Q.pop();
        if(t==0)
        {
            minr=min(minr, A[r]);
            for(auto& it: row[r])
            {
                if(!cols.count(it.c))
                    ensure(B[it.c]==it.x-A[it.r]);
                else
                {
                    B[it.c]=it.x-A[it.r];
                    Q.push({it.c, 1});
                    cols.erase(it.c);
                }
            }
        }
        else
        {
            minc=min(minc, B[r]);
            for(auto& it: col[r])
            {
                if(!rows.count(it.r))
                    ensure(A[it.r]==it.x-B[it.c]);
                else
                {
                    A[it.r]=it.x-B[it.c];
                    Q.push({it.r, 0});
                    rows.erase(it.r);
                }
            }
        }
    }
    ensure(minr+minc>=0);
}

int main()
{
    scanf("%d%d%d", &R, &C, &N);
    for(int i=0; i<N; i++)
    {
        int a, b, c;
        scanf("%d%d%d", &a, &b, &c);
        a--, b--;
        row[a].push_back((thing){a, b, c});
        col[b].push_back((thing){a, b, c});
        rows.insert(a);
        cols.insert(b);
    }
    while(!rows.empty())
        go(*rows.begin());
    printf("Yes\n");
    return 0;
}

