            ll d = v[i][j+1].second - v[i][j].second;
            ev[y1].pb({y2, d});
            ev[y2].pb({y1, -d});
        }
    }
    vector<bool> used(H, false);
    vector<ll> pot(H, 0);
    bool ans = true;
    vector<ll> group(H, -1);
