void dfs(int x, long long cp) {
	if ((used[x]) && (cp != pot[x])) {
		puts("No");
		exit(0);
	}
	if (used[x]) return;
	m1 = min(m1, pp[x] - cp);
	m2 = min(m2, cp);
	used[x] = 1;
	pot[x] = cp;
	for (int i = 0; i < (int)g[x].size(); i++) {
		dfs(g[x][i].first, cp + g[x][i].second);
	}
}

