using namespace std;
#define REP(i,a,b) for (int i = (a); i <= (b); ++i)
#define REPD(i,a,b) for (int i = (a); i >= (b); --i)
#define FORI(i,n) REP(i,1,n)
#define FOR(i,n) REP(i,0,int(n)-1)
#define mp make_pair
#define pb push_back
#define pii pair<int,int>
#define vi vector<int>
#define ll long long
#define SZ(x) int((x).size())
#define DBG(v) cerr << #v << " = " << (v) << endl;
#define FOREACH(i,t) for (typeof(t.begin()) i=t.begin(); i!=t.end(); i++)
#define fi first
#define se second

const int N = 100100;

int R,C,n,ir,ic;
int x[N], y[N], a[N], M[N], vis[N], val[N];
int ux[N], uy[N];
vector<pii> X[N], Y[N], dif[N];

bool ok;

void dfs(int u) {
	vis[u] = 1;
	FOR(i,SZ(dif[u])) {
		int v = dif[u][i].fi;
		if (vis[v]) {
			if (val[v] != val[u] + dif[u][i].se) ok = false;
		} else {
			val[v] = val[u] + dif[u][i].se;
			dfs(v);
		}
	}
}

int main() {
	scanf("%d%d%d", &R, &C, &n);
	FOR(i,n) {
		scanf("%d%d%d", &x[i], &y[i], &a[i]);
		ux[x[i]]=1;
		uy[y[i]]=1;
	}

	FORI(r,R) if (ux[r]) ux[r]=ir++;
	FORI(c,C) if (uy[c]) uy[c]=ic++;

	FOR(i,n) {
		X[ux[x[i]]].pb(mp(uy[y[i]], a[i]));
		Y[uy[y[i]]].pb(mp(ux[x[i]], a[i]));
	}

	R = ir;
	C = ic;

	FOR(i,R) sort(X[i].begin(), X[i].end());
	FOR(j,C) sort(Y[j].begin(), Y[j].end());

	// check negatives
	FOR(i,C) {
		M[i] = 1e9+4566;
		FOR(j,SZ(Y[i])) M[i] = min(M[i], Y[i][j].se);
	}

	FOR(r,R) {
		int mi = 1e9+234, ma = -1;
		FOR(c,SZ(X[r])) {
			mi = min(mi, X[r][c].se);
			ma = max(ma, X[r][c].se - M[X[r][c].fi]);
		}
		if (mi < ma) {
			printf("No\n");
			return 0;
		}
	}

	// check existing values

	FOR(r,R) {
		FORI(i,SZ(X[r])-1) {
			//printf("dif %d %d = %d\n", X[r][i].fi, X[r][i-1].fi, X[r][i].se-X[r][i-1].se);
			dif[X[r][i].fi].pb(mp(X[r][i-1].fi, X[r][i].se-X[r][i-1].se));
			dif[X[r][i-1].fi].pb(mp(X[r][i].fi, X[r][i-1].se-X[r][i].se));
		}
	}

	ok = true;

	FOR(c,C) if (!vis[c]) {
		dfs(c);
	}


	printf("%s\n", ok ? "Yes" : "No");


	return 0;
}

#include<stdio.h>
