int R, C, N;
map<P, int> mp;
priority_queue<P, vector<P>, greater<P>> pq;
int dr[101010], dc[101010];

int main() {
    cin >> R >> C >> N;
    fill(dr, dr+R, -1);
    fill(dc, dc+C, -1);

    for (int j = 0; j < N; ++j) {
        int r, c, a;
