        pq.push(next_p);
    }

    while (!pq.empty()) {
        P p = pq.top(); pq.pop();

        int r = p.first;
        int c = p.second;
        int v = mp[p];

        for (int i = 0; i < 4; ++i) {
            int nr = r + dx[i];
            int nc = c + dy[i];
            auto it = mp.find(make_pair(nr, nc));
            if (0 <= nr && nr < R && 0 <= nc && nc < C && it != end(mp)) {

                auto u1 = mp.find(make_pair(r + dx[i], c));
                auto u2 = mp.find(make_pair(r, c + dy[i]));

                if (u1 != end(mp)) {
                    if (u2 != end(mp)) {
                        if (it->second + v != u1->second + u2->second) {
                            cout << "No" << endl;
                            return 0;
                        }
                    } else {
                        if (it->second + v < u1->second) {
                            cout << "No" << endl;
                            return 0;
                        } else {
                            P next_p = make_pair(r, c+dy[i]);
                            mp[next_p] = it->second + v - u1->second;
                            pq.push(next_p);
                        }
                    }
                } else if (u2 != end(mp)) {
                    if (it->second + v < u2->second) {
                        cout << "No" << endl;
                        return 0;
                    } else {
                        P next_p = make_pair(r+dx[i], c);
                        mp[next_p] = it->second + v - u2->second;
                        pq.push(next_p);
                    }
                }
            }
        }
    }

    for (auto& e: mp) {
        pq.push(e.first);
    }

    while (!pq.empty()) {
        P p = pq.top(); pq.pop();

        int r = p.first;
        int c = p.second;
        int v = mp[p];

        {
            int nr = r+1;
            int nc = c;
            auto it = mp.find(make_pair(nr, nc));

            if (it != end(mp)) {
                if (dr[r] == -1) {
                    dr[r] = pow(-1, c) * (v - it->second) ;
                } else {
                    if (dr[r] != pow(-1, c) * (v - it->second)) {
                        cout << "No" << endl;
                        return 0;
                    }
                }
            }
        }

        {
            int nr = r;
            int nc = c+1;
            auto it = mp.find(make_pair(nr, nc));

            if (it != end(mp)) {
                if (dc[c] == -1) {
                    dc[c] = pow(-1, r) * (v - it->second) ;
                } else {
                    if (dc[c] != pow(-1, r) * (v - it->second)) {
                        cout << "No" << endl;
                        return 0;
                    }
                }
            }
        }

    }


    cout << "Yes" << endl;

    return 0;
}

