#include<algorithm>
#define maxn 100005
#define oo 0x3f3f3f3f
using namespace std;

struct node
{
	int x,y,val;
}tr[maxn];
int t,n,r,c;
int fa[maxn],del[maxn],mn1[maxn],mn2[maxn];//del[i]指i到父节点的差值

bool cmp(node a,node b)
{
	if(a.y!=b.y)
	return a.y<b.y;
	else return a.x<b.x;
}//以y轴为第一关键字从小到大排序

int find(int a)
{
	if(fa[a]==a)
	return a;
	int fax=find(fa[a]);
	del[a]+=del[fa[a]];//合并差值
	return fa[a]=fax;
}//找父亲

int unionn(int a,int b,int v)
{
	int fax=find(a),fay=find(b);
	if(fax!=fay)
	{
		del[fax]=v+del[b]-del[a];//推导的性质
		fa[fax]=fay;//合并并查集
		return 1;
	}//不在同一个集合内
	else
	{
		if(del[a]!=del[b]+v)return 0;
		else return 1;
	}//在同一个集合内
}//并查集合并

int main()
{
	memset(mn1,oo,sizeof(mn1));
	memset(mn2,oo,sizeof(mn2));
	int flag=1;
	scanf("%d%d%d",&r,&c,&n);
	for(int i=1;i<=r;++i)
	{
		fa[i]=i;
		del[i]=0;
	}//初始化并查集
	for(int i=1;i<=n;++i)
	{
		int x,y,z;
		scanf("%d%d%d",&x,&y,&z);
		tr[i].x=x;
		tr[i].y=y;
		tr[i].val=z;
		if(z<0)flag=0;
	}
	if(!flag)
	{
		printf("No\n");
		continue;
	}
	if(r==1)
	{
		printf("Yes\n");
		continue;
	}//特判行为1
	sort(tr+1,tr+1+n,cmp);//初始化排序
	for(int i=1;i<n;++i)
	{
		if(tr[i].y==tr[i+1].y)
		{
			if(!unionn(tr[i].x,tr[i+1].x,tr[i+1].val-tr[i].val))//顺便结合两行
			flag=0;//与所得结论矛盾
		}
	}//判断是否矛盾
	if(!flag)
	{
		printf("No\n");
		continue;
	}
	for(int i=1;i<=n;++i)
	{
		int fax=find(tr[i].x);
		mn1[fax]=min(mn1[fax],tr[i].val+del[tr[i].x]);
	}//求父节点行上一点的最小值
	for(int i=1;i<=r;++i)
	{
		int fax=find(i);
		mn2[fax]=min(mn2[fax],-del[i]);
	}//求某一行的父节点可能的最小值
	for(int i=1;i<=r;++i)
	{
		if(fa[i]==i&&mn1[i]+mn2[i]<0)
		{
			flag=0;
			break;
		}
	}
	if(!flag)
	printf("No\n");
	else printf("Yes\n");
	return 0;
}

