bool dfs(int pos, long long sum, int id, vector<vector<edge> > &g) {
	for (edge e : g[pos]) {
		if (dat[id][e.to] != inf) {
			if (sum + e.val != dat[id][e.to]) return false;
		}
		else {
			dat[id][e.to] = sum + e.val;
			if (!dfs(e.to, sum + e.val, id, g)) return false;
		}
	}
	return true;
}
