using Pair = std::pair<long long, long long>;
using PP = std::pair<Pair, long long>;
constexpr long long INF = std::numeric_limits<long long>::max();
constexpr long long MINF = std::numeric_limits<long long>::min();

int r, c;
int n;
std::set<PP> points;

bool check() {
    std::map<long long, long long> m; // x, diff
    std::map<long long, std::vector<Pair>> edges;
    std::set<long long> pts;
    std::vector<long long> Min(c + 100, INF);

    long long prevY = INF;
    long long prevX = INF;
    long long prevV = INF;
    for(auto&& p : points) {
        if(p.first.first != prevY) {
            prevY = p.first.first;
            prevX = p.first.second;
            prevV = p.second;
        }else {
            edges[p.first.second].push_back({prevX, prevV - p.second});
            edges[prevX].push_back({p.first.second, p.second - prevV});
        }
        pts.insert(p.first.second);
        Min[p.first.second] = std::min(Min[p.first.second], p.second);
    }

    while(pts.size()) {
        std::queue<long long> que;
        std::map<long long, long long> costs;

        que.push(*pts.begin());
        costs[*pts.begin()] = 0;

        long long M = Min[*pts.begin()];
        long long Medge = INF;
        while(!que.empty()) {
            long long x = que.front(); que.pop();

            pts.erase(x);

            auto& e = edges[x];

            for(int i = 0; i < e.size(); ++i) {
                if(pts.count(e[i].first))
                    que.push(e[i].first);

                if(costs.count(e[i].first)) {
                    if(costs[e[i].first] != e[i].second + costs[x]) {
                        return false;
                    }
                }else {
                    auto c = e[i].second + costs[x];
                    costs[e[i].first] = c;

                    M = std::min(M, Min[e[i].first] - c);

                    Medge = std::min(c, Medge);
                }
            }
        }

        if(0 > M + Medge) {
            return false;
        }
    }

    return true;
}

int main() {
    std::cin >> r >> c >> n;

    for(int i = 0; i < n; ++i) {
        PP v;

        std::cin >> v.first.first >> v.first.second >> v.second;

        points.insert(v);
    }

    if(!check()) {
        std::cout << "No" << std::endl;

        return 0;
    }

    std::set<PP> ns;

    for(auto pp : points) {
        ns.insert({{pp.first.second, pp.first.first}, pp.second});
    }

    std::swap(ns, points);

    std::swap(r, c);

    if(!check()) {
        std::cout << "No" << std::endl;
    }else {
        std::cout << "Yes" << std::endl;
    }
}

