template<class T> T gcd(T a, T b) { return b ? gcd(b, a % b) : a; }
template<class T> T lcm(T a, T b) { return a / gcd(a, b) * b; }
ll mod_pow(ll a, ll n, ll mod) {
	ll ret = 1;
	ll p = a % mod;
	while (n) {
		if (n & 1) ret = ret * p % mod;
		p = p * p % mod;
		n >>= 1;
	}
	return ret;
}
template<class T> T extgcd(T a, T b, T& x, T& y) { for (T u = y = 1, v = x = 0; a;) { T q = b / a; swap(x -= q * u, u); swap(y -= q * v, v); swap(b -= q * a, a); } return b; }
template<class T> T mod_inv(T a, T m) { T x, y; extgcd(a, m, x, y); return (m + x % m) % m; }

using Pii = pair<int, int>;
using Pll = pair<ll, ll>;

class UnionFind {
private:
	int n;
	vector<int> a;
public:
	UnionFind(int n) : n(n), a(n, -1) {}
	int find(int x) { return a[x] < 0 ? x : (a[x] = find(a[x])); }
	bool same(int x, int y) { return find(x) == find(y); }
	bool same(Pii& p) { return same(p.first, p.second); }
	bool unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y) return false;
		if (a[x] > a[y]) swap(x, y);
		a[x] += a[y];
		a[y] = x;
		n--;
		return true;
	}
	bool unite(Pii& p) { return unite(p.first, p.second); }
	int size() const { return n; }
	int size(int x) { return -a[find(x)]; }
};


int main() {
	int r, c; reader(r, c);
	int n; reader(n);

	vector<tuple<int, int, int>> vp;

	vector<int> cm1, cm2;
	FOR(i, n) {
		int a, b, x; reader(a, b, x);
		a--; b--;
		cm1.push_back(a);
		cm2.push_back(b);
		vp.emplace_back(a, b, x);
	}
	sort(cm1.begin(), cm1.end());
	cm1.erase(unique(cm1.begin(), cm1.end()), cm1.end());
	sort(cm2.begin(), cm2.end());
	cm2.erase(unique(cm2.begin(), cm2.end()), cm2.end());
	for (auto& abx : vp) {
		get<0>(abx) = lower_bound(cm1.begin(), cm1.end(), get<0>(abx)) - cm1.begin();
		get<1>(abx) = lower_bound(cm2.begin(), cm2.end(), get<1>(abx)) - cm2.begin();
	}
	map<int, vector<Pii>> mp;
	for (auto& abx : vp) {
		int a, b, x; tie(a, b, x) = abx;
		mp[a].emplace_back(b, x);
	}

	vector<tuple<int, int, int>> diffs;
	for (auto& v : mp) {
		auto& y = v.second;
		sort(y.begin(), y.end());
		FOR(i, sz(y) - 1) {
			int l = y[i].first, r = y[i + 1].first;
			int d = y[i + 1].second - y[i].second;
			diffs.emplace_back(l, r, d);
		}
	}
	sort(diffs.begin(), diffs.end());

	UnionFind uf(ten(5) + 1);

	const int X = ten(9) + 1;
	vector<int> dp(ten(5) + 1, X);
	bool ok = true;
	for (auto& lrd : diffs) {
		int l, r, d; tie(l, r, d) = lrd;
		uf.unite(l, r);
		if (dp[l] == X) dp[l] = 0;
		if (dp[r] == X) {
			dp[r] = dp[l] + d;
		}
		if (dp[r] != dp[l] + d) ok = false;
	}

	map<int, int> min_id;
	FOR(i, ten(5) + 1) {
		if (dp[i] == X) continue;
		int id = uf.find(i);
		if (min_id.find(id) == min_id.end()) min_id[id] = i;
		int& m = min_id[id];
		if (dp[m] > dp[i]) m = i;
	}

	for (auto& v : mp) {
		auto& y = v.second;
		const int uid = uf.find(y[0].first);
		const int mid = min_id[uid];
		int diff = dp[uid] - dp[mid];
		const int minval = y[0].second - diff;
		if (minval < 0)
			ok = false;
	}

	puts(ok ? "Yes" : "No");

	return 0;
}

