	memset(la,0,sizeof(la));
	memset(lb,0,sizeof(lb));
	for(int i=0;i<=r;i++){
		fa[i] = i; da[i] = 0;
	}
	for(int i=0;i<=c;i++){
		fb[i] = i; db[i] = 0;
	}
