using namespace std;

map<int, int> grid[112123];
map<int, int> prv;
map<int, map<int, int> > gdelta;

int h, w;
int n;
int ldelta[112123];
bool seen[112123];
vector<int> adjList[112123];

void dfs(int r)
{
	if (seen[r]) return;
	seen[r] = true;
	for (int i = 0; i < adjList[r].size(); i++)
	{
		int r2 = adjList[r][i];
		if (gdelta[r][r2] < 0) continue;
		dfs(r2);
		ldelta[r] = max(ldelta[r], gdelta[r][r2] + ldelta[r2]);
	}
}

int main()
{
	cin >> h >> w >> n;
	for (int i = 0; i < n; i++)
	{
		int r, c, a;
		cin >> r >> c >> a;
		r--;
		c--;
		grid[r][c] = a;
	}
	for (int r = 0; r < h; r++)
	{
		if (grid[r].empty()) continue;
		auto &row = grid[r];
		map<int, int> &delta = gdelta[r];
		for (auto it = row.begin(); it != row.end(); it++)
		{
			int c = it->first;
			if (!prv.count(c))
			{
				prv[c] = r;
				continue;
			}
			int r2 = prv[c];
			if (!delta.count(r2))
			{
				delta[r2] = grid[r][c] - grid[r2][c];
				gdelta[r2][r] = -delta[r2];
				adjList[r].push_back(r2);
				adjList[r2].push_back(r);
				//ldelta[r] = max(ldelta[r], delta[r2]);
				//ldelta[r2] = max(ldelta[r2], -delta[r2]);
			}
			else if (delta[r2] != grid[r][c] - grid[r2][c])
			{
				cout << "No\n";
				return 0;
			}
			prv[c] = r;
		}
	}
	for (int r = 0; r < h; r++) dfs(r);
	for (int r = 0; r < h; r++)
	{
		if (grid[r].empty()) continue;
		auto &row = grid[r];
		for (auto it = row.begin(); it != row.end(); it++)
		{
			if (it->second < ldelta[r])
			{
				cout << "No\n";
				return 0;
			}
		}
	}
	cout << "Yes\n";
	return 0;
}

