template<class T> bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1; } return 0; }
template<class T> bool chmin(T &a, const T &b) { if (a>b) { a=b; return 1; } return 0; }

template<class A, size_t N, class T> void Fill(A (&a)[N], const T &v){ fill( (T*)a, (T*)(a+N), v ); }

const int INF = 0x3fffffff;


int R, C, N;
bool ans=true;
vector<pii> edge[2][100005];
int memo[2][100005];

bool dfs(int k, int n, int b, int v, int m[2]){
	//cout << "\t" << k << " " << n << " " << b << " " << v << " (" << m[0] << "," << m[1] << ") " << endl;
	if( memo[k%2][n] == INF ) memo[k%2][n] = v;
	else return ( memo[k%2][n] == v );
	chmin( m[k%2], v );
	if( m[0] + m[1] < 0 ) return false;
	bool ret = true;
	for(auto t: edge[k%2][n]) if( k%2 == 0 || t.X > b ){
		ret &= dfs(k+1, t.X, n, t.Y-v, m);
	}
	return ret;
}

