			int t=xid[i][j].first;
			int c=xid[i][0].second-xid[i][j].second;
			xlimit[f].push_back(P(t,-c));
			xlimit[t].push_back(P(f,c));
			if(mini[f]-c<0)flag=false;
			if(mini[t]+c<0)flag=false;
		}
	}
	for(int i=0;i<C;i++){
		if(yid[i].size()<=1)continue;
		int f=yid[i][0].first;
		for(int j=1;j<yid[i].size();j++){
			int t=yid[i][j].first;
			int c=yid[i][0].second-yid[i][j].second;
			ylimit[f].push_back(P(t,-c));
			ylimit[t].push_back(P(f,c));
			if(mini2[f]-c<0)flag=false;
			if(mini2[t]+c<0)flag=false;
		}
	}

	for(int i=0;i<R;i++){
		if(!checked[i])dfs(i,0);
	}
	memset(checked,false,sizeof(checked));
	memset(dist,0,sizeof(dist));
	for(int i=0;i<C;i++){
