		uf.unite(a, b + r);
		mp1[a].emplace_back(b, x);
		mp2[b].emplace_back(a, x);
	}

	vector<int> rdp = solve(mp1);
	vector<int> cdp = solve(mp2);
	map<int, vector<int>> con;
