using namespace std;

using pii=pair<int, int>;
using ppi=pair<pii, int>;
using mpi=map<pii, int>;

static const int di[]={-1, -1, 1, 1}, dj[]={-1, 1, -1, 1};

bool is_valid(const ppi &item, mpi &dict, mpi &extdict, int R, int C) {
    int i=item.first.first, j=item.first.second;
    int a=item.second;

    for (int k=0; k<4; ++k) {
        int I=i+di[k], J=j+dj[k];
        if (I<0 || R<=I || J<0 || C<=J) continue;

        int fcount=1;
        int matched=0;
        if (dict.find(pii(I, J)) != dict.end()) ++fcount, matched|=1;
        if (dict.find(pii(I, j)) != dict.end()) ++fcount, matched|=2;
        if (dict.find(pii(i, J)) != dict.end()) ++fcount, matched|=4;

        if (fcount <= 2) continue;
        if (fcount == 3) {
            int b=0;
            pii blank;
            if (matched == 6) {
                b = dict[pii(I, j)]+dict[pii(i, J)]-a;
                blank = pii(I, J);
            } else if (matched == 3) {
                b = a+dict[pii(I, J)]-dict[pii(I, j)];
                blank = pii(i, J);
            } else if (matched == 5) {
                b = a+dict[pii(I, J)]-dict[pii(i, J)];
                blank = pii(I, j);
            }

            if (b < 0) {
                return false;
            } else if (extdict.find(blank)!=extdict.end() && extdict[blank]!=b) {
                return false;
            } else {
                extdict[blank] = b;
            }
        } else {
            if (dict[pii(I, J)]+a != dict[pii(I, j)]+dict[pii(i, J)])
                return false;
        }
    }

    return true;
}

int main() {
    int R, C, N;
    scanf("%d %d %d", &R, &C, &N);

    mpi dict;
    for (int i=0; i<N; ++i) {
        int r, c, a;
        scanf("%d %d %d", &r, &c, &a);

        dict[pii(r, c)] = a;
    }

    mpi extdict;
    for (auto item: dict) {
        if (!is_valid(item, dict, extdict, R, C)) {
            printf("No\n");
            return 0;
        }
    }

    for (auto item: extdict) {
        if (dict.find(item.first)!=dict.end()&&dict[item.first]!=item.second) {
            printf("No\n");
            return 0;
        }

        dict[item.first] = item.second;
    }

    mpi extdict2;
    for (auto item: extdict) {
        if (!is_valid(item, dict, extdict2, R, C)) {
            printf("No\n");
            return 0;
        }
    }

    printf("Yes\n");
    return 0;
}

