using namespace std;

typedef long long ll;
typedef pair <int, int> pii;

const int MAXN = 100005;

int R, C, N;
vector <pii> row[MAXN];
vector <pii> graph[MAXN];
int r[MAXN], c[MAXN], a[MAXN];
bool bio[MAXN];
ll val[MAXN];
ll mini[MAXN];
int comp[MAXN];

void load() {
	scanf("%d%d%d", &R, &C, &N);
	for (int i = 0; i < N; i++)
		scanf("%d%d%d", r + i, c + i, a + i);
}

ll dfs(int x, ll c, int root) {
	val[x] = c;
	comp[x] = root;
	bio[x] = true;
	ll res = c;
	for (int i = 0; i < graph[x].size(); i++)
		if (!bio[graph[x][i].first])
			res = min(res, dfs(graph[x][i].first, c + graph[x][i].second, root));
	return res;
}

bool solve() {
	for (int i = 0; i < N; i++) 
		row[--r[i]].push_back(pii(--c[i], a[i]));

	for (int i = 0; i < R; i++)
		for (int j = 1; j < row[i].size(); j++) {
			graph[row[i][0].first].push_back(pii(row[i][j].first, row[i][j].second - row[i][0].second));
			graph[row[i][j].first].push_back(pii(row[i][0].first, row[i][0].second - row[i][j].second));
		}	

	for (int i = 0; i < C; i++) 
		if (!bio[i]) 
			mini[i] = dfs(i, 0, i);

	for (int i = 0; i < R; i++)
		for (int j = 1; j < row[i].size(); j++) 
			if (val[row[i][j].first] - val[row[i][0].first] != (ll)(row[i][j].second - row[i][0].second))
				return false;

	for (int i = 0; i < N; i++)
		if (a[i] - val[c[i]] + mini[comp[c[i]]] < 0)
			return false;

	return true;
}

int main() {
	load();
	puts(solve() ? "Yes" : "No");
	return 0;
}

