#define REP(i,n) for (int i=1;i<=(n);++i)
#define FOR(i,a,b) for (int i=(a);i<=(b);++i)
#define ROF(i,a,b) for (int i=(a);i>=(b);--i)
#define FEC(p,u) for (edge*p=head[u];p;p=p->nxt)
using namespace std;
typedef long long LL;

struct edge{ int b; LL c; edge *nxt; }e[210000], *le(e);
edge *head[110000];
void add(int u, int v, int c){ le->b = v, le->c = c, le->nxt = head[u], head[u] = le++; }

int f[110000];
LL pot[110000], pm[110000];
int inf = 1234567890;
LL INF = 1LL<<60;

LL ma, mpot;
void dfs(int x){
	ma = min(ma, pm[x]+pot[x]);
	mpot = max(mpot, pot[x]);
	FEC(p,x) if (f[p->b] == -1){
		f[p->b] = x;
		pot[p->b] = pot[x]+p->c;
		dfs(p->b);
	}
}

int R, C, m;
bool ans = true;

struct res{ int r, c, v; }inp[110000];
bool cmp(res x, res y){ return x.r < y.r || x.r == y.r && x.c < y.c; }

void work() {
	sort(inp+1, inp+m+1, cmp);
	REP(i,C) pm[i] = inf, head[i] = NULL;
	REP(i,m) pm[inp[i].c] = min(pm[inp[i].c], (LL)(inp[i].v));

	REP(i,m-1) if (inp[i].r == inp[i+1].r) {
		add(inp[i].c, inp[i+1].c, inp[i].v-inp[i+1].v);
		add(inp[i+1].c, inp[i].c, inp[i+1].v-inp[i].v);
	}
	FOR(i,1,C) f[i] = -1, pot[i] = -INF;
	FOR(i,1,C) if (f[i] == -1){
		ma = INF, mpot = -INF;
		f[i] = i; pot[i] = 0; dfs(i);
		if (ma < mpot) ans = false;
	}
	FOR(i,1,C) FEC(p,i) {
		if (pot[p->b] != pot[i]+p->c) ans = false;
	}
}
int main(){
	scanf("%d%d%d", &R, &C, &m);
	REP(i,m) scanf("%d%d%d", &inp[i].r, &inp[i].c, &inp[i].v);
	work();
	REP(i,m) swap(inp[i].r, inp[i].c);
	swap(R, C);
	le = e;
	work();
	if (ans) printf("Yes\n"); else printf("No\n");
	return 0;
}

