const int M = 100100;
const ll inf = 1e12;

int r, c, n;
bool used[M];
ll s[M];
vector<int> g[M], t[M];
vector<pair<int, int>> h[M];
ll mn[M];
int col[M];
ll clm[M];
bool nice = true;

void read() {
  fill(mn, mn + M, inf);
  fill(clm, clm + M, inf);

  cin >> r >> c >> n;
  for (int i = 0; i < n; ++i) {
    int x, y, a;
    cin >> x >> y >> a;
    --x, --y;

    mn[y] = min<ll>(mn[y], a);
    h[x].emplace_back(y, a);
  }
}

void add(int u, int v, int d) {
  g[u].push_back(v);
  t[u].push_back(d);

  g[v].push_back(u);
  t[v].push_back(-d);
}

void build() {
  for (int i = 0; i < r; ++i) {
    for (int j = 0; j + 1 < (int) h[i].size(); ++j) {
      int a = h[i][j].first;
      int b = h[i][j + 1].first;
      int d = h[i][j + 1].second - h[i][j].second;

      add(a, b, d);
    }
  }
}

void dfs(int v, ll cur, int cl) {
  used[v] = true;
  s[v] = cur;
  col[v] = cl;
  clm[cl] = min<ll>(clm[cl], cur);

  for (int i = 0; i < (int) g[v].size(); ++i) {
    int to = g[v][i];
    int by = t[v][i];

    if (used[to]) {
      nice &= s[to] == s[v] + by;
    } else {
      dfs(to, cur + by, cl);
    }
  }
}

void kill() {
  int cnt = 0;
  for (int i = 0; i < c; ++i)
    if (!used[i]) {
      dfs(i, 0, cnt++);
    }

  if (!nice) {
    cout << "No\n";
    return;
  }

  /*
  for (int i = 0; i < c; ++i) {
    cerr << "i = " << i << ", mn[i] = " << mn[i] << ", col[i] = " << col[i];
    cerr << ", s[i] = " << s[i] << endl;
  }

  cout << clm[0] << endl;
  */

  for (int i = 0; i < c; ++i) {
    ll res = mn[i] + clm[col[i]] - s[i];
    if (res < 0) {
      cout << "No\n";
      return;
    }
  }

  cout << "Yes\n";
}

int main() {
  cout.precision(20);
  cout << fixed;
  ios_base::sync_with_stdio(false);
  read();
  build();
  kill();
}

