typedef long long ll;
typedef pair<ll, ll> P;
#define X first
#define Y second

const int MAX = 1<<17;
const ll INF = 1e18;

P root[MAX];
ll minn[MAX];

P Find(ll x)
{
  if (root[x].X == x)
    return P(x, 0);
  P tmp = Find(root[x].X);
  tmp.Y += root[x].Y;
  return root[x] = tmp;
}

int Merge(int a, int b, ll raz) //a - b
{
  if (rand() % 2) {
    swap(a, b);
    raz = -raz;
  }

  P ta = Find(a);
  P tb = Find(b);

  if (ta.X == tb.X)
    return (ta.Y - tb.Y) == raz;

  root[b] = P(ta.X, ta.Y - tb.Y - raz);

  return 1;
}

pair <P, int> p[MAX];

int main()
{
  int n;

  scanf("%*d%*d%d", &n);

  for (int i=0; i<n; i++)
    scanf("%lld%lld%d", &p[i].X.X, &p[i].X.Y, &p[i].Y);

  int rje = 1;
  for (int st=0; st<2; st++) {
    sort(p, p + n);
    for (int i=0; i<MAX; i++)
      root[i] = P(i, 0);

    for (int i=1; i<n; i++)
      if (p[i].X.X == p[i-1].X.X)
        rje &= Merge((int) p[i].X.Y, (int) p[i-1].X.Y, p[i].Y - p[i-1].Y);

    for (int i=0; i<MAX; i++)
      minn[i] = INF;

    for (int i=0; i<MAX; i++)
      minn[root[i].X] = min(minn[root[i].X], root[i].Y);

    for (int i=0; i<n; i++) {
      int ind = (int) p[i].X.Y;
      if (minn[root[ind].X] - root[ind].Y + p[i].Y < 0)
        rje = 0;
    }

    for (int i=0; i<n; i++)
      swap(p[i].X.X, p[i].X.Y);
  }

  printf("%s\n", rje ? "Yes" : "No");

  return 0;
}

