#define rep(i,l,r) for(int i=l;i<=r;++i)
const int N=1e5+5;
bool ok;
struct BING
{
int n,last[N],lastv[N];
int fa[N],d[N],mn[N];
void init(int r,int c)
{
	n=r;
	rep(i,1,c)last[i]=0;
	rep(i,1,r){fa[i]=i;d[i]=0;mn[i]=0;}
}
void find(int x)
{
	if(fa[x]==x)return ;
	find(fa[x]);
	d[x]+=d[fa[x]];
	fa[x]=fa[fa[x]];
}
void merge(int x,int y,int dx)
{
	find(x);find(y);
	dx=dx-d[x]+d[y];
	x=fa[x];y=fa[y];
	//cerr<<x<<" "<<y<<" "<<dx<<endl;
	if(x==y){ok&=dx==0;return ;}
	fa[x]=y;d[x]=dx;
}
void ins(int x,int y,int a)
{
	if(!last[y])
	{
		last[y]=x;lastv[y]=a;
		return ;
	}
	merge(x,last[y],a-lastv[y]);
}
void init_mn()
{
	rep(i,1,n)
	{
		find(i);
		chmin(mn[fa[i]],d[i]);
	}
}
int get_mn(int x)
{
	return -d[x]+mn[fa[x]];
}
};
