bool vis[MAXN<<1];
inline void insert(int u,int v,int w)
{
	e[++cnt].to=v,e[cnt].next=head[u],head[u]=cnt,e[cnt].w=w;
	e[++cnt].to=u,e[cnt].next=head[v],head[v]=cnt,e[cnt].w=w;
}
int kn,km;
bool dfs(int x,int now)
{
	if(vis[x]){
		if(val[x]!=now)return false;
		return true;
	}
	vis[x]=true;
	val[x]=now;
	if(x<=n)kn=min(kn,now);
	else km=min(km,now);
	for(int i=head[x];i;i=e[i].next){
		if(!dfs(e[i].to,e[i].w-now))return false;
	}
	return true;
}
