	for(int i=1;i<=tot;++i){
		if(!vis[i]){
			kn=0x3f3f3f3f,km=0x3f3f3f3f;
			if(!dfs(i,0) || kn+km<0){
				puts("No");
				return 0;
			}
		}
	}
	puts("Yes");
