const ll inf = ll(1e18)+9;
int main() {
    // input
    int h, w; scanf("%d%d", &h, &w);
    int n; scanf("%d", &n);
    vector<tuple<int,int,int> > q(n);
    map<tuple<int,int>,int> f;
    map<int,map<int,int> > fh;
    map<int,map<int,int> > fw;
    repeat (i,n) {
        int y, x, a; scanf("%d%d%d", &y, &x, &a); -- y; -- x;
        q[i] = { y, x, a };
        f[make_tuple(y, x)] = a;
        fh[y][x] = a;
        fw[x][y] = a;
    }
    // compute
    bool ans = true;
    vector<ll> ph(h, inf);
    vector<ll> pw(w, inf);
    queue<tuple<int,int> > que;
    vector<bool> usedh(h, false);
    vector<bool> usedw(w, false);
    auto go = [&](int sy, int sx, int sa) {
        assert (ans);
        assert (ph[sy] == inf);
        assert (pw[sx] == inf);
        ph[sy] = sa; pw[sx] = 0;
        que.push(make_tuple(sy, sx));
        while (not que.empty()) {
            int y, x; tie(y, x) = que.front(); que.pop();
            int a = f[make_tuple(y, x)];
            bool useh = not usedh[y]; usedh[y] = true;
            bool usew = not usedw[x]; usedw[x] = true;
            if (useh) {
                for (auto it : fh[y]) {
                    int nx, na; tie(nx, na) = it;
                    if (pw[nx] == inf) {
                        pw[nx] = pw[x] - a + na;
                        if (not usedw[nx]) que.push(make_tuple(y, nx));
                    } else {
                        if (pw[nx] != pw[x] - a + na) { ans = false; return; }
                    }
                }
            }
            if (usew) {
                for (auto it : fw[x]) {
                    int ny, na; tie(ny, na) = it;
                    if (ph[ny] == inf) {
                        ph[ny] = pw[y] - a + na;
                        if (not usedh[ny]) que.push(make_tuple(ny, x));
                    } else {
                        if (pw[ny] != pw[y] - a + na) { ans = false; return; }
                    }
                }
            }
        }
    };
    repeat (i,n) {
        int y, x, a; tie(y, x, a) = q[i];
        if (ph[y] == inf and pw[x] == inf) {
            go(y, x, a);
        }
        if (not ans) break;
        if (ph[y] == inf) ph[y] = a - pw[x];
        if (pw[x] == inf) pw[x] = a - ph[y];
        if (a != ph[y] + pw[x]) { ans = false; break; }
    }
    // output
    fprintf(stderr, "%s\n", ans ? "Yes" : "No");
    printf("%s\n", ans ? "Yes" : "No");
    return 0;
}

