#include <bits/stdc++.h>
#define oo 1e18
using namespace std;

typedef long long ll;
const int N = 1e5 + 5;
int fax[N], fay[N], T, R, C, n;
ll mi1[N], mi2[N], wx[N], wy[N];
struct node {
	int x, y;
	ll val;
	void read( ) {
		scanf("%d%d%lld",& x,& y,& val);
	}
}P[N];

bool cmpx(const node & a, const node & b) {
	return a.x < b.x;
}

bool cmpy(const node & a, const node & b) {
	return a.y < b.y;
}

int find_x(int u) {

	if(fax[u] == u) return u;
	int rt = find_x(fax[u]);
	wx[u] += wx[fax[u]];
	return fax[u] = rt;
}

bool link_x(int u, int v, ll w) {

	int fu = find_x(u), fv = find_x(v);
	if(fu != fv) {
		fax[fu] = fv;
		wx[fu] = w + wx[v] - wx[u]; return true;
	}
	else return wx[u] == wx[v] + w;
}

int find_y(int u) {

	if(fay[u] == u) return u;
	int rt = find_y(fay[u]);
	wy[u] += wy[fay[u]];
	return fay[u] = rt;
}

bool link_y(int u, int v, ll w) {

	int fu = find_y(u), fv = find_y(v);
	if(fu != fv) {
		fay[fu] = fv;
		wy[fu] = w + wy[v] - wy[u]; return true;
	}
	else return wy[u] == wy[v] + w;
}

