	//freopen("then.in", "r", stdin);
	//freopen("then.out", "w", stdout);
	T = 1;
	while(T --) {
		bool tag = true;
		scanf("%d%d%d",& R,& C,& n);
		for(int i = 1;i <= R;i ++) {
			fax[i] = i; wx[i] = 0; 
		}
		for(int i = 1;i <= C;i ++) {
			fay[i] = i; wy[i] = 0;
		}
		for(int i = 1;i <= n;i ++) {
			P[i].read( );
			if(P[i].val < 0) tag = false;
		}
		sort(P + 1, P + n + 1, cmpx);
		for(int i = 1;i < n;i ++) {
			if(P[i].x == P[i + 1].x) 
				if(! link_y(P[i].y, P[i + 1].y, P[i + 1].val - P[i].val)) tag = false;
		}
		sort(P + 1, P + n + 1, cmpy);
		for(int i = 1;i < n;i ++) {
			if(P[i].y == P[i + 1].y)
				if(! link_x(P[i].x, P[i + 1].x, P[i + 1].val - P[i].val)) tag = false;
		}
		memset(mi1, 0x3f3f, sizeof(mi1));
		memset(mi2, 0x3f3f, sizeof(mi2));
		for(int i = 1;i <= n;i ++) {
			int rt = find_x(P[i].x);
			mi1[rt] = min(mi1[rt], P[i].val + wx[P[i].x]);
		}
		for(int i = 1;i <= R;i ++) {
			int rt = find_x(i);
			mi2[rt] = min(mi2[rt], -wx[i]);
		}
		ll cmp = oo;
		for(int i = 1;i <= R;i ++) cmp = min(cmp, mi1[i] + mi2[i]);
		if(cmp < 0) tag = false;
		if(tag) printf("Yes\n");
		else printf("No\n");
	}
}

