	seen[r] = true;
	for (int i = 0; i < adjList[r].size(); i++)
	{
		int r2 = adjList[r][i];
		dfs(r2);
		ldelta[r] = max(ldelta[r], gdelta[r][r2] + ldelta[r2]);
	}
