  //cout << " " << c << " " << d << endl;
  int minus = 0;
  if(a<0) minus++;
  if(b<0) minus++;
  if(c<0) minus++;
  if(d<0) minus++;
  if(minus == 0){
    if(a+d == b+c) return true;
    else return false;
  }
  if(minus == 1){
    if(a==-1){
      if(b+c>=d){
        in2[make_pair(y,x)] = b+c-d;
        return true;
      }
      else return false;
    }
    if(b==-1){
      if(a+d>=c){
        in2[make_pair(y,x+1)] = a+d-c;
        return true;
      }
      else return false;
    }
    if(c==-1){
      if(a+d>=b){
        in2[make_pair(y+1,x)] = a+d-b;
        return true;
      }
      else return false;
    }
    if(d==-1){
      if(b+c>=a){
        in2[make_pair(y+1,x+1)] = b+c-a;
        return true;
      }
      else return false;
    }
  }
  return true;
}
