using namespace std;

const int N = (int) 1e5 + 7;
const int C = -6969696;
const int C2 = -C;
int h, w;
int n;
map<int, int> x[N];
map<int, int> y[N];

int get_sum(int i) {
  set<int> difs;
  for (auto &it : x[i]) {
    if (x[i + 1].count(it.first)) {
      difs.insert(x[i][it.first] - x[i + 1][it.first]);
    }
  }
  if (difs.empty()) {
    return C;
  }
  if ((int) difs.size() == 1) {
    return *difs.begin();
  }
  return C2;
}

bool okx() {
  for (int i = 0; i + 1 < N; i++) {
    if (!x[i].empty() && !x[i + 1].empty()) {
      int val = get_sum(i);
      if (val == C) {
        continue;
      }
      if (val == C2) {
        return 0;
      }
      for (auto &it : x[i]) {
        if (it.second - val < 0) {
          return 0;
        }
      }
      for (auto &it : x[i + 1]) {
        if (-it.second + val < 0) {
          return 0;
        }
      }
    }
  }
  return 1;
}

