			//puts("XOK");
			int T = memo[Pii(i,j)];
			int A = memo[Pii(ay,ax)];
			int B = memo[Pii(by,bx)];
			int C = memo[Pii(cy,cx)];

			if(A && B && !C){
			//	cout << k << endl;
				if((T-1) + (A-1) - (B-1) < 0){
					puts("No");
					exit(0);
				}
				memo[Pii(cy,cx)] = (T-1) + (A-1) - (B-1) + 1;
			}
			else if(A && !B && C){
			//	cout << k << endl;
				if((T-1) + (A-1) - (C-1) < 0){
					puts("No");
					exit(0);
				}
				memo[Pii(by,bx)] = (T-1) + (A-1) - (C-1) + 1;
			}
			else if(!A && B && C){
			//	cout << k << endl;
				if((B-1) + (C-1) - (T-1) < 0){
					puts("No");
					exit(0);
				}
				memo[Pii(ay,ax)] = (B-1) + (C-1) - (T-1) + 1;
			}
			else if(A && B && C){
			//	cout << k << endl;
				if(A+T != B+C){
					puts("No");
					exit(0);
				}
			}
			else{
			//	cout << T << " " << A << " " << B << " " << C << endl;
			//	puts("HOGE");
			}
		}
	}
	puts("Yes");
	return 0;
}

