long long m1, m2;
void dfs(int x, long long v) {
  if (vis[x]) return;
  vis[x] = true;

  A[x] = v;
  if (x < R) m1 = min(m1, A[x]);
  else       m2 = min(m2, A[x]);

  for (P p : edges[x]) {
    dfs(p.first, (long long)p.second - A[x]);
  }
}

