	return f2[n]=fa;
}
inline bool merge1(int x,int y,int z)
{
	int t1=find1(x),t2=find1(y);
	if(t1!=t2)
	{
		f1[t1]=t2,w1[t1]=z+w1[y]-w1[x];
		return 1;
	}
	return w1[x]==z+w1[y];
}
inline bool merge2(int x,int y,int z)
{
	int t1=find2(x),t2=find2(y);
	if(t1!=t2)
	{
		f2[t1]=t2,w2[t1]=z+w2[y]-w2[x];
		return 1;
	}
	return w2[x]==z+w2[y];
}
int main()
{
	scanf("%d%d%d",&n,&m,&k);
	for(int i=1;i<=n;i++) f1[i]=i;
	for(int i=1;i<=m;i++) f2[i]=i;
	for(int i=1;i<=k;i++)
	{
		scanf("%d%d%d",&a[i].x,&a[i].y,&a[i].num);
		if(a[i].num<0) return puts("No"),0;
	}
	sort(a+1,a+k+1,cmp1);
	for(int i=1;i<k;i++)
	  if(a[i].x==a[i+1].x&&!merge1(a[i].y,a[i+1].y,a[i+1].num-a[i].num)) return puts("No"),0;
	sort(a+1,a+k+1,cmp2);
	for(int i=1;i<k;i++)
	  if(a[i].y==a[i+1].y&&!merge2(a[i].x,a[i+1].x,a[i+1].num-a[i].num)) return puts("No"),0;
	memset(t1,0x3f,sizeof(t1));
	memset(t2,0x3f,sizeof(t2));
	for(int i=1;i<=k;i++)
	{
		int fa=find1(a[i].x);
		t1[fa]=min(t1[fa],a[i].num+w1[a[i].x]);
	}
	for(int i=1;i<=n;i++)
	{
		int fa=find1(i);
		t2[fa]=min(t2[fa],-w1[i]);
	}
	for(int i=1;i<=n;i++)
	  if(f1[i]==i&&w1[i]+w2[i]<0) return puts("No"),0;
	puts("Yes");
	return 0;
}

