P root[MAX];

P Find(ll x)
{
  if (root[x].X == x)
    return P(x, 0);
  P tmp = Find(root[x].X);
  tmp.Y += root[x].Y;
  return root[x] = tmp;
}

int Merge(int a, int b, ll raz) //a - b
{
  if (rand() % 2) {
    swap(a, b);
    raz = -raz;
  }

  P ta = Find(a);
  P tb = Find(b);

  if (ta.X == tb.X)
    return (ta.Y - tb.Y) == raz;

  root[b] = P(ta.X, ta.Y - tb.Y - raz);

  return 1;
}

