    int from, to, a, b;
    tie(from, a) = *row[i].begin();
    for (auto p: row[i]) {
      tie(to, b) = p;
      erow[from].emplace_back(to, b - a);
    }
  }
  REP(i,C) {
    if (col[i].empty()) continue;
    int from, to, a, b;
    tie(from, a) = *col[i].begin();
    for (auto p: col[i]) {
      tie(to, b) = p;
      ecol[from].emplace_back(to, b - a);
    }
  }
  col.clear();
  // REP(i,R) {
  //   for (auto p: erow[i]) cout << i << " " << p.first << " " << p.second << endl;
  // }
  // REP(i,C) {
  //   for (auto p: ecol[i]) cout << i << " " << p.first << " " << p.second << endl;
  // }
  try {
    vector<ll> rval(R, -1), cval(C, -1);
    REP(i,R) {
      if (rval[i] != -1) continue;
      map<int,ll> val;
      val[i] = 0;
      dfs(i, erow, val);
      ll mi = 1e18;
      for (auto p: val) chmin(mi, p.second);
      for (auto p: val) rval[p.first] = p.second - mi;
    }
    REP(i,C) {
      if (cval[i] != -1) continue;
      map<int,ll> val;
      val[i] = 0;
      dfs(i, ecol, val);
      ll mi = 1e18;
      for (auto p: val) chmin(mi, p.second);
      for (auto p: val) cval[p.first] = p.second - mi;
    }
    // for (ll i: rval) cout << i << " "; cout << endl;
    // for (ll i: cval) cout << i << " "; cout << endl;
    REP(i,R) {
      for (auto p: row[i]) {
        int j, v; tie(j, v) = p;
        if (v < cval[i] + rval[j]) throw 0;
      }
    }
  }
  catch(int) {
    cout << "No" << endl;
    return 0;
  }
  cout << "Yes" << endl;
  return 0;
}

