const ll inf = ll(1e18)+9;
bool check(unordered_map<int,unordered_map<int,int> > const & fh) {
    unordered_map<int,int> minh;
    for (auto & row : fh) {
        ll acc = inf;
        for (auto it : row.second) setmin<ll>(acc, it.second);
        minh[row.first] = acc;
    }
    for (auto & row1 : fh) {
        for (auto & row2 : fh) {
            if (row1.first <= row2.first) continue;
            int y1 = row1.first; unordered_map<int,int> const *p1 = &row1.second;
            int y2 = row2.first; unordered_map<int,int> const *p2 = &row2.second;
            if (p1->size() > p2->size()) {
                swap(y1, y2);
                swap(p1, p2);
            }
            ll delta = inf;
            for (auto & it1 : *p1) {
                if (p2->count(it1.first)) {
                    ll delta1 = p2->at(it1.first) - it1.second;
                    if (delta == inf) delta = delta1;
                    if (delta != delta1) return false;
                }
            }
            if (delta == inf) continue;
            if (minh[y1] + delta < 0) return false;
            if (minh[y2] - delta < 0) return false;
        }
    }
    return true;
}
