inline bool has_num(int y, int x){
    return (num.find(y) != end(num) and num[y].find(x) != end(num[y]));
}

bool dfs(int y, int x){
    rep(i, 4){
        int ny = y + 2 * dy[i], nx = x + 2 * dx[i];
        if(not has_num(y, nx) or not has_num(ny, x) or not has_num(ny, nx)) continue;
        if(num[y][x] + num[ny][nx] != num[y][nx] + num[ny][x]) return false;
    }
    if(used[y][x]) return true;
    used[y][x] = true;

    bool ret = true;
    rep(i, 4){
        int ny = y + dy[i], nx = x + dx[i];
        if(not has_num(y, nx) or not has_num(ny, x)) continue;
        int nnum = num[y][nx] + num[ny][x] - num[y][x];
        if(nnum >= 0 and (not has_num(ny, nx) or num[ny][nx] == nnum)){
            num[ny][nx] = nnum;
            ret &= dfs(ny, nx);
        }
        else {
            ret = false;
        }
        if(not ret) break;
    }

    return ret;
}

