	ll R, C, n; cin >> R >> C >> n;
	map<pair<ll, ll>, ll> dict;
	vector<vector<pair<ll,ll>>> rl(R), cl(C);
	REP(i, n) {
		ll r, c, a; cin >> r >> c >> a; r--, c--;
		dict[make_pair(r, c)] = a;
		rl[r].push_back({ c, a });
		cl[c].push_back({ r, a });
	}
	vl sumR(R - 1, TEN(10)), sumC(C - 1, TEN(10));
	vl updateR, updateC;
	const vl dr = { 0, 0,  1, -1 };
	const vl dc = { 1, -1, 0 , 0 };
	auto update = [&](pair<pair<ll, ll>, ll> p) {
		pair<ll, ll> pos; ll val, r, c;
		tie(pos, val) = p; tie(r, c) = pos;
		REP(i, 4) {
			ll nr = dr[i] + r, nc = dc[i] + c;
			if (nr < R && nr >= 0 && nc < C && nc >= 0) {
				auto it = dict.find({ nr , nc });
				if (it != dict.end()) {
					ll sum = i%2 == 1 ? it->second - val : val - it->second;
					if (i >= 2) {
						if (sumR[min(nr, r)] == TEN(10)) {
							sumR[min(nr, r)] = sum;
							updateR.push_back(min(nr, r));
						}
						if (sumR[min(nr, r)] != sum) return false;
					} else {
						if (sumC[min(nc, c)] == TEN(10)) {
							sumC[min(nc, c)] = sum;
							updateC.push_back(min(nc, c));
						}
						if (sumC[min(nc, c)] != sum) return false;
					}
				}
			}
		}
		return true;
	};
	vector<pair<pair<ll,ll>, ll>> updateP;
	auto update2 = [&]() {
		for (ll c : updateC) {
			for (auto p : cl[c]) {
				auto it = dict.find({ p.first, c + 1 });
				if (it == dict.end()) {
					ll x = p.second - sumC[c];
					if (x < 0) return false;
					dict[{p.first, c + 1}] = x;
					cl[c + 1].push_back({ p.first, x });
					updateP.push_back({ { p.first, c + 1 } , x });
				} else if (sumC[c] != p.second - it->second) {
					return false;
				}
			}
			for (auto p : cl[c + 1]) {
				auto it = dict.find({ p.first, c });
				if (it == dict.end()) {
					ll x = p.second + sumC[c];
					if (x < 0) return false;
					dict[{p.first, c}] = x;
					cl[c].push_back({ p.first, x });
					updateP.push_back({ { p.first, c } , x });
				} else if (sumC[c] != it->second - p.second) {
					return false;
				}
			}
		}
		for (ll r : updateR) {
			for (auto p : rl[r]) {
				auto it = dict.find({ r + 1, p.first });
				if (it == dict.end()) {
					ll x = p.second - sumR[r];
					if (x < 0) return false;
					dict[{r + 1, p.first}] = x;
					rl[r + 1].push_back({ p.first, x });
					updateP.push_back({ { r + 1, p.first } , x });
				} else if (sumR[r] != p.second - it->second) {
					return false;
				}
			}
			for (auto p : rl[r + 1]) {
				auto it = dict.find({ r, p.first });
				if (it == dict.end()) {
					ll x = p.second + sumR[r];
					if (x < 0) return false;
					dict[{r, p.first}] = x;
					rl[r].push_back({ p.first, x });
					updateP.push_back({ { r, p.first } , x });
				} else if (sumR[r] != it->second - p.second) {
					return false;
				}
			}
		}
		return true;
	};
	for (auto p : dict) if (!update(p)) {
		cout << "No" << endl;
		return 0;
	}
	while (!updateC.empty() && !updateR.empty()) {
		if (!update2()) {
			cout << "No" << endl;
			return 0;
		}
		updateC.clear(); updateR.clear();
		for (auto p : updateP) if (!update(p)) {
			cout << "No" << endl;
			return 0;
		}
		updateP.clear();
	}
	cout << "Yes" << endl;

	return 0;
}

