        set<int> defined;
        set<int> added;
        vll diff(c, nd);
        int current_r = rows[0][1];
        rep (i, (int)ca[current_r].size()) {
            diff[ca[current_r][i][0]] = ca[current_r][i][1] - ca[current_r][0][1];
            defined.insert(ca[current_r][i][0]);
            added.insert(current_r);
        }
        rows.erase(begin(rows));
        current_all_r -= 1;

        int offset;
        int j = 0;
        while (j < current_all_r) {
            current_r = rows[j][1];
            bool included = false;
            int common_c;
            for (int elm : ci[current_r]) {
                if (defined.find(elm) != end(defined)) {
                    included = true;
                    common_c = elm;
                    break;
                }
            }
            if (!included) {
                j += 1;
                continue;
            }
            offset = diff[common_c] - rc_a[mp(current_r, common_c)];
            rep (i, (int)ca[current_r].size()) {
                int newdiff = offset + rc_a[mp(current_r, ca[current_r][i][0])];
                if (diff[ca[current_r][i][0]] != nd && diff[ca[current_r][i][0]] != newdiff) {
                    printf("No\n");
