            current_all_r -= 1;
        }
        ll diffmax = INT_MIN;
        ll diffmin = INT_MIN;
        for (ll elm : defined) {
            diffmax = max(diffmax, diff[elm]);
            diffmin = min(diffmin, diff[elm]);
        }
        if (diffmin - offset < 0) {
            printf("No\n");
            return 0;
        }
    }

    printf("Yes\n");
    return 0;
}

