int main() {
	int c, r, n;
	scanf("%d%d%d", &r, &c, &n);
	stack<pair<int, int> > q;
	f(i, 0, n) {
		int a, b, c;
		scanf("%d%d%d", &a, &b, &c);
		mp[make_pair(a, b)] = c;
		q.push(make_pair(a, b));
	}
	while (!q.empty()) {
		int a, b;
		ll c;
		tie(a, b) = q.top();
		q.pop();
		c = mp[make_pair(a, b)];
		f(i, 0, 4) {
			int j = i + 1;
			if (j == 4)j = 0;
			int a1 = dx[i] + a, a2 = dx[j] + a, b1 = dy[i] + b, b2 = dy[j] + b;
			pair<int, int> x = make_pair(a1, b1), y = make_pair(a2, b2);
			pair<int, int> z = make_pair(a + dx[i + 4], b + dy[i + 4]);
			map<pair<int, int>, ll>::iterator itx = mp.find(x), ity = mp.find(y), itz = mp.find(z);
			if (itx != mp.end() && ity != mp.end()) {
				if (itx->second + ity->second < c)NO();
				if (itz != mp.end() && itx->second + ity->second != itz->second + c)NO();
				if (itz == mp.end())mp[z] = itx->second + ity->second - c, q.push(z);
			}
			if (itz != mp.end()) {
				if (itx != mp.end() && itz->second + c < itx->second)NO();
				if (itx != mp.end() && ity == mp.end())mp[y] = c + itz->second - itx->second, q.push(y);
				if (ity != mp.end() && itz->second + c < ity->second)NO();
				if (ity != mp.end() && itx == mp.end())mp[x] = c + itz->second - ity->second, q.push(x);
			}
			if (itz != mp.end() && ity == mp.end() && itx == mp.end())mp[x] = c, q.push(x);
			if (itx != mp.end() && ity == mp.end() && itz == mp.end())mp[y] = c, q.push(y);
			if (ity != mp.end() && itz == mp.end() && itx == mp.end())mp[x] = c, q.push(x);
		}
	}
	printf("Yes\n");
}

