vector<pll> vals;
bool was[MAXN];

void addE(int v, int u, ll sum) {
	assert(v != u);
	g[v].pb(mp(u, sum));
	g[u].pb(mp(v, sum));
}

bool dfs1(int v) {
	was[v] = true;
	assert(vals[v].snd >= 0);
	assert(vals[v].fst == 0);
	for (const auto& e : g[v]) {
		int to = e.fst;
		ll sum = e.snd;
		if  (vals[to].snd != -1) {
			if  (vals[v].snd + vals[to].snd != sum) {
				return false;
			}
		} else {
			vals[to] = mp(0, sum - vals[v].snd);
			if  (vals[to].snd < 0) {
				return false;
			}
		}
		if  (!was[to]) {
			if  (!dfs1(to)) {
				return false;
			}
		}
	}
	return true;
}

bool dfs2(int v, ll& low, ll& up, vi& vs) {
	ll a, b;
	tie(a, b) = vals[v];

	if  (a == 0) {
		if  (b < 0) {
			return false;
		}
	} else if  (a > 0) {
		low = max(low, (-b + a - 1) / a);
	} else {
		assert(a < 0);
		up = min(up, (b) / (-a));
	}

	vs.pb(v);
	was[v] = true;
	for (const auto& e : g[v]) {
		int to = e.fst;
		ll sum = e.snd;
		if  (was[to]) {
			ll c, d;
			tie(c, d) = vals[to];
			ll right = sum - (b + d);
			ll left = a + c;
			if  (left == 0) {
				if  (right != 0) {
					return false;
				}
				continue;
			} else if  (right % left != 0) {
				return false;
			}
			low = max(low, right / left);
			up = min(up, right / left);
			continue;
		}
		assert(vals[to] == mp(-1ll, -1ll));
		vals[to].fst = -a;
		vals[to].snd = -b + sum;
		dfs2(to, low, up, vs);
	}

	return true;
}

bool solve_comp(int v) {
	vals[v] = mp(1, 0);
	ll low = -INF;
	ll up = INF;
	vi vs;
	if  (!dfs2(v, low, up, vs)) {
		return false;
	}
	if  (up < 0 || low > up) {
		return false;
	}
	for (int u : vs) vals[u] = mp(-1, -1);
	vals[v] = mp(0, v < R ? low : up);
	return true;
}

bool solve() {
	vals.assign(R + C, mp(-1, -1));
	forn(i, R + C) g[i].clear();
	forn(i, n) {
		if (ps[i].r == ps[0].r) {
			assert(vals[R + ps[i].c].snd == -1);
			vals[R + ps[i].c] = mp(0, ps[i].val);
		}
		if (ps[i].c == ps[0].c) {
			assert(vals[ps[i].r].snd == -1);
			vals[ps[i].r] = mp(0, ps[i].val);
		}
		if  (ps[i].r != ps[0].r && ps[i].c != ps[0].c) {
			int v = ps[i].r;
			int u = R + ps[i].c;
			addE(v, u, ps[0].val + ps[i].val);
		}
	}

	// forn(i, R + C) {
	// 	printf("%d: %lld %lld\n", i, vals[i].fst, vals[i].snd);
	// 	for (auto e : g[i]) {
	// 		int to = e.fst;
	// 		ll sum = e.snd;
	// 		printf(" -> %d %lld\n", to, sum);
	// 	}
	// }
	// puts("----");

	memset (was, 0, sizeof was);
	forn(i, R + C) {
		if (vals[i].snd != -1 && !was[i]) {
			if  (!dfs1(i)) {
				return false;
			}
		}
	}

	forn(i, R + C) {
		if  (!was[i]) {
			if  (!solve_comp(i)) {
				return false;
			}
		}
	}

	// forn(i, R + C) {
	// 	printf("%d: %lld %lld\n", i, vals[i].fst, vals[i].snd);
	// 	for (auto e : g[i]) {
	// 		int to = e.fst;
	// 		ll sum = e.snd;
	// 		printf(" -> %d %lld\n", to, sum);
	// 	}
	// }
	// puts("----");

	{
		memset (was, 0, sizeof was);
		forn(i, R + C) {
			if (vals[i].snd != -1 && !was[i]) {
				assert(vals[i].snd >= 0);
				assert(vals[i].fst == 0);
				if  (!dfs1(i)) {
					return false;
				}
			}
		}
	}

	ll min_col = INF;
	ll min_row = INF;
	forn(i, R) min_col = min(min_col, vals[i].snd);
	forn(i, C) min_row = min(min_row, vals[R + i].snd);
	if  (min_col + min_row < ps[0].val) {
		return false;
	}

	forn(v, R + C) {
		for (const auto& e : g[v]) {
			int to = e.fst;
			ll sum = e.snd;
			assert(vals[v].snd + vals[to].snd == sum);
		}
		assert(vals[v].fst == 0);
		assert(vals[v].snd >= 0);
	}

	return true;
}

