using namespace std;
using ll = int64_t;

struct Cell {
  int x, y;

  bool operator<(const Cell& other) const {
    if (x != other.x)
      return x < other.x;
    return y < other.y;
  }
};

struct Condition {
  Cell a, b;
  int sum;
};

int R, C, n;
map<Cell, int> values;
queue<Cell> q;
vector<Condition> conditions;

void fail() {
  cout << "No" << endl;
  cout.flush();
  exit(0);
}

bool valid(Cell a) {
  return a.x >= 1 && a.y >= 1 && a.x <= R && a.y <= C;
}

void relax_zero(Cell a, Cell b, Cell c, Cell d) {
  array<Cell, 4> cells = {a, d, b, c};
  int already = 0;
  for (auto cell : cells) {
    if (!valid(cell))
      return;
    already += values.count(cell);
  }
  if (already == 4) {
    int i = 0;
    int sum = values[cells[(i ^ 2)]] + values[cells[(i ^ 2) ^ 1]];
    int current_sum = values[cells[i ^ 1 ]] + values[cells[i]];
    if (sum != current_sum)
      fail();
  }
}

void relax_zero() {
  for (auto p : values)
    q.push(p.first);
  while (!q.empty()) {
    auto p = q.front();
    q.pop();
    relax_zero(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x + 1, p.y + 1});
    relax_zero(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x + 1, p.y - 1});
    relax_zero(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x - 1, p.y + 1});
    relax_zero(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x - 1, p.y - 1}); 
  }
  for (auto p : values)
    q.push(p.first);
}

void relax_single(Cell a, Cell b, Cell c, Cell d) {
  array<Cell, 4> cells = {a, d, b, c};
  int already = 0;
  for (auto cell : cells) {
    if (!valid(cell))
      return;
    already += values.count(cell);
  }
  if (already == 3) {
    for (int i = 0; i < 4; i++) {
      if (!values.count(cells[i])) {
        int sum = values[cells[(i ^ 2)]] + values[cells[(i ^ 2) ^ 1]];
        int brother = values[cells[i ^1]];
        if (brother > sum) {
          fail();
        }
        values[cells[i]] = sum - brother;
      }
    }

    for (auto cell : cells)
      q.push(cell);
  }
}

void relax_single() {
  for (auto p : values)
    q.push(p.first);
  while (!q.empty()) {
    auto p = q.front();
    q.pop();
    relax_single(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x + 1, p.y + 1});
    relax_single(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x + 1, p.y - 1});
    relax_single(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x - 1, p.y + 1});
    relax_single(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x - 1, p.y - 1}); 
  }
}

void prepare_conditions() {
  for (auto p : values)
    q.push(p.first);
  while (!q.empty()) {
    auto p = q.front();
    q.pop();
    relax_single(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x + 1, p.y + 1});
    relax_single(p, Cell{p.x + 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x + 1, p.y - 1});
    relax_single(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y + 1}, Cell{p.x - 1, p.y + 1});
    relax_single(p, Cell{p.x - 1, p.y}, Cell{p.x, p.y - 1}, Cell{p.x - 1, p.y - 1}); 
  }
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  cin >> R >> C >> n;
  for (int i = 0; i < n; i++) {
    int x, y, value;
    cin >> x >> y >> value;
    values[Cell{x, y}] = value;
  }

  relax_zero();
  relax_single();
  relax_zero();
  prepare_conditions();

  cout << "Yes" << endl;

  return 0;
}

