bool dfs(int i) {
  minv = min(minv, v[x[i]]);
  minu = min(minu, u[y[i]]);
  used[i] = true;
  for (int ii = 0; ii < 4; ii++) {
    int j = g[i][ii];
    if (j == -1 || used[j]) {
      continue;
    }
    if (ii & 1) {
      int vv = v[x[i]] + a[j] - a[i];
      if (usedr[x[j]] && v[x[j]] != vv) {
        return false;
      }
      v[x[j]] = vv;
      usedr[x[j]] = true;
      if (!dfs(j)) {
        return false;
      }
    } else {
      int uu = u[y[i]] + a[j] - a[i];
      if (usedc[y[j]] && u[y[j]] != uu) {
        return false;
      }
      u[y[j]] = uu;
      usedc[y[j]] = true;
      if (!dfs(j)) {
        return false;
      }
    }
  }
  return true;
}

