    rows[x[i]].push_back(make_pair(y[i], i));
    cols[y[i]].push_back(make_pair(x[i], i));
    for (int j = 0; j < 4; j++) {
      g[i][j] = -1;
    }
  }
  for (int i = 0; i < r; i++) {
    sort(rows[i].begin(), rows[i].end());
    for (int j = 0; j + 1 < sz(rows[i]); j++) {
      g[rows[i][j].second][0] = rows[i][j + 1].second;
      g[rows[i][j + 1].second][2] = rows[i][j].second;
    }
  }
  for (int i = 0; i < c; i++) {
    sort(cols[i].begin(), cols[i].end());
    for (int j = 0; j + 1 < sz(cols[i]); j++) {
      g[cols[i][j].second][1] = cols[i][j + 1].second;
      g[cols[i][j + 1].second][3] = cols[i][j].second;
    }
  }
  for (int i = 0; i < n; i++) {
    used[i] = false;
  }
  for (int i = 0; i < n; i++) {
