	for(int i=1;i<k;i++)
	  if(a[i].x==a[i+1].x&&!merge1(a[i].y,a[i+1].y,a[i+1].num-a[i].num)) return puts("No"),0;
	sort(a+1,a+k+1,cmp2);
	for(int i=1;i<k;i++)
	  if(a[i].y==a[i+1].y&&!merge2(a[i].x,a[i+1].x,a[i+1].num-a[i].num)) return puts("No"),0;
	memset(t1,0x3f,sizeof(t1));
	memset(t2,0x3f,sizeof(t2));
	for(int i=1;i<=k;i++)
	{
		int fa=find1(a[i].x);
		t1[fa]=min(t1[fa],a[i].num+w1[a[i].x]);
	}
	for(int i=1;i<=n;i++)
	{
