struct Edge{
    int from, to;
    Weight weight;
    int rev;     // 無向グラフの対の辺
    Edge(int from, int to, Weight weight) :
        from(from), to(to), weight(weight) { }
    Edge(int from, int to, Weight weight, int rev) :
        from(from), to(to), weight(weight), rev(rev){ }
};
bool operator < (const Edge &a, const Edge &b){
    if(a.weight != b.weight) return a.weight > b.weight;
    if(a.from != b.from) return a.from > b.from;
    return  a.to > b.to;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;
typedef vector<Weight> Array;
typedef vector<Array> Matrix;

void addFlowEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, 0, g[a].size() - 1));
}
void addUndirectedEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, c, g[a].size() - 1));
}


bool bellmanFord(const Graph &g, int s, vector<Weight> &dist, vector<int> &prev){
    int n = g.size();
    bool nagativeRoop = false;
    dist.assign(n, INF); dist[s] = 0;
    prev.assign(n, -1);
    for(int k = 0; k < n; ++k){
        for(int v = 0; v < n; ++v){
            EACH(i, g[v]){
            //for(Edges::const_iterator i=g[v].begin(); i != g[v].end(); ++i){
                if(dist[i -> from] != INF && dist[i -> to] > dist[i -> from] + i -> weight){
                    dist[i -> to] = dist[i -> from] + i-> weight;
                    prev[i -> to] = i -> from;
                    if(k == n - 1){
                        dist[i -> to] = -INF;
                        nagativeRoop = true;
                    }
                }
            }
        }
    }
    return nagativeRoop;
}
bool findNegativeRoop(const Graph &g){
    int n = g.size();
    vector<Weight> dist(n, 0);
    for(int k = 0; k < n; ++k){
        for(int v = 0; v < n; ++v){
            EACH(i, g[v]){
            //for(Edges::const_iterator i=g[v].begin(); i != g[v].end(); ++i){
                if(dist[i -> to] > dist[i -> from] + i -> weight){
                    dist[i -> to] = dist[i -> from] + i -> weight;
                    if(k == n - 1) return true;
                }
            }
        }
    }
    return false;
}
vector<int> buildPath(const vector<int> &prev, int t){
    vector<int> path;
    for(int v = t; v >= 0; v = prev[v])
        path.push_back(v);
    reverse(path.begin(), path.end());
    return path;
}


bool func(vector<vector<int>> &rlist, vector<vector<int>> &clist, map<pair<int,int>, int> &mp){
	int R = rlist.size(), C = clist.size();

	Graph g(C);
	for(int i = 0; i < R; ++i){
		for(int j = 0; j + 1 < rlist[i].size(); ++j){
			int c1 = rlist[i][j], c2 = rlist[i][j+1];
			int a = mp[make_pair(i, c1)];
			int b = mp[make_pair(i, c2)];
			g[c1].push_back(Edge(c1, c2, a - b));
			g[c2].push_back(Edge(c2, c1, b - a));
		}
	}

	// g でベルマンフォードをやって，負の閉路を探す

	vector<bool> vst(C);
	for(int i = 0; i < C; ++i) if(!vst[i]){
		vector<int> prev;
		vector<ll> dist;
		if(bellmanFord(g, i, dist, prev)){
			for(int i = 0; i < C; ++i){
				EACH(j, g[i]){
					cout << i << j->to << "," << j->weight << endl;
				}
			}
			return false;
		}

		ll mn = (ll)(1e+15), mx = -(ll)(1e+15);
		for(int i = 0; i < C; ++i) if(prev[i] >= 0){
			vst[i] = true;
			mn = min(mn, dist[i]);
			mx = max(mx, dist[i]);
		}
		for(int i = 0; i < C; ++i) if(prev[i] >= 0){
			ll bb = mx - dist[i];
			cout <<" " << bb << endl;
			for(auto r: clist[i]){
				ll a = mp[make_pair(r, i)];
				if(a - bb < 0) return false;
			}
		}
	}

	return true;
}

int main(){
	int R, C, N;
	cin >> R >> C >> N;
	vector<int> r(N), c(N), a(N);
	map<pair<int,int>, int> mp, rmp;

	vector<vector<int>> rlist(R), clist(C);

	for(int i = 0; i < N; ++i){
		cin >> r[i] >> c[i] >> a[i];

		r[i]--; c[i]--;
		mp[make_pair(r[i], c[i])] = a[i];
