bool check(const set<pair<int, int>>& se, int& plus) {
    bool updated = false;
    pair<int, int> before;
    for(const auto& cur : se) {
        if(updated == false) {
            before = cur;
            updated = true;
            continue;
        }
        if(plus == -1) {
            int sa1 = cur.first - before.first;
            int sa2 = cur.second - before.second;
            if(sa2 < 0 || sa2 % sa1 != 0) return false;
            plus = sa2 / sa1;
            continue;
        }
        int sa1 = cur.first - before.first;
        int sa2 = cur.second - before.second;

        if(sa2 < 0 || sa2 % sa1 != 0) return false;
        if(plus != sa2 / sa1) return false;
    }
    return true;
}
