typedef long long ll;
const int INF = 1e9;
int R,C,N;
int board[100002][100001];

int count_set(int ii,int jj){
    int c =0;
    for(int i=0;i<2;i++){
        for(int j=0;j<2;j++){
            if(board[ii+i][jj+j]!=-1)c++;
        }
    }
    return c;
}

void solve(){
    for(int i=1;i<=R;i+=2){
        for(int j=1;j<=C-1;j++){
            int c = count_set(i,j);
            if(c==3){//3埋め
               for(int ii=0;ii<2;ii++){
                    for(int jj=0;jj<2;jj++){
                        if(board[ii+i][jj+j]==-1){
                            if(ii==0&&jj==0){
                                board[ii+i][jj+j] = board[ii+i+1][jj+j]+board[ii+i][jj+j+1]-board[ii+i+1][jj+j+1];
                            }
                            else if(ii==0&jj==1){
                                board[ii+i][jj+j] = board[ii+i+1][jj+j]+board[ii+i][jj+j-1]-board[ii+i+1][jj+j-1];
                            }
                            else if(ii==1&jj==0){
                                board[ii+i][jj+j] = board[ii+i-1][jj+j]+board[ii+i][jj+j+1]-board[ii+i-1][jj+j+1];
                            }
                            else if(ii==1&&jj==1){
                                board[ii+i][jj+j] = board[ii+i-1][jj+j]+board[ii+i][jj+j-1]-board[ii+i-1][jj+j-1];
                            }
                            if(board[ii+1][jj+j]>=0)continue;
                            else{
                                cout << "No" << endl;
                                return;
                            }
                        }
                    }
               }
            }
            else if(c==4){//今埋めたやつはいい
                if(board[i][j]+board[i+1][j+1]==board[i+1][j]+board[i][j+1])continue;
                else{
                    cout << "No" << endl;
                    return;
                }
            }
        }
    }
    cout << "Yes" <<endl;
}

