const int dx[] = {0, 1, 1, 0};
const int dy[] = {0, 1, 0, 1};

int r, c;
int n;
vector<PII> G[200005];
bool vis[200005];
LL w[200005];
LL rMin, cMin;

void dfs(int v, LL h) {
  vis[v] = true;
  w[v] = h;
  for (int i = 0; i < G[v].size(); i += 1) {
    int nxtV = G[v][i].first, cost = G[v][i].second;
    if (!vis[nxtV]) {
      dfs(nxtV, cost - h);
    }
  }
}

bool check(int v) {
  vis[v] = true;
  if (v < r) rMin = min(rMin, w[v]);
  else cMin = min(cMin, w[v]);
  for (int i = 0; i < G[v].size(); i += 1) {
    int nxtV = G[v][i].first, cost = G[v][i].second;
    if (w[v] + w[nxtV] != cost) return false;
  }
  for (int i = 0; i < G[v].size(); i += 1) {
    int nxtV = G[v][i].first;
    if (!vis[nxtV]) {
      if (!check(nxtV)) return false;
    }
  }
  return true;
}

int main() {
  scanf("%d %d", &r, &c);
  scanf("%d", &n);
  for(int i = 0; i < n; i += 1) {
    int x, y, a;
    scanf("%d %d %d", &x, &y, &a);
    x -= 1; y -= 1;
    G[x].push_back(PII(r + y, a));
    G[r + y].push_back(PII(x, a));
  }
  for(int i = 0; i < r + c; i += 1) {
    vis[i] = false;
  }
  for(int i = 0; i < r + c; i += 1) {
    if (!vis[i]) dfs(i, 0);
  }
  bool flag = true;
  for(int i = 0; i < r + c; i += 1) {
    vis[i] = false;
  }
  for (int i = 0; i < r + c; i += 1) {
    if (!vis[i]) {
      rMin = LLONG_MAX; cMin = LLONG_MAX;
      if (!check(i)) flag = false;
      if (rMin + cMin < 0) flag = false;
    }
  }
  printf("%s\n", flag ? "YES" : "NO");
  return 0;
}

