    int r, c, a;
    cin >> r >> c >> a;
    r --;
    c --;
    row[r].push_back(pair<int, int>(c, a));
    column[c].push_back(pair<int, int>(r, a));
  }

  vector<vector<pair<int, int> > > c2(C), r2(R);
  for (int i=0; i<R; i++)
    for (int j=1; j<row[i].size(); j++) {
      int id1 = row[i][0].first;
      int sc1 = row[i][0].second;
      int id2 = row[i][j].first;
      int sc2 = row[i][j].second;
      c2[id1].push_back(pair<int, int>(id2, sc2 - sc1));
      c2[id2].push_back(pair<int, int>(id1, sc1 - sc2));
    }
  for (int i=0; i<C; i++)
    for (int j=1; j<column[i].size(); j++) {
      int id1 = column[i][0].first;
      int sc1 = column[i][0].second;
      int id2 = column[i][j].first;
      int sc2 = column[i][j].second;
      r2[id1].push_back(pair<int, int>(id2, sc2 - sc1));
      r2[id2].push_back(pair<int, int>(id1, sc1 - sc2));
    }
  if (validate(c2) && validate(r2))
    cout << "Yes" << endl;
  else cout << "No" << endl;
}

