//[x, y]
void upd(int x, int y, LL v){
    for (int i = y; i > 0; i -= i & -i){
        a[i] += v;
    }
    for (int i = x - 1; i > 0; i -= i & -i){
        a[i] -= v;
    }
}

LL que(int x){
    LL ret = 0;
    for (int i = x; i <= n; i += i & -i){
        ret += a[i];
    }
    return ret;
}

int xx[N], yy[N];
LL zz[N];
int ok = 1;

void ff(int);

int main(){
//    ios::sync_with_stdio(false);
    cin >> n >> m;
    cin >> q;
    FOR(i,0,q){
        int x, y;
        LL z;
        cin >> x >> y >> z;
        xx[i] = x;
        yy[i] = y;
        zz[i] = z;
    }
    ff(0);
    ff(1);
    if (ok) cout << "Yes\n";
    else cout << "No\n";
    return 0;
}
void ff(int o){
    LL mn, mx;
    mn = mx = 0;
    d = 0;
    if (o){
        FOR(i,0,q) swap(xx[i], yy[i]);
        swap(n, m);
    }
    FOE(i,0,n) mp[i].clear();
    FOE(i,1,n) upd(i, i, -que(i));
    memset(f, 0, sizeof(f));
    FOR(i,0,q){
        int x = xx[i], y = yy[i];
        LL z = zz[i];
        mp[x][y] = z;
 //       printf("%d %d\n", x, y);
   //     printf("%d\n", mp[x].size());
    }
    upd(1, n, -1);
    //FOE(i,1,n)
      //  printf("%d\n", mp[i].size());
    for (auto& it : mp[n]){
        int j = it.first;
        LL z = it.second;
        upd(j, j, z + 1);
        f[j] = 1;
        //printf("%d %d\n", n, j);
    }
    for (int i = n - 1; i > 0 && ok; i--){
        int vis = 0;
        LL td = 0;
        for(auto it : mp[i]){
            int j = it.first;
            LL z = it.second;
            LL cv = que(j);
          //  printf("%d %d %lld %lld %lld\n", i, j, z, cv, td);
            if (f[j]){
                if (vis){
                    if (z - cv != td){
                        ok = 0;
                    }
     //               puts("vis");
                }
                else{
                    td = z - cv;
                    vis = 1;
                }
                upd(j, j, z - cv);
            }
            else{
                f[j] = 1;
                upd(j, j, z - cv);
                if (z < d - mn)
                    ok = 0;
            }
            d += td;
            mn = min(mn, d);
            mx = max(mx, d);
            if (!ok) break;
        }
    }
    FOE(i,1,n) fin[i] = que(i);
    FOE(i,1,n) if (f[i] && fin[i] < 0) ok = 0;
    FOE(i,1,n) ini[i] = fin[i] - d;
    FOE(i,1,n) if (f[i] && ini[i] + mn < 0) ok = 0;
}

