#define mk(a,b) make_pair(a,b)
#define fi first
#define se second

typedef long long ll;
typedef pair<ll, ll> pll;

int H,W,N;
int Y[100010],X[100010];
ll A[100010];
ll INF = 1000000000000000000;
vector<pll> V[100010], G[100010];
ll D[100010], dif[100010];
vector<int> vis;
ll MIN;

bool flag = false;

void DFS(int v, ll d)
{
    if(D[v] != INF)
    {
        if(D[v] != d)flag = true;
        return;
    }
    D[v] = d;
    if(MIN > d)MIN = d;
    vis.push_back(v);

    for(int i = 0; i < G[v].size(); i++)
    {
        pll e = G[v][i];
        DFS(e.fi, d + e.se);
    }
}

int main()
{
    cin >> H >> W >> N;
    for(int i = 0; i < N; i++)cin >> Y[i] >> X[i] >> A[i];

    for(int i = 0; i < 100010; i++)D[i] = INF;

    for(int i = 0; i < N; i++)V[Y[i]].push_back(mk(X[i], A[i]));
    for(int i = 0; i < 100010; i++)sort(V[i].begin(), V[i].end());

    for(int i = 0; i < 100010; i++)
    {
        for(int j = 0; j + 1 < V[i].size(); j++)
        {
            pll a = V[i][j];
            pll b = V[i][j + 1];
            G[a.fi].push_back(mk(b.fi, b.se - a.se));
            G[b.fi].push_back(mk(a.fi, a.se - b.se));
        }
    }

    for(int i = 0; i < 100010; i++)
    {
        if(D[i] == INF)
        {
            vis.clear();
            MIN = INF;
            DFS(i, 0);
            if(flag)
            {
                cout << "No" << endl;
                return 0;
            }

            for(int j = 0; j < vis.size(); j++)
            {
                int now = vis[j];
                dif[now] = MIN - D[now];
            }
        }
    }

    for(int i = 0; i < N; i++)
    {
        int x = X[i];
        if(dif[x] + A[i] < 0)
        {
            cout << "No" << endl;
            return 0;
        }
    }

    for(int i = 0; i < 100010; i++)
    {
        V[i].clear();
        G[i].clear();
    }
    for(int i = 0; i < 100010; i++)D[i] = INF;

    for(int i = 0; i < N; i++)V[X[i]].push_back(mk(Y[i], A[i]));
    for(int i = 0; i < 100010; i++)sort(V[i].begin(), V[i].end());
    for(int i = 0; i < 100010; i++)
    {
        for(int j = 0; j + 1 < V[i].size(); j++)
        {
            pll a = V[i][j], b = V[i][j + 1];
            G[a.fi].push_back(mk(b.fi, b.se - a.se));
            G[b.fi].push_back(mk(a.fi, a.se - b.se));
        }
    }

    for(int i = 0; i < 100010; i++)
    {
        if(D[i] == INF)
        {
            vis.clear();
            MIN = INF;
            DFS(i, 0);
            if(flag)
            {
                cout << "No" << endl;
                return 0;
            }

            for(int j = 0; j < vis.size(); j++)
            {
                int now = vis[j];
                dif[now] = MIN - D[now];
            }
        }
    }

    for(int i = 0; i < N; i++)
    {
        int y = Y[i];
        if(dif[y] + A[i] < 0)
        {
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;
    return 0;
}

