void merge(int p, int q, ll sub) {
  if (W[p].size() > W[q].size()) {
    merge(q, p, -sub);
  } else {
    for (auto x : W[p]) {
      int col = x.first;
      ll val = x.second;
      ind[col] = q;
      W[q][col] = val + sub;
    }
    mini[q] = min(mini[q], mini[p] + sub);
  }
}

bool issame(int p, int q) {
  return (ind[p] == ind[q]);
}

ll calc_sa(int p, int q) {
  return W[ind[q]][q] - W[ind[p]][p];
}

