signed main() {
	INIT;
	VAR(int, R, C, N);
	std::vector<int> row(R, INFLL), col(C, INFLL);
	std::map<int, std::map<int, int>> a;
	std::map<int, std::vector<int>> r_c, c_r;
	int startR;
	REP(i, N) {
		VAR(int, r, c, _a);
		a[--r][--c] = _a;
		r_c[r].emplace_back(c);
		c_r[c].emplace_back(r);
		if (i == 0) startR = r;
	}

	std::vector<bool> checkedR(R), checkedC(C);
	std::function<bool(int, int)> dfs = [&](int r, int c) {
		bool flag = true;
		if (c == -1) {
			for (const auto& _c : r_c[r]) {
				if (checkedC[_c]) {
					if (row[r] + col[_c] != a[r][_c]) flag &= false;
					else flag &= true;
				}
				else {
					checkedC[_c] = true;
					col[_c] = a[r][_c] - row[r];
					flag &= dfs(-1, _c);
				}
			}
		}
		else {
			for (const auto& _r : c_r[c]) {
				if (checkedR[_r]) {
					if (col[c] + row[_r] != a[_r][c]) flag &= false;
					else flag &= true;
				}
				else {
					checkedR[_r] = true;
					row[_r] = a[_r][c] - col[c];
					flag &= dfs(_r, -1);
				}
			}
		}
		return flag;
	};
	row[startR] = 0;
	checkedR[startR] = true;
	if (!dfs(startR, -1) || *std::min_element(ALL(row)) + *std::min_element(ALL(col)) < 0) {
