#include <bits/stdc++.h>

using namespace std;

const int maxValue = 2000000000;

void noAnswer() {
    cout << "No" << endl;
    exit(0);
}

int r, c;
map<pair<int, int>, int> field;

typedef vector<int> vi;

vi rowLow;
vi rowHigh;
vi colLow;
vi colHigh;

void setRowLow(int rn, int val) {
    rowLow[rn] = max(rowLow[rn], val);
}

void setRowHigh(int rn, int val) {
    rowHigh[rn] = min(rowHigh[rn], val);
}

void setColLow(int cn, int val) {
    colLow[cn] = max(colLow[cn], val);
}

void setColHigh(int cn, int val) {
    colHigh[cn] = min(colHigh[cn], val);
}

void setRow(int rn, int val) {
    if (val < rowLow[rn])
        noAnswer();
    if (val > rowHigh[rn])
        noAnswer();
    setRowLow(rn, val);
    setRowHigh(rn, val);
}

void setCol(int cn, int val) {
    if (val < colLow[cn])
        noAnswer();
    if (val > colHigh[cn])
        noAnswer();
    setColLow(cn, val);
    setColHigh(cn, val);
}

void check(int x, int y, int v) {
    if (x > 0) {
        auto it = field.find(make_pair(x-1, y));
        if (it != field.end()) {
            setRow(x-1, it->second - v);
        } else {
            setRowLow(x-1, -v);
        }
    }

    if (x + 1 < r) {
        auto it = field.find(make_pair(x+1, y));
        if (it != field.end()) {
            setRow(x, v - it->second);
        } else {
            setRowHigh(x, v);
        }
    }

    if (y > 0) {
        auto it = field.find(make_pair(x, y - 1));
        if (it != field.end()) {
            setCol(y-1, it->second - v);
        } else {
            setColLow(y-1, -v);
        }

    }

    if (y + 1 < c) {
        auto it = field.find(make_pair(x, y + 1));
        if (it != field.end()) {
            setCol(y, v - it->second);
        } else {
            setColHigh(y, v);
        }
    }

}

int main()
{
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    scanf("%d %d", &r, &c);

    rowLow.assign(r, -maxValue);
    rowHigh.assign(r, maxValue);
    colLow.assign(c, -maxValue);
    colHigh.assign(c, maxValue);

    int n;
    scanf("%d", &n);

    for (int i = 0; i < n; ++i) {
        int a, b, v;
        scanf("%d %d %d", &a, &b, &v);
        --a, --b;
        field[make_pair(a, b)] = v;
        check(a, b, c);
    }

    bool ok = true;

    for (int i = 0; i < r; ++i) {
        if (rowLow[i] > rowHigh[i])
            ok = false;
    }

    for (int i = 0; i < c; ++i) {
        if (colLow[i] > colHigh[i])
            ok = false;
    }

    cout << (ok ? "Yes" : "No") << endl;

    return 0;
}

