int r, c, n;
vector<pair<int, int> > vr[(int)1e5];
vector<pair<int, int> > vc[(int)1e5];
bool used[2][(int)1e5];
int score[2][(int)1e5];

pair<int, int> dfs(int pos, int value, bool first, bool tate){
	if(first){
		used[(int)!tate][pos] = 1;
		score[(int)!tate][pos] = 0;
		pair<int, int> ret = pair<int, int>(1145141919 * (int)!tate, 1145141919 * (int)tate);
		for(auto next : (tate ? vr[pos] : vc[pos])){
			auto temp = dfs(next.first, next.second, 0, !tate);
			ret = pair<int, int>(min(ret.first, temp.first), min(ret.second, temp.second));
		}
		return ret;
	}
	used[(int)!tate][pos] = 1;
	score[(int)!tate][pos] = value;
	pair<int, int> ret = pair<int, int>((tate ? value : 1145141919), (tate ? 1145141919 : value));
	for(auto next : (tate ? vr[pos] : vc[pos])){
		if(used[(int)tate][next.first]){
			if(score[(int)tate][next.first] + value != next.second) return pair<int, int>(-1, - 1);
			else continue;
		}
		auto temp = dfs(next.first, next.second - value, 0, !tate);
		ret = pair<int, int>(min(ret.first, temp.first), min(ret.second, temp.second));
	}
	return ret;
}

