	}
	for(int i = 0; i < r; ++i){
		if(!used[0][i]){
			pair<int, int> ret = dfs(i, 0, 1, 1);
			if(ret.first + ret.second < 0){
				cout << "No\n";
				return 0;
			}
		}
	}
	for(int i = 0; i < c; ++i){
		if(!used[1][i]){
			pair<int, int> ret = dfs(i, 0, 1, 0);
			if(ret.first + ret.second < 0){
				cout << "No\n";
				return 0;
			}
		}
	}
	cout << "Yes\n";
	return 0;
}

