  for (int i = 0; i < R; ++i) {
    f[i] = i;
    minv[i] = INF64;
  }
  for (int i = 0, j; i < n; i = j) {
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      int k = visit[a[j].y];
      if (k >= 0) {
        delta[a[j].x] = a[j].v - a[k].v;
        break;
      }
    }
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      a[j].v -= delta[a[j].x];
      minv[a[j].x] = min(minv[a[j].x], a[j].v);
    }
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      int k = visit[a[j].y];
      if (k < 0) {
        visit[a[j].y] = j;
      } else {
        if (a[k].v != a[j].v) {
          puts("No");
          return 0;
        }
        join(a[j].x, a[k].x);
      }
    }
  }
  for (int i = 0; i < R; ++i) {
    if (minv[find(i)] + delta[i] < 0) {
      puts("No");
      return 0;
    }
  }
  puts("Yes");
  return 0;
}

