using namespace std;

int main() {
    ios::sync_with_stdio(false);
    int R, C; cin >> R >> C;

    int N; cin >> N;
    vector< vector< pair<int, int> > > edgesR(R), edgesC(C);
    for (int i = 0; i < N; ++i) {
        int r, c, a; cin >> r >> c >> a;
        --r; --c;
        edgesR[r].emplace_back(c, a);
        edgesC[c].emplace_back(r, a);
    }

    vector<bool> usedR(R, false), usedC(C, false);
    vector<int> valueR(R), valueC(C);
    vector<int> componentR, componentC;

    queue< pair<bool, int> > Q;
    for (int i = 0; i < R; ++i)
        if (!usedR[i]) {
            if (edgesR[i].empty())
                continue;
            Q.emplace(true, i);
            valueR[i] = 0;
            componentR.clear();
            componentC.clear();
            usedR[i] = true;
            while (!Q.empty()) {
                bool isRow; int node;
                tie(isRow, node) = Q.front();
                Q.pop();
                if (isRow) {
                    componentR.emplace_back(node);
                    for (auto &c : edgesR[node]) {
                        if (usedC[c.first]) {
                            if (valueC[c.first] + valueR[node] != c.second) {
                                cout << "No\n";
                                return 0;
                            }
                            continue;
                        }
                        usedC[c.first] = true;
                        valueC[c.first] = c.second - valueR[node];
                        Q.emplace(false, c.first);
                    }
                } else {
                    componentC.emplace_back(node);
                    for (auto &r : edgesC[node]) {
                        if (usedR[r.first]) {
                            if (valueR[r.first] + valueC[node] != r.second) {
                                cout << "No\n";
                                return 0;
                            }
                            continue;
                        }
                        usedR[r.first] = true;
                        valueR[r.first] = r.second - valueC[node];
                        Q.emplace(true, r.first);
                    }
                }
            }

            int maxt = numeric_limits<int>::max();
            int mint = 0;
            for (auto &v : componentR)
                mint = max(mint, -valueR[v]);
            for (auto &v : componentC)
                maxt = min(maxt, valueC[v]);
            if (maxt < mint) {
                cout << "No\n";
                return 0;
            }
        }
    cout << "Yes\n";
}

