vector<bool> used;
vector<long> value;
int m1=INF, m2=INF;

void dfs(int n, int v){
	used[n]=true;
	value[n]=v;
	if(n<R && value[n]<m1){
		m1=value[n];
	}else if(n>=R && value[n]<m2){
		m2=value[n];
	}

	REP(i, edge[n].size()){
		if(!used[edge[n][i].to]){
			dfs(edge[n][i].to, edge[n][i].cost-v);
		}
	}
}

