	}

	for(int i = 0; i < N; i++){
		if(RC[i].second - row_dif[RC[i].first.first] + min_row[row_parent[RC[i].first.first]] - col_dif[RC[i].first.second] + min_col[col_parent[RC[i].first.second]] < 0){
			cout << "No" << endl;
