						m[i+1][j] = m[i + 1][j + 1] - m[i][j + 1] + m[i + 1][j + 1];
				}
				if (m[i][j + 1] == -1)
				{
					if (numEmpty == 1)
						m[i][j+1] = -m[i + 1][j] + m[i][j] + m[i + 1][j + 1];
				}
				if (m[i + 1][j + 1] == -1)
				{
					if (numEmpty == 1)
						m[i+1][j+1] = m[i + 1][j] + m[i][j + 1] - m[i][j];
				}
			}
		}
		if(wasAZero)
			break;
	}

	bool yes = true;
	for (int i = 0; i < r - 1; ++i)
	{
		for (int j = 0; j < c - 1; ++j)
		{
			if(m[i][j] + m[i+1][j+1] != m[i + 1][j] + m[i][j + 1])
			{
				yes = false;
				break;
			}
			if(m[i][j] < 0)
			{
				yes = false;
				break;
			}
			if(m[i+1][j] < 0)
			{
				yes = false;
				break;
			}
			if(m[i][j+1] < 0)
			{
				yes = false;
				break;
			}
			if(m[i+1][j+1] < 0)
			{
				yes = false;
				break;
			}
		}
	}

	cout << (yes ? "Yes" : "No");
	return 0;
}

