template<class T> T gcd(T a, T b) { return b ? gcd(b, a % b) : a; }
template<class T> T lcm(T a, T b) { return a / gcd(a, b) * b; }
ll mod_pow(ll a, ll n, ll mod) {
	ll ret = 1;
	ll p = a % mod;
	while (n) {
		if (n & 1) ret = ret * p % mod;
		p = p * p % mod;
		n >>= 1;
	}
	return ret;
}
template<class T> T extgcd(T a, T b, T& x, T& y) { for (T u = y = 1, v = x = 0; a;) { T q = b / a; swap(x -= q * u, u); swap(y -= q * v, v); swap(b -= q * a, a); } return b; }
template<class T> T mod_inv(T a, T m) { T x, y; extgcd(a, m, x, y); return (m + x % m) % m; }

using Pii = pair<int, int>;
using Pll = pair<ll, ll>;

class UnionFind {
private:
	int n;
	vector<int> a;
public:
	UnionFind(int n) : n(n), a(n, -1) {}
	int find(int x) { return a[x] < 0 ? x : (a[x] = find(a[x])); }
	bool same(int x, int y) { return find(x) == find(y); }
	bool same(Pii& p) { return same(p.first, p.second); }
	bool unite(int x, int y) {
		x = find(x), y = find(y);
		if (x == y) return false;
		if (a[x] > a[y]) swap(x, y);
		a[x] += a[y];
		a[y] = x;
		n--;
		return true;
	}
	bool unite(Pii& p) { return unite(p.first, p.second); }
	int size() const { return n; }
	int size(int x) { return -a[find(x)]; }
};

bool used[ten(5) * 2];
int x[ten(5) * 2];
int a[ten(5) * 2];

int main() {
	int r, c; reader(r, c);
	int n; reader(n);

	vector<vector<Pii>> g(r + c);
	FOR(i, n) {
		int a, b, x; reader(a, b, x);
		a--; b--;
		g[a].emplace_back(b + r, x);
		g[b + r].emplace_back(a, x);
	}
	FOR(i, r + c) {
		if (used[i]) continue;

		int b = 0, e = 1;
		x[0] = i;
		used[i] = true;
		a[i] = 0;
		while (b < e) {
			for(auto to : g[x[b]]) {
				int u, val; tie(u, val) = to;
				if (used[u]) {
					if (a[x[b]] + a[u] != val) {
						puts("No");
						return 0;
					}
					continue;
				}
				x[e] = u;
				a[u] = val - a[x[b]];
				used[u] = true;
				e++;
			}
			b++;
		}

		int m1 = 1e15, m2 = 1e15;
		FOR(j, e) {
			if (x[j] < r) m1 = min(m1, a[x[j]]);
			else m2 = min(m2, a[x[j]]);
		}
		if (m1 + m2 < 0) {
			puts("No");
			return 0;
		}
	}
	puts("Yes");

	return 0;
}

