int T[100000];

bool g(int x) {
  for (auto &p : B[x]) {
    int u = p._1, v = T[x] + p._2;
    if (T[u] != INF && T[u] != v) return false;
    if (T[u] == INF) {
      T[u] = v;
      if (!g(u)) return false;
    }
  }
  return true;
}

bool f() {
  for (int y=0; y<R; y++) {
    sort(G[y].begin(), G[y].end());
    P &a = G[y][0];
    for (int i=1; i<G[y].size(); i++) {
      P &b = G[y][i];
      B[a._1].push_back(P(b._1, b._2-a._2));
    }
  }
  for (int x=0; x<C; x++) T[x] = INF;
  T[0] = 0;
  if (!g(0)) return false;
  for (int x=0; x<C; x++) {
    if (T[x] == INF) {
      T[x] = (1LL<<55);
      if (!g(x)) return false;
    }
  }
  int ma = INF, mb = INF;
