void dfsR(int r, ll b) {
  Rb[r] = b;
  vector<cell> ces;
  ces.swap(R[r]);
  for (auto& ce : ces) {
    if (!C[ce.c].empty()) {
      dfsC(ce.c, ce.a - b);
    } else if (Cb[ce.c] != ce.a - b) {
      ub = numeric_limits<ll>::min();
      lb = numeric_limits<ll>::max();
    }
  }
  //  printf("%d: x+%lld\n", r, b);
  lb = max(lb, -b);
}
// SC[r]=b-x
void dfsC(int c, ll b) {
  Cb[c] = b;
  vector<cell> ces;
  ces.swap(C[c]);
  for (auto& ce : ces) {
    if (!R[ce.r].empty()) {
      dfsR(ce.r, ce.a - b);
    } else if (Rb[ce.r] != ce.a - b) {
      ub = numeric_limits<ll>::min();
      lb = numeric_limits<ll>::max();
    }
  }
  //  printf("%d: %lld-x\n", c, b);
  ub = min(ub, b);
}

