void solve(){
    int r,c,n;
    cin >> r >> c >> n;
    vector<vector<pair<int,int>>> ps(c);
    vector<map<int,int>> mp(r);
    set<pair<int,int>> exist;
    rep(i,0,n){
        int x,y,a;
        cin >> y >> x >> a;
        --x;
        --y;
        ps[x].push_back(make_pair(y,a));
        mp[y][x]=a;
        exist.insert(make_pair(y,x));
    }

    rep(x,0,c) sort(ps[x].begin(),ps[x].end());

    vector<int> req(r-1);
    rep(y,0,r-1){
        int k=-inf;
        for(auto &p:mp[y]){
            int x=p.first;
            if(exist.find(make_pair(y+1,x))==exist.end()) continue;
            int diff=mp[y+1][x]-mp[y][x];
            if(k==-inf) k=diff;
            else if(k!=diff){
                cout << "No" << endl;
                return;
            }
        }
        req[y]=k;
    }
    vector<int> dp(r-1,inf);
    for(int y=r-2; y>=0; --y){
        if(req[y]==-inf) continue;
        dp[y]=req[y];
        if(y!=r-2) dp[y]=min(dp[y],dp[y+1]+req[y]);
     }
     rep(y,0,r-1){
         if(mp[y].size()==0) continue;
         int mini=inf;
         for(auto &p:mp[y]) mini=min(mini,p.second);
         if(mini+dp[y]<0){
             cout << "No" << endl;
             return;
         }
     }

    cout << "Yes" << endl;
}

