const long long INF = 1LL<<60;

int R, C, N, M;
Graph G;

vector<int> tmp;
vector<long long> vals;

bool rec(int v, long long val) {
    vals[v] = val;
    for (auto e : G[v]) {
        if (vals[e.first] != -1) {
            if (val + vals[e.first] != e.second) return false;
            continue;
        }
        if (!rec(e.first, e.second - val)) return false;
    }
    tmp.push_back(v);
    return true;
}   

