        --r, --c;
        c += R;
        G[r].push_back({c, a});
        G[c].push_back({r, a});
    }

    bool res = true;
    vals.assign(N, -1);
    for (int v = 0; v < N; ++v) {
        if (vals[v] != -1) continue;
        tmp.clear();
        if (!rec(v, 0)) res = false;
        long long lmi = INF, rmi = INF;
        for (auto t : tmp) {
            if (t < R) lmi = min(lmi, vals[t]);
            else rmi = min(rmi, vals[t]);
        }
        if (lmi + rmi < 0) res = false;
    }
