int gcd(int a, int b)
{
    return b ? gcd(b, a % b) : a;
}

bool check(int R, int C, int x, int y, int val)
{
    // 左上
    if(val-x*R-y*C < 0) return false;
    // 右上
    if(val-x*R+y*(c-C-1) < 0) return false;
    // 左下
    if(val+x*(r-R-1)-y*C < 0) return false;
    // 右下
    if(val+x*(r-R-1)+y*(c-C-1) < 0) return false;
    return true;
}

bool ok(tri hoge)
{
    if(hoge.fi == 0){
        if(abs(hoge.th) % abs(hoge.se)){
            return false;
        }
        return check(vec[0].fi, vec[0].se, 0, hoge.th / hoge.se, num[0]);
    }else if(hoge.se == 0){
        if(abs(hoge.th) % abs(hoge.fi)){
            return false;
        }
        return check(vec[0].fi, vec[0].se, hoge.th / hoge.fi, 0, num[0]);
    }
    ll x, y;
    for(x = -200000; x < 200001; x++){
        if(abs(hoge.th-hoge.fi*x) % abs(hoge.se)) continue;
        y = (hoge.th-hoge.fi*x) / hoge.se;
        if(check(vec[0].fi, vec[0].se, x, y, num[0])) return true;
    }
    for(y = -200000; y < 200001; y++){
        if(abs(hoge.th-hoge.se*y) % abs(hoge.fi)) continue;
        x = (hoge.th-hoge.se*y) / hoge.fi;
        if(check(vec[0].fi, vec[0].se, x, y, num[0])) return true;
    }
    return false;
}

