vpii getSquare1(int x, int y) {
    return {{x,     y},
            {x,     y + 1},
            {x + 1, y},
            {x + 1, y + 1}};
}

vpii getSquare2(int x, int y) {
    return {{x,     y - 1},
            {x,     y},
            {x + 1, y - 1},
            {x + 1, y}};
}

vpii getSquare3(int x, int y) {
    return {{x - 1, y},
            {x - 1, y + 1},
            {x,     y},
            {x,     y + 1}};
}

vpii getSquare4(int x, int y) {
    return {{x - 1, y - 1},
            {x - 1, y},
            {x,     y - 1},
            {x,     y}};
}

vpii getSquare(int x, int y, int i) {
    if (i == 0)
        return getSquare1(x, y);
    if (i == 1)
        return getSquare2(x, y);
    if (i == 2)
        return getSquare3(x, y);
    return getSquare4(x, y);
}

void solve() {
    int n, m, k;
    cin >> n >> m >> k;
    map<pii, ll> a;
    set<pii> XY;
    queue<pii> q;
    forn(i, k) {
        int x, y, z;
        cin >> x >> y >> z;
        XY.insert({x, y});
        a[{x, y}] = z;
        q.push({x, y});
    }
    while (!q.empty()) {
        int x = q.front().F, y = q.front().S;
        q.pop();
        forn(i0, 4) {
            vpii xy = getSquare(x, y, i0);
            bool flag = true;
            forn(i, 4) {
                if (xy[i].F <= 0 || xy[i].S <= 0 || xy[i].F > n || xy[i].S > m) {
                    flag = false;
                    break;
                }
            }
            if (!flag) continue;
            int cnt = 0;
            vll A(4);
            forn(i, 4) {
                A[i] = a[xy[i]];
                if (XY.count(xy[i])) cnt++;
            }
            ll sum1 = A[0] + A[3], sum2 = A[1] + A[2];
            if (cnt == 4 && sum1 != sum2) {
                cout << "No\n";
                return;
            }
            if (cnt == 3) {
                forn(i, 4) {
                    if (!XY.count(xy[i])) {
                        if (i == 0) A[i] = A[1] + A[2] - A[3];
                        if (i == 1) A[i] = A[0] + A[3] - A[2];
                        if (i == 2) A[i] = A[0] + A[3] - A[1];
                        if (i == 3) A[i] = A[1] + A[2] - A[0];
                        if (A[i] < 0){
                            cout << "No\n";
                            return;
                        }
                        a[xy[i]] = A[i];
                        XY.insert(xy[i]);
                        q.push(xy[i]);
                    }
                }
            }
        }
    }
    cout << "Yes\n";
}

