bool valid(){
  REP(i,125252)used[i] = false;
  dist[0] = 0;
  used[0] = true;
  queue<int> Q;
  Q.push(0);
  while(!Q.empty()){
    int p = Q.front(); Q.pop();
    ll d = dist[p];
    REP(i,g[p].size()){
      int to = g[p][i].first;
      int cost = g[p][i].second;
      ll nd = d+cost;
      if(used[to]){
