    y=My[ps[i].second];
    xs[y].push_back(x);
    ys[x].push_back(y);
    ps[i] = pii(x,y);
    rev[ps[i]] = i;
  }
  // graph
  REP(i,125252)g[i].clear();
  REP(i,r){
    vi &vec = ys[i];
    sort(ALL(vec));
    REP(j,vec.size()-1){
