    ll d = dist[i+1]-dist[i];
    add(0,i+1,d);
    add(i+1,c,-d);
  }
  // graph
  REP(i,125252)g[i].clear();
  REP(i,c){
    vi &vec = xs[i];
    sort(ALL(vec));
    REP(j,vec.size()-1){
