      s = vec[j];
      t = vec[j+1];
      int sid = rev[pii(s,i)];
      int tid = rev[pii(t,i)];
      int sa = val[tid]-val[sid];
      g[s].push_back(pii(t,sa));
      g[t].push_back(pii(s,-sa));
    }
  }
  if(!valid()){
    puts("No");
    return 0;
  }
  // negative check
  init(r);
  REP(i,c){
    ll mn = query(0,r);
    if(mn + xs[i][0] < 0){
      puts("No");
      return 0;
    }
    if(i==c-1)break;
    ll d = dist[i+1]-dist[i];
    add(0,i+1,d);
    add(i+1,r,-d);
  }
  // ok
