	}
}

void dfsw(int x) {
	visw[x] = 1;
	for (int i : w[x]) {
		if (vish[r[i]]) {
			if (W[x] + H[r[i]] != a[i]) {
				f = false;
			}
		}
		else {
			H[r[i]] = a[i] - W[x];
			dfsh(r[i]);
		}
	}
}

signed main() {
	cin >> R >> C >> N;
	f = true;
	for (int i = 0; i < N; ++i) {
		cin >> r[i] >> c[i] >> a[i];
		--r[i];
		--c[i];
		h[r[i]].push_back(i);
		w[c[i]].push_back(i);
	}
	for (int i = 0; i < N; ++i) {
		if (!vish[r[i]]) {
			v.clear();
			dfsh(r[i]);
			int minh, minw;
			minh = minw = intmax;
			for (int j : v) {
				minh = min(minh, H[r[j]]);
				minw = min(minw, W[c[j]]);
			}
			for (int j : v) {
				if (vish[r[j]] == 1) {
					H[r[j]] -= minh;
					++vish[r[j]];
				}
				if (visw[c[j]] == 1) {
					W[c[j]] -= minw;
					++visw[c[j]];
				}
				if (H[r[j]] + W[c[j]] > a[j])f = false;
			}
		}
	}
	puts(f ? "Yes" : "No");
}

