void dfs(int s, int ind){
	used[s] = 1;
	if (ind == 0){
		mxl = max(mxl, dp[s]);
	} else {
		mnr = min(mnr, dp[s]);
	}
	REP(i, 0, SZ(g[s])){
		int to = g[s][i]._1;
		if (!used[to]){
			dp[to] = dp[s] + g[s][i]._2;
			dfs(to, ind ^ 1);
		} else if (dp[to] != dp[s] + g[s][i]._2){
			//printf("%d %d %d %lld %lld\n", s, to, g[s][i]._2, dp[s], dp[to]);
