using namespace std;

#define DBGOUT if(0) cout

bool matrix_exists(unordered_map<int, unordered_map<int, int>>& matrix, int i, int j) {
	auto it = matrix.find(i);
	if(it == matrix.end()) {
		return false;
	}

	auto arr = it->second;
	auto it2 = arr.find(j);
	if(it2 == arr.end()) {
		return false;
	}

	return true;
}

bool fill_matrix_square(unordered_map<int, unordered_map<int, int>>& matrix, int i, int j, bool& changed) {
	changed = false;

	int filled = 0;
	if(matrix_exists(matrix, i, j)) {
		filled++;
	}
	if(matrix_exists(matrix, i + 1, j)) {
		filled++;
	}
	if(matrix_exists(matrix, i, j + 1)) {
		filled++;
	}
	if(matrix_exists(matrix, i + 1, j + 1)) {
		filled++;
	}

	if(filled == 4) {
		bool ret =
			matrix[i][j] + matrix[i + 1][j + 1] ==
			matrix[i + 1][j] + matrix[i][j + 1];

		if(!ret) DBGOUT << "failed " << __LINE__;
		return ret;
	}

	if(filled == 3) {
		changed = true;
		if(!matrix_exists(matrix, i, j)) {
			matrix[i][j] = matrix[i + 1][j] + matrix[i][j + 1] - matrix[i + 1][j + 1];
			bool ret = matrix[i][j] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(!matrix_exists(matrix, i + 1, j + 1)) {
			matrix[i + 1][j + 1] = matrix[i + 1][j] + matrix[i][j + 1] - matrix[i][j];
			bool ret = matrix[i + 1][j + 1] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(!matrix_exists(matrix, i + 1, j)) {
			matrix[i + 1][j] = matrix[i][j] + matrix[i + 1][j + 1] - matrix[i][j + 1];
			bool ret = matrix[i + 1][j] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
		if(!matrix_exists(matrix, i, j + 1)) {
			matrix[i][j + 1] = matrix[i][j] + matrix[i + 1][j + 1] - matrix[i + 1][j];
			bool ret = matrix[i][j + 1] >= 0;
			if(!ret) DBGOUT << "failed " << __LINE__;
			return ret;
		}
	}

	return true;
}

int main() {
	int rows, cols, n;
	cin >> rows >> cols >> n;

	unordered_map<int, unordered_map<int, int>> matrix;

	for(int j = 0; j < n; j++) {
		int r, c, a;
		cin >> r >> c >> a;
		matrix[r - 1][c - 1] = a;
	}

	bool loop = true;
	while(loop)	{
		loop = false;

		for(int i = 0; i < rows - 1; i++) {
			for(int j = 0; j < cols - 1; j++) {
				bool changed;
				if(!fill_matrix_square(matrix, i, j, changed)) {
					cout << "No";
					return 0;
				}

				if(changed) {
					loop = true;
				}
			}
		}
	}

	cout << "Yes";
	return 0;
}

