bool check(const set<pair<int, int>>& se, i64& plus) {
    bool updated = false;
    pair<int, int> before;
    for(const auto& cur : se) {
        if(updated == false) {
            before = cur;
            updated = true;
            continue;
        }
        if(plus == -1) {
            i64 sa1 = (i64)(cur.first - before.first);
            i64 sa2 = (i64)(cur.second - before.second);
            if(sa2 < 0 || sa2 % sa1 != 0) return false;
            plus = sa2 / sa1;
            continue;
        }
        i64 sa1 = (i64)(cur.first - before.first);
        i64 sa2 = (i64)(cur.second - before.second);

        if(sa2 < 0 || sa2 % sa1 != 0) return false;
        if(plus != sa2 / sa1) return false;
    }
    return true;
}
