map<PLL,ll> m;  //  m{y,x} -> a，ただしxはないかもしれん
map<PLL,ll> m2; //  m{x,y} -> a，ただしyはないかもしれん

signed main(){
    ll H,W,N;
    cin>>H>>W>>N;
    ll dh=0; // 横方向の公差
    ll dv=0; // 縦方向の公差

    rep(i,0,N){
        ll y,x,a;
        cin>>y>>x>>a;
        y--; x--;
        m [{y,x}] = a;
        m2[{x,y}] = a;
    }

    // 同一の行に2つの値があれば公差 dh の算出
    for(auto it = m.begin(); it != m.end(); ++it) {
        ll y = it->first.first;
        ll x = it->first.second;
        ll a = it->second;

        auto nit = it; nit++;
        if(nit==m.end()) continue;
        ll ny = nit->first.first;
        ll nx = nit->first.second;
        ll na = nit->second;

        if(y==ny){
            dh = (na-a) / (nx-x);
            if( (na-a) % (nx-x) != 0) {
                cout<<"No"<<endl;
                return 0;
            }
        }
    }
    //cout<<"dh="<<dh<<endl;

    // 同一の列に2つの値があれば公差 dv の算出
    for(auto it = m2.begin(); it != m2.end(); ++it) {
        ll x = it->first.first;
        ll y = it->first.second;
        ll a = it->second;

        auto nit = it; nit++;
        if(nit==m2.end()) continue;
        ll nx = nit->first.first;
        ll ny = nit->first.second;
        ll na = nit->second;

        if(x==nx){
            dv = (na-a) / (ny-y);
            if( (na-a) % (ny-y) != 0) {
                cout<<"No"<<endl;
                return 0;
            }
        }
    }
    //cout<<"dv="<<dv<<endl;

    // 公差dh チェック
    for(auto it = m.begin(); it != m.end(); ++it) {
        ll y = it->first.first;
        ll x = it->first.second;
        ll a = it->second;

        ll mi = a-x*dh;
        ll ma = a+(W-x-1)*dh;
        if(mi<0 || ma<0) {
            cout<<"No"<<endl;
            return 0;
        }

        auto nit = it; nit++;
        if(nit!=m.end()) { // 次があるならチェック
            ll ny = nit->first.first;
            ll nx = nit->first.second;
            ll na = nit->second;
            //cout<<"y="<<y<<",x="<<x<<endl;
            //cout<<"ny="<<ny<<",nx="<<nx<<endl;
            if(y==ny){
                ll d = (na-a) / (nx-x);
                if( (na-a) % (nx-x) != 0 || d != dh) {
                    cout<<"No"<<endl;
                    return 0;
                }
            }
        }
    }

    // 公差dv チェック
    for(auto it = m2.begin(); it != m2.end(); ++it) {
        ll x = it->first.first;
        ll y = it->first.second;
        ll a = it->second;

        ll mi = a-y*dv;
        ll ma = a+(H-y-1)*dv;
        if(mi<0 || ma<0) {
            cout<<"No"<<endl;
            return 0;
        }

        auto nit = it; nit++;
        if(nit!=m2.end()) { // 次があるならチェック
            ll nx = nit->first.first;
            ll ny = nit->first.second;
            ll na = nit->second;
            if(x==nx){
                ll d = (na-a) / (ny-y);
                if( (na-a) % (ny-y) != 0 || d != dv) {
                    cout<<"No"<<endl;
                    return 0;
                }
            }
        }
    }

    cout<<"Yes"<<endl;


    return 0;
}

