void check(int x, int y) {
  val[x][y] -= 1;
  if (x > 0) {
    val[x - 1][y] -= 1;
    if (val[x - 1][y] == 1) {
      Q.push(make_pair(x - 1, y));
    }
  }
  if (y > 0) {
    val[x][y - 1] -= 1;
    if (val[x][y - 1] == 1) {
      Q.push(make_pair(x, y - 1));
    }
  }
  if (x > 0 && y > 0) {
    val[x - 1][y - 1] -= 1;
    if (val[x - 1][y - 1] == 1) {
      Q.push(make_pair(x - 1, y - 1));
    }
  }
}

