bool check(int a, int b, int c, int d, pair<int, int>& p)
{
    /* ab */
    /* cd */

    vector<int> v = {a, b, c, d};
    int cnt = count(v.begin(), v.end(), -1);
    if(cnt == 0){
        p.first = -1;
        return a + d == b + c;
    }
    else if(cnt == 1){
        if(a == -1){
            p.first = 0;
            p.second = b + c - d;
        }
        else if(b == -1){
            p.first = 1;
            p.second = a + d - c;
        }
        else if(c == -1){
