const int INF = 1e9+7;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int R, C;
    cin >> R >> C;
    int N;
    cin >> N;
    map<pii, int> mp;
    for (int i = 0; i < N; i++) {
        cin >> r[i] >> c[i] >> a[i];
        r[i]--; c[i]--;
        c2r[c[i]].insert(pii(r[i], i));
        r2c[r[i]].insert(pii(c[i], i));
        mp[pii(r[i], c[i])] = a[i];
    }
    for (int i = 0; i < C-2; i++) {
        int cnt = -INF;
        for (auto p : c2r[i]) {
            int r = p.first;
            int ri = p.second;
            auto q = c2r[i+2].lower_bound(pii(r, -1));
            if (q == c2r[i+2].end() || q->first != r) continue;
            int qi = q->second;
            int tmp = a[ri] - a[qi];
            if (cnt != -INF && cnt != tmp) {
                no();
            }
            cnt = tmp;
        }
    }
    for (int i = 0; i < R-2; i++) {
        int cnt = -INF;
        for (auto p : r2c[i]) {
            int c = p.first;
            int ci = p.second;
            auto q = r2c[i+2].lower_bound(pii(c, -1));
            if (q == r2c[i+2].end() || q->first != c) continue;
            int qi = q->second;
            int tmp = a[ci] - a[qi];
            if (cnt != -INF && cnt != tmp) {
                no();
            }
            cnt = tmp;
        }
    }
    for (auto p : mp) {
        int y = p.first.first, x = p.first.second;
        if (y + 1 >= R || x + 1 >= C) continue;
        int cnt = 0;
        vi A(4, -1);
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                int ny = y+i, nx = x+j;
                auto it = mp.find(pii(ny, nx));
                if (it == mp.end()) cnt++;
                else A[2*i+j] = it->second;
            }
        }
        if (cnt == 1) {
            if (A[0] == -1) {
                if (A[1]+A[2]-A[3] < 0) no();
            }
            if (A[1] == -1) {
                if (A[0]+A[3]-A[2] < 0) no();
            }
            if (A[2] == -1) {
                if (A[0]+A[3]-A[1] < 0) no();
            }
            if (A[3] == -1) {
                if (A[1]+A[2]-A[0] < 0) no();
            }
        }
        if (cnt == 0) {
            if (A[0] + A[3] != A[1] + A[2]) {
                cout << "No" << endl;
                return 0;
            }
        }
    }
    cout << "Yes" << endl;
    return 0;
}

