typedef long long ll;

constexpr ll INF = 1e15;

vector<pair<int,int>> e[200000];
ll cost[200000];
bool used[200000];
int R;
ll minr, minc;

bool dfs(int v, ll c) {
    if (v < R) minr = min(minr,c);
    else minc = min(minc,c);
    used[v] = true;
    cost[v] = c;
    bool ret = true;
    for (auto p: e[v]) {
        if (!used[p.first])
            ret &= dfs(p.first,p.second - c);
        else if (cost[p.first] != p.second - c)
            ret = false;
    }
    ret &= minr + minc >= 0;
    return ret;
}

int main() {
    int i, C, N;
    scanf("%d%d%d",&R,&C,&N);
    REP (i,N) {
        int r, c, a;
        scanf("%d%d%d",&r,&c,&a);
        r--; c--;
        e[r].emplace_back(c+R,a);
        e[c+R].emplace_back(r,a);
    }
    REP (i,R+C) cost[i] = INF;
    REP (i,R+C) if (!used[i]) {
        minr = minc = INF;
        if (!dfs(i,0)) {
            puts("No");
            return 0;
        }
    }
    puts("Yes");
    return 0;
}

