    roots[uf.root(i)] = INF;
  }
  for (auto p = roots.begin(); p != roots.end(); ++p) {
    int x = p->first;
    p->second = x;
    for (; x != -1; x = uf.get_next(x)) {
      if (offset[p->second] > offset[x]) {
        p->second = x;
      }
    }
  }

