		if (dp[r] == X) {
			dp[r] = dp[l] + d;
		}
		if (dp[r] != dp[l] + d) ok = false;
	}

	map<int, int> min_id;
	FOR(i, ten(5) + 1) {
		if (dp[i] == X) continue;
		int id = uf.find(i);
		if (min_id.find(id) == min_id.end()) min_id[id] = i;
		int& m = min_id[id];
		if (dp[m] > dp[i]) m = i;
	}

	for (auto& v : mp) {
		auto& y = v.second;
		const int mid = min_id[uf.find(y[0].first)];
		int diff = dp[y[0].first] - dp[mid];
		const int minval = y[0].second - diff;
		if (minval < 0)
			ok = false;
	}

	puts(ok ? "Yes" : "No");

	return 0;
}

