using namespace std;
struct edge { int to, sum; };
int R, C, N, lv, x, y, val; long long v[200009]; bool vis[200009], vis2[200009]; vector<edge> g[200009]; vector<int> vs;
void dfs1(int pos) {
	vis[pos] = true;
	vs.push_back(pos);
	for (edge e : g[pos]) {
		if (!vis[e.to]) dfs1(e.to);
	}
}
bool dfs2(int pos) {
	vis2[pos] = true;
	for (edge e : g[pos]) {
		if (v[e.to] != -(1LL << 60) && v[e.to] + v[pos] != e.sum * 2 - (lv != -1 ? lv : 0)) return false;
		v[e.to] = e.sum * 2 - v[pos] - (lv != -1 ? lv : 0);
		if (!vis2[e.to] && !dfs2(e.to)) return false;
	}
	return true;
}
int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);
	cin >> R >> C >> N; lv = -1;
	fill(v, v + R + C - 2, -(1LL << 60));
	for (int i = 0; i < N; i++) {
		cin >> x >> y >> val; x--, y--;
		if (x == 0 && y == 0) lv = val;
		else if (y == 0) v[x - 1] = val * 2;
		else if (x == 0) v[R + y - 2] = val * 2;
		else {
			g[x - 1].push_back(edge{ R + y - 2, val });
			g[R + y - 2].push_back(edge{ x - 1, val });
		}
	}
	bool ok = true;
	for (int i = 0; i < R + C - 2; i++) {
		if (vis[i]) continue;
		vs.clear();
		dfs1(i);
		int start = i;
		for (int j : vs) {
			if (v[j] != -1) start = j;
		}
		bool change = (v[start] == -1);
		if (v[start] == -(1LL << 60)) v[start] = 0;
		bool res = dfs2(start);
		if (!res) ok = false;
		long long lm = 1LL << 60, rm = 1LL << 60;
		for (int j : vs) {
			if (j < R - 1) lm = min(lm, v[j]);
			else rm = min(rm, v[j]);
		}
		if (change) {
			for (int j : vs) {
				if (j < R - 1) v[j] += (rm - lm) / 2;
				else v[j] -= (rm - lm) / 2;
			}
		}
		for(int j : vs) {
			if (v[j] < 0) ok = false;
		}
	}
	if (lv != -1 && *min_element(v, v + R - 1) + *min_element(v + R - 1, v + R + C - 2) - 2 * lv < 0) ok = false;
	cout << (ok ? "Yes" : "No") << endl;
	return 0;
}

