ll mix,miy;

void dfs(int cur) {
	if(XX[cur]!=-1LL<<60 && YY[cur]!=-1LL<<60) {
		if(XX[cur]+YY[cur]!=A[cur]) {
			cout<<"No"<<endl;
			exit(0);
		}
		return;
	}
	if(XX[cur]==-1LL<<60) {
		XX[cur]=YY[cur]-A[cur];
		mix=min(XX[cur],mix);
		FORR(e,LR[cur]) {
			XX[X[e]] = XX[cur] + (A[e] - A[cur]);
			dfs(e);
		}
	}
	if(YY[cur]==-1LL<<60) {
		YY[cur]=XX[cur]-A[cur];
		miy=min(YY[cur],miy);
		FORR(e,UD[cur]) {
			YY[Y[e]] = YY[cur] + (A[e] - A[cur]);
			dfs(e);
		}
	}
	if(XX[cur]+YY[cur]!=A[cur]) {
