	vector<pii> p(n);

	REP(i, n) {
		int ia, ib, ic;
		scanf("%d %d %d", &ia, &ib, &ic);
		p[i] = pii(ia, ib);
		a[i] = ic;
	}

	// 座標圧縮
	vector<int> xs, ys;

	REP(i, n) {
		xs.push_back(p[i].first);
		ys.push_back(p[i].second);
	}

	sort(xs.begin(), xs.end());
	xs.erase(unique(xs.begin(), xs.end()), xs.end());

	sort(ys.begin(), ys.end());
	ys.erase(unique(ys.begin(), ys.end()), ys.end());

	REP(i, n) {
		p[i].first = find(xs.begin(), xs.end(), p[i].first) - xs.begin();
		p[i].second = find(ys.begin(), ys.end(), p[i].second) - ys.begin();
	}
	//


	REP(i, n) REP(j, n) if (i != j) {
		if (p[i].first == p[j].first || p[i].second == p[j].second) continue;

		// 座標復元
		int nx[2] = {*(p[i].first + xs.begin()), *(p[j].first + xs.begin())};
		int ny[2] = {*(p[i].second + ys.begin()), *(p[j].second + ys.begin())};

		int p1x = nx[0], p1y = ny[1];
		int p2x = nx[1], p2y = ny[0];

		if (!check(p1x, p1y) || !check(p2x, p2y)) continue;

		//printf("%d %d : %d %d : %d %d : %d %d\n", nx[0], ny[0], nx[1], ny[1], p1x, p1y, p2x, p2y);

		pii inf = pii(INF, INF);
		pii np1 = inf, np2 = inf;

		if (!(find(xs.begin(), xs.end(), p1x) == xs.end()) && !(find(ys.begin(), ys.end(), p1y) == ys.end())) {
			np1 = pii(find(xs.begin(), xs.end(), p1x) - xs.begin(), find(ys.begin(), ys.end(), p1y) - ys.begin());
		}
		if (!(find(xs.begin(), xs.end(), p2x) == xs.end()) && !(find(ys.begin(), ys.end(), p2y) == ys.end())) {
			np2 = pii(find(xs.begin(), xs.end(), p2x) - xs.begin(), find(ys.begin(), ys.end(), p2y) - ys.begin());
		}


		int na = 0;
		bool ok = true;

		if (np1 == inf && np2 == inf) continue;
		else if (np1 == inf || np2 == inf) {
			if (np1 == inf) na += a[find(p.begin(), p.end(), np2) - p.begin()];
			else na += a[find(p.begin(), p.end(), np1) - p.begin()];

			if (a[i] + a[j] - na < 0) ok = false;

		}
		else {
			na += a[find(p.begin(), p.end(), np1) - p.begin()];
			na += a[find(p.begin(), p.end(), np2) - p.begin()];
			if (a[i] + a[j] != na) ok = false;
		}


		if (!ok) {
			puts("No");
			return 0;
		}
	}
	puts("Yes");
	return 0;
}

