//init O(nlogn),zip O(n),unzip O(1)
int compress(vector<int> &x,map<int,int> &zip,vector<int> &unzip) {
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(),x.end()),x.end());
    for(int i=0; i<x.size(); ++i){
        zip[x[i]]=i;
        unzip.push_back(x[i]);
    }
    return x.size();
}

