void dfs(int i, ll val) {
	vis[i] = 1;
	ret[i] = val;
	last.push_back(i);
	for (pii p : adj[i]) {
		if (!vis[p.first]) {
			dfs(p.first, val + p.second);
		}
		else if (ret[p.first] != val + p.second) {
			failed = 1;
			break;
		}
	}
}

vector<ll> calc(int D) {
	sort(v, v + n);
	F0(i, n) adj[i].clear();
	F0(i, n - 1) if (v[i].first.first == v[i + 1].first.first) {
		add(v[i].first.second, v[i + 1].first.second, v[i + 1].second - v[i].second);
	}
	CL(0, vis);
	ret.resize(D);
	F0(i, D) if (!vis[i]) {
		last.clear();
		dfs(i, 0);
		ll mv = ret[last[0]];
		for (int x : last) mv = min(mv, ret[x]);
		for (int x : last) ret[x] -= mv;
	}
	//F0(i, D) cout << ret[i] << " "; cout << endl;
	return ret;
}

