using namespace std;

typedef long long LL;
typedef pair<int, int> PII;

int r, c;
int n;
vector<PII> G[200005];
bool vis[200005];
int w[200005];

PII dfs(int v, int h) {
  if (vis[v]) {
    if (w[v] != h) {
      printf("NO\n");
      exit(0);
    }
    return PII(INT_MAX / 2 - 1, INT_MAX / 2 - 1);
  }
  vis[v] = true;
  w[v] = h;
  int w1 = h, w2 = INT_MAX / 2 - 1;
  for (int i = 0; i < G[v].size(); i += 1) {
    PII nxt = G[v][i];
    PII tmp = dfs(nxt.first, nxt.second - h);
    w1 = min(w1, tmp.second);
    w2 = min(w2, tmp.first);
  }
  return PII(w1, w2);
}

int main() {
  scanf("%d %d", &r, &c);
  scanf("%d", &n);
  for(int i = 0; i < n; i += 1) {
    int x, y, a;
    scanf("%d %d %d", &x, &y, &a);
    x -= 1; y -= 1;
    G[x].push_back(PII(r + y, a));
    G[r + y].push_back(PII(x, a));
  }
  for(int i = 0; i < r + c; i += 1) {
    vis[i] = false;
  }
  for(int i = 0; i < r + c; i += 1) {
    if (!vis[i]) {
      PII res = dfs(i, 0);
      if (res.first + res.second < 0) {
        printf("NO\n");
        return 0;
      }
    }
  }
  printf("YES\n");
  return 0;
}

