void rdfs(int id, long long val, int from) {
  if(from < 0) {
    if(rc[id]) return;
    rc[id] = true;
    rw[id] = val;
  } else {
    if(rc[id]) {
      if(rw[id] != val) {
        b = true;
      }
      return;
    } else {
      rc[id] = true;
      rw[id] = val;
    }
  }
  for(int i = 0; i < rp[id].size(); i++) {
    if(from == rp[id][i].first) continue;
    cdfs(rp[id][i].first, rp[id][i].second - val, id);
  }
}

void cdfs(int id, long long val, int from) {
  if(from < 0) {
    if(cc[id]) return;
    cc[id] = true;
    cw[id] = val;
  } else {
    if(cc[id]) {
      if(cw[id] != val) {
        b = true;
      }
      return;
    } else {
      cc[id] = true;
      cw[id] = val;
    }
  }
  for(int i = 0; i < cp[id].size(); i++) {
    if(from == cp[id][i].first) continue;
    rdfs(cp[id][i].first, cp[id][i].second - val, id);
  }
}

