using ll = long long;
using vi = vector<ll>;
using pii = pair<ll, ll>;

vi diff;
vector<vector<pii>> col;
vector<ll> con;

bool dfs(ll cc, ll i, ll v)
{
    con[i] = cc;
    diff[i] = v;

    bool ret = true;
    for(pii& p : col[i]){
        ll tmp = v + p.second;
        if(con[p.first] != -1){
            ret &= tmp == diff[p.first];
        }
        else{
            dfs(cc, p.first, tmp);
        }
    }

    return ret;
}

bool check(ll R, ll C, vector<vector<pii>>& a)
{
    col.clear();
    col.resize(C);
    rep(i, R){
        rep(j, a[i].size() - 1){
            col[a[i][j].first].emplace_back(a[i][j+1].first, a[i][j+1].second - a[i][j].second);
            col[a[i][j+1].first].emplace_back(a[i][j].first, a[i][j].second - a[i][j+1].second);
        }
    }

    diff.assign(C, 0);
    con.assign(C, -1);
    ll num_con = 0;

    rep(i, C){
        if(con[i] != -1) continue;
        if(!dfs(num_con, i, 0)){
            return false;
        }
        ++num_con;
    }

    vi m(num_con);
    rep(i, C){
        m[con[i]] = min(m[con[i]], diff[i]);
    }

    vi real(C);
    rep(i, R){
        ll mm = 0;
        for(pii& p : a[i]){
            mm = min(mm, m[con[p.first]]);
        }

        for(pii& p : a[i]){
            ll tmp = p.second - diff[p.first] + mm;
            if(tmp < 0){
                return false;
            }
        }
    }

    return true;
}

int main()
{
    ll R, C, n;
    cin >> R >> C >> n;

    vector<vector<pii>> a(R);
    rep(i, n){
        ll r, c, v;
        cin >> r >> c >> v;
        --r;
        --c;
        a[r].emplace_back(c, v);
    }

    bool x = check(R, C, a);

    vector<vector<pii>> b(C);
    rep(i, R) for(pii& p : a[i]){
        b[p.first].emplace_back(i, p.second);
    }

    bool y = check(C, R, b);

    cout << (x && y ? "Yes" : "No") << endl;
}

#include<bits/stdc++.h>
using namespace std;
#define MAX 100005
typedef pair<int,int> P;
int R,C;
int N;
map< P , int > mp;
map< P , bool > used;

int r[MAX],c[MAX],a[MAX];
queue<P> Q;

bool check(int x,int y){
  int cnt=4;
  int total=0;
  bool fa=false,fb=false,fc=false,fd=false;

  if( mp.count(P(x,y)) >0)cnt--,fa=true,total+=mp[ P(x,y) ];
  if( mp.count(P(x+1,y)) >0)cnt--,fb=true,total+=mp[ P(x+1,y) ];
  if( mp.count(P(x,y+1)) >0)cnt--,fc=true,total+=mp[ P(x,y+1) ];
  if( mp.count(P(x+1,y+1)) >0)cnt--,fd=true,total+=mp[ P(x+1,y+1) ];

  if(cnt==0){
    if( mp[P(x,y)]+mp[P(x+1,y+1)] == mp[P(x,y+1)]+mp[P(x+1,y)])return true;
    else return false;
  }

  if(cnt==1){
    if(fa==false){
      mp[ P(x,y) ]=total-mp[P(x+1,y+1)]*2;
      Q.push(P(x,y));

    }
    if(fb==false){
      mp[ P(x+1,y) ]=total-mp[P(x,y+1)]*2;
      Q.push(P(x+1,y));

    }
    if(fc==false){
      mp[ P(x,y+1) ]=total-mp[P(x+1,y)]*2;
      Q.push(P(x,y+1));

    }
    if(fd==false){
      mp[ P(x+1,y+1) ]=total-mp[P(x,y)]*2;
      Q.push(P(x+1,y+1));

    }

  }

  if(cnt==2){
    if(total==0 && fa==true && fd==true){
      mp[ P(x,y+1) ]=0;
      Q.push(P(x,y+1));
      mp[ P(x+1,y) ]=0;
      Q.push(P(x+1,y));

    }else if(total==0 && fb==true && fc==true ){
      mp[ P(x,y) ]=0;
      Q.push(P(x,y));
      mp[ P(x+1,y+1) ]=0;
      Q.push(P(x+1,y+1)); 
    }

  }
  return true;
}


bool solve(){
  while(!Q.empty()){
    P p=Q.front();Q.pop();
    int px=p.first;
    int py=p.second;

    if( mp[P(px,py)] < 0 )return false;

    for(int dx=-1;dx<=0;dx++){
      for(int dy=-1;dy<=0;dy++){

        if(px+dx<0 || py+dy<0)continue;
        if(R<=px+dx+1 || C<=py+dy+1)continue;

        if( check(px,py) == false )return false;

      }
    }
  }
  return true;
}

int main(){
  scanf("%d %d %d",&R,&C,&N);
  for(int i=0;i<N;i++){
    scanf("%d %d %d",&r[i],&c[i],&a[i]);
    r[i]--,c[i]--;

    mp[ P(r[i],c[i]) ]=a[i];
    Q.push( P(r[i],c[i]) );
  }

  cout<< ( solve()? "Yes":"No") <<endl;
  return 0;
}

