struct Node {
  int x, y;
  int64 v;
};

bool operator <(const Node& a, const Node& b) {
  return (a.x < b.x) || (a.x == b.x && a.y < b.y);
}

const int N = 1e5 + 10;
Node a[N];

const int64 INF64 = 1LL << 60;
int main() {
  int R, C, n;
  scanf("%d%d%d", &R, &C, &n);
  for (int i = 0; i < n; ++i) {
    scanf("%d%d%lld", &a[i].x, &a[i].y, &a[i].v);
    --a[i].x; --a[i].y;
  }
  sort(a, a + n);
  vector<int64> delta(R);
  vector<int64> visit(C, -INF64);
  for (int i = 0, j; i < n; i = j) {
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      if (visit[a[j].y] != -INF64) {
        delta[a[j].x] = a[j].v - visit[a[j].y];
        break;
      }
    }
    for (j = i; j < n && a[j].x == a[i].x; ++j) {
      a[j].v -= delta[a[j].x];
      if (visit[a[j].y] == -INF64) {
        visit[a[j].y] = a[j].v;
      } else if (visit[a[j].y] != a[j].v) {
        puts("No");
        return 0;
      }
    }
  }
  int64 minv = INF64, maxv = -INF64;
  for (int i = 0; i < C; ++i) {
    if (visit[i] != -INF64) {
      minv = min(minv, visit[i]);
      maxv = max(maxv, visit[i]);
    }
  }
  for (int i = 0; i < R; ++i) {
    if (minv + delta[i] < 0) {
      puts("No");
      return 0;
    }
  }
  puts("Yes");
  return 0;
}

