bool check(int R, int C, vector<int> r, vector<int> c, vector<int> a) {
	map<int, vector<pair<int, int>>> mapp;
	vector<vector<pair<int, int>>> g(C + 1);
	int n = (int)r.size();
	for (int i = 0; i < n; i++) {
		mapp[r[i]].push_back({c[i], a[i]});
	}
	for (const auto & it : mapp) {
		const auto & vec = it.second;
		for (int i = 0; i + 1 < (int)vec.size(); i++) {
			int from = vec[i].first;
			int to = vec[i + 1].first;
			int fromVal = vec[i].second;
			int toVal = vec[i + 1].second;
			g[from].push_back({to, toVal - fromVal});
			g[to].push_back({from, fromVal - toVal});
		}
	}
	vector<ll> values(C + 1);
	vector<int> used(C + 1);
	int colorCnt;
	bool ok = true;
	function<void(int, ll)> dfs;
	dfs = [&](int v, ll c) {
		if (used[v]) {
			if (values[v] != c) {
				ok = false;
			}
			return;
		}
		used[v] = colorCnt;
		values[v] = c;
		for (auto p : g[v]) {
			int to = p.first;
			int cst = p.second;
			dfs(to, c + cst);
		}
	};
	for (int i = 1; i <= C; i++) {
		if (used[i] == 0) {
			colorCnt++;
			dfs(i, 0);
		}
	}
	vector<vector<int>> idxs(colorCnt + 1);
	vector<vector<int>> vertices(colorCnt + 1);
	for (int i = 0; i < n; i++) {
		idxs[used[c[i]]].push_back(i);
	}
	for (int i = 1; i <= C; i++) {
		vertices[used[i]].push_back(i);
	}
	for (int color = 1; color <= colorCnt; color++) {
		int pos = -1;
		for (int i : vertices[color]) {
			if (pos == -1 || values[i] < values[pos]) {
				pos = i;
			}
		}
		for (int i : idxs[color]) {
			ll cur = a[i];
			int curVertex = c[i];
			ll z = cur + (values[pos] - values[curVertex]);
			if (z < 0) {
				ok = false;
			}
		}
	}
	return ok;
}

