const ll inf= 5e15;

bool dfs(ll idx, const vvec<tll> &cons, vec<bool> &used, vec<ll> &vals, std::set<ll> &def) {
    if (used[idx]) return true;
    used[idx] = true;
    bool ret = true;
    for (auto &&e : cons[idx]) {
        ll i1, i2, v1, v2;
        i1 = idx;
        std::tie(i2, v1, v2) = e;
        if (vals[i1] != inf && vals[i2] != inf) {
            ll d1 = vals[i1] - vals[i2];
            ll d2 = v1 - v2;
            if (d1 != d2) return false;
        } else if (vals[i1] != inf) {
            vals[i2] = vals[i1] - v1 + v2;
            def.insert(i2);
        } else if (vals[i2] != inf) {
            vals[i1] = vals[i2] - v2 + v1;
            def.insert(i1);
        } else {
            vals[i1] = v1;
            vals[i2] = v2;
            def.insert(i1);
            def.insert(i2);
        }
        ret &= dfs(i2, cons, used, vals, def);
    }

    return ret;
}

bool check(const vvec<pll> &lines, ll w) {
    vvec<tll> cons(1e5 + 10);
    vec<ll> minv(w, inf);
    for (auto &&line : lines) {
        for (pll p : line) {
            ll c, a;
            std::tie(c, a) = p;
            chmin(minv[c], a);
        }
        if (line.size() < 2) continue;
        for (ll i = (ll)(line.size()) - 2; 0 <= i; i--) {
            ll i1, i2, v1, v2;
            std::tie(i1, v1) = line[i];
            std::tie(i2, v2) = line[i + 1];
            cons[i1].emplace_back(i2, v1, v2);
            cons[i2].emplace_back(i1, v2, v1);
        }
    }

    vec<ll> vals(w, inf);
    vec<bool> used(cons.size(), false);

    for (ll i = 0; i < cons.size(); i++) {
        if (used[i]) continue;
        std::set<ll> def;
        if (!dfs(i, cons, used, vals, def)) return false;
        ll dec = 0;
        for (ll e : def) chmax(dec, vals[e] - minv[e]);
        for (ll e : def) {
            vals[e] -= dec;
            if (vals[e] < 0) return false;
        }
    }

    return true;
}

