bool traverse(int i,int x,int y,int a,int dx,int dy){
  auto itx = xAxis.find(x), ity = yAxis.find(y);
  if(itx==xAxis.end())xAxis[x] = dx;
  else if(itx->second!=dx)return false;
  if(ity==yAxis.end())yAxis[y] = dy;
  else if(ity->second!=dy)return false;
  if(used[i])return true;
  used[i] = 1;
  for(const int &p : xis[x]){
    if(p!=i){
      int a2 = v[p].second;
      bool r = traverse(p,v[p].first.first,v[p].first.second,a2,dx,dy+a2-a);
      if(!r)return false;
    }
  }
  for(const int &p : yis[y]){
    if(p!=i){
      int a2 = v[p].second;
      bool r = traverse(p,v[p].first.first,v[p].first.second,a2,dx+a2-a,dy);
      if(!r)return false;
    }
  }
  return true;
}

