bool DFSUtil(int, vector<bool>);

int main(){
  int R, C;
  cin >> R >> C;
  int N;
  cin >> N;
  vector<int, pair<int, int>> g;

  for(int i = 0; i < N; i++){
    int r, c, a;
    cin >> r >> c >> a;
    g[r].push_back(make_pair( c + C, a);
    g[c + C].push_back(make_pair(r, a));
  }

  vector<bool> visited(R + C, false);
  vector<int> node(R + C, 0);
  int minR, minC = pow(10,9);
  if(!DFSUtil(0, visited)){
    cout << "No";
  }
  else{
    cout >> "Yes";
  }
}

bool DFSUtil(int v, vector<bool> visited){
  visited[v] = true;
  for(int i = 0; i < g[v].size(); i++){
    int w = g[v][i]. first;
    int a = g[v][i].second;
    if(visited[w] && node[v] + node[w] != a){
      return false;
    }
    node[w] = a - node[v];

    if(v < R) minR = minR >node[v] ? node[v] : minR;
    if(v >= R) minC = minC>node[v] ? node[v] : minC;
    if(minR + minC < 0) return false;
    if(!visited[w]){
      if(!DFSUtil(w, visited)) return false;
    }
  }
  return true;
}

#include <iostream>
#include <map>
using namespace std;

int R, C, N;
int r[100000], c[100000], a[100000];
map<int, int> field;
map<int, bool> filled;

const int dx[] = {1, 1, -1, -1};
const int dy[] = {1, -1, 1, -1};

bool isIllegal(int ri, int ci) {
    int ai = field[C*ri+ci];

    for (int j = 0; j < 4; j++) {
        int y = ri + dy[j];
        int x = ci + dx[j];
        if (x < 0 || C <= x || y < 0 || R <= y) continue;

        int cnt = 1 + filled[C*ri+x] + filled[C*y+ci] + filled[C*y+x];
        if (cnt <= 2) continue;
        if (cnt == 4) {
            if (ai + field[C*y+x] != field[C*ri+x] + field[C*y+ci]) {
                return true;
            }
        } else if (!filled[C*ri+x]) {
            int temp = ai + field[C*y+x] - field[C*y+ci];
            field[C*ri+x] = temp;
            filled[C*ri+x] = true;
            if (temp < 0) return true;
            return isIllegal(ri, x);
        } else if (!filled[C*y+ci]) {
            int temp = ai + field[C*y+x] - field[C*ri+x];
            field[C*y+ci] = temp;
            filled[C*y+ci] = true;
            if (temp < 0) return true;
            return isIllegal(y, ci);
        } else if (!filled[C*y+x]) {
            int temp = field[C*ri+x] + field[C*y+ci] - ai;
            field[C*y+x] = temp;
            filled[C*y+x] = true;
            if (temp < 0) return true;
            return isIllegal(y, x);
        }
    }
    return false;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> R >> C >> N;
    for (int i = 0; i < N; i++) {
        cin >> r[i] >> c[i] >> a[i];
        r[i]--;
        c[i]--;
        field[C*r[i] + c[i]] = a[i];
        filled[C*r[i] + c[i]] = true;
    }

    for (int i = 0; i < N; i++) {
        if (isIllegal(r[i], c[i])) {
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;

    return 0;
}

