		if(rx==ry){
			return (d[x]-d[y]==z);
		}
		d[ry]=d[x]-d[y]-z;
		par[ry]=rx;
		return 1;
	}
	ll diff(int x,int y){		//w[x]-w[y]=?
		find(x),find(y);			//いる!!
		return d[x]-d[y];
	}
	bool same(int x,int y) { return find(x)==find(y); }
}UH,UW;
