ll as[MN];
vector<P> rows[MN],cols[MN];
ll mnH[MN],mnW[MN];
ll inf=1e18;
bool solve(){
	cin>>H>>W>>N;
	UH.init(H);
	UW.init(W);
	rep(i,N){
		int r,c,a;
		scanf("%d%d%d",&r,&c,&a);
		r--,c--;
		rs[i]=r,cs[i]=c,as[i]=a;
		rows[r].pb(P(c,a));
