	}
	rep(i,H){
		int K=rows[i].size();
		rep(j,K-1){
			P p=rows[i][j],q=rows[i][j+1];
			int a=p.fs,b=q.fs;
			ll dif=p.sc-q.sc;
			if(!UW.unite(a,b,dif)) return 0;
		}
	}
	rep(i,W){
		int K=cols[i].size();
		rep(j,K-1){
			P p=cols[i][j],q=cols[i][j+1];
