			ll dif=p.sc-q.sc;
			if(!UH.unite(a,b,dif)) return 0;
		}
	}
	rep(i,H) mnH[i]=inf;
	rep(i,W) mnW[i]=inf;
	rep(i,H){
		int r=UH.find(i);
		chmin(mnH[r],UH.diff(i,r));
	}
	rep(i,W){
