void dfs(node nd){
    ll r = nd.r, c = nd.c, n = nd.n;
//    cout << r << "," << c << "," << n << endl;
//    cout << row[r] << "," << col[c] << endl;
    if(M[nd.r * mod + nd.c]) return;
    M[nd.r * mod + nd.c] = 1;
    if(row[r] == inf && col[c] == inf){
        row[r] = n, col[c] = 0;
    }
    else if(row[r] == inf){
        row[r] = n - col[c];
    }
    else if(col[c] == inf){
        col[c] = n - row[r];
    }
    else return;
    for(node nr: GR[r]){
        dfs(nr);
    }
    for(node nc: GC[c]){
        dfs(nc);
    }

}


