using namespace std;
#define FOR(i,j,k) for(int (i)=(j);(i)<(int)(k);++(i))
#define rep(i,j) FOR(i,0,j)
#define each(x,y) for(auto &(x):(y))
#define mp make_pair
#define MT make_tuple
#define all(x) (x).begin(),(x).end()
#define debug(x) cout<<#x<<": "<<(x)<<endl
#define smax(x,y) (x)=max((x),(y))
#define smin(x,y) (x)=min((x),(y))
#define MEM(x,y) memset((x),(y),sizeof (x))
#define sz(x) (int)(x).size()
#define RT return
#define vv(a,b,c,d) vector<vector<a> >(b,vector<a>(c,d))
#define vvv(a,b,c,d,e) vector<vector<vector<a> > >(b,vv(a,c,d,e))
using ll = long long;
using pii = pair<int, int>;
using vi = vector<int>;
using vll = vector<ll>;

int R, C, N;
vi G[200005];
int U[100005], V[100005], A[100005];
int vis[200005];
ll MI = LLONG_MIN / 3;
ll MA = LLONG_MAX / 3;
ll X[200005], rmi, cmi;

void dfs(int u) {
    if (vis[u]++)RT;
    if (u < R)smin(rmi, X[u]);
    else smin(cmi, X[u]);
    each(e, G[u]) {
        int v = U[e] ^ V[e] ^ u;
        int a = A[e];
        if (!vis[v]) {
            X[v] = a - X[u];
            dfs(v);
        } else {
            if (a != X[u] + X[v]) {
                rmi = cmi = MI;
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    cin >> R >> C >> N;

    rep(i, N) {
        cin >> U[i] >> V[i] >> A[i];
        --U[i];
        V[i] = (V[i] - 1) + R;
        G[U[i]].push_back(i);
        G[V[i]].push_back(i);
    }

    rep(i, R) if(!vis[i]){
        rmi = 0;
        cmi = MA;
        dfs(i);
        if (rmi + cmi < 0) {
            cout << "No" << endl;
            return 0;
        }
    }

    cout << "Yes" << endl;
}

#include <bits/stdc++.h>

#define REP(i,n) for(int i=0; i<(int)(n); ++i)
#define FOR(i,k,n) for(int i=(k);i<(int)(n);++i)

using namespace std;


int R, C, N;
int wr[100001], wc[100001];

struct E{
    int to, cost;
    E(int t, int c): to(t), cost(c) {};
};
vector<E> edge_r[100001], edge_c[100001];

bool dfs(int v) {
    bool flag = true;
    if(v < R) {
        REP(i, edge_r[v].size()) {
            E e = edge_r[v][i];
            if(wc[e.to] != -1) {
                if(wr[v]+wc[e.to]!=e.cost) {
                    flag = false;
                    break;
                }
            } else {
                wc[e.to] = e.cost - wr[v];
                flag = dfs(e.to+R);
            }
        }
    }
    else {
        v -= R;
        REP(i, edge_c[v].size()) {
            E e = edge_c[v][i];
            if(wr[e.to] != -1) {
                if(wc[v]+wr[e.to]!=e.cost) flag = false;
            } else {
                wr[e.to] = e.cost - wc[v];
                flag = dfs(e.to);
            }
        }
    }
    return flag;
}


int main(void) {
    int tr, tc, ta;
    cin >> R >> C >> N;

    REP(i, R) wr[i] = -1;
    REP(i, C) wc[i] = -1;

    REP(i, N) {
        cin >> tr >> tc >> ta;
        tr--; tc--;
        edge_r[tr].push_back(E(tc, ta));
        edge_c[tc].push_back(E(tr, ta));
    }

    REP(i, R) {
        if(wr[i] != -1) continue;
        if(edge_r[i].size() > 0) wr[i] = 0;
        if(!dfs(i)) {
            cout << "No" << endl;
            return 0;
        }
    }
    int min_r = numeric_limits<int>::max();
    int min_c = numeric_limits<int>::max();
    REP(i, R) {
        if(wr[i] != -1) min_r = min(min_r, wr[i]);
    }
    REP(i, C) {
        if(wc[i] != -1) min_c = min(min_c, wc[i]);
    }
    if(min_r+min_c >= 0) cout << "Yes" << endl;
    else cout << "No" << endl;
}

