 if (cy > 1 && cx+1 <= c) {
  bool flag = d[cy].count(cx+1) &&
     d[cy-1].count(cx+1) &&
     d[cy].count(cx+1);

  if (!flag) return 0;

  return d[cy-1][cx+1] + d[cy][cx] == d[cy-1][cx] + d[cy][cx+1] ?
   1 : -1;
 }

 return 0; // NONE
}

inline int check1(int cy, int cx) {
 if (cx > 1 && cy > 1) {
  if (!d[cy-1].count(cx) || !d[cy].count(cx-1))
   return 0;
  if (d[cy-1].count(cx-1)) return 0;
