void decide(int i, int j, int a);

void check(int i, int j) {
	if (yeey(i - 1, j - 1) && yeey(i - 1, j) && yeey(i, j - 1))
		decide(i, j, m[mp(i - 1, j)] + m[mp(i, j - 1)] - m[mp(i - 1, j - 1)]);

	if (yeey(i - 1, j) && yeey(i - 1, j + 1) && yeey(i, j + 1))
		decide(i, j, m[mp(i - 1, j)] + m[mp(i, j + 1)] - m[mp(i - 1, j + 1)]);

	if (yeey(i, j - 1) && yeey(i + 1, j - 1) && yeey(i + 1, j))
		decide(i, j, m[mp(i, j - 1)] + m[mp(i + 1, j)] - m[mp(i + 1, j - 1)]);

	if (yeey(i, j + 1) && yeey(i + 1, j) && yeey(i + 1, j + 1))
		decide(i, j, m[mp(i, j + 1)] + m[mp(i + 1, j)] - m[mp(i + 1, j + 1)]);

	if (yeey(i - 1, j - 1) && yeey(i - 1, j + 1) && yeey(i, j - 1) && yeey(i, j + 1))
		if (m[mp(i - 1, j - 1)] - m[mp(i - 1, j + 1)] != m[mp(i, j - 1)] - m[mp(i, j + 1)])
			seeyou();

	if (yeey(i, j - 1) && yeey(i, j + 1) && yeey(i + 1, j - 1) && yeey(i + 1, j + 1))
		if (m[mp(i, j - 1)] - m[mp(i, j + 1)] != m[mp(i + 1, j - 1)] - m[mp(i + 1, j + 1)])
			seeyou();

	if (yeey(i - 1, j - 1) && yeey(i - 1, j) && yeey(i + 1, j - 1) && yeey(i + 1, j))
		if (m[mp(i - 1, j - 1)] - m[mp(i + 1, j - 1)] != m[mp(i - 1, j)] - m[mp(i + 1, j)])
			seeyou();

	if (yeey(i - 1, j) && yeey(i - 1, j + 1) && yeey(i + 1, j) && yeey(i + 1, j + 1))
		if (m[mp(i - 1, j)] - m[mp(i + 1, j)] != m[mp(i - 1, j + 1)] - m[mp(i + 1, j + 1)])
			seeyou();
}

void decide(int i, int j, int a) {
	if (a < 0 || exist(i, j) && m[mp(i, j)] != a)
		seeyou();

	m[mp(i, j)] = a;
	for (int ni = i - 1; ni <= i + 1; ni++)
		for (int nj = j - 1; nj <= j + 1; nj++)
			if (inrange(ni, nj) && !exist(ni, nj))
				check(ni, nj);
}

