			if (c1[u] < min1) min1 = c1[u];
			if (!dfs1(u)) return false;
		}
	}
	return true;
}
bool dfs2 (sll v) {
	check2[v] = true;

	for (sll i = gin2[v]; i < gin2[v + 1]; i++) {
