int idx(int r, int c, int w) {
    return (r * w) + c;
}

int fill(int *grid, int R, int C, int x, int y, int *N) {
    int TL, TR, BL, BR;
    int valid = TRUE;
    int sum = 0;

    // get positions
    TL = grid[idx(x, y, C)];
    TR = grid[idx(x + 1, y, C)];
    BL = grid[idx(x, y + 1, C)];
    BR = grid[idx(x + 1, y + 1, C)];

    if (TL < 0) {
        if (TR >= 0 && BL >= 0) {
            sum = TR + BL;
            if (BR >= 0) {
                if (BR <= sum) {
                    grid[idx(x, y, C)] = sum - BR;
                    *N++;
                } else {
                    valid = FALSE;
                }
            }
        }
    } else if (TR < 0) {
        if (TL >= 0 && BR >= 0) {
            sum = TL + BR;
            if (BL >= 0) {
                if (BL <= sum) {
                    grid[idx(x + 1, y, C)] = sum - BL;
                    *N++;
                } else {
                    valid = FALSE;
                }
            }
        }
    } else if (BL < 0) {
        if (BR >= 0 && TL >= 0) {
            sum = BR + TL;
            if (TR >= 0) {
                if (TR <= sum) {
                    grid[idx(x, y + 1, C)] = sum - TR;
                    *N++;
                } else {
                    valid = FALSE;
                }
            }
        }
    } else if (BR < 0) {
        if (BL >= 0 && TR >= 0) {
            sum = BL + TR;
            if (TL >= 0) {
                if (TL <= sum) {
                    grid[idx(x + 1, y + 1, C)] = sum - TL;
                    *N++;
                } else {
                    valid = FALSE;
                }
            }
        }
    } else {
        if (TL + BR != TR + BL) valid = FALSE;
    }

    return valid;
}

