    scanf("%d", &N);

    int *grid = calloc(R * C, sizeof(int));
    int i;
    for (i = 0; i < R * C; i++) grid[i] = -1;

    int x, y, v;
    for (i = 0; i < N; i++) {
        scanf("%d %d %d", &x, &y, &v);
        grid[idx(x - 1, y - 1, C)] = v;
