		// 子へ移動
		if (liRet < 0) {										// 左側
			lzpNow = lzpNow->mzp1Child[D_TREE_LEFT];
		}
		else {													// 右側
			lzpNow = lzpNow->mzp1Child[D_TREE_RIGHT];
		}
	}

	return NULL;
}

// 木データ - 高さ取得
int
fTreeGetHeight(
	Tree *pzpTree				// <I> 対象の木情報
)
{
	// データ有無
	if (pzpTree == NULL) {
		return 0;
	}

	if (pzpTree->mi1Height[D_TREE_LEFT] >= pzpTree->mi1Height[D_TREE_RIGHT]) {
		return pzpTree->mi1Height[D_TREE_LEFT] + 1;
	}
	else {
		return pzpTree->mi1Height[D_TREE_RIGHT] + 1;
	}
}

// 木データ - 右回転(親は子[左]の右下へ・子[左]は親の左上へ)
int
fTreeRttR(
	Tree **pzppTree				// <I> 回転対象
)
{
	// 現在の子[左]
	Tree *lzpChild = (*pzppTree)->mzp1Child[D_TREE_LEFT];

	// 右回転
	(*pzppTree)->mzp1Child[D_TREE_LEFT] = lzpChild->mzp1Child[D_TREE_RIGHT];	// 親の左側 = 子[左]の右側
	(*pzppTree)->mi1Height[D_TREE_LEFT] = lzpChild->mi1Height[D_TREE_RIGHT];	// 親の高さ(左) = 子[左]の高さ(右)
	lzpChild->mzp1Child[D_TREE_RIGHT] = *pzppTree;								// 子[左]の右側 = 親
	lzpChild->mi1Height[D_TREE_RIGHT] = fTreeGetHeight(*pzppTree);				// 子[左]の高さ(右) - 親の高さ
	*pzppTree = lzpChild;														// 親 = 子[左]

	return 0;
}

// 木データ - 左回転(親は子[右]の左下へ・子[右]は親の右上へ)
int
fTreeRttL(
	Tree **pzppTree				// <I> 回転対象
)
{
	// 現在の子[右]
	Tree *lzpChild = (*pzppTree)->mzp1Child[D_TREE_RIGHT];

	// 左回転
	(*pzppTree)->mzp1Child[D_TREE_RIGHT] = lzpChild->mzp1Child[D_TREE_LEFT];	// 親の右側 = 子[右]の左側
	(*pzppTree)->mi1Height[D_TREE_RIGHT] = lzpChild->mi1Height[D_TREE_LEFT];	// 親の高さ(右) = 子[右]の高さ(左)
	lzpChild->mzp1Child[D_TREE_LEFT] = *pzppTree;								// 子[右]の左側 = 親
	lzpChild->mi1Height[D_TREE_LEFT] = fTreeGetHeight(*pzppTree);				// 子[右]の高さ(左) - 親の高さ
	*pzppTree = lzpChild;														// 親 = 子[右]

	return 0;
}

// 木データ - 追加・削除の共通処理
// 戻り値：[2]高さの変更あり [1]高さの変更なし
int
fTreeComAddDel(
	Tree **pzppNow				// <I> 現在の木情報
	, int piWay					// <I> 対象の方向
)
{
	// 高さの変更があるかチェック
	int liNew = fTreeGetHeight((*pzppNow)->mzp1Child[piWay]);
	if ((*pzppNow)->mi1Height[piWay] == liNew) {												// 変化なし
		return 1;
	}
	(*pzppNow)->mi1Height[piWay] = liNew;														// 更新

	// 高さが離れている場合、回転
	if ((*pzppNow)->mi1Height[D_TREE_LEFT] - (*pzppNow)->mi1Height[D_TREE_RIGHT] > 1) {			// 左側が高い
		fTreeRttR(pzppNow);																			// 右回転
	}
	else if ((*pzppNow)->mi1Height[D_TREE_RIGHT] - (*pzppNow)->mi1Height[D_TREE_LEFT] > 1) {	// 右側が高い
		fTreeRttL(pzppNow);																			// 左回転
	}

	return 2;
}

// 木データ - 追加
// 戻り値：[2]高さの変更あり [1]高さの変更なし [0]データ数の追加のみ
int
fTreeAdd(
	int piTNo					// <I> 木の配列番号 0～
	, Tree **pzppNow			// <I> 現在の木情報
	, int piRow					// <I> 行
	, int piCol					// <I> 列
	, int piVal					// <I> 値
)
{
	// 作成
	if (*pzppNow == NULL) {
		*pzppNow = fTreeMake(piTNo, piRow, piCol, piVal);
		return 1;
	}

	// 比較
	int liRet = fTreeCmp(piTNo, *pzppNow, piRow, piCol);

	// 一致
	if (liRet == 0) {
		return 0;
	}

	// 方向の判別
	int liWay;
	if (liRet < 0) {																	// 左側
		liWay = D_TREE_LEFT;
	}
	else {																				// 右側
		liWay = D_TREE_RIGHT;
	}

	// 下位へ
	liRet = fTreeAdd(piTNo, &((*pzppNow)->mzp1Child[liWay]), piRow, piCol, piVal);
	if (liRet == 0) {																	// 変更なし
		return 0;
	}

	// 追加・削除の共通処理
	return fTreeComAddDel(pzppNow, liWay);
}

// 差 - セット
int
fSetDF(
	int piRC					// <I> 行・列
	, int piPos					// <I> 位置
	, int piDF					// <I> 差
)
{
	if (si2DF[piRC][piPos] == INT_MAX) {		// 新規
		si2DF[piRC][piPos] = piDF;
	}
	else if (si2DF[piRC][piPos] == piDF) {		// 一致
		return 0;
	}
	else {										// 不一致
		return -1;
	}

	return 0;
}

// 隣接マス - チェック
int
fChkMass(
	int piRC					// <I> 行・列
	, int piRow					// <I> 行
	, int piCol					// <I> 列
	, int piVal					// <I> 値
	, int piWay					// <I> 方向
)
{
	int liRet;

	// 隣接マス・差
	int liRow, liCol, liVal, liDF;
	if (piRC == D_TNO_ROW) {
		liRow = piRow + piWay;
		liCol = piCol;
		if (piWay > 0) {
			liDF = si2DF[D_TNO_ROW][piRow];
		}
		else {
			liDF = si2DF[D_TNO_ROW][liRow];
		}
	}
	else {
		liRow = piRow;
		liCol = piCol + piWay;
		if (piWay > 0) {
			liDF = si2DF[D_TNO_COL][piCol];
		}
		else {
			liDF = si2DF[D_TNO_COL][liCol];
		}
	}

	// 隣接マス - 取得
	Tree *lzpTree;
	while (1) {
		lzpTree = fTreeSrh(piRC, liRow, liCol);
		if (lzpTree != NULL) {
			break;
		}

		// 差 - なし
		if (liDF == INT_MAX) {
			return 0;
		}

		// 隣接マス - 追加
		if (piWay > 0) {
			liVal = piVal + liDF;
		}
		else {
			liVal = piVal - liDF;
		}
		liRet = fAddMass(liRow, liCol, liVal);
		if (liRet != 0) {
			return -1;
		}
	}

	// 差 - セット
	if (piRC == D_TNO_ROW) {
		if (piWay > 0) {
			liRet = fSetDF(piRC, piRow, lzpTree->miVal - piVal);
		}
		else {
			liRet = fSetDF(piRC, liRow, piVal - lzpTree->miVal);
		}
	}
	else {
		if (piWay > 0) {
			liRet = fSetDF(piRC, piCol, lzpTree->miVal - piVal);
		}
		else {
			liRet = fSetDF(piRC, liCol, piVal - lzpTree->miVal);
		}
	}
	if (liRet != 0) {
		return -1;
	}

	return 0;
}

// マス - 追加
int
fAddMass(
	int piRow					// <I> 行
	, int piCol					// <I> 列
	, int piVal					// <I> 値
)
{
	int liRet;

	// 値 - チェック
	if (piVal < 0) {
		return -1;
	}

	// マス - 追加
	fTreeAdd(D_TNO_ROW, &(szp1Top[D_TNO_ROW]), piRow, piCol, piVal);
	fTreeAdd(D_TNO_COL, &(szp1Top[D_TNO_COL]), piRow, piCol, piVal);

	// 隣接マス - チェック
	liRet = fChkMass(D_TNO_ROW, piRow, piCol, piVal, 1);
	if (liRet != 0) {
		return -1;
	}
	liRet = fChkMass(D_TNO_ROW, piRow, piCol, piVal, -1);
	if (liRet != 0) {
		return -1;
	}
	liRet = fChkMass(D_TNO_COL, piRow, piCol, piVal, 1);
	if (liRet != 0) {
		return -1;
	}
	liRet = fChkMass(D_TNO_COL, piRow, piCol, piVal, -1);
	if (liRet != 0) {
		return -1;
	}

	return 0;
}

