                    }   
                }
                Point p = new Point(t.y,t.z-t.zz);
                ten[t.x] = p;
            }
            else{
                if((ten[t.x].x%2==0 && t.y%2==0) || (ten[t.x].x%2==1 && t.y%2==1)){
                    if(ten[t.x].y!=t.z-t.zz){
                        flag = false;
                    }
                }
                else{
                    if(ten[t.x].y!=t.zz-t.z){
                        flag = false;
                    }
                }
            }
            if(!flag){
                break;
            }
        }
        if(flag){
            out.println("Yes");
        }
        else{
            out.println("No");
        }
        out.flush();
