	void solve() throws IOException{
		int r = in.nextInt();
		int c = in.nextInt();
		int n = in.nextInt();
		int[] y = new int[n];
		int[] x = new int[n];
		int[] v = new int[n];
		for(int i=0; i<n; i++){
			y[i] = in.nextInt()-1;
			x[i] = in.nextInt()-1;
			v[i] = in.nextInt();
		}
		if(!ok(x, y, v, r, c)){
			System.out.println("No");
			return;
		}
		long max = tmp;
	    if(!ok(y, x, v, c, r)){
	    	System.out.println("No");
	    	return;
	    }
		max = -max-tmp;
		if(max+v[0]<0){
			System.out.println("No");
		}else{
			System.out.println("Yes");
		}
	}

	int tmp;
	boolean ok(int[] x, int[] y, int[] v, int r, int c){
		TreeMap<Integer, Group> xs = new TreeMap<>();
		final int n = y.length;
		for(int i=0; i<n; i++){
			Group g;
			if(xs.containsKey(y[i])){
				g = xs.get(y[i]);
			}else{
				g = new Group();
				xs.put(y[i], g);
			}
			g.list.add(new Pair(x[i], i));
		}
		TreeMap<Integer, Group> ys = new TreeMap<>();
		for(int i=0; i<n; i++){
			Group g;
			if(ys.containsKey(x[i])){
				g = ys.get(x[i]);
			}else{
				g = new Group();
				ys.put(x[i], g);
			}
			g.list.add(new Pair(y[i], i));
		}
		List<Group> xgs = new ArrayList<>();
		xgs.addAll(xs.values());
		List<Group> ygs = new ArrayList<>();
		ygs.addAll(ys.values());

		List<Integer>[] node = graph(xgs, ygs, n);
		int[] diff = new int[c];
		boolean[] see = new boolean[c];
		Queue<Integer> qu = new ArrayDeque<>(n);
		int next = 0;
		boolean[] used = new boolean[n];
		used[0] = true;
		int preD = 0;
		int preDmax = 0;
		while(next>=0){
			preDmax = Math.max(preDmax, preD);
			qu.add(next);
			next = -1;
			while(!qu.isEmpty()){
				int p = qu.poll();
				for(int np: node[p]){
					if(used[np]) continue;
					if(y[p] != y[np]){
						if(next==-1){
							next = np;
							preD += v[p]-v[np];
							used[np] = true;
						}
						continue;
					}
					used[np] = true;
					if(see[x[np]]){
						if(-v[np] != diff[x[np]] + preD) return false;
					}else{
						see[x[np]] = true;
						diff[x[np]] = diff[x[p]] + v[p]-v[np];
					}
					qu.add(np);
				}
			}
		}
		tmp = Arrays.stream(diff).max().getAsInt();
		return true;
	}

	List<Integer>[] graph(List<Group> xs, List<Group> ys, int n){
		List<Integer>[] res = new List[n];
		for(int i=0; i<n; i++){
			res[i] = new ArrayList<>();
		}
		for(Group g: xs){
			g.init();
			List<Pair> list = g.list;
			int pre = list.get(0).b;
			for(int i=1; i<list.size(); i++){
				int id = list.get(i).b;
				res[pre].add(id);
				res[id].add(pre);
				pre = id;
			}
		}
		for(Group g: ys){
			g.init();
			List<Pair> list = g.list;
			int pre = list.get(0).b;
			for(int i=1; i<list.size(); i++){
				int id = list.get(i).b;
				res[pre].add(id);
				res[id].add(pre);
				pre = id;
			}
		}
		return res;
	}
