/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author ilyakor
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        static final int SENTINEL = -2 * 1000 * 1000 * 1000;
        int[] d1;
        int[] d2;
        ArrayList<ii>[] g1;
        ArrayList<ii>[] g2;
        int i0;
        int j0;
        int c0;
        int lower;
        int upper;
        int len;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            d1 = new int[n];
            d2 = new int[m];
            Arrays.fill(d1, SENTINEL);
            Arrays.fill(d2, SENTINEL);

            g1 = new ArrayList[n];
            for (int i = 0; i < n; ++i)
                g1[i] = new ArrayList<>();
            g2 = new ArrayList[m];
            for (int i = 0; i < m; ++i)
                g2[i] = new ArrayList<>();

            int k = in.nextInt();
            i0 = -1;
            j0 = -1;
            c0 = -1;
            for (int i = 0; i < k; ++i) {
                int x = in.nextInt() - 1;
                int y = in.nextInt() - 1;
                int c = in.nextInt();
                if (i0 == -1) {
                    i0 = x;
                    j0 = y;
                    c0 = c;
                    d1[x] = c;
                    d2[y] = c;
                } else if (x == i0) {
                    d2[y] = c;
                } else if (y == j0) {
                    d1[x] = c;
                } else {
                    g1[x].add(new ii(y, c + c0));
                    g2[y].add(new ii(x, c + c0));
                }
            }

            for (int i = 0; i < n; ++i)
                if (d1[i] != SENTINEL)
                    if (!dfs1(0, i)) {
                        out.printLine("No");
                        return;
                    }
            for (int i = 0; i < m; ++i)
                if (d2[i] != SENTINEL)
                    if (!dfs1(1, i)) {
                        out.printLine("No");
                        return;
                    }

            len = c0;
            int U = 1000 * 1000 * 1000 + 1, D = 1000 * 1000 * 1000 + 1;
            for (int i = 0; i < n; ++i)
                if (d1[i] != SENTINEL)
                    U = Math.min(U, d1[i]);
            for (int i = 0; i < m; ++i)
                if (d2[i] != SENTINEL)
                    D = Math.min(D, d2[i]);
            len = Math.max(len, 2 * c0 - U - D);

            if (U + D < c0) {
                out.printLine("No");
                return;
            }

            for (int i = 0; i < n; ++i) {
                if (d1[i] != SENTINEL) continue;
                lower = 0;
                upper = 1000 * 1000 * 1000 + 1;
                dfs2(0, i, 0);
                if (lower > upper + len) {
                    out.printLine("No");
                    return;
                }
            }

            for (int i = 0; i < m; ++i) {
                if (d2[i] != SENTINEL) continue;
                lower = -1000 * 1000 * 1000 - 1;
                upper = 0;
                dfs2(1, i, 0);
                if (lower > upper + len) {
                    out.printLine("No");
                    return;
                }
            }
            out.printLine("Yes");
        }

        private void dfs2(int ind, int x, int c) {
            if (ind == 0) {
                d1[x] = c;
                // 0 <= c + x
                // x >= -c
                if (lower < -c)
                    lower = -c;
            } else {
                d2[x] = c;
                // c - x >= 0
                // x <= c
                if (upper > c)
                    upper = c;
            }
            if (lower > upper + len) return;
            int oind = 1 - ind;
            ArrayList<ii> adj = ind == 0 ? g1[x] : g2[x];
            for (ii edge : adj) {
                int y = edge.first;
                int oc = edge.second - c;
                int oval = oind == 0 ? d1[y] : d2[y];
                if (oval == SENTINEL) {
                    dfs2(oind, y, oc);
                } else {
                    if (oval != oc) {
                        lower = 1;
                        upper = -1;
                        return;
                    }
                }
                if (lower > upper + len) return;
            }
        }

        private boolean dfs1(int ind, int x) {
            int oind = 1 - ind;
            ArrayList<ii> adj = ind == 0 ? g1[x] : g2[x];
            int val = ind == 0 ? d1[x] : d2[x];
            for (ii edge : adj) {
                int y = edge.first;
                int c = edge.second - val;
                if (c < 0)
                    return false;
                int oval = oind == 0 ? d1[y] : d2[y];
                if (oval == SENTINEL) {
                    if (oind == 0)
                        d1[y] = c;
                    else
                        d2[y] = c;
                    if (!dfs1(oind, y))
                        return false;
                } else {
                    if (oval != c)
                        return false;
                }
            }
            return true;
        }

    }

    static class ii implements Comparable<ii> {
        public int first;
        public int second;

        public ii() {
        }

        public ii(int first, int second) {
            this.first = first;
            this.second = second;
        }

        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            ii ii = (ii) o;

            if (first != ii.first) return false;
            if (second != ii.second) return false;

            return true;
        }

        public int hashCode() {
            int result = first;
            result = 31 * result + second;
            return result;
        }

        public int compareTo(ii o) {
            if (first != o.first) {
                return first < o.first ? -1 : 1;
            }
            if (second != o.second) {
                return second < o.second ? -1 : 1;
            }
            return 0;
        }


        public String toString() {
            return "{" +
                    "first=" + first +
                    ", second=" + second +
                    '}';
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buffer = new byte[10000];
        private int cur;
        private int count;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (count == -1) {
                throw new InputMismatchException();
            }
            try {
                if (cur >= count) {
                    cur = 0;
                    count = stream.read(buffer);
                    if (count <= 0)
                        return -1;
                }
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            return buffer[cur++];
        }

        public int readSkipSpace() {
            int c;
            do {
                c = read();
            } while (isSpace(c));
            return c;
        }

        public int nextInt() {
            int sgn = 1;
            int c = readSkipSpace();
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res = res * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            res *= sgn;
            return res;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }
}

