/**
 * Built using CHelper plug-in Actual solution is at the top
 * 
 * @author daltao
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "daltao", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            PrintWriter out = new PrintWriter(outputStream);
            TaskD solver = new TaskD();
            solver.solve(1, in, out);
            out.close();
        }
    }
    static class TaskD {
        public void solve(int testNumber, FastInput in, PrintWriter out) {
            int r = in.readInt();
            int c = in.readInt();
            int n = in.readInt();
            int[][] rcas = new int[n][3];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 3; j++) {
                    rcas[i][j] = in.readInt();
                }
            }
            Arrays.sort(rcas, (a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);

            Node[] cols = new Node[c + 1];
            for (int i = 1; i <= c; i++) {
                cols[i] = new Node();
            }

            for (int i = 1; i < n; i++) {
                int ci = rcas[i][1];

                for (int j = i - 1; j >= 0 && rcas[i][0] == rcas[j][0]; j--) {
                    int cj = rcas[j][1];
                    if (cols[ci].find() == cols[cj].find()) {
                        if (cols[ci].diff - cols[cj].diff != rcas[i][2] - rcas[j][2]) {
                            out.println("No");
                            return;
                        }
                    } else {
                        Node.merge(cols[cj], cols[ci], rcas[i][2] - rcas[j][2]);
                    }
                    break;
                }

                Node min = cols[ci].find().min;
                int val = rcas[i][2] - cols[ci].diff + min.diff;
                if (val < 0) {
                    out.println("No");
                    return;
                }
            }


            out.println("Yes");
        }

    }
    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
    static class Node {
        Node p = this;
        int rank;
        int diff;
        Node min = this;

        public Node find() {
            if (p.p == p) {
                return p;
            }
            p.find();
            diff += p.diff;
            p = p.find();
            return p;
        }

        public static Node min(Node a, Node b) {
            a.find();
            b.find();
            return a.diff <= b.diff ? a : b;
        }

        public static void merge(Node a, Node b, int d) {
            a.find();
            b.find();
            // Rb + Db = Ra + Da + d
            // Rb = Ra + Da + d - Db
            d = a.diff + d - b.diff;
            a = a.find();
            b = b.find();
            if (a == b) {
                return;
            }
            if (a.rank == b.rank) {
                a.rank++;
            }
            if (a.rank > b.rank) {
                b.p = a;
                b.diff = d;
                a.min = min(a.min, b.min);

            } else {
                a.p = b;
                a.diff = -d;
                b.min = min(a.min, b.min);
            }
        }

    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.util.HashMap;
import java.util.NoSuchElementException;

public class Main {
	static FastScanner sc = new FastScanner();
	static PrintStream out = System.out;
	static HashMap<Long, Integer> map = new HashMap<Long, Integer>();
	static final int D_INIT = -10000007;
	static final int POS_INIT = 10000007;

	public static void main(String args[]) {
		try {
			int R = ni();
			int C = ni();
			int N = ni();
			boolean check = true;
			int CD = D_INIT;
			int RD = D_INIT;
			int RR[] = new int[R];
			int Rmin[] = new int[R];
			int CC[] = new int[C];
			int Cmin[] = new int[C];
			for (int i=0;i<R;i++)
				Rmin[i] = POS_INIT;
			for (int i=0;i<C;i++)
				Cmin[i] = POS_INIT;

			for (int i=0;i<N;i++) {
				int r = ni() - 1;
				int c = ni() - 1;
				int a = ni();

				if (Rmin[r] != POS_INIT) {
					int t = RR[r] - a;
					int s = Rmin[r] - c;
					if (checkmod0(t, s) == false) {
						check = false;
					} else {
						int dd = 0;
						if (s != 0) dd = t/s;
						if (RD == D_INIT) {
							RD = dd;
						} else if (RD != dd) {
							check = false;
						}
					}
				} else {
					Rmin[r] = c;
					RR[r] = a;
				}

				if (Cmin[c] != POS_INIT) {
					int t = CC[c] - a;
					int s = Cmin[c] - r;
					if (checkmod0(t, s) == false) {
						check = false;
					} else {
						int dd = 0;
						if (s != 0) dd = t/s;
						if (CD == D_INIT) {
							CD = dd;
						} else if (CD != dd) {
							check = false;
						}
					}
				} else {
					Cmin[c] = r;
					CC[c] = a;
				}
			}

			// minus check
			for (int i=0;i<R;i++) {
				long pos = Rmin[i];
				long val = RR[i];
				long d = RD;
				if (pos == POS_INIT) continue;
				if (d == D_INIT) continue;

				if (val - pos * d < 0) check = false;
				if (val + ((long) R - 1 - pos) * d < 0) check = false;
			}

			for (int i=0;i<C;i++) {
				long pos = Cmin[i];
				long val = CC[i];
				long d = CD;
				if (pos == POS_INIT) continue;
				if (d == D_INIT) continue;

				if (val - pos * d < 0) check = false;
				if (val + ((long) C - 1 - pos) * d < 0) check = false;
			}

			System.out.println(check ? "Yes" : "No");
		} catch (Exception e) {
			System.out.println("Yes");
		}
	}

	private static boolean checkmod0(int a, int b) {
		if (a < 0) a = -a;
		if (b < 0) b = -b;
		if (b == 0) return true;

		return (a%b) == 0;
	}

	private static String next() {
		return sc.next();
	}

	private static int ni() {
		return sc.nextInt();
	}

	private static long nl() {
		return sc.nextLong();
	}

	private static int[] na(int n) {
		int[] a = new int[n];
		for(int i = 0;i < n;i++) a[i] = ni();
		return a;
	}

	private static long[] nal(int n) {
		long[] a = new long[n];
		for(int i = 0;i < n;i++) a[i] = ni();
		return a;
	}

	private static double nd() {
		return Double.parseDouble( next() );
	}
}

class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
	public boolean hasNext() { skipUnprintable(); return hasNextByte();}
	public String next() {
		if (!hasNext()) throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public int nextInt() {
		if (!hasNext()) throw new NoSuchElementException();
		int n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public long nextLong() {
		if (!hasNext()) throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
}

