		long weight;
		public P(int type,int pos,long weight){
			this.type = type;
			this.pos = pos;
			this.weight = weight;
		}
	}

	public void solve() {
		R = nextInt();
		C = nextInt();
		N = nextInt();

		r = new int[N];
		c = new int[N];
		a = new int[N];

		used = new boolean[2][];
		used[0] = new boolean[R];
		used[1] = new boolean[C];

		b = new long[2][];
		b[0] = new long[R];
		b[1] = new long[C];

		graph = new ArrayList[2][];
		graph[0] = new ArrayList[R];
		graph[1] = new ArrayList[C];

		for(int i = 0;i < R;i++){
			graph[0][i] = new ArrayList<Edge>();
		}

		for(int i = 0;i < C;i++){
			graph[1][i] = new ArrayList<Edge>();
		}

		for(int i = 0;i < N;i++){
			r[i] = nextInt() - 1;
			c[i] = nextInt() - 1;
			a[i] = nextInt();

			graph[0][r[i]].add(new Edge(c[i],a[i]));
			graph[1][c[i]].add(new Edge(r[i],a[i]));
		}
		long min = Long.MAX_VALUE;
		for(int i = 0;i < N;i++){
			Queue<P> q = new ArrayDeque<P>();
			//type,pos,weight
			q.add(new P(0,r[i],0));
			while(q.size() > 0){
				P p = q.poll();
				if(used[p.type][p.pos])continue;
				used[p.type][p.pos] = true;
				b[p.type][p.pos] = p.weight;
				min = Math.min(min,b[p.type][p.pos]);
				for(Edge e : graph[p.type][p.pos]){
					q.add(new P(((p.type + 1)&1),e.t,e.w - p.weight));
				}
			}
		}

		for(int i = 0;i < N;i++){
			//out.println(a[i] + " - " + b[0][r[i]] + " - " + b[1][c[i]] + " - " + min);
			if(a[i] - b[0][r[i]] - b[1][c[i]] - min >= 0)continue;
			out.println("No");
			return;
		}

		out.println("Yes");
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.io.*;
import java.util.*;

public class Main {

    class Pair {
        int r, c;
        long value;

        public Pair(int r, int c, long value) {
            this.r = r;
            this.c = c;
            this.value = value;
        }
    }

    class Graph {
        class Edge {
            int from, to;
            long diff;

            public Edge(int from, int to, long diff) {
                this.from = from;
                this.to = to;
                this.diff = diff;
            }
        }

        List<Edge>[] graph;
        long[] vals;
        boolean[] vis;

        public Graph(int n) {
            graph = new List[n];
            for (int i = 0; i < n; i++) {
                graph[i] = new ArrayList<>();
            }
            vals = new long[n];
            Arrays.fill(vals, Long.MAX_VALUE / 3);
            vis = new boolean[n];
        }

        void run(int u, long init) {
            if (!vis[u]) {
                dfs(u, init);
            }
        }

        void dfs(int u, long cur) {
            vals[u] = cur;
            vis[u] = true;
            for (int t = 0; t < graph[u].size(); t++) {
                Edge e = graph[u].get(t);
                if (!vis[e.to]) {
                    dfs(e.to, cur + e.diff);
                }
            }
        }

        void addEdge(int from, int to, long cost) {
            graph[from].add(new Edge(from, to, cost));
            graph[to].add(new Edge(to, from, -cost));
        }
    }


    public void solve() {
        int r = in.nextInt(), c = in.nextInt();
        int n = in.nextInt();
        Pair[] p = new Pair[n];
        for (int i = 0; i < n; i++) {
            p[i] = new Pair(in.nextInt() - 1, in.nextInt() - 1, in.nextInt());
        }
        Graph rows = new Graph(r), cols = new Graph(c);

        Arrays.sort(p, new Comparator<Pair>() {
            @Override
            public int compare(Pair o1, Pair o2) {
                if (o1.r == o2.r) {
                    return Integer.compare(o1.c, o2.c);
                }
                return Integer.compare(o1.r, o2.r);
            }
        });
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && p[i].r == p[j].r) {
                j++;
            }

            for (int t = i; t + 1 < j; t++) {
                cols.addEdge(p[t].c, p[t + 1].c, -p[t].value + p[t + 1].value);
            }
            i = j;
        }

        Arrays.sort(p, new Comparator<Pair>() {
            @Override
            public int compare(Pair o1, Pair o2) {
                if (o1.c == o2.c) {
                    return Integer.compare(o1.r, o2.r);
                }
                return Integer.compare(o1.c, o2.c);
            }
        });
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && p[i].c == p[j].c) {
                j++;
            }

            for (int t = i; t + 1 < j; t++) {
                rows.addEdge(p[t].r, p[t + 1].r, -p[t].value + p[t + 1].value);
            }
            i = j;
        }

        for (int i = 0; i < n; i++) {
            rows.run(p[i].r, 0);
            cols.run(p[i].c, 0);
        }

        Pair[] rs = new Pair[r];
        for (int i = 0; i < r; i++) {
            rs[i] = new Pair(i, 0, rows.vals[i]);
        }
        Arrays.sort(rs, new Comparator<Pair>() {
            @Override
            public int compare(Pair o1, Pair o2) {
                return Long.compare(o1.value, o2.value);
            }
        });
        Arrays.fill(rows.vis, false);
        for (int i = 0; i < r; i++) {
            if (!rows.vis[rs[i].r]) {
                rows.run(rs[i].r, 0);
            }
        }
        Arrays.fill(cols.vis, false);
        for (int i = 0; i < n; i++) {
            cols.run(p[i].c, p[i].value - rows.vals[p[i].r]);
        }

        for (int i = 0; i < n; i++) {
            Pair x = p[i];
            if (rows.vals[x.r] + cols.vals[x.c] != x.value) {
                out.println("No");
                return;
            }
        }

        long min1 = Long.MAX_VALUE, min2 = Long.MAX_VALUE;
        for (int i = 0; i < r; i++) {
            min1 = Math.min(min1, rows.vals[i]);
        }
        for (int j = 0; j < c; j++) {
            min2 = Math.min(min2, cols.vals[j]);
        }
        if (min1 + min2 < 0) {
            out.println("No");
            return;
        }
        out.println("Yes");
    }

    public void run() {
        in = new FastScanner();
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    FastScanner in;
    PrintWriter out;

    class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner(String fileName) {
            try {
                br = new BufferedReader(new FileReader(fileName));
            } catch (FileNotFoundException e) {
            }
        }

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

