			r[i] = nextInt() - 1;
			c[i] = nextInt() - 1;
			a[i] = nextInt();
			map[r[i]].put(c[i], a[i]);
			set.add((long)r[i] * (long)1e6 + c[i]);
			if(r[i] + 1 >= R || c[i] + 1 >= C)continue;
			for(int j = 0;j < 3;j++){
				int nr = r[i] + dy[j];
				int nc = c[i] + dx[j];
				map[nr].put(nc, -1);
			}
		}

		for(int i = 0;i < R - 1;i++){
			for(int key : map[i].keySet()){
				if(!set.contains((long)i * (long)1e6 + key))continue;
				if(key == C - 1)continue;
				int a = map[i].get(key);
				int b = map[i].get(key + 1);
				int c = map[i + 1].get(key);
				int d = map[i + 1].get(key + 1);

