						return;
					}
					map[i + 1].put(key + 1,c + b - a);
				}else if(a != -1 && b != -1 && c == -1 && d != -1){
					if(a + d < b){
						out.println("NO");
						return;
					}
					map[i + 1].put(key, a + d - b);
				}else if(a != -1 && b == -1 && c != -1 && d != -1){
					if(a + d < c){
						out.println("NO");
						return;
					}
					map[i].put(key + 1, a + d - c);
				}else if(a == -1 && b != -1 && c != -1 && d != -1){
					if(b + c < d){
						out.println("NO");
						return;
					}
					map[i].put(key, b + c - d);
				}
			}
		}
		out.println("YES");
	}

