                int pos = (a[0] << 1) + (a[1] & 1);
                int diff = a[2] - b[2];
                Integer value = xx.get(pos);
                if (value != null && value != diff) {
                    return false;
                }
                if (value == null) {
                    xx.put(pos, diff);
                }
                pos ^= 1;
                diff = -diff;
                value = xx.get(pos);
                if (value != null && value != diff) {
                    return false;
                }
                if (value == null) {
                    xx.put(pos, diff);
                }
            } else if (a[1] + 1 == b[1]) {
                rects.add(new int[]{a[0], a[1], a[2] + b[2]});
            }
        }

        return true;
    }

    final boolean check1(final int[] a, final int[] b) {
