            value = yy.get(pos);
            if (value != null && value != diff) {
                return false;
            }
            if (value == null) {
                yy.put(pos, diff);
            }
        }

        return true;
    }

    final boolean check2(final int x, final int y, final int value) {
        long key = (((long) x) << 32) | y;
        Integer hasValue = xy.get(key);
        if (hasValue != null && hasValue != value) {
            return false;
        }
        if (hasValue == null) {
            xy.put(key, value);
        }
        return true;
    }

