import java.util.TreeSet;

public class Main {
	int w, h;
	TreeSet<C> set;
	TreeMap<Integer, List<C>> mapX, mapY;
	TreeMap<Pair, C> map;

	class C implements Comparable<C> {
		Pair p;
		long value;

		C(int x, int y, int value) {
			this.p = new Pair(x, y);
			this.value = value;
		}

		@Override
		public int compareTo(C o) {
			return this.p.compareTo(o.p);
		}
	}

	class Pair implements Comparable<Pair> {
		int x, y;

		Pair(int x, int y) {
			this.x = x;
			this.y = y;
		}

		@Override
		public int compareTo(Pair o) {
			if (this.x != o.x) {
				return this.x - o.x;
			}
			return this.y - o.y;
		}
	}

	void run() {
		Scanner sc = new Scanner(System.in);

		w = sc.nextInt();
		h = sc.nextInt();
		int n = sc.nextInt();
		C[] c = new C[n];
		set = new TreeSet<C>();
		mapX = new TreeMap<Integer, List<C>>();
		mapY = new TreeMap<Integer, List<C>>();
		map = new TreeMap<Pair, C>();
		for (int i = 0; i < n; i++) {
			int x = sc.nextInt();
			int y = sc.nextInt();
			int v = sc.nextInt();
			C tmp = new C(x, y, v);
			c[i] = tmp;
			set.add(tmp);
			if (mapX.containsKey(x)) {
				mapX.get(x).add(tmp);
			} else {
				List<C> xlist = new LinkedList<C>();
				xlist.add(tmp);
				mapX.put(x, xlist);
			}
			if (mapY.containsKey(y)) {
				mapY.get(y).add(tmp);
			} else {
				List<C> ylist = new LinkedList<C>();
				ylist.add(tmp);
				mapY.put(y, ylist);
			}
			map.put(new Pair(x, y), new C(x, y, v));
		}

		for (int i = 0; i < n; i++) {
			int x = c[i].p.x;
			int y = c[i].p.y;
			List<C> listX = mapX.get(x);
			List<C> listY = mapY.get(y);
			if (listX == null || listY == null) {
				continue;
			}
			for (C tmpX : listX) {
				for (C tmpY : listY) {
					int nx = tmpY.p.x;
					int ny = tmpX.p.y;
//					System.out.println(x + " " + y + " " + nx + " " + ny);
					long k = tmpX.value + tmpY.value - c[i].value;
					C tmpC = map.get(new Pair(nx, ny));
					if ((tmpC != null && tmpC.value != k) || (k < 0)) {
						System.out.println("No");
						return;
					}
				}
			}
		}
		System.out.println("Yes");
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

import java.io.*;
import java.util.*;


public class Main{
	int R;
	int C;
	int N;

	class Graph{
		Node[] nodes;
		public Graph(int n){
			nodes = new Node[n];
			for(int i = 0; i < n; i++){
				nodes[i] = new Node(i);
			}
		}
		public void addEdge(int from, int to, int weight){
			nodes[from].add(new Edge(nodes[from], nodes[to], weight));
		}
		public void addBiEdge(int n1, int n2, int weight){
			addEdge(n1, n2, weight);
			addEdge(n2, n1, weight);
		}
	}

	class Node extends ArrayList<Edge>{
		int idx;
		int value;
		boolean flg;
		public Node(int idx){
			this.idx = idx;
		}

	}

	class Edge{
		Node from;
		Node to;
		int weight;
		public Edge(Node from, Node to, int weight){
			this.from = from;
			this.to = to;
			this.weight = weight;
		}
	}

	public void solve(){
		R = nextInt();
		C = nextInt();
		N = nextInt();

		Graph g = new Graph(R + C);

		for(int i = 0; i < N; i++){
			int r = nextInt() - 1;
			int c = nextInt() - 1;
			int a = nextInt();
			g.addBiEdge(r, c + R, a);
		}

		for(Node n : g.nodes){
			if(!n.flg){
				n.flg = true;
				n.value = 0;
				int[] min = new int[2];
				if(!dfs(n, min)){
					out.println("No");
					return;
				}
				if(min[0] + min[1] < 0){
					out.println("No");
					return;
				}
			}
		}
		out.println("Yes");
	}

	public boolean dfs(Node n, int[] min){
		if(n.idx < R){
			min[0] = Math.min(min[0], n.value);
		}else{
			min[1] = Math.min(min[1], n.value);
		}
		for(Edge p : n){
			if(p.to.flg){
				if(n.value + p.to.value != p.weight) return false;
			}else{
				p.to.flg = true;
				p.to.value = p.weight - n.value;
				if(!dfs(p.to, min)) return false;
			}
		}
		return true;
	}



	private static PrintWriter out;
	public static void main(String[] args){
		out = new PrintWriter(System.out);
		new Main().solve();
		out.flush();
	}



