public class Main {
	static final long C =  1000000007;
	static final int CY = 1000000000;
	StringBuilder sb;
	public void calc() {
		sb = new StringBuilder();


		FastScanner sc = new FastScanner();

		int R = sc.nextInt();
		int C = sc.nextInt();
		int n = sc.nextInt();

		int[] r = new int [n];
		int[] c = new int[n];
		int[] a = new int[n];
		for (int i=0; i < n; i++) {
			r[i] = sc.nextInt()-1;
			c[i] = sc.nextInt()-1;
			a[i] = sc.nextInt();
		}

		boolean ans = true;
		boolean[] rdf = new boolean[R];
		int[] rd = new int[R];
		int[] rmin = new int[R];
		int[] rmax = new int[R];
		boolean[] cdf = new boolean[C];
		int[] cd = new int[C];
		int[] cmin = new int[C];
		int[] cmax = new int[C];
		Arrays.fill(rmax, Integer.MAX_VALUE);
		Arrays.fill(rmin, Integer.MIN_VALUE);
		Arrays.fill(cmax, Integer.MAX_VALUE);
		Arrays.fill(cmin, Integer.MIN_VALUE);

		LOOP:for (int i=0; i< n; i++) {
			if (c[i] != C-1) {
				for (int t=0; t < n; t++) {
					//隣なら
					if (r[i] == r[t] && c[i] == c[t]-1) {
						if (cdf[c[i]]) {
							if (a[i]-a[t] != cd[c[i]]) {

								ans = false;
								break LOOP;
							}
						}else {
							cdf[c[i]] = true;
							cd[c[i]] = a[i]-a[t];
							if (cd[c[i]] < cmin[c[i]] || cmax[c[i]] < cd[c[i]]) {

								ans = false;
								break LOOP;
							}
						}
					}
				}
			}
			//C
			if (r[i] != R-1) {

				for (int t=0; t < n; t++) {
					//隣なら
					if (c[i] == c[t] && r[i] == r[t]-1) {
						if (rdf[r[i]]) {
							if (a[i]-a[t] != rd[r[i]]) {
								ans = false;
								break LOOP;
							}
						}else {
							rdf[r[i]] = true;
							rd[r[i]] = a[i]-a[t];
							if (rd[r[i]] < rmin[r[i]] || rmax[r[i]] < rd[r[i]]) {
								ans = false;
								break LOOP;
							}
						}
					}
				}
			}
			//RM
			if (r[i] != 0) {
				rmin[r[i]-1] = Math.max(-a[i], rmin[r[i]-1]);
				if (rdf[r[i]-1] && rd[r[i]-1] < rmin[r[i]-1]) {
					ans = false;
					break LOOP;
				}
			}
			if (r[i] != R-1) {

				rmax[r[i]] = Math.min(a[i], rmax[r[i]]);
				if (rdf[r[i]] && rd[r[i]] > rmax[r[i]]) {
					ans = false;
					break LOOP;
				}
			}
			//CM
			if (c[i] != 0) {

				cmin[c[i]-1] = Math.max(-a[i], cmin[c[i]-1]);
				if (cdf[c[i]-1] && cd[c[i]-1] < cmin[c[i]-1]) {
					//System.err.println(cmin[c[i]-1] + ":" +  cd[c[i]-1]);
					ans = false;
					break LOOP;
				}
			}
			if (c[i] != C-1) {

				cmax[c[i]] = Math.min(a[i], cmax[c[i]]);
				if (cdf[c[i]] && cd[c[i]] > cmax[c[i]]) {
					ans = false;
					break LOOP;
				}
			}
		}


		System.out.println(ans?"Yes": "No");
	}



