import java.util.Arrays;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in Actual solution is at the top
 * 
 * @author daltao
 */
public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "daltao", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            PrintWriter out = new PrintWriter(outputStream);
            TaskD solver = new TaskD();
            solver.solve(1, in, out);
            out.close();
        }
    }
    static class TaskD {
        public void solve(int testNumber, FastInput in, PrintWriter out) {
            int r = in.readInt();
            int c = in.readInt();
            int n = in.readInt();
            int[][] rcas = new int[n][3];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 3; j++) {
                    rcas[i][j] = in.readInt();
                }
            }

            out.println(check(r, c, rcas) ? "Yes" : "No");
        }

        public boolean check(int r, int c, int[][] rcas) {
            int n = rcas.length;
            Arrays.sort(rcas, (a, b) -> a[0] == b[0] ? a[1] - b[1] : a[0] - b[0]);

            Node[] cols = new Node[c + 1];
            for (int i = 1; i <= c; i++) {
                cols[i] = new Node();
            }

            for (int i = 1; i < n; i++) {
                int ci = rcas[i][1];

                for (int j = i - 1; j >= 0 && rcas[i][0] == rcas[j][0]; j--) {
                    int cj = rcas[j][1];
                    if (cols[ci].find() == cols[cj].find()) {
                        if (cols[ci].diff - cols[cj].diff != rcas[i][2] - rcas[j][2]) {
                            return false;
                        }
                    } else {
                        Node.merge(cols[cj], cols[ci], rcas[i][2] - rcas[j][2]);
                    }
                    break;
                }
            }

            Arrays.sort(rcas, (a, b) -> a[1] == b[1] ? a[0] - b[0] : a[1] - b[1]);
            Node[] rows = new Node[r + 1];
            for (int i = 1; i <= r; i++) {
                rows[i] = new Node();
            }

            for (int i = 1; i < rcas.length; i++) {
                int ri = rcas[i][0];

                for (int j = i - 1; j >= 0 && rcas[i][1] == rcas[j][1]; j--) {
                    int rj = rcas[j][0];
                    if (rows[ri].find() == rows[rj].find()) {
                        if (rows[ri].diff - rows[rj].diff != rcas[i][2] - rcas[j][2]) {
                            return false;
                        }
                    } else {
                        Node.merge(rows[rj], rows[ri], rcas[i][2] - rcas[j][2]);
                    }
                    break;
                }
            }

            for (int i = 0; i < n; i++) {
                int rr = rcas[i][0];
                int cc = rcas[i][1];
                long v = rcas[i][2];

                Node minRow = rows[rr].find().min;
                v = v - rows[rr].diff + minRow.diff;
                Node minCol = cols[cc].find().min;
                v = v - cols[cc].diff + minCol.diff;
                if (v < 0) {
                    return false;
                }
            }

            return true;
        }

    }
    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
    static class Node {
        Node p = this;
        int rank;
        long diff;
        Node min = this;

        public Node find() {
            if (p.p == p) {
                return p;
            }
            p.find();
            diff += p.diff;
            p = p.find();
            return p;
        }

        public static Node min(Node a, Node b) {
            a.find();
            b.find();
            return a.diff <= b.diff ? a : b;
        }

        public static void merge(Node a, Node b, long d) {
            a.find();
            b.find();
            // Rb + Db = Ra + Da + d
            // Rb = Ra + Da + d - Db
            d = a.diff + d - b.diff;
            a = a.find();
            b = b.find();
            if (a == b) {
                return;
            }
            if (a.rank == b.rank) {
                a.rank++;
            }
            if (a.rank > b.rank) {
                b.p = a;
                b.diff = d;
                a.min = min(a.min, b.min);

            } else {
                a.p = b;
                a.diff = -d;
                b.min = min(a.min, b.min);
            }
        }

    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main m = new Main();
		m.solve();
	}

	private void solve() {
		Scanner sc = new Scanner(System.in);
		int R = sc.nextInt();
		int C = sc.nextInt();
		int N = sc.nextInt();
		Pt[] p = new Pt[N + 1];
		ArrayList<Pt>[] ra = new ArrayList[R + 1];
		ArrayList<Pt>[] ca = new ArrayList[C + 1];
		String ans = "Yes";

		for (int i = 1; i <= N; i++) {
			p[i] = new Pt();
			p[i].r = sc.nextInt();
			p[i].c = sc.nextInt();
			p[i].a = sc.nextInt();
			p[i].i = i;
			if (ra[p[i].r] == null) {
				ra[p[i].r] = new ArrayList<Pt>();
			}
			ra[p[i].r].add(p[i]);
			if (ca[p[i].c] == null) {
				ca[p[i].c] = new ArrayList<Pt>();
			}
			ca[p[i].c].add(p[i]);
		}

		boolean[] chk = new boolean[N + 1];
		int[] r_min = new int[N + 1];
		int[] c_min = new int[N + 1];
		int[] r_d = new int[R + 1];
		int[] c_d = new int[C + 1];
		int[] r_grp = new int[R + 1];
		int[] c_grp = new int[C + 1];
		Arrays.fill(r_d, Integer.MIN_VALUE);
		Arrays.fill(c_d, Integer.MIN_VALUE);

		Queue<Pt> r_que = new ArrayDeque<>();
		Queue<Pt> c_que = new ArrayDeque<>();
		i_LOOP: for (int i = 1; i <= N; i++) {
			if (chk[i]) {
				continue;
			}

			r_que.clear();
			c_que.clear();
			r_que.add(p[i]);
			c_que.add(p[i]);
			r_grp[p[i].r] = i;
			c_grp[p[i].c] = i;
			r_d[p[i].r] = 0;
			c_d[p[i].c] = 0;
			chk[i] = true;
			int r_m = Integer.MAX_VALUE;
			int c_m = Integer.MAX_VALUE;
			while (r_que.size() > 0 || c_que.size() > 0) {
				if (r_que.size() > 0) {
					Pt cur = r_que.poll();
					if (ra[cur.r] != null) {
						for (Pt t : ra[cur.r]) {
							if (t == cur) {
								continue;
							}
							int d = t.a - cur.a;
							if (c_d[t.c] != Integer.MIN_VALUE
									&& c_d[t.c] != d) {
								ans = "No";
								break i_LOOP;
							} else {
								c_d[t.c] = d;
								c_m = Math.min(c_m, d);
							}
							chk[t.i] = true;
							if (c_grp[t.c] == 0) {
								c_grp[t.c] = i;
								c_que.add(t);
							}
						}
					}
				} else if (c_que.size() > 0) {
					Pt cur = c_que.poll();
					if (ca[cur.c] != null) {
						for (Pt t : ca[cur.c]) {
							if (t == cur) {
								continue;
							}
							int d = t.a - cur.a;
							if (r_d[t.r] != Integer.MIN_VALUE
									&& r_d[t.r] != d) {
								ans = "No";
								break i_LOOP;
							} else {
								r_d[t.r] = d;
								r_m = Math.min(r_m, d);
							}
							chk[t.i] = true;
							if (r_grp[t.r] == 0) {
								r_grp[t.r] = i;
