	void solve() throws IOException{
		int r = in.nextInt();
		int c = in.nextInt();
		int n = in.nextInt();
		int[] y = new int[n];
		int[] x = new int[n];
		int[] v = new int[n];
		for(int i=0; i<n; i++){
			y[i] = in.nextInt()-1;
			x[i] = in.nextInt()-1;
			v[i] = in.nextInt();
		}
		if(!ok(x, y, v, r, c)){
			System.out.println("No");
			return;
		}
	    if(!ok(y, x, v, c, r)){
	    	System.out.println("No");
	    	return;
	    }
