final class UnionFind {
	int[] data;

	UnionFind(int n) {
		data = new int[n];
		for (int i = 0; i < n; i++) {
			data[i] = -1;
		}
	}

	boolean union(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y)
			return false;
		if (data[y] < data[x]) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		data[x] += data[y];
		data[y] = x;
		return true;
	}

	boolean find(int x, int y) {
		return root(x) == root(y);
	}

	int root(int x) {
		return data[x] < 0 ? x : (data[x] = root(data[x]));
	}

	int size(int x) {
		return -data[root(x)];
	}
}

final class IO {
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out, false);
	private static final byte[] buffer = new byte[1024];
	private static int ptr = 0;
	private static int len = 0;

	private static boolean hasNextByte() {
		if (ptr < len)
			return true;
		ptr = 0;
		try {
			len = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		return len > 0;
	}

	private static int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	static boolean hasNext() {
		byte c;
		while (hasNextByte() && ((c = buffer[ptr]) < '!' || c > '~'))
			ptr++;
		return hasNextByte();
	}

	static String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (b >= '!' && b <= '~') {
			sb.append((char) b);
			b = readByte();
		}
		return sb.toString();
	}

	static long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static int nextInt() {
		if (!hasNext())
			throw new NoSuchElementException();
		int n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static void out(String val) {
		out.println(val);
	}

	static void flush() {
		out.flush();
	}
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.HashMap;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
import java.util.Map;
import java.io.BufferedReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		ProblemD solver = new ProblemD();
		solver.solve(1, in, out);
		out.close();
	}

	static class ProblemD {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int height = in.nextInt();
			int width = in.nextInt();
			int n = in.nextInt();
			int[] rs = new int[n];
			int[] cs = new int[n];
			long[] as = new long[n];
			Map<Long, Long> map = new HashMap<>();
			for (int i = 0; i < n; i++) {
				rs[i] = in.nextInt();
				cs[i] = in.nextInt();
				as[i] = in.nextInt();
				map.put(f(rs[i], cs[i]), as[i]);
			}
			boolean[][] got = new boolean[4][Math.max(height, width) + 1];
			long[][] val = new long[4][Math.max(height, width) + 1];
			int[] dr = {-1, 0, 1, 0};
			int[] dc = {0, -1, 0, 1};
			for (int i = 0; i < n; i++) {
				int r1 = rs[i];
				int c1 = cs[i];
				for (int dir = 0; dir < 4; dir++) {
					int r2 = rs[i] + dr[dir];
					int c2 = cs[i] + dc[dir];
					if (!map.containsKey(f(r2, c2))) {
						continue;
					}
					long v = map.get(f(r2, c2)) - map.get(f(r1, c1));
					int id = r1;
					if (dr[dir] == 0) {
						id = c1;
					}
					if (got[dir][id] && val[dir][id] != v) {
						out.println("No");
						return;
					}
					got[dir][id] = true;
					val[dir][id] = v;
				}
			}
			for (int dir = 0; dir < 4; dir++) {
				int[] xs = rs;
				if (dr[dir] == 0) {
					xs = cs;
				}
				if (!check(xs, as, got[dir], val[dir])) {
					out.println("No");
					return;
				}
			}
			out.println("Yes");
		}

		private boolean check(int[] xs, long[] as, boolean[] got, long[] v) {
			long[] min = new long[v.length];
			for (int i = v.length - 1; i >= 0; i--) {
				if (!got[i]) {
					min[i] = Long.MAX_VALUE / 2;
					continue;
				}
				min[i] = v[i];
				if (i + 1 < v.length) {
					min[i] = Math.min(min[i], min[i + 1] + v[i]);
				}
			}
			for (int i = 0; i < xs.length; i++) {
				int x = xs[i];
				if (got[x] && as[i] + min[x] < 0) {
					return false;
				}
			}
			return true;
		}

		private long f(int r, int c) {
			return r * (long) (1e6) + c;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.io.IOException;
