public class Main {
	int R,C,N;
	int[] r,c,a;
	long[] min;
	ArrayList<Edge>[][] graph;
	boolean[][] used;
	int[][] b;
	private class Edge{
		int t,w;
		public Edge(int t,int w){
			this.t = t;
			this.w = w;
		}
	}
	public void dfs(int type,int pos,long weight){
		if(used[type&1][pos])return;
		used[type&1][pos] = true;
		b[type&1][pos] = weight;
		min[type&1] = Math.min(min[type&1],weight);
		for(Edge e : graph[type&1][pos]){
			dfs((type+1)&1,e.t,e.w - weight);
		}
	}

	public void solve() {
		R = nextInt();
		C = nextInt();
		N = nextInt();
		r = new int[N];
		c = new int[N];
		a = new int[N];

		graph = new ArrayList[2][];
		graph[0] = new ArrayList[R];
		graph[1] = new ArrayList[C];
		for(int i = 0;i < R;i++)graph[0][i] = new ArrayList<Edge>();
		for(int i = 0;i < C;i++)graph[1][i] = new ArrayList<Edge>();

		for(int i = 0;i < N;i++){
			r[i] = nextInt() - 1;
			c[i] = nextInt() - 1;
			a[i] = nextInt();

			graph[0][r[i]].add(new Edge(c[i],a[i]));
			graph[1][c[i]].add(new Edge(r[i],a[i]));
		}

		used = new boolean[2][];
		used[0] = new boolean[R];
		used[1] = new boolean[C];

		b = new int[2][];
		b[0] = new int[R];
		b[1] = new int[C];
		min = new long[2];
		for(int i = 0;i < N;i++){
			if(used[0][r[i]] || used[1][c[i]])continue;
			min[0] = Long.MAX_VALUE;
			min[1] = Long.MAX_VALUE;
			dfs(0,r[i],0);
			if(min[0] + min[1] < 0){
				out.println("No");
				return;
			}
		}

		for(int i = 0;i < N;i++){

			if(a[i] == b[0][r[i]] + b[1][c[i]])continue;
			out.println("No");
			return ;

		}

		out.println("Yes");
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.io.FileNotFoundException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Main implements Runnable {

	class Edge {
		int src, dst;
		long cost;

		public Edge(int src_, int dst_, long cost_) {
			src = src_;
			dst = dst_;
			cost = cost_;
		}
	}

	boolean dfs(int cur, long[] num, ArrayList<Edge>[] g) {
		boolean ret = true;
		for (Edge e : g[cur]) {
			if (num[e.dst] != -1) {
				ret &= (num[e.dst] + num[cur] == e.cost);
				continue;
			}
			num[e.dst] = e.cost - num[cur];
			ret &= num[e.dst] + num[e.dst] >= 0;
			ret &= dfs(e.dst, num, g);
		}
		return ret;
	}

	void solver(int R, int C, int N, int[] r, int[] c, int[] a) {
		ArrayList<Edge>[] g = new ArrayList[R + C];
		for (int i = 0; i < g.length; ++i) {
			g[i] = new ArrayList<>();
		}
		for (int i = 0; i < N; ++i) {
			g[r[i]].add(new Edge(r[i], c[i] + R, a[i]));
			g[c[i] + R].add(new Edge(c[i] + R, r[i], a[i]));
		}
		long[] num = new long[R + C];
		Arrays.fill(num, -1);
		for (int i = 0; i < num.length; ++i) {
			if (num[i] != -1)
				continue;
			num[i] = 0;
			if (!dfs(i, num, g)) {
				System.out.println("No");
				return;
			}
		}
		System.out.println("Yes");
	}

	void input() {
		Scanner sc = new Scanner(System.in);
		int R = sc.nextInt();
		int C = sc.nextInt();
		int N = sc.nextInt();
		int[] r = new int[N];
		int[] c = new int[N];
		int[] a = new int[N];
		for (int i = 0; i < N; ++i) {
			r[i] = sc.nextInt();
			c[i] = sc.nextInt();
			a[i] = sc.nextInt();
			--r[i];
			--c[i];
		}
		solver(R, C, N, r, c, a);
	}

	public void run() {
		input();
	}

	public static void main(String[] args) throws FileNotFoundException {
		new Main().run();
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.io.*;
import java.util.*;
import java.math.*;
// import java.awt.Point;

public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    long inf = Long.MAX_VALUE/2;

    int r, c, n;
    Board[] bor;
    ArrayList<long[]>[] edge;
    long[] val;
    boolean[] seen;

    void solve(){
        r = ni();
        c = ni();
        n = ni();

        bor = new Board[n];
        for(int i = 0; i < n; i++){
            int x = ni()-1;
            int y = ni()-1;
            long v = nl();
            bor[i] = new Board(x, y, v);
        }

        edge = new ArrayList[r+c];
        for(int i = 0; i < r+c; i++){
            edge[i] = new ArrayList<long[]>();
        }

        for(int i = 0; i < n; i++){
            int x = bor[i].x;
            int y = bor[i].y + r;
            long v = bor[i].v;
            edge[x].add(new long[]{y, v});
            edge[y].add(new long[]{x, v});
        }

        val = new long[r+c];
        Arrays.fill(val, inf);

        for(int i = 0; i < r+c; i++){
            if(val[i]!=inf) continue;
            boolean flag = func(-1, i, 0);
            if(!flag){
                out.println("No");
                return;
            }
        }
        seen = new boolean[r+c];
        for(int i = 0; i < r+c; i++){
            if(seen[i]) continue;
            long[] ret = calc_min(-1, i);
            if(ret[0]+ret[1]<0){
                out.println("No");
                return;
            }
        }
        out.println("Yes");

    }

    long[] calc_min(int p, int c){
        seen[c] = true;
        long[] ret = new long[2];
        Arrays.fill(ret, inf);
        if(c<r) ret[0] = val[c];
        else ret[1] = val[c];

        for(long[] e : edge[c]){
            if(e[0]==p) continue;
            if(seen[(int)e[0]]) continue;
            seen[(int)e[0]] = true;
            long[] res = calc_min(c, (int)e[0]);
            ret[0] = Math.min(ret[0], res[0]);
            ret[1] = Math.min(ret[1], res[1]);
        }
        return ret;
    }

    boolean func(int p, int c, long v){
        boolean ret = true;
        if(val[c]!=inf){
            if(val[c]!=v) return false;
            else return true;
        }
        val[c] = v;
        for(long[] e : edge[c]){
            if(e[0]==p) continue;
            ret &= func(c, (int)e[0], e[1]-v);
        }
        return ret;
    }

    class Board{
        int x;
        int y;
        long v;
        Board(int x, int y, long v){
            this.x = x;
            this.y = y;
            this.v = v;
        }
    }


    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
