public class Main {
  private static class Task {
    class Edge {
      int to;
      long w;
      Edge(int to, long w) {
        this.to = to;
        this.w = w;
      }
    }

    ArrayList<Edge>[] E;
    boolean[] vis;
    long[] m = new long[2];
    long[] dist;

    boolean dfs(int u, int type) {
      vis[u] = true;
      m[type] = Math.min(m[type], dist[u]);

      for (Edge edge : E[u]) {
        if (vis[edge.to]) {
          if (dist[u] + dist[edge.to] != edge.w) return false;
          continue;
        }
        dist[edge.to] = edge.w - dist[u];
        if (!dfs(edge.to, type ^ 1)) return false;
      }
      return true;
    }

    void solve(FastScanner in, PrintWriter out) throws Exception {
      int R = in.nextInt();
      int C = in.nextInt();
      int N = in.nextInt();

      vis = new boolean[R + C];
      dist = new long[R + C];
      E = new ArrayList[R + C];
      for (int i = 0; i < R + C; i++) E[i] = new ArrayList<>();
      for (int i = 0; i < N; i++) {
        int u = in.nextInt() - 1;
        int v = in.nextInt() - 1;
        int w = in.nextInt();
        v += R;
        E[u].add(new Edge(v, w));
        E[v].add(new Edge(u, w));
      }

      for (int i = 0; i < R + C; ++i)
        if (!vis[i]) {
          dist[i] = 0;
          m[0] = m[1] = Long.MAX_VALUE;
          if (!dfs(i, 0) || m[0] + m[1] < 0) {
            out.println("No");
            return;
          }
        }

      out.println("Yes");

    }
  }

