public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    long inf = Long.MAX_VALUE/2;

    int r, c, n;
    Board[] bor;
    ArrayList<long[]>[] edge;
    long[] val;
    boolean[] seen;

    void solve(){
        r = ni();
        c = ni();
        n = ni();

        bor = new Board[n];
        for(int i = 0; i < n; i++){
            int x = ni()-1;
            int y = ni()-1;
            long v = nl();
            bor[i] = new Board(x, y, v);
        }

        edge = new ArrayList[r+c];
        for(int i = 0; i < r+c; i++){
            edge[i] = new ArrayList<long[]>();
        }

        for(int i = 0; i < n; i++){
            int x = bor[i].x;
            int y = bor[i].y + r;
            long v = bor[i].v;
            edge[x].add(new long[]{y, v});
            edge[y].add(new long[]{x, v});
        }

        val = new long[r+c];
        Arrays.fill(val, inf);

        for(int i = 0; i < r+c; i++){
            if(val[i]!=inf) continue;
            boolean flag = func(-1, i, 0);
            if(!flag){
                out.println("No");
                return;
            }
        }
        seen = new boolean[r+c];
        for(int i = 0; i < r+c; i++){
            if(seen[i]) continue;
            long[] ret = calc_min(-1, i);
            if(ret[0]+ret[1]<0){
                out.println("No");
                return;
            }
        }
        out.println("Yes");

    }

    long[] calc_min(int p, int c){
        seen[c] = true;
        long[] ret = new long[2];
        if(c<r) ret[0] = val[c];
        else ret[1] = val[c];

        for(long[] e : edge[c]){
            if(e[0]==p) continue;
            if(seen[(int)e[0]]) continue;
            seen[(int)e[0]] = true;
            long[] res = calc_min(c, (int)e[0]);
            ret[0] = Math.min(ret[0], res[0]);
            ret[1] = Math.min(ret[1], res[1]);
        }
        return ret;
    }

    boolean func(int p, int c, long v){
        boolean ret = true;
        if(val[c]!=inf){
            if(val[c]!=v) return false;
            else return true;
        }
        val[c] = v;
        for(long[] e : edge[c]){
            if(e[0]==p) continue;
            ret &= func(c, (int)e[0], e[1]-v);
        }
        return ret;
    }

    class Board{
        int x;
        int y;
        long v;
        Board(int x, int y, long v){
            this.x = x;
            this.y = y;
            this.v = v;
        }
    }


    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
