							dmax = Math.max(dmax, diff[x[np]]);
						}
						qu.add(np);
					}
				}
			}
			tmp = Math.max(tmp, dmax+preDmax);
		}
		return true;
	}

	List<Integer>[] graph(List<Group> xs, List<Group> ys, int n){
		List<Integer>[] res = new List[n];
		for(int i=0; i<n; i++){
			res[i] = new ArrayList<>();
		}
		for(Group g: xs){
			g.init();
			List<Pair> list = g.list;
			int pre = list.get(0).b;
			for(int i=1; i<list.size(); i++){
				int id = list.get(i).b;
				res[pre].add(id);
				res[id].add(pre);
				pre = id;
			}
		}
		for(Group g: ys){
			g.init();
			List<Pair> list = g.list;
			int pre = list.get(0).b;
			for(int i=1; i<list.size(); i++){
				int id = list.get(i).b;
				res[pre].add(id);
				res[id].add(pre);
				pre = id;
			}
		}
		return res;
	}
