					int t = RR[r] - a;
					int s = Rmin[r] - c;
					if (checkmod0(t, s) == false) {
						check = false;
					} else {
						int dd = 0;
						if (s != 0) dd = t/s;
						if (RD == D_INIT) {
							RD = dd;
						} else if (RD != dd) {
							check = false;
						}
					}
				} else {
					Rmin[r] = c;
					RR[r] = a;
				}

				if (Cmin[c] != POS_INIT) {
					int t = CC[c] - a;
					int s = Cmin[c] - r;
					if (checkmod0(t, s) == false) {
						check = false;
