import java.util.LinkedList;
import java.util.List;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
	int w, h;
	TreeMap<Integer, List<C>> mapX, mapY;
	TreeMap<Pair, C> map;

	class C implements Comparable<C> {
		Pair p;
		long value;

		C(int x, int y, long value) {
			this.p = new Pair(x, y);
			this.value = value;
		}

		@Override
		public int compareTo(C o) {
			return this.p.compareTo(o.p);
		}
	}

	class Pair implements Comparable<Pair> {
		int x, y;

		Pair(int x, int y) {
			this.x = x;
			this.y = y;
		}

		@Override
		public int compareTo(Pair o) {
			if (this.x != o.x) {
				return this.x - o.x;
			}
			return this.y - o.y;
		}
	}

	void run() {
		Scanner sc = new Scanner(System.in);

		w = sc.nextInt();
		h = sc.nextInt();
		int n = sc.nextInt();
		C[] c = new C[n];
		mapX = new TreeMap<Integer, List<C>>();
		mapY = new TreeMap<Integer, List<C>>();
		map = new TreeMap<Pair, C>();
		for (int i = 0; i < n; i++) {
			int x = sc.nextInt();
			int y = sc.nextInt();
			int v = sc.nextInt();
			C tmp = new C(x, y, v);
			c[i] = tmp;
			if (mapX.containsKey(x)) {
				mapX.get(x).add(tmp);
			} else {
				List<C> xlist = new LinkedList<C>();
				xlist.add(tmp);
				mapX.put(x, xlist);
			}
			if (mapY.containsKey(y)) {
				mapY.get(y).add(tmp);
			} else {
				List<C> ylist = new LinkedList<C>();
				ylist.add(tmp);
				mapY.put(y, ylist);
			}
			map.put(new Pair(x, y), new C(x, y, v));
		}

		for (int i = 0; i < n; i++) {
			int x = c[i].p.x;
			int y = c[i].p.y;
			List<C> listX = mapX.get(x);
			List<C> listY = mapY.get(y);
			if (listX == null || listY == null) {
				continue;
			}
			for (C tmpX : listX) {
				for (C tmpY : listY) {
					int nx = tmpY.p.x;
					int ny = tmpX.p.y;
					long k = tmpX.value + tmpY.value - c[i].value;
					C tmpC = map.get(new Pair(nx, ny));
					if ((tmpC != null && tmpC.value != k) || (k < 0)) {
						System.out.println("No");
						return;
					}
				}
			}
		}
		System.out.println("Yes");
	}

	public static void main(String[] args) {
		new Main().run();
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.NoSuchElementException;

public class Main {
	private static int[][][] DIR = { { { 1, 1 }, { 1, 0 }, { 0, 1 } }, { { -1, -1 }, { -1, 0 }, { 0, -1 } },
			{ { 1, -1 }, { 1, 0 }, { 0, -1 } }, { { -1, 1 }, { -1, 0 }, { 0, 1 } }, };

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		int R = sc.nextInt();
		int C = sc.nextInt();

		int N = sc.nextInt();
		Map<Long, Long> map = new HashMap<>();
		for (int i = 0; i < N; i++) {
			int r = sc.nextInt();
			int c = sc.nextInt();
			long a = sc.nextInt();
			map.put(enc(r, c), a);
		}

		boolean ng = false;
		Map<Long, Long> now = map;
		loop: while (now.size() > 0) {
			Map<Long, Long> newMap = new HashMap<>();
			for (Map.Entry<Long, Long> entry : now.entrySet()) {
				int[] p = dec(entry.getKey());
				int r = p[0];
				int c = p[1];
				long a = entry.getValue();

				for (int[][] d : DIR) {

					long hx = enc(r + d[0][0], c + d[0][1]);
					long hy = enc(r + d[1][0], c + d[1][1]);
					long hz = enc(r + d[2][0], c + d[2][1]);
					Long x = map.get(hx);
					Long y = map.get(hy);
					Long z = map.get(hz);

					long hash = 0;
					long v = 0;
					if (x == null && y != null && z != null) {
						v = y + z - a;
						hash = hx;
					} else if (x != null && y == null && z != null) {
						v = a + x - z;
						hash = hy;
					} else if (x != null && y != null && z == null) {
						v = a + x - y;
						hash = hz;
					} else if (x != null && y != null && z != null) {
						if (x + a != y + z) {
							ng = true;
							break loop;
						}
					}
					if (v < 0) {
						ng = true;
						break loop;
					}
					if (hash > 0)
						newMap.put(hash, v);
				}
			}
			map.putAll(newMap);
			now = newMap;
		}

		System.out.println(ng ? "No" : "Yes");
	}

	private static long enc(int r, int c) {
		return (long) r * 100000 + c;
	}

	private static int[] dec(long hash) {
		return new int[] { (int) (hash / 100000), (int) (hash % 100000) };
	}
}

