        Long v = get(r - 1, c);
        if (v == null) return true;
        long diff = a - v;
        Long d = rDiff.get(r - 1);
        if (d == null) {
          rDiff.put(r - 1, diff);
          return true;
        }
        return d == diff;
      } else {
        Long v = get(r + 1, c);
        if (v == null) return true;
        long diff = v - a;
        Long d = rDiff.get(r + 1);
        if (d == null) {
          rDiff.put(r, diff);
          return true;
        }
        return d == diff;
      }
    }

    boolean processC(long r, long c, long a, boolean left) {
      if (left) {
        Long v = get(r, c - 1);
        if (v == null) return true;
        long diff = a - v;
        Long d = cDiff.get(c - 1);
        if (d == null) {
          cDiff.put(c - 1, diff);
          return true;
        }
        return d == diff;
      } else {
        Long v = get(r, c + 1);
        if (v == null) return true;
        long diff = v - a;
        Long d = cDiff.get(c + 1);
        if (d == null) {
          cDiff.put(c, diff);
          return true;
        }
        return d == diff;
      }
    }

    boolean check(long r, long c, long a) {
      Long up = rDiff.get(r - 1);
      Long down = rDiff.get(r);
      Long left = cDiff.get(c - 1);
      Long right = cDiff.get(c);
      if (up != null) {
        if (a - up < 0) return false;
      }
      if (down != null) {
        if (a + down < 0) return false;
      }
      if (left != null) {
        if (a - left < 0) return false;
      }
      if (right != null) {
        if (a + right < 0) return false;
      }

      if (up != null && left != null) {
        long check = a - up - left;
        if (check < 0) return false;

        Long v = get(r - 1, c - 1);
        if (v != null && v != check) return false;
      }
      if (up != null && right != null) {
        long check = a - up + right;
        if (check < 0) return false;

        Long v = get(r - 1, c + 1);
        if (v != null && v != check) return false;
      }
      if (down != null && left != null) {
        long check = a + down - left;
        if (check < 0) return false;

        Long v = get(r + 1, c - 1);
        if (v != null && v != check) return false;
      }
      if (down != null && right != null) {
        long check = a + down + right;
        if (check < 0) return false;

        Long v = get(r + 1, c + 1);
        if (v != null && v != check) return false;
      }

      return true;
    }

    boolean solve(int[][] rca) {
      for (int i = 0; i < N; i++) {
        long r = rca[i][0];
        long c = rca[i][1];
        long a = rca[i][2];

        if (!processR(r, c, a, true)) return false;
        if (!processR(r, c, a, false)) return false;
        if (!processC(r, c, a, true)) return false;
        if (!processC(r, c, a, false)) return false;
      }

      for (int i = 0; i < N; i++) {
        long r = rca[i][0];
        long c = rca[i][1];
        long a = rca[i][2];
        if (!check(r, c, a)) return false;
      }

      return true;
    }

    Long get(long r, long c) {
      return map.get(r * MOD + c);
    }
  }

  /**
   * ここから下はテンプレートです。
   */
  public static void main(String[] args) throws Exception {
    OutputStream outputStream = System.out;
    FastScanner in = new FastScanner();
    PrintWriter out = new PrintWriter(outputStream);
    Task solver = new Task();
    solver.solve(in, out);
    out.close();
  }
  private static class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int bufferLength = 0;

    private boolean hasNextByte() {
      if (ptr < bufferLength) {
        return true;
      } else {
        ptr = 0;
        try {
          bufferLength = in.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (bufferLength <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) return buffer[ptr++];
      else return -1;
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
    }

    boolean hasNext() {
      skipUnprintable();
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) throw new NoSuchElementException();
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    long nextLong() {
      if (!hasNext()) throw new NoSuchElementException();
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    double nextDouble() {
      return Double.parseDouble(next());
    }

    double[] nextDoubleArray(int n) {
      double[] array = new double[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextDouble();
      }
      return array;
    }

    double[][] nextDoubleMap(int n, int m) {
      double[][] map = new double[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextDoubleArray(m);
      }
      return map;
    }

    public int nextInt() {
      return (int) nextLong();
    }

    public int[] nextIntArray(int n) {
      int[] array = new int[n];
      for (int i = 0; i < n; i++) array[i] = nextInt();
      return array;
    }

    public long[] nextLongArray(int n) {
      long[] array = new long[n];
      for (int i = 0; i < n; i++) array[i] = nextLong();
      return array;
    }

    public String[] nextStringArray(int n) {
      String[] array = new String[n];
      for (int i = 0; i < n; i++) array[i] = next();
      return array;
    }

    public char[][] nextCharMap(int n) {
      char[][] array = new char[n][];
      for (int i = 0; i < n; i++) array[i] = next().toCharArray();
      return array;
    }

    public int[][] nextIntMap(int n, int m) {
      int[][] map = new int[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextIntArray(m);
      }
      return map;
    }
  }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.NoSuchElementException;
import java.util.*;

public class Main {
	int R,C,N;
	int[] r,c,a;
	int[][] b;
	boolean[][] used;
	ArrayList<Edge>[][] graph;

	private class Edge{
		int t,w;
		public Edge(int t,int w){
			this.t = t;
			this.w = w;
		}
	}

	private class P{
		int type,pos,weight;
		public P(int type,int pos,int weight){
			this.type = type;
			this.pos = pos;
			this.weight = weight;
		}
	}

	public void solve() {
		R = nextInt();
		C = nextInt();
		N = nextInt();

		r = new int[N];
		c = new int[N];
		a = new int[N];

		used = new boolean[2][];
		used[0] = new boolean[R];
		used[1] = new boolean[C];

		b = new int[2][];
		b[0] = new int[R];
		b[1] = new int[C];

		graph = new ArrayList[2][];
		graph[0] = new ArrayList[R];
		graph[1] = new ArrayList[C];

		for(int i = 0;i < R;i++){
			graph[0][i] = new ArrayList<Edge>();
		}

		for(int i = 0;i < C;i++){
			graph[1][i] = new ArrayList<Edge>();
		}

		for(int i = 0;i < N;i++){
			r[i] = nextInt() - 1;
			c[i] = nextInt() - 1;
			a[i] = nextInt();

			graph[0][r[i]].add(new Edge(c[i],a[i]));
			graph[1][c[i]].add(new Edge(r[i],a[i]));
		}

		for(int i = 0;i < N;i++){
			if(used[0][r[i]] || used[1][c[i]])continue;
			Queue<P> q = new ArrayDeque<P>();
			//type,pos,weight
			q.add(new P(0,r[i],0));
			while(q.size() > 0){
				P p = q.poll();
				if(used[p.type][p.pos])continue;
				used[p.type][p.pos] = true;
				b[p.type][p.pos] = p.weight;
				for(Edge e : graph[p.type][p.pos]){
					q.add(new P(((p.type + 1)&1),e.t,p.weight + e.w));
				}
			}
		}

		for(int i = 0;i < N;i++){
			if(a[i] - b[0][r[i]] - b[1][c[i]] == 0)continue;
			out.println("No");
			return;
		}

		out.println("Yes");
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

