/**
 * Created by Aksenov239 on 24.09.2016.
 */
public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    BufferedReader br;
    StringTokenizer st;
    PrintWriter out;

    public String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    public class Pair implements Comparable<Pair> {
        int x, y;
        int a;

        public Pair(int x, int y, int a) {
            this.x = x;
            this.y = y;
            this.a = a;
        }

        public int compareTo(Pair p) {
            return x == p.x ? y - p.y : x - p.x;
        }
    }

    public class Edge {
        int v, w;

        public Edge(int v, int w) {
            this.v = v;
            this.w = w;
        }
    }

    ArrayList<Edge>[] e;
    int[] color;
    int[] value;
    int[] min;

    public void dfs(int v, int c, int current) throws Exception {
        if (color[v] == c) {
            if (value[v] != current) {
                throw new Exception("WTF?!");
            }
            return;
        }
        color[v] = c;
        value[v] = current;
        min[c] = Math.min(min[c], current);
        for (Edge edge : e[v]) {
            dfs(edge.v, c, edge.w + current);
        }
    }

    public void solve() throws IOException {
        int x = nextInt();
        int y = nextInt();
        int n = nextInt();
        Pair[] a = new Pair[n];
        e = new ArrayList[y];
        for (int i = 0; i < e.length; i++) {
            e[i] = new ArrayList<Edge>();
        }
        for (int i = 0; i < n; i++) {
            a[i] = new Pair(nextInt() - 1, nextInt() - 1, nextInt());
        }
        Arrays.sort(a);
        int i = 0;
        while (i < a.length) {
            int j = i + 1;
            while (j < a.length && a[i].x == a[j].x) {
                e[a[i].y].add(new Edge(a[j].y, a[j].a - a[i].a));
                e[a[j].y].add(new Edge(a[i].y, a[i].a - a[j].a));
                j++;
            }
            i = j;
        }
        color = new int[e.length];
        Arrays.fill(color, -1);
        min = new int[e.length];
        Arrays.fill(min, Integer.MAX_VALUE);
        value = new int[e.length];
        int c = 0;
        for (i = 0; i < e.length; i++) {
            if (color[i] == -1 && e[i].size() > 0) {
                try {
                    dfs(i, c++, 0);
                } catch (Exception e) {
                    out.println("No");
                    return;
                }
            }
        }
        for (i = 0; i < n; i++) {
            if (color[a[i].y] == -1)
                continue;
            c = color[a[i].y];
            int baseline = a[i].a - value[a[i].y];
            if (baseline + min[c] < 0) {
                out.println("No");
                return;
            }
        }
        out.println("Yes");
    }

    public void run() {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);

            solve();

            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
  private static void solve() {
    int R = ni();
    int C = ni();
    int N = ni();
    int[][] p = ntable(N, 3);
    Map<Integer, List<int[]>> map = new TreeMap<>();
    long[] cmin = new long[C];
    Arrays.fill(cmin, Long.MAX_VALUE);

    for (int[] v : p) {
      v[0] --;
      v[1] --;
      if (!map.containsKey(v[0])) {
        map.put(v[0], new ArrayList<>());
      }
      map.get(v[0]).add(v);
      cmin[v[1]] = Math.min(cmin[v[1]], v[2]);
    }

    List<List<int[]>> g = new ArrayList<>();
    for (int i = 0; i < C; i ++) {
      g.add(new ArrayList<>());
    }

    for (List<int[]> list : map.values()) {
      Collections.sort(list, (o1, o2) -> o1[1] - o2[1]);
      int[][] array = list.stream().toArray(size -> new int[size][]);
      int m = array.length;

      for (int i = 0; i < m - 1 ; i ++) {
        int from = array[i][1];
        int to = array[i + 1][1];
        int d = array[i + 1][2] - array[i][2];
        g.get(from).add(new int[] {to, d});
        g.get(to).add(new int[] {from, -d});
      }
    }

    long[] memo = new long[C];
    int[] minIdx = new int[C];
    Arrays.fill(memo, Long.MIN_VALUE);
    for (int i = 0; i < C; i ++) {
      if (cmin[i] > Long.MIN_VALUE) {
        if (memo[i] == Long.MIN_VALUE) {
          if (!dfs(i, 0, memo, minIdx, g)) {
            System.out.println("No");
            return;
          }
        }
        if (memo[minIdx[i]] - memo[i] + cmin[i] < 0) {
          System.out.println("No");
          return;
        }
      }
    }

    System.out.println("Yes");
  }

  private static boolean dfs(int now, long x, long[] memo, int[] minIdx, List<List<int[]>> g) {
    if (memo[now] != Long.MIN_VALUE) {
      return memo[now] == x;
    }
    memo[now] = x;
    minIdx[now] = now;

    for (int[] v : g.get(now)) {
      boolean ret = dfs(v[0], x + v[1], memo, minIdx, g);
      if (!ret) return false;

      if (memo[minIdx[v[0]]] < memo[minIdx[now]]) {
        minIdx[now] = minIdx[v[0]];
      }
    }
    return true;
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = args.length > 0 ? args[0] : null;
