          graph[prevC].add(new long[]{c, a - prevA});
          graph[c].add(new long[]{prevC, prevA - a});
          prevC = c;
          prevA = a;
        }
      }

      long[] dist = new long[C];
      Arrays.fill(dist, Long.MAX_VALUE);
      ArrayDeque<Integer> deque = new ArrayDeque<>();
      deque.add(start);
      dist[start] = min;
      while (!deque.isEmpty()) {
        int v = deque.poll();
        for (long[] edge : graph[v]) {
          int to = (int) edge[0];
          long w = edge[1];
          if (dist[to] == Long.MAX_VALUE) {
            dist[to] = dist[v] + w;
            deque.add(to);
          }
          if (dist[to] != dist[v] + w) return false;
          if (dist[to] < 0) return false;
        }
      }
      return true;
    }

    void put(int r, int c, int a) {
      {
        TreeMap<Integer, Integer> map = cMap.get(c);
        if (map == null) cMap.put(c, map = new TreeMap<>());
        map.put(r, a);
      }
      {
        TreeMap<Integer, Integer> map = rMap.get(r);
        if (map == null) rMap.put(r, map = new TreeMap<>());
        map.put(c, a);
      }
    }

  }

