	public static class DJSet {
		public int[] upper;
		public long[] delta;

		public DJSet(int n) {
			upper = new int[n];
			delta = new long[n];
			Arrays.fill(upper, -1);
		}

		public int root(int x) {
			if(upper[x] < 0)return x;
			int newr = root(upper[x]);
			delta[x] += delta[upper[x]];
			upper[x] = newr;
			return newr;
		}

		public boolean equiv(int x, int y) {
			return root(x) == root(y);
		}

		public boolean union(int x, int y, long xmy) {
			int rx = root(x);
			// v[x]-v[y]
			// v[rx]-v[ry]
			xmy += -delta[x];
			x = rx;
			int ry = root(y);
			xmy += delta[y];
			y = ry;
			if (x != y) {
				if (upper[y] < upper[x]) {
					int d = x;
					x = y;
					y = d;
					xmy = -xmy;
				}
				upper[x] += upper[y];
				delta[y] = -xmy;
				upper[y] = x;
			}else{
				if(xmy != 0)throw new IllegalStateException();
			}
			return x == y;
		}

		public int count() {
			int ct = 0;
			for (int u : upper)
				if (u < 0)
					ct++;
			return ct;
		}
	}


