      }
      public int hashCode() {
        return i*p + j;
      }
      public boolean equals(Object o) {
        if (o == null) return false;
        if (!(o instanceof Cell)) return false;

        Cell that = (Cell)o;
        if (i != that.i || j != that.j) return false;
        return true;
      }
