import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int H, W, N;
    static Cord[] C;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        N = sc.nextInt();
        C = new Cord[N];
        for (int i = 0; i < N; i++) {
            C[i] = new Cord(sc.nextInt()-1, sc.nextInt()-1, sc.nextInt());
        }

        System.out.println(solve() ? "Yes" : "No");
    }

    static class Cord {
        int r, c, a;

        public Cord(int r, int c, int a) {
            this.r = r;
            this.c = c;
            this.a = a;
        }
    }

    static boolean solve() {
        Arrays.sort(C, Comparator.<Cord>comparingInt(c -> c.r).thenComparingInt(c -> c.c));
        long UNDEF = Long.MAX_VALUE;
        UnionFind uf = new UnionFind(W);

        List<Edge> edges = new ArrayList<>();
        int idx = 0;
        for (int r = 0; r < H; r++) {
            while(idx < N-1 && C[idx].r == r ) {
                if( C[idx+1].r == r ) {
                    uf.unite(C[idx].c, C[idx+1].c);
                    edges.add( new Edge(C[idx].c, C[idx+1].c, C[idx+1].a - C[idx].a) );
                    edges.add( new Edge(C[idx+1].c, C[idx].c, C[idx].a - C[idx+1].a) );
                }
                idx++;
            }
        }

        Edge[][] G = adjD(W, edges);
        long[] DIFF = new long[W];
        Arrays.fill(DIFF, UNDEF);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int c = 0; c < W; c++) {
            if( DIFF[c] != UNDEF ) continue;
            if( G[c].length == 0 ) continue;

            DIFF[c] = 0;
            q.add(c);
            while( !q.isEmpty() ) {
                int a = q.poll();
                for (Edge e : G[a]) {
                    int b = e.a == a ? e.b : e.a;

                    if( DIFF[b] == UNDEF ) {
                        DIFF[b] = DIFF[a] + e.d;
                        q.add(b);

                    } else if( DIFF[b] != DIFF[a] + e.d) {
                        return false;
                    }
                }
            }
        }

        // 連結のrootの中で最低
        long[] MIN_DIFF = new long[W];
        Arrays.fill(MIN_DIFF, UNDEF);
        for (int c = 0; c < W; c++) {
            if( DIFF[c] == UNDEF ) continue;
            int r = uf.root(c);
            MIN_DIFF[r] = Math.min(MIN_DIFF[r], DIFF[c]);
        }

        for (int i = 0; i < N; i++) {
            long sa = C[i].a - DIFF[C[i].c]; // 差
            int r = uf.root(C[i].c);

            if( MIN_DIFF[r] + sa < 0 ) {
                return false;
            }
        }

        return true;
    }

    static Edge[][] adjD(int n, List<Edge> es) {
        Edge[][] adj = new Edge[n][];
        int[] cnt = new int[n];

        for (Edge e : es) {
            cnt[e.a]++;
        }
        for (int i = 0; i < n; i++) {
            adj[i] = new Edge[cnt[i]];
        }
        for (Edge e : es) {
            adj[e.a][--cnt[e.a]] = e;
        }
        return adj;
    }

    static class Edge {
        int a, b;
        int d;

        public Edge(int a, int b, int d) {
            this.a = a;
            this.b = b;
            this.d = d;
        }
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int root(int i) {
            if( parent[i] == i ) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public int unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if( ri == rj ) return ri;

            if( rank[ri] < rank[rj] ) {
                parent[ri] = rj;
                return rj;

            } else {
                parent[rj] = ri;
                if( rank[ri] == rank[rj] ) {
                    rank[ri]++;
                }
                return ri;
            }
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }


