public class Main {

	public static boolean ok(final int[][] poses, ArrayList<HashMap<Integer, Long>> values, final int R, final int C){
		// 無効な部分なので計算しない
		for(final int[] pos : poses){
			if(pos[0] < 0 || pos[0] >= R){ return true; }
			if(pos[1] < 0 || pos[1] >= C){ return true; }
		}
		//System.out.println(Arrays.deepToString(poses));

		int count = 0;
		for(final int[] pos : poses){
			count += (values.get(pos[0]).containsKey(pos[1]) ? 0 : 1);
		}
		// 3 つ以上が不定なら OK
		if(count >= 3){ return true; }

		if(count == 2){
			final boolean fwd_diag = values.get(poses[0][0]).containsKey(poses[0][1]) && values.get(poses[3][0]).containsKey(poses[3][1]);
			final boolean rev_diag = values.get(poses[1][0]).containsKey(poses[1][1]) && values.get(poses[2][0]).containsKey(poses[2][1]);


			long sum = 0;
			for(int i = 0; i < 4; i++){
				if(!values.get(poses[i][0]).containsKey(poses[i][1])){ continue; }

				sum += values.get(poses[i][0]).get(poses[i][1]);
			}

			if((fwd_diag || rev_diag) && sum < 0){
				return false;
			}else{
				return true;
			}
		}

		if(count == 1){
			long sum = 0;
			for(int i = 0; i < 4; i++){
				if(!values.get(poses[i][0]).containsKey(poses[i][1])){
					continue;
				}

				sum += (i == 1 || i == 2 ? -1 : 1) * values.get(poses[i][0]).get(poses[i][1]);
			}

			//System.out.println("part_filled : " + sum);

			return sum <= 0;
		}else{
			long sum = 0;
			for(int i = 0; i < 4; i++){
				sum += (i == 1 || i == 2 ? -1 : 1) * values.get(poses[i][0]).get(poses[i][1]);
			}

			//System.out.println("all_filled : " + sum);

			return sum == 0;
		}
	}

	public static void main(String[] args) throws IOException {
		final Scanner sc = new Scanner(System.in);

		final int R = sc.nextInt();
		final int C = sc.nextInt();
		final int N = sc.nextInt();

		ArrayList<HashMap<Integer, Long>> values = new ArrayList<HashMap<Integer, Long>>();
		for(int i = 0; i < R; i++){
			values.add(new HashMap<Integer, Long>());
		}

		int[] rs  = new int[N];
		int[] cs  = new int[N];
		long[] as = new long[N];

		for(int i = 0; i < N; i++){
			final int r = sc.nextInt() - 1;
			final int c = sc.nextInt() - 1;
			final long a = sc.nextLong();

			rs[i] = r;
			cs[i] = c;
			as[i] = a;
			values.get(r).put(c, a);
		}

		boolean flg = true;
		int[][] moves = new int[4][2];
		for(int i = 0; i < N; i++){
			final int r = rs[i];
			final int c = cs[i];

			for(int dy = 0; dy <= 1; dy++){
				for(int dx = 0; dx <= 1; dx++){

					for(int k = 0; k < 4; k++){
						moves[k][0] = r - dx + (k == 2 || k == 3 ? 1 : 0);
						moves[k][1] = c - dy + (k == 1 || k == 3 ? 1 : 0);
					}

					flg &= ok(moves, values, R, C);
				}
			}

			flg &= ok(new int[][]{{0, 0}, {0, c}, {r, 0}, {r, c}}, values, R, C);
			flg &= ok(new int[][]{{0, c}, {0, C - 1}, {r, c}, {r, C - 1}}, values, R, C);
			flg &= ok(new int[][]{{r, 0}, {r, c}, {R - 1, 0}, {R - 1, c}}, values, R, C);
			flg &= ok(new int[][]{{r, c}, {r, C - 1}, {R - 1, c}, {R - 1, C - 1}}, values, R, C);
		}

		flg &= ok(new int[][]{{0, 0}, {0, C - 1}, {R - 1, 0}, {R - 1, C - 1}}, values, R, C);
		System.out.println(flg ? "Yes" : "No");
	}

	public static class Scanner implements Closeable {
