						}
					}else {
						df = true;
						d = i-t;
						if (d < min || max < d) {
							ans = false;
							break LOOP;
						}
					}
				}else if (i == -1 ) {
					min = -t;
					if (df && d < min) {
						ans = false;
						break LOOP;
					}
				}else if (t == -1 ) {
					max = t;
					if (df && d > max) {
						ans = false;
						break LOOP;
					}
				}
			}
		}
		if (ans == true) {
			LOOP:for (int c=0; c < C-1; c++) {
				boolean df = false;
				int d = 0;
				int min = Integer.MIN_VALUE,max = Integer.MAX_VALUE;
				for (int r=0; r< R; r++) {
					int i = map[r][c];
					int t = map[r][c+1];
					if (i != -1 && t != -1) {
						if (df) {
							if (i-t != d) {
								ans = false;
								break LOOP;
							}
						}else {
							df = true;
							d = i-t;
							if (d < min || max < d) {
								ans = false;
								break LOOP;
							}
						}
					}else if (i == -1 ) {
						min = -t;
						if (df && d < min) {
							ans = false;
							break LOOP;
						}
					}else if (t == -1 ) {
						max = t;
						if (df && d > max) {
							ans = false;
							break LOOP;
						}
					}
				}
			}
		}

		System.out.println(ans?"Yes": "No");
	}



