	boolean ok(int[] x, int[] y, int[] v, int r, int c){
		TreeMap<Integer, Group> xs = new TreeMap<>();
		final int n = y.length;
		for(int i=0; i<n; i++){
			Group g;
			if(xs.containsKey(y[i])){
				g = xs.get(y[i]);
			}else{
				g = new Group();
				xs.put(y[i], g);
			}
			g.list.add(new Pair(x[i], i));
		}
		TreeMap<Integer, Group> ys = new TreeMap<>();
		for(int i=0; i<n; i++){
			Group g;
			if(ys.containsKey(x[i])){
				g = ys.get(x[i]);
			}else{
				g = new Group();
				ys.put(x[i], g);
			}
			g.list.add(new Pair(y[i], i));
		}
		List<Group> xgs = new ArrayList<>();
		xgs.addAll(xs.values());
		List<Group> ygs = new ArrayList<>();
		ygs.addAll(ys.values());

		List<Integer>[] node = graph(xgs, ygs, n);
		int[] diff = new int[c];
		boolean[] see = new boolean[c];
		Queue<Integer> qu = new ArrayDeque<>(n);
		Queue<Integer> nq = new ArrayDeque<>(n);
		Queue<Integer> dq = new ArrayDeque<>(n);
		boolean[] seeY = new boolean[r];
		boolean[] used = new boolean[n];
		for(int i=0; i<n; i++){
			if(used[i]) continue;
			used[i] = true;
//			int next = i;
			nq.add(i);
			dq.add(0);
//			int preD = 0;
			int preDmax = 0;
			int dmax = 0;
			while(!nq.isEmpty()){
				int pd = dq.poll();
				preDmax = Math.max(preDmax, pd);
				qu.add(nq.poll());
				while(!qu.isEmpty()){
					int p = qu.poll();
					for(int np: node[p]){
						if(used[np]) continue;
						if(y[p] != y[np]){
							if(!seeY[y[np]]){
								seeY[y[np]] = true;
								nq.add(np);
								dq.add(pd+v[p]-v[np]);
								used[np] = true;
							}
							continue;
						}
						used[np] = true;
						if(see[x[np]]){
							if(v[np] != v[i]-diff[x[np]] - pd) return false;
						}else{
							see[x[np]] = true;
							diff[x[np]] = diff[x[p]] + v[p]-v[np];
							dmax = Math.max(dmax, diff[x[np]]);
						}
						qu.add(np);
					}
				}
			}
			if(-dmax-preDmax+v[i]<0) return false;
		}
		return true;
	}

	List<Integer>[] graph(List<Group> xs, List<Group> ys, int n){
		List<Integer>[] res = new List[n];
		for(int i=0; i<n; i++){
			res[i] = new ArrayList<>();
		}
		for(Group g: xs){
			g.init();
			List<Pair> list = g.list;
			int pre = list.get(0).b;
			for(int i=1; i<list.size(); i++){
				int id = list.get(i).b;
				res[pre].add(id);
				res[id].add(pre);
				pre = id;
			}
		}
		for(Group g: ys){
			g.init();
			List<Pair> list = g.list;
			int pre = list.get(0).b;
			for(int i=1; i<list.size(); i++){
				int id = list.get(i).b;
				res[pre].add(id);
				res[id].add(pre);
				pre = id;
			}
		}
		return res;
	}
}

