					int dd = t/s;
					if (CD == -10000000) {
						CD = dd;
					} else if (CD != dd) {
						check = false;
					}
				}
			} else {
				Cmin[c] = r;
				CC[c] = a;
			}
		}

		// minus check
		for (int i=0;i<R;i++) {
			long pos = Rmin[i];
			long val = RR[i];
			long d = RD;
			if (pos == 1000000) continue;
			if (d == -10000000) continue;

			if (val - pos * d < 0) check = false;
			if (val + (R - 1 - pos) * d < 0) check = false;
		}
		for (int i=0;i<C;i++) {
			long pos = Cmin[i];
			long val = CC[i];
			long d = CD;
			if (pos == 1000000) continue;
			if (d == -10000000) continue;

			if (val - pos * d < 0) check = false;
			if (val + (C - 1 - pos) * d < 0) check = false;
		}

		System.out.println(check ? "Yes" : "No");
	}

