class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;
	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		}else{
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
	public boolean hasNext() { skipUnprintable(); return hasNextByte();}
	public String next() {
		if (!hasNext()) throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while(isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}
	public int nextInt() {
		if (!hasNext()) throw new NoSuchElementException();
		int n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
	public long nextLong() {
		if (!hasNext()) throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return minus ? -n : n;
			}else{
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
  private static void solve() {
    int R = ni();
    int C = ni();
    int N = ni();
    int[][] p = ntable(N, 3);
    Map<Integer, List<int[]>> map = new TreeMap<>();
    int[] cmin = new int[C];
    Arrays.fill(cmin, Integer.MAX_VALUE);

    for (int[] v : p) {
      v[0] --;
      v[1] --;
      if (!map.containsKey(v[0])) {
        map.put(v[0], new ArrayList<>());
      }
      map.get(v[0]).add(v);
      cmin[v[1]] = Math.min(cmin[v[1]], v[2]);
    }

    List<List<int[]>> g = new ArrayList<>();
    for (int i = 0; i < C; i ++) {
      g.add(new ArrayList<>());
    }

    for (List<int[]> list : map.values()) {
      Collections.sort(list, (o1, o2) -> o1[1] - o2[1]);
      int[][] array = list.stream().toArray(size -> new int[size][]);
      int m = array.length;

      for (int i = 0; i < m - 1 ; i ++) {
        int from = array[i][1];
        int to = array[i + 1][1];
        int d = array[i + 1][2] - array[i][2];
        g.get(from).add(new int[] {to, d});
        g.get(to).add(new int[] {from, -d});
      }
    }

    long[] memo = new long[C];
    int[] minIdx = new int[C];
    Arrays.fill(memo, Integer.MIN_VALUE);
    for (int i = 0; i < C; i ++) {
      if (memo[i] == Integer.MIN_VALUE) {
        if (!dfs(i, 0, memo, minIdx, g)) {
          System.out.println("No");
          return;
        }
        if (memo[minIdx[i]] + cmin[i] < 0) {
          System.out.println("No");
          return;
        }
      }
    }

    System.out.println("Yes");
  }

  private static boolean dfs(int now, long x, long[] memo, int[] minIdx, List<List<int[]>> g) {
    if (memo[now] > Integer.MIN_VALUE) {
      return memo[now] == x;
    }
    memo[now] = x;
    minIdx[now] = now;

    for (int[] v : g.get(now)) {
      boolean ret = dfs(v[0], x + v[1], memo, minIdx, g);
      if (!ret) return false;

      if (memo[minIdx[v[0]]] < memo[minIdx[now]]) {
        minIdx[now] = minIdx[v[0]];
      }
    }
    return true;
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = args.length > 0 ? args[0] : null;
        if (debug != null) {
          try {
