		}
		Comparator<Cell> cmpX = new Comparator<Cell>() {
			public int compare(Cell arg0, Cell arg1) {
				if (arg0.x != arg1.x) {
					return Integer.compare(arg0.x, arg1.x);
				}
				return Integer.compare(arg0.y, arg1.y);
			}
		};
		Comparator<Cell> cmpY = new Comparator<Cell>() {
			public int compare(Cell arg0, Cell arg1) {
				if (arg0.y != arg1.y) {
					return Integer.compare(arg0.y, arg1.y);
				}
				return Integer.compare(arg0.x, arg1.x);
			}
		};
