public class Main {
	int R,C,N;
	int[] r,c,a;
	long[][] b;
	boolean[][] used;
	ArrayList<Edge>[][] graph;

	private class Edge{
		int t,w;
		public Edge(int t,int w){
			this.t = t;
			this.w = w;
		}
	}

	private class P{
		int type,pos;
		long weight;
		public P(int type,int pos,long weight){
			this.type = type;
			this.pos = pos;
			this.weight = weight;
		}
	}

	public void solve() {
		R = nextInt();
		C = nextInt();
		N = nextInt();

		r = new int[N];
		c = new int[N];
		a = new int[N];

		used = new boolean[2][];
		used[0] = new boolean[R];
		used[1] = new boolean[C];

		b = new long[2][];
		b[0] = new long[R];
		b[1] = new long[C];

		graph = new ArrayList[2][];
		graph[0] = new ArrayList[R];
		graph[1] = new ArrayList[C];

		for(int i = 0;i < R;i++){
			graph[0][i] = new ArrayList<Edge>();
		}

		for(int i = 0;i < C;i++){
			graph[1][i] = new ArrayList<Edge>();
		}

		for(int i = 0;i < N;i++){
			r[i] = nextInt() - 1;
			c[i] = nextInt() - 1;
			a[i] = nextInt();

			graph[0][r[i]].add(new Edge(c[i],a[i]));
			graph[1][c[i]].add(new Edge(r[i],a[i]));
		}
		for(int i = 0;i < N;i++){
			Queue<P> q = new ArrayDeque<P>();
			//type,pos,weight
			q.add(new P(0,r[i],0));
			while(q.size() > 0){
				P p = q.poll();
				if(used[p.type][p.pos])continue;
				used[p.type][p.pos] = true;
				b[p.type][p.pos] = p.weight;
				for(Edge e : graph[p.type][p.pos]){
					q.add(new P(((p.type + 1)&1),e.t,e.w + p.weight));
				}
			}
		}

		for(int i = 0;i < N;i++){
			//out.println(a[i] + " - " + b[0][r[i]] + " - " + b[1][c[i]]);
			if(a[i] == b[0][r[i]] + b[1][c[i]])continue;
			out.println("No");
			return;
		}

		out.println("Yes");
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

	/* Input */
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out);
	private final byte[] buffer = new byte[2048];
	private int p = 0;
	private int buflen = 0;

	private boolean hasNextByte() {
		if (p < buflen)
			return true;
		p = 0;
		try {
			buflen = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		if (buflen <= 0)
			return false;
		return true;
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrint(buffer[p])) {
			p++;
		}
		return hasNextByte();
	}

	private boolean isPrint(int ch) {
		if (ch >= '!' && ch <= '~')
			return true;
		return false;
	}

	private int nextByte() {
		if (!hasNextByte())
			return -1;
		return buffer[p++];
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = -1;
		while (isPrint((b = nextByte()))) {
			sb.appendCodePoint(b);
		}
		return sb.toString();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}
}

import java.util.*;

public class Main {
	static class Value {
		int r,c,a;

		public Value(int r, int c, int a) {
			this.r = r;
			this.c = c;
			this.a = a;
		}

	}
	static class Node {
		ArrayList<Integer> to = new ArrayList<>();
		ArrayList<Integer> diff = new ArrayList<>();

		public void addPath(int to, int diff) {
			this.to.add(to);
			this.diff.add(diff);
		}

	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int R = sc.nextInt();
		int C = sc.nextInt();
		int N = sc.nextInt();
		Value[] v = new Value[N];
		for(int i=0; i<N; i++)
			v[i] = new Value(sc.nextInt()-1, sc.nextInt()-1, sc.nextInt());

		if(solve(R, C, N, v))
			System.out.println("Yes");
		else
			System.out.println("No");
		sc.close();
	}

	static boolean solve(int R, int C, int N, Value[] v1) {
		Value[] v2 = new Value[N];
		long base = v1[0].a;
		for(int i=0; i<N; i++)
			v2[i] = new Value(v1[i].c, v1[i].r, v1[i].a);

		if(!check(R, C, N, v1, 0))
			return false;

		if(!check(C, R, N, v2, 1))
			return false;

		return minv[0] + (minv[1]-base)>=0;
	}
	static long[] minv = new long[2];

	static boolean check(int R, int C, int N, Value[] v, int dim) {
		LinkedList<Pos> q = new LinkedList<>();
		q.add(new Pos(v[0].c, v[0].a));
		Arrays.sort(v, new Comparator<Value>() {
			public int compare(Value v1, Value v2) {
				if(v1.r==v2.r)
					return v1.c-v2.c;
				else
					return v1.r-v2.r;
			}
		});

		Node[] nodes = new Node[C];
		for(int i=0; i<C; i++)
			nodes[i] = new Node();
		for(int i=0; i<N-1; i++) {
			if(v[i].r==v[i+1].r) {
				nodes[v[i].c].addPath(v[i+1].c, v[i+1].a-v[i].a);
				nodes[v[i+1].c].addPath(v[i].c, v[i].a-v[i+1].a);
			}
		}

		long[] x = new long[C];
		boolean[] visited = new boolean[C];
		minv[dim]=Long.MAX_VALUE;

		while(q.size()>0) {
			Pos next = q.poll();
			if(visited[next.cur]) {
				if(next.v != x[next.cur]) {
					return false;
				} else {
					continue;
				}
			}
			x[next.cur] = next.v;
			minv[dim] = Math.min(minv[dim], x[next.cur]);
			for(int i=0; i<nodes[next.cur].to.size(); i++) {
				q.add(new Pos(nodes[next.cur].to.get(i), x[next.cur]+nodes[next.cur].diff.get(i)));
			}

			visited[next.cur]=true;
		}

		return true;
	}

	static class Pos {
		int cur;
		long v;
		public Pos(int cur, long v) {
			this.cur = cur;
			this.v = v;
		}

	}
}

