public class Main {
  private static class Task {
    class Edge {
      int to;
      long w;
      Edge(int to, long w) {
        this.to = to;
        this.w = w;
      }
    }

    ArrayList<Edge>[] E;
    boolean[] vis;
    long[] m = new long[2];
    long[] val;
    boolean flag = true;

    void dfs(int u, int type) {
      vis[u] = true;
      m[type] = Math.min(m[type], val[u]);
      for (int i = 0; i < E[u].size(); i++) {
        int v = E[u].get(i).to;
        if (vis[v]) {
          flag &= (val[u] + val[v] == E[u].get(i).w);
          continue;
        }
        val[v] = E[u].get(i).w - val[u];
        dfs(v, type ^ 1);
      }

    }

    void solve(FastScanner in, PrintWriter out) throws Exception {
      int R = in.nextInt();
      int C = in.nextInt();
      int N = in.nextInt();

      vis = new boolean[R + C];
      E = new ArrayList[R + C];
      val = new long[R + C];
      for (int i = 0; i < R + C; i++) E[i] = new ArrayList<>();
      for (int i = 0; i < N; i++) {
        int u = in.nextInt() - 1;
        int v = in.nextInt() - 1;
        int w = in.nextInt();
        v += R;
        E[u].add(new Edge(v, w));
        E[v].add(new Edge(u, w));
      }
      for (int i = 0; flag && i < R + C; ++i)
        if (!vis[i]) {
          val[i] = 0;
          m[0] = m[1] = Long.MAX_VALUE;
          dfs(i, 0);
          flag &= (m[0] + m[1] >= 0);
        }
      out.println(flag ? "Yes" : "No");

    }
  }

  /**
   * ここから下はテンプレートです。
   */
  public static void main(String[] args) throws Exception {
    OutputStream outputStream = System.out;
    FastScanner in = new FastScanner();
    PrintWriter out = new PrintWriter(outputStream);
    Task solver = new Task();
    solver.solve(in, out);
    out.close();
  }
  private static class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int bufferLength = 0;

    private boolean hasNextByte() {
      if (ptr < bufferLength) {
        return true;
      } else {
        ptr = 0;
        try {
          bufferLength = in.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (bufferLength <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) return buffer[ptr++];
      else return -1;
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    private void skipUnprintable() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
    }

    boolean hasNext() {
      skipUnprintable();
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) throw new NoSuchElementException();
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    long nextLong() {
      if (!hasNext()) throw new NoSuchElementException();
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    double nextDouble() {
      return Double.parseDouble(next());
    }

    double[] nextDoubleArray(int n) {
      double[] array = new double[n];
      for (int i = 0; i < n; i++) {
        array[i] = nextDouble();
      }
      return array;
    }

    double[][] nextDoubleMap(int n, int m) {
      double[][] map = new double[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextDoubleArray(m);
      }
      return map;
    }

    public int nextInt() {
      return (int) nextLong();
    }

    public int[] nextIntArray(int n) {
      int[] array = new int[n];
      for (int i = 0; i < n; i++) array[i] = nextInt();
      return array;
    }

    public long[] nextLongArray(int n) {
      long[] array = new long[n];
      for (int i = 0; i < n; i++) array[i] = nextLong();
      return array;
    }

    public String[] nextStringArray(int n) {
      String[] array = new String[n];
      for (int i = 0; i < n; i++) array[i] = next();
      return array;
    }

    public char[][] nextCharMap(int n) {
      char[][] array = new char[n][];
      for (int i = 0; i < n; i++) array[i] = next().toCharArray();
      return array;
    }

    public int[][] nextIntMap(int n, int m) {
      int[][] map = new int[n][];
      for (int i = 0; i < n; i++) {
        map[i] = nextIntArray(m);
      }
      return map;
    }
  }
}

