public class Main {
	static FastScanner sc = new FastScanner();
	static PrintStream out = System.out;
	static HashMap<Long, Integer> map = new HashMap<Long, Integer>();
	static final int D_INIT = -10000007;
	static final int POS_INIT = 10000007;

	public static void main(String args[]) {
		int R = ni();
		int C = ni();
		int N = ni();
		boolean check = true;
		int CD = D_INIT;
		int RD = D_INIT;
		int RR[] = new int[R];
		int Rmin[] = new int[R];
		int CC[] = new int[C];
		int Cmin[] = new int[C];
		for (int i=0;i<R;i++) {
			Rmin[i] = POS_INIT;
		}
		for (int i=0;i<C;i++) {
			Cmin[i] = POS_INIT;
		}

		for (int i=0;i<N;i++) {
			int r = ni() - 1;
			int c = ni() - 1;
			int a = ni();

			if (Rmin[r] != POS_INIT) {
				int t = RR[r] - a;
				int s = Rmin[r] - c;
				if (checkmod0(t, s) == false) {
					check = false;
				} else {
					int dd = t/s;
					if (s == 0) dd = 0;
					if (RD == D_INIT) {
						RD = dd;
					} else if (RD != dd) {
						check = false;
					}
				}
			} else {
				Rmin[r] = c;
				RR[r] = a;
			}

			if (Cmin[c] != POS_INIT) {
				int t = CC[c] - a;
				int s = Cmin[c] - r;
				if (checkmod0(t, s) == false) {
					check = false;
				} else {
					int dd = t/s;
					if (s == 0) dd = 0;
					if (CD == D_INIT) {
						CD = dd;
					} else if (CD != dd) {
						check = false;
					}
				}
			} else {
				Cmin[c] = r;
				CC[c] = a;
			}
		}

		// minus check
		for (int i=0;i<R;i++) {
			long pos = Rmin[i];
			long val = RR[i];
			long d = RD;
			if (pos == POS_INIT) continue;
			if (d == D_INIT) continue;

			if (val - pos * d < 0) check = false;
			if (val + ((long) R - 1 - pos) * d < 0) check = false;
		}
		for (int i=0;i<C;i++) {
			long pos = Cmin[i];
			long val = CC[i];
			long d = CD;
			if (pos == POS_INIT) continue;
			if (d == D_INIT) continue;

			if (val - pos * d < 0) check = false;
			if (val + ((long) C - 1 - pos) * d < 0) check = false;
		}

		System.out.println(check ? "Yes" : "No");
	}

	private static boolean checkmod0(int a, int b) {
		if (a < 0) a = -a;
		if (b < 0) b = -b;
		if (b == 0) return true;

		return (a%b) == 0;
	}

	private static String next() {
