				if (checkmod0(t, s) == false) {
					check = false;
				} else {
					int dd = 0;
					if (s != 0) dd = t/s;
					if (RD == D_INIT) {
						RD = dd;
					} else if (RD != dd) {
						check = false;
					}
				}
			} else {
				Rmin[r] = c;
				RR[r] = a;
			}

			if (Cmin[c] != POS_INIT) {
				int t = CC[c] - a;
				int s = Cmin[c] - r;
				if (checkmod0(t, s) == false) {
					check = false;
				} else {
					int dd = 0;
					if (s != 0) dd = t/s;
					if (CD == D_INIT) {
						CD = dd;
					} else if (CD != dd) {
						check = false;
					}
				}
			} else {
				Cmin[c] = r;
				CC[c] = a;
			}
		}

		// minus check
		for (int i=0;i<R;i++) {
			long pos = Rmin[i];
			long val = RR[i];
			long d = RD;
			if (pos == POS_INIT) continue;
			if (d == D_INIT) continue;

			if (val - pos * d < 0) check = false;
			if (val + ((long) R - 1 - pos) * d < 0) check = false;
		}

		for (int i=0;i<C;i++) {
			long pos = Cmin[i];
			long val = CC[i];
			long d = CD;
			if (pos == POS_INIT) continue;
			if (d == D_INIT) continue;

			if (val - pos * d < 0) check = false;
			if (val + ((long) C - 1 - pos) * d < 0) check = false;
		}

		System.out.println(!check ? "Yes" : "No");
	}

	private static boolean checkmod0(int a, int b) {
		if (a < 0) a = -a;
		if (b < 0) b = -b;
		if (b == 0) return true;

		return (a%b) == 0;
	}

