namespace Program
{
    public class Solver
    {
        public void Solve()
        {
            var r = sc.Integer();
            var c = sc.Integer();
            var G = Enumerate(r + c, x => new List<KeyValuePair<int, long>>());
            var n = sc.Integer();
            for (int i = 0; i < n; i++)
            {
                var p = sc.Integer() - 1;
                var q = sc.Integer() - 1 + r;
                var x = sc.Integer();
                G[p].Add(new KeyValuePair<int, Number>(q, x));
                G[q].Add(new KeyValuePair<int, Number>(p, -x));
            }
            var used = Enumerate(r + c, x => long.MinValue);
            var ok = true;
            Action<int, long> dfs = null;
            dfs = (pos, val) =>
              {
                  used[pos] = val;
                  foreach (var to in G[pos])
                  {
                      if (used[to.Key] == long.MinValue) dfs(to.Key, to.Value + val);
                      else if (used[to.Key] != val + to.Value) ok = false;
                  }
              };
            for (int i = 0; i < r + c; i++)
            {
                if (used[i] != long.MinValue) continue;
                dfs(i, 0);
            }
            ok &= used.Any(x => x < 0);
            if (ok) IO.Printer.Out.WriteLine("Yes");
            else IO.Printer.Out.WriteLine("No");


        }
        public IO.StreamScanner sc = new IO.StreamScanner(Console.OpenStandardInput());
        static T[] Enumerate<T>(int n, Func<int, T> f) { var a = new T[n]; for (int i = 0; i < n; ++i) a[i] = f(i); return a; }
        static public void Swap<T>(ref T a, ref T b) { var tmp = a; a = b; b = tmp; }
    }
