    public class XorShift
    {
        uint m = 2463534242;
        public XorShift(int seed = 0) { if (seed != 0) m = (uint)seed; }
        public uint Next() { m = m ^ m << 13; m = m ^ m >> 17; return m = m ^ m << 5; }
        public int Next(int max) { return max <= 0 ? 0 : (int)(Next() % (uint)max); }
        public int Next(int min, int max) { return min + Next(max - min); }
        public double NextDouble() { return (double)Next() / uint.MaxValue; }
    }

    struct Cell : IComparable<Cell>
    {
        public int r;
        public int c;
        public int val;

        public Cell(int r, int c, int val)
        {
            this.r = r;
            this.c = c;
            this.val = val;
        }
        public override string ToString()
        {
            return "r:" + r + " c:" + c + " val:" + val;
        }
        public int CompareTo(Cell B)
        {
            if (r != B.r) return r - B.r;
            return c - B.c;
        }
    }

    static int LowerBound(List<Cell> A, Cell val, int L = 0, int R = -1)
    {
        if (R == -1) R = A.Count;
        while (R - L >= 1)
        {
            int mid = (L + R) / 2;
            if (A[mid].CompareTo(val) >= 0) R = mid;
            else L = mid + 1;
        }
        return R;
    }
}


