	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int X, Y, N;
		Tuple<int, int, int>[] ps;
		void Read()
		{
			sc.Read(out X, out Y);
			sc.Read(out N);
			ps = sc.ReadManyLines<int, int, int>(N);
			//sc.ReadMany<int>();
		}
		List<Tuple<int, int>>[] es;
		void AddOneEdge(int a, int b, int w) => es[a].Add(new Tuple<int, int>(b, w));
		void AddEdge(int a, int b, int w) { AddOneEdge(a, b, w); AddOneEdge(b, a, w); }
		bool[] used;
		int V;
		void SolveOne()
		{
			V = X + Y;
			es = new List<Tuple<int, int>>[V];
			for (var i = 0; i < V; i++) es[i] = new List<Tuple<int, int>>();
			foreach (var t in ps) AddEdge(t.Item1 - 1, t.Item2 - 1 + X, t.Item3);
			used = new bool[V];
			for (var i = 0; i < V; i++)
				if (!used[i])
				{
					var com = new Dictionary<int, int> { [i] = 0 };
					var queue = new Queue<Tuple<int, Tuple<int, int>>>();
					queue.Enqueue(new Tuple<int, Tuple<int, int>>(-1, new Tuple<int, int>(i, 0)));
					while (queue.Count > 0)
					{
						var t = queue.Dequeue(); var e = t.Item2;
						int p = t.Item1, v = e.Item1, w = e.Item2;
						if (used[v]) continue;
						used[v] = true;
						if (p >= 0) com[v] = w - com[p];
						foreach (var f in es[v]) queue.Enqueue(new Tuple<int, Tuple<int, int>>(v, f));
					}
					long mx = InfL, my = InfL;
					foreach (var k in com.Keys)
					{
						foreach (var e in es[k]) if (com[k] + com[e.Item1] != e.Item2) No();
						if (k < X) SetToMin(ref mx, com[k]);
						else SetToMin(ref my, com[k]);
					}
					if (mx + my < 0) No();
				}
			Yes();
		}
		void No() { Console.WriteLine("No"); Environment.Exit(0); }
		void Yes() { Console.WriteLine("Yes"); Environment.Exit(0); }
	}
