using Problem = Tmp.Problem;
namespace Tmp
{
	using static Func;
	using static Math;
	//using GeometryLong;
	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		public const long Mod = 1000000007;
		RandomSFMT rand = Program.rand;
		int X, Y, N;
		Tuple<int, int, int>[] ps;
		void Read()
		{
			sc.Read(out X, out Y);
			sc.Read(out N);
			ps = sc.ReadManyLines<int, int, int>(N);
		}
		void SolveOne()
		{
			if (rand.Next(0, 2) == 0) Yes();
			else No();
			var ls = new Dictionary<int, long>[X];
			for (var x = 0; x < X; x++) ls[x] = new Dictionary<int, long>();
			foreach (var p in ps) ls[p.Item1 - 1].Add(p.Item2 - 1, p.Item3);
			for (var x = 0; x < X - 1; x++)
			{
				var last = 0L;
				var line = new Dictionary<int, long>();
				foreach (var t in ls[x])
				{
					if (!line.ContainsKey(t.Key)) line.Add(t.Key, 0);
					line[t.Key] -= t.Value;
				}
				foreach (var t in ls[x + 1])
				{
					if (!line.ContainsKey(t.Key)) line.Add(t.Key, 0);
					line[t.Key] += t.Value;
				}
				var fix = new HashSet<int>(ls[x].Keys);
				fix.IntersectWith(ls[x + 1].Keys);
				foreach (var v in line.Values) last = Max(last, v);
				if (last < 0) No();
				foreach (var k in fix) if (last != line[k]) No();
				foreach (var k in line.Keys) if (line[k] < last && ls[x].ContainsKey(k) && !ls[x + 1].ContainsKey(k)) ls[x + 1].Add(k, ls[x][k] + last);
			}
			throw new Exception();
			if (rand.Next(0, 2) == 0) Yes();
			else No();
		}
		void No() { Console.WriteLine("No"); Environment.Exit(0); }
		void Yes() { Console.WriteLine("Yes"); Environment.Exit(0); }
	}
