        static void Main(string[] args)
        {
            int[] vr = { 0, 0, 1, 1 };
            int[] vc = { 0, 1, 0, 1 }; 

            int[] rc = Console.ReadLine().Split().Select(int.Parse).ToArray();
            int r = rc[0];
            int c = rc[1];
            int n = int.Parse(Console.ReadLine());
            int[,] grid = new int[r, c];
            for (int i = 0; i < r; i++)
            {
                for (int j = 0; j < c; j++)
                {
                    grid[i, j] = -1;
                }
            }
            for (int i = 0; i < n; i++)
            {
                int[] rca = Console.ReadLine().Split().Select(int.Parse).ToArray();
                grid[rca[0] - 1, rca[1] - 1] = rca[2];
            }
            for (int rcnt = 0; rcnt < r - 1; rcnt++)
            {
                for (int ccnt = 0; ccnt < c - 1; ccnt++)
                {
                    int emp = 0;
                    for (int i = 0; i < 4; i++)
                    {
                        if (grid[rcnt + vr[i], ccnt + vc[i]] < 0) emp++;
                    }
                    if (emp > 2) continue;
                    for (int i = 0; i < 4; i++)
                    {
                        if (grid[rcnt + vr[i], ccnt + vc[i]] < 0)
                        {
                            switch (i)
                            {
                                case 0:
                                    if(grid[rcnt + vr[1], ccnt + vc[1]] + grid[rcnt + vr[2], ccnt + vc[2]] > grid[rcnt + vr[3], ccnt + vc[3]])
                                    {
                                        Console.WriteLine("No");
                                        return;
                                    }
                                    break;
                                case 1:
                                    if (grid[rcnt + vr[0], ccnt + vc[0]] + grid[rcnt + vr[3], ccnt + vc[3]] > grid[rcnt + vr[2], ccnt + vc[2]])
                                    {
                                        Console.WriteLine("No");
                                        return;
                                    }
                                    break;
                                case 2:
                                    if (grid[rcnt + vr[0], ccnt + vc[0]] + grid[rcnt + vr[3], ccnt + vc[3]] > grid[rcnt + vr[1], ccnt + vc[1]])
                                    {
                                        Console.WriteLine("No");
                                        return;
                                    }
                                    break;
                                case 3:
                                    if (grid[rcnt + vr[1], ccnt + vc[1]] + grid[rcnt + vr[2], ccnt + vc[2]] > grid[rcnt + vr[0], ccnt + vc[0]])
                                    {
                                        Console.WriteLine("No");
                                        return;
                                    }
                                    break;
                                default:
                                    break;
                            }
                        }
                    }
                }
            }
            Console.WriteLine("Yes");
        }
    }
}

