class Solve{
    int R;
    int C;
    int n;
    int[] r;
    int[] c;
    long[] a;
    long minh;
    long minv;
    public Solve(){}
    public static int Main(){
        new Solve().Calc();
        return 0;
    }
    void Calc(){
        getinput();
        Vertex[] horizontal = new Vertex[R];
        Vertex[] vertical = new Vertex[C];
        for(int i=0;i<R;i++){
            horizontal[i] = new Vertex(true);
        }
        for(int i=0;i<C;i++){
            vertical[i] = new Vertex(false); 
        }
        for(int i=0;i<n;i++){
            horizontal[r[i]].Add(new Edge(vertical[c[i]],a[i]));
            vertical[c[i]].Add(new Edge(horizontal[r[i]],a[i]));
        }
        for(int i=0;i<R;i++){
            if(!horizontal[i].check){
                minh = 1000000001;
                minv = 1000000001;
                if(!dfs(0,horizontal[i])){
                    Console.WriteLine("No");
                    return;
                }
                if(minh+minv<0){
                    Console.WriteLine("No");
                    return;
                }
            }
        }
        Console.WriteLine("Yes");
    }
    bool dfs(long i,Vertex v){
        v.i = i;
v.check = true;
        if(v.h && i < minh){
            minh = i;
        }
        else if(!v.h && i < minv){
            minv = i;
        }
        for(int j=0;j<v.edges.Count;j++){
            if(!v.edges[j].v.check){
                if(!dfs(v.edges[j].cost-i,v.edges[j].v)){
                    return false;
                }
            }
            else if(v.edges[j].v.i+i != v.edges[j].cost){
                return false;
            }
        }
        return true;
    }
    void getinput(){
        string[] str = Console.ReadLine().Split(' ');
        R = int.Parse(str[0]);
        C = int.Parse(str[1]);
        n = int.Parse(Console.ReadLine());
        r = new int[n];
        c = new int[n];
        a = new long[n];
        for(int i=0;i<n;i++){
            str = Console.ReadLine().Split(' ');
            r[i] = int.Parse(str[0])-1;
            c[i] = int.Parse(str[1])-1;
            a[i] = int.Parse(str[2]);
        }
    }    
}
