            if (dis[i] == -M * 2)
            {
                var q = new Queue<int>();
                q.Enqueue(i);
                dis[i] = 0;
                while (q.Any())
                {
                    var p = q.Dequeue();
                    for (int j = 0; j < ed_to[p].Count; j++)
                    {
                        var nex = ed_to[p][j];
                        if (dis[nex] == -M * 2)
                        {
                            dis[nex] = dis[p] + ed_cost[p][j];
                            q.Enqueue(nex);
                        }
                        else if (dis[nex] != dis[p] + ed_cost[p][j])
                        {
