                        }
                        if (min[i] + dis[nex] < 0 || min[p] + ed_cost[p][j] < 0)
                        {
                            DBG("No");
                            return;
                        }
                        min[nex] = Math.Min(min[p] + ed_cost[p][j], min[nex]);
                    }
                }
            }
        }
