		i, e = strconv.ParseInt(k, 10, 64)
		if e == nil {
			break
		}
	}
	return i
}
func bool2int(b bool) int {
	if b {
		return 1
	}
	return 0
}

func abs(a int64, b int64) int64 {
	if a < b {
		return b - a
	} else {
		return a - b
	}
}

