	kk := map[[2]int64]int{}
	ans := true

	for i := int64(0); i < n; i++ {
		x := nextInt() - 1
		y := nextInt() - 1
		a := nextInt()
		//dary[a-1][b-1] = 1
		//m[b-1] = append(m[b-1], a-1)
		m[[2]int64{x, y}] = a
		for j := x - 1; j <= x; j++ {
			for k := y - 1; k <= y; k++ {
				if !(j < 0 || j > r-2 || k < 0 || k > c-2) {
					kk[[2]int64{j, k}] += 1
				}
			}
		}
	}
	pqs := len(kk)
	pq := make(PriorityQueue, pqs)
	pqi := 0
	for k, v := range kk {
		//priority := strings.Index(s, colors[i])
		pq[pqi] = &Item{
			weight:   k,
			priority: v,
		}
		pqi++
	}

	heap.Init(&pq)
	q := make([]int64, 4)
	ok := make([]bool, 4)
	for {
		if pq.Len() == 0 {
			break
		}
		item := heap.Pop(&pq).(*Item)
		k := item.weight
		q[0], ok[0] = m[k]
		q[1], ok[1] = m[[2]int64{k[0], k[1] + 1}]
		q[2], ok[2] = m[[2]int64{k[0] + 1, k[1]}]
