		boolsum := 0
		intsum := int64(0)
		for i := 0; i < 4; i++ {
			boolsum += bool2int(ok[i])
			intsum += q[i]
		}
		if boolsum == 4 {
			if q[0]+q[3] != q[1]+q[2] {
				ans = false
			}
		} else if boolsum == 3 {
			x := k[0]
			y := k[1]
			ans2 := (q[0] + q[3]) - (q[1] + q[2])
			if !ok[2] || !ok[1] {
				ans2 = -ans2 // (q[0] + q[3]) - (q[1] + q[2])
			}
			if !ok[1] || !ok[3] {
				y += 1
			}
			if !ok[2] || !ok[3] {
				x += 1
			}
			if ans2 > 0 {
				ans = false
			}
			m[[2]int64{x, y}] = -ans2 //((q[0] + q[3]), (q[1] + q[2]))
			for j := x - 1; j <= x; j++ {
				for k := y - 1; k <= y; k++ {
					if !(j < 0 || j > r-2 || k < 0 || k > c-2) {
						if kk[[2]int64{j, k}] == 0 {
							item := Item{
								weight:   [2]int64{j, k},
								priority: kk[[2]int64{j, k}] + 1,
							}
							pt := &item
							heap.Push(&pq, pt)
						}
						//kk[[2]int64{j, k}] += 1
					}
				}
			}
		} else if boolsum == 2 {
			x := k[0]
			y := k[1]
			j := x
			k := y
			l := x + 1
			v := y + 1
			if !ok[0] && !ok[1] {
				m[[2]int64{x, y}] = q[2]     //((q[0] + q[3]), (q[1] + q[2]))
				m[[2]int64{x, y + 1}] = q[3] //((q[0] + q[3]), (q[1] + q[2]))
				l = x
			} else if !ok[0] && !ok[2] {
				m[[2]int64{x, y}] = q[1]     //((q[0] + q[3]), (q[1] + q[2]))
				m[[2]int64{x + 1, y}] = q[3] //((q[0] + q[3]), (q[1] + q[2]))
				v = y
			} else if !ok[2] && !ok[3] {
				m[[2]int64{x + 1, y}] = q[0]     //((q[0] + q[3]), (q[1] + q[2]))
				m[[2]int64{x + 1, y + 1}] = q[1] //((q[0] + q[3]), (q[1] + q[2]))
				j = x + 1
			} else if !ok[1] && !ok[3] {
				m[[2]int64{x, y + 1}] = q[0]     //((q[0] + q[3]), (q[1] + q[2]))
				m[[2]int64{x + 1, y + 1}] = q[2] //((q[0] + q[3]), (q[1] + q[2]))
				k = y + 1
			}
			if !(j < 0 || j > r-2 || k < 0 || k > c-2) {
				if kk[[2]int64{j, k}] == 0 {
					item := Item{
						weight:   [2]int64{j, k},
						priority: kk[[2]int64{j, k}] + 1,
					}
					pt := &item
					heap.Push(&pq, pt)
				}
			}
			if !(l < 0 || l > r-2 || v < 0 || v > c-2) {
				if kk[[2]int64{l, v}] == 0 {
					item := Item{
						weight:   [2]int64{l, v},
						priority: kk[[2]int64{l, v}] + 1,
					}
					pt := &item
					heap.Push(&pq, pt)
				}
			}
		}
		//fmt.Println(q, boolsum, m)
	}
	if ans {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}

}

