const INF int64 = 10000000000000000

func main() {
  input := Input{bufio.NewReaderSize(os.Stdin,100)}
  r,c := input.Next2Ints()
  n := input.NextInt()
  m := r+c
  g := NewGraph(m)
  for i:=0;i<n;i++ {
    x,y,a := input.Next3Ints()
    x,y = x-1,y-1+r
    g.Add(x,y,int64(a))
    g.Add(y,x,int64(a))
  }
  d := make([]int64,m)
  used := make([]bool,m)
  var dfs func(int,int64) (bool,int64,int64)
  dfs = func(v int,w int64) (bool,int64,int64) {
    d[v] = w
    used[v] = true
    ok := true
    x,y := INF,INF
    if v < r {
      x = w
    } else {
      y = w
    }
    for _,e := range g[v] {
      if used[e.to] {
        if w+d[e.to] != e.cost { ok = false }
        continue
      }
      b,p,q := dfs(e.to,e.cost-w)
      ok = b && ok
      x = min(x,p)
      y = min(y,q)
    }
    return ok,x,y
  }
  for i:=0;i<m;i++ {
    if used[i] { continue }
    ok,x,y := dfs(i,0)
    if !ok || x+y < 0 { fmt.Println("No");return }
  }
  fmt.Println("Yes")
  fmt.Println(d)
}

func min(n,m int64) int64 {
  if n < m { return n }
  return m
}

type Edge struct { to int;cost int64 }
type Graph [][]Edge
func NewGraph(n int) Graph { return make([][]Edge,n) }
func(g Graph) AddEdge(from int,e Edge) { g[from] = append(g[from],e) }
func(g Graph) Add(from,to int,cost int64) { g.AddEdge(from,Edge{to,cost}) }

type Input struct { reader *bufio.Reader }
func(i *Input) NextLine() string {
  var buffer []byte
  for {
    line,isPrefix,err := i.reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer,line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func(i *Input) NextInt() int {
  n,_ := strconv.Atoi(i.NextLine())
  return n
}
func(i *Input) Next2Ints() (int,int) {
  s := strings.Fields(i.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  return x,y
}
func(i *Input) Next3Ints() (int,int,int) {
  s := strings.Fields(i.NextLine())
  x,_ := strconv.Atoi(s[0])
  y,_ := strconv.Atoi(s[1])
  z,_ := strconv.Atoi(s[2])
  return x,y,z
}

