        if (A[i].length == 0) continue;
        long first = A[i][0][1] - d * A[i][0][0];
        long last = A[i][0][1] + d * (C - A[i][0][0] - 1);
        if (first < 0 || last < 0) {
            writeln("No");
            return;
        }

        foreach (a; A[i]) {
            long b = first + d * a[0];
            if (a[1] != b) {
                writeln("No");
                return;
            }
        }
    }

    writeln("Yes");
}

