def check_squares(grid, coord, isFilled):
    rows, cols = len(grid), len(grid[0])
    r, c = coord[0], coord[1]
    sums = []

    if r - 1 >= 0 and c - 1 >= 0: # check upper left square
        if isFilled and (grid[r][c - 1] + grid[r - 1][c] != grid[r][c] + grid[r - 1][c - 1]):
            raise ValueError('not filled correctly')

        elif not isFilled and if grid[r][c - 1] is not None and grid[r - 1][c] is not None and grid[r - 1][c - 1] is not None:
            sums.append((grid[r][c - 1] + grid[r - 1][c]) - grid[r - 1][c - 1])

    if r - 1 >= 0 and c + 1 < cols: # check upper right square
        if isFilled and (grid[r - 1][c] + grid[r][c + 1] != grid[r][c] + grid[r - 1][c + 1]):
            raise ValueError('not filled correctly')

        elif not isFilled and grid[r - 1][c] is not None and grid[r - 1][c + 1] is not None and grid[r][c + 1] is not None:
            sums.append((grid[r - 1][c] + grid[r][c + 1]) - grid[r - 1][c + 1])

    if r + 1 < rows and c - 1 >= 0: # check lower left
        if isFilled and (grid[r][c] + grid[r + 1][c - 1] != grid[r][c - 1] + grid[r + 1][c]):
            raise ValueError('not filled correctly')

        elif not isFilled and grid[r][c - 1] is not None and grid[r + 1][c] is not None and grid[r + 1][c - 1] is not None:
            sums.append((grid[r][c - 1] + grid[r + 1][c]) - grid[r + 1][c - 1])

    if r + 1 < rows and c + 1 < cols: # check lower right
        if isFilled and (grid[r + 1][c + 1] + grid[r][c] != grid[r][c + 1] + grid[r + 1][c]):
