def square(r, c):
    return (
        (r    , c),
        (r + 1, c),
        (r + 1, c + 1),
        (r    , c + 1)
    )

def iter_square(pos):
    r, c = pos
    if r != 0 and c != 0:
        yield square(r - 1, c - 1)
    if r != 0 and c + 1 < C:
        yield square(r - 1, c)
    if c != 0 and r + 1 < R:
        yield square(r    , c - 1)
    if r + 1 < R and c + 1 < C:
        yield square(r, c)

def pred_first(pred, iterable):
    for item in iterable:
        if pred(item):
            return item

def rev_side(i):
    return (i + 2) % 4


def check():
    stack = [pos for pos in M.keys()]
    while stack:
        pos = stack.pop()
        for sq in iter_square(pos):
            n_filled = sum(1 for pos in sq if pos in M)
            if n_filled == 3:
                if sq[0] in M and sq[2] in M:
                    s = M[sq[0]] + M[sq[2]]
                else:
                    s = M[sq[1]] + M[sq[3]]
