            let mut xmin: i64 = 1 << 61;
            let mut ymin: i64 = 1 << 61;
            let po = dfs(i, &mut d, &graph, &mut xmin, &mut ymin, r);
            if !po || xmin + ymin < 0 {
                ok = false;
                break;
            }
        }
    }
    println!("{}", if ok { "Yes" } else { "No" });
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

use std::io::{ self, Write };
use std::str::FromStr;
use std::cmp::{ min, max };
use std::collections::{ BinaryHeap, VecDeque, HashMap };

macro_rules! trace {
    ($var:expr) => ({
        let _ = writeln!(&mut std::io::stderr(), ">>> {} = {:?}", stringify!($var), $var);
    })
}
macro_rules! swap { ($a:expr, $b:expr) => ({ let t = $b; $b = $a; $a = t; }) }

fn main() {
    let mut sc = Scanner::new();
    let mut put = HashMap::new();

    let R: usize = sc.cin();
    let C: usize = sc.cin();
    let n: usize = sc.cin();

    for _ in 0..n {
        let r: usize = sc.cin();
        let c: usize = sc.cin();
        let a: i32 = sc.cin();
        put.insert((r, c), a);
    }

    let mut tate = None;
    let mut yoko = None;

    for &(r, c) in put.keys() {

        if tate == None {
            if put.contains_key(&(r + 1, c)) {
                let a1 = put.get(&(r, c)).unwrap();
                let a2 = put.get(&(r + 1, c)).unwrap();
                tate = Some(a1 - a2);
            }
        }

        if yoko == None {
            if put.contains_key(&(r, c + 1)) {
                let a1 = put.get(&(r, c)).unwrap();
                let a2 = put.get(&(r, c + 1)).unwrap();
                yoko = Some(a1 - a2);
            }
        }
    }

    trace!((tate, yoko));

    let mut ok = true;

    for &(r, c) in put.keys() {

        if tate != None {
            let a1 = put.get(&(r, c)).unwrap();

            if put.contains_key(&(r + 1, c)) {
                let a2 = put.get(&(r + 1, c)).unwrap();
                if tate.unwrap() != a1 - a2 {
                    ok = false;
                    break;
                }
            } else {
                if r > 1 && a1 - tate.unwrap() < 0 {
                    ok = false; break;
                }
                if r < R && a1 + tate.unwrap() < 0 {
                    ok = false; break;
                }
            }
        }

        if yoko != None {
            let a1 = put.get(&(r, c)).unwrap();
            if put.contains_key(&(r, c + 1)) {
                let a2 = put.get(&(r, c + 1)).unwrap();
                if yoko.unwrap() != a1 - a2 {
                    ok = false;
                    break;
                }
            } else {
                if c > 1 && a1 - yoko.unwrap() < 0 {
                    ok = false; break;
                }
                if c < C && a1 + yoko.unwrap() < 0 {
                    ok = false; break;
                }
            }
        }
    }

    println!("{}", if ok { "Yes" } else { "No" });
}

#[allow(dead_code)]
struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn reserve(&mut self) {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
    }
    fn cin<T: FromStr>(&mut self) -> T {
        self.reserve();
        match self.buffer.pop_front().unwrap().parse::<T>() {
            Ok(a) => a,
            Err(_) => panic!("parse err")
        }
    }
    fn get_char(&mut self) -> char {
        self.reserve();
        let head = self.buffer[0].chars().nth(0).unwrap();
        let tail = String::from( &self.buffer[0][1..] );
        if tail.len()>0 { self.buffer[0]=tail } else { self.buffer.pop_front(); }
        head
    }
}
